		private Button CreateDialogButton(string text, DialogResult result, bool primary)
		{
			Button button = new Button();
			button.Text = text;
			button.DialogResult = result;
			button.Width = ResolveDialogButtonWidth(text);
			button.Height = 44;
			button.FlatStyle = FlatStyle.Flat;
			button.Font = new Font(Font.FontFamily, 10f, FontStyle.Bold);
			button.Margin = new Padding(8, 0, 0, 0);
			button.BackColor = (primary ? Color.FromArgb(28, 151, 101) : Color.White);
			button.ForeColor = (primary ? Color.White : Color.FromArgb(29, 55, 46));
			button.UseMnemonic = false;
			button.FlatAppearance.BorderColor = (primary ? Color.FromArgb(28, 151, 101) : Color.FromArgb(190, 206, 198));
			button.FlatAppearance.BorderSize = 1;
			return button;
		}

		private int ResolveDialogButtonWidth(string text)
		{
			int length = (text ?? string.Empty).Length;
			int estimated = checked(_isKorean ? (length * 14 + 44) : (length * 9 + 46));
			return Math.Min(280, Math.Max(_isKorean ? 112 : 104, estimated));
		}

		private static DialogResult ResolveDefaultResult(MessageBoxButtons buttons, MessageBoxDefaultButton defaultButton)
		{
			if (buttons == MessageBoxButtons.YesNo)
			{
				if (defaultButton == MessageBoxDefaultButton.Button2)
				{
					return DialogResult.No;
				}
				return DialogResult.Yes;
			}
			return DialogResult.OK;
		}

		private string ResolveKindText(MessageBoxIcon icon)
		{
			return icon switch
			{
				MessageBoxIcon.Exclamation => _isKorean ? "주의가 필요한 작업 결과" : "Action result needs attention", 
				MessageBoxIcon.Hand => _isKorean ? "작업 중 오류가 발생했습니다" : "An error occurred", 
				MessageBoxIcon.Question => _isKorean ? "작업을 계속할지 확인합니다" : "Confirm before continuing", 
				_ => _isKorean ? "작업 결과" : "Action result", 
			};
		}

		private static Color ResolveAccentColor(MessageBoxIcon icon)
		{
			return icon switch
			{
				MessageBoxIcon.Exclamation => Color.FromArgb(218, 151, 47), 
				MessageBoxIcon.Hand => Color.FromArgb(205, 74, 58), 
				MessageBoxIcon.Question => Color.FromArgb(48, 119, 190), 
				_ => Color.FromArgb(28, 151, 101), 
			};
		}

		private static string ResolveIconGlyph(MessageBoxIcon icon)
		{
			return icon switch
			{
				MessageBoxIcon.Exclamation => "!", 
				MessageBoxIcon.Hand => "X", 
				MessageBoxIcon.Question => "?", 
				_ => "i", 
			};
		}

