			button.FlatStyle = FlatStyle.Flat;
			button.Font = new Font(Font.FontFamily, 10f, FontStyle.Bold);
			button.Margin = new Padding(8, 0, 0, 0);
			button.BackColor = (primary ? Color.FromArgb(28, 151, 101) : Color.White);
			button.ForeColor = (primary ? Color.White : Color.FromArgb(29, 55, 46));
			button.UseMnemonic = false;
			button.FlatAppearance.BorderColor = (primary ? Color.FromArgb(28, 151, 101) : Color.FromArgb(190, 206, 198));
			button.FlatAppearance.BorderSize = 1;
			return button;
		}

		private string Tx(string en, string ko)
		{
			if (!_isKorean)
			{
				return en;
			}
			return ko;
		}
