		private static int ClampDialogSize(int value, int minimum, int maximum)
		{
			return Math.Max(minimum, Math.Min(value, Math.Max(minimum, maximum)));
		}

		private string BuildHeadline(string headlineText, string scopeText)
		{
			List<string> lines = new List<string>();
			if (!string.IsNullOrWhiteSpace(headlineText))
			{
				lines.Add(headlineText.Trim());
			}
			if (!string.IsNullOrWhiteSpace(scopeText))
			{
				lines.Add(scopeText.Replace("\r\n", " ").Replace("\r", " ").Replace("\n", " ")
					.Trim());
			}
			if (lines.Count == 0)
			{
				return Tx("The family load command finished.", "패밀리 로드 작업이 완료되었습니다.");
			}
			return string.Join("  ", lines);
		}

		private ListView BuildDetailList(LoadableFamilySyncExecutionReport report)
		{
			ListView listView = new ListView
			{
				Dock = DockStyle.Fill,
				View = View.Details,
				FullRowSelect = true,
				GridLines = false,
				HideSelection = false,
				BorderStyle = BorderStyle.None,
				BackColor = Color.FromArgb(250, 252, 251),
				ForeColor = Color.FromArgb(33, 54, 47),
				Font = new Font(Font.FontFamily, 10f, FontStyle.Regular)
			};
			listView.Columns.Add(Tx("Result", "결과"), 96);
			listView.Columns.Add(Tx("Action", "작업"), 110);
			listView.Columns.Add(Tx("Category", "카테고리"), 170);
			listView.Columns.Add(Tx("Family", "패밀리"), 230);
			listView.Columns.Add(Tx("Details", "상세"), 420);
			List<LoadableFamilySyncExecutionItem> ordered = ((report == null || report.Items == null) ? new List<LoadableFamilySyncExecutionItem>() : report.Items).OrderBy([SpecialName] (LoadableFamilySyncExecutionItem x) => OutcomeSortKey(x)).ThenBy([SpecialName] (LoadableFamilySyncExecutionItem x) => x.CategoryName ?? string.Empty, StringComparer.OrdinalIgnoreCase).ThenBy([SpecialName] (LoadableFamilySyncExecutionItem x) => x.FamilyName ?? string.Empty, StringComparer.OrdinalIgnoreCase)
				.ToList();
			if (ordered.Count == 0)
			{
				ListViewItem emptyItem = new ListViewItem(Tx("OK", "완료"));
				emptyItem.SubItems.Add("-");
				emptyItem.SubItems.Add("-");
				emptyItem.SubItems.Add("-");
				emptyItem.SubItems.Add(Tx("No item-level records were written.", "항목별 기록이 없습니다."));
				listView.Items.Add(emptyItem);
				return listView;
			}
			foreach (LoadableFamilySyncExecutionItem item in ordered)
			{
				if (item != null)
				{
					ListViewItem row = new ListViewItem(DisplayOutcome(item.Outcome));
					row.SubItems.Add(DisplayAction(item.ExecutionMode, item.PlannedAction));
					row.SubItems.Add(string.IsNullOrWhiteSpace(item.CategoryName) ? "-" : item.CategoryName);
					row.SubItems.Add(string.IsNullOrWhiteSpace(item.FamilyName) ? "-" : item.FamilyName);
					row.SubItems.Add(TranslateDetail(item.Details));
					row.BackColor = OutcomeBackColor(item.Outcome);
					row.ForeColor = Color.FromArgb(31, 52, 45);
					listView.Items.Add(row);
				}
			}
			return listView;
		}

