		private void OpenReportFolderClicked(object sender, EventArgs e)
		{
			try
			{
				if (string.IsNullOrWhiteSpace(_reportPath) || !File.Exists(_reportPath))
				{
					SetStatus(Tx("Report file was not found.", "리포트 파일을 찾을 수 없습니다."));
					return;
				}
				string folder = Path.GetDirectoryName(_reportPath);
				if (string.IsNullOrWhiteSpace(folder) || !Directory.Exists(folder))
				{
					SetStatus(Tx("Report folder was not found.", "리포트 폴더를 찾을 수 없습니다."));
					return;
				}
				Process.Start(new ProcessStartInfo(folder)
				{
					UseShellExecute = true
				});
			}
			catch (Exception ex)
			{
				ProjectData.SetProjectError(ex);
				Exception ex2 = ex;
				SetStatus(ex2.Message);
				ProjectData.ClearProjectError();
			}
		}

		private void CopyReportPathClicked(object sender, EventArgs e)
		{
			try
			{
				if (string.IsNullOrWhiteSpace(_reportPath))
				{
					SetStatus(Tx("No report path to copy.", "복사할 리포트 경로가 없습니다."));
					return;
				}
				Clipboard.SetText(_reportPath);
				SetStatus(Tx("Report path copied.", "리포트 경로를 복사했습니다."));
			}
			catch (Exception ex)
			{
				ProjectData.SetProjectError(ex);
				Exception ex2 = ex;
				SetStatus(ex2.Message);
				ProjectData.ClearProjectError();
			}
		}

		private void SetStatus(string message)
		{
			if (_statusLabel != null)
			{
				_statusLabel.Text = message ?? string.Empty;
			}
		}

		private void HeaderMouseDown(object sender, MouseEventArgs e)
		{
			if (e.Button == MouseButtons.Left)
			{
				ReleaseCapture();
				SendMessage(base.Handle, 161, 2, 0);
			}
		}

		private int OutcomeSortKey(LoadableFamilySyncExecutionItem item)
		{
			if (item == null)
			{
				return 9;
			}
			return NormalizeLocal(item.Outcome) switch
			{
				"failed" => 0, 
				"blocked" => 1, 
				"reloaded" => 2, 
				"loaded" => 3, 
				"stamprefreshpending" => 4, 
				"skipped" => 5, 
				_ => 6, 
			};
		}

		private string DisplayOutcome(string outcome)
		{
			return NormalizeLocal(outcome) switch
			{
				"loaded" => Tx("Loaded", "로드됨"), 
				"reloaded" => Tx("Reloaded", "재로드됨"), 
				"failed" => Tx("Failed", "실패"), 
				"blocked" => Tx("Blocked", "차단"), 
				"stamprefreshpending" => Tx("Tracking", "추적 대기"), 
				"skipped" => Tx("Skipped", "건너뜀"), 
				_ => string.IsNullOrWhiteSpace(outcome) ? "-" : outcome, 
			};
		}

		private string DisplayAction(string executionMode, string plannedAction)
		{
			switch (NormalizeLocal(executionMode))
			{
			case "load":
				return Tx("Load", "로드");
			case "reload":
				return Tx("Reload", "재로드");
			case "stamponly":
				return Tx("Tracking", "추적");
			case "blocked":
				return Tx("Review", "검토");
			default:
				if (!string.IsNullOrWhiteSpace(plannedAction))
				{
					return plannedAction;
				}
				return string.IsNullOrWhiteSpace(executionMode) ? "-" : executionMode;
			}
		}

		private Color OutcomeBackColor(string outcome)
		{
			switch (NormalizeLocal(outcome))
			{
			case "failed":
				return Color.FromArgb(255, 241, 236);
			case "blocked":
				return Color.FromArgb(255, 248, 229);
			case "loaded":
			case "reloaded":
				return Color.FromArgb(239, 249, 244);
			case "stamprefreshpending":
				return Color.FromArgb(240, 247, 252);
			default:
				return Color.FromArgb(250, 252, 251);
			}
		}

		private string TranslateDetail(string value)
		{
			if (string.IsNullOrWhiteSpace(value) || !_isKorean)
			{
				return value ?? string.Empty;
			}
			return value.Replace("Family loaded from the registered standard RVT.", "등록된 표준 RVT에서 패밀리를 로드했습니다.").Replace("Family reloaded from the registered standard RVT with overwrite enabled.", "표준 RVT 기준으로 패밀리를 덮어써서 재로드했습니다.").Replace("The family was not found in the registered standard RVT.", "등록된 표준 RVT에서 해당 패밀리를 찾지 못했습니다.")
				.Replace("In-place families cannot be synchronized through this command.", "내부 작성 패밀리는 이 명령으로 동기화할 수 없습니다.")
				.Replace("The family exists in the standard RVT but is not editable through the Revit API.", "표준 RVT에 패밀리는 있지만 Revit API로 편집할 수 없습니다.")
				.Replace("Revit returned no family reference after load.", "로드 후 Revit이 패밀리 참조를 반환하지 않았습니다.")
				.Replace("No family reload is required. Tracking metadata should be refreshed.", "패밀리 재로드는 필요 없고 추적 정보만 갱신하면 됩니다.")
				.Replace("This family requires manual review before overwrite.", "덮어쓰기 전에 수동 검토가 필요한 패밀리입니다.")
				.Replace("No loadable family action is required.", "필요한 로더블 패밀리 작업이 없습니다.")
				.Replace("A project family with the same name exists in a different category. Review it before loading the standard family.", "프로젝트에 같은 이름의 다른 카테고리 패밀리가 있습니다. 표준 패밀리 로드 전에 검토해야 합니다.")
				.Replace("Family: ", "패밀리: ")
				.Replace("Standard category: ", "표준 카테고리: ")
				.Replace("Project category: ", "프로젝트 카테고리: ");
		}

		private static string CountText(int value)
		{
			return value.ToString(CultureInfo.InvariantCulture);
		}

		private static string NormalizeLocal(string value)
		{
			if (value == null)
			{
				return string.Empty;
			}
			return value.Trim().ToLowerInvariant();
		}

		private string Tx(string englishText, string koreanText)
		{
			if (_isKorean)
			{
				return koreanText;
			}
			return englishText;
		}

