		public FamilyBrowserFileGuardPolicy BuildPolicy()
		{
			List<FamilyBrowserFileGuardTarget> targets = new List<FamilyBrowserFileGuardTarget>();
			string nowText = DateTime.UtcNow.ToString("O", CultureInfo.InvariantCulture);
			foreach (DataGridViewRow row in (IEnumerable)_grid.Rows)
			{
				if (row != null && CellBool(RuntimeHelpers.GetObjectValue(row.Cells["Protect"].Value)))
				{
					string filePath = row.Tag as string;
					if (!string.IsNullOrWhiteSpace(filePath))
					{
						targets.Add(new FamilyBrowserFileGuardTarget
						{
							Enabled = true,
							FileName = Path.GetFileName(filePath),
							CentralPath = filePath,
							RelativePath = Convert.ToString(RuntimeHelpers.GetObjectValue(row.Cells["RelativePath"].Value), CultureInfo.InvariantCulture),
							BlockFamilyLoadAndEdit = CellBool(RuntimeHelpers.GetObjectValue(row.Cells["BlockFamily"].Value)),
							BlockTypeChanges = CellBool(RuntimeHelpers.GetObjectValue(row.Cells["BlockType"].Value)),
							LastUpdatedUtc = nowText,
							LastUpdatedBy = Environment.UserName
						});
					}
				}
			}
			return new FamilyBrowserFileGuardPolicy
			{
				Enabled = (targets.Count > 0),
				RootFolder = _rootFolder,
				Targets = targets,
				LastUpdatedUtc = nowText,
				LastUpdatedBy = Environment.UserName
			};
		}

		private void AddRows(List<string> rvtFiles, FamilyBrowserFileGuardPolicy currentGuard)
		{
			Dictionary<string, FamilyBrowserFileGuardTarget> targetByPath = BuildTargetLookup(currentGuard);
			foreach (string filePath in rvtFiles ?? new List<string>())
			{
				string relativePath = MakeRelativePath(_rootFolder, filePath);
				string key = NormalizePathForLookup(filePath);
				FamilyBrowserFileGuardTarget current = null;
				if (!targetByPath.TryGetValue(key, out current))
				{
					targetByPath.TryGetValue(NormalizePathForLookup(relativePath), out current);
				}
				if (current == null)
				{
					targetByPath.TryGetValue(NormalizeNameForLookup(Path.GetFileName(filePath)), out current);
				}
				bool isProtected = current?.Enabled ?? false;
				bool blockFamily = current?.BlockFamilyLoadAndEdit ?? true;
				bool blockType = current?.BlockTypeChanges ?? true;
				int index = _grid.Rows.Add(isProtected, Path.GetFileName(filePath), relativePath, blockFamily, blockType);
				_grid.Rows[index].Tag = filePath;
			}
		}

		private static Dictionary<string, FamilyBrowserFileGuardTarget> BuildTargetLookup(FamilyBrowserFileGuardPolicy currentGuard)
		{
			Dictionary<string, FamilyBrowserFileGuardTarget> result = new Dictionary<string, FamilyBrowserFileGuardTarget>(StringComparer.OrdinalIgnoreCase);
			if (currentGuard == null || currentGuard.Targets == null)
			{
				return result;
			}
			foreach (FamilyBrowserFileGuardTarget target in currentGuard.Targets)
			{
				if (target != null)
				{
					AddTargetLookup(result, NormalizePathForLookup(target.CentralPath), target);
					AddTargetLookup(result, NormalizePathForLookup(target.RelativePath), target);
					AddTargetLookup(result, NormalizeNameForLookup(target.FileName), target);
				}
			}
			return result;
		}

		private static void AddTargetLookup(Dictionary<string, FamilyBrowserFileGuardTarget> result, string key, FamilyBrowserFileGuardTarget target)
		{
			if (result != null && !string.IsNullOrWhiteSpace(key) && target != null && !result.ContainsKey(key))
			{
				result.Add(key, target);
			}
		}

		private void SetAllProtected(bool value)
		{
			foreach (DataGridViewRow row in (IEnumerable)_grid.Rows)
			{
				if (!IsSearchActive() || row.Visible)
				{
					row.Cells["Protect"].Value = value;
					if (value)
					{
						row.Cells["BlockFamily"].Value = true;
						row.Cells["BlockType"].Value = true;
					}
				}
			}
		}

		private bool IsSearchActive()
		{
			if (_searchBox != null)
			{
				return !string.IsNullOrWhiteSpace(_searchBox.Text);
			}
			return false;
		}

		private void SearchBoxTextChanged(object sender, EventArgs e)
		{
			ApplySearchFilter();
		}

		private void ApplySearchFilter()
		{
			if (_grid == null)
			{
				return;
			}
			List<string> tokens = SplitSearchTokens((_searchBox == null) ? string.Empty : _searchBox.Text);
			try
			{
				_grid.EndEdit();
				_grid.CurrentCell = null;
			}
			catch (Exception projectError)
			{
				ProjectData.SetProjectError(projectError);
				ProjectData.ClearProjectError();
			}
			DataGridViewRow firstVisible = null;
			foreach (DataGridViewRow row in (IEnumerable)_grid.Rows)
			{
				bool visible = RowMatchesSearch(row, tokens);
				if (row.Visible != visible)
				{
					row.Visible = visible;
				}
				if (visible && firstVisible == null)
				{
					firstVisible = row;
				}
			}
			try
			{
				_grid.ClearSelection();
				if (firstVisible != null)
				{
					firstVisible.Selected = true;
					_grid.CurrentCell = firstVisible.Cells["FileName"];
				}
			}
			catch (Exception projectError2)
			{
				ProjectData.SetProjectError(projectError2);
				ProjectData.ClearProjectError();
			}
			UpdateVisibleCount();
		}

		private void UpdateVisibleCount()
		{
			if (_visibleCountLabel == null || _grid == null)
			{
				return;
			}
			int visible = 0;
			foreach (DataGridViewRow item in (IEnumerable)_grid.Rows)
			{
				if (item.Visible)
				{
					visible = checked(visible + 1);
				}
			}
			_visibleCountLabel.Text = visible.ToString(CultureInfo.InvariantCulture) + " / " + _grid.Rows.Count.ToString(CultureInfo.InvariantCulture);
		}

		private static bool RowMatchesSearch(DataGridViewRow row, List<string> tokens)
		{
			if (row == null || tokens == null || tokens.Count == 0)
			{
				return true;
			}
			string text = string.Join(" ", Convert.ToString(RuntimeHelpers.GetObjectValue(row.Cells["FileName"].Value), CultureInfo.InvariantCulture), Convert.ToString(RuntimeHelpers.GetObjectValue(row.Cells["RelativePath"].Value), CultureInfo.InvariantCulture), (row.Tag as string) ?? string.Empty);
			return tokens.All([SpecialName] (string token) => text.IndexOf(token, StringComparison.OrdinalIgnoreCase) >= 0);
		}

		private static List<string> SplitSearchTokens(string value)
		{
			return (from x in (value ?? string.Empty).Split(new char[4] { ' ', '\t', '\r', '\n' }, StringSplitOptions.RemoveEmptyEntries)
				select x.Trim() into x
				where x.Length > 0
				select x).ToList();
		}

		private void GridCurrentCellDirtyStateChanged(object sender, EventArgs e)
		{
			if (_grid.IsCurrentCellDirty)
			{
				_grid.CommitEdit(DataGridViewDataErrorContexts.Commit);
			}
		}

		private void GridCellValueChanged(object sender, DataGridViewCellEventArgs e)
		{
			if (e != null && e.RowIndex >= 0 && e.ColumnIndex >= 0 && string.Equals(_grid.Columns[e.ColumnIndex].Name, "Protect", StringComparison.OrdinalIgnoreCase))
			{
				DataGridViewRow row = _grid.Rows[e.RowIndex];
				if (CellBool(RuntimeHelpers.GetObjectValue(row.Cells["Protect"].Value)) && !CellBool(RuntimeHelpers.GetObjectValue(row.Cells["BlockFamily"].Value)) && !CellBool(RuntimeHelpers.GetObjectValue(row.Cells["BlockType"].Value)))
				{
					row.Cells["BlockFamily"].Value = true;
					row.Cells["BlockType"].Value = true;
				}
			}
		}

		private static bool CellBool(object value)
		{
			if (value == null || value == DBNull.Value)
			{
				return false;
			}
			if (!(value is bool CellBool))
			{
				if (bool.TryParse(Convert.ToString(RuntimeHelpers.GetObjectValue(value), CultureInfo.InvariantCulture), out var parsed))
				{
					return parsed;
				}
				return false;
			}
			return CellBool;
		}

		private static string MakeRelativePath(string rootFolder, string filePath)
		{
			string MakeRelativePath;
			if (string.IsNullOrWhiteSpace(rootFolder) || string.IsNullOrWhiteSpace(filePath))
			{
				MakeRelativePath = filePath ?? string.Empty;
			}
			else
			{
				try
				{
					string root = Path.GetFullPath(rootFolder).TrimEnd(Path.DirectorySeparatorChar, Path.AltDirectorySeparatorChar) + Conversions.ToString(Path.DirectorySeparatorChar);
					string full = Path.GetFullPath(filePath);
					Uri uri = new Uri(root);
					Uri fileUri = new Uri(full);
					MakeRelativePath = Uri.UnescapeDataString(uri.MakeRelativeUri(fileUri).ToString()).Replace('/', Path.DirectorySeparatorChar);
				}
				catch (Exception projectError)
				{
					ProjectData.SetProjectError(projectError);
					MakeRelativePath = Path.GetFileName(filePath);
					ProjectData.ClearProjectError();
				}
			}
			return MakeRelativePath;
		}

		private static string NormalizePathForLookup(string value)
		{
			string text = (value ?? string.Empty).Trim();
			if (text.Length == 0)
			{
				return string.Empty;
			}
			text = text.Replace('/', '\\').TrimEnd('\\');
			try
			{
				if (Path.IsPathRooted(text))
				{
					text = Path.GetFullPath(text);
				}
			}
			catch (Exception projectError)
			{
				ProjectData.SetProjectError(projectError);
				ProjectData.ClearProjectError();
			}
			return text.ToLowerInvariant();
		}

		private static string NormalizeNameForLookup(string value)
		{
			string text = (value ?? string.Empty).Trim();
			if (text.Length == 0)
			{
				return string.Empty;
			}
			try
			{
				text = Path.GetFileNameWithoutExtension(text);
			}
			catch (Exception projectError)
			{
				ProjectData.SetProjectError(projectError);
				ProjectData.ClearProjectError();
			}
			return text.ToLowerInvariant();
		}

