		private static List<BootstrapProfileChoice> BuildChoices(FamilyBrowserDeploymentBootstrapProfileIndexResult indexResult)
		{
			List<BootstrapProfileChoice> choices = new List<BootstrapProfileChoice> { BootstrapProfileChoice.CreateAutomatic() };
			if (indexResult == null || indexResult.Profiles == null)
			{
				return choices;
			}
			foreach (FamilyBrowserDeploymentBootstrapProfile profile in indexResult.Profiles.Where([SpecialName] (FamilyBrowserDeploymentBootstrapProfile x) => x != null && !x.Disabled))
			{
				choices.Add(BootstrapProfileChoice.Create(profile));
			}
			return choices;
		}

