				{
					action = action.Substring(prefix.Length);
				}
				HandleBrowserAction(Uri.UnescapeDataString(action));
			}
		}

		private void HandleBrowserAction(string action)
		{
			string normalized = (action ?? string.Empty).Trim();
			if (normalized.Equals("cancel", StringComparison.OrdinalIgnoreCase))
			{
				base.DialogResult = DialogResult.Cancel;
				Close();
			}
			else if (normalized.Equals("add-files", StringComparison.OrdinalIgnoreCase))
			{
				AddFilesClicked();
			}
			else if (normalized.StartsWith("remove-files/", StringComparison.OrdinalIgnoreCase))
			{
