			sb.AppendLine("<div class=\"card\"><div class=\"card-title\">" + Html(Tx("Before Registering", "등록 전 확인")) + "</div><div style=\"font-size:13px;line-height:1.55;color:#52655d\">" + Html(Tx("The request will be saved to the configured request store. General users do not need to know or open that folder.", "요청은 설정된 요청 저장소에 저장됩니다. 일반 사용자는 해당 폴더를 알거나 직접 열 필요가 없습니다.")) + "</div></div>");
			sb.AppendLine("</div></div></div>");
			sb.AppendLine("<div class=\"footer\"><div id=\"validation\" class=\"validation\">" + Html(_validationMessage) + "</div><div class=\"actions\"><a class=\"btn ghost\" href=\"kkyfb-request:cancel\">" + Html(Tx("Cancel", "취소")) + "</a><a class=\"btn primary\" href=\"kkyfb-request:submit\">" + Html(Tx("Register", "등록하기")) + "</a></div></div>");
			sb.AppendLine("</div></body></html>");
			return sb.ToString();
		}

		private string BuildKindOptions()
		{
			List<ComboOption> options = new List<ComboOption>
			{
				new ComboOption(Tx("General", "일반"), "GENERAL"),
				new ComboOption(Tx("Family", "패밀리"), "FAMILY"),
				new ComboOption(Tx("System Type", "시스템 타입"), "SYSTEM"),
				new ComboOption(Tx("Update", "업데이트"), "UPDATE")
			};
			StringBuilder sb = new StringBuilder();
			string selectedKind = NormalizeRequestKindValue(_requestKind);
			foreach (ComboOption optionItem in options)
			{
				sb.Append("<option value=\"" + Attr(optionItem.Value) + "\"");
				if (string.Equals(optionItem.Value, selectedKind, StringComparison.OrdinalIgnoreCase))
				{
					sb.Append(" selected");
				}
				sb.Append(">" + Html(optionItem.Text) + "</option>");
			}
			return sb.ToString();
		}

		private string BuildDisciplineChips()
		{
			if (_disciplineOptions.Count == 0)
			{
				return string.Empty;
			}
			StringBuilder sb = new StringBuilder();
			sb.Append("<div class=\"chips\">");
			foreach (string optionText in _disciplineOptions.Take(8))
			{
				sb.Append("<a class=\"chip\" href=\"#\" onclick=\"return pickDiscipline('" + Js(optionText) + "')\">" + Html(optionText) + "</a>");
			}
			sb.Append("</div>");
			return sb.ToString();
		}

		private string BuildAttachmentListHtml()
		{
			if (_attachmentPaths.Count == 0)
			{
				return "<div class=\"empty\">" + Html(Tx("No attachments selected.", "선택된 첨부파일이 없습니다.")) + "<br/>" + Html(Tx("Attach only files needed to explain the request.", "요청 설명에 필요한 파일만 첨부하세요.")) + "</div>";
			}
			StringBuilder sb = new StringBuilder();
			checked
			{
				int num = _attachmentPaths.Count - 1;
				for (int index = 0; index <= num; index++)
				{
					string fileName = Path.GetFileName(_attachmentPaths[index]);
					sb.Append("<label class=\"attach-row\"><input type=\"checkbox\" name=\"removeFile\" value=\"" + index.ToString(CultureInfo.InvariantCulture) + "\" /><span class=\"attach-name\">" + Html(fileName) + "</span></label>");
				}
				return sb.ToString();
			}
		}

		private static string NormalizeRequestKindValue(string value)
		{
			string normalized = (value ?? string.Empty).Trim().ToUpperInvariant();
			switch (normalized)
			{
			case "FAMILY":
			case "SYSTEM":
			case "UPDATE":
			case "GENERAL":
				return normalized;
			default:
				return "GENERAL";
			}
		}

		private string Tx(string englishText, string koreanText)
		{
			if (_isKorean)
			{
				return koreanText;
			}
			return englishText;
		}
	}

