		public StandardRvtManagerHtmlForm(FamilyBrowserDashboardHtmlForm owner)
		{
			if (owner == null)
			{
				throw new ArgumentNullException("owner");
			}
			_owner = owner;
			Text = _owner.T("Standard RVT Manager", "표준 RVT 관리");
			base.AutoScaleMode = AutoScaleMode.Dpi;
			base.AutoScaleDimensions = new SizeF(96f, 96f);
			base.StartPosition = FormStartPosition.CenterParent;
			base.FormBorderStyle = FormBorderStyle.Sizable;
			base.MinimizeBox = false;
			base.MaximizeBox = true;
			base.ShowInTaskbar = false;
			BackColor = Color.White;
			Rectangle workingArea = Screen.FromControl(owner).WorkingArea;
			checked
			{
				int dialogWidth = Math.Min(Math.Max(1120, (int)Math.Floor((double)workingArea.Width * 0.68)), Math.Max(900, workingArea.Width - 96));
				int dialogHeight = Math.Min(Math.Max(650, (int)Math.Floor((double)workingArea.Height * 0.64)), Math.Max(600, workingArea.Height - 96));
				MinimumSize = new Size(900, 560);
				base.ClientSize = new Size(dialogWidth, dialogHeight);
				_browser = new WebBrowser
				{
					Dock = DockStyle.Fill,
					ScriptErrorsSuppressed = true,
					AllowNavigation = true,
					IsWebBrowserContextMenuEnabled = false,
					WebBrowserShortcutsEnabled = true
				};
