		public void RefreshContent()
		{
			_browser.DocumentText = BuildHtml();
		}

		private void HandleBrowserNavigating(object sender, WebBrowserNavigatingEventArgs e)
		{
			if (e == null || (object)e.Url == null)
			{
				return;
			}
			string action = e.Url.ToString() ?? string.Empty;
			if (action.StartsWith("kkyfb:", StringComparison.OrdinalIgnoreCase))
			{
				e.Cancel = true;
				string actionName = action.Substring("kkyfb:".Length);
				if (string.Equals(actionName, "manager-refresh", StringComparison.OrdinalIgnoreCase))
				{
					RefreshContent();
				}
				else if (string.Equals(actionName, "standard-rvt-manager-close", StringComparison.OrdinalIgnoreCase))
				{
					Close();
				}
				else
				{
					_owner.RunStandardRvtManagerCommand(actionName);
				}
			}
		}

