		base.WindowState = FormWindowState.Normal;
		ApplyRecommendedWindowSize(ResolveStartupScreen());
		BackColor = Color.White;
		_browser = new WebBrowser
		{
			Dock = DockStyle.Fill,
			ScriptErrorsSuppressed = true,
			AllowWebBrowserDrop = false,
			IsWebBrowserContextMenuEnabled = false,
			WebBrowserShortcutsEnabled = true
		};
		_browser.Navigating += BrowserNavigating;
		_browser.DocumentCompleted += BrowserDocumentCompleted;
		_browser.ProgressChanged += BrowserProgressChanged;
		_browser.PreviewKeyDown += BrowserPreviewKeyDown;
		base.KeyDown += DashboardKeyDown;
		base.Shown += DashboardShown;
		base.Controls.Add(_browser);
		_startupOverlay = CreateStartupOverlay();
		base.Controls.Add(_startupOverlay);
		_startupOverlay.BringToFront();
		_requestRefreshTimer = new System.Windows.Forms.Timer
		{
			Interval = 20000
		};
		_requestRefreshTimer.Tick += RequestRefreshTimerTick;
		_homepageSecurityRefreshTimer = new System.Windows.Forms.Timer
		{
			Interval = 60000
		};
		_homepageSecurityRefreshTimer.Tick += HomepageSecurityRefreshTimerTick;
		_startupOverlayReadyTimer = new System.Windows.Forms.Timer
		{
			Interval = 200
		};
		_startupOverlayReadyTimer.Tick += StartupOverlayReadyTimerTick;
		RenderStartupShellOnly();
	}

	protected override void OnFormClosed(FormClosedEventArgs e)
	{
		try
		{
			_startupOverlayReadyTimer.Stop();
			_startupOverlayReadyTimer.Dispose();
		}
		catch (Exception projectError)
		{
			ProjectData.SetProjectError(projectError);
			ProjectData.ClearProjectError();
		}
		try
		{
			_requestRefreshTimer.Stop();
			_requestRefreshTimer.Dispose();
		}
		catch (Exception projectError2)
		{
			ProjectData.SetProjectError(projectError2);
			ProjectData.ClearProjectError();
		}
		try
		{
			_homepageSecurityRefreshTimer.Stop();
			_homepageSecurityRefreshTimer.Dispose();
		}
		catch (Exception projectError3)
		{
			ProjectData.SetProjectError(projectError3);
			ProjectData.ClearProjectError();
		}
		base.OnFormClosed(e);
