	private void DashboardShown(object sender, EventArgs e)
	{
		if (!_startBoundsApplied)
		{
			_startBoundsApplied = true;
			ApplyRecommendedWindowSize(ResolveStartupScreen());
			QueueInitialOpenRefresh();
		}
	}

	private void QueueInitialOpenRefresh()
	{
		if (!_initialOpenRefreshQueued && !base.IsDisposed)
		{
			_initialOpenRefreshQueued = true;
			BeginInvoke(new Action(DeferredInitialOpenRefresh));
		}
	}

	private void DeferredInitialOpenRefresh()
	{
		if (base.IsDisposed)
		{
			return;
		}
		string refreshTitle = T("Loading Family Browser list", "패밀리 브라우저 목록 불러오는 중");
		string refreshMessage = T("Loading cached scan data and browser rows...", "캐시된 스캔 데이터와 브라우저 목록을 불러오는 중...");
		try
		{
			UpdateStartupOverlayProgress(1, 100, refreshMessage, forcePaint: true);
			WriteDashboardRuntimeDiagnostic("initial-open-refresh-start", -1, -1L);
			RefreshDocumentShellOnlyWithProgress(refreshTitle, refreshMessage, 1);
			UpdateStartupOverlayProgress(100, 100, T("Dashboard refresh completed.", "대시보드 갱신이 완료되었습니다."), forcePaint: true);
			WriteDashboardRuntimeDiagnostic("initial-open-refresh-complete", -1, -1L);
		}
		catch (Exception ex)
		{
			ProjectData.SetProjectError(ex);
			Exception ex2 = ex;
			UpdateStartupOverlayProgress(100, 100, T("Startup refresh failed. Keeping the fallback dashboard shell visible.", "시작 갱신 중 오류가 발생했습니다. 기본 대시보드 화면을 유지합니다."), forcePaint: true);
			WriteDashboardRuntimeDiagnostic("initial-open-refresh-failed:" + ex2.Message, -1, -1L);
			ProjectData.ClearProjectError();
		}
		finally
		{
			try
			{
				if (!_requestRefreshTimer.Enabled)
				{
					_requestRefreshTimer.Start();
				}
			}
			catch (Exception projectError)
			{
				ProjectData.SetProjectError(projectError);
				ProjectData.ClearProjectError();
			}
			StartDeferredDeploymentBootstrapRefresh();
			try
			{
				if (!_homepageSecurityRefreshTimer.Enabled)
				{
					_homepageSecurityRefreshTimer.Start();
				}
			}
			catch (Exception projectError2)
			{
				ProjectData.SetProjectError(projectError2);
				ProjectData.ClearProjectError();
			}
		}
	}

