			string detail = (num ? "창을 먼저 표시한 뒤 등록 정보와 권한 상태를 불러옵니다." : "The window is shown first; registration and permission status load next.");
			string startupHtml = "<!doctype html><html><head><meta charset=\"utf-8\"><style>body{margin:0;font-family:'Malgun Gothic','Segoe UI',Arial,sans-serif;background:#f6f7f9;color:#20242a}.shell{height:100vh;display:flex;align-items:center;justify-content:center}.panel{width:min(520px,calc(100vw - 48px));padding:28px 30px;border:1px solid #d9dee7;background:#fff;border-radius:8px;box-shadow:0 12px 32px rgba(15,23,42,.10)}.brand{font-size:13px;font-weight:700;color:#246b65;letter-spacing:.02em;text-transform:uppercase;margin-bottom:12px}h1{font-size:22px;line-height:1.35;margin:0 0 10px}p{font-size:14px;line-height:1.6;margin:0;color:#5c6573}.bar{height:3px;background:#e6eaef;margin-top:22px;overflow:hidden;border-radius:999px}.bar span{display:block;width:38%;height:100%;background:#2b8a7e;animation:move 1.2s infinite ease-in-out}@keyframes move{0%{transform:translateX(-100%)}100%{transform:translateX(280%)}}</style></head><body><div class=\"shell\"><div class=\"panel\"><div class=\"brand\">KKY Family Browser</div><h1>" + Html(title) + "</h1><p>" + Html(detail) + "</p><div class=\"bar\"><span></span></div></div></div></body></html>";
			_browser.DocumentText = startupHtml;
			WriteDashboardRuntimeDiagnostic("startup-shell-render-complete", startupHtml.Length, 0L);
