	private bool IsStartupOverlayVisible()
	{
		if (!_startupOverlayDismissed && _startupOverlay != null)
		{
			return _startupOverlay.Visible;
		}
		return false;
	}

	private void UpdateStartupOverlayProgress(int current, int total, string message, bool forcePaint = false)
	{
		if (base.IsDisposed)
		{
			return;
		}
		if (base.InvokeRequired)
		{
			try
			{
				BeginInvoke((Action)([SpecialName] () =>
				{
					UpdateStartupOverlayProgress(current, total, message, forcePaint);
				}));
				return;
			}
			catch (Exception projectError)
			{
				ProjectData.SetProjectError(projectError);
				ProjectData.ClearProjectError();
				return;
			}
		}
		if (!IsStartupOverlayVisible())
		{
			return;
		}
		int safeTotal = Math.Max(1, total);
		int safeCurrent = Math.Max(0, Math.Min(current, safeTotal));
		int percent = ResolveLongOperationPercent(safeCurrent, safeTotal);
		string cleanMessage = (message ?? string.Empty).Trim();
		if (string.IsNullOrWhiteSpace(cleanMessage))
		{
			cleanMessage = T("Preparing dashboard render...", "대시보드 렌더를 준비하는 중...");
		}
		try
		{
			if (_startupOverlayTitleLabel != null)
			{
				_startupOverlayTitleLabel.Text = T("Opening Family Browser", "Family Browser 여는 중");
			}
			if (_startupOverlayDetailLabel != null)
			{
				_startupOverlayDetailLabel.Text = cleanMessage;
			}
			if (_startupOverlayStageLabel != null)
			{
				_startupOverlayStageLabel.Text = percent.ToString(CultureInfo.InvariantCulture) + "% - " + safeCurrent.ToString(CultureInfo.InvariantCulture) + " / " + safeTotal.ToString(CultureInfo.InvariantCulture);
			}
			if (_startupOverlayProgressBar != null)
			{
				if (_startupOverlayProgressBar.Style != ProgressBarStyle.Continuous)
				{
					_startupOverlayProgressBar.Style = ProgressBarStyle.Continuous;
				}
				_startupOverlayProgressBar.Value = Math.Max(_startupOverlayProgressBar.Minimum, Math.Min(_startupOverlayProgressBar.Maximum, percent));
			}
			DateTime now = DateTime.UtcNow;
			if (forcePaint || DateTime.Compare(_startupOverlayProgressLastPaintUtc, DateTime.MinValue) == 0 || (now - _startupOverlayProgressLastPaintUtc).TotalMilliseconds >= 120.0)
			{
				_startupOverlayProgressLastPaintUtc = now;
				_startupOverlay.Refresh();
				_startupOverlay.Update();
			}
		}
		catch (Exception projectError2)
		{
			ProjectData.SetProjectError(projectError2);
			ProjectData.ClearProjectError();
		}
	}

	private void DismissStartupOverlayIfDashboardReady()
	{
		if (_startupOverlayDismissed || _startupOverlay == null)
		{
			return;
		}
		try
		{
			if (_browser == null || (object)_browser.Document == null || (object)_browser.Document.GetElementById("dashboardRoot") == null || (object)_browser.Document.Body == null)
			{
				return;
			}
			if (!string.Equals(_browser.Document.Body.GetAttribute("data-kkyfb-ready") ?? string.Empty, "true", StringComparison.OrdinalIgnoreCase))
			{
				if (DateTime.Compare(_startupOverlayReadyPollStartedUtc, DateTime.MinValue) == 0 || !((DateTime.UtcNow - _startupOverlayReadyPollStartedUtc).TotalSeconds > 30.0))
				{
					QueueStartupOverlayReadyPoll();
					return;
				}
				WriteDashboardRuntimeDiagnostic("startup-overlay-dismiss-timeout", -1, -1L);
			}
			_startupOverlayDismissed = true;
			_startupOverlay.Visible = false;
			_startupOverlay.SendToBack();
			try
			{
				_startupOverlayReadyTimer.Stop();
			}
			catch (Exception projectError)
			{
				ProjectData.SetProjectError(projectError);
				ProjectData.ClearProjectError();
			}
			WriteDashboardRuntimeDiagnostic("startup-overlay-dismissed", -1, -1L);
		}
		catch (Exception projectError2)
		{
			ProjectData.SetProjectError(projectError2);
			ProjectData.ClearProjectError();
		}
	}

	private void QueueStartupOverlayReadyPoll()
	{
		if (_startupOverlayDismissed || _startupOverlayReadyTimer == null)
		{
			return;
		}
		try
		{
			if (DateTime.Compare(_startupOverlayReadyPollStartedUtc, DateTime.MinValue) == 0)
			{
				_startupOverlayReadyPollStartedUtc = DateTime.UtcNow;
			}
			if (!_startupOverlayReadyTimer.Enabled)
			{
				_startupOverlayReadyTimer.Start();
			}
		}
		catch (Exception projectError)
		{
			ProjectData.SetProjectError(projectError);
			ProjectData.ClearProjectError();
		}
	}

	private void StartupOverlayReadyTimerTick(object sender, EventArgs e)
	{
		DismissStartupOverlayIfDashboardReady();
	}

	private void StartDeferredDeploymentBootstrapRefresh()
	{
		if (_deferredBootstrapStarted || base.IsDisposed)
		{
			return;
		}
		_deferredBootstrapStarted = true;
		string workspaceRoot = _workspaceRoot;
		string userName = Environment.UserName;
		FamilyBrowserDeploymentProjectIdentity projectIdentity = BuildDeploymentProjectIdentity(GetActiveDocument(), includeCentralPath: false);
		string beforeRefreshSignature = BuildDeploymentRefreshSignature(_standardPolicy);
		WriteDashboardRuntimeDiagnostic("deferred-bootstrap-start", -1, -1L);
		Task.Factory.StartNew([SpecialName] () => FamilyBrowserDeploymentBootstrapService.TryApply(workspaceRoot, userName, force: false, projectIdentity), CancellationToken.None, TaskCreationOptions.DenyChildAttach, TaskScheduler.Default).ContinueWith([SpecialName] (Task<FamilyBrowserDeploymentBootstrapResult> t) =>
		{
			try
			{
				if (!base.IsDisposed)
				{
					BeginInvoke((Action)([SpecialName] () =>
					{
						if (!base.IsDisposed)
						{
							if (t.Status == TaskStatus.RanToCompletion)
							{
								_deploymentBootstrapResult = t.Result;
								WriteDashboardRuntimeDiagnostic("deferred-bootstrap-complete:" + ResolveDeploymentBootstrapMessage(), -1, -1L);
								if (ShouldRefreshAfterDeferredBootstrap(beforeRefreshSignature, t.Result))
								{
									WriteDashboardRuntimeDiagnostic("deferred-bootstrap-refresh:policy-changed", -1, -1L);
									RefreshAfterDeferredBootstrapPolicyChanged();
								}
								else
								{
									WriteDashboardRuntimeDiagnostic("deferred-bootstrap-refresh-skip:no-policy-change", -1, -1L);
								}
							}
							else if (t.IsFaulted && t.Exception != null)
							{
								WriteDashboardRuntimeDiagnostic("deferred-bootstrap-failed:" + t.Exception.GetBaseException().Message, -1, -1L);
							}
						}
					}));
				}
			}
			catch (Exception projectError)
			{
				ProjectData.SetProjectError(projectError);
				ProjectData.ClearProjectError();
			}
		});
	}

	private void RefreshAfterDeferredBootstrapPolicyChanged()
	{
		_standardPolicy = LoadStandardPolicy();
		FamilyBrowserNativeCommandGuardService.NotifyPolicyChanged();
		string refreshTitle = T("Reloading Family Browser list", "패밀리 브라우저 목록 다시 불러오는 중");
		string refreshMessage = T("Homepage settings changed. Reloading cached browser rows...", "홈페이지 설정이 변경되어 캐시된 브라우저 목록을 다시 불러오는 중...");
		RefreshDocumentShellOnlyWithProgress(refreshTitle, refreshMessage);
	}

	private bool ShouldRefreshAfterDeferredBootstrap(string beforeRefreshSignature, FamilyBrowserDeploymentBootstrapResult result)
	{
		bool ShouldRefreshAfterDeferredBootstrap;
		if (result == null || !result.Applied)
		{
			ShouldRefreshAfterDeferredBootstrap = false;
		}
		else
		{
			try
			{
				FamilyBrowserStandardPolicy afterPolicy = LoadStandardPolicy();
				string afterRefreshSignature = BuildDeploymentRefreshSignature(afterPolicy);
				ShouldRefreshAfterDeferredBootstrap = !string.Equals(beforeRefreshSignature, afterRefreshSignature, StringComparison.Ordinal);
			}
			catch (Exception projectError)
			{
				ProjectData.SetProjectError(projectError);
				ShouldRefreshAfterDeferredBootstrap = true;
				ProjectData.ClearProjectError();
			}
		}
		return ShouldRefreshAfterDeferredBootstrap;
	}

	private string BuildDeploymentRefreshSignature(FamilyBrowserStandardPolicy policy)
	{
		List<string> parts = new List<string>();
		try
		{
			FamilyBrowserMachineConfig config = FamilyBrowserMachineConfigStore.Load();
			parts.Add("config");
			parts.Add(config.UseManagedPolicy ? "true" : "false");
			parts.Add(config.ManagedPolicyPath ?? string.Empty);
			parts.Add(config.DeploymentBootstrapUrl ?? string.Empty);
		}
		catch (Exception projectError)
		{
			ProjectData.SetProjectError(projectError);
			parts.Add("config-unreadable");
			ProjectData.ClearProjectError();
		}
		AppendPolicyRefreshSignature(parts, policy);
		return string.Join("|", parts.Select([SpecialName] (string x) => (x ?? string.Empty).Replace("|", "/")));
	}

	private static void AppendPolicyRefreshSignature(List<string> parts, FamilyBrowserStandardPolicy policy)
	{
		if (parts == null)
		{
			return;
		}
		if (policy == null)
		{
			parts.Add("policy-null");
			return;
		}
		parts.Add("policy");
		parts.Add(policy.Mode ?? string.Empty);
		parts.Add(policy.ActiveDiscipline ?? string.Empty);
		AppendSlotRefreshSignature(parts, "integrated", policy.IntegratedLibrary);
		parts.Add("slots");
		foreach (FamilyBrowserStandardLibrarySlot slot in (policy.DisciplineLibraries ?? new List<FamilyBrowserStandardLibrarySlot>()).Where([SpecialName] (FamilyBrowserStandardLibrarySlot x) => x != null).OrderBy([SpecialName] (FamilyBrowserStandardLibrarySlot x) => x.SlotKey ?? string.Empty, StringComparer.OrdinalIgnoreCase).ThenBy([SpecialName] (FamilyBrowserStandardLibrarySlot x) => x.Discipline ?? string.Empty, StringComparer.OrdinalIgnoreCase))
		{
			AppendSlotRefreshSignature(parts, "slot", slot);
		}
		FamilyBrowserRequestStoreSettings requestStore = policy.RequestStore ?? new FamilyBrowserRequestStoreSettings();
		parts.Add("request-store");
		parts.Add(requestStore.Mode ?? string.Empty);
		parts.Add(requestStore.Path ?? string.Empty);
		parts.Add(requestStore.Endpoint ?? string.Empty);
		FamilyBrowserPermissionExcelSettings permissionExcel = policy.PermissionExcel ?? new FamilyBrowserPermissionExcelSettings();
		parts.Add("permission-excel");
		parts.Add(permissionExcel.Enabled ? "true" : "false");
		parts.Add(permissionExcel.Path ?? string.Empty);
		parts.Add(permissionExcel.SheetName ?? string.Empty);
		FamilyBrowserSecurityPolicy security = policy.Security ?? FamilyBrowserSecurityPolicy.CreateDefault();
		parts.Add("security");
		AppendNormalizedStringList(parts, security.AdminUsers);
		AppendNormalizedStringList(parts, security.AdminProfileKeywords);
		AppendNormalizedStringList(parts, security.RequestApproverUsers);
		AppendNormalizedStringList(parts, security.ReadOnlyUsers);
		parts.Add(security.AllowUnlistedUsersAsModelers ? "true" : "false");
		parts.Add(security.AllowModelersToLoadFamilies ? "true" : "false");
		parts.Add(security.AllowModelersToApplySystemTypes ? "true" : "false");
		parts.Add(security.AllowModelersToSubmitRequests ? "true" : "false");
		parts.Add("project-rules");
		foreach (FamilyBrowserProjectPolicyRule rule in (policy.ProjectPolicyRules ?? new List<FamilyBrowserProjectPolicyRule>()).Where([SpecialName] (FamilyBrowserProjectPolicyRule x) => x != null).OrderBy([SpecialName] (FamilyBrowserProjectPolicyRule x) => x.RuleName ?? string.Empty, StringComparer.OrdinalIgnoreCase))
		{
			parts.Add(rule.RuleName ?? string.Empty);
			parts.Add(rule.Enabled ? "true" : "false");
			parts.Add(rule.MatchMode ?? string.Empty);
			parts.Add(rule.MatchValue ?? string.Empty);
			parts.Add(rule.PermissionPreset ?? string.Empty);
			AppendNormalizedStringList(parts, rule.CustomAdminUsers);
			AppendNormalizedStringList(parts, rule.CustomRequestApproverUsers);
			AppendNormalizedStringList(parts, rule.CustomReadOnlyUsers);
			parts.Add(rule.AllowUnlistedUsersAsModelers ?? string.Empty);
			parts.Add(rule.AllowModelersToLoadFamilies ?? string.Empty);
			parts.Add(rule.AllowModelersToApplySystemTypes ?? string.Empty);
			parts.Add(rule.AllowModelersToSubmitRequests ?? string.Empty);
		}
		FamilyBrowserFileGuardPolicy fileGuard = policy.FileGuard ?? FamilyBrowserFileGuardPolicy.CreateDefault();
		parts.Add("file-guard");
		parts.Add(fileGuard.Enabled ? "true" : "false");
		parts.Add(fileGuard.RootFolder ?? string.Empty);
		foreach (FamilyBrowserFileGuardTarget target in (fileGuard.Targets ?? new List<FamilyBrowserFileGuardTarget>()).Where([SpecialName] (FamilyBrowserFileGuardTarget x) => x != null).OrderBy([SpecialName] (FamilyBrowserFileGuardTarget x) => x.RelativePath ?? string.Empty, StringComparer.OrdinalIgnoreCase).ThenBy([SpecialName] (FamilyBrowserFileGuardTarget x) => x.FileName ?? string.Empty, StringComparer.OrdinalIgnoreCase))
		{
			parts.Add(target.Enabled ? "true" : "false");
			parts.Add(target.FileName ?? string.Empty);
			parts.Add(target.CentralPath ?? string.Empty);
			parts.Add(target.RelativePath ?? string.Empty);
			parts.Add(target.BlockFamilyLoadAndEdit ? "true" : "false");
			parts.Add(target.BlockTypeChanges ? "true" : "false");
		}
	}

	private static void AppendSlotRefreshSignature(List<string> parts, string label, FamilyBrowserStandardLibrarySlot slot)
	{
		parts.Add(label);
		if (slot == null)
		{
			parts.Add("null");
			return;
		}
		parts.Add(slot.SlotKey ?? string.Empty);
		parts.Add(slot.Discipline ?? string.Empty);
		parts.Add(slot.DisplayName ?? string.Empty);
		parts.Add(slot.RegistrationPath ?? string.Empty);
		parts.Add(slot.SourceId ?? string.Empty);
		parts.Add(slot.StandardRvtPath ?? string.Empty);
		parts.Add(slot.SnapshotPath ?? string.Empty);
		parts.Add(slot.StandardListPath ?? string.Empty);
		parts.Add(slot.StandardListSheetName ?? string.Empty);
		parts.Add(slot.LastSnapshotAtUtc ?? string.Empty);
		parts.Add(slot.Enabled ? "true" : "false");
	}

	private static void AppendNormalizedStringList(List<string> parts, IEnumerable<string> values)
	{
		parts?.Add(string.Join(",", (from x in values ?? new List<string>()
			where !string.IsNullOrWhiteSpace(x)
			select x.Trim()).OrderBy([SpecialName] (string x) => x, StringComparer.OrdinalIgnoreCase)));
	}

