	private void StartDeferredHomepageSecurityRefresh()
	{
		if (_homepageSecurityRefreshInFlight || base.IsDisposed)
		{
			return;
		}
		_homepageSecurityRefreshInFlight = true;
		string workspaceRoot = _workspaceRoot;
		string userName = Environment.UserName;
		FamilyBrowserDeploymentProjectIdentity projectIdentity = BuildDeploymentProjectIdentity(GetActiveDocument(), includeCentralPath: false);
		string a = BuildHomepageSecuritySignature(_standardPolicy);
		WriteDashboardRuntimeDiagnostic("homepage-security-refresh-start", -1, -1L);
		Task.Factory.StartNew([SpecialName] () => FamilyBrowserDeploymentBootstrapService.RefreshSecurityFromHomepage(workspaceRoot, userName, projectIdentity), CancellationToken.None, TaskCreationOptions.DenyChildAttach, TaskScheduler.Default).ContinueWith([SpecialName] (Task<FamilyBrowserDeploymentBootstrapSecurityRefreshResult> t) =>
		{
			try
			{
				if (!base.IsDisposed)
				{
					BeginInvoke((Action)([SpecialName] () =>
					{
						try
						{
							if (!base.IsDisposed)
							{
								if (t.Status == TaskStatus.RanToCompletion)
								{
									FamilyBrowserDeploymentBootstrapSecurityRefreshResult result = t.Result;
									WriteDashboardRuntimeDiagnostic("homepage-security-refresh-complete:" + ((result == null) ? string.Empty : result.Message), -1, -1L);
									if (result != null && result.Success && result.Changed)
									{
										_standardPolicy = LoadStandardPolicy();
										FamilyBrowserNativeCommandGuardService.NotifyPolicyChanged();
										EnsureAdminModeAllowed(_standardPolicy);
										string b = BuildHomepageSecuritySignature(_standardPolicy);
										if (!string.Equals(a, b, StringComparison.Ordinal))
										{
											RefreshDocumentShellOnly();
										}
									}
								}
								else if (t.IsFaulted && t.Exception != null)
								{
									WriteDashboardRuntimeDiagnostic("homepage-security-refresh-failed:" + t.Exception.GetBaseException().Message, -1, -1L);
								}
							}
						}
						finally
						{
							_homepageSecurityRefreshInFlight = false;
						}
					}));
				}
			}
			catch (Exception projectError)
			{
				ProjectData.SetProjectError(projectError);
				_homepageSecurityRefreshInFlight = false;
				ProjectData.ClearProjectError();
			}
		});
	}

	private string BuildHomepageSecuritySignature(FamilyBrowserStandardPolicy policy)
	{
		FamilyBrowserSecurityPolicy security = null;
		if (policy != null)
		{
			security = policy.Security;
		}
		if (security == null)
		{
			security = FamilyBrowserSecurityPolicy.CreateDefault();
		}
		List<string> parts = new List<string> { "security" };
		AppendNormalizedStringList(parts, security.AdminUsers);
		AppendNormalizedStringList(parts, security.AdminProfileKeywords);
		AppendNormalizedStringList(parts, security.RequestApproverUsers);
		AppendNormalizedStringList(parts, security.ReadOnlyUsers);
		parts.Add(security.AllowUnlistedUsersAsModelers ? "true" : "false");
		parts.Add(security.AllowModelersToLoadFamilies ? "true" : "false");
		parts.Add(security.AllowModelersToApplySystemTypes ? "true" : "false");
		parts.Add(security.AllowModelersToSubmitRequests ? "true" : "false");
		return string.Join("|", parts.Select([SpecialName] (string x) => (x ?? string.Empty).Replace("|", "/")));
	}

	private void ApplyRecommendedWindowSize(Screen screen)
	{
		Screen obj = screen ?? Screen.PrimaryScreen;
		Size startSize = GetRecommendedStartSize(obj);
		MinimumSize = GetRecommendedMinimumSize(screen, startSize);
		base.Size = startSize;
		Rectangle area = obj.WorkingArea;
		checked
		{
			base.Location = new Point(area.Left + Math.Max(0, unchecked(checked(area.Width - base.Width) / 2)), area.Top + Math.Max(0, unchecked(checked(area.Height - base.Height) / 2)));
		}
	}

	private static Size GetRecommendedMinimumSize(Screen screen, Size startSize)
	{
		Rectangle area = (screen ?? Screen.PrimaryScreen).WorkingArea;
		int widthFloor = ((area.Width <= 1500) ? 1120 : 1280);
		int heightFloor = ((area.Height <= 850) ? 620 : 680);
		checked
		{
			int width = Math.Min(startSize.Width, Math.Max(Math.Min(widthFloor, startSize.Width), (int)Math.Floor((double)startSize.Width * 0.68)));
			int height = Math.Min(startSize.Height, Math.Max(Math.Min(heightFloor, startSize.Height), (int)Math.Floor((double)startSize.Height * 0.68)));
			return new Size(width, height);
		}
	}

	private static Size GetRecommendedStartSize(Screen screen)
	{
		Rectangle area = (screen ?? Screen.PrimaryScreen).WorkingArea;
		int horizontalMargin = ((area.Width <= 1500) ? 16 : ((area.Width > 2200) ? 128 : 64));
		int verticalMargin = ((area.Height <= 850) ? 34 : ((area.Height > 1300) ? 120 : 64));
		checked
		{
			int maxWidth = Math.Max(720, area.Width - horizontalMargin);
			int maxHeight = Math.Max(520, area.Height - verticalMargin);
			int idealWidth = ((area.Width <= 1500) ? maxWidth : ((area.Width > 2200) ? Math.Min(maxWidth, 1780) : Math.Min(maxWidth, 1680)));
			int idealHeight = ((area.Height <= 850) ? maxHeight : ((area.Height > 1300) ? Math.Min(maxHeight, 1040) : Math.Min(maxHeight, 960)));
			int minWidth = Math.Min(maxWidth, (area.Width <= 1500) ? 1180 : 1540);
			int minHeight = Math.Min(maxHeight, (area.Height <= 850) ? 700 : 840);
			int width = ClampInt(idealWidth, minWidth, maxWidth);
			int height = ClampInt(idealHeight, minHeight, maxHeight);
			return new Size(width, height);
		}
	}

	private Screen ResolveStartupScreen()
	{
		Screen ResolveStartupScreen;
		try
		{
			PropertyInfo handleProperty = ((object)_uiApplication).GetType().GetProperty("MainWindowHandle");
			if ((object)handleProperty != null)
			{
				object rawHandle = RuntimeHelpers.GetObjectValue(handleProperty.GetValue(_uiApplication, null));
				if (rawHandle is IntPtr)
				{
					IntPtr handle = ((rawHandle != null) ? ((IntPtr)rawHandle) : default(IntPtr));
					if (handle != IntPtr.Zero)
					{
						ResolveStartupScreen = Screen.FromHandle(handle);
						goto IL_008f;
					}
				}
			}
		}
		catch (Exception projectError)
		{
			ProjectData.SetProjectError(projectError);
			ProjectData.ClearProjectError();
		}
		try
		{
			ResolveStartupScreen = Screen.FromPoint(Cursor.Position);
		}
		catch (Exception projectError2)
		{
			ProjectData.SetProjectError(projectError2);
			ResolveStartupScreen = Screen.PrimaryScreen;
			ProjectData.ClearProjectError();
		}
		goto IL_008f;
		IL_008f:
		return ResolveStartupScreen;
	}

	private static int ClampInt(int value, int minValue, int maxValue)
	{
		if (maxValue < minValue)
		{
			return maxValue;
		}
		return Math.Max(minValue, Math.Min(maxValue, value));
	}

	private void BrowserNavigating(object sender, WebBrowserNavigatingEventArgs e)
	{
		if ((object)e.Url != null)
		{
			string raw = e.Url.ToString();
			if (raw.StartsWith("kkyfb:", StringComparison.OrdinalIgnoreCase))
			{
				e.Cancel = true;
				CaptureDashboardUiState();
				RememberActiveDashboardTab();
				string action = raw.Substring("kkyfb:".Length).Trim('/', ' ');
				DispatchOrRunDashboardAction(action);
			}
		}
	}

	private void CaptureDashboardUiState()
	{
		try
		{
			if (_browser != null && (object)_browser.Document != null)
			{
				string json = Convert.ToString(RuntimeHelpers.GetObjectValue(RuntimeHelpers.GetObjectValue(_browser.Document.InvokeScript("captureDashboardUiStateJson"))), CultureInfo.InvariantCulture);
				if (!string.IsNullOrWhiteSpace(json))
				{
					_lastDashboardUiStateJson = json;
				}
			}
		}
		catch (Exception projectError)
		{
			ProjectData.SetProjectError(projectError);
			ProjectData.ClearProjectError();
		}
	}

	private void RememberActiveDashboardTab()
	{
		try
		{
			if (_browser != null && (object)_browser.Document != null)
			{
				string tab = Convert.ToString(RuntimeHelpers.GetObjectValue(RuntimeHelpers.GetObjectValue(_browser.Document.InvokeScript("eval", new object[1] { "currentTab" }))), CultureInfo.InvariantCulture);
				if (IsKnownDashboardTab(tab))
				{
					_activeTab = tab;
				}
			}
		}
		catch (Exception projectError)
		{
			ProjectData.SetProjectError(projectError);
			ProjectData.ClearProjectError();
		}
	}

	private static bool IsKnownDashboardTab(string tab)
	{
		switch (Normalize(tab))
		{
		case "families":
		case "systems":
		case "requests":
		case "audit":
		case "unregisteredfamilies":
		case "unregisteredsystems":
		case "permissions":
		case "admin":
		case "help":
		case "settings":
			return true;
		default:
			return false;
		}
	}

	private static string NormalizeDashboardTabName(string tab)
	{
		string normalized = Normalize(tab);
		if (IsKnownDashboardTab(normalized))
		{
			return normalized;
		}
		return "families";
	}

	private string DashboardPaneDisplayStyle(string tabName)
	{
		if (!string.Equals(NormalizeDashboardTabName(_activeTab), NormalizeDashboardTabName(tabName), StringComparison.Ordinal))
		{
			return "display:none";
		}
		return "display:block";
	}

	private static string DashboardTabHref(string tabName)
	{
		return "kkyfb:tab/" + Uri.EscapeDataString(NormalizeDashboardTabName(tabName));
	}

	private static string NavClassForTab(string currentTab, string tabName, string baseClass = "tool")
	{
		return baseClass + (string.Equals(NormalizeDashboardTabName(currentTab), NormalizeDashboardTabName(tabName), StringComparison.Ordinal) ? " primary" : string.Empty);
	}

	private static string CenterTabClassForTab(string currentTab, string tabName)
	{
		return NavClassForTab(currentTab, tabName, "tab");
	}

	private string DashboardTabLabel(string tabName)
	{
		return NormalizeDashboardTabName(tabName) switch
		{
			"families" => T("Family Load", "패밀리 로드"), 
			"systems" => T("System Type Load", "시스템 타입 로드"), 
			"requests" => T("Request Addition", "추가 요청"), 
			"audit" => T("Current Model Check", "현재 모델 검사"), 
			"unregisteredfamilies" => T("Unregistered Families", "미등록 패밀리"), 
			"unregisteredsystems" => T("Unregistered Types", "미등록 타입"), 
			"permissions" => T("Permission / Admin", "권한/관리"), 
			"admin" => T("Admin Settings", "관리자 설정"), 
			"help" => T("Help", "도움말"), 
			"settings" => T("Settings", "설정"), 
			_ => T("Family Load", "패밀리 로드"), 
		};
