	private string ResolveInitialDashboardTab(bool showAdminUi, bool canViewAdmin)
	{
		string tab = (_activeTab ?? string.Empty).Trim();
		if (!IsKnownDashboardTab(tab))
		{
			return "families";
		}
		if (string.Equals(Normalize(tab), "admin", StringComparison.Ordinal) && !canViewAdmin)
		{
			return "settings";
		}
		if (!showAdminUi)
		{
			switch (Normalize(tab))
			{
			case "audit":
			case "unregisteredfamilies":
			case "unregisteredsystems":
			case "permissions":
			case "admin":
			case "help":
				return "families";
			}
		}
		return tab;
	}

	private void BrowserDocumentCompleted(object sender, WebBrowserDocumentCompletedEventArgs e)
	{
		try
		{
			if ((object)_browser.Document != null && (object)_browser.Document.Body != null)
			{
				_browser.Document.Body.Style = _browser.Document.Body.Style + ";width:100%;height:100%;";
				TryInvokeDashboardScript("fbLog", "HOST document-completed");
				if (_longOperationActive)
				{
					PaintLongOperationProgress(forcePaint: true);
				}
			}
			if (_startupBrowserRenderPending)
			{
				_startupBrowserRenderPending = false;
				UpdateStartupOverlayProgress(100, 100, T("Dashboard render completed.", "대시보드 렌더가 완료되었습니다."), forcePaint: true);
			}
			DismissStartupOverlayIfDashboardReady();
			WriteDashboardRuntimeDiagnostic("document-completed", -1, -1L);
		}
		catch (Exception projectError)
		{
			ProjectData.SetProjectError(projectError);
			ProjectData.ClearProjectError();
		}
	}

	private void BrowserProgressChanged(object sender, WebBrowserProgressChangedEventArgs e)
	{
		if (!_startupBrowserRenderPending || !IsStartupOverlayVisible())
		{
			return;
		}
		try
		{
			int percent;
			if (e.MaximumProgress > 0 && e.CurrentProgress >= 0)
			{
				double ratio = Math.Max(0.0, Math.Min(1.0, (double)e.CurrentProgress / (double)e.MaximumProgress));
				percent = checked(96 + (int)Math.Round(ratio * 2.0));
			}
			else
			{
				percent = 97;
			}
			percent = Math.Max(96, Math.Min(98, percent));
			UpdateStartupOverlayProgress(percent, 100, T("Rendering dashboard in browser...", "브라우저에서 대시보드를 렌더링하는 중..."));
		}
		catch (Exception projectError)
		{
			ProjectData.SetProjectError(projectError);
			ProjectData.ClearProjectError();
		}
	}

