	private void ToggleDebugConsoleFromHost(string source)
	{
		WriteDashboardRuntimeDiagnostic("host-debug-toggle:" + (source ?? "unknown"), -1, -1L);
		try
		{
			if (TryInvokeDashboardScript("toggleDebug"))
			{
				TryInvokeDashboardScript("fbLog", "HOST F12 via " + (source ?? "unknown"));
			}
			else
			{
				ShowDashboardMessage(this, T("The dashboard debug console is not ready yet. Reopen Family Browser or wait until the page finishes loading.", "대시보드 디버그 콘솔이 아직 준비되지 않았습니다. Family Browser를 다시 열거나 화면 로딩이 끝난 뒤 다시 눌러주세요."), T("KKY Family Browser Debug", "KKY 패밀리 브라우저 디버그"), MessageBoxButtons.OK, MessageBoxIcon.Asterisk);
			}
		}
		catch (Exception ex)
		{
			ProjectData.SetProjectError(ex);
			Exception ex2 = ex;
			ShowDashboardMessage(this, T("Failed to open the dashboard debug console.", "대시보드 디버그 콘솔을 열지 못했습니다.") + Environment.NewLine + ex2.Message, T("KKY Family Browser Debug", "KKY 패밀리 브라우저 디버그"), MessageBoxButtons.OK, MessageBoxIcon.Exclamation);
			ProjectData.ClearProjectError();
		}
	}

	private bool TryInvokeDashboardScript(string scriptName, params object[] args)
	{
		bool TryInvokeDashboardScript;
		try
		{
			if (_browser == null || (object)_browser.Document == null)
			{
				TryInvokeDashboardScript = false;
			}
			else
			{
				_browser.Document.InvokeScript(scriptName, args);
				TryInvokeDashboardScript = true;
			}
		}
		catch (Exception projectError)
		{
			ProjectData.SetProjectError(projectError);
			TryInvokeDashboardScript = false;
			ProjectData.ClearProjectError();
		}
		return TryInvokeDashboardScript;
	}

	internal void ExecuteDashboardActionFromExternalEvent(string action)
	{
		RunDashboardAction(action);
	}

	internal void BringModelessWindowToFront()
	{
		try
		{
			if (base.WindowState == FormWindowState.Minimized)
			{
				base.WindowState = FormWindowState.Normal;
			}
			Show();
			Activate();
			BringToFront();
			QueueLightDashboardRefresh("bring-to-front");
		}
		catch (Exception ex)
		{
			ProjectData.SetProjectError(ex);
			Exception ex2 = ex;
			ShowLoggedError("Open Family Browser", ex2);
			ProjectData.ClearProjectError();
		}
	}

	private void QueueLightDashboardRefresh(string reason)
	{
		if (base.IsDisposed || _deferredLightRefreshPending)
		{
			return;
		}
		_deferredLightRefreshPending = true;
		BeginInvoke((Action)([SpecialName] () =>
		{
			try
			{
				if (!base.IsDisposed)
				{
					WriteDashboardRuntimeDiagnostic("deferred-shell-refresh:" + (reason ?? "unknown"), -1, -1L);
					RefreshDocumentShellOnly();
				}
			}
			catch (Exception ex)
			{
				ProjectData.SetProjectError(ex);
				Exception ex2 = ex;
				ShowLoggedError(T("Family Browser Refresh", "패밀리 브라우저 새로고침"), ex2);
				ProjectData.ClearProjectError();
			}
			finally
			{
				_deferredLightRefreshPending = false;
			}
		}));
	}

	internal void ShowDashboardActionException(string caption, Exception ex)
	{
		ShowLoggedError(caption, ex);
	}

	private void DispatchOrRunDashboardAction(string action)
	{
		if (IsDashboardUiOnlyAction(action))
		{
			RunDashboardAction(action);
		}
		else if (_modelessActionDispatcher == null)
		{
			RunDashboardAction(action);
		}
		else if (!_modelessActionDispatcher(action))
		{
			_statusMessage = T("Family Browser is already running another Revit command. Try again after it finishes.", "Family Browser가 다른 Revit 명령을 실행 중입니다. 완료 후 다시 실행하세요.");
			RenderDashboard();
		}
	}

	private static bool IsDashboardUiOnlyAction(string action)
	{
		string actionKey = (action ?? string.Empty).Trim();
		if (actionKey.StartsWith("tab/", StringComparison.OrdinalIgnoreCase))
		{
			return true;
		}
		if (actionKey.StartsWith("browse-discipline-", StringComparison.OrdinalIgnoreCase) || actionKey.StartsWith("discipline-", StringComparison.OrdinalIgnoreCase) || actionKey.StartsWith("request-status/", StringComparison.OrdinalIgnoreCase) || actionKey.StartsWith("request-delete/", StringComparison.OrdinalIgnoreCase) || actionKey.StartsWith("request-attachments/", StringComparison.OrdinalIgnoreCase) || actionKey.StartsWith("preview-inline/", StringComparison.OrdinalIgnoreCase))
		{
			return true;
		}
		switch (actionKey.ToLowerInvariant())
		{
		case "debug-log":
		case "lang-ko":
		case "lang-en":
		case "admin-mode-on":
		case "admin-mode-off":
		case "homepage-security-refresh":
		case "open-standard-registration":
		case "standard-rvt-manager":
		case "standard-rvt-manager-close":
		case "mode-separated":
		case "mode-integrated":
		case "request-new":
		case "request-refresh":
		case "request-family":
		case "request-system":
		case "request-update":
		case "request-store-local":
		case "request-store-network":
		case "request-store-sharepoint":
		case "request-store-cloud":
		case "request-store-api":
		case "standard-discipline-add":
		case "standard-discipline-rename":
		case "standard-discipline-delete":
		case "standard-list-template":
		case "standard-list-export-rvt":
		case "standard-list-clear":
		case "standard-fingerprint-audit":
		case "deployment-refresh":
		case "deployment-profile":
		case "deployment-url":
		case "open-managed-root":
		case "open-requests":
		case "output":
		case "security-admins":
		case "security-admin-profile-keywords":
		case "security-approvers":
		case "security-readonly":
		case "permission-excel":
		case "permission-excel-clear":
		case "permission-excel-template":
		case "permission-excel-rvt-folder":
		case "permission-check":
		case "file-guard-config":
		case "file-guard-export":
		case "file-guard-clear":
		case "project-rule-current":
		case "project-rules-clear":
		case "settings-reset-all":
		case "temporary-register":
		case "team-shared-test":
		case "policy-managed":
		case "policy-local":
			return true;
		default:
			return false;
		}
	}

	private void RunDashboardAction(string action)
	{
		string actionKey = (action ?? string.Empty).Trim().ToLowerInvariant();
		if (actionKey.StartsWith("tab/", StringComparison.OrdinalIgnoreCase))
		{
			ShowDashboardTabFromAction(action.Substring("tab/".Length));
			return;
		}
		if (actionKey.StartsWith("sync-family/", StringComparison.OrdinalIgnoreCase))
		{
			ApplySelectedStandardFamilyFromAction(action.Substring("sync-family/".Length));
			return;
		}
		if (actionKey.StartsWith("sync-families-selected/", StringComparison.OrdinalIgnoreCase))
		{
			ApplySelectedStandardFamiliesFromAction(action.Substring("sync-families-selected/".Length));
			return;
		}
		if (actionKey.StartsWith("sync-system/", StringComparison.OrdinalIgnoreCase))
		{
			ApplySelectedStandardSystemTypeFromAction(action.Substring("sync-system/".Length));
			return;
		}
		if (actionKey.StartsWith("sync-systems-selected/", StringComparison.OrdinalIgnoreCase))
		{
			ApplySelectedStandardSystemTypesFromAction(action.Substring("sync-systems-selected/".Length));
			return;
		}
		if (actionKey.StartsWith("browse-discipline-", StringComparison.OrdinalIgnoreCase))
		{
			SetBrowseDiscipline(action.Substring("browse-discipline-".Length));
			return;
		}
		if (actionKey.StartsWith("refresh-target/", StringComparison.OrdinalIgnoreCase))
		{
			RunCurrentModelCheckForTarget(action.Substring("refresh-target/".Length));
			return;
		}
		if (actionKey.StartsWith("preflight-target/", StringComparison.OrdinalIgnoreCase))
		{
			RunSystemPreflightForTarget(action.Substring("preflight-target/".Length));
			return;
		}
		if (actionKey.StartsWith("sync-families-target/", StringComparison.OrdinalIgnoreCase))
		{
			ApplyExistingStandardFamiliesForTarget(action.Substring("sync-families-target/".Length));
			return;
		}
		if (actionKey.StartsWith("discipline-", StringComparison.OrdinalIgnoreCase))
		{
			SetActiveDiscipline(action.Substring("discipline-".Length));
			return;
		}
		if (actionKey.StartsWith("request-status/", StringComparison.OrdinalIgnoreCase))
		{
			UpdateRequestStatusFromAction(action);
			return;
		}
		if (actionKey.StartsWith("request-delete/", StringComparison.OrdinalIgnoreCase))
		{
			DeleteRequestFromAction(action);
			return;
		}
		if (actionKey.StartsWith("request-attachments/", StringComparison.OrdinalIgnoreCase))
		{
			OpenRequestAttachmentFolderFromAction(action);
			return;
		}
		if (actionKey.StartsWith("preview-inline/", StringComparison.OrdinalIgnoreCase))
		{
			InlinePreviewImageFromAction(action.Substring("preview-inline/".Length));
			return;
		}
		switch (actionKey)
		{
		case "refresh":
			RefreshDashboard(deepProjectScan: true);
			break;
		case "open-standard-registration":
			OpenStandardRegistrationSetup();
			break;
		case "register":
			RegisterStandardRvt();
			break;
		case "standard-rvt-manager":
			ShowStandardRvtManager();
			break;
		case "standard-rvt-manager-close":
			CloseStandardRvtManagerWindow();
			_showStandardRvtManagerPanel = false;
			_statusMessage = T("Standard RVT manager window closed.", "표준 RVT 관리 창을 닫았습니다.");
			SetDashboardElementText("dashboardStatusBar", _statusMessage);
			break;
		case "standard-rvt-fast-check":
			CheckStandardRvtChangesAndMaybeFastScan();
			break;
		case "standard-rvt-selected-precise":
			RefreshSelectedStandardFamiliesPrecise();
			break;
		case "standard-rvt-full-precise":
			RefreshRegisteredStandardRvt("Precise");
			break;
		case "standard-rvt-selected-images":
			UpdateSelectedStandardImages();
			break;
		case "register-precise":
			RefreshRegisteredStandardRvt("Precise");
			break;
		case "standard-rvt-reset":
			ResetRegisteredStandardRvt();
			break;
		case "settings-reset-all":
			ResetAllFamilyBrowserSettings();
			break;
		case "temporary-register":
			HandleRemovedManualManagedFolderAction();
			break;
		case "mode-separated":
			SetStandardMode("DisciplineSeparated");
			break;
		case "mode-integrated":
			SetStandardMode("Integrated");
			break;
		case "images":
			UpdateStandardImages();
			break;
		case "sync-families":
			ApplyStandardFamilies();
			break;
		case "stamp":
			StampCurrentProjectTracking();
			break;
		case "tracking":
			CheckTracking();
			break;
		case "preflight":
			RunSystemPreflight();
			break;
		case "apply-systems":
			ApplyStandardSystemTypes(null, null, null, _browseDisciplineKey);
			break;
		case "request-new":
			CreateRequestDraft("GENERAL");
			break;
		case "request-refresh":
			RefreshRequestsAndAudit();
			RenderDashboard();
			break;
		case "request-family":
			CreateRequestDraft("FAMILY");
			break;
		case "request-system":
