		case "deployment-refresh":
			RefreshDeploymentBootstrap();
			break;
		case "homepage-security-refresh":
			RefreshHomepageSecurityPolicy();
			break;
		case "deployment-profile":
			ConfigureDeploymentBootstrapProfile();
