			SetAdminMode(enabled: false);
			break;
		default:
			_statusMessage = T("Unknown action: ", "알 수 없는 동작: ") + action;
			RenderDashboard();
			break;
		}
	}

	private void ShowDashboardTabFromAction(string tabToken)
	{
		string tab = NormalizeDashboardTabName(Uri.UnescapeDataString(tabToken ?? string.Empty));
		if (string.Equals(tab, "admin", StringComparison.Ordinal) && !CanViewAdminTab())
		{
			tab = "settings";
		}
		if (!_adminModeEnabled)
		{
			switch (tab)
			{
			case "audit":
			case "unregisteredfamilies":
			case "unregisteredsystems":
			case "permissions":
			case "admin":
			case "help":
				tab = "families";
				break;
			}
		}
		_activeTab = tab;
		_statusMessage = T("Screen switched: ", "화면 전환: ") + DashboardTabLabel(tab);
		if (_adminModeEnabled && IsUnregisteredDashboardTab(tab))
		{
			WriteDashboardRuntimeDiagnostic("host-tab-unregistered-render-only:" + tab, -1, -1L);
			RenderDashboard(preserveCurrentBrowserTab: false);
			return;
		}
		if (string.Equals(tab, "requests", StringComparison.Ordinal))
		{
			WriteDashboardRuntimeDiagnostic("host-tab-request-list-deferred", -1, -1L);
			if (!_requestRecordsLoaded)
			{
				try
				{
					WriteDashboardRuntimeDiagnostic("host-tab-request-list-load", -1, -1L);
					RefreshRequestsAndAudit(forceLoadRequests: true);
					_statusMessage = T("Request list loaded.", "요청 목록을 불러왔습니다.");
				}
				catch (Exception ex)
				{
					ProjectData.SetProjectError(ex);
					Exception ex2 = ex;
					_requestItems = new List<string>
					{
						T("Request list could not be loaded.", "요청 목록을 불러오지 못했습니다."),
						ex2.Message
					};
					_requestRecords = new List<FamilyBrowserRequestRecord>();
					_requestRecordsLoaded = false;
					_statusMessage = T("Request list load failed. Admin log was saved for review.", "요청 목록 로드에 실패했습니다. 관리자 검토용 로그를 저장했습니다.");
					WriteErrorLog(T("Request List Refresh", "요청 목록 새로고침"), ex2);
					ProjectData.ClearProjectError();
				}
				RenderDashboard(preserveCurrentBrowserTab: false);
				return;
			}
		}
		WriteDashboardRuntimeDiagnostic("host-tab:" + tab, -1, -1L);
		if (!TrySwitchDashboardTabInPlace(tab))
		{
			RenderDashboard(preserveCurrentBrowserTab: false);
		}
	}

	private void OpenStandardRegistrationSetup()
	{
		try
		{
			if (!CanEnableAdminMode(_standardPolicy = _standardPolicy ?? LoadStandardPolicy()))
			{
				_activeTab = "settings";
				_statusMessage = T("Standard RVT registration requires an administrator. Ask an admin to register the approved standard RVT.", "표준 RVT 등록은 관리자 권한이 필요합니다. 관리자에게 승인된 표준 RVT 등록을 요청하세요.");
				RenderDashboard(preserveCurrentBrowserTab: false);
				return;
			}
			if (!_adminModeEnabled)
			{
				_adminModeEnabled = true;
				SaveAdminModeEnabled();
				FamilyBrowserNativeCommandGuardService.NotifyAdminModeChanged(enabled: true);
			}
			_activeTab = "admin";
			_focusStandardRegistrationOnNextRender = true;
			_statusMessage = T("Open Admin Settings and connect the selected standard RVT.", "관리자 설정에서 선택 표준 RVT를 연결하세요.");
			RenderDashboard(preserveCurrentBrowserTab: false);
		}
		catch (Exception ex)
		{
			ProjectData.SetProjectError(ex);
			Exception ex2 = ex;
			ShowLoggedError(T("Open Standard RVT Registration", "표준 RVT 등록 화면 열기"), ex2);
			ProjectData.ClearProjectError();
		}
	}

	private bool TrySwitchDashboardTabInPlace(string tab)
	{
		bool TrySwitchDashboardTabInPlace;
		try
		{
			if (_browser == null || (object)_browser.Document == null)
			{
				TrySwitchDashboardTabInPlace = false;
			}
			else
			{
				string paneId = DashboardPaneElementId(tab);
				if (string.IsNullOrWhiteSpace(paneId) || (object)_browser.Document.GetElementById(paneId) == null)
				{
					TrySwitchDashboardTabInPlace = false;
				}
				else if (IsBrowserDashboardTab(tab) && ((object)_browser.Document.GetElementById("familiesPane") == null || (object)_browser.Document.GetElementById("systemsPane") == null || (object)_browser.Document.GetElementById("browserSearch") == null || (object)_browser.Document.GetElementById("selectionDetailPanel") == null))
				{
					TrySwitchDashboardTabInPlace = false;
				}
				else
				{
					_browser.Document.InvokeScript("setTab", new object[1] { tab });
					HtmlElement statusBar = _browser.Document.GetElementById("dashboardStatusBar");
					if ((object)statusBar != null)
					{
						statusBar.InnerText = _statusMessage;
					}
					TrySwitchDashboardTabInPlace = true;
				}
			}
		}
		catch (Exception projectError)
		{
			ProjectData.SetProjectError(projectError);
			TrySwitchDashboardTabInPlace = false;
			ProjectData.ClearProjectError();
		}
		return TrySwitchDashboardTabInPlace;
	}

	private static bool IsUnregisteredDashboardTab(string tab)
	{
		if (!string.Equals(tab, "unregisteredfamilies", StringComparison.Ordinal))
		{
			return string.Equals(tab, "unregisteredsystems", StringComparison.Ordinal);
		}
		return true;
	}

	private static bool IsBrowserDashboardTab(string tab)
	{
		if (!string.Equals(tab, "families", StringComparison.Ordinal))
		{
			return string.Equals(tab, "systems", StringComparison.Ordinal);
		}
		return true;
	}

	private static string DashboardPaneElementId(string tab)
	{
		return NormalizeDashboardTabName(tab) switch
		{
			"families" => "familiesPane", 
			"systems" => "systemsPane", 
			"requests" => "requestsPane", 
			"audit" => "auditPane", 
			"unregisteredfamilies" => "unregisteredFamiliesPane", 
			"unregisteredsystems" => "unregisteredSystemsPane", 
			"permissions" => "permissionsPane", 
			"admin" => "adminPane", 
			"help" => "helpPane", 
			"settings" => "settingsPane", 
			_ => string.Empty, 
		};
	}

