	private void AddStandardDisciplineTarget()
	{
		try
		{
			if (EnsurePermission("ManagePolicy", T("Standard Operation", "표준 운영 설정")))
			{
				string displayName = PromptText(T("Add Trade", "공종 추가"), T("Enter the trade name to show in Family Browser.", "패밀리 브라우저에 표시할 공종 이름을 입력하세요."), string.Empty);
				if (string.IsNullOrWhiteSpace(displayName))
				{
					_statusMessage = T("Trade setup was cancelled.", "공종 설정이 취소되었습니다.");
					RenderDashboard();
					return;
				}
				FamilyBrowserStandardPolicy policy = LoadStandardPolicy();
				FamilyBrowserStandardPolicyStore.AddOrUpdateDisciplineSlot(_workspaceRoot, policy, displayName, displayName, Environment.UserName);
				FamilyBrowserStandardPolicyStore.SetActiveDiscipline(_workspaceRoot, policy, displayName, Environment.UserName);
				_standardPolicy = FamilyBrowserStandardPolicyStore.LoadOrCreate(_workspaceRoot, Environment.UserName);
				_statusMessage = T("Trade target added. Connect a standard RVT for this target.", "공종 대상이 추가되었습니다. 이 공종에 사용할 표준 RVT를 연결하세요.");
				RefreshDocumentShellOnly();
			}
		}
		catch (Exception ex)
		{
			ProjectData.SetProjectError(ex);
			Exception ex2 = ex;
			ShowLoggedError("Add Trade", ex2);
			ProjectData.ClearProjectError();
		}
	}

	private void RenameActiveStandardDisciplineTarget()
	{
		try
		{
			if (!EnsurePermission("ManagePolicy", T("Standard Operation", "표준 운영 설정")))
			{
				return;
			}
			FamilyBrowserStandardPolicy policy = LoadStandardPolicy();
			FamilyBrowserStandardLibrarySlot slot = FamilyBrowserStandardPolicyStore.GetEffectiveSlot(policy);
			if (slot == null)
			{
				ShowDashboardMessage(this, T("No active trade target is available.", "활성 공종 대상이 없습니다."), T("Rename Trade", "공종 이름 변경"), MessageBoxButtons.OK, MessageBoxIcon.Asterisk);
				return;
			}
			string currentName = FamilyBrowserStandardPolicyStore.ResolveSlotDisplayName(slot, IsKorean());
			string displayName = PromptText(T("Rename Trade", "공종 이름 변경"), T("Enter the display name for the active trade target.", "현재 선택된 공종 대상의 표시 이름을 입력하세요."), currentName);
			if (string.IsNullOrWhiteSpace(displayName))
			{
				_statusMessage = T("Trade rename was cancelled.", "공종 이름 변경이 취소되었습니다.");
				RenderDashboard();
				return;
			}
			FamilyBrowserStandardPolicyStore.RenameDisciplineSlot(_workspaceRoot, policy, slot.Discipline, displayName, Environment.UserName);
			_standardPolicy = FamilyBrowserStandardPolicyStore.LoadOrCreate(_workspaceRoot, Environment.UserName);
			_statusMessage = T("Trade display name updated.", "공종 표시 이름을 변경했습니다.");
			RefreshDocumentShellOnly();
		}
		catch (Exception ex)
		{
			ProjectData.SetProjectError(ex);
