	private void DeleteActiveStandardDisciplineTarget()
	{
		try
		{
			if (!EnsurePermission("ManagePolicy", T("Standard Operation", "표준 운영 설정")))
			{
				return;
			}
			FamilyBrowserStandardPolicy policy = LoadStandardPolicy();
			if (string.Equals(policy.Mode, "Integrated", StringComparison.OrdinalIgnoreCase))
			{
				ShowDashboardMessage(this, T("Trade targets can be deleted only in separate-by-trade mode.", "공종 대상 삭제는 공종별 표준 모드에서만 사용할 수 있습니다."), T("Delete Trade", "공종 삭제"), MessageBoxButtons.OK, MessageBoxIcon.Asterisk);
				return;
			}
			FamilyBrowserStandardLibrarySlot slot = FamilyBrowserStandardPolicyStore.GetEffectiveSlot(policy);
			if (slot == null)
			{
				ShowDashboardMessage(this, T("No active trade target is available.", "활성 공종 대상이 없습니다."), T("Delete Trade", "공종 삭제"), MessageBoxButtons.OK, MessageBoxIcon.Asterisk);
				return;
			}
			if (FamilyBrowserStandardPolicyStore.GetDisciplineSlots(policy).Count <= 1)
			{
				ShowDashboardMessage(this, T("At least one trade target must remain.", "공종 대상은 최소 1개 이상 남아 있어야 합니다."), T("Delete Trade", "공종 삭제"), MessageBoxButtons.OK, MessageBoxIcon.Asterisk);
				return;
			}
			string displayName = FamilyBrowserStandardPolicyStore.ResolveSlotDisplayName(slot, IsKorean());
			string confirmation = T("Delete the selected trade target?", "선택한 공종 대상을 삭제할까요?") + Environment.NewLine + Environment.NewLine + displayName + Environment.NewLine + Environment.NewLine + T("The add-in will remove this target from the list and clear its standard RVT/list connections. Source files are not deleted.", "목록에서 이 공종을 숨기고 표준 RVT/목록 연결만 해제합니다. 원본 파일은 삭제하지 않습니다.");
			if (ShowDashboardMessage(this, confirmation, T("Delete Trade", "공종 삭제"), MessageBoxButtons.YesNo, MessageBoxIcon.Exclamation, MessageBoxDefaultButton.Button2) != DialogResult.Yes)
			{
				_statusMessage = T("Trade delete was cancelled.", "공종 삭제가 취소되었습니다.");
				RenderDashboard();
				return;
			}
			string removedKey = ResolveSlotKey(slot);
			FamilyBrowserStandardPolicyStore.RemoveDisciplineSlot(_workspaceRoot, policy, slot.Discipline, Environment.UserName);
			_standardPolicy = FamilyBrowserStandardPolicyStore.LoadOrCreate(_workspaceRoot, Environment.UserName);
			if (string.Equals(Normalize(_browseDisciplineKey), Normalize(removedKey), StringComparison.Ordinal))
			{
				_browseDisciplineKey = string.Empty;
				_browseDisciplineAutoSelected = true;
			}
			_statusMessage = T("Trade target deleted. Source files were left untouched.", "공종 대상을 삭제했습니다. 원본 파일은 그대로 유지됩니다.");
			RefreshDocumentShellOnly();
		}
		catch (Exception ex)
		{
			ProjectData.SetProjectError(ex);
			Exception ex2 = ex;
			ShowLoggedError("Delete Trade", ex2);
			ProjectData.ClearProjectError();
		}
	}

	private void ConfigureStandardListExcel()
	{
		try
		{
			if (!EnsurePermission("ManagePolicy", T("Standard List Excel", "표준 목록 Excel")))
			{
				return;
			}
			FamilyBrowserStandardPolicy policy = LoadStandardPolicy();
			FamilyBrowserStandardLibrarySlot slot = FamilyBrowserStandardPolicyStore.GetEffectiveSlot(policy);
			if (slot == null)
			{
				ShowDashboardMessage(this, T("No active standard target is available.", "활성 표준 대상이 없습니다."), T("Standard List Excel", "표준 목록 Excel"), MessageBoxButtons.OK, MessageBoxIcon.Asterisk);
				return;
			}
			string currentPath = slot.StandardListPath ?? string.Empty;
			string selectedPath;
			using (OpenFileDialog dialog = new OpenFileDialog())
			{
				dialog.Title = T("Select standard list Excel file", "표준 목록 Excel 파일 선택");
				dialog.Filter = "Excel or CSV (*.xlsx;*.csv)|*.xlsx;*.csv|Excel Workbook (*.xlsx)|*.xlsx|CSV (*.csv)|*.csv|All files (*.*)|*.*";
				dialog.CheckFileExists = true;
				dialog.Multiselect = false;
				dialog.RestoreDirectory = true;
				if (!string.IsNullOrWhiteSpace(currentPath))
				{
					string expanded = Environment.ExpandEnvironmentVariables(currentPath);
					if (File.Exists(expanded))
					{
						string currentExtension = Path.GetExtension(expanded);
						if (string.Equals(currentExtension, ".xlsx", StringComparison.OrdinalIgnoreCase) || string.Equals(currentExtension, ".csv", StringComparison.OrdinalIgnoreCase))
						{
							dialog.FileName = expanded;
						}
						else
						{
							string currentFolder = Path.GetDirectoryName(expanded);
							if (!string.IsNullOrWhiteSpace(currentFolder) && Directory.Exists(currentFolder))
							{
								dialog.InitialDirectory = currentFolder;
							}
						}
					}
					else
					{
						string currentFolder2 = Path.GetDirectoryName(expanded);
						if (!string.IsNullOrWhiteSpace(currentFolder2) && Directory.Exists(currentFolder2))
						{
							dialog.InitialDirectory = currentFolder2;
						}
					}
				}
				else if (!string.IsNullOrWhiteSpace(slot.StandardRvtPath))
				{
					string standardFolder = Path.GetDirectoryName(slot.StandardRvtPath);
					if (!string.IsNullOrWhiteSpace(standardFolder) && Directory.Exists(standardFolder))
					{
						dialog.InitialDirectory = standardFolder;
					}
				}
				if (dialog.ShowDialog(this) != DialogResult.OK)
				{
					_statusMessage = T("Standard list Excel setup was cancelled.", "표준 목록 Excel 설정이 취소되었습니다.");
					RenderDashboard();
					return;
				}
				selectedPath = dialog.FileName;
			}
			string sheetName = PromptText(T("Standard List Excel", "표준 목록 Excel"), T("Enter sheet name. Leave blank to use the first worksheet.", "시트명을 입력하세요. 비워두면 첫 번째 시트를 사용합니다."), slot.StandardListSheetName ?? string.Empty);
			if (sheetName == null)
			{
				_statusMessage = T("Standard list Excel setup was cancelled.", "표준 목록 Excel 설정이 취소되었습니다.");
				RenderDashboard();
				return;
			}
			string caption = T("Standard List Excel", "표준 목록 Excel");
			BeginLongOperationProgress(caption, T("Reading the Excel list and creating the shared JSON...", "Excel 목록을 읽고 공유 JSON을 만드는 중..."));
			UpdateLongOperationProgress(caption, 20, 100, T("Parsing approved family list...", "승인 패밀리 목록을 파싱하는 중..."), forcePaint: true);
			StandardLibrarySnapshot baselineSnapshot = null;
			try
			{
				StandardLibraryRegistrationRecord baselineRegistration = TryLoadRegistrationForSlot(policy, slot);
				if (baselineRegistration != null && !string.IsNullOrWhiteSpace(baselineRegistration.LastSnapshotPath))
				{
					baselineSnapshot = LoadStandardSnapshotForDashboard(baselineRegistration.LastSnapshotPath);
				}
			}
			catch (Exception projectError)
			{
				ProjectData.SetProjectError(projectError);
				baselineSnapshot = null;
				ProjectData.ClearProjectError();
			}
			FamilyBrowserStandardListMaterializeResult jsonList = FamilyBrowserStandardListService.MaterializeJsonFromExcel(selectedPath, (sheetName ?? string.Empty).Trim(), _workspaceRoot, slot, Environment.UserName, baselineSnapshot, ResolveSlotKey(slot), ResolveSlotLabel(slot));
			UpdateLongOperationProgress(caption, 65, 100, T("Connecting the JSON list to the selected trade...", "생성된 JSON 목록을 선택 공종에 연결하는 중..."), forcePaint: true);
			string slotKey = ResolveSlotKey(slot);
			FamilyBrowserStandardPolicyStore.SetStandardListForSlot(_workspaceRoot, policy, slotKey, jsonList.OutputPath, string.Empty, Environment.UserName);
			_standardPolicy = FamilyBrowserStandardPolicyStore.LoadOrCreate(_workspaceRoot, Environment.UserName);
			UpdateLongOperationProgress(caption, 80, 100, T("Saving the standard list index...", "표준 목록 인덱스를 저장하는 중..."), forcePaint: true);
			FamilyBrowserStandardListIndexResult indexResult = FamilyBrowserStandardListService.SaveStandardListIndex(_workspaceRoot, _standardPolicy, Environment.UserName);
			ResolvePolicySlot(_standardPolicy, slotKey);
			ClearStandardListDashboardCaches();
			ClearModelerAllSlotsCache();
			_statusMessage = T("Standard list JSON created and connected: ", "표준 목록 JSON 생성 및 연결 완료: ") + jsonList.OutputPath + T(" / rows: ", " / 행: ") + jsonList.RowCount.ToString(CultureInfo.InvariantCulture) + T(" / source: ", " / 원본: ") + selectedPath + T(" / index: ", " / 인덱스: ") + indexResult.OutputPath;
			UpdateLongOperationProgress(caption, 94, 100, T("Rebuilding the browser list from cached standard data...", "캐시된 표준 데이터로 브라우저 목록을 재구성하는 중..."), forcePaint: true);
			RefreshDocumentShellOnly(caption, 94);
			CompleteLongOperationProgress(T("Standard list Excel connected.", "표준 목록 Excel 연결 완료."));
			ShowDashboardMessage(this, T("Standard list Excel connection completed.", "표준 목록 Excel 연결이 완료되었습니다.") + Environment.NewLine + Environment.NewLine + T("Target: ", "대상: ") + ResolveSlotLabel(slot) + Environment.NewLine + T("Rows: ", "행: ") + jsonList.RowCount.ToString(CultureInfo.InvariantCulture) + Environment.NewLine + T("Sheet: ", "시트: ") + (string.IsNullOrWhiteSpace(jsonList.SheetName) ? T("First worksheet", "첫 번째 시트") : jsonList.SheetName) + Environment.NewLine + T("Source: ", "원본: ") + jsonList.SourcePath + Environment.NewLine + T("Created JSON: ", "생성 JSON: ") + jsonList.OutputPath + Environment.NewLine + T("Index: ", "인덱스: ") + indexResult.OutputPath + Environment.NewLine + T("Indexed targets: ", "인덱스 대상 수: ") + indexResult.ItemCount.ToString(CultureInfo.InvariantCulture), T("Standard List Excel", "표준 목록 Excel"), MessageBoxButtons.OK, (jsonList.RowCount > 0) ? MessageBoxIcon.Asterisk : MessageBoxIcon.Exclamation);
		}
		catch (Exception ex)
		{
			ProjectData.SetProjectError(ex);
			Exception ex2 = ex;
			if (_longOperationActive)
			{
				CompleteLongOperationProgress(T("Standard list Excel setup failed.", "표준 목록 Excel 설정에 실패했습니다."));
			}
			ShowLoggedError("Standard List Excel", ex2);
			ProjectData.ClearProjectError();
		}
	}

	private StandardLibraryPartialRefreshResult TryRefreshStandardListNestedMetadataIfNeeded(FamilyBrowserStandardPolicy policy, FamilyBrowserStandardLibrarySlot slot, string caption)
	{
		StandardLibraryPartialRefreshResult TryRefreshStandardListNestedMetadataIfNeeded;
		if (policy == null || slot == null)
		{
			TryRefreshStandardListNestedMetadataIfNeeded = null;
		}
		else
		{
			try
			{
				StandardLibraryRegistrationRecord registration = TryLoadRegistrationForSlot(policy, slot);
				if (registration == null || string.IsNullOrWhiteSpace(registration.LastSnapshotPath))
				{
					TryRefreshStandardListNestedMetadataIfNeeded = null;
				}
				else
				{
					StandardLibrarySnapshot snapshot = LoadStandardSnapshotForDashboard(registration.LastSnapshotPath);
					if (snapshot == null || snapshot.LoadableFamilies == null || snapshot.LoadableFamilies.Count == 0)
					{
						TryRefreshStandardListNestedMetadataIfNeeded = null;
					}
					else
					{
						string disciplineKey = ResolveSlotKey(slot);
						string disciplineLabel = ResolveSlotLabel(slot);
						FamilyBrowserStandardListCatalog catalog = FamilyBrowserStandardListService.LoadForSlot(slot, registration);
						if (!FamilyBrowserStandardListService.IsFilteringEnabled(catalog))
						{
							TryRefreshStandardListNestedMetadataIfNeeded = null;
						}
						else
						{
							ISet<string> candidateNames = BuildStandardListLoadableFamilyNameSet(catalog, disciplineKey, disciplineLabel);
							if (candidateNames.Count == 0)
							{
								TryRefreshStandardListNestedMetadataIfNeeded = null;
							}
							else
							{
								HashSet<string> namesToRefresh = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
								using (IEnumerator<string> enumerator = candidateNames.GetEnumerator())
								{
									_Closure_0024__181_002D0 closure_0024__181_002D = default(_Closure_0024__181_002D0);
									while (enumerator.MoveNext())
									{
										closure_0024__181_002D = new _Closure_0024__181_002D0(closure_0024__181_002D);
										closure_0024__181_002D._0024VB_0024Local_familyName = enumerator.Current;
										StandardLoadableFamilySnapshotItem item = snapshot.LoadableFamilies.FirstOrDefault(closure_0024__181_002D._Lambda_0024__0);
										if (item != null && RequiresNestedMetadataRefresh(item))
										{
											namesToRefresh.Add(item.FamilyName);
										}
									}
								}
								if (namesToRefresh.Count == 0)
								{
									TryRefreshStandardListNestedMetadataIfNeeded = null;
								}
								else
								{
									WriteDashboardRuntimeDiagnostic("standard-list-nested-metadata-refresh-skip:auto-disabled count=" + namesToRefresh.Count.ToString(CultureInfo.InvariantCulture), -1, -1L);
									TryRefreshStandardListNestedMetadataIfNeeded = null;
								}
							}
						}
					}
				}
			}
			catch (Exception ex)
			{
				ProjectData.SetProjectError(ex);
				Exception ex2 = ex;
				WriteDashboardRuntimeDiagnostic("standard-list-nested-metadata-refresh-skipped:" + ex2.Message, -1, -1L);
				TryRefreshStandardListNestedMetadataIfNeeded = null;
				ProjectData.ClearProjectError();
			}
		}
		return TryRefreshStandardListNestedMetadataIfNeeded;
	}

	private static bool RequiresNestedMetadataRefresh(StandardLoadableFamilySnapshotItem item)
	{
		if (item == null)
		{
			return false;
		}
		if (string.Equals(item.MetadataMode, "Precise", StringComparison.OrdinalIgnoreCase))
		{
			return false;
		}
		if (!string.IsNullOrWhiteSpace(item.MetadataMode) && item.MetadataMode.IndexOf("Nested", StringComparison.OrdinalIgnoreCase) >= 0)
		{
			return false;
		}
		return item.NestedLoadableFamilies == null || item.NestedLoadableFamilies.Count == 0;
	}

	private static ISet<string> BuildStandardListLoadableFamilyNameSet(FamilyBrowserStandardListCatalog catalog, string disciplineKey, string disciplineLabel)
	{
		_Closure_0024__183_002D0 arg = default(_Closure_0024__183_002D0);
		_Closure_0024__183_002D0 CS_0024_003C_003E8__locals6 = new _Closure_0024__183_002D0(arg);
		CS_0024_003C_003E8__locals6._0024VB_0024Local_disciplineKey = disciplineKey;
		CS_0024_003C_003E8__locals6._0024VB_0024Local_disciplineLabel = disciplineLabel;
		HashSet<string> result = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
		if (!FamilyBrowserStandardListService.IsFilteringEnabled(catalog))
		{
			return result;
		}
		bool hasDisciplineSpecificRows = catalog.Entries.Any([SpecialName] (FamilyBrowserStandardListEntry familyBrowserStandardListEntry) => StandardListDisciplineMatches((familyBrowserStandardListEntry == null) ? string.Empty : familyBrowserStandardListEntry.Discipline, CS_0024_003C_003E8__locals6._0024VB_0024Local_disciplineKey, CS_0024_003C_003E8__locals6._0024VB_0024Local_disciplineLabel));
		foreach (FamilyBrowserStandardListEntry entry in catalog.Entries)
		{
			if (entry != null && !string.IsNullOrWhiteSpace(entry.Family) && StandardListEntryAppliesToDiscipline(entry, CS_0024_003C_003E8__locals6._0024VB_0024Local_disciplineKey, CS_0024_003C_003E8__locals6._0024VB_0024Local_disciplineLabel, hasDisciplineSpecificRows))
			{
				result.Add(entry.Family.Trim());
			}
		}
		return result;
	}

	private void ClearStandardListExcel()
	{
		try
		{
			if (EnsurePermission("ManagePolicy", T("Standard List Excel", "표준 목록 Excel")) && ShowDashboardMessage(this, T("Disconnect the standard list Excel for the active target?", "활성 대상의 표준 목록 Excel 연결을 해제할까요?"), T("Standard List Excel", "표준 목록 Excel"), MessageBoxButtons.YesNo, MessageBoxIcon.Question) == DialogResult.Yes)
			{
				FamilyBrowserStandardPolicy policy = LoadStandardPolicy();
				FamilyBrowserStandardLibrarySlot slot = FamilyBrowserStandardPolicyStore.GetEffectiveSlot(policy);
				if (slot != null)
				{
					FamilyBrowserStandardPolicyStore.SetStandardListForSlot(_workspaceRoot, policy, ResolveSlotKey(slot), string.Empty, string.Empty, Environment.UserName);
					_standardPolicy = FamilyBrowserStandardPolicyStore.LoadOrCreate(_workspaceRoot, Environment.UserName);
					FamilyBrowserStandardListService.SaveStandardListIndex(_workspaceRoot, _standardPolicy, Environment.UserName);
					ClearDashboardDataCaches();
					ClearModelerAllSlotsCache();
				}
				_standardPolicy = FamilyBrowserStandardPolicyStore.LoadOrCreate(_workspaceRoot, Environment.UserName);
				_statusMessage = T("Standard list Excel disconnected.", "표준 목록 Excel 연결을 해제했습니다.");
				RefreshDocumentShellOnly();
			}
		}
		catch (Exception ex)
		{
			ProjectData.SetProjectError(ex);
			Exception ex2 = ex;
			ShowLoggedError("Standard List Excel", ex2);
			ProjectData.ClearProjectError();
		}
	}

