	private void SaveStandardListExcelFromRegisteredStandard()
	{
		try
		{
			if (!EnsurePermission("ManagePolicy", T("Standard List Excel", "표준 목록 Excel")))
			{
				return;
			}
			StandardLibraryRegistrationRecord registration = LoadRegistrationOrWarn(T("Standard List Excel", "표준 목록 Excel"));
			if (registration == null)
			{
				return;
			}
			StandardLibrarySnapshot snapshot = LoadStandardSnapshotForDashboard(registration.LastSnapshotPath);
			string sourceName = ((!string.IsNullOrWhiteSpace(registration.ResolvedPath)) ? Path.GetFileNameWithoutExtension(registration.ResolvedPath) : (string.IsNullOrWhiteSpace(registration.DisplayName) ? "StandardRVT" : registration.DisplayName));
			string defaultName = "KKY_FamilyBrowser_StandardList_" + SafeFileToken(BuildPolicyTargetLabel()) + "_" + SafeFileToken(sourceName) + ".xlsx";
			using (SaveFileDialog dialog = new SaveFileDialog())
			{
				dialog.Title = T("Save standard list from registered RVT", "등록 표준 RVT 목록 저장");
				dialog.Filter = "Excel Workbook (*.xlsx)|*.xlsx";
				dialog.DefaultExt = "xlsx";
				dialog.FileName = defaultName;
				dialog.OverwritePrompt = true;
				dialog.RestoreDirectory = true;
				string standardFolder = Path.GetDirectoryName(registration.ResolvedPath ?? string.Empty);
				ConfigureExplorerSaveDialog(dialog, standardFolder);
				if (dialog.ShowDialog(this) != DialogResult.OK)
				{
					_statusMessage = T("Standard RVT list export was cancelled.", "표준 RVT 목록 저장이 취소되었습니다.");
					RenderDashboard();
					return;
				}
				FamilyBrowserStandardLibrarySlot slot = FamilyBrowserStandardPolicyStore.GetEffectiveSlot(LoadStandardPolicy());
				FamilyBrowserStandardListCatalog catalog = ((slot == null) ? new FamilyBrowserStandardListCatalog() : FamilyBrowserStandardListService.LoadForSlot(slot, registration));
				FamilyBrowserStandardListExcelExportResult result = FamilyBrowserStandardListExcelExportService.SaveFromSnapshot(dialog.FileName, BuildPolicyTargetLabel(), snapshot, catalog, (slot == null) ? string.Empty : ResolveSlotKey(slot), (slot == null) ? string.Empty : ResolveSlotLabel(slot));
				_statusMessage = T("Standard RVT list Excel saved: ", "표준 RVT 목록 Excel 저장 완료: ") + result.OutputPath + T(" / rows: ", " / 행: ") + result.RowCount.ToString(CultureInfo.InvariantCulture);
				ShowSavedExcelMessageAndMaybeOpen(this, T("Standard List Excel", "표준 목록 Excel"), _statusMessage + Environment.NewLine + Environment.NewLine + T("Loadable families are exported at family level. Nested child families are omitted; system types are exported with Family=type class and Type=type name.", "로더블 패밀리는 패밀리 단위로 저장했습니다. 하위 패밀리는 제외했고, 시스템 타입은 Family=타입 클래스 / Type=타입 이름 형식으로 저장했습니다."), result.OutputPath);
			}
			RefreshDocumentShellOnly();
		}
		catch (Exception ex)
		{
			ProjectData.SetProjectError(ex);
			Exception ex2 = ex;
			ShowLoggedError("Standard List RVT Export", ex2);
			ProjectData.ClearProjectError();
		}
	}

	private void ExportUnregisteredFamilies()
	{
		try
		{
			if (!EnsurePermission("ManagePolicy", T("Unregistered Families", "미등록 패밀리")))
			{
				return;
			}
			using (SaveFileDialog dialog = new SaveFileDialog())
			{
				dialog.Title = T("Export unregistered project families", "미등록 프로젝트 패밀리 Excel 추출");
				dialog.Filter = "Excel Workbook (*.xlsx)|*.xlsx";
				dialog.DefaultExt = "xlsx";
				dialog.FileName = "KKY_FamilyBrowser_Unregistered_Families_" + SafeFileToken(CurrentProjectFileName()) + "_" + DateTime.Now.ToString("yyyyMMdd-HHmmss", CultureInfo.InvariantCulture) + ".xlsx";
				dialog.OverwritePrompt = true;
				dialog.RestoreDirectory = true;
				ConfigureExplorerSaveDialog(dialog, FamilyBrowserStandardPolicyStore.GetDataFolder(_workspaceRoot, "Reports"));
				if (dialog.ShowDialog(this) != DialogResult.OK)
				{
					_statusMessage = T("Unregistered family export was cancelled.", "미등록 패밀리 추출이 취소되었습니다.");
					RenderDashboard();
					return;
				}
				List<string> headers = (IsKorean() ? new List<string> { "구분", "카테고리", "패밀리", "출처", "비고" } : new List<string> { "Kind", "Category", "Family", "Source", "Notes" });
				List<List<string>> rows = (from x in _unregisteredFamilyRows.OrderBy([SpecialName] (UnregisteredProjectItemRow x) => Normalize(x.CategoryName), StringComparer.Ordinal).ThenBy([SpecialName] (UnregisteredProjectItemRow x) => Normalize(x.Name), StringComparer.Ordinal)
					select new List<string> { x.ItemKind, x.CategoryName, x.Name, x.Source, x.Notes }).ToList();
				FamilyBrowserStandardListExcelExportResult result = FamilyBrowserStandardListExcelExportService.SaveRows(dialog.FileName, T("UnregisteredFamilies", "미등록패밀리"), headers, rows);
				_statusMessage = T("Unregistered family Excel saved: ", "미등록 패밀리 Excel 저장 완료: ") + result.OutputPath + T(" / rows: ", " / 행: ") + result.RowCount.ToString(CultureInfo.InvariantCulture);
				ShowSavedExcelMessageAndMaybeOpen(this, T("Unregistered Families", "미등록 패밀리"), _statusMessage, result.OutputPath);
			}
			RenderDashboard(preserveCurrentBrowserTab: false);
		}
		catch (Exception ex)
		{
			ProjectData.SetProjectError(ex);
			Exception ex2 = ex;
			ShowLoggedError("Unregistered Family Export", ex2);
			ProjectData.ClearProjectError();
		}
	}

	private void ExportUnregisteredSystemTypes()
	{
		try
		{
			if (!EnsurePermission("ManagePolicy", T("Unregistered Types", "미등록 타입")))
			{
				return;
			}
			using (SaveFileDialog dialog = new SaveFileDialog())
			{
				dialog.Title = T("Export unregistered project system types", "미등록 프로젝트 시스템 타입 Excel 추출");
				dialog.Filter = "Excel Workbook (*.xlsx)|*.xlsx";
				dialog.DefaultExt = "xlsx";
				dialog.FileName = "KKY_FamilyBrowser_Unregistered_SystemTypes_" + SafeFileToken(CurrentProjectFileName()) + "_" + DateTime.Now.ToString("yyyyMMdd-HHmmss", CultureInfo.InvariantCulture) + ".xlsx";
				dialog.OverwritePrompt = true;
				dialog.RestoreDirectory = true;
				ConfigureExplorerSaveDialog(dialog, FamilyBrowserStandardPolicyStore.GetDataFolder(_workspaceRoot, "Reports"));
				if (dialog.ShowDialog(this) != DialogResult.OK)
				{
					_statusMessage = T("Unregistered system type export was cancelled.", "미등록 시스템 타입 추출이 취소되었습니다.");
					RenderDashboard();
					return;
				}
				List<string> headers = (IsKorean() ? new List<string> { "구분", "카테고리", "타입 종류", "타입", "출처", "비고" } : new List<string> { "Kind", "Category", "Type Class", "Type", "Source", "Notes" });
				List<List<string>> rows = (from x in _unregisteredSystemRows.OrderBy([SpecialName] (UnregisteredProjectItemRow x) => Normalize(x.CategoryName), StringComparer.Ordinal).ThenBy([SpecialName] (UnregisteredProjectItemRow x) => Normalize(x.TypeClassName), StringComparer.Ordinal).ThenBy([SpecialName] (UnregisteredProjectItemRow x) => Normalize(x.Name), StringComparer.Ordinal)
					select new List<string> { x.ItemKind, x.CategoryName, x.TypeClassName, x.Name, x.Source, x.Notes }).ToList();
				FamilyBrowserStandardListExcelExportResult result = FamilyBrowserStandardListExcelExportService.SaveRows(dialog.FileName, T("UnregisteredTypes", "미등록타입"), headers, rows);
				_statusMessage = T("Unregistered system type Excel saved: ", "미등록 시스템 타입 Excel 저장 완료: ") + result.OutputPath + T(" / rows: ", " / 행: ") + result.RowCount.ToString(CultureInfo.InvariantCulture);
				ShowSavedExcelMessageAndMaybeOpen(this, T("Unregistered Types", "미등록 타입"), _statusMessage, result.OutputPath);
			}
			RenderDashboard(preserveCurrentBrowserTab: false);
		}
		catch (Exception ex)
		{
			ProjectData.SetProjectError(ex);
			Exception ex2 = ex;
			ShowLoggedError("Unregistered System Type Export", ex2);
			ProjectData.ClearProjectError();
		}
	}

