	private void SetAdminMode(bool enabled)
	{
		if (enabled && !CanEnableAdminMode())
		{
			_adminModeEnabled = false;
			SaveAdminModeEnabled();
			FamilyBrowserNativeCommandGuardService.NotifyAdminModeChanged(enabled: false);
			_statusMessage = T("Admin mode is blocked for the current Autodesk/Revit user.", "현재 Autodesk/Revit 사용자 권한으로는 관리자 모드를 켤 수 없습니다.");
			RenderDashboard();
			ShowDashboardMessage(this, T("Admin Mode can be turned on only by users whose Autodesk/Revit user name matches the admin list or admin keywords.", "관리자 모드는 Autodesk/Revit 사용자명이 관리자 목록 또는 관리자 키워드와 일치하는 사용자만 켤 수 있습니다.") + Environment.NewLine + Environment.NewLine + T("Current user: ", "현재 사용자: ") + CurrentUserIdentity(), T("Admin Mode", "관리자 모드"), MessageBoxButtons.OK, MessageBoxIcon.Exclamation);
		}
		else
		{
			_adminModeEnabled = enabled;
			SaveAdminModeEnabled();
			FamilyBrowserNativeCommandGuardService.NotifyAdminModeChanged(_adminModeEnabled);
			_statusMessage = (enabled ? T("Admin screen mode is on. Management and review menus are visible.", "관리자 화면 모드가 켜졌습니다. 관리/검사 메뉴를 표시합니다.") : T("Admin screen mode is off. Modeler workflow is shown.", "관리자 화면 모드가 꺼졌습니다. 모델러 작업 메뉴만 표시합니다."));
			ClearModelerAllSlotsCache();
			RefreshDocumentShellOnly();
		}
	}

