	private FamilyBrowserStandardPolicy LoadStandardPolicy(int timeoutMilliseconds = 0)
	{
		if (timeoutMilliseconds <= 0)
		{
			return FamilyBrowserStandardPolicyStore.LoadOrCreate(_workspaceRoot, Environment.UserName);
		}
		try
		{
			Task<FamilyBrowserStandardPolicy> loadTask = Task.Factory.StartNew([SpecialName] () => FamilyBrowserStandardPolicyStore.LoadOrCreate(_workspaceRoot, Environment.UserName), CancellationToken.None, TaskCreationOptions.DenyChildAttach, TaskScheduler.Default);
			if (loadTask.Wait(timeoutMilliseconds))
			{
				return loadTask.Result;
			}
			WriteDashboardRuntimeDiagnostic("policy-load-timeout:" + timeoutMilliseconds.ToString(CultureInfo.InvariantCulture) + "ms", -1, -1L);
		}
		catch (Exception ex)
		{
			ProjectData.SetProjectError(ex);
			Exception ex2 = ex;
			WriteDashboardRuntimeDiagnostic("policy-load-fast-failed:" + ex2.Message, -1, -1L);
			ProjectData.ClearProjectError();
		}
		return new FamilyBrowserStandardPolicy();
	}

	private bool EnsureFieldTestRootConfigured(FamilyBrowserDeploymentProjectIdentity projectIdentity = null)
	{
		try
		{
			_deploymentBootstrapResult = FamilyBrowserDeploymentBootstrapService.TryApply(_workspaceRoot, Environment.UserName, force: false, projectIdentity);
			if (_deploymentBootstrapResult != null && _deploymentBootstrapResult.Applied)
			{
				_standardPolicy = LoadStandardPolicy();
				_statusMessage = T("Shared homepage settings applied.", "업데이트 홈페이지 설정을 적용했습니다.");
				return true;
			}
		}
		catch (Exception projectError)
		{
			ProjectData.SetProjectError(projectError);
			ProjectData.ClearProjectError();
		}
		_statusMessage = T("No reachable homepage-managed folder is connected. Open Settings and use Check Homepage Path Again.", "연결 가능한 홈페이지 관리 폴더가 없습니다. 설정에서 홈페이지 경로 다시 확인을 실행하세요.");
		return false;
	}

