	private bool CanEnableAdminMode(FamilyBrowserStandardPolicy policy)
	{
		bool CanEnableAdminMode;
		try
		{
			FamilyBrowserStandardPolicy activePolicy = policy ?? LoadStandardPolicy();
			string user = CurrentUserIdentity();
			FamilyBrowserProjectPolicyContext context = CurrentProjectPolicyContext();
			CanEnableAdminMode = ((!_deferExpensiveStartupLookups) ? (FamilyBrowserSecurityPolicyService.Can(activePolicy, user, "ManagePolicy", context) || FamilyBrowserSecurityPolicyService.Can(activePolicy, user, "RegisterStandard", context)) : (FamilyBrowserSecurityPolicyService.Can(activePolicy, user, "ManagePolicy", context, null) || FamilyBrowserSecurityPolicyService.Can(activePolicy, user, "RegisterStandard", context, null)));
		}
		catch (Exception projectError)
		{
			ProjectData.SetProjectError(projectError);
			CanEnableAdminMode = false;
			ProjectData.ClearProjectError();
		}
		return CanEnableAdminMode;
	}

	private void EnsureAdminModeAllowed(FamilyBrowserStandardPolicy policy)
	{
		if (_adminModeEnabled && !CanEnableAdminMode(policy))
		{
			_adminModeEnabled = false;
			SaveAdminModeEnabled();
			FamilyBrowserNativeCommandGuardService.NotifyAdminModeChanged(enabled: false);
			switch (NormalizeDashboardTabName(_activeTab))
			{
			case "audit":
			case "permissions":
			case "admin":
			case "help":
				_activeTab = "families";
				break;
			}
			_statusMessage = T("Admin mode was turned off because the current Autodesk/Revit user is not an admin.", "현재 Autodesk/Revit 사용자가 관리자가 아니어서 관리자 모드를 껐습니다.");
		}
	}

