				PolicyPath = FamilyBrowserStandardPolicyStore.GetPolicyPath(_workspaceRoot),
				StandardTarget = BuildPolicyTargetLabel(),
				BlockingCount = 1
			};
			_readinessReport.Items.Add(new FamilyBrowserOperationalReadinessItem
			{
				Area = "Readiness",
				Status = "Blocked",
				Message = "Readiness check failed.",
				Action = ex2.Message
			});
