	private string CurrentSecurityRoleLabel(FamilyBrowserStandardPolicy policy)
	{
		return ResolveSecurityRoleLabel(CurrentSecurityRole(policy));
	}

	private void UpdateSecurityContext(FamilyBrowserStandardPolicy policy)
	{
		string currentUser = CurrentUserIdentity();
		FamilyBrowserProjectPolicyContext context = CurrentProjectPolicyContext();
		string role = FamilyBrowserSecurityPolicyService.ResolveRole(policy, currentUser, context, null);
		_userRoleText = ResolveSecurityRoleLabel(role);
		string left = FamilyBrowserPolicyKey.Normalize(role);
		if (Operators.CompareString(left, FamilyBrowserPolicyKey.Normalize("Admin"), TextCompare: false) == 0)
		{
			_permissionText = T("Permission: Admin / apply allowed", "권한: 관리자 / 적용 가능");
			return;
		}
		if (Operators.CompareString(left, FamilyBrowserPolicyKey.Normalize("Approver"), TextCompare: false) == 0)
		{
			_permissionText = T("Permission: Approver / request workflow", "권한: 승인자 / 요청 처리");
			return;
		}
		if (Operators.CompareString(left, FamilyBrowserPolicyKey.Normalize("ReadOnly"), TextCompare: false) == 0)
		{
			_permissionText = T("Permission: Read only / load blocked", "권한: 읽기 전용 / 로드 차단");
			return;
		}
		bool canLoadFamilies = FamilyBrowserSecurityPolicyService.Can(policy, currentUser, "LoadFamilies", context, null);
		bool canApplySystems = FamilyBrowserSecurityPolicyService.Can(policy, currentUser, "ApplySystemTypes", context, null);
		if (canLoadFamilies && canApplySystems)
		{
			_permissionText = T("Permission: Modeler / load & system apply allowed", "권한: 모델러 / 로드·시스템 적용 허용");
		}
		else if (canLoadFamilies)
		{
			_permissionText = T("Permission: Modeler / family load allowed", "권한: 모델러 / 패밀리 로드 허용");
		}
		else if (canApplySystems)
		{
			_permissionText = T("Permission: Modeler / system apply allowed", "권한: 모델러 / 시스템 적용 허용");
		}
		else
		{
			_permissionText = T("Permission: Modeler / load blocked", "권한: 모델러 / 로드 차단");
		}
	}

	private bool HasPermission(string permission)
	{
		FamilyBrowserStandardPolicy policy = _standardPolicy ?? LoadStandardPolicy();
		string currentUser = CurrentUserIdentity();
		FamilyBrowserProjectPolicyContext context = CurrentProjectPolicyContext();
		return FamilyBrowserSecurityPolicyService.Can(policy, currentUser, permission, context, null);
	}

	private DashboardPermissionSnapshot BuildDashboardPermissionSnapshot()
	{
		FamilyBrowserStandardPolicy policy = _standardPolicy ?? LoadStandardPolicy();
		string user = CurrentUserIdentity();
		FamilyBrowserProjectPolicyContext context = CurrentProjectPolicyContext();
		string cacheKey = BuildPermissionDiagnosticCacheKey(policy, user, context);
		if (_deferExpensiveStartupLookups)
		{
			cacheKey += "|startup-policy-only";
		}
		if (string.Equals(_dashboardPermissionCacheKey, cacheKey, StringComparison.Ordinal) && _dashboardPermissionCachedSnapshot != null)
		{
			return _dashboardPermissionCachedSnapshot;
		}
		DashboardPermissionSnapshot snapshot = new DashboardPermissionSnapshot();
		snapshot.CanLoadFamilies = FamilyBrowserSecurityPolicyService.Can(policy, user, "LoadFamilies", context, null);
		snapshot.CanApplySystems = FamilyBrowserSecurityPolicyService.Can(policy, user, "ApplySystemTypes", context, null);
		snapshot.CanCreateRequest = FamilyBrowserSecurityPolicyService.Can(policy, user, "CreateRequest", context, null);
		snapshot.CanSubmitRequest = FamilyBrowserSecurityPolicyService.Can(policy, user, "SubmitRequest", context, null);
		snapshot.CanApproveRequest = FamilyBrowserSecurityPolicyService.Can(policy, user, "ApproveRequest", context, null);
		snapshot.CanViewAdmin = FamilyBrowserSecurityPolicyService.Can(policy, user, "ManagePolicy", context, null) || FamilyBrowserSecurityPolicyService.Can(policy, user, "RegisterStandard", context, null);
		_dashboardPermissionCacheKey = cacheKey;
		_dashboardPermissionCachedSnapshot = snapshot;
		return snapshot;
	}

	private FamilyBrowserPermissionExcelDiagnostic GetCachedPermissionExcelDiagnostic(FamilyBrowserStandardPolicy policy, string currentUser, FamilyBrowserProjectPolicyContext context)
	{
		string cacheKey = BuildPermissionDiagnosticCacheKey(policy, currentUser, context);
		if (string.Equals(_permissionDiagnosticCacheKey, cacheKey, StringComparison.Ordinal) && _permissionDiagnosticCached != null)
		{
			return _permissionDiagnosticCached;
		}
		FamilyBrowserPermissionExcelDiagnostic diagnostic = FamilyBrowserPermissionExcelPolicyService.BuildDiagnostic(policy, currentUser, context);
		_permissionDiagnosticCacheKey = cacheKey;
		_permissionDiagnosticCached = diagnostic;
		_dashboardPermissionCacheKey = string.Empty;
		_dashboardPermissionCachedSnapshot = null;
		return diagnostic;
	}

	private FamilyBrowserPermissionExcelDiagnostic GetPermissionExcelDiagnosticForPane(FamilyBrowserStandardPolicy policy, string currentUser, FamilyBrowserProjectPolicyContext context)
	{
		string cacheKey = BuildPermissionDiagnosticCacheKey(policy, currentUser, context);
		if (string.Equals(_permissionDiagnosticCacheKey, cacheKey, StringComparison.Ordinal) && _permissionDiagnosticCached != null)
		{
			return _permissionDiagnosticCached;
		}
		FamilyBrowserPermissionExcelSettings settings = policy?.PermissionExcel;
		FamilyBrowserPermissionExcelDiagnostic diagnostic = new FamilyBrowserPermissionExcelDiagnostic
		{
			CurrentUser = (currentUser ?? string.Empty),
			ProjectTitle = ((context == null) ? string.Empty : context.ProjectTitle),
			ModelPath = ((context == null) ? string.Empty : context.ModelPath),
			CentralPath = ((context == null) ? string.Empty : context.CentralPath),
			StandardTarget = ((context == null) ? string.Empty : context.StandardTarget),
			Enabled = (settings?.Enabled ?? false),
			SourcePath = ((settings == null) ? string.Empty : settings.Path),
			SheetName = ((settings == null) ? string.Empty : settings.SheetName)
		};
		if (diagnostic.Enabled && !string.IsNullOrWhiteSpace(diagnostic.SourcePath))
		{
			diagnostic.Message = T("Not checked yet. Click Check Current Permission to read the Excel file.", "아직 확인하지 않았습니다. 현재 권한 확인을 누르면 Excel 파일을 읽습니다.");
		}
		else
		{
			diagnostic.Message = T("Excel permission policy is not connected.", "Excel 권한 정책이 연결되지 않았습니다.");
		}
		return diagnostic;
	}

	private static string BuildPermissionDiagnosticCacheKey(FamilyBrowserStandardPolicy policy, string currentUser, FamilyBrowserProjectPolicyContext context)
	{
		FamilyBrowserPermissionExcelSettings permissionExcel = policy?.PermissionExcel;
		List<string> parts = new List<string>
		{
			currentUser ?? string.Empty,
			(policy == null) ? string.Empty : policy.LastUpdatedUtc,
			(permissionExcel == null) ? string.Empty : permissionExcel.LastUpdatedUtc,
			(permissionExcel == null) ? string.Empty : (permissionExcel.Enabled ? "True" : "False"),
			(permissionExcel == null) ? string.Empty : permissionExcel.Path,
			(permissionExcel == null) ? string.Empty : permissionExcel.SheetName,
			(context == null) ? string.Empty : context.ProjectTitle,
			(context == null) ? string.Empty : context.ModelPath,
			(context == null) ? string.Empty : context.CentralPath,
			(context == null) ? string.Empty : context.StandardTarget
		};
		return string.Join("|", parts.Select([SpecialName] (string x) => (x ?? string.Empty).Replace("|", "/")));
	}

	private bool EnsurePermission(string permission, string caption)
	{
		if (HasPermission(permission))
		{
			return true;
		}
		string roleLabel = CurrentSecurityRoleLabel(_standardPolicy ?? LoadStandardPolicy());
		string message = T("This action is blocked by the Family Browser permission policy.", "패밀리 브라우저 권한 정책으로 이 작업이 차단되었습니다.") + Environment.NewLine + Environment.NewLine + T("Current user: ", "현재 사용자: ") + CurrentUserIdentity() + Environment.NewLine + T("Current role: ", "현재 역할: ") + roleLabel + PermissionBlockedUserAction(permission);
		_statusMessage = message.Replace(Environment.NewLine, " ");
		RenderDashboard();
		ShowDashboardMessage(this, message, caption, MessageBoxButtons.OK, MessageBoxIcon.Exclamation);
		return false;
	}

	private string PermissionBlockedUserAction(string permission)
	{
		string left = Normalize(permission);
		if (Operators.CompareString(left, Normalize("LoadFamilies"), TextCompare: false) == 0)
		{
			return Environment.NewLine + Environment.NewLine + T("Use Request Addition, or ask an administrator to load the approved family from the standard RVT.", "추가 요청을 등록하거나, 관리자에게 표준 RVT의 승인 패밀리 로드를 요청하세요.");
		}
		if (Operators.CompareString(left, Normalize("ApplySystemTypes"), TextCompare: false) == 0)
		{
			return Environment.NewLine + Environment.NewLine + T("Use Request Addition, or ask an administrator to apply the approved system type after review.", "추가 요청을 등록하거나, 관리자에게 검토 후 승인 시스템 타입 적용을 요청하세요.");
		}
		if (Operators.CompareString(left, Normalize("EditFamilies"), TextCompare: false) == 0 || Operators.CompareString(left, Normalize("AddDeleteTypes"), TextCompare: false) == 0)
		{
			return Environment.NewLine + Environment.NewLine + T("Modelers cannot load external families, edit families, or add/delete/rename protected types directly.", "모델러는 외부 패밀리 로드, 패밀리 편집, 보호 대상 타입 추가/삭제/이름 변경을 직접 수행할 수 없습니다.");
		}
		return string.Empty;
	}

