	private FamilyBrowserOperationalReadinessReport BuildScopedReadinessReport(FamilyBrowserStandardPolicy policy, IEnumerable<string> requestedAreas)
	{
		FamilyBrowserOperationalReadinessReport report = new FamilyBrowserOperationalReadinessReport
		{
			GeneratedAtUtc = DateTime.UtcNow.ToString("O", CultureInfo.InvariantCulture),
			PolicyPath = FamilyBrowserStandardPolicyStore.GetPolicyPath(_workspaceRoot),
			StandardTarget = BuildPolicyTargetLabel()
		};
		List<string> areaList = new List<string>();
		if (requestedAreas != null)
		{
			areaList.AddRange(requestedAreas.Where([SpecialName] (string x) => !string.IsNullOrWhiteSpace(x)));
		}
		if (areaList.Count == 0)
		{
			areaList.Add("Policy");
		}
		foreach (string area in areaList.Distinct(StringComparer.OrdinalIgnoreCase))
		{
			string left = FamilyBrowserPolicyKey.Normalize(area);
			if (Operators.CompareString(left, FamilyBrowserPolicyKey.Normalize("Policy"), TextCompare: false) == 0)
			{
				AddScopedReadinessItem(report, "Policy", (policy == null) ? "Blocked" : "Ready", (policy == null) ? "Policy could not be loaded." : "Policy is loaded for this action.", string.IsNullOrWhiteSpace(report.PolicyPath) ? "Policy path is empty." : report.PolicyPath);
			}
			else if (Operators.CompareString(left, FamilyBrowserPolicyKey.Normalize("Standard RVT"), TextCompare: false) == 0)
			{
				AddScopedStandardRvtReadiness(report, policy);
			}
			else if (Operators.CompareString(left, FamilyBrowserPolicyKey.Normalize("Snapshot"), TextCompare: false) == 0)
			{
				AddScopedSnapshotReadiness(report, policy);
			}
			else if (Operators.CompareString(left, FamilyBrowserPolicyKey.Normalize("Request Store"), TextCompare: false) == 0)
			{
				AddScopedRequestStoreReadiness(report, policy);
			}
			else
			{
				AddScopedReadinessItem(report, area, "Ready", "Scoped readiness check skipped unrelated area.", "No full readiness scan was run for this action.");
			}
		}
		FinalizeScopedReadiness(report);
		return report;
	}

	private void AddScopedStandardRvtReadiness(FamilyBrowserOperationalReadinessReport report, FamilyBrowserStandardPolicy policy)
	{
		FamilyBrowserStandardLibrarySlot slot = FamilyBrowserStandardPolicyStore.GetEffectiveSlot(policy);
		if (slot == null)
		{
			AddScopedReadinessItem(report, "Standard RVT", "Blocked", "No active standard library slot is available.", "Choose a trade and register a standard RVT.");
			return;
		}
		if (!slot.Enabled)
		{
			AddScopedReadinessItem(report, "Standard RVT", "Blocked", "The active standard library slot is disabled.", "Enable the slot or choose another trade.");
			return;
		}
		StandardLibraryRegistrationRecord registration = TryLoadRegistrationForSlot(policy, slot);
		string standardPath = FirstNonEmptyValue(slot.StandardRvtPath, (registration == null) ? string.Empty : registration.ResolvedPath, (registration == null) ? string.Empty : registration.Locator);
		if (string.IsNullOrWhiteSpace(standardPath))
		{
			AddScopedReadinessItem(report, "Standard RVT", "Blocked", "Standard RVT is not registered for the active target.", "Register the approved standard RVT.");
		}
		else if (File.Exists(standardPath))
		{
			AddScopedReadinessItem(report, "Standard RVT", "Ready", "Standard RVT file exists.", standardPath);
		}
		else
		{
			AddScopedReadinessItem(report, "Standard RVT", "Blocked", "Standard RVT file cannot be found.", standardPath);
		}
	}

	private void AddScopedSnapshotReadiness(FamilyBrowserOperationalReadinessReport report, FamilyBrowserStandardPolicy policy)
	{
		FamilyBrowserStandardLibrarySlot slot = FamilyBrowserStandardPolicyStore.GetEffectiveSlot(policy);
		StandardLibraryRegistrationRecord registration = ((slot == null) ? null : TryLoadRegistrationForSlot(policy, slot));
		string snapshotPath = FamilyBrowserStandardPolicyStore.ResolveSlotSnapshotPath(_workspaceRoot, slot, registration);
		if (string.IsNullOrWhiteSpace(snapshotPath))
		{
			AddScopedReadinessItem(report, "Snapshot", "Blocked", "Standard snapshot is missing.", "Register or refresh the standard RVT to rebuild the snapshot.");
		}
		else if (File.Exists(snapshotPath))
		{
			AddScopedReadinessItem(report, "Snapshot", "Ready", "Standard snapshot exists.", snapshotPath);
		}
		else
		{
			AddScopedReadinessItem(report, "Snapshot", "Blocked", "Saved snapshot file cannot be found.", snapshotPath);
		}
	}

	private void AddScopedRequestStoreReadiness(FamilyBrowserOperationalReadinessReport report, FamilyBrowserStandardPolicy policy)
	{
		FamilyBrowserRequestStoreInfo info = FamilyBrowserRequestStore.GetRequestStoreInfo(_workspaceRoot, policy);
		if (info == null)
		{
			AddScopedReadinessItem(report, "Request Store", "Blocked", "Request store is not configured.", "Set the family request path.");
			return;
		}
		string detail = string.Empty;
		if (FamilyBrowserRequestStoreBackendService.TestWritable(info, ref detail))
		{
			AddScopedReadinessItem(report, "Request Store", "Ready", "Request store is writable.", detail);
		}
		else
		{
			AddScopedReadinessItem(report, "Request Store", "Blocked", "Request store is not writable.", detail);
		}
	}

	private static void AddScopedReadinessItem(FamilyBrowserOperationalReadinessReport report, string area, string status, string message, string action)
	{
		report.Items.Add(new FamilyBrowserOperationalReadinessItem
		{
			Area = (area ?? string.Empty),
			Status = (status ?? "Warning"),
			Message = (message ?? string.Empty),
			Action = (action ?? string.Empty)
		});
	}

	private static void FinalizeScopedReadiness(FamilyBrowserOperationalReadinessReport report)
	{
		if (report != null && report.Items != null)
		{
			report.BlockingCount = report.Items.Where([SpecialName] (FamilyBrowserOperationalReadinessItem x) => string.Equals(x.Status, "Blocked", StringComparison.OrdinalIgnoreCase)).Count();
			report.WarningCount = report.Items.Where([SpecialName] (FamilyBrowserOperationalReadinessItem x) => string.Equals(x.Status, "Warning", StringComparison.OrdinalIgnoreCase)).Count();
			report.ReadyCount = report.Items.Where([SpecialName] (FamilyBrowserOperationalReadinessItem x) => string.Equals(x.Status, "Ready", StringComparison.OrdinalIgnoreCase)).Count();
		}
	}

	private static string FirstNonEmptyValue(params string[] values)
	{
		foreach (string value in values)
		{
			if (!string.IsNullOrWhiteSpace(value))
			{
				return value.Trim();
			}
		}
		return string.Empty;
	}

	private string ResolveSecurityRoleLabel(string role)
	{
		string left = FamilyBrowserPolicyKey.Normalize(role);
		if (Operators.CompareString(left, FamilyBrowserPolicyKey.Normalize("Admin"), TextCompare: false) == 0)
		{
			return T("Admin", "관리자");
		}
		if (Operators.CompareString(left, FamilyBrowserPolicyKey.Normalize("Approver"), TextCompare: false) == 0)
		{
			return T("Request Approver", "요청 승인자");
		}
		if (Operators.CompareString(left, FamilyBrowserPolicyKey.Normalize("ReadOnly"), TextCompare: false) == 0)
		{
			return T("Read Only", "읽기 전용");
		}
		return T("Modeler", "모델러");
	}

	private string ResolveSecurityUsersLabel(IEnumerable<string> users)
	{
		string label = FamilyBrowserSecurityPolicyService.FormatUserList(users);
		if (string.IsNullOrWhiteSpace(label))
		{
			return T("not configured", "미설정");
		}
		return label;
	}

	private string ResolvePermissionFlagLabel(bool allowed)
	{
		if (!allowed)
		{
			return T("Blocked", "차단");
		}
		return T("Allowed", "허용");
	}

	private string ResolveSecurityReadiness(FamilyBrowserStandardPolicy policy)
	{
		if (!FamilyBrowserSecurityPolicyService.HasConfiguredAdmin(policy?.Security))
		{
			return T("Initial setup mode: configure homepage admin profile keywords before production use.", "초기 설정 모드: 실사용 전 홈페이지 관리자 프로필 키워드를 설정하세요.");
		}
		return T("Homepage admin profile keywords are enforced. Admins have all Family Browser permissions; other users follow modeler/native-command policy.", "홈페이지 관리자 프로필 키워드가 적용됩니다. 관리자는 Family Browser 전체 권한을 가지며, 그 외 사용자는 모델러/Revit 기본 명령 정책을 따릅니다.");
	}

	private bool CanViewAdminTab()
	{
		return CanEnableAdminMode();
	}

	private bool CanSeeInternalPaths()
	{
		bool CanSeeInternalPaths;
		try
		{
			CanSeeInternalPaths = _adminModeEnabled && (HasPermission("ManagePolicy") || HasPermission("RegisterStandard"));
		}
		catch (Exception projectError)
		{
			ProjectData.SetProjectError(projectError);
			CanSeeInternalPaths = false;
			ProjectData.ClearProjectError();
		}
		return CanSeeInternalPaths;
	}

	private string InternalPathHiddenLabel()
	{
		return T("Configured. Detailed path is hidden in modeler mode.", "설정됨. 상세 경로는 모델러 화면에서 숨겨집니다.");
	}

	private string DisplayProjectSubtitle()
	{
		string projectLocation = (_projectPath ?? string.Empty).Trim();
		if (CanSeeInternalPaths())
		{
			return _projectTitle + " / " + projectLocation;
		}
		if (string.IsNullOrWhiteSpace(projectLocation) || string.Equals(projectLocation, "-", StringComparison.Ordinal))
		{
			return _projectTitle;
		}
		if (projectLocation.IndexOf(":\\", StringComparison.Ordinal) >= 0 || projectLocation.StartsWith("\\\\", StringComparison.Ordinal))
		{
			return _projectTitle + " / " + T("Saved project", "저장된 프로젝트");
		}
		return _projectTitle + " / " + projectLocation;
	}

	private string CurrentProjectFileName()
	{
		try
		{
			Document doc = GetActiveDocument();
			if (doc != null)
			{
				if (!string.IsNullOrWhiteSpace(doc.PathName))
				{
					return Path.GetFileNameWithoutExtension(doc.PathName);
				}
				if (!string.IsNullOrWhiteSpace(doc.Title))
				{
					return doc.Title;
				}
			}
		}
		catch (Exception projectError)
		{
			ProjectData.SetProjectError(projectError);
			ProjectData.ClearProjectError();
		}
		if (!string.IsNullOrWhiteSpace(_projectTitle))
		{
			return _projectTitle;
		}
		return "Project";
	}

	private string HideInternalPathDetails(string value)
	{
		string text = (value ?? string.Empty).Trim();
		if (CanSeeInternalPaths() || string.IsNullOrWhiteSpace(text))
		{
			return text;
		}
		string[] array = new string[3] { " Configured path: ", "Configured path: ", " 설정 경로: " };
		foreach (string marker in array)
		{
			int index = text.IndexOf(marker, StringComparison.OrdinalIgnoreCase);
			if (index >= 0)
			{
				string prefix = text.Substring(0, index).Trim();
				if (string.IsNullOrWhiteSpace(prefix))
				{
					return InternalPathHiddenLabel();
				}
				return prefix + " " + T("Detailed path is hidden in modeler mode.", "상세 경로는 모델러 화면에서 숨겨집니다.");
			}
		}
		if (text.IndexOf(":\\", StringComparison.Ordinal) >= 0 || text.StartsWith("\\\\", StringComparison.Ordinal) || text.IndexOf(".json", StringComparison.OrdinalIgnoreCase) >= 0)
		{
			return InternalPathHiddenLabel();
		}
		return text;
	}

	private string ToolActionLink(string actionName, string text, bool primary = false, bool enabled = true)
	{
		string classes = "tool" + (primary ? " primary" : string.Empty);
		if (enabled)
		{
			return "<a class=\"" + classes + "\" href=\"kkyfb:" + Attr(actionName) + "\">" + Html(text) + "</a>";
		}
		return "<span class=\"" + classes + " disabled\" title=\"" + Attr(T("Not available for your current role.", "현재 역할에서는 사용할 수 없습니다.")) + "\">" + Html(text) + "</span>";
	}

	private string ToolTabLink(string tabName, string text, bool primary = false, bool enabled = true)
	{
		string classes = "tool" + ((primary || string.Equals(NormalizeDashboardTabName(_activeTab), NormalizeDashboardTabName(tabName), StringComparison.Ordinal)) ? " primary" : string.Empty);
		if (enabled)
		{
			return "<a name=\"mainNav\" data-tab=\"" + Attr(NormalizeDashboardTabName(tabName)) + "\" class=\"" + classes + "\" href=\"" + Attr(DashboardTabHref(tabName)) + "\">" + Html(text) + "</a>";
		}
		return "<span class=\"" + classes + " disabled\" title=\"" + Attr(T("Not available for your current role.", "현재 역할에서는 사용할 수 없습니다.")) + "\">" + Html(text) + "</span>";
	}

	private string DashboardTabLink(string tabName, string text, bool active, bool enabled = true)
	{
		string classes = "tab" + (active ? " active" : string.Empty);
		if (enabled)
		{
			return "<a name=\"dashTab\" data-tab=\"" + Attr(NormalizeDashboardTabName(tabName)) + "\" class=\"" + classes + "\" href=\"" + Attr(DashboardTabHref(tabName)) + "\">" + Html(text) + "</a>";
		}
		return "<span class=\"" + classes + " disabled\" title=\"" + Attr(T("Not available for your current role.", "현재 역할에서는 사용할 수 없습니다.")) + "\">" + Html(text) + "</span>";
	}

	private string RequestActionLinkForPermission(string statusToken, string requestId, string text, string permission, string cssClass = "")
	{
		if (HasPermission(permission))
		{
			return RequestActionLink(statusToken, requestId, text, cssClass);
		}
		string classes = (string.IsNullOrWhiteSpace(cssClass) ? "disabled" : ("disabled " + cssClass));
		return "<span class=\"" + Attr(classes) + "\" title=\"" + Attr(T("Not available for your current role.", "현재 역할에서는 사용할 수 없습니다.")) + "\">" + Html(text) + "</span>";
	}

	private void ConfigureSecurityUsers(string role)
	{
		try
		{
			if (!EnsurePermission("ManagePolicy", T("Security Policy", "권한 정책")))
			{
				return;
			}
			FamilyBrowserStandardPolicy policy = LoadStandardPolicy();
			string text = FamilyBrowserPolicyKey.Normalize(role);
			string currentUsers;
			string title;
			string promptMessage;
			switch (text)
			{
			case "adminprofilekeywords":
			case "adminprofilekeyword":
			case "admin-keywords":
			case "admin-profile-keywords":
				currentUsers = FamilyBrowserSecurityPolicyService.FormatUserList(policy.Security.AdminProfileKeywords);
				title = T("Admin Profile Keywords", "관리자 프로필 키워드");
				promptMessage = T("Enter Autodesk profile name keywords separated by comma or semicolon. A user can turn on Admin Mode when their Revit Autodesk profile name contains one of these keywords. Example: BIM; KCIM", "Autodesk 프로필 이름에 포함될 키워드를 쉼표/세미콜론으로 구분해 입력하세요. Revit의 Autodesk 프로필 이름에 이 키워드가 포함된 사용자만 관리자 모드를 켤 수 있습니다. 예: BIM; KCIM");
				break;
			default:
				if (Operators.CompareString(text, FamilyBrowserPolicyKey.Normalize("Approver"), TextCompare: false) == 0)
				{
					currentUsers = FamilyBrowserSecurityPolicyService.FormatUserList(policy.Security.RequestApproverUsers);
					title = T("Request Approvers", "요청 승인자");
					promptMessage = T("Enter Autodesk/Revit user names separated by comma or semicolon. Example: Kim Minsoo; DOMAIN\\user", "Autodesk/Revit 사용자명을 쉼표/세미콜론으로 구분해 입력하세요. 예: 김민수; DOMAIN\\user");
				}
				else if (Operators.CompareString(text, FamilyBrowserPolicyKey.Normalize("ReadOnly"), TextCompare: false) == 0)
				{
					currentUsers = FamilyBrowserSecurityPolicyService.FormatUserList(policy.Security.ReadOnlyUsers);
					title = T("Read Only Users", "읽기 전용 사용자");
					promptMessage = T("Enter Autodesk/Revit user names separated by comma or semicolon. Example: Kim Minsoo; DOMAIN\\user", "Autodesk/Revit 사용자명을 쉼표/세미콜론으로 구분해 입력하세요. 예: 김민수; DOMAIN\\user");
				}
				else
				{
					currentUsers = FamilyBrowserSecurityPolicyService.FormatUserList(policy.Security.AdminUsers);
					title = T("Administrators", "관리자");
					promptMessage = T("Enter Autodesk/Revit user names or admin name keywords separated by comma or semicolon. Example: Kim Minsoo; BIM; DOMAIN\\user", "Autodesk/Revit 사용자명 또는 관리자 이름 키워드를 쉼표/세미콜론으로 구분해 입력하세요. 예: 김민수; BIM; DOMAIN\\user");
				}
				break;
			}
			string rawUsers = PromptText(title, promptMessage, currentUsers);
			if (rawUsers == null)
			{
				_statusMessage = T("Security policy update was cancelled.", "권한 정책 변경이 취소되었습니다.");
				RenderDashboard();
				return;
			}
			if (string.IsNullOrWhiteSpace(rawUsers) && ShowDashboardMessage(this, T("Clear this user list?", "이 사용자 목록을 비울까요?") + Environment.NewLine + T("If no administrator name or profile keyword is configured, the add-in stays in initial setup mode.", "관리자 이름과 프로필 키워드가 모두 비어 있으면 애드인은 초기 설정 모드로 유지됩니다."), title, MessageBoxButtons.YesNo, MessageBoxIcon.Exclamation) != DialogResult.Yes)
			{
				_statusMessage = T("Security policy update was cancelled.", "권한 정책 변경이 취소되었습니다.");
				RenderDashboard();
				return;
			}
			FamilyBrowserStandardPolicyStore.SetSecurityUsers(_workspaceRoot, policy, role, rawUsers, Environment.UserName);
			_standardPolicy = FamilyBrowserStandardPolicyStore.LoadOrCreate(_workspaceRoot, Environment.UserName);
			_statusMessage = T("Security policy updated.", "권한 정책을 업데이트했습니다.");
			RefreshDocumentShellOnly();
		}
		catch (Exception ex)
		{
			ProjectData.SetProjectError(ex);
			Exception ex2 = ex;
			ShowLoggedError("Security Policy", ex2);
			ProjectData.ClearProjectError();
		}
	}

	private void ConfigurePermissionExcel()
	{
		try
		{
			if (!EnsurePermission("ManagePolicy", T("Permission Excel", "권한 Excel")))
			{
				return;
			}
			FamilyBrowserStandardPolicy policy = LoadStandardPolicy();
			string selectedPath = ((policy.PermissionExcel == null) ? string.Empty : policy.PermissionExcel.Path);
			using (OpenFileDialog dialog = new OpenFileDialog())
			{
				dialog.Title = T("Select permission Excel file", "권한 Excel 파일 선택");
				dialog.Filter = "Excel or CSV (*.xlsx;*.csv)|*.xlsx;*.csv|Excel Workbook (*.xlsx)|*.xlsx|CSV (*.csv)|*.csv|All files (*.*)|*.*";
				dialog.CheckFileExists = true;
				dialog.Multiselect = false;
				dialog.RestoreDirectory = true;
				if (dialog.ShowDialog(this) != DialogResult.OK)
				{
					_statusMessage = T("Permission Excel setup was cancelled.", "권한 Excel 설정이 취소되었습니다.");
					RenderDashboard();
					return;
				}
				selectedPath = dialog.FileName;
			}
			string sheetName = PromptText(T("Permission Excel", "권한 Excel"), T("Enter sheet name. Leave blank to use the first worksheet.", "시트명을 입력하세요. 비워두면 첫 번째 시트를 사용합니다."), (policy.PermissionExcel == null) ? string.Empty : policy.PermissionExcel.SheetName);
			if (sheetName == null)
			{
				_statusMessage = T("Permission Excel setup was cancelled.", "권한 Excel 설정이 취소되었습니다.");
				RenderDashboard();
				return;
			}
			FamilyBrowserStandardPolicyStore.SetPermissionExcel(_workspaceRoot, policy, enabled: true, selectedPath, sheetName, Environment.UserName);
			_standardPolicy = FamilyBrowserStandardPolicyStore.LoadOrCreate(_workspaceRoot, Environment.UserName);
			FamilyBrowserPermissionExcelPolicyService.ClearCache();
			_permissionDiagnosticCacheKey = string.Empty;
			_permissionDiagnosticCached = null;
			_dashboardPermissionCacheKey = string.Empty;
			_dashboardPermissionCachedSnapshot = null;
			_statusMessage = T("Permission Excel connected without parsing during settings render: ", "설정 화면에서는 파싱하지 않고 권한 Excel 연결만 완료했습니다: ") + selectedPath;
			RenderDashboard();
		}
		catch (Exception ex)
		{
			ProjectData.SetProjectError(ex);
			Exception ex2 = ex;
			ShowLoggedError("Permission Excel", ex2);
			ProjectData.ClearProjectError();
		}
	}

	private void ClearPermissionExcel()
	{
		try
		{
			if (EnsurePermission("ManagePolicy", T("Permission Excel", "권한 Excel")) && ShowDashboardMessage(this, T("Disable Excel-based permission policy?", "Excel 기반 권한 정책을 비활성화할까요?"), T("Permission Excel", "권한 Excel"), MessageBoxButtons.YesNo, MessageBoxIcon.Question) == DialogResult.Yes)
			{
				FamilyBrowserStandardPolicy policy = LoadStandardPolicy();
				FamilyBrowserStandardPolicyStore.SetPermissionExcel(_workspaceRoot, policy, enabled: false, string.Empty, string.Empty, Environment.UserName);
				_standardPolicy = FamilyBrowserStandardPolicyStore.LoadOrCreate(_workspaceRoot, Environment.UserName);
				FamilyBrowserPermissionExcelPolicyService.ClearCache();
				_permissionDiagnosticCacheKey = string.Empty;
				_permissionDiagnosticCached = null;
				_dashboardPermissionCacheKey = string.Empty;
				_dashboardPermissionCachedSnapshot = null;
				_statusMessage = T("Permission Excel disabled.", "권한 Excel을 비활성화했습니다.");
				RenderDashboard();
			}
		}
		catch (Exception ex)
		{
			ProjectData.SetProjectError(ex);
			Exception ex2 = ex;
			ShowLoggedError("Permission Excel", ex2);
			ProjectData.ClearProjectError();
		}
	}

	private void ConfigureFileGuardPolicy()
	{
		try
		{
			if (!EnsurePermission("ManagePolicy", T("File-specific Guard", "파일별 권한 적용")))
			{
				return;
			}
			FamilyBrowserStandardPolicy policy = LoadStandardPolicy();
			FamilyBrowserFileGuardPolicy currentGuard = policy.FileGuard ?? FamilyBrowserFileGuardPolicy.CreateDefault();
			string selectedFolder = currentGuard.RootFolder ?? string.Empty;
			selectedFolder = BrowseForFolderWithExplorer(T("Select the parent folder that contains central RVT files.", "센트럴 RVT 파일이 들어있는 상위 폴더를 선택하세요."), selectedFolder);
			if (string.IsNullOrWhiteSpace(selectedFolder))
			{
				_statusMessage = T("File guard setup was cancelled.", "파일별 권한 적용 설정이 취소되었습니다.");
				RenderDashboard();
				return;
			}
			string title = T("File-specific Guard", "파일별 권한 적용");
			BeginLongOperationProgress(title, T("Scanning RVT files under the selected folder...", "선택한 폴더 하위의 RVT 파일을 검색하는 중..."));
			List<string> rvtFiles;
			try
			{
				rvtFiles = EnumerateRvtFilesForFileGuard(selectedFolder, [SpecialName] (int current, int total, string message) =>
				{
					int current2 = Math.Min(95, Math.Max(5, current));
					UpdateLongOperationProgress(title, current2, 100, T("Scanning RVT folder: ", "RVT 폴더 검색 중: ") + message, forcePaint: true);
				});
				CompleteLongOperationProgress(T("RVT file scan completed.", "RVT 파일 검색이 완료되었습니다."));
			}
			catch (Exception projectError)
			{
				ProjectData.SetProjectError(projectError);
				CompleteLongOperationProgress(T("RVT file scan stopped.", "RVT 파일 검색을 중단했습니다."));
				throw;
			}
			if (rvtFiles.Count == 0)
			{
				ShowDashboardMessage(this, T("No RVT files were found under the selected folder.", "선택한 폴더 하위에서 RVT 파일을 찾지 못했습니다."), T("File-specific Guard", "파일별 권한 적용"), MessageBoxButtons.OK, MessageBoxIcon.Asterisk);
				return;
			}
			using (FileGuardConfigurationForm dialog = new FileGuardConfigurationForm(selectedFolder, rvtFiles, currentGuard, IsKorean()))
			{
				if (dialog.ShowDialog(this) != DialogResult.OK)
				{
					_statusMessage = T("File guard setup was cancelled.", "파일별 권한 적용 설정이 취소되었습니다.");
					RenderDashboard();
					return;
				}
				FamilyBrowserFileGuardPolicy updatedGuard = dialog.BuildPolicy();
				FamilyBrowserStandardPolicyStore.SetFileGuardPolicy(_workspaceRoot, policy, updatedGuard, Environment.UserName);
			}
			_standardPolicy = FamilyBrowserStandardPolicyStore.LoadOrCreate(_workspaceRoot, Environment.UserName);
			FamilyBrowserNativeCommandGuardService.NotifyPolicyChanged();
			_dashboardPermissionCacheKey = string.Empty;
			_dashboardPermissionCachedSnapshot = null;
			_statusMessage = T("File-specific native command guard saved.", "파일별 Revit 기본 명령 차단 설정을 저장했습니다.");
			RefreshDocumentShellOnly();
		}
		catch (Exception ex)
		{
			ProjectData.SetProjectError(ex);
			Exception ex2 = ex;
			ShowLoggedError("File-specific Guard", ex2);
			ProjectData.ClearProjectError();
		}
	}

	private void ExportFileGuardPolicy()
	{
		try
		{
			if (!EnsurePermission("ManagePolicy", T("File-specific Guard", "파일별 권한 적용")))
			{
				return;
			}
			FamilyBrowserFileGuardPolicy fileGuard = LoadStandardPolicy().FileGuard ?? FamilyBrowserFileGuardPolicy.CreateDefault();
			List<FamilyBrowserFileGuardTarget> targets = (fileGuard.Targets ?? new List<FamilyBrowserFileGuardTarget>()).Where([SpecialName] (FamilyBrowserFileGuardTarget x) => x?.Enabled ?? false).ToList();
			if (!fileGuard.Enabled || targets.Count == 0)
			{
				ShowDashboardMessage(this, T("There are no active file-specific guards to export.", "추출할 활성 파일별 권한 적용 항목이 없습니다."), T("File-specific Guard", "파일별 권한 적용"), MessageBoxButtons.OK, MessageBoxIcon.Asterisk);
				return;
			}
			using SaveFileDialog dialog = new SaveFileDialog();
			dialog.Title = T("Export file-specific guards to Excel", "파일별 권한 Excel 추출");
			dialog.Filter = "Excel Workbook (*.xlsx)|*.xlsx";
			dialog.DefaultExt = "xlsx";
			dialog.AddExtension = true;
			dialog.OverwritePrompt = true;
			dialog.RestoreDirectory = true;
			dialog.FileName = "FamilyBrowser_FileGuards_" + DateTime.Now.ToString("yyyyMMdd-HHmm", CultureInfo.InvariantCulture) + ".xlsx";
			ConfigureExplorerSaveDialog(dialog, FamilyBrowserStandardPolicyStore.GetDataFolder(_workspaceRoot, "Reports"));
