				_statusMessage = T("File guard Excel export was cancelled.", "파일별 권한 Excel 추출이 취소되었습니다.");
				RenderDashboard();
				return;
			}
			FamilyBrowserPermissionExcelExportResult result = FamilyBrowserPermissionExcelExportService.ExportFileGuardPolicy(fileGuard, dialog.FileName, IsKorean());
			_statusMessage = T("File guard Excel exported: ", "파일별 권한 Excel 추출 완료: ") + result.OutputPath;
