			RenderDashboard();
		}
		catch (Exception ex)
		{
			ProjectData.SetProjectError(ex);
			Exception ex2 = ex;
			ShowLoggedError("File-specific Guard Export", ex2);
			ProjectData.ClearProjectError();
		}
	}

