	private static List<string> EnumerateRvtFilesForFileGuard(string rootFolder, Action<int, int, string> progress = null)
	{
		List<string> result = new List<string>();
		if (string.IsNullOrWhiteSpace(rootFolder) || !Directory.Exists(rootFolder))
		{
			return result;
		}
		Stack<string> pending = new Stack<string>();
		pending.Push(rootFolder);
		int scannedFolderCount = 0;
		while (pending.Count > 0)
		{
			string folder = pending.Pop();
			scannedFolderCount = checked(scannedFolderCount + 1);
			if (progress != null && scannedFolderCount % 20 == 1)
			{
				progress(Math.Min(95, checked(5 + scannedFolderCount)), 100, folder);
			}
			try
			{
				foreach (string filePath in Directory.EnumerateFiles(folder, "*.rvt", SearchOption.TopDirectoryOnly))
				{
					if (!IsBackupRvtFileName(filePath))
					{
						result.Add(filePath);
					}
				}
			}
			catch (Exception projectError)
			{
				ProjectData.SetProjectError(projectError);
				ProjectData.ClearProjectError();
			}
			try
			{
				foreach (string childFolder in Directory.EnumerateDirectories(folder))
				{
					pending.Push(childFolder);
				}
			}
			catch (Exception projectError2)
			{
				ProjectData.SetProjectError(projectError2);
				ProjectData.ClearProjectError();
			}
		}
		return result.OrderBy([SpecialName] (string path) => path, StringComparer.OrdinalIgnoreCase).ToList();
	}

	private string BrowseForFolderWithExplorer(string title, string initialFolder)
	{
		using (OpenFileDialog dialog = new OpenFileDialog())
		{
			dialog.Title = title ?? string.Empty;
			dialog.CheckFileExists = false;
			dialog.CheckPathExists = true;
			dialog.ValidateNames = false;
			dialog.AddExtension = false;
			dialog.DereferenceLinks = true;
			dialog.Multiselect = false;
			dialog.RestoreDirectory = true;
			dialog.FileName = T("Select this folder", "이 폴더 선택");
			if (!string.IsNullOrWhiteSpace(initialFolder) && Directory.Exists(initialFolder))
			{
				dialog.InitialDirectory = initialFolder;
			}
			if (!TryEnableFolderPickMode(dialog))
			{
				return BrowseForFolderFallback(title, initialFolder);
			}
			if (dialog.ShowDialog(this) != DialogResult.OK)
			{
				return string.Empty;
			}
			string selected = (dialog.FileName ?? string.Empty).Trim();
			if (Directory.Exists(selected))
			{
				return selected;
			}
			try
			{
				string folder = Path.GetDirectoryName(selected);
				if (!string.IsNullOrWhiteSpace(folder) && Directory.Exists(folder))
				{
					return folder;
				}
			}
			catch (Exception projectError)
			{
				ProjectData.SetProjectError(projectError);
				ProjectData.ClearProjectError();
			}
		}
		return string.Empty;
	}

	private string BrowseForFolderFallback(string title, string initialFolder)
	{
		using FolderBrowserDialog folderDialog = new FolderBrowserDialog();
		folderDialog.Description = title ?? string.Empty;
		folderDialog.ShowNewFolderButton = false;
		if (!string.IsNullOrWhiteSpace(initialFolder) && Directory.Exists(initialFolder))
		{
			folderDialog.SelectedPath = initialFolder;
		}
		if (folderDialog.ShowDialog(this) != DialogResult.OK || string.IsNullOrWhiteSpace(folderDialog.SelectedPath))
		{
			return string.Empty;
		}
		return folderDialog.SelectedPath;
	}

	private static bool TryEnableFolderPickMode(OpenFileDialog dialog)
	{
		bool TryEnableFolderPickMode;
		if (dialog == null)
		{
			TryEnableFolderPickMode = false;
		}
		else
		{
			try
			{
				FieldInfo field = typeof(FileDialog).GetField("options", BindingFlags.Instance | BindingFlags.NonPublic);
				if ((object)field == null)
				{
					TryEnableFolderPickMode = false;
				}
				else
				{
					int options = Conversions.ToInteger(field.GetValue(dialog));
					field.SetValue(dialog, options | 0x20);
					TryEnableFolderPickMode = true;
				}
			}
			catch (Exception projectError)
			{
				ProjectData.SetProjectError(projectError);
				TryEnableFolderPickMode = false;
				ProjectData.ClearProjectError();
			}
		}
		return TryEnableFolderPickMode;
	}

	private static bool IsBackupRvtFileName(string filePath)
	{
		string name = Path.GetFileNameWithoutExtension(filePath) ?? string.Empty;
		if (name.Length == 0)
		{
			return false;
		}
		string lastPart = name;
		int underscore = name.LastIndexOf('_');
		checked
		{
			if (underscore >= 0 && underscore < name.Length - 1)
			{
				lastPart = name.Substring(underscore + 1);
			}
			return lastPart.Length == 4 && lastPart.All([SpecialName] (char ch) => char.IsDigit(ch));
		}
	}

