	private void ExportPermissionExcelFromRvtFolder()
	{
		try
		{
			if (!EnsurePermission("ManagePolicy", T("Permission Excel", "권한 Excel")))
			{
				return;
			}
			string sourceFolder;
			using (FolderBrowserDialog folderDialog = new FolderBrowserDialog())
			{
				folderDialog.Description = T("Select the folder that contains project RVT files.", "프로젝트 RVT 파일이 들어있는 폴더를 선택하세요.");
				folderDialog.ShowNewFolderButton = false;
				if (folderDialog.ShowDialog(this) != DialogResult.OK || string.IsNullOrWhiteSpace(folderDialog.SelectedPath))
				{
					_statusMessage = T("RVT folder export was cancelled.", "RVT 폴더 권한대장 생성이 취소되었습니다.");
					RenderDashboard();
					return;
				}
				sourceFolder = folderDialog.SelectedPath;
			}
			string defaultName = "FamilyBrowser_PermissionPolicy_" + SafeFileToken(Path.GetFileName(sourceFolder)) + ".xlsx";
			string outputPath;
			using (SaveFileDialog saveDialog = new SaveFileDialog())
			{
				saveDialog.Title = T("Save permission Excel from RVT folder", "RVT 폴더 기반 권한 Excel 저장");
				saveDialog.Filter = "Excel Workbook (*.xlsx)|*.xlsx";
				saveDialog.DefaultExt = "xlsx";
				saveDialog.AddExtension = true;
				saveDialog.OverwritePrompt = true;
				saveDialog.RestoreDirectory = true;
				saveDialog.FileName = defaultName;
				ConfigureExplorerSaveDialog(saveDialog, sourceFolder);
				if (saveDialog.ShowDialog(this) != DialogResult.OK)
				{
					_statusMessage = T("RVT folder export was cancelled.", "RVT 폴더 권한대장 생성이 취소되었습니다.");
					RenderDashboard();
					return;
				}
				outputPath = saveDialog.FileName;
			}
			FamilyBrowserPermissionExcelExportResult result = FamilyBrowserPermissionExcelExportService.ExportRvtFolder(sourceFolder, outputPath, BuildPolicyTargetLabel(), IsKorean());
			string message = T("Permission Excel created from RVT folder.", "RVT 폴더 기반 권한 Excel을 생성했습니다.") + Environment.NewLine + T("RVT rows: ", "RVT 행: ") + result.RowCount.ToString(CultureInfo.InvariantCulture) + Environment.NewLine + T("Skipped backup RVTs: ", "제외한 백업 RVT: ") + result.SkippedBackupCount.ToString(CultureInfo.InvariantCulture) + Environment.NewLine + result.OutputPath;
			_statusMessage = message.Replace(Environment.NewLine, " ");
			if (result.RowCount > 0 && ShowDashboardMessage(this, message + Environment.NewLine + Environment.NewLine + T("Connect this file as the active permission Excel?", "이 파일을 현재 권한 Excel로 바로 연결할까요?"), T("Permission Excel", "권한 Excel"), MessageBoxButtons.YesNo, MessageBoxIcon.Question) == DialogResult.Yes)
			{
				FamilyBrowserStandardPolicy policy = LoadStandardPolicy();
				FamilyBrowserStandardPolicyStore.SetPermissionExcel(_workspaceRoot, policy, enabled: true, result.OutputPath, result.SheetName, Environment.UserName);
				_standardPolicy = FamilyBrowserStandardPolicyStore.LoadOrCreate(_workspaceRoot, Environment.UserName);
				FamilyBrowserPermissionExcelPolicyService.ClearCache();
				_permissionDiagnosticCacheKey = string.Empty;
				_permissionDiagnosticCached = null;
				_dashboardPermissionCacheKey = string.Empty;
				_dashboardPermissionCachedSnapshot = null;
				_statusMessage = T("Permission Excel created and connected: ", "권한 Excel 생성 및 연결 완료: ") + result.OutputPath;
				PromptOpenSavedExcel(result.OutputPath, T("Permission Excel", "권한 Excel"), this);
				RenderDashboard();
			}
			else
			{
				ShowSavedExcelMessageAndMaybeOpen(this, T("Permission Excel", "권한 Excel"), message, result.OutputPath);
				RenderDashboard();
			}
		}
		catch (Exception ex)
		{
			ProjectData.SetProjectError(ex);
			Exception ex2 = ex;
			ShowLoggedError("Permission Excel RVT Folder Export", ex2);
			ProjectData.ClearProjectError();
		}
	}

	private static string SafeFileToken(string value)
	{
		string text = (value ?? string.Empty).Trim();
		if (string.IsNullOrWhiteSpace(text))
		{
			text = "RVT_Folder";
		}
		char[] invalidFileNameChars = Path.GetInvalidFileNameChars();
		foreach (char ch in invalidFileNameChars)
		{
			text = text.Replace(ch, '_');
		}
		return text;
	}

	private static void ConfigureExplorerSaveDialog(SaveFileDialog dialog, string initialDirectory = null)
	{
		if (dialog == null)
		{
			return;
		}
		dialog.CheckPathExists = true;
		dialog.RestoreDirectory = true;
		if (!string.IsNullOrWhiteSpace(initialDirectory))
		{
			try
			{
				if (Directory.Exists(initialDirectory))
				{
					dialog.InitialDirectory = initialDirectory;
				}
			}
			catch (Exception projectError)
			{
				ProjectData.SetProjectError(projectError);
				ProjectData.ClearProjectError();
			}
		}
		try
		{
			dialog.AutoUpgradeEnabled = true;
		}
		catch (Exception projectError2)
		{
			ProjectData.SetProjectError(projectError2);
			ProjectData.ClearProjectError();
		}
	}

	private void ShowSavedExcelMessageAndMaybeOpen(IWin32Window owner, string caption, string message, string outputPath)
	{
		IWin32Window dialogOwner = owner ?? this;
		string safeCaption = FirstNonEmptyValue(caption, T("Excel Export", "Excel 내보내기"));
		string prompt = (message ?? string.Empty).Trim();
		if (prompt.Length > 0)
		{
			prompt = prompt + Environment.NewLine + Environment.NewLine;
		}
		prompt += T("Open the saved Excel file now?", "저장한 Excel 파일을 지금 열어볼까요?");
		if (!string.IsNullOrWhiteSpace(outputPath))
		{
			prompt = prompt + Environment.NewLine + outputPath;
		}
		if (ShowDashboardMessage(dialogOwner, prompt, safeCaption, MessageBoxButtons.YesNo, MessageBoxIcon.Question) == DialogResult.Yes)
		{
			OpenSavedExcelFile(outputPath, safeCaption, dialogOwner);
		}
	}

	private void PromptOpenSavedExcel(string outputPath, string caption, IWin32Window owner = null)
	{
		if (!string.IsNullOrWhiteSpace(outputPath))
		{
			IWin32Window dialogOwner = owner ?? this;
			string safeCaption = FirstNonEmptyValue(caption, T("Excel Export", "Excel 내보내기"));
			string prompt = T("Excel file saved.", "Excel 파일을 저장했습니다.") + Environment.NewLine + outputPath + Environment.NewLine + Environment.NewLine + T("Open it now?", "지금 열어볼까요?");
			if (ShowDashboardMessage(dialogOwner, prompt, safeCaption, MessageBoxButtons.YesNo, MessageBoxIcon.Question) == DialogResult.Yes)
			{
				OpenSavedExcelFile(outputPath, safeCaption, dialogOwner);
			}
		}
	}

	private void OpenSavedExcelFile(string outputPath, string caption, IWin32Window owner)
	{
		try
		{
			string expandedPath = Environment.ExpandEnvironmentVariables((outputPath ?? string.Empty).Trim());
			if (string.IsNullOrWhiteSpace(expandedPath) || !File.Exists(expandedPath))
			{
				ShowDashboardMessage(owner, T("The saved Excel file could not be found: ", "저장한 Excel 파일을 찾을 수 없습니다: ") + expandedPath, caption, MessageBoxButtons.OK, MessageBoxIcon.Exclamation);
				return;
			}
			Process.Start(new ProcessStartInfo(expandedPath)
			{
				UseShellExecute = true
			});
		}
		catch (Exception ex)
		{
			ProjectData.SetProjectError(ex);
			Exception ex2 = ex;
			ShowDashboardMessage(owner, T("Excel file was saved, but it could not be opened automatically: ", "Excel 파일은 저장됐지만 자동으로 열지 못했습니다: ") + ex2.Message, caption, MessageBoxButtons.OK, MessageBoxIcon.Exclamation);
			ProjectData.ClearProjectError();
		}
	}

	private void CheckPermissionDiagnostic()
	{
		try
		{
			FamilyBrowserStandardPolicy policy = _standardPolicy ?? LoadStandardPolicy();
			FamilyBrowserProjectPolicyContext context = CurrentProjectPolicyContext();
			string currentUser = CurrentUserIdentity();
			FamilyBrowserPermissionExcelDiagnostic diagnostic = FamilyBrowserPermissionExcelPolicyService.BuildDiagnostic(policy, currentUser, context);
			_permissionDiagnosticCacheKey = BuildPermissionDiagnosticCacheKey(policy, currentUser, context);
			_permissionDiagnosticCached = diagnostic;
			_dashboardPermissionCacheKey = string.Empty;
			_dashboardPermissionCachedSnapshot = null;
			if (diagnostic != null && diagnostic.Matched)
			{
				_statusMessage = T("Permission check: Excel row ", "권한 확인: Excel 행 ") + diagnostic.MatchedRowNumber.ToString(CultureInfo.InvariantCulture) + T(" is applied.", " 이 적용됩니다.");
			}
			else if (diagnostic != null && !string.IsNullOrWhiteSpace(diagnostic.Message))
			{
				_statusMessage = T("Permission check: ", "권한 확인: ") + diagnostic.Message;
			}
			else
			{
				_statusMessage = T("Permission check completed.", "권한 확인을 완료했습니다.");
			}
			RenderDashboard();
		}
		catch (Exception ex)
		{
			ProjectData.SetProjectError(ex);
			Exception ex2 = ex;
			ShowLoggedError("Permission Diagnostic", ex2);
			ProjectData.ClearProjectError();
		}
	}

	private FamilyBrowserProjectPolicyContext CurrentProjectPolicyContext()
	{
		FamilyBrowserProjectPolicyContext context = new FamilyBrowserProjectPolicyContext
		{
			ProjectTitle = _projectTitle,
			ModelPath = _projectPath,
			CentralPath = (string.Equals(_centralPathText, "-", StringComparison.Ordinal) ? string.Empty : _centralPathText),
			StandardTarget = BuildPolicyTargetLabel(),
			IsWorkshared = false
		};
		Document doc = GetActiveDocument();
		if (doc == null)
		{
			return context;
		}
		try
		{
			if (!string.IsNullOrWhiteSpace(doc.Title))
			{
				context.ProjectTitle = doc.Title;
			}
