	private void AddCurrentProjectPolicyRule()
	{
		try
		{
			if (!EnsurePermission("ManagePolicy", T("Project Policy", "프로젝트별 정책")))
			{
				return;
			}
			Document doc = GetActiveDocument();
			if (doc == null)
			{
				ShowDashboardMessage(this, T("Open a Revit project before adding a project-specific policy rule.", "프로젝트별 정책 규칙을 추가하려면 먼저 Revit 프로젝트를 여세요."), T("Project Policy", "프로젝트별 정책"), MessageBoxButtons.OK, MessageBoxIcon.Asterisk);
				return;
			}
			FamilyBrowserProjectPolicyContext context = BuildProjectPolicyContext(doc);
			string ruleName = PromptText(T("Project Policy", "프로젝트별 정책"), T("Enter a rule name for this project.", "이 프로젝트 정책 규칙 이름을 입력하세요."), string.IsNullOrWhiteSpace(context.ProjectTitle) ? T("Current project", "현재 프로젝트") : context.ProjectTitle);
			if (string.IsNullOrWhiteSpace(ruleName))
			{
				_statusMessage = T("Project policy rule setup was cancelled.", "프로젝트별 정책 규칙 설정이 취소되었습니다.");
				RenderDashboard();
				return;
			}
			string preset = PromptText(T("Project Policy Preset", "프로젝트 권한 프리셋"), T("Preset: StandardModeler, RequestOnly, ReadOnly, Inherit", "프리셋: StandardModeler, RequestOnly, ReadOnly, Inherit"), "StandardModeler");
			if (preset == null)
			{
				_statusMessage = T("Project policy rule setup was cancelled.", "프로젝트별 정책 규칙 설정이 취소되었습니다.");
				RenderDashboard();
				return;
			}
			if (string.IsNullOrWhiteSpace(preset))
			{
				preset = "StandardModeler";
			}
			string matchMode = "ProjectTitleContains";
			string matchValue = context.ProjectTitle;
			if (!string.IsNullOrWhiteSpace(context.CentralPath))
			{
				matchMode = "ExactCentralPath";
				matchValue = context.CentralPath;
			}
			else if (!string.IsNullOrWhiteSpace(context.ModelPath))
			{
				matchMode = "ExactModelPath";
				matchValue = context.ModelPath;
			}
			FamilyBrowserProjectPolicyRule rule = new FamilyBrowserProjectPolicyRule
			{
				RuleName = ruleName,
				Enabled = true,
				MatchMode = matchMode,
				MatchValue = matchValue,
				PermissionPreset = preset
			};
			FamilyBrowserStandardPolicy policy = LoadStandardPolicy();
			FamilyBrowserStandardPolicyStore.AddOrUpdateProjectPolicyRule(_workspaceRoot, policy, rule, Environment.UserName);
			_standardPolicy = FamilyBrowserStandardPolicyStore.LoadOrCreate(_workspaceRoot, Environment.UserName);
			_statusMessage = T("Project policy rule saved.", "프로젝트별 정책 규칙을 저장했습니다.");
			RefreshDocumentShellOnly();
		}
		catch (Exception ex)
		{
			ProjectData.SetProjectError(ex);
			Exception ex2 = ex;
			ShowLoggedError("Project Policy", ex2);
			ProjectData.ClearProjectError();
		}
	}

	private void ClearProjectPolicyRules()
	{
		try
		{
			if (EnsurePermission("ManagePolicy", T("Project Policy", "프로젝트별 정책")) && ShowDashboardMessage(this, T("Clear all project-specific policy rules?", "모든 프로젝트별 정책 규칙을 삭제할까요?"), T("Project Policy", "프로젝트별 정책"), MessageBoxButtons.YesNo, MessageBoxIcon.Exclamation) == DialogResult.Yes)
			{
				FamilyBrowserStandardPolicy policy = LoadStandardPolicy();
				FamilyBrowserStandardPolicyStore.ClearProjectPolicyRules(_workspaceRoot, policy, Environment.UserName);
				_standardPolicy = FamilyBrowserStandardPolicyStore.LoadOrCreate(_workspaceRoot, Environment.UserName);
				_statusMessage = T("Project policy rules cleared.", "프로젝트별 정책 규칙을 삭제했습니다.");
				RefreshDocumentShellOnly();
			}
		}
		catch (Exception ex)
		{
			ProjectData.SetProjectError(ex);
			Exception ex2 = ex;
			ShowLoggedError("Project Policy", ex2);
			ProjectData.ClearProjectError();
		}
	}

	private string BuildPolicyTargetLabel()
	{
		FamilyBrowserStandardPolicy policy = _standardPolicy ?? LoadStandardPolicy();
		FamilyBrowserStandardLibrarySlot slot = FamilyBrowserStandardPolicyStore.GetEffectiveSlot(policy);
		if (string.Equals(policy.Mode, "Integrated", StringComparison.OrdinalIgnoreCase))
		{
			return FamilyBrowserStandardPolicyStore.ResolveSlotDisplayName(policy.IntegratedLibrary, IsKorean());
		}
		if (slot == null)
		{
			return FamilyBrowserStandardPolicyStore.ResolveDisciplineLabel(policy.ActiveDiscipline, IsKorean());
		}
		return FamilyBrowserStandardPolicyStore.ResolveSlotDisplayName(slot, IsKorean());
	}

	private List<string> BuildDisciplineDisplayOptions(FamilyBrowserStandardPolicy policy)
	{
		List<string> result = new List<string>();
		if (policy == null)
		{
			result.Add(BuildPolicyTargetLabel());
			return result;
		}
		if (!string.Equals(policy.Mode, "Integrated", StringComparison.OrdinalIgnoreCase))
		{
			foreach (FamilyBrowserStandardLibrarySlot slot in FamilyBrowserStandardPolicyStore.GetDisciplineSlots(policy))
			{
				result.Add(FamilyBrowserStandardPolicyStore.ResolveSlotDisplayName(slot, IsKorean()));
			}
		}
		else
		{
			result.Add(FamilyBrowserStandardPolicyStore.ResolveSlotDisplayName(policy.IntegratedLibrary, IsKorean()));
		}
		if (result.Count == 0)
		{
			result.Add(BuildPolicyTargetLabel());
		}
		return result.Where([SpecialName] (string x) => !string.IsNullOrWhiteSpace(x)).Distinct(StringComparer.OrdinalIgnoreCase).ToList();
	}

	private string BuildPolicyModeLabel()
	{
		if (string.Equals((_standardPolicy ?? LoadStandardPolicy()).Mode, "Integrated", StringComparison.OrdinalIgnoreCase))
		{
			return T("One integrated standard mode", "통합 표준 모드");
		}
		return T("Separate standards by trade", "공종별 표준 모드");
	}

	private List<FamilyBrowserStandardLibrarySlot> GetBrowserStandardSlots(FamilyBrowserStandardPolicy policy)
	{
		List<FamilyBrowserStandardLibrarySlot> result = new List<FamilyBrowserStandardLibrarySlot>();
		if (policy == null)
		{
			return result;
		}
		if (string.Equals(policy.Mode, "Integrated", StringComparison.OrdinalIgnoreCase))
		{
			if (policy.IntegratedLibrary != null)
			{
				result.Add(policy.IntegratedLibrary);
			}
		}
		else
		{
			result.AddRange(FamilyBrowserStandardPolicyStore.GetDisciplineSlots(policy));
		}
		if (result.Count == 0)
		{
			FamilyBrowserStandardLibrarySlot fallback = FamilyBrowserStandardPolicyStore.GetEffectiveSlot(policy);
			if (fallback != null)
			{
				result.Add(fallback);
			}
		}
		return result;
	}

	private FamilyBrowserStandardLibrarySlot ResolvePolicySlot(FamilyBrowserStandardPolicy policy, string targetKey)
	{
		if (policy == null)
		{
			return null;
		}
		if (string.IsNullOrWhiteSpace(targetKey))
		{
			return FamilyBrowserStandardPolicyStore.GetEffectiveSlot(policy);
		}
		string normalizedTarget = Normalize(targetKey);
		foreach (FamilyBrowserStandardLibrarySlot slot in GetBrowserStandardSlots(policy))
		{
			if (string.Equals(Normalize(ResolveSlotKey(slot)), normalizedTarget, StringComparison.Ordinal) || string.Equals(Normalize(slot.Discipline), normalizedTarget, StringComparison.Ordinal) || string.Equals(Normalize(slot.DisplayName), normalizedTarget, StringComparison.Ordinal))
			{
				return slot;
			}
		}
		string discipline = FamilyBrowserStandardPolicyStore.ResolveDisciplineKey(policy, targetKey);
		if (!string.IsNullOrWhiteSpace(discipline))
		{
			_Closure_0024__293_002D0 arg = default(_Closure_0024__293_002D0);
			_Closure_0024__293_002D0 CS_0024_003C_003E8__locals2 = new _Closure_0024__293_002D0(arg);
			CS_0024_003C_003E8__locals2._0024VB_0024Local_normalizedDiscipline = Normalize(discipline);
			FamilyBrowserStandardLibrarySlot match = GetBrowserStandardSlots(policy).FirstOrDefault([SpecialName] (FamilyBrowserStandardLibrarySlot x) => string.Equals(Normalize(x.Discipline), CS_0024_003C_003E8__locals2._0024VB_0024Local_normalizedDiscipline, StringComparison.Ordinal));
			if (match != null)
			{
				return match;
			}
		}
		return FamilyBrowserStandardPolicyStore.GetEffectiveSlot(policy);
	}

	private FamilyBrowserStandardLibrarySlot ResolveBrowseSlot(FamilyBrowserStandardPolicy policy)
	{
		if (policy == null)
		{
			return null;
		}
		if (!string.IsNullOrWhiteSpace(_browseDisciplineKey))
		{
			return ResolvePolicySlot(policy, _browseDisciplineKey);
		}
		FamilyBrowserStandardLibrarySlot effective = FamilyBrowserStandardPolicyStore.GetEffectiveSlot(policy);
		if (effective != null)
		{
			return effective;
		}
		return GetBrowserStandardSlots(policy).FirstOrDefault();
	}

	private string ResolveRegistrationPathForSlot(FamilyBrowserStandardPolicy policy, FamilyBrowserStandardLibrarySlot slot)
	{
		string slotRegistrationPath = FamilyBrowserStandardPolicyStore.ResolveSlotRegistrationPath(_workspaceRoot, slot);
		if (!string.IsNullOrWhiteSpace(slotRegistrationPath))
		{
			return slotRegistrationPath;
		}
		FamilyBrowserStandardLibrarySlot effective = null;
		if (policy != null)
		{
			effective = FamilyBrowserStandardPolicyStore.GetEffectiveSlot(policy);
		}
		if (SlotMatches(slot, effective))
		{
			return FamilyBrowserStandardPolicyStore.ResolveEffectiveRegistrationPath(_workspaceRoot, policy);
		}
		return Path.Combine(FamilyBrowserStandardPolicyStore.GetRegistryFolder(_workspaceRoot), "missing-standard-library-slot.json");
	}

	private static bool SlotMatches(FamilyBrowserStandardLibrarySlot left, FamilyBrowserStandardLibrarySlot right)
	{
		if (left == null || right == null)
		{
			return false;
		}
		string leftKey = Normalize(ResolveSlotKey(left));
		string rightKey = Normalize(ResolveSlotKey(right));
		if (leftKey.Length > 0 && rightKey.Length > 0 && string.Equals(leftKey, rightKey, StringComparison.Ordinal))
		{
			return true;
		}
		return string.Equals(Normalize(left.Discipline), Normalize(right.Discipline), StringComparison.Ordinal);
	}

	private void SelectFirstReadyBrowseSlotIfImplicit(ref FamilyBrowserStandardLibrarySlot browseSlot, ref StandardLibraryRegistrationRecord selectedRegistration, ref bool selectedSnapshotMissing, FamilyBrowserStandardLibrarySlot firstReadySlot, StandardLibraryRegistrationRecord firstReadyRegistration)
	{
		if (selectedRegistration == null && (string.IsNullOrWhiteSpace(_browseDisciplineKey) || _browseDisciplineAutoSelected) && firstReadySlot != null && firstReadyRegistration != null)
		{
			browseSlot = firstReadySlot;
			selectedRegistration = firstReadyRegistration;
			selectedSnapshotMissing = false;
			_browseDisciplineKey = ResolveSlotKey(firstReadySlot);
			_browseDisciplineAutoSelected = true;
		}
	}

	private static string ResolveSlotKey(FamilyBrowserStandardLibrarySlot slot)
	{
		if (slot == null)
		{
			return string.Empty;
		}
		if (!string.IsNullOrWhiteSpace(slot.SlotKey))
		{
			return slot.SlotKey;
		}
		return slot.Discipline;
	}

	private string ResolveSlotLabel(FamilyBrowserStandardLibrarySlot slot)
