	private string ResolveDisciplineDisplayName(FamilyBrowserStandardPolicy policy, string disciplineKey)
	{
		FamilyBrowserStandardLibrarySlot slot = ResolvePolicySlot(policy, disciplineKey);
		if (slot != null)
