	private static bool IsStandardSnapshotStale(StandardLibraryRegistrationRecord registration)
	{
		StandardRvtFileStampStatus status = BuildStandardRvtFileStampStatus(registration, probeFile: true);
		if (status != null && status.Exists)
		{
			return status.ChangedSinceScan;
		}
		return false;
	}

	private static StandardRvtFileStampStatus BuildStandardRvtFileStampStatus(StandardLibraryRegistrationRecord registration, bool probeFile = false)
	{
		StandardRvtFileStampStatus status = new StandardRvtFileStampStatus();
		if (registration == null)
		{
			return status;
		}
		status.HasRegistration = true;
		status.Path = (string.IsNullOrWhiteSpace(registration.ResolvedPath) ? (registration.Locator ?? string.Empty) : registration.ResolvedPath);
		if (string.IsNullOrWhiteSpace(status.Path))
		{
			return status;
		}
		DateTime recordedUtc = default(DateTime);
		if (TryParseUtcStamp(registration.SourceFileLastWriteUtc, ref recordedUtc))
		{
			status.HasRecordedSourceStamp = true;
			status.HasAnyRecordedStamp = true;
			status.RecordedLastWriteUtc = recordedUtc;
		}
		else if (TryParseUtcStamp(registration.LastSnapshotAtUtc, ref recordedUtc))
		{
			status.HasAnyRecordedStamp = true;
			status.RecordedLastWriteUtc = recordedUtc;
		}
		status.RecordedLength = registration.SourceFileLength;
		if (!probeFile)
		{
			status.Exists = true;
			status.FileProbeSkipped = true;
			return status;
		}
		try
		{
			status.Path = Environment.ExpandEnvironmentVariables(status.Path.Trim());
			if (!File.Exists(status.Path))
			{
				return status;
			}
			FileInfo info = new FileInfo(status.Path);
			status.Exists = true;
			status.CurrentLastWriteUtc = info.LastWriteTimeUtc;
			status.CurrentLength = info.Length;
			if (!status.HasAnyRecordedStamp)
			{
				return status;
			}
			double modifiedSecondsDelta = Math.Abs((status.CurrentLastWriteUtc - status.RecordedLastWriteUtc).TotalSeconds);
			status.CurrentIsNewer = DateTime.Compare(status.CurrentLastWriteUtc, status.RecordedLastWriteUtc.AddSeconds(1.0)) > 0;
			status.LengthChanged = status.RecordedLength > 0 && status.CurrentLength != status.RecordedLength;
			status.ChangedSinceScan = modifiedSecondsDelta > 1.0;
		}
		catch (Exception ex)
		{
			ProjectData.SetProjectError(ex);
			Exception ex2 = ex;
			status.ErrorMessage = ex2.Message;
			ProjectData.ClearProjectError();
		}
		return status;
	}

	private static bool TryParseUtcStamp(string value, ref DateTime parsedUtc)
	{
		parsedUtc = DateTime.MinValue;
		if (string.IsNullOrWhiteSpace(value))
		{
			return false;
		}
		if (!DateTime.TryParse(value, CultureInfo.InvariantCulture, DateTimeStyles.AdjustToUniversal | DateTimeStyles.AssumeUniversal, out var parsed))
		{
			return false;
		}
		parsedUtc = parsed.ToUniversalTime();
		return true;
	}

	private void UpdateAggregateHealthContext()
	{
		int differenceCount = 0;
		int projectOnlyCount = 0;
		int loadAvailableCount = 0;
		checked
		{
			foreach (BrowserRow row in _loadableRows)
			{
				if (row != null)
				{
					if (MatchesFilterStatus(row.RawStatus, "FingerprintDifferent"))
					{
						differenceCount++;
					}
					if (MatchesFilterStatus(row.RawStatus, "ProjectOnly"))
					{
						projectOnlyCount++;
					}
					if (MatchesFilterStatus(row.RawStatus, "LoadAvailable"))
					{
						loadAvailableCount++;
					}
				}
			}
			foreach (SystemRow row2 in _systemComparisonRows)
			{
				if (row2 != null)
				{
					if (MatchesFilterStatus(row2.RawStatus, "FingerprintDifferent"))
					{
						differenceCount++;
					}
					if (MatchesFilterStatus(row2.RawStatus, "ProjectOnly"))
					{
						projectOnlyCount++;
					}
				}
			}
			foreach (SystemRow row3 in _systemRows)
			{
				if (row3 != null && MatchesFilterStatus(row3.RawStatus, "LoadAvailable"))
				{
					loadAvailableCount++;
				}
			}
			projectOnlyCount += CountUnregisteredDashboardRows();
			_healthText = T("Different: ", "차이 있음: ") + differenceCount.ToString(CultureInfo.InvariantCulture) + T(" / Load available: ", " / 로드 가능: ") + loadAvailableCount.ToString(CultureInfo.InvariantCulture);
			_projectOnlyText = T("Review needed: ", "검토 필요: ") + projectOnlyCount.ToString(CultureInfo.InvariantCulture);
			if (differenceCount > 0)
			{
				_nextWorkflowText = T("Review differences by trade, then approve update or keep project content.", "공종별 차이 항목을 검토한 뒤 업데이트 승인 또는 프로젝트 유지 여부를 결정하세요.");
			}
			else if (projectOnlyCount > 0)
			{
				_nextWorkflowText = T("Admins should review items that are not found in the registered standard.", "등록된 표준에 없는 항목은 관리자가 표준 편입 여부를 검토하세요.");
			}
			else if (loadAvailableCount > 0)
			{
				_nextWorkflowText = T("Missing approved items are shown for reference. Apply updates only changes families and system types already in the current project.", "누락된 승인 항목은 참고로 표시됩니다. 적용 작업은 현재 프로젝트에 이미 있는 패밀리와 시스템 타입만 갱신합니다.");
			}
			else
			{
				_nextWorkflowText = T("Current model aligns with registered standard snapshots.", "현재 모델이 등록된 표준 스냅샷과 일치합니다.");
			}
		}
	}

	private void UpdateModelerLightHealthContext()
	{
		int familyLoadAvailableCount = CountModelerFamily("LoadAvailable");
		int familyLoadedCount = CountModelerFamily("Latest");
		int systemLoadAvailableCount = CountModelerSystem("LoadAvailable");
		int systemLoadedCount = CountModelerSystem("Latest");
		checked
		{
			int reviewCount = CountModelerReviewNeeded() + CountUnregisteredDashboardRows();
			_healthText = T("Loaded: ", "로드됨: ") + (familyLoadedCount + systemLoadedCount).ToString(CultureInfo.InvariantCulture) + T(" / Load available: ", " / 로드 가능: ") + (familyLoadAvailableCount + systemLoadAvailableCount).ToString(CultureInfo.InvariantCulture);
			_projectOnlyText = T("Admin review: ", "관리자 검토: ") + reviewCount.ToString(CultureInfo.InvariantCulture);
			if (reviewCount > 0)
			{
				_nextWorkflowText = T("Some names already exist in a different category. Modelers can load only clear Load Available items; admins can review conflicts from Current Model Check.", "같은 이름이 다른 카테고리에 있는 항목이 있습니다. 모델러는 명확한 로드 가능 항목만 로드하고, 충돌은 관리자가 현재 모델 검사에서 검토합니다.");
			}
			else if (familyLoadAvailableCount > 0)
			{
				_nextWorkflowText = T("Select Load Available standard families and load them. Existing families are only marked as loaded; modeler view does not compare their content.", "로드 가능 표준 패밀리를 선택해 로드하세요. 이미 있는 패밀리는 로드됨으로만 표시하며, 모델러 화면에서는 내용 비교를 하지 않습니다.");
			}
			else if (systemLoadAvailableCount > 0)
			{
				_nextWorkflowText = T("Missing approved system types can be applied after duplicate/dependency validation.", "누락된 승인 시스템 타입은 중복/의존성 검증 후 적용할 수 있습니다.");
			}
			else
			{
				_nextWorkflowText = T("All visible approved items are already present by name/category in the current project.", "표시된 승인 항목은 현재 프로젝트에 이름/카테고리 기준으로 이미 있습니다.");
			}
		}
	}

	private int CountUnregisteredDashboardRows()
	{
		return checked(CountUnregisteredFamilyRows() + CountUnregisteredSystemRows());
	}

	private int CountUnregisteredFamilyRows()
	{
		if (_unregisteredFamilyRows != null)
		{
			return _unregisteredFamilyRows.Count;
		}
		return 0;
	}

	private int CountUnregisteredSystemRows()
	{
		if (_unregisteredSystemRows != null)
		{
			return _unregisteredSystemRows.Count;
		}
		return 0;
	}

	private void AppendLoadableRowsFromComparison(ProjectStandardComparisonReport report, StandardLibrarySnapshot standardSnapshot, StandardLibraryRegistrationRecord registration, string disciplineKey, string disciplineLabel)
	{
		if (report == null || report.LoadableFamilies == null)
		{
			return;
		}
		HashSet<string> nestedFamilyNames = BuildNestedLoadableNameSet(standardSnapshot);
		StandardListLoadableEntryIndex standardListFamilyIndex = BuildStandardListLoadableEntryIndex(_activeStandardListCatalog, disciplineKey, disciplineLabel);
		StandardFamilySnapshotLookup standardFamilyLookup = BuildStandardFamilySnapshotLookup(standardSnapshot);
		checked
		{
			foreach (LoadableFamilyComparisonItem item in report.LoadableFamilies.OrderBy([SpecialName] (LoadableFamilyComparisonItem x) => Normalize(x.CategoryName) + "|" + Normalize(x.FamilyName), StringComparer.Ordinal))
			{
				if (IsProjectOnlyComparisonItem(item))
				{
					AppendUnregisteredFamilyRowFromComparison(item);
				}
				else
				{
					if (!_adminModeEnabled && ShouldHideMatchedStandardStatus(item.Status))
					{
						continue;
					}
					bool allowedByStandardList = StandardListAllowsLoadable(standardListFamilyIndex, item.CategoryName, item.FamilyName);
					if (allowedByStandardList)
					{
						StandardLoadableFamilySnapshotItem standardFamily = FindStandardFamilySnapshot(standardFamilyLookup, item.CategoryName, item.FamilyName);
						if (!IsNestedLoadableChild(item, standardFamily, nestedFamilyNames) && !FamilyBrowserFamilyClassificationService.IsTypeManagedFamilyLike(item.CategoryName, (standardFamily == null) ? string.Empty : standardFamily.CategoryId, item.FamilyName))
						{
							string routingNote = BuildRoutingDependencyNote(item.CategoryName, (standardFamily == null) ? string.Empty : standardFamily.CategoryId);
							string memo = CombineMemo(BuildFamilyMemo(item), BuildStandardListReviewMemo(item, allowedByStandardList));
							string previewImagePath = ResolveComparisonPreviewImagePath(report, registration, item);
							IEnumerable<string> detailTypeNames = ResolveLoadableDetailTypeNames(item, standardFamily);
							string detailParameters = BuildLoadableDetailParameterPreviewText(item, standardFamily);
							IEnumerable<StandardNestedLoadableFamilySnapshotItem> detailNestedFamilies = ResolveLoadableDetailNestedFamilies(item);
							_loadableRows.Add(new BrowserRow
							{
								Status = DisplayLoadableComparisonStatus(item),
								RawStatus = item.Status,
								DisciplineKey = disciplineKey,
								DisciplineLabel = disciplineLabel,
								Name = item.FamilyName,
								Category = item.CategoryName,
								CategoryGroup = ResolveFamilyCategoryGroup(standardFamily, item.CategoryName, (standardFamily == null) ? string.Empty : standardFamily.CategoryId, item.FamilyName),
								Action = LoadableAction(item.Status),
								Notes = CombineMemo(memo, routingNote),
								ApprovedRev = T("Standard types: ", "표준 타입: ") + item.StandardTypeCount.ToString(CultureInfo.InvariantCulture),
								LoadedRev = T("Project types: ", "프로젝트 타입: ") + item.ProjectTypeCount.ToString(CultureInfo.InvariantCulture),
								ChangeSummary = BuildChangeSummary(item),
								DifferenceSummaryTable = BuildFingerprintDifferenceTableText(item),
								TypeSummary = BuildFamilyTypeSummary(detailTypeNames),
								ParameterSummary = detailParameters,
								NestedSummary = BuildNestedLoadableSummary(detailNestedFamilies),
								IsNestedLoadableChild = IsNestedLoadableChild(item, standardFamily, nestedFamilyNames),
								PreviewImagePath = previewImagePath
							});
							_loadableRows[_loadableRows.Count - 1].PreviewDiagnostic = BuildPreviewDiagnostic(registration, item.CategoryName, item.FamilyName, _loadableRows[_loadableRows.Count - 1].PreviewImagePath);
						}
					}
				}
			}
		}
	}

	private string DisplayLoadableComparisonStatus(LoadableFamilyComparisonItem item)
	{
		if (item != null && IsBasisMatch(item.Status, item.Notes))
		{
			return T("Matches Standard", "표준과 일치");
		}
		return DisplayStatus((item == null) ? string.Empty : item.Status);
	}

	private string ResolveComparisonPreviewImagePath(ProjectStandardComparisonReport report, StandardLibraryRegistrationRecord registration, LoadableFamilyComparisonItem item)
	{
		if (item == null)
		{
			return string.Empty;
		}
		string standardSourceId = registration?.SourceId ?? string.Empty;
		string standardPath = (string.IsNullOrWhiteSpace(standardSourceId) ? string.Empty : FamilyThumbnailPreviewService.ResolveExistingCachedImagePath(_workspaceRoot, standardSourceId, item.CategoryName, item.FamilyName));
		string raw = Normalize(item.Status);
		string projectSourceId = report?.Project?.ThumbnailSourceId ?? string.Empty;
		if (Operators.CompareString(raw, "loadavailable", TextCompare: false) != 0 && !string.IsNullOrWhiteSpace(projectSourceId))
		{
			string projectPath = FamilyThumbnailPreviewService.ResolveExistingCachedImagePath(_workspaceRoot, projectSourceId, item.CategoryName, item.FamilyName);
			if (File.Exists(projectPath))
			{
				return projectPath;
			}
		}
		return standardPath;
	}

	private IEnumerable<string> ResolveLoadableDetailTypeNames(LoadableFamilyComparisonItem item, StandardLoadableFamilySnapshotItem standardFamily)
	{
		if (ShouldShowProjectLoadableDetail(item))
		{
			return item.ProjectTypeNames ?? new List<string>();
		}
		if (standardFamily != null)
		{
			return standardFamily.TypeNames ?? new List<string>();
		}
		return item?.ExtraTypeNames ?? new List<string>();
	}

	private IEnumerable<StandardNestedLoadableFamilySnapshotItem> ResolveLoadableDetailNestedFamilies(LoadableFamilyComparisonItem item)
	{
		if (ShouldShowProjectLoadableDetail(item))
		{
			return item.ProjectNestedLoadableFamilies ?? new List<StandardNestedLoadableFamilySnapshotItem>();
		}
		return item?.NestedLoadableFamilies ?? new List<StandardNestedLoadableFamilySnapshotItem>();
	}

	private string BuildLoadableDetailParameterPreviewText(LoadableFamilyComparisonItem item, StandardLoadableFamilySnapshotItem standardFamily)
	{
		if (ShouldShowProjectLoadableDetail(item))
		{
			return BuildParameterPreviewText(item.ProjectParameters ?? new List<StandardFamilyParameterSnapshotItem>(), item.ProjectTypeCount, T("No current project parameter data was captured for this family.", "현재 프로젝트에서 캡처된 이 패밀리의 파라미터 데이터가 없습니다."), T("No captured shared parameter data in the current project scan.", "현재 프로젝트 스캔에서 캡처된 공유 파라미터 데이터가 없습니다."));
		}
		return BuildParameterPreviewText(standardFamily);
	}

	private bool ShouldShowProjectLoadableDetail(LoadableFamilyComparisonItem item)
	{
		if (_adminModeEnabled)
		{
			return item != null;
		}
		return false;
	}

