	private string BuildPreviewDiagnostic(StandardLibraryRegistrationRecord registration, string categoryName, string familyName, string previewPath)
	{
		List<string> lines = new List<string> { T("3D snapshot is not displayed.", "3D 스냅샷이 표시되지 않았습니다.") };
		if (registration == null)
		{
			lines.Add(T("Reason: standard RVT is not registered for this target.", "원인: 이 대상에 표준 RVT가 등록되지 않았습니다."));
			lines.Add(T("Next: refresh the homepage path, register the standard RVT, then regenerate 3D images.", "다음: 홈페이지 경로를 다시 확인하고 표준 RVT를 등록한 뒤 3D 이미지를 재생성하세요."));
			return string.Join(Environment.NewLine, lines);
		}
		string cacheFolder;
		try
		{
			cacheFolder = FamilyThumbnailPreviewService.GetCacheFolder(_workspaceRoot, registration.SourceId);
		}
		catch (Exception ex)
		{
			ProjectData.SetProjectError(ex);
			Exception ex2 = ex;
			cacheFolder = T("Could not resolve thumbnail folder: ", "썸네일 폴더를 확인할 수 없음: ") + ex2.Message;
			ProjectData.ClearProjectError();
		}
		lines.Add(T("Source: ", "소스: ") + (string.IsNullOrWhiteSpace(registration.SourceId) ? "-" : registration.SourceId));
		lines.Add(T("Family: ", "패밀리: ") + (string.IsNullOrWhiteSpace(categoryName) ? "-" : categoryName) + " / " + (string.IsNullOrWhiteSpace(familyName) ? "-" : familyName));
		lines.Add(T("Folder: ", "폴더: ") + (string.IsNullOrWhiteSpace(cacheFolder) ? "-" : cacheFolder));
		lines.Add(T("Expected file: ", "예상 파일: ") + (string.IsNullOrWhiteSpace(previewPath) ? "-" : previewPath));
		if (string.IsNullOrWhiteSpace(previewPath))
		{
			lines.Add(T("Reason: preview file path was not created.", "원인: 미리보기 파일 경로가 만들어지지 않았습니다."));
		}
		else if (File.Exists(previewPath))
		{
			lines.Add(T("The PNG exists. The browser view uses a managed preview display cache copy.", "PNG 파일은 존재합니다. 브라우저 표시는 공용 관리폴더의 미리보기 표시용 캐시 복사본을 사용합니다."));
		}
		else
		{
			lines.Add(T("The expected PNG does not exist yet.", "예상 PNG 파일이 아직 없습니다."));
			lines.Add(T("If the preview remains blank, run 3D Image Regenerate for the registered standard RVT.", "미리보기가 계속 비어 있으면 등록된 표준 RVT에서 3D 이미지 재생성을 실행하세요."));
		}
		return string.Join(Environment.NewLine, lines);
	}

	private void AppendSystemRowsFromComparison(ProjectStandardComparisonReport report, string disciplineKey, string disciplineLabel)
	{
		if (report == null || report.SystemTypes == null)
		{
			return;
		}
		StandardListSystemEntryIndex standardListSystemIndex = BuildStandardListSystemEntryIndex(_activeStandardListCatalog, disciplineKey, disciplineLabel);
		if (standardListSystemIndex.WildcardTypeEntries.Count == 0 && standardListSystemIndex.EntriesByTypeToken.Count == 0)
		{
			return;
		}
		foreach (SystemTypeComparisonItem item in report.SystemTypes.OrderBy([SpecialName] (SystemTypeComparisonItem x) => Normalize(x.CategoryName) + "|" + Normalize(x.TypeName), StringComparer.Ordinal))
		{
			if (IsProjectOnlyComparisonItem(item))
			{
				AppendUnregisteredSystemRowFromComparison(item);
			}
			else if ((_adminModeEnabled || !ShouldHideMatchedStandardStatus(item.Status)) && StandardListAllowsExplicitSystem(standardListSystemIndex, item.CategoryName, item.TypeClassName, item.TypeName))
			{
				SystemRow systemRow = new SystemRow
				{
					Status = DisplaySystemComparisonStatus(item.Status, item.Notes),
					RawStatus = item.Status,
					DisciplineKey = disciplineKey,
					DisciplineLabel = disciplineLabel,
					Name = item.TypeName,
					Category = (string.IsNullOrWhiteSpace(item.CategoryName) ? item.TypeClassName : item.CategoryName),
					SystemFamilyKind = item.TypeClassName,
					Action = SystemCompareAction(item.Status),
					Notes = TranslateNote(item.Notes),
					LayerSummary = BuildSystemLayerSummary(item.Layers),
					DifferenceSummaryTable = BuildSystemDifferenceTableText(item)
				};
				_systemRows.Add(systemRow);
				_systemComparisonRows.Add(systemRow);
			}
		}
	}

	private string DisplaySystemComparisonStatus(string status, string notes)
	{
		if (IsBasisMatch(status, notes))
		{
			return T("Matches Standard", "표준과 일치");
		}
		return DisplayStatus(status);
	}

