	}

	private void RebuildUnregisteredRowsFromProjectLightInfo(IEnumerable<ProjectFamilyLightInfo> projectFamilies, IEnumerable<ProjectSystemTypeLightInfo> projectSystemTypes, IEnumerable<ModelerStandardSnapshotContext> contexts)
	{
		_unregisteredFamilyRows = new List<UnregisteredProjectItemRow>();
		_unregisteredSystemRows = new List<UnregisteredProjectItemRow>();
