		List<ModelerStandardSnapshotContext> contextList = (contexts ?? Enumerable.Empty<ModelerStandardSnapshotContext>()).Where([SpecialName] (ModelerStandardSnapshotContext x) => x != null).ToList();
		if (contextList.Count == 0)
		{
			_unregisteredListStatusText = T("No registered standard snapshot/list is ready, so unregistered project items cannot be classified.", "등록된 표준 스냅샷/목록이 준비되지 않아 미등록 프로젝트 항목을 판정할 수 없습니다.");
			return;
		}
		List<ModelerStandardSnapshotContext> filteringContexts = contextList.Where([SpecialName] (ModelerStandardSnapshotContext x) => FamilyBrowserStandardListService.IsFilteringEnabled(x.Catalog)).ToList();
		if (filteringContexts.Count == 0)
		{
			_unregisteredListStatusText = T("No approved standard Excel/JSON list is connected. Unregistered items are classified only after the approved list exists.", "승인된 표준 Excel/JSON 목록이 연결되지 않았습니다. 미등록 항목은 승인 목록이 있어야 판정할 수 있습니다.");
			return;
		}
		HashSet<string> approvedFamilyTokens = new HashSet<string>(StringComparer.Ordinal);
		HashSet<string> nestedFamilyTokens = new HashSet<string>(StringComparer.Ordinal);
		HashSet<string> standardSnapshotFamilyTokens = new HashSet<string>(StringComparer.Ordinal);
		HashSet<string> standardSnapshotSystemKeys = new HashSet<string>(StringComparer.Ordinal);
		HashSet<string> standardSnapshotSystemTypeTokens = new HashSet<string>(StringComparer.Ordinal);
		foreach (ModelerStandardSnapshotContext context in filteringContexts)
		{
			if (context.LoadableIndex != null && context.LoadableIndex.EntriesByFamilyToken != null)
			{
				foreach (string key in context.LoadableIndex.EntriesByFamilyToken.Keys)
				{
					if (!string.IsNullOrWhiteSpace(key))
					{
						approvedFamilyTokens.Add(key);
					}
				}
			}
			foreach (string nestedName in BuildNestedLoadableNameSet(context.Snapshot))
			{
				nestedFamilyTokens.Add(nestedName);
			}
			if (context.Snapshot != null && context.Snapshot.LoadableFamilies != null)
			{
				foreach (StandardLoadableFamilySnapshotItem item in context.Snapshot.LoadableFamilies)
				{
					if (item != null && !string.IsNullOrWhiteSpace(item.FamilyName))
					{
						string familyToken = StandardListFoldToken(item.FamilyName);
						standardSnapshotFamilyTokens.Add(familyToken);
						if (context.LoadableIndex != null && StandardListAllowsLoadable(context.LoadableIndex, item.CategoryName, item.FamilyName))
						{
							approvedFamilyTokens.Add(familyToken);
						}
					}
				}
			}
			if (context.Snapshot == null || context.Snapshot.SystemTypes == null)
			{
				continue;
			}
			foreach (StandardSystemTypeSnapshotItem item2 in context.Snapshot.SystemTypes)
			{
				if (item2 != null && !string.IsNullOrWhiteSpace(item2.TypeName))
				{
					standardSnapshotSystemTypeTokens.Add(StandardListFoldToken(item2.TypeName));
					standardSnapshotSystemKeys.Add(BuildProjectSystemTypeLightLookupKey(item2.TypeClassName, item2.TypeName));
				}
			}
		}
		HashSet<string> seenFamilies = new HashSet<string>(StringComparer.Ordinal);
		foreach (ProjectFamilyLightInfo projectFamily in projectFamilies ?? Enumerable.Empty<ProjectFamilyLightInfo>())
		{
			if (projectFamily == null || string.IsNullOrWhiteSpace(projectFamily.FamilyName) || FamilyBrowserFamilyClassificationService.IsTypeManagedFamilyLike(projectFamily.CategoryName, projectFamily.CategoryId, projectFamily.FamilyName))
			{
				continue;
			}
			string familyToken2 = StandardListFoldToken(projectFamily.FamilyName);
			if (!string.IsNullOrWhiteSpace(familyToken2) && !approvedFamilyTokens.Contains(familyToken2) && !nestedFamilyTokens.Contains(Normalize(projectFamily.FamilyName)))
			{
				string rowKey = Normalize(projectFamily.CategoryName) + "|" + Normalize(projectFamily.FamilyName);
				if (seenFamilies.Add(rowKey))
				{
					string note = (standardSnapshotFamilyTokens.Contains(familyToken2) ? T("This family exists in a registered standard RVT snapshot but is not in the approved Excel/JSON list.", "등록 표준 RVT 스냅샷에는 있지만 승인 Excel/JSON 목록에는 없는 패밀리입니다.") : T("This project family is not found in the approved Excel/JSON list for the registered standard targets.", "등록된 표준 대상의 승인 Excel/JSON 목록에서 찾을 수 없는 프로젝트 패밀리입니다."));
					_unregisteredFamilyRows.Add(new UnregisteredProjectItemRow
					{
						ItemKind = T("Family", "패밀리"),
						Name = projectFamily.FamilyName,
						CategoryName = projectFamily.CategoryName,
						TypeClassName = string.Empty,
						Notes = note,
						Source = T("Fast project scan", "프로젝트 빠른 스캔")
					});
				}
			}
		}
		HashSet<string> seenSystems = new HashSet<string>(StringComparer.Ordinal);
		foreach (ProjectSystemTypeLightInfo projectSystem in projectSystemTypes ?? Enumerable.Empty<ProjectSystemTypeLightInfo>())
		{
			if (projectSystem != null && !string.IsNullOrWhiteSpace(projectSystem.TypeName) && !ProjectSystemTypeIsApprovedByAnyContext(projectSystem, filteringContexts))
			{
				string rowKey2 = BuildProjectSystemTypeLightLookupKey(projectSystem.TypeClassName, projectSystem.TypeName) + "|" + Normalize(projectSystem.CategoryName);
				if (seenSystems.Add(rowKey2))
				{
					string systemKey = BuildProjectSystemTypeLightLookupKey(projectSystem.TypeClassName, projectSystem.TypeName);
					string typeToken = StandardListFoldToken(projectSystem.TypeName);
					string note2 = ((!standardSnapshotSystemKeys.Contains(systemKey) && !standardSnapshotSystemTypeTokens.Contains(typeToken)) ? T("This project system type is outside the approved Excel/JSON list for the registered standard targets.", "등록된 표준 대상의 승인 Excel/JSON 목록 밖에 있는 프로젝트 시스템 타입입니다.") : T("This system type exists in a registered standard RVT snapshot but is not approved by the Excel/JSON list for this category/class.", "등록 표준 RVT 스냅샷에는 있지만 이 카테고리/종류 기준 승인 Excel/JSON 목록에는 없는 시스템 타입입니다."));
					_unregisteredSystemRows.Add(new UnregisteredProjectItemRow
					{
						ItemKind = T("System Type", "시스템 타입"),
						Name = projectSystem.TypeName,
						CategoryName = projectSystem.CategoryName,
						TypeClassName = projectSystem.TypeClassName,
						Notes = note2,
						Source = T("Fast project scan", "프로젝트 빠른 스캔")
					});
				}
			}
		}
		WriteDashboardRuntimeDiagnostic("unregistered-fast-scan families=" + _unregisteredFamilyRows.Count.ToString(CultureInfo.InvariantCulture) + " systems=" + _unregisteredSystemRows.Count.ToString(CultureInfo.InvariantCulture), -1, -1L);
	}

	private void EnsureUnregisteredRowsInitialized()
