		}
		if (_unregisteredSystemRows == null)
		{
			_unregisteredSystemRows = new List<UnregisteredProjectItemRow>();
		}
	}

	private void AppendUnregisteredFamilyRowFromComparison(LoadableFamilyComparisonItem item)
	{
		if (item != null && !string.IsNullOrWhiteSpace(item.FamilyName) && !FamilyBrowserFamilyClassificationService.IsTypeManagedFamilyLike(item.CategoryName, string.Empty, item.FamilyName))
		{
			EnsureUnregisteredRowsInitialized();
			string b = Normalize(item.CategoryName) + "|" + Normalize(item.FamilyName);
			if (!_unregisteredFamilyRows.Any([SpecialName] (UnregisteredProjectItemRow row) => row != null && string.Equals(Normalize(row.CategoryName) + "|" + Normalize(row.Name), b, StringComparison.Ordinal)))
			{
				_unregisteredFamilyRows.Add(new UnregisteredProjectItemRow
				{
					ItemKind = T("Family", "패밀리"),
					Name = item.FamilyName,
					CategoryName = item.CategoryName,
					TypeClassName = string.Empty,
					Notes = T("This project family is not registered in the selected standard RVT/list. It is excluded from the load list and routed here for administrator review.", "이 프로젝트 패밀리는 선택한 표준 RVT/목록에 등록되어 있지 않습니다. 로드 리스트에서는 제외하고 관리자 검토용으로 이 탭에 표시합니다."),
					Source = T("Current model comparison", "현재 모델 비교")
				});
				_unregisteredListStatusText = string.Empty;
			}
		}
	}

	private void AppendUnregisteredSystemRowFromComparison(SystemTypeComparisonItem item)
	{
		if (item != null && !string.IsNullOrWhiteSpace(item.TypeName))
		{
			EnsureUnregisteredRowsInitialized();
			string b = Normalize(item.TypeClassName) + "|" + Normalize(item.CategoryName) + "|" + Normalize(item.TypeName);
			if (!_unregisteredSystemRows.Any([SpecialName] (UnregisteredProjectItemRow row) => row != null && string.Equals(Normalize(row.TypeClassName) + "|" + Normalize(row.CategoryName) + "|" + Normalize(row.Name), b, StringComparison.Ordinal)))
			{
				_unregisteredSystemRows.Add(new UnregisteredProjectItemRow
				{
					ItemKind = T("System Type", "시스템 타입"),
					Name = item.TypeName,
					CategoryName = item.CategoryName,
					TypeClassName = item.TypeClassName,
					Notes = T("This project system type is not registered in the selected standard RVT/list. It is excluded from the system type load list and routed here for administrator review.", "이 프로젝트 시스템 타입은 선택한 표준 RVT/목록에 등록되어 있지 않습니다. 시스템 타입 로드 리스트에서는 제외하고 관리자 검토용으로 이 탭에 표시합니다."),
					Source = T("Current model comparison", "현재 모델 비교")
				});
				_unregisteredListStatusText = string.Empty;
			}
		}
	}

	private static bool ProjectSystemTypeIsApprovedByAnyContext(ProjectSystemTypeLightInfo projectSystem, IEnumerable<ModelerStandardSnapshotContext> contexts)
	{
		if (projectSystem == null || contexts == null)
		{
			return false;
		}
		foreach (ModelerStandardSnapshotContext context in contexts)
		{
			if (context != null && context.SystemIndex != null && StandardListAllowsExplicitSystem(context.SystemIndex, projectSystem.CategoryName, projectSystem.TypeClassName, projectSystem.TypeName))
			{
				return true;
			}
		}
		return false;
	}

	private static void AddStandardListEntry(Dictionary<string, List<FamilyBrowserStandardListEntry>> index, string token, FamilyBrowserStandardListEntry entry)
	{
		if (index != null && !string.IsNullOrWhiteSpace(token) && entry != null)
		{
			List<FamilyBrowserStandardListEntry> entries = null;
			if (!index.TryGetValue(token, out entries) || entries == null)
			{
				entries = (index[token] = new List<FamilyBrowserStandardListEntry>());
			}
			entries.Add(entry);
		}
	}

	private static HashSet<string> BuildStandardListSystemTypeTokenSet(FamilyBrowserStandardListCatalog catalog, string disciplineKey, string disciplineLabel)
	{
		_Closure_0024__346_002D0 arg = default(_Closure_0024__346_002D0);
		_Closure_0024__346_002D0 CS_0024_003C_003E8__locals6 = new _Closure_0024__346_002D0(arg);
		CS_0024_003C_003E8__locals6._0024VB_0024Local_disciplineKey = disciplineKey;
		CS_0024_003C_003E8__locals6._0024VB_0024Local_disciplineLabel = disciplineLabel;
		HashSet<string> result = new HashSet<string>(StringComparer.Ordinal);
		if (!FamilyBrowserStandardListService.IsFilteringEnabled(catalog))
		{
			return result;
		}
		bool hasDisciplineSpecificRows = catalog.Entries.Any([SpecialName] (FamilyBrowserStandardListEntry familyBrowserStandardListEntry) => StandardListDisciplineMatches((familyBrowserStandardListEntry == null) ? string.Empty : familyBrowserStandardListEntry.Discipline, CS_0024_003C_003E8__locals6._0024VB_0024Local_disciplineKey, CS_0024_003C_003E8__locals6._0024VB_0024Local_disciplineLabel));
		foreach (FamilyBrowserStandardListEntry entry in catalog.Entries)
		{
			if (entry != null && !string.IsNullOrWhiteSpace(entry.TypeName) && StandardListEntryAppliesToDiscipline(entry, CS_0024_003C_003E8__locals6._0024VB_0024Local_disciplineKey, CS_0024_003C_003E8__locals6._0024VB_0024Local_disciplineLabel, hasDisciplineSpecificRows))
			{
				result.Add(StandardListFoldToken(entry.TypeName));
			}
		}
		return result;
	}

	private static bool StandardListEntryAppliesToDiscipline(FamilyBrowserStandardListEntry entry, string disciplineKey, string disciplineLabel, bool hasDisciplineSpecificRows)
	{
		if (entry == null || string.IsNullOrWhiteSpace(entry.Discipline))
		{
			return true;
		}
		if (!hasDisciplineSpecificRows)
		{
			return true;
		}
		return StandardListDisciplineMatches(entry.Discipline, disciplineKey, disciplineLabel);
	}

	private static bool StandardListDisciplineMatches(string entryDiscipline, string disciplineKey, string disciplineLabel)
	{
		if (string.IsNullOrWhiteSpace(entryDiscipline))
		{
			return true;
		}
		return StandardListSimilarToken(entryDiscipline, disciplineKey) || StandardListSimilarToken(entryDiscipline, disciplineLabel);
	}

	private static bool StandardListSimilarToken(string leftValue, string rightValue)
	{
		string left = StandardListFoldToken(leftValue);
		string right = StandardListFoldToken(rightValue);
		if (string.IsNullOrWhiteSpace(left) || string.IsNullOrWhiteSpace(right))
		{
			return false;
		}
		if (string.Equals(left, right, StringComparison.Ordinal))
		{
			return true;
		}
		checked
		{
			if (left.EndsWith("s", StringComparison.Ordinal) && string.Equals(left.Substring(0, left.Length - 1), right, StringComparison.Ordinal))
			{
				return true;
			}
			if (right.EndsWith("s", StringComparison.Ordinal) && string.Equals(right.Substring(0, right.Length - 1), left, StringComparison.Ordinal))
			{
				return true;
			}
			return left.Length >= 5 && right.Length >= 5 && (left.IndexOf(right, StringComparison.Ordinal) >= 0 || right.IndexOf(left, StringComparison.Ordinal) >= 0);
		}
	}

	private static string StandardListFoldToken(string value)
	{
		return (value ?? string.Empty).Trim().Replace(" ", string.Empty).Replace("_", string.Empty)
			.Replace("-", string.Empty)
			.Replace(".", string.Empty)
			.Replace("/", string.Empty)
			.Replace("\\", string.Empty)
			.ToLowerInvariant();
	}

	private static bool ShouldHideMatchedStandardStatus(string status)
	{
		string raw = Normalize(status);
		if (Operators.CompareString(raw, "loadedlatest", TextCompare: false) != 0 && Operators.CompareString(raw, "latest", TextCompare: false) != 0)
		{
			return Operators.CompareString(raw, "nochange", TextCompare: false) == 0;
		}
		return true;
	}

	private static bool IsProjectOnlyComparisonItem(LoadableFamilyComparisonItem item)
	{
		if (item != null)
		{
			return string.Equals(Normalize(item.Status), "projectonly", StringComparison.Ordinal);
		}
		return false;
	}

	private static bool IsProjectOnlyComparisonItem(SystemTypeComparisonItem item)
	{
		if (item != null)
		{
			return string.Equals(Normalize(item.Status), "projectonly", StringComparison.Ordinal);
		}
		return false;
	}

	private static bool IsAdminStandardListReviewFamily(LoadableFamilyComparisonItem item)
	{
		return IsProjectOnlyComparisonItem(item);
	}

	private bool ShouldHideStandardListNestedLoadableChild(LoadableFamilyComparisonItem item, StandardLoadableFamilySnapshotItem standardFamily, HashSet<string> nestedFamilyNames)
	{
		return IsNestedLoadableChild(item, standardFamily, nestedFamilyNames);
	}

	private static bool IsNestedLoadableChild(LoadableFamilyComparisonItem item, StandardLoadableFamilySnapshotItem standardFamily, HashSet<string> nestedFamilyNames)
	{
		if (standardFamily != null && standardFamily.IsNestedLoadableChild)
		{
			return standardFamily.IsShared && IsModelLoadableFamily(standardFamily);
		}
		if (item != null && item.IsNestedLoadableChild)
		{
			return standardFamily != null && standardFamily.IsShared && IsModelLoadableFamily(standardFamily);
		}
		return item != null && nestedFamilyNames != null && nestedFamilyNames.Contains(Normalize(item.FamilyName));
	}

	private bool ShouldHideStandardListNestedLoadableChild(StandardLoadableFamilySnapshotItem item, HashSet<string> nestedFamilyNames)
	{
		if (item != null && item.IsShared && IsModelLoadableFamily(item))
		{
			if (!item.IsNestedLoadableChild)
			{
				return nestedFamilyNames?.Contains(Normalize(item.FamilyName)) ?? false;
			}
			return true;
		}
		return false;
	}

	private static void MergeSystemTypesIntoSnapshot(ProjectContentSnapshot target, ProjectContentSnapshot source)
	{
		if (target == null || source == null)
		{
			return;
		}
		target.SystemTypes = source.SystemTypes ?? new List<ProjectSystemTypeSnapshotItem>();
		if (target.Summary == null)
		{
			target.Summary = new ProjectContentSnapshotSummary();
		}
		if (source.Summary == null)
		{
			target.Summary.SystemTypeCount = target.SystemTypes.Count;
			target.Summary.SystemTypeClassCount = target.SystemTypes.Select([SpecialName] (ProjectSystemTypeSnapshotItem x) => x.TypeClassName).Distinct(StringComparer.OrdinalIgnoreCase).Count();
		}
		else
		{
			target.Summary.SystemTypeCount = source.Summary.SystemTypeCount;
			target.Summary.SystemTypeClassCount = source.Summary.SystemTypeClassCount;
		}
	}

	private string BuildSystemComparisonSummary()
	{
		int latestCount = 0;
		int loadAvailableCount = 0;
		int differentCount = 0;
		int categoryMismatchCount = 0;
		int reviewCount = 0;
		checked
		{
			foreach (SystemRow row in _systemRows)
			{
				if (row != null)
				{
					if (MatchesFilterStatus(row.RawStatus, "Latest"))
					{
						latestCount++;
					}
					if (MatchesFilterStatus(row.RawStatus, "LoadAvailable"))
					{
						loadAvailableCount++;
					}
					if (MatchesFilterStatus(row.RawStatus, "FingerprintDifferent"))
					{
						differentCount++;
					}
					if (MatchesFilterStatus(row.RawStatus, "CategoryMismatch"))
					{
						categoryMismatchCount++;
					}
					if (MatchesFilterStatus(row.RawStatus, "ProjectOnly") || MatchesFilterStatus(row.RawStatus, "ManualReview"))
					{
						reviewCount++;
					}
				}
			}
			reviewCount += CountUnregisteredSystemRows();
			if (!_adminModeEnabled)
			{
				return T("Modeler system list: loaded ", "모델러 시스템 목록: 로드됨 ") + latestCount.ToString(CultureInfo.InvariantCulture) + T(" / missing ", " / 현재 프로젝트에 없음 ") + loadAvailableCount.ToString(CultureInfo.InvariantCulture) + T(" / category review ", " / 카테고리 검토 ") + categoryMismatchCount.ToString(CultureInfo.InvariantCulture);
			}
			return T("Fast system comparison: latest ", "빠른 시스템 비교: 최신 ") + latestCount.ToString(CultureInfo.InvariantCulture) + T(" / missing ", " / 현재 프로젝트에 없음 ") + loadAvailableCount.ToString(CultureInfo.InvariantCulture) + T(" / different ", " / 차이 ") + differentCount.ToString(CultureInfo.InvariantCulture) + T(" / category review ", " / 카테고리 검토 ") + categoryMismatchCount.ToString(CultureInfo.InvariantCulture) + T(" / admin review ", " / 관리자 검토 ") + reviewCount.ToString(CultureInfo.InvariantCulture);
		}
	}

