				int missingCount = 0;
				int snapshotMissingCount = 0;
				StandardLibraryRegistrationRecord selectedRegistration = null;
				bool selectedSnapshotMissing = false;
				FamilyBrowserStandardLibrarySlot firstReadySlot = null;
				StandardLibraryRegistrationRecord firstReadyRegistration = null;
				foreach (FamilyBrowserStandardLibrarySlot slot in browseSlots)
				{
					string registryPath = ResolveRegistrationPathForSlot(_standardPolicy, slot);
					bool isSelectedSlot = SlotMatches(slot, browseSlot);
					if (string.IsNullOrWhiteSpace(registryPath) || !File.Exists(registryPath))
					{
						missingCount++;
						continue;
					}
					StandardLibraryRegistrationRecord registration = LoadStandardRegistrationForDashboard(registryPath);
					if (registration == null)
					{
						missingCount++;
						continue;
					}
					if (string.IsNullOrWhiteSpace(registration.LastSnapshotPath))
					{
						snapshotMissingCount++;
						if (isSelectedSlot)
						{
							selectedSnapshotMissing = true;
						}
						continue;
					}
					registeredCount++;
					if (firstReadyRegistration == null)
					{
						firstReadySlot = slot;
						firstReadyRegistration = registration;
					}
					if (isSelectedSlot)
					{
						selectedRegistration = registration;
					}
				}
				SelectFirstReadyBrowseSlotIfImplicit(ref browseSlot, ref selectedRegistration, ref selectedSnapshotMissing, firstReadySlot, firstReadyRegistration);
				if (selectedRegistration == null)
				{
					_activeStandardScanNeeded = selectedSnapshotMissing;
					_standardText = BuildRegisteredStandardSummaryText(registeredCount, missingCount, snapshotMissingCount);
					_loadText = T("Load Available: 0", "로드 가능: 0");
					_updateText = T("Update Available: 0", "업데이트 가능: 0");
					_permissionText = (selectedSnapshotMissing ? ScanNeededPermissionText() : T("Permission: Register required", "권한: 표준 등록 필요"));
					_trackingText = (selectedSnapshotMissing ? ScanNeededTrackingText() : T("Tracking: register first", "추적: 표준 등록 필요"));
					_trackingTone = (selectedSnapshotMissing ? "bad" : "warn");
					string targetLabel = ((browseSlot == null) ? BuildBrowserStandardScopeLabel(_standardPolicy) : ResolveSlotLabel(browseSlot));
					if (selectedSnapshotMissing)
					{
						_statusMessage = StandardScanNeededUserAction() + " " + T("Target: ", "대상: ") + targetLabel;
					}
					else
					{
						_statusMessage = T("Selected trade has no registered standard RVT: ", "선택한 공종의 표준 RVT가 등록되지 않았습니다: ") + targetLabel;
					}
					_systemSummary = T("System comparison needs a registered standard RVT.", "시스템 비교에는 등록된 표준 RVT가 필요합니다.");
					_nextWorkflowText = (selectedSnapshotMissing ? StandardScanNeededUserAction() : T("Select a trade with a registered standard RVT, or connect the approved RVT in admin settings.", "등록된 표준 RVT가 있는 공종을 선택하거나 관리자 설정에서 승인 RVT를 연결하세요."));
					_projectScanText = (selectedSnapshotMissing ? StandardScanNeededUserAction() : T("Current project is open, but comparison is waiting for a registered standard RVT.", "현재 프로젝트는 열려 있지만 등록된 표준 RVT가 없어 비교 대기 중입니다."));
					RefreshRequestsAndAudit();
					RenderDashboard();
					return;
				}
				_registration = selectedRegistration;
				UpdateStandardContext(_registration);
				StandardLibrarySnapshot standardSnapshot = null;
				try
				{
					standardSnapshot = LoadStandardSnapshotForDashboard(selectedRegistration.LastSnapshotPath);
				}
				catch (Exception projectError)
				{
					ProjectData.SetProjectError(projectError);
					standardSnapshot = null;
					ProjectData.ClearProjectError();
				}
				if (standardSnapshot == null)
				{
					_activeStandardScanNeeded = true;
					_standardText = BuildRegisteredStandardSummaryText(registeredCount, missingCount, snapshotMissingCount + 1);
					_loadText = T("Load Available: 0", "로드 가능: 0");
					_updateText = T("Update Available: 0", "업데이트 가능: 0");
					_permissionText = ScanNeededPermissionText();
					_trackingText = ScanNeededTrackingText();
					_trackingTone = "bad";
					_statusMessage = StandardScanNeededUserAction();
					_projectScanText = StandardScanNeededUserAction();
					RefreshRequestsAndAudit();
					RenderDashboard();
					return;
				}
				string disciplineKey = ResolveSlotKey(browseSlot);
				string disciplineLabel = ResolveSlotLabel(browseSlot);
				_activeStandardListCatalog = LoadStandardListCatalogForDashboard(browseSlot, selectedRegistration);
				if (!deepProjectScan)
				{
					RebuildModelerRowsFromRegisteredStandardSlotsLight(doc, browseSlots, browseSlot, selectedRegistration);
					_standardText = BuildRegisteredStandardSummaryText(registeredCount, missingCount, snapshotMissingCount);
					UpdateSecurityContext(_standardPolicy);
					EnsureAdminModeAllowed(_standardPolicy);
					_loadText = T("Load Available: ", "로드 가능: ") + CountDashboardLoadAvailable().ToString(CultureInfo.InvariantCulture);
					_updateText = T("Update Available: ", "업데이트 가능: ") + CountDashboardUpdateAvailable().ToString(CultureInfo.InvariantCulture);
					UpdateModelerLightHealthContext();
					_systemSummary = BuildSystemComparisonSummary();
					_projectScanText = T("Fast browser list checked only current project family/type names and categories. No fingerprint, parameter, snapshot, standard RVT scan, or comparison report was run.", "빠른 브라우저 목록은 현재 프로젝트의 패밀리/타입 이름과 카테고리만 확인했습니다. Fingerprint, 파라미터, 스냅샷, 표준 RVT 스캔, 비교 리포트는 실행하지 않았습니다.");
					_statusMessage = T("Family Browser loaded the registered standard snapshot and marked current-project loaded status by name/category only.", "등록된 표준 스냅샷을 읽고 현재 프로젝트 로드 상태만 이름/카테고리 기준으로 표시했습니다.");
					RefreshRequestsAndAudit();
					RenderDashboard();
					return;
				}
				ProjectStandardComparisonReport report = null;
				ProjectContentSnapshot projectSnapshotForModelerRows = null;
				string comparisonCacheKey = BuildFastComparisonCacheKey(doc, selectedRegistration, standardSnapshot, browseSlot, _activeStandardListCatalog, trackingCatalog);
				string cachedProjectScanText = string.Empty;
				List<FamilyThumbnailAutoConfirmedDialogRecord> currentModelAutoDialogs = new List<FamilyThumbnailAutoConfirmedDialogRecord>();
				if (deepProjectScan)
				{
					string operationTitle = T("Current Model Check", "현재 모델 검사");
					bool includeDeepProjectContent = ShouldRunPreciseProjectContentCheck(standardSnapshot);
					BeginLongOperationProgress(operationTitle, T("Reading current project content...", "현재 프로젝트 내용을 읽는 중..."));
					ProjectContentSnapshot projectSnapshot = null;
					using (FamilyThumbnailConstraintDialogGuard dialogGuard = new FamilyThumbnailConstraintDialogGuard(_uiApplication))
					{
						string fingerprintDebugRunFolder = FingerprintDebugSignatureStore.CreateProjectRunFolder(_workspaceRoot, doc.Title ?? string.Empty, DateTime.UtcNow.ToString("O", CultureInfo.InvariantCulture), ProjectSnapshotStore.ResolveProjectIdentityPath(doc));
						projectSnapshot = ProjectSnapshotCaptureService.Capture(doc, null, includeDeepProjectContent, CreateLongOperationProgressCallback(operationTitle), fingerprintDebugRunFolder, dialogGuard);
						currentModelAutoDialogs = dialogGuard.GetRecordsSince(0);
					}
					if (includeDeepProjectContent)
					{
						EnsurePreciseProjectLoadableFingerprints(projectSnapshot, operationTitle);
					}
					projectSnapshotForModelerRows = projectSnapshot;
					_projectScanText = (includeDeepProjectContent ? T("Precise Current Model Check read current project: ", "정밀 현재 모델 검사로 프로젝트를 읽었습니다: ") : T("Fast Current Model Check read current project: ", "빠른 현재 모델 검사로 프로젝트를 읽었습니다: ")) + projectSnapshot.Summary.LoadableFamilyCount.ToString(CultureInfo.InvariantCulture) + T(" loadable families / ", "개 로더블 패밀리 / ") + projectSnapshot.Summary.LoadableTypeCount.ToString(CultureInfo.InvariantCulture) + T(" loadable types / ", "개 로더블 타입 / ") + projectSnapshot.Summary.SystemTypeCount.ToString(CultureInfo.InvariantCulture) + T(" system types.", "개 시스템 타입.");
					string projectSnapshotPath = ProjectSnapshotStore.Save(_workspaceRoot, projectSnapshot, doc);
					report = ProjectStandardComparisonService.BuildReport(selectedRegistration, selectedRegistration.LastSnapshotPath, standardSnapshot, projectSnapshotPath, projectSnapshot, trackingCatalog);
					string projectThumbnailSourceId = ProjectSnapshotStore.BuildProjectThumbnailSourceId(_workspaceRoot, doc);
					if (report != null && report.Project != null && !string.IsNullOrWhiteSpace(projectThumbnailSourceId))
					{
						report.Project.ThumbnailSourceId = projectThumbnailSourceId;
						report.Project.ThumbnailFolder = FamilyThumbnailPreviewService.GetCacheFolder(_workspaceRoot, projectThumbnailSourceId);
					}
					_projectScanText += T(" 3D images were not regenerated during Current Model Check; existing cache is reused when available.", " 현재 모델 검사 중 3D 이미지는 새로 만들지 않았습니다. 기존 캐시가 있으면 재사용합니다.");
					UpdateLongOperationProgress(operationTitle, 98, 100, T("Saving current model comparison report...", "현재 모델 비교 리포트를 저장하는 중..."), forcePaint: true);
					_lastComparisonPath = ProjectStandardComparisonStore.Save(_workspaceRoot, report);
					ProjectSnapshotStore.SaveLatestProjectScan(_workspaceRoot, doc, selectedRegistration, standardSnapshot, projectSnapshotPath, _lastComparisonPath, projectSnapshot, report, projectThumbnailSourceId);
					MarkLatestProjectScanCacheFresh(doc);
					ClearModelerAllSlotsCache();
					ProjectTrackingStoreService.ClearCurrentModelCheckRequired(doc);
					StoreFastComparisonCache(comparisonCacheKey, report, _projectScanText);
					UpdateLongOperationProgress(operationTitle, 100, 100, T("Current Model Check completed.", "현재 모델 검사를 완료했습니다."), forcePaint: true);
				}
				else if (TryGetFastComparisonCache(comparisonCacheKey, ref report, ref cachedProjectScanText))
				{
					_projectScanText = (string.IsNullOrWhiteSpace(cachedProjectScanText) ? T("Cached tracking comparison was reused. No current project snapshot was created.", "캐시된 추적 비교를 재사용했습니다. 현재 프로젝트 스냅샷은 만들지 않았습니다.") : (cachedProjectScanText + " " + T("(cached)", "(캐시 재사용)")));
				}
				else
				{
					ProjectContentSnapshot projectSnapshot2 = BuildStartupProjectSnapshotFromTracking(doc, standardSnapshot, selectedRegistration, trackingCatalog);
					projectSnapshotForModelerRows = projectSnapshot2;
					_projectScanText = T("Opened from saved tracking only. No current project scan or snapshot was created: ", "저장된 추적 기록만으로 열었습니다. 현재 프로젝트 스캔이나 스냅샷은 만들지 않았습니다: ") + projectSnapshot2.Summary.LoadableFamilyCount.ToString(CultureInfo.InvariantCulture) + T(" tracked loadable families / ", "개 추적 로더블 패밀리 / ") + projectSnapshot2.Summary.LoadableTypeCount.ToString(CultureInfo.InvariantCulture) + T(" tracked loadable types / ", "개 추적 로더블 타입 / ") + projectSnapshot2.Summary.SystemTypeCount.ToString(CultureInfo.InvariantCulture) + T(" tracked system types.", "개 추적 시스템 타입.");
					report = ProjectStandardComparisonService.BuildReport(selectedRegistration, selectedRegistration.LastSnapshotPath, standardSnapshot, string.Empty, projectSnapshot2, trackingCatalog);
					StoreFastComparisonCache(comparisonCacheKey, report, _projectScanText);
				}
				AppendLoadableRowsFromComparison(report, standardSnapshot, selectedRegistration, disciplineKey, disciplineLabel);
				AppendSystemRowsFromComparison(report, disciplineKey, disciplineLabel);
				RebuildModelerRowsFromAllRegisteredStandardSlots(doc, browseSlots, browseSlot, selectedRegistration, trackingCatalog, projectSnapshotForModelerRows, report);
				_standardText = BuildRegisteredStandardSummaryText(registeredCount, missingCount, snapshotMissingCount);
				UpdateSecurityContext(_standardPolicy);
				EnsureAdminModeAllowed(_standardPolicy);
				_loadText = T("Load Available: ", "로드 가능: ") + CountDashboardLoadAvailable().ToString(CultureInfo.InvariantCulture);
				_updateText = T("Update Available: ", "업데이트 가능: ") + CountDashboardUpdateAvailable().ToString(CultureInfo.InvariantCulture);
				UpdateAggregateHealthContext();
				_systemSummary = BuildSystemComparisonSummary();
				if (deepProjectScan)
				{
					_statusMessage = T("Current Model Check completed for: ", "현재 모델 검사 완료: ") + disciplineLabel;
				}
				else
				{
					_statusMessage = T("Family Browser loaded from registered standard snapshot and saved tracking only: ", "등록된 표준 스냅샷과 저장된 추적 기록만으로 Family Browser를 열었습니다: ") + disciplineLabel;
				}
				if (deepProjectScan && _longOperationActive)
				{
					CompleteLongOperationProgress(_statusMessage);
				}
				RefreshRequestsAndAudit();
				RenderDashboard();
				if (deepProjectScan)
				{
					ShowCurrentModelCheckResultDialog(report, projectSnapshotForModelerRows, disciplineLabel, currentModelAutoDialogs);
				}
			}
			catch (Exception ex)
			{
				ProjectData.SetProjectError(ex);
				Exception ex2 = ex;
				if (_longOperationActive)
				{
					CompleteLongOperationProgress(T("Long operation failed.", "긴 작업이 실패했습니다."));
				}
				ShowLoggedError(T("Family Browser Refresh", "패밀리 브라우저 새로고침"), ex2);
				ProjectData.ClearProjectError();
			}
		}
	}

	private void RefreshDocumentShellOnly(string progressTitle = null, int progressStart = 0, int progressEnd = 100)
	{
		checked
		{
			try
			{
				Stopwatch shellSw = Stopwatch.StartNew();
				ReportDashboardRefreshProgress(progressTitle, progressStart, progressEnd, 1, 100, T("Preparing cached dashboard refresh...", "캐시된 대시보드 갱신을 준비하는 중..."), forcePaint: true);
				WriteDashboardRuntimeDiagnostic("shell-start", -1, -1L);
				_deferExpensiveStartupLookups = true;
				Document doc = GetActiveDocument();
				_deploymentBootstrapResult = FamilyBrowserDeploymentBootstrapService.GetLastResult();
				_standardPolicy = LoadStandardPolicy(1000);
				ReportDashboardRefreshProgress(progressTitle, progressStart, progressEnd, 12, 100, T("Loaded standard policy metadata.", "표준 정책 메타데이터를 읽었습니다."));
				WriteDashboardRuntimeDiagnostic("shell-policy-loaded", 0, shellSw.ElapsedMilliseconds);
				UseCachedOperationalReadiness();
				UpdateProjectContext(doc, includeCentralPath: false);
				ReportDashboardRefreshProgress(progressTitle, progressStart, progressEnd, 22, 100, T("Reading current project identity...", "현재 프로젝트 식별 정보를 읽는 중..."));
				WriteDashboardRuntimeDiagnostic("shell-project-context-light", 0, shellSw.ElapsedMilliseconds);
				UpdateSecurityContext(_standardPolicy);
				EnsureAdminModeAllowed(_standardPolicy);
				UpdateStandardContext(null);
				UpdateHealthContext(null);
				_loadableRows = new List<BrowserRow>();
				_systemRows = new List<SystemRow>();
				_systemComparisonRows = new List<SystemRow>();
				_lastComparisonPath = string.Empty;
				_lastSystemPreflightReport = null;
				_registration = null;
				_activeStandardListCatalog = null;
				_activeStandardScanNeeded = false;
				_modelerStandardListFilterMissing = false;
				PrepareRequestAndAuditPlaceholders();
				_loadText = T("Load Available: check needed", "로드 가능: 검사 필요");
				_updateText = T("Update Available: check needed", "업데이트 가능: 검사 필요");
				_healthText = T("Not checked", "검사 전");
				_projectOnlyText = T("Review needed: check needed", "검토 필요: 검사 필요");
				_projectScanText = T("Startup loaded only cached registration metadata. No project comparison, project scan, standard RVT scan, or snapshot generation was run.", "시작 시에는 등록된 스캔 기록만 확인했습니다. 프로젝트 비교, 프로젝트 스캔, 표준 RVT 스캔, 스냅샷 생성은 실행하지 않았습니다.");
				_systemSummary = T("System comparison is not loaded on startup.", "시스템 비교는 시작 시 로드하지 않습니다.");
				_trackingText = T("Tracking: not checked on startup", "추적: 시작 시 확인 안 함");
				_trackingTone = "info";
				_statusMessage = string.Empty;
				if (doc == null)
				{
					_projectTitle = T("No active project", "활성 프로젝트 없음");
					_projectPath = T("Open a Revit project before browsing.", "브라우저를 사용하기 전에 Revit 프로젝트를 열어주세요.");
					_standardText = T("Standard: ", "표준: ") + BuildBrowserStandardScopeLabel(_standardPolicy) + " / " + T("not checked", "확인 안 함");
					_loadText = T("Load Available: 0", "로드 가능: 0");
					_updateText = T("Update Available: 0", "업데이트 가능: 0");
					_permissionText = T("Permission: Review", "권한: 검토 필요");
					_trackingText = T("Tracking: no project", "추적: 프로젝트 없음");
					_trackingTone = "warn";
					_nextWorkflowText = T("Open a project, then run Current Model Check only when you need live comparison.", "프로젝트를 연 뒤 실제 비교가 필요할 때만 현재 모델 검사를 실행하세요.");
					_statusMessage = T("Family Browser opened without scanning because there is no active project.", "활성 프로젝트가 없어 스캔 없이 Family Browser를 열었습니다.");
					ReportDashboardRefreshProgress(progressTitle, progressStart, progressEnd, 98, 100, T("Rendering dashboard...", "대시보드를 표시하는 중..."), forcePaint: true);
					RenderDashboard();
					ReportDashboardRefreshProgress(progressTitle, progressStart, progressEnd, 100, 100, T("Dashboard refresh completed.", "대시보드 갱신이 완료되었습니다."), forcePaint: true);
					WriteDashboardRuntimeDiagnostic("shell-render-no-doc", 0, shellSw.ElapsedMilliseconds);
					return;
				}
				_projectTitle = doc.Title;
				_projectPath = (string.IsNullOrWhiteSpace(doc.PathName) ? T("Unsaved project", "저장되지 않은 프로젝트") : doc.PathName);
				List<FamilyBrowserStandardLibrarySlot> browseSlots = GetBrowserStandardSlots(_standardPolicy);
				FamilyBrowserStandardLibrarySlot browseSlot = ResolveBrowseSlot(_standardPolicy);
				if (browseSlot == null && browseSlots.Count > 0)
				{
					browseSlot = browseSlots[0];
				}
				int registeredCount = 0;
				int missingCount = 0;
				int snapshotMissingCount = 0;
				StandardLibraryRegistrationRecord selectedRegistration = null;
				bool selectedSnapshotMissing = false;
				FamilyBrowserStandardLibrarySlot firstReadySlot = null;
				StandardLibraryRegistrationRecord firstReadyRegistration = null;
				ReportDashboardRefreshProgress(progressTitle, progressStart, progressEnd, 32, 100, T("Checking registered standard RVT snapshots...", "등록된 표준 RVT 스냅샷을 확인하는 중..."));
				foreach (FamilyBrowserStandardLibrarySlot slot in browseSlots)
				{
					bool isSelectedSlot = SlotMatches(slot, browseSlot);
					StandardLibraryRegistrationRecord registration = TryLoadRegistrationForSlot(_standardPolicy, slot, 500);
					if (registration == null)
					{
						missingCount++;
						continue;
					}
					if (string.IsNullOrWhiteSpace(registration.LastSnapshotPath))
					{
						snapshotMissingCount++;
						if (isSelectedSlot)
						{
							selectedSnapshotMissing = true;
						}
						continue;
					}
					registeredCount++;
					if (firstReadyRegistration == null)
					{
						firstReadySlot = slot;
						firstReadyRegistration = registration;
					}
					if (isSelectedSlot)
					{
						selectedRegistration = registration;
					}
				}
				WriteDashboardRuntimeDiagnostic("shell-registration-metadata-checked", 0, shellSw.ElapsedMilliseconds);
				SelectFirstReadyBrowseSlotIfImplicit(ref browseSlot, ref selectedRegistration, ref selectedSnapshotMissing, firstReadySlot, firstReadyRegistration);
				_standardText = BuildRegisteredStandardSummaryText(registeredCount, missingCount, snapshotMissingCount);
				if (selectedRegistration == null)
				{
					_activeStandardScanNeeded = selectedSnapshotMissing;
					_permissionText = (selectedSnapshotMissing ? ScanNeededPermissionText() : T("Permission: Register required", "권한: 표준 등록 필요"));
					_trackingText = (selectedSnapshotMissing ? ScanNeededTrackingText() : T("Tracking: register first", "추적: 표준 등록 필요"));
					_trackingTone = (selectedSnapshotMissing ? "bad" : "warn");
					_nextWorkflowText = (selectedSnapshotMissing ? StandardScanNeededUserAction() : T("Connect a registered standard RVT, then run Current Model Check only when live project status is needed.", "등록된 표준 RVT를 연결한 뒤 실제 프로젝트 상태가 필요할 때만 현재 모델 검사를 실행하세요."));
					_statusMessage = (selectedSnapshotMissing ? StandardScanNeededUserAction() : T("No registered standard RVT was found for the selected trade.", "선택한 공종에 등록된 표준 RVT가 없습니다."));
				}
				else
				{
					_registration = selectedRegistration;
					_activeStandardScanNeeded = false;
					UpdateStandardContext(_registration);
					ReportDashboardRefreshProgress(progressTitle, progressStart, progressEnd, 44, 100, T("Building browser rows from standard list JSON...", "표준 목록 JSON 기준으로 브라우저 행을 만드는 중..."), forcePaint: true);
					WriteDashboardRuntimeDiagnostic("shell-before-light-rows", 0, shellSw.ElapsedMilliseconds);
					RebuildModelerRowsFromRegisteredStandardSlotsLight(doc, browseSlots, browseSlot, selectedRegistration, CreateDashboardRefreshProgressCallback(progressTitle, progressStart, progressEnd, 44, 90));
					WriteDashboardRuntimeDiagnostic("shell-after-light-rows loadableRows=" + _loadableRows.Count.ToString(CultureInfo.InvariantCulture) + " systemRows=" + _systemRows.Count.ToString(CultureInfo.InvariantCulture), 0, shellSw.ElapsedMilliseconds);
					_loadText = T("Load Available: ", "로드 가능: ") + CountDashboardLoadAvailable().ToString(CultureInfo.InvariantCulture);
					if (_lastModelerRowsUsedCachedProjectScan)
					{
						_updateText = T("Update Available: ", "업데이트 가능: ") + CountDashboardUpdateAvailable().ToString(CultureInfo.InvariantCulture);
						UpdateAggregateHealthContext();
						_trackingText = T("Tracking: latest project check loaded", "추적: 최신 프로젝트 검사 기록 로드됨");
						_trackingTone = ((CountDashboardUpdateAvailable() > 0) ? "warn" : "info");
						_projectScanText = T("Loaded the latest saved Current Model Check for this project from the shared management folder. No project scan, standard RVT scan, family edit, or 3D snapshot generation was run.", "공용 관리 폴더에서 이 프로젝트의 마지막 현재 모델 검사 결과를 불러왔습니다. 프로젝트 스캔, 표준 RVT 스캔, 패밀리 에디트, 3D 스냅샷 생성은 실행하지 않았습니다.");
						_systemSummary = BuildSystemComparisonSummary();
						_statusMessage = T("Family Browser restored the latest saved comparison result for the active project.", "현재 프로젝트의 마지막 비교 결과를 복원했습니다.");
					}
					else
					{
						_updateText = T("Project Updates: check needed", "프로젝트 업데이트: 검사 필요");
