	private void RefreshDocumentShellOnlyWithProgress(string title, string initialMessage, int progressStart = 0, int progressEnd = 100)
	{
		bool startedInlineProgress = false;
		string safeTitle = (title ?? string.Empty).Trim();
		string safeMessage = (initialMessage ?? string.Empty).Trim();
		if (string.IsNullOrWhiteSpace(safeTitle))
		{
			safeTitle = T("Loading Family Browser list", "패밀리 브라우저 목록 불러오는 중");
		}
		if (string.IsNullOrWhiteSpace(safeMessage))
		{
			safeMessage = T("Loading cached scan data and browser rows...", "캐시된 스캔 데이터와 브라우저 목록을 불러오는 중...");
		}
		if (IsStartupOverlayVisible())
		{
			UpdateStartupOverlayProgress(progressStart, 100, safeMessage, forcePaint: true);
		}
		else if (!_longOperationActive)
		{
			BeginLongOperationProgress(safeTitle, safeMessage);
			startedInlineProgress = true;
		}
		try
		{
			RefreshDocumentShellOnly(safeTitle, progressStart, progressEnd);
			if (startedInlineProgress)
			{
				CompleteLongOperationProgress(T("Dashboard refresh completed.", "대시보드 갱신이 완료되었습니다."));
			}
		}
		catch (Exception projectError)
		{
			ProjectData.SetProjectError(projectError);
			if (startedInlineProgress)
			{
				CompleteLongOperationProgress(T("Dashboard refresh failed.", "대시보드 갱신에 실패했습니다."));
			}
			throw;
		}
	}

	private void ApplyHomepageManagedPathBeforePolicyLoad(Document doc, bool force = false)
	{
		try
		{
			if (FamilyBrowserDeploymentBootstrapService.IsBootstrapDisabled(FamilyBrowserMachineConfigStore.ResolveDeploymentBootstrapUrl()))
			{
				FamilyBrowserDeploymentBootstrapService.SetBootstrapUrl(string.Empty, Environment.UserName);
			}
			_deploymentBootstrapResult = FamilyBrowserDeploymentBootstrapService.TryApply(_workspaceRoot, Environment.UserName, force, BuildDeploymentProjectIdentity(doc, includeCentralPath: false));
		}
		catch (Exception ex)
		{
			ProjectData.SetProjectError(ex);
			Exception ex2 = ex;
			WriteDashboardRuntimeDiagnostic("homepage-managed-path-refresh-skipped:" + ex2.Message, -1, -1L);
			_deploymentBootstrapResult = FamilyBrowserDeploymentBootstrapService.GetLastResult();
			ProjectData.ClearProjectError();
		}
	}

	private static ProjectContentSnapshot BuildStartupProjectSnapshotFromTracking(Document doc, StandardLibrarySnapshot standardSnapshot, StandardLibraryRegistrationRecord registration, ProjectTrackingCatalog trackingCatalog)
	{
		ProjectContentSnapshot snapshot = new ProjectContentSnapshot
		{
			CapturedAtUtc = DateTime.UtcNow.ToString("O", CultureInfo.InvariantCulture)
		};
		if (doc != null)
		{
			try
			{
				snapshot.DocumentTitle = doc.Title;
			}
			catch (Exception projectError)
			{
				ProjectData.SetProjectError(projectError);
				ProjectData.ClearProjectError();
			}
			try
			{
				snapshot.DocumentPath = doc.PathName;
			}
			catch (Exception projectError2)
			{
				ProjectData.SetProjectError(projectError2);
				ProjectData.ClearProjectError();
			}
			try
			{
				if (doc.Application != null)
				{
					snapshot.RevitVersion = doc.Application.VersionNumber;
				}
			}
			catch (Exception projectError3)
			{
				ProjectData.SetProjectError(projectError3);
				ProjectData.ClearProjectError();
			}
		}
		if (standardSnapshot == null || registration == null || trackingCatalog == null)
		{
			return snapshot;
		}
		if (!string.Equals(Normalize(trackingCatalog.SourceId), Normalize(registration.SourceId), StringComparison.Ordinal))
		{
			return snapshot;
		}
		string standardStamp = Normalize(standardSnapshot.CapturedAtUtc);
		Dictionary<string, TrackedLoadableFamilyState> trackedLoadables = (trackingCatalog.LoadableFamilies ?? new List<TrackedLoadableFamilyState>()).Where([SpecialName] (TrackedLoadableFamilyState x) => x != null).GroupBy([SpecialName] (TrackedLoadableFamilyState x) => BuildTrackedLoadableKey(x.CategoryName, x.FamilyName), StringComparer.Ordinal).ToDictionary([SpecialName] (IGrouping<string, TrackedLoadableFamilyState> g) => g.Key, [SpecialName] (IGrouping<string, TrackedLoadableFamilyState> g) => g.First(), StringComparer.Ordinal);
		foreach (StandardLoadableFamilySnapshotItem item in standardSnapshot.LoadableFamilies ?? new List<StandardLoadableFamilySnapshotItem>())
		{
			if (item == null)
			{
				continue;
			}
			TrackedLoadableFamilyState tracked = null;
			if (trackedLoadables.TryGetValue(BuildTrackedLoadableKey(item.CategoryName, item.FamilyName), out tracked))
			{
				string standardFingerprint = Normalize(ProjectSnapshotFingerprintService.BuildLoadableFingerprint(item));
				if (string.Equals(Normalize(tracked.ApprovedFingerprint), standardFingerprint, StringComparison.Ordinal) && string.Equals(Normalize(tracked.ApprovedStandardStamp), standardStamp, StringComparison.Ordinal))
				{
					snapshot.LoadableFamilies.Add(new ProjectLoadableFamilySnapshotItem
					{
						FamilyName = item.FamilyName,
						CategoryName = item.CategoryName,
						CategoryId = item.CategoryId,
						CategoryGroup = item.CategoryGroup,
						TypeCount = item.TypeCount,
						InstanceCount = 0,
						TypeNames = new List<string>(item.TypeNames ?? new List<string>()),
						Parameters = new List<StandardFamilyParameterSnapshotItem>(item.Parameters ?? new List<StandardFamilyParameterSnapshotItem>()),
						ContentFingerprint = item.ContentFingerprint,
						IsShared = item.IsShared
					});
				}
			}
		}
		Dictionary<string, TrackedSystemTypeState> trackedSystems = (trackingCatalog.SystemTypes ?? new List<TrackedSystemTypeState>()).Where([SpecialName] (TrackedSystemTypeState x) => x != null).GroupBy([SpecialName] (TrackedSystemTypeState x) => BuildTrackedSystemKey(x.TypeClassName, x.CategoryName, x.TypeName), StringComparer.Ordinal).ToDictionary([SpecialName] (IGrouping<string, TrackedSystemTypeState> g) => g.Key, [SpecialName] (IGrouping<string, TrackedSystemTypeState> g) => g.First(), StringComparer.Ordinal);
		foreach (StandardSystemTypeSnapshotItem item2 in standardSnapshot.SystemTypes ?? new List<StandardSystemTypeSnapshotItem>())
		{
			if (item2 == null)
			{
				continue;
			}
			TrackedSystemTypeState tracked2 = null;
			if (trackedSystems.TryGetValue(BuildTrackedSystemKey(item2.TypeClassName, item2.CategoryName, item2.TypeName), out tracked2))
			{
				string approvedFingerprint = tracked2.ApprovedFingerprint;
				string standardFingerprint2 = Normalize(ProjectSnapshotFingerprintService.BuildSystemFingerprint(item2));
				if (string.Equals(Normalize(approvedFingerprint), standardFingerprint2, StringComparison.Ordinal) && string.Equals(Normalize(tracked2.ApprovedStandardStamp), standardStamp, StringComparison.Ordinal))
				{
					snapshot.SystemTypes.Add(new ProjectSystemTypeSnapshotItem
					{
						TypeName = item2.TypeName,
						CategoryName = item2.CategoryName,
						CategoryId = item2.CategoryId,
						TypeClassName = item2.TypeClassName,
						SupportsRoutingDependencies = item2.SupportsRoutingDependencies,
						SemanticFingerprint = standardFingerprint2,
						ClassificationCode = item2.ClassificationCode,
						SegmentName = item2.SegmentName,
						MaterialName = item2.MaterialName,
						Shape = item2.Shape,
						RoutingPreferenceSignature = item2.RoutingPreferenceSignature,
						CompoundStructureSignature = item2.CompoundStructureSignature
					});
				}
			}
		}
		snapshot.Summary.LoadableFamilyCount = snapshot.LoadableFamilies.Count;
		snapshot.Summary.LoadableTypeCount = snapshot.LoadableFamilies.Sum([SpecialName] (ProjectLoadableFamilySnapshotItem x) => x.TypeCount);
		snapshot.Summary.SystemTypeCount = snapshot.SystemTypes.Count;
		snapshot.Summary.SystemTypeClassCount = (from x in snapshot.SystemTypes
			select Normalize(x.TypeClassName) into x
			where x.Length > 0
			select x).Distinct(StringComparer.Ordinal).Count();
		return snapshot;
	}

	private static string BuildTrackedLoadableKey(string categoryName, string familyName)
	{
		return Normalize(categoryName) + "|" + Normalize(familyName);
	}

	private static string BuildTrackedSystemKey(string typeClassName, string categoryName, string typeName)
	{
		return Normalize(typeClassName) + "|" + Normalize(categoryName) + "|" + Normalize(typeName);
	}

	private void InvalidateFastComparisonCache(string reason)
	{
		_fastComparisonCacheKey = string.Empty;
		_fastComparisonCachedReport = null;
		_fastComparisonCachedProjectScanText = string.Empty;
		ClearModelerAllSlotsCache();
		if (!string.IsNullOrWhiteSpace(reason))
		{
			WriteDashboardRuntimeDiagnostic("fast-compare-cache-clear:" + reason, -1, -1L);
		}
	}

	private void RebuildModelerRowsFromAllRegisteredStandardSlots(Document doc, IList<FamilyBrowserStandardLibrarySlot> browseSlots, FamilyBrowserStandardLibrarySlot selectedSlot, StandardLibraryRegistrationRecord selectedRegistration, ProjectTrackingCatalog trackingCatalog, ProjectContentSnapshot projectSnapshot = null, ProjectStandardComparisonReport selectedComparison = null)
	{
		if (_adminModeEnabled || doc == null || browseSlots == null || browseSlots.Count <= 1)
		{
			return;
		}
		_lastModelerRowsUsedCachedProjectScan = selectedComparison != null;
		string cacheKey = BuildModelerAllSlotsCacheKey(doc, browseSlots, trackingCatalog);
		if (TryGetModelerAllSlotsCache(cacheKey))
		{
			return;
		}
		List<BrowserRow> previousLoadableRows = _loadableRows;
		List<SystemRow> previousSystemRows = _systemRows;
		List<SystemRow> previousSystemComparisonRows = _systemComparisonRows;
		List<UnregisteredProjectItemRow> previousUnregisteredFamilyRows = _unregisteredFamilyRows;
		List<UnregisteredProjectItemRow> previousUnregisteredSystemRows = _unregisteredSystemRows;
		string previousUnregisteredListStatusText = _unregisteredListStatusText;
		FamilyBrowserStandardListCatalog previousStandardListCatalog = _activeStandardListCatalog;
		try
		{
			_modelerStandardListFilterMissing = false;
			ProjectContentSnapshot effectiveProjectSnapshot = projectSnapshot;
			if (effectiveProjectSnapshot == null)
			{
				effectiveProjectSnapshot = BuildStartupProjectSnapshotFromTracking(doc, null, null, trackingCatalog);
				WriteDashboardRuntimeDiagnostic("modeler-all-standard-slots-tracking-only-no-project-scan", -1, -1L);
			}
			else
			{
				WriteDashboardRuntimeDiagnostic("modeler-all-standard-slots-tracking-snapshot-reused", -1, -1L);
			}
			_loadableRows = new List<BrowserRow>();
			_systemRows = new List<SystemRow>();
			_systemComparisonRows = new List<SystemRow>();
			int readySlotCount = 0;
			foreach (FamilyBrowserStandardLibrarySlot slot in browseSlots)
			{
				if (slot == null)
				{
					continue;
				}
				StandardLibraryRegistrationRecord registration = (SlotMatches(slot, selectedSlot) ? selectedRegistration : TryLoadRegistrationForSlot(_standardPolicy, slot));
				if (registration != null && !string.IsNullOrWhiteSpace(registration.LastSnapshotPath) && File.Exists(registration.LastSnapshotPath))
				{
					StandardLibrarySnapshot standardSnapshot = LoadStandardSnapshotForDashboard(registration.LastSnapshotPath);
					if (standardSnapshot != null)
					{
						readySlotCount = checked(readySlotCount + 1);
						string disciplineKey = ResolveSlotKey(slot);
						string disciplineLabel = ResolveSlotLabel(slot);
						_activeStandardListCatalog = LoadStandardListCatalogForDashboard(slot, registration);
						ProjectStandardComparisonReport comparison = null;
						comparison = ((!SlotMatches(slot, selectedSlot) || selectedComparison == null) ? ProjectStandardComparisonService.BuildReport(registration, registration.LastSnapshotPath, standardSnapshot, string.Empty, effectiveProjectSnapshot, trackingCatalog) : selectedComparison);
						AppendLoadableRowsFromComparison(comparison, standardSnapshot, registration, disciplineKey, disciplineLabel);
						AppendSystemRowsFromComparison(comparison, disciplineKey, disciplineLabel);
					}
				}
			}
			WriteDashboardRuntimeDiagnostic("modeler-all-standard-slots ready=" + readySlotCount.ToString(CultureInfo.InvariantCulture) + " loadableRows=" + _loadableRows.Count.ToString(CultureInfo.InvariantCulture) + " systemRows=" + _systemRows.Count.ToString(CultureInfo.InvariantCulture), -1, -1L);
			StoreModelerAllSlotsCache(cacheKey, _loadableRows, _systemRows, _systemComparisonRows);
		}
		catch (Exception ex)
		{
			ProjectData.SetProjectError(ex);
			Exception ex2 = ex;
			_loadableRows = previousLoadableRows;
			_systemRows = previousSystemRows;
			_systemComparisonRows = previousSystemComparisonRows;
			_unregisteredFamilyRows = previousUnregisteredFamilyRows;
			_unregisteredSystemRows = previousUnregisteredSystemRows;
			_unregisteredListStatusText = previousUnregisteredListStatusText;
			WriteDashboardRuntimeDiagnostic("modeler-all-standard-slots-failed:" + ex2.Message, -1, -1L);
			ProjectData.ClearProjectError();
		}
		finally
		{
			_activeStandardListCatalog = previousStandardListCatalog;
		}
	}

