			registration = TryLoadRegistrationForSlot(_standardPolicy, slot, registrationLoadTimeout);
			string registryPath = ResolveRegistrationPathForSlot(_standardPolicy, slot);
			string standardListPath = ResolveStandardListPathForCache(slot, registration);
			parts.Add("slot");
			parts.Add(ResolveSlotKey(slot));
			parts.Add(slot.DisplayName ?? string.Empty);
			parts.Add(slot.Discipline ?? string.Empty);
			parts.Add(slot.StandardListSheetName ?? string.Empty);
			parts.Add(registryPath);
			parts.Add(standardListPath);
			parts.Add(_deferExpensiveStartupLookups ? "deferred" : BuildFileCacheStamp(standardListPath));
			if (registration != null)
			{
				parts.Add(registration.SourceId ?? string.Empty);
				parts.Add(registration.ResolvedPath ?? string.Empty);
				parts.Add(registration.LastSnapshotPath ?? string.Empty);
				parts.Add(registration.LastSnapshotAtUtc ?? string.Empty);
				parts.Add(registration.SourceFileLastWriteUtc ?? string.Empty);
				parts.Add(registration.SourceFileLength.ToString(CultureInfo.InvariantCulture));
			}
		}
		return string.Join("|", parts.Select([SpecialName] (string x) => (x ?? string.Empty).Replace("|", "/")));
	}

