		object standardRegistrationCacheLock = StandardRegistrationCacheLock;
		ObjectFlowControl.CheckForSyncLockOnValueType(standardRegistrationCacheLock);
		bool lockTaken = false;
		try
		{
			Monitor.Enter(standardRegistrationCacheLock, ref lockTaken);
			StandardRegistrationCache[fullPath] = new CachedStandardRegistration
			{
				Path = fullPath,
				LastWriteTicks = lastWriteTicks,
				Length = length,
				Registration = registration
			};
		}
		finally
		{
			if (lockTaken)
			{
				Monitor.Exit(standardRegistrationCacheLock);
			}
		}
	}

