	private static string ResolveStandardListPathForCache(FamilyBrowserStandardLibrarySlot slot, StandardLibraryRegistrationRecord registration)
	{
		string configuredPath = ResolveConfiguredStandardListPathForCache(slot, registration);
		if (!string.IsNullOrWhiteSpace(configuredPath))
		{
			return configuredPath;
		}
		return string.Empty;
	}

	private static string ResolveConfiguredStandardListPathForCache(FamilyBrowserStandardLibrarySlot slot, StandardLibraryRegistrationRecord registration)
	{
		string ResolveConfiguredStandardListPathForCache;
		if (slot == null || string.IsNullOrWhiteSpace(slot.StandardListPath))
		{
			ResolveConfiguredStandardListPathForCache = string.Empty;
		}
		else
		{
			try
			{
				string raw = Environment.ExpandEnvironmentVariables(slot.StandardListPath.Trim());
				if (Path.IsPathRooted(raw))
				{
					ResolveConfiguredStandardListPathForCache = Path.GetFullPath(raw);
				}
				else
				{
					string standardPath = string.Empty;
					if (!string.IsNullOrWhiteSpace(slot.StandardRvtPath))
					{
						standardPath = Environment.ExpandEnvironmentVariables(slot.StandardRvtPath.Trim());
					}
					else if (registration != null && !string.IsNullOrWhiteSpace(registration.ResolvedPath))
					{
						standardPath = Environment.ExpandEnvironmentVariables(registration.ResolvedPath.Trim());
					}
					if (string.IsNullOrWhiteSpace(standardPath))
					{
						goto IL_00ae;
					}
					string folder = Path.GetDirectoryName(standardPath);
					if (string.IsNullOrWhiteSpace(folder))
					{
						goto IL_00ae;
					}
					ResolveConfiguredStandardListPathForCache = Path.GetFullPath(Path.Combine(folder, raw));
				}
				goto end_IL_001c;
				IL_00ae:
				ResolveConfiguredStandardListPathForCache = Path.GetFullPath(raw);
				end_IL_001c:;
			}
			catch (Exception projectError)
			{
				ProjectData.SetProjectError(projectError);
				ResolveConfiguredStandardListPathForCache = slot.StandardListPath ?? string.Empty;
				ProjectData.ClearProjectError();
			}
		}
		return ResolveConfiguredStandardListPathForCache;
	}

	private static string BuildStandardListDiscoveryCacheStamp(FamilyBrowserStandardLibrarySlot slot, StandardLibraryRegistrationRecord registration)
	{
		if (slot != null && !string.IsNullOrWhiteSpace(slot.StandardListPath))
		{
			return "-";
