	private static List<string> BuildStandardListDiscoveryCandidatePaths(FamilyBrowserStandardLibrarySlot slot, StandardLibraryRegistrationRecord registration)
	{
		List<string> result = new List<string>();
		string standardPath = ResolveStandardPathForStandardListCache(slot, registration);
		if (string.IsNullOrWhiteSpace(standardPath))
		{
			return result;
		}
		try
		{
			string folder = Path.GetDirectoryName(standardPath);
			if (string.IsNullOrWhiteSpace(folder))
			{
				return result;
			}
			string baseName = Path.GetFileNameWithoutExtension(standardPath);
			if (string.IsNullOrWhiteSpace(baseName))
			{
				return result;
			}
			result.Add(Path.GetFullPath(Path.Combine(folder, baseName + ".json")));
			result.Add(Path.GetFullPath(Path.Combine(folder, baseName + ".xlsx")));
			result.Add(Path.GetFullPath(Path.Combine(folder, baseName + ".csv")));
			result.Add(Path.GetFullPath(Path.Combine(folder, baseName + "_list.json")));
			result.Add(Path.GetFullPath(Path.Combine(folder, baseName + "_list.xlsx")));
			result.Add(Path.GetFullPath(Path.Combine(folder, baseName + "_list.csv")));
			result.Add(Path.GetFullPath(Path.Combine(folder, baseName + "-list.json")));
			result.Add(Path.GetFullPath(Path.Combine(folder, baseName + "-list.xlsx")));
			result.Add(Path.GetFullPath(Path.Combine(folder, baseName + "-list.csv")));
			result.Add(Path.GetFullPath(Path.Combine(folder, baseName + " list.json")));
			result.Add(Path.GetFullPath(Path.Combine(folder, baseName + " list.xlsx")));
			result.Add(Path.GetFullPath(Path.Combine(folder, baseName + " list.csv")));
			result.Add(Path.GetFullPath(Path.Combine(folder, "standard-list.json")));
			result.Add(Path.GetFullPath(Path.Combine(folder, "standard-list.xlsx")));
			result.Add(Path.GetFullPath(Path.Combine(folder, "standard-list.csv")));
		}
		catch (Exception projectError)
		{
			ProjectData.SetProjectError(projectError);
			ProjectData.ClearProjectError();
		}
		return result;
	}

