		}
		foreach (BrowserRow row in rows)
		{
			if (row != null)
			{
				result.Add(new BrowserRow
				{
					Status = row.Status,
					RawStatus = row.RawStatus,
					DisciplineKey = row.DisciplineKey,
					DisciplineLabel = row.DisciplineLabel,
					Name = row.Name,
					Category = row.Category,
					CategoryGroup = row.CategoryGroup,
					Action = row.Action,
					Notes = row.Notes,
					ApprovedRev = row.ApprovedRev,
					LoadedRev = row.LoadedRev,
					ChangeSummary = row.ChangeSummary,
					DifferenceSummaryTable = row.DifferenceSummaryTable,
					ParameterSummary = row.ParameterSummary,
					NestedSummary = row.NestedSummary,
					IsNestedLoadableChild = row.IsNestedLoadableChild,
					PreviewImagePath = row.PreviewImagePath,
					PreviewDiagnostic = row.PreviewDiagnostic
				});
			}
		}
		return result;
	}

