	private bool TryGetFastComparisonCache(string cacheKey, ref ProjectStandardComparisonReport report, ref string projectScanText)
	{
		if (string.IsNullOrWhiteSpace(cacheKey))
		{
			return false;
		}
		if (_fastComparisonCachedReport == null)
		{
			return false;
		}
		if (!string.Equals(_fastComparisonCacheKey, cacheKey, StringComparison.Ordinal))
		{
			return false;
		}
		report = _fastComparisonCachedReport;
		projectScanText = _fastComparisonCachedProjectScanText;
		WriteDashboardRuntimeDiagnostic("fast-compare-cache-hit", (report.LoadableFamilies != null) ? report.LoadableFamilies.Count : 0, -1L);
		return true;
	}

	private void StoreFastComparisonCache(string cacheKey, ProjectStandardComparisonReport report, string projectScanText)
	{
		if (!string.IsNullOrWhiteSpace(cacheKey) && report != null)
		{
			_fastComparisonCacheKey = cacheKey;
			_fastComparisonCachedReport = report;
			_fastComparisonCachedProjectScanText = projectScanText ?? string.Empty;
			WriteDashboardRuntimeDiagnostic("fast-compare-cache-store", (report.LoadableFamilies != null) ? report.LoadableFamilies.Count : 0, -1L);
		}
	}

	private static bool ShouldRunPreciseProjectContentCheck(StandardLibrarySnapshot standardSnapshot)
	{
		if (standardSnapshot == null)
		{
			return false;
		}
		if (string.Equals(standardSnapshot.SnapshotMode, "Precise", StringComparison.OrdinalIgnoreCase))
		{
			return true;
		}
		if (standardSnapshot.LoadableFamilies == null)
		{
			return false;
		}
		return standardSnapshot.LoadableFamilies.Any([SpecialName] (StandardLoadableFamilySnapshotItem item) => item != null && (string.Equals(item.MetadataMode ?? string.Empty, "Precise", StringComparison.OrdinalIgnoreCase) || !string.IsNullOrWhiteSpace(item.ContentSignatureDebugPath)));
	}

	private void EnsurePreciseProjectLoadableFingerprints(ProjectContentSnapshot projectSnapshot, string operationName)
	{
		if (projectSnapshot == null || projectSnapshot.LoadableFamilies == null)
		{
			return;
		}
		List<ProjectLoadableFamilySnapshotItem> failed = projectSnapshot.LoadableFamilies.Where([SpecialName] (ProjectLoadableFamilySnapshotItem x) => x != null && string.IsNullOrWhiteSpace(x.ContentFingerprint)).ToList();
		if (failed.Count != 0)
		{
			string details = string.Join(Environment.NewLine, failed.Select([SpecialName] (ProjectLoadableFamilySnapshotItem x) => "- " + (x.CategoryName ?? string.Empty) + " / " + (x.FamilyName ?? string.Empty) + " / reason=" + (string.IsNullOrWhiteSpace(x.ContentFingerprintFailureReason) ? "Fingerprint was empty without a recorded reason." : x.ContentFingerprintFailureReason) + (string.IsNullOrWhiteSpace(x.ContentSignatureDebugPath) ? string.Empty : (" / " + x.ContentSignatureDebugPath))));
			WriteDashboardRuntimeDiagnostic("precise-project-fingerprint-missing", failed.Count, details.Length);
			_auditItems.Add((operationName ?? T("Precise Current Model Check", "현재 모델 정밀 검사")) + T(" found loadable families without fingerprints. The comparison report will include the failure list.", " 중 Fingerprint가 없는 로더블 패밀리가 발견되었습니다. 비교 리포트에 실패 목록을 포함합니다."));
		}
	}

	private string BuildFastComparisonCacheKey(Document doc, StandardLibraryRegistrationRecord registration, StandardLibrarySnapshot standardSnapshot, FamilyBrowserStandardLibrarySlot browseSlot, FamilyBrowserStandardListCatalog catalog, ProjectTrackingCatalog trackingCatalog)
	{
		int trackedFamilyCount = ((trackingCatalog != null && trackingCatalog.LoadableFamilies != null) ? trackingCatalog.LoadableFamilies.Count : 0);
		int trackedSystemCount = ((trackingCatalog != null && trackingCatalog.SystemTypes != null) ? trackingCatalog.SystemTypes.Count : 0);
		List<string> parts = new List<string>
		{
			"v3",
			BuildProjectDocumentCacheStamp(doc),
			GetProjectContentMutationSerial(doc).ToString(CultureInfo.InvariantCulture),
			(registration == null) ? string.Empty : registration.SourceId,
			(registration == null) ? string.Empty : registration.ResolvedPath,
			(registration == null) ? string.Empty : registration.LastSnapshotPath,
			(standardSnapshot == null) ? string.Empty : standardSnapshot.CapturedAtUtc,
			(standardSnapshot == null) ? string.Empty : standardSnapshot.SourceFileLastWriteUtc,
			(standardSnapshot == null) ? "0" : standardSnapshot.SourceFileLength.ToString(CultureInfo.InvariantCulture),
			ResolveSlotKey(browseSlot),
			(catalog == null) ? string.Empty : catalog.SourcePath,
			(catalog == null) ? string.Empty : catalog.SheetName,
			(catalog == null) ? "0" : catalog.RowCount.ToString(CultureInfo.InvariantCulture),
			(trackingCatalog == null) ? string.Empty : trackingCatalog.GeneratedAtUtc,
			(trackingCatalog == null) ? string.Empty : trackingCatalog.ApprovedStandardStamp,
			trackedFamilyCount.ToString(CultureInfo.InvariantCulture),
			trackedSystemCount.ToString(CultureInfo.InvariantCulture)
		};
		return string.Join("|", parts.Select([SpecialName] (string x) => (x ?? string.Empty).Replace("|", "/")));
	}

	private static string BuildProjectDocumentCacheStamp(Document doc)
	{
		if (doc == null)
		{
			return "no-doc";
		}
		string path = string.Empty;
		try
		{
			path = doc.PathName;
		}
		catch (Exception projectError)
		{
			ProjectData.SetProjectError(projectError);
			ProjectData.ClearProjectError();
		}
		string title = string.Empty;
		try
		{
			title = doc.Title;
		}
		catch (Exception projectError2)
		{
			ProjectData.SetProjectError(projectError2);
			ProjectData.ClearProjectError();
		}
		string modified = string.Empty;
		try
		{
			PropertyInfo propertyInfo = ((object)doc).GetType().GetProperty("IsModified");
			if ((object)propertyInfo != null)
			{
				object value = RuntimeHelpers.GetObjectValue(propertyInfo.GetValue(doc, null));
				if (value != null)
				{
					modified = Convert.ToString(RuntimeHelpers.GetObjectValue(value), CultureInfo.InvariantCulture);
				}
			}
		}
		catch (Exception projectError3)
		{
			ProjectData.SetProjectError(projectError3);
			ProjectData.ClearProjectError();
		}
		return title + "|" + (string.IsNullOrWhiteSpace(path) ? doc.GetHashCode().ToString(CultureInfo.InvariantCulture) : path) + "|" + modified;
	}

