	internal void RefreshForActiveDocumentChanged(string documentKey)
	{
		if (!base.IsDisposed)
		{
			try
			{
				InvalidateFastComparisonCache("active-document-changed");
				RefreshForActiveDocumentChangedCore(documentKey, deferred: false);
			}
			catch (Exception ex)
			{
				ProjectData.SetProjectError(ex);
				Exception ex2 = ex;
				ShowLoggedError(T("Family Browser Auto Refresh", "패밀리 브라우저 자동 검사"), ex2);
				ProjectData.ClearProjectError();
			}
		}
	}

	private void RefreshForActiveDocumentChangedCore(string documentKey, bool deferred)
	{
		if (base.IsDisposed)
		{
			return;
		}
		string currentKey = BuildCurrentDocumentRuntimeKey();
		if (string.IsNullOrWhiteSpace(currentKey))
		{
			WriteDashboardRuntimeDiagnostic("active-document-changed:no-active-document", -1, -1L);
			RefreshDocumentShellOnly();
		}
		else if (!string.IsNullOrWhiteSpace(documentKey) && !string.Equals(currentKey, documentKey, StringComparison.OrdinalIgnoreCase) && !deferred)
		{
			WriteDashboardRuntimeDiagnostic("active-document-changed:defer-until-active", -1, -1L);
			BeginInvoke((Action)([SpecialName] () =>
			{
				try
				{
					RefreshForActiveDocumentChangedCore(documentKey, deferred: true);
				}
				catch (Exception ex)
				{
					ProjectData.SetProjectError(ex);
					Exception ex2 = ex;
					ShowLoggedError(T("Family Browser Auto Refresh", "패밀리 브라우저 자동 검사"), ex2);
					ProjectData.ClearProjectError();
				}
			}));
		}
		else
		{
			WriteDashboardRuntimeDiagnostic("active-document-changed:shell-only", -1, -1L);
			RefreshDocumentShellOnly();
		}
	}

	internal void MarkCurrentProjectContentChanged(string documentKey)
	{
		if (!base.IsDisposed)
		{
			string currentKey = BuildCurrentDocumentRuntimeKey();
			if (string.IsNullOrWhiteSpace(documentKey) || string.IsNullOrWhiteSpace(currentKey) || string.Equals(documentKey, currentKey, StringComparison.OrdinalIgnoreCase))
			{
				int serial = IncrementProjectContentMutationSerialForKey(documentKey);
				ClearModelerAllSlotsCache();
				InvalidateFastComparisonCache("document-content-changed");
				WriteDashboardRuntimeDiagnostic("project-content-changed:" + documentKey + ":serial=" + serial.ToString(CultureInfo.InvariantCulture), -1, -1L);
			}
		}
	}

	private static string BuildDocumentRuntimeKey(Document doc)
	{
		if (doc == null)
		{
			return string.Empty;
		}
		string path = string.Empty;
		try
		{
			path = doc.PathName;
		}
		catch (Exception projectError)
		{
			ProjectData.SetProjectError(projectError);
			ProjectData.ClearProjectError();
		}
		if (!string.IsNullOrWhiteSpace(path))
		{
			return path;
		}
		string title = string.Empty;
		try
		{
			title = doc.Title;
		}
		catch (Exception projectError2)
		{
			ProjectData.SetProjectError(projectError2);
			ProjectData.ClearProjectError();
		}
		return title + "|" + doc.GetHashCode().ToString(CultureInfo.InvariantCulture);
	}

	private string BuildCurrentDocumentRuntimeKey()
	{
		return BuildDocumentRuntimeKey(GetActiveDocument());
	}

	private int GetProjectContentMutationSerial(Document doc)
	{
		return GetProjectContentMutationSerialForKey(BuildDocumentRuntimeKey(doc));
	}

	private int GetProjectContentMutationSerialForKey(string documentKey)
	{
		if (string.IsNullOrWhiteSpace(documentKey))
		{
			return _projectContentMutationSerial;
		}
		int serial = 0;
		if (_projectContentMutationSerials.TryGetValue(documentKey, out serial))
		{
			return serial;
		}
		return 0;
	}

	private int IncrementProjectContentMutationSerialForKey(string documentKey)
	{
		checked
		{
			if (string.IsNullOrWhiteSpace(documentKey))
			{
				_projectContentMutationSerial++;
				return _projectContentMutationSerial;
			}
			int serial = GetProjectContentMutationSerialForKey(documentKey) + 1;
			_projectContentMutationSerials[documentKey] = serial;
			_projectContentMutationSerial++;
			return serial;
		}
	}

	private void MarkLatestProjectScanCacheFresh(Document doc)
	{
		string documentKey = BuildDocumentRuntimeKey(doc);
		if (!string.IsNullOrWhiteSpace(documentKey))
		{
			_projectScanMutationBaselines[documentKey] = GetProjectContentMutationSerialForKey(documentKey);
			WriteDashboardRuntimeDiagnostic("latest-project-scan-cache-fresh:" + documentKey + ":serial=" + _projectScanMutationBaselines[documentKey].ToString(CultureInfo.InvariantCulture), -1, -1L);
		}
	}

	private bool CanUseLatestProjectScanCache(Document doc)
	{
		string documentKey = BuildDocumentRuntimeKey(doc);
		if (string.IsNullOrWhiteSpace(documentKey))
		{
			return _projectContentMutationSerial == 0;
		}
		int currentSerial = GetProjectContentMutationSerialForKey(documentKey);
		int baselineSerial = 0;
		if (_projectScanMutationBaselines.TryGetValue(documentKey, out baselineSerial))
		{
			return currentSerial == baselineSerial;
		}
		return currentSerial == 0;
	}

	private void UpdateProjectContext(Document doc, bool includeCentralPath = true)
	{
		_modelStateText = T("No Project", "프로젝트 없음");
		_centralPathText = "-";
		_userRoleText = T("Modeler", "모델러");
		if (doc == null)
		{
			_nextWorkflowText = T("Open a project and connect the standard RVT.", "프로젝트를 열고 표준 RVT를 연결하세요.");
			return;
		}
		try
		{
			if (string.IsNullOrWhiteSpace(doc.PathName))
			{
				_modelStateText = T("Unsaved", "미저장");
				_nextWorkflowText = T("Save the model, then run project health check.", "모델을 저장한 뒤 프로젝트 검사를 실행하세요.");
				return;
			}
			if (!doc.IsWorkshared)
			{
				_modelStateText = T("Standalone", "단독 모델");
				_nextWorkflowText = T("This can be checked, but final operation should target the project central/local workflow.", "검사는 가능하지만 실제 운영은 센트럴/로컬 모델 기준으로 진행하세요.");
				return;
			}
			string centralPath = string.Empty;
			if (includeCentralPath)
			{
				centralPath = TryGetCentralPath(doc);
				_centralPathText = (string.IsNullOrWhiteSpace(centralPath) ? "-" : centralPath);
			}
			else
			{
				_centralPathText = T("Not checked on startup", "시작 시 확인 안 함");
			}
			if (IsDetachedDocument(doc))
			{
				_modelStateText = T("Detached", "분리됨");
				_nextWorkflowText = T("Detached models are review-only. Reopen the local/central model for managed updates.", "분리된 모델은 검토 전용입니다. 관리 업데이트는 로컬/센트럴 모델에서 실행하세요.");
			}
			else if (includeCentralPath && IsSameUserVisiblePath(doc.PathName, centralPath))
			{
				_modelStateText = T("Central", "센트럴");
				_nextWorkflowText = T("Run health check before approving loads or updates.", "로드/업데이트 승인 전에 프로젝트 검사를 실행하세요.");
			}
			else if (includeCentralPath)
			{
				_modelStateText = T("Local", "로컬");
				_nextWorkflowText = T("Run health check against the connected central standard.", "연결된 센트럴 기준으로 프로젝트 검사를 실행하세요.");
			}
			else
			{
				_modelStateText = T("Project Open", "프로젝트 열림");
				_nextWorkflowText = T("Startup skipped central path lookup. Run Current Model Check only when live project status is needed.", "시작 시 센트럴 경로 확인을 건너뛰었습니다. 실제 프로젝트 상태가 필요할 때만 현재 모델 검사를 실행하세요.");
			}
		}
		catch (Exception projectError)
		{
			ProjectData.SetProjectError(projectError);
			_modelStateText = T("Check Needed", "확인 필요");
			_nextWorkflowText = T("Model state could not be fully resolved. Run health check and review paths.", "모델 상태를 완전히 확인하지 못했습니다. 프로젝트 검사 후 경로를 확인하세요.");
			ProjectData.ClearProjectError();
		}
	}

	private void UpdateStandardContext(StandardLibraryRegistrationRecord registration)
	{
		if (registration == null)
		{
			_standardPathText = "-";
			_standardSnapshotText = "-";
			return;
		}
		if (!string.IsNullOrWhiteSpace(registration.ResolvedPath))
		{
			_standardPathText = registration.ResolvedPath;
		}
		else if (!string.IsNullOrWhiteSpace(registration.Locator))
		{
			_standardPathText = registration.Locator;
		}
		else
		{
			_standardPathText = registration.DisplayName;
		}
		_standardSnapshotText = FormatUtcStamp(registration.LastSnapshotAtUtc);
	}

	private void EnsureNestedLoadableSnapshotMetadata(ref StandardLibraryRegistrationRecord registration, ref StandardLibrarySnapshot standardSnapshot, FamilyBrowserStandardLibrarySlot browseSlot)
	{
		if (registration != null && standardSnapshot != null && RequiresNestedLoadableSnapshotRefresh(standardSnapshot))
		{
			WriteDashboardRuntimeDiagnostic("nested-snapshot-refresh-skip:auto-disabled schema=" + standardSnapshot.SnapshotSchemaVersion.ToString(CultureInfo.InvariantCulture), -1, -1L);
		}
	}

	private static bool RequiresNestedLoadableSnapshotRefresh(StandardLibrarySnapshot snapshot)
	{
		if (snapshot != null)
		{
			return snapshot.SnapshotSchemaVersion < 4;
		}
		return false;
	}

	private void UpdateHealthContext(ProjectStandardComparisonReport report)
	{
		if (report == null)
		{
			_healthText = T("Not checked", "검사 전");
			_projectOnlyText = T("Review needed: 0", "검토 필요: 0");
			return;
		}
		checked
		{
			int differenceCount = report.Summary.LoadableDifferentCount + report.Summary.SystemDifferentCount;
			int projectOnlyCount = report.Summary.LoadableProjectOnlyCount + report.Summary.SystemProjectOnlyCount;
			int loadAvailableCount = report.Summary.LoadableLoadAvailableCount + report.Summary.SystemLoadAvailableCount;
			_healthText = T("Different: ", "차이 있음: ") + differenceCount.ToString(CultureInfo.InvariantCulture) + T(" / Load available: ", " / 로드 가능: ") + loadAvailableCount.ToString(CultureInfo.InvariantCulture);
			_projectOnlyText = T("Review needed: ", "검토 필요: ") + projectOnlyCount.ToString(CultureInfo.InvariantCulture);
			if (differenceCount > 0)
			{
				_nextWorkflowText = T("Review differences, then approve update or keep project content.", "차이 항목을 검토한 뒤 업데이트 승인 또는 프로젝트 유지 여부를 결정하세요.");
			}
			else if (projectOnlyCount > 0)
			{
				_nextWorkflowText = T("Admins should review items that are not found in the registered standard.", "등록된 표준에 없는 항목은 관리자가 표준 편입 여부를 검토하세요.");
			}
			else if (loadAvailableCount > 0)
			{
				_nextWorkflowText = T("Missing approved items are shown for reference. Apply updates only changes families and system types already in the current project.", "누락된 승인 항목은 참고로 표시됩니다. 적용 작업은 현재 프로젝트에 이미 있는 패밀리와 시스템 타입만 갱신합니다.");
			}
			else
			{
				_nextWorkflowText = T("Current model aligns with the registered standard snapshot.", "현재 모델이 등록된 표준 스냅샷과 일치합니다.");
			}
		}
	}

	private void RegisterStandardRvt(string snapshotMode = "Fast")
	{
		try
		{
			if (!EnsurePermission("RegisterStandard", T("Connect Standard RVT", "표준 RVT 연결")))
			{
				return;
			}
			string effectiveSnapshotMode = (string.Equals(snapshotMode, "Precise", StringComparison.OrdinalIgnoreCase) ? "Precise" : "Fast");
			bool isPreciseScan = string.Equals(effectiveSnapshotMode, "Precise", StringComparison.OrdinalIgnoreCase);
			using OpenFileDialog dialog = new OpenFileDialog();
			string targetLabel = T("Current Target", "현재 대상");
			FamilyBrowserStandardLibrarySlot registrationTargetSlot = null;
			_standardPolicy = LoadStandardPolicy();
			registrationTargetSlot = ResolveBrowseSlot(_standardPolicy);
			if (registrationTargetSlot == null)
			{
				registrationTargetSlot = FamilyBrowserStandardPolicyStore.GetEffectiveSlot(_standardPolicy);
			}
			targetLabel = ((registrationTargetSlot == null) ? BuildPolicyTargetLabel() : ResolveSlotLabel(registrationTargetSlot));
			dialog.Title = T("Select Standard RVT for ", "표준 RVT 선택 - ") + targetLabel;
			dialog.Filter = "Revit Project (*.rvt)|*.rvt";
			dialog.CheckFileExists = true;
			dialog.Multiselect = false;
			dialog.RestoreDirectory = true;
			Document doc = GetActiveDocument();
			if (doc != null && !string.IsNullOrWhiteSpace(doc.PathName))
			{
				try
				{
					dialog.InitialDirectory = Path.GetDirectoryName(doc.PathName);
				}
				catch (Exception projectError)
				{
					ProjectData.SetProjectError(projectError);
					ProjectData.ClearProjectError();
				}
			}
			if (dialog.ShowDialog(this) == DialogResult.OK)
			{
				string operationTitle = (isPreciseScan ? T("Precise Standard RVT Scan", "표준 RVT 정밀 스캔") : T("Fast Standard RVT Scan", "표준 RVT 빠른 스캔"));
				BeginLongOperationProgress(operationTitle, isPreciseScan ? T("Preparing precise standard RVT scan...", "표준 RVT 정밀 스캔을 준비하는 중...") : T("Preparing fast standard RVT registration...", "표준 RVT 빠른 등록을 준비하는 중..."));
				ISet<string> nestedScanFamilyNames = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
				if (isPreciseScan)
				{
					UpdateLongOperationProgress(operationTitle, 4, 100, T("Preparing nested/helper family candidates...", "하위/헬퍼 패밀리 후보를 준비하는 중..."), forcePaint: true);
					nestedScanFamilyNames = BuildNestedLoadableScanFamilyNameSetForRegistration(_standardPolicy, dialog.FileName, registrationTargetSlot);
				}
				else
				{
					UpdateLongOperationProgress(operationTitle, 4, 100, T("Fast scan skips family edit, nested metadata, and 3D image generation.", "빠른 스캔은 패밀리 편집, 하위 메타데이터, 3D 이미지 생성을 건너뜁니다."), forcePaint: true);
				}
				Action<int, int, string> progressCallback = CreateLongOperationProgressCallback(operationTitle);
				StandardLibraryRegistrationResult result = StandardLibraryRegistrationService.Register(_workspaceRoot, _uiApplication.Application, dialog.FileName, Environment.UserName, effectiveSnapshotMode, _uiApplication, nestedScanFamilyNames, forceSnapshotRebuild: false, progressCallback);
				_registration = result.Registration;
				UpdateLongOperationProgress(operationTitle, 99, 100, T("Attaching registration to the selected trade...", "선택한 공종에 등록 정보를 연결하는 중..."), forcePaint: true);
				string requestedSlotKey = ResolveSlotKey(registrationTargetSlot ?? FamilyBrowserStandardPolicyStore.GetEffectiveSlot(_standardPolicy));
				string slotRegistrationPath = FamilyBrowserStandardPolicyStore.AttachRegistrationToSlot(_workspaceRoot, _standardPolicy, requestedSlotKey, result.Registration, Environment.UserName);
				_standardPolicy = LoadStandardPolicy();
				FamilyBrowserStandardLibrarySlot registeredSlot = ResolvePolicySlot(_standardPolicy, requestedSlotKey);
				if (registeredSlot != null)
				{
					_browseDisciplineKey = ResolveSlotKey(registeredSlot);
					_browseDisciplineAutoSelected = false;
				}
				ClearDashboardDataCaches();
				StoreStandardSnapshotForDashboard(result.SnapshotPath, result.Snapshot);
				StoreStandardRegistrationForDashboard(slotRegistrationPath, result.Registration);
				InvalidateFastComparisonCache("standard-rvt-register");
				StandardRvtChangeCandidateService.NotifyPolicyChanged();
				CompleteLongOperationProgress(T("Standard RVT registration finished.", "표준 RVT 등록을 완료했습니다."));
				FamilyBrowserStandardFingerprintAuditExportResult fingerprintAudit = null;
				if (isPreciseScan)
				{
					fingerprintAudit = PromptSaveStandardListFingerprintAudit(result.Snapshot, result.Registration, registeredSlot, T("Register RVT", "RVT 등록"));
				}
				ShowDashboardMessage(this, (isPreciseScan ? T("Precise standard RVT scan completed.", "표준 RVT 정밀 스캔 완료.") : T("Fast standard RVT scan completed.", "표준 RVT 빠른 스캔 완료.")) + Environment.NewLine + Environment.NewLine + T("Target: ", "대상: ") + targetLabel + Environment.NewLine + T("Scan mode: ", "스캔 방식: ") + effectiveSnapshotMode + Environment.NewLine + T("Name: ", "이름: ") + result.Registration.DisplayName + Environment.NewLine + T("Loadable families: ", "로드 가능 패밀리: ") + result.Snapshot.Summary.LoadableFamilyCount.ToString(CultureInfo.InvariantCulture) + Environment.NewLine + T("Loadable types: ", "로드 가능 타입: ") + result.Snapshot.Summary.LoadableTypeCount.ToString(CultureInfo.InvariantCulture) + Environment.NewLine + T("System types: ", "시스템 타입: ") + result.Snapshot.Summary.SystemTypeCount.ToString(CultureInfo.InvariantCulture) + Environment.NewLine + BuildRegistrationDialogDiagnosticSummary(result) + BuildStandardFingerprintAuditDialogSummary(fingerprintAudit) + T("Registry: ", "등록 정보: ") + slotRegistrationPath, T("Register RVT", "RVT 등록"), MessageBoxButtons.OK, MessageBoxIcon.Asterisk);
				_statusMessage = T("Standard RVT registration finished. Project comparison was not run automatically; use Current Model Check when live project status is needed.", "표준 RVT 등록을 완료했습니다. 프로젝트 비교는 자동 실행하지 않았습니다. 실제 프로젝트 상태 확인이 필요할 때만 현재 모델 검사를 실행하세요.");
				RefreshDocumentShellOnly();
			}
		}
		catch (Exception ex)
		{
			ProjectData.SetProjectError(ex);
			Exception ex2 = ex;
			if (_longOperationActive)
			{
				CompleteLongOperationProgress(T("Standard RVT registration failed.", "표준 RVT 등록에 실패했습니다."));
			}
			ShowLoggedError("Register RVT", ex2);
			ProjectData.ClearProjectError();
		}
	}

	private ISet<string> BuildNestedLoadableScanFamilyNameSetForRegistration(FamilyBrowserStandardPolicy policy, string standardRvtPath, FamilyBrowserStandardLibrarySlot targetSlot = null)
	{
		HashSet<string> result = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
		if (policy == null || string.IsNullOrWhiteSpace(standardRvtPath))
		{
			return result;
		}
		try
		{
			FamilyBrowserStandardLibrarySlot slot = targetSlot ?? FamilyBrowserStandardPolicyStore.GetEffectiveSlot(policy);
			if (slot == null)
			{
				return result;
			}
			StandardLibraryRegistrationRecord registrationProbe = new StandardLibraryRegistrationRecord
			{
				ResolvedPath = standardRvtPath,
				Locator = standardRvtPath
			};
			FamilyBrowserStandardListCatalog catalog = FamilyBrowserStandardListService.LoadForSlot(slot, registrationProbe);
			if (!FamilyBrowserStandardListService.IsFilteringEnabled(catalog))
			{
				WriteDashboardRuntimeDiagnostic("standard-register-nested-scan-candidates:0", -1, -1L);
				return result;
			}
			foreach (FamilyBrowserStandardListEntry entry in catalog.Entries)
			{
				if (entry != null && !string.IsNullOrWhiteSpace(entry.Family))
				{
					result.Add(entry.Family.Trim());
				}
			}
			WriteDashboardRuntimeDiagnostic("standard-register-nested-scan-candidates:" + result.Count.ToString(CultureInfo.InvariantCulture), -1, -1L);
		}
		catch (Exception ex)
		{
			ProjectData.SetProjectError(ex);
			Exception ex2 = ex;
			WriteDashboardRuntimeDiagnostic("standard-register-nested-scan-candidates-failed:" + ex2.Message, -1, -1L);
			ProjectData.ClearProjectError();
		}
		return result;
	}

	private void ResetRegisteredStandardRvt()
	{
		try
		{
			string caption = T("Reset Standard RVT Scan", "표준 RVT 등록/스캔 초기화");
			if (!EnsurePermission("RegisterStandard", caption))
			{
				return;
			}
			_standardPolicy = LoadStandardPolicy();
			FamilyBrowserStandardLibrarySlot slot = FamilyBrowserStandardPolicyStore.GetEffectiveSlot(_standardPolicy);
			if (slot == null)
			{
				ShowDashboardMessage(this, T("There is no active standard target to reset.", "초기화할 활성 표준 대상이 없습니다."), caption, MessageBoxButtons.OK, MessageBoxIcon.Asterisk);
				return;
			}
			string targetLabel = ResolveSlotLabel(slot);
			StandardLibraryRegistrationRecord registration = TryLoadRegistrationForSlot(_standardPolicy, slot);
			string confirmMessage = T("Clear the registered Standard RVT and scan cache for this target?", "이 대상의 표준 RVT 등록 정보와 스캔 캐시를 초기화할까요?") + Environment.NewLine + Environment.NewLine + T("Target: ", "대상: ") + targetLabel + Environment.NewLine + T("The connected standard list Excel/JSON will be kept. Reconnect the Standard RVT afterward to rebuild the snapshot from scratch.", "연결된 표준 목록 Excel/JSON은 유지됩니다. 이후 표준 RVT를 다시 연결하면 스냅샷을 처음부터 새로 만듭니다.");
			if (ShowDashboardMessage(this, confirmMessage, caption, MessageBoxButtons.YesNo, MessageBoxIcon.Exclamation) == DialogResult.Yes)
			{
				List<string> deletedFiles = new List<string>();
				List<string> failedFiles = new List<string>();
				DeleteStandardRegistrationAndSnapshotFiles(slot, registration, deletedFiles, failedFiles);
				FamilyBrowserStandardPolicyStore.ClearRegistrationForSlot(_workspaceRoot, _standardPolicy, ResolveSlotKey(slot), Environment.UserName);
				_standardPolicy = LoadStandardPolicy();
				_registration = null;
				_standardPathText = "-";
				_standardSnapshotText = "-";
				InvalidateFastComparisonCache("standard-rvt-reset");
				ClearDashboardDataCaches();
				WriteDashboardRuntimeDiagnostic("standard-rvt-reset target=" + targetLabel + " deleted=" + deletedFiles.Count.ToString(CultureInfo.InvariantCulture) + " failed=" + failedFiles.Count.ToString(CultureInfo.InvariantCulture), -1, -1L);
				string resultMessage = T("Standard RVT registration was reset.", "표준 RVT 등록/스캔 정보를 초기화했습니다.") + Environment.NewLine + Environment.NewLine + T("Deleted files: ", "삭제된 파일: ") + deletedFiles.Count.ToString(CultureInfo.InvariantCulture);
				if (failedFiles.Count > 0)
				{
					resultMessage = resultMessage + Environment.NewLine + T("Files that could not be deleted: ", "삭제하지 못한 파일: ") + failedFiles.Count.ToString(CultureInfo.InvariantCulture) + Environment.NewLine + string.Join(Environment.NewLine, failedFiles.Take(5));
				}
				ShowDashboardMessage(this, resultMessage, caption, MessageBoxButtons.OK, (failedFiles.Count > 0) ? MessageBoxIcon.Exclamation : MessageBoxIcon.Asterisk);
				RefreshDocumentShellOnly();
			}
		}
		catch (Exception ex)
		{
			ProjectData.SetProjectError(ex);
			Exception ex2 = ex;
			ShowLoggedError("Reset Standard RVT Scan", ex2);
			ProjectData.ClearProjectError();
		}
	}

	private void ResetAllFamilyBrowserSettings()
	{
		try
		{
			string caption = T("Reset All Browser Settings", "모든 브라우저 설정 초기화");
			if (!EnsurePermission("ManagePolicy", caption))
			{
				return;
			}
			string policyPathBeforeReset = string.Empty;
			try
			{
				policyPathBeforeReset = FamilyBrowserStandardPolicyStore.GetPolicyPath(_workspaceRoot);
			}
			catch (Exception projectError)
			{
				ProjectData.SetProjectError(projectError);
				ProjectData.ClearProjectError();
			}
			string confirmMessage = T("Reset every Family Browser setting and cache for this configured data root?", "현재 설정된 데이터 위치의 패밀리 브라우저 설정과 캐시를 모두 초기화할까요?") + Environment.NewLine + Environment.NewLine + T("This clears Standard RVT registrations, scan snapshots, standard-list JSON files, 3D thumbnail cache, comparison reports, system preflight/apply reports, tracking reports, and managed preview display cache.", "표준 RVT 등록, 스캔 스냅샷, 표준 목록 JSON, 3D 썸네일 캐시, 비교 리포트, 시스템 타입 진단/적용 리포트, 추적 리포트, 공용 미리보기 표시 캐시를 삭제합니다.") + Environment.NewLine + T("Original RVT/Excel files and request cards are kept. The homepage/shared-root pointer is kept so the browser can still find the management folder.", "원본 RVT/Excel 파일과 요청 카드는 유지합니다. 홈페이지/공유 루트 경로는 유지해서 브라우저가 관리 폴더를 계속 찾을 수 있게 합니다.") + (string.IsNullOrWhiteSpace(policyPathBeforeReset) ? string.Empty : (Environment.NewLine + Environment.NewLine + T("Policy path: ", "정책 경로: ") + policyPathBeforeReset));
			if (ShowDashboardMessage(this, confirmMessage, caption, MessageBoxButtons.YesNo, MessageBoxIcon.Exclamation) != DialogResult.Yes)
			{
				return;
			}
			string secondConfirm = T("This cannot be undone. Continue reset?", "이 작업은 되돌릴 수 없습니다. 계속 초기화할까요?");
			if (ShowDashboardMessage(this, secondConfirm, caption, MessageBoxButtons.YesNo, MessageBoxIcon.Exclamation) != DialogResult.Yes)
			{
				return;
			}
			List<string> deletedItems = new List<string>();
			List<string> failedItems = new List<string>();
			List<string> folders = new List<string>();
			AddResetFolder(folders, FamilyBrowserStandardPolicyStore.GetRegistryFolder(_workspaceRoot));
			AddResetFolder(folders, FamilyBrowserStandardPolicyStore.GetSnapshotFolder(_workspaceRoot));
			AddResetFolder(folders, FamilyBrowserStandardPolicyStore.GetThumbnailFolder(_workspaceRoot));
			AddResetFolder(folders, FamilyBrowserStandardPolicyStore.GetStandardListFolder(_workspaceRoot));
			AddResetFolder(folders, ProjectSnapshotStore.GetProjectScanCacheFolder(_workspaceRoot));
			string localDataRoot = FamilyBrowserStandardPolicyStore.GetDataRootFolder(_workspaceRoot);
			AddResetFolder(folders, Path.Combine(localDataRoot, "Comparisons"));
			AddResetFolder(folders, Path.Combine(localDataRoot, "Diagnostics"));
			AddResetFolder(folders, Path.Combine(localDataRoot, "LoadableSync"));
			AddResetFolder(folders, Path.Combine(localDataRoot, "Logs"));
			AddResetFolder(folders, Path.Combine(localDataRoot, "ProjectSnapshots"));
			AddResetFolder(folders, Path.Combine(localDataRoot, "ProjectTrackingDirty"));
			AddResetFolder(folders, Path.Combine(localDataRoot, "SecurityAudit"));
			AddResetFolder(folders, Path.Combine(localDataRoot, "SystemTypePreflight"));
			AddResetFolder(folders, Path.Combine(localDataRoot, "SystemTypeSync"));
			AddResetFolder(folders, Path.Combine(localDataRoot, "Tracking"));
			AddResetFolder(folders, Path.Combine(localDataRoot, "HtmlPreviewCache"));
			foreach (string item in folders)
			{
				DeleteResetFolder(item, deletedItems, failedItems);
			}
			try
			{
				FamilyBrowserDeploymentBootstrapService.ClearCache();
				deletedItems.Add(T("Deployment bootstrap cache", "배포 설정 캐시"));
			}
			catch (Exception ex)
			{
				ProjectData.SetProjectError(ex);
				Exception ex2 = ex;
				failedItems.Add(T("Deployment bootstrap cache", "배포 설정 캐시") + " - " + ex2.Message);
				ProjectData.ClearProjectError();
			}
			string policyPath = FamilyBrowserStandardPolicyStore.ResetToDefault(_workspaceRoot, Environment.UserName);
			ClearDashboardDataCaches();
			FamilyBrowserPermissionExcelPolicyService.ClearCache();
			_standardPolicy = FamilyBrowserStandardPolicyStore.LoadOrCreate(_workspaceRoot, Environment.UserName);
			_registration = null;
			_activeStandardListCatalog = null;
			_loadableRows.Clear();
			_systemRows.Clear();
			_systemComparisonRows.Clear();
			_requestRecords.Clear();
			_lastComparisonPath = string.Empty;
			_lastPreflightPath = string.Empty;
			_standardPathText = "-";
			_standardSnapshotText = "-";
			_browseDisciplineKey = string.Empty;
			_browseDisciplineAutoSelected = false;
			InvalidateFastComparisonCache("settings-reset-all");
			WriteDashboardRuntimeDiagnostic("settings-reset-all policy=" + policyPath + " folders=" + folders.Count.ToString(CultureInfo.InvariantCulture) + " deleted=" + deletedItems.Count.ToString(CultureInfo.InvariantCulture) + " failed=" + failedItems.Count.ToString(CultureInfo.InvariantCulture), -1, -1L);
			string resultMessage = T("Family Browser settings and caches were reset.", "패밀리 브라우저 설정과 캐시를 초기화했습니다.") + Environment.NewLine + Environment.NewLine + T("New policy: ", "새 정책: ") + policyPath + Environment.NewLine + T("Deleted/reset items: ", "삭제/초기화 항목: ") + deletedItems.Count.ToString(CultureInfo.InvariantCulture);
			if (failedItems.Count > 0)
			{
				resultMessage = resultMessage + Environment.NewLine + T("Items that could not be deleted: ", "삭제하지 못한 항목: ") + failedItems.Count.ToString(CultureInfo.InvariantCulture) + Environment.NewLine + string.Join(Environment.NewLine, failedItems.Take(6));
			}
			ShowDashboardMessage(this, resultMessage, caption, MessageBoxButtons.OK, (failedItems.Count > 0) ? MessageBoxIcon.Exclamation : MessageBoxIcon.Asterisk);
			RefreshDocumentShellOnly();
		}
		catch (Exception ex3)
		{
			ProjectData.SetProjectError(ex3);
			Exception ex4 = ex3;
			ShowLoggedError("Reset All Browser Settings", ex4);
			ProjectData.ClearProjectError();
		}
	}

	private void DeleteStandardRegistrationAndSnapshotFiles(FamilyBrowserStandardLibrarySlot slot, StandardLibraryRegistrationRecord registration, List<string> deletedFiles, List<string> failedFiles)
	{
		HashSet<string> sourceIds = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
		HashSet<string> sourcePaths = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
		HashSet<string> linkedFiles = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
		AddIfNotBlank(sourceIds, (registration == null) ? string.Empty : registration.SourceId);
		AddIfNotBlank(sourceIds, (slot == null) ? string.Empty : slot.SourceId);
		AddNormalizedPathIfNotBlank(sourcePaths, (registration == null) ? string.Empty : registration.ResolvedPath);
		AddNormalizedPathIfNotBlank(sourcePaths, (registration == null) ? string.Empty : registration.Locator);
		AddNormalizedPathIfNotBlank(sourcePaths, (slot == null) ? string.Empty : slot.StandardRvtPath);
		AddNormalizedPathIfNotBlank(linkedFiles, (slot == null) ? string.Empty : slot.RegistrationPath);
		AddNormalizedPathIfNotBlank(linkedFiles, (slot == null) ? string.Empty : slot.SnapshotPath);
		AddNormalizedPathIfNotBlank(linkedFiles, (registration == null) ? string.Empty : registration.LastSnapshotPath);
		string resolvedRegistrationPath = ResolveRegistrationPathForSlot(_standardPolicy, slot);
		AddNormalizedPathIfNotBlank(linkedFiles, resolvedRegistrationPath);
		string activeRegistrationPath = Path.Combine(FamilyBrowserStandardPolicyStore.GetRegistryFolder(_workspaceRoot), "active-standard-library.json");
		if (string.Equals(NormalizePathForFileCompare(resolvedRegistrationPath), NormalizePathForFileCompare(activeRegistrationPath), StringComparison.OrdinalIgnoreCase) || ActiveRegistrationMatchesResetTarget(activeRegistrationPath, sourceIds, sourcePaths))
		{
			AddNormalizedPathIfNotBlank(linkedFiles, activeRegistrationPath);
		}
		foreach (string item in linkedFiles.ToList())
		{
			DeleteFileIfExists(item, deletedFiles, failedFiles);
		}
		DeleteMatchingStandardSnapshotCache(sourceIds, sourcePaths, linkedFiles, deletedFiles, failedFiles);
	}

	private void DeleteMatchingStandardSnapshotCache(HashSet<string> sourceIds, HashSet<string> sourcePaths, HashSet<string> linkedFiles, List<string> deletedFiles, List<string> failedFiles)
	{
		string snapshotFolder = FamilyBrowserStandardPolicyStore.GetSnapshotFolder(_workspaceRoot);
		if (string.IsNullOrWhiteSpace(snapshotFolder) || !Directory.Exists(snapshotFolder))
		{
			return;
		}
		IEnumerable<FileInfo> snapshotFiles;
		try
		{
			snapshotFiles = new DirectoryInfo(snapshotFolder).EnumerateFiles("standard-library-snapshot-*.json", SearchOption.TopDirectoryOnly).ToList();
		}
		catch (Exception projectError)
		{
			ProjectData.SetProjectError(projectError);
			ProjectData.ClearProjectError();
			return;
		}
		foreach (FileInfo fileInfo in snapshotFiles)
		{
			if (fileInfo == null)
			{
				continue;
			}
			string normalizedFilePath = NormalizePathForFileCompare(fileInfo.FullName);
			bool shouldDelete = linkedFiles?.Contains(normalizedFilePath) ?? false;
			if (!shouldDelete)
			{
				try
				{
					shouldDelete = StandardSnapshotMatchesResetTarget(LoadStandardSnapshotForDashboard(fileInfo.FullName), sourceIds, sourcePaths);
				}
				catch (Exception projectError2)
				{
					ProjectData.SetProjectError(projectError2);
					shouldDelete = false;
					ProjectData.ClearProjectError();
				}
			}
			if (shouldDelete)
			{
				DeleteFileIfExists(fileInfo.FullName, deletedFiles, failedFiles);
			}
		}
	}

	private static bool StandardSnapshotMatchesResetTarget(StandardLibrarySnapshot snapshot, HashSet<string> sourceIds, HashSet<string> sourcePaths)
	{
		if (snapshot == null)
		{
			return false;
		}
		if (sourceIds != null && sourceIds.Count > 0 && sourceIds.Contains(snapshot.SourceId ?? string.Empty))
		{
			return true;
		}
		if (sourcePaths == null || sourcePaths.Count == 0)
		{
			return false;
		}
		return sourcePaths.Contains(NormalizePathForFileCompare(snapshot.ResolvedPath)) || sourcePaths.Contains(NormalizePathForFileCompare(snapshot.Locator));
	}

	private static bool ActiveRegistrationMatchesResetTarget(string registrationPath, HashSet<string> sourceIds, HashSet<string> sourcePaths)
	{
		bool ActiveRegistrationMatchesResetTarget;
		if (string.IsNullOrWhiteSpace(registrationPath) || !File.Exists(registrationPath))
		{
			ActiveRegistrationMatchesResetTarget = false;
		}
		else
		{
			try
			{
				StandardLibraryRegistrationRecord registration = LoadStandardRegistrationForDashboard(registrationPath);
				ActiveRegistrationMatchesResetTarget = registration != null && ((sourceIds != null && sourceIds.Count > 0 && sourceIds.Contains(registration.SourceId ?? string.Empty)) || (sourcePaths != null && sourcePaths.Count != 0 && (sourcePaths.Contains(NormalizePathForFileCompare(registration.ResolvedPath)) || sourcePaths.Contains(NormalizePathForFileCompare(registration.Locator)))));
			}
			catch (Exception projectError)
			{
				ProjectData.SetProjectError(projectError);
				ActiveRegistrationMatchesResetTarget = false;
				ProjectData.ClearProjectError();
			}
		}
		return ActiveRegistrationMatchesResetTarget;
	}

	private static void AddIfNotBlank(HashSet<string> values, string value)
	{
		if (values != null && !string.IsNullOrWhiteSpace(value))
		{
			values.Add(value.Trim());
		}
	}

	private static void AddNormalizedPathIfNotBlank(HashSet<string> values, string value)
	{
		if (values != null && !string.IsNullOrWhiteSpace(value))
		{
			string normalized = NormalizePathForFileCompare(value);
			if (!string.IsNullOrWhiteSpace(normalized))
			{
				values.Add(normalized);
			}
		}
	}

	private static string NormalizePathForFileCompare(string value)
	{
		string NormalizePathForFileCompare;
		if (string.IsNullOrWhiteSpace(value))
		{
			NormalizePathForFileCompare = string.Empty;
		}
		else
		{
			try
			{
				NormalizePathForFileCompare = Path.GetFullPath(Environment.ExpandEnvironmentVariables(value.Trim())).TrimEnd(Path.DirectorySeparatorChar, Path.AltDirectorySeparatorChar);
			}
			catch (Exception projectError)
			{
				ProjectData.SetProjectError(projectError);
				NormalizePathForFileCompare = Environment.ExpandEnvironmentVariables(value.Trim()).TrimEnd(Path.DirectorySeparatorChar, Path.AltDirectorySeparatorChar);
				ProjectData.ClearProjectError();
			}
		}
		return NormalizePathForFileCompare;
	}

	private static void DeleteFileIfExists(string filePath, List<string> deletedFiles, List<string> failedFiles)
	{
		if (string.IsNullOrWhiteSpace(filePath))
		{
			return;
		}
		try
		{
			string normalizedPath = NormalizePathForFileCompare(filePath);
			if (!string.IsNullOrWhiteSpace(normalizedPath) && File.Exists(normalizedPath))
			{
				File.Delete(normalizedPath);
				deletedFiles?.Add(normalizedPath);
			}
		}
		catch (Exception ex)
		{
			ProjectData.SetProjectError(ex);
			Exception ex2 = ex;
			failedFiles?.Add(filePath + " - " + ex2.Message);
			ProjectData.ClearProjectError();
		}
	}

	private static void AddResetFolder(List<string> folders, string folderPath)
	{
		if (folders != null && !string.IsNullOrWhiteSpace(folderPath))
		{
			string text = NormalizePathForFileCompare(folderPath);
			if (!string.IsNullOrWhiteSpace(text) && !folders.Any([SpecialName] (string existing) => string.Equals(NormalizePathForFileCompare(existing), text, StringComparison.OrdinalIgnoreCase)))
			{
				folders.Add(text);
			}
		}
	}

	private static void DeleteResetFolder(string folderPath, List<string> deletedItems, List<string> failedItems)
	{
		if (string.IsNullOrWhiteSpace(folderPath))
		{
			return;
		}
		string normalized = NormalizePathForFileCompare(folderPath);
		if (string.IsNullOrWhiteSpace(normalized))
		{
			return;
		}
		try
		{
			if (Directory.Exists(normalized))
			{
				Directory.Delete(normalized, recursive: true);
				deletedItems?.Add(normalized);
			}
		}
		catch (Exception ex)
		{
			ProjectData.SetProjectError(ex);
			Exception ex2 = ex;
			failedItems?.Add(normalized + " - " + ex2.Message);
			ProjectData.ClearProjectError();
		}
	}

