	private void CheckStandardRvtChangesAndMaybeFastScan()
	{
		if (!EnsurePermission("RegisterStandard", T("Fast Standard RVT Check", "표준 RVT 빠른 변경 확인")))
		{
			return;
		}
		StandardLibraryRegistrationRecord registration = LoadRegistrationOrWarn(T("Fast Standard RVT Check", "표준 RVT 빠른 변경 확인"));
		if (registration != null)
		{
			StandardRvtFileStampStatus status = BuildStandardRvtFileStampStatus(registration, probeFile: true);
			if (status == null || !status.Exists)
			{
				ShowDashboardMessage(this, BuildStandardRvtUpdateSummary(status), T("Fast Standard RVT Check", "표준 RVT 빠른 변경 확인"), MessageBoxButtons.OK, MessageBoxIcon.Exclamation);
			}
			else if (status.HasAnyRecordedStamp && !status.ChangedSinceScan)
			{
				_statusMessage = T("No Standard RVT change detected. No scan was run.", "표준 RVT 변경이 감지되지 않았습니다. 스캔은 실행하지 않았습니다.");
				ShowDashboardMessage(this, _statusMessage, T("Fast Standard RVT Check", "표준 RVT 빠른 변경 확인"), MessageBoxButtons.OK, MessageBoxIcon.Asterisk);
				RefreshDocumentShellOnly();
			}
			else if (ShowDashboardMessage(this, BuildStandardRvtUpdateSummary(status) + Environment.NewLine + Environment.NewLine + T("Run a fast standard snapshot rebuild now?", "지금 표준 RVT 빠른 스캔을 실행할까요?"), T("Fast Standard RVT Check", "표준 RVT 빠른 변경 확인"), MessageBoxButtons.YesNo, MessageBoxIcon.Question) != DialogResult.Yes)
			{
				_statusMessage = T("Fast standard scan was cancelled.", "표준 RVT 빠른 스캔을 취소했습니다.");
				RefreshDocumentShellOnly();
			}
			else
			{
				RefreshRegisteredStandardRvt("Fast");
			}
		}
	}

	private void RefreshRegisteredStandardRvt(string snapshotMode)
	{
		bool isPreciseScan = string.Equals(snapshotMode, "Precise", StringComparison.OrdinalIgnoreCase);
		string caption = (isPreciseScan ? T("Full Precise Standard Scan", "표준 RVT 전체 정밀 스캔") : T("Fast Standard Scan", "표준 RVT 빠른 스캔"));
		try
		{
			if (!EnsurePermission("RegisterStandard", caption))
			{
				return;
			}
			_standardPolicy = LoadStandardPolicy();
			StandardLibraryRegistrationRecord registration = LoadRegistrationOrWarn(caption);
			if (registration == null)
			{
				return;
			}
			string standardPath = ((!string.IsNullOrWhiteSpace(registration.ResolvedPath)) ? registration.ResolvedPath : registration.Locator);
			if (string.IsNullOrWhiteSpace(standardPath) || !File.Exists(standardPath))
			{
				ShowDashboardMessage(this, T("The registered standard RVT file cannot be found: ", "등록된 표준 RVT 파일을 찾을 수 없습니다: ") + standardPath, caption, MessageBoxButtons.OK, MessageBoxIcon.Exclamation);
				return;
			}
			BeginLongOperationProgress(caption, isPreciseScan ? T("Preparing full precise standard scan...", "표준 RVT 전체 정밀 스캔을 준비하는 중...") : T("Preparing fast standard scan...", "표준 RVT 빠른 스캔을 준비하는 중..."));
			ISet<string> nestedScanFamilyNames = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
			if (isPreciseScan)
			{
				UpdateLongOperationProgress(caption, 4, 100, T("Preparing nested/helper family candidates...", "하위/헬퍼 패밀리 후보를 준비하는 중..."), forcePaint: true);
				nestedScanFamilyNames = BuildNestedLoadableScanFamilyNameSetForRegistration(_standardPolicy, standardPath);
			}
			else
			{
				UpdateLongOperationProgress(caption, 4, 100, T("Fast scan skips family edit, nested metadata, and 3D image generation.", "빠른 스캔은 패밀리 편집, 하위 메타데이터, 3D 이미지 생성을 건너뜁니다."), forcePaint: true);
			}
			StandardLibraryRegistrationResult result = StandardLibraryRegistrationService.Register(_workspaceRoot, _uiApplication.Application, standardPath, Environment.UserName, isPreciseScan ? "Precise" : "Fast", _uiApplication, nestedScanFamilyNames, forceSnapshotRebuild: true, CreateLongOperationProgressCallback(caption));
			AttachRegistrationResultToEffectiveSlot(result);
			ClearDashboardDataCaches();
			StoreStandardSnapshotForDashboard(result.SnapshotPath, result.Snapshot);
			StoreStandardRegistrationForDashboard(result.RegistrationPath, result.Registration);
			CompleteLongOperationProgress(T("Standard RVT scan finished.", "표준 RVT 스캔을 완료했습니다."));
			_statusMessage = (isPreciseScan ? T("Full precise standard scan completed. Project comparison was not run.", "표준 RVT 전체 정밀 스캔 완료. 프로젝트 비교는 실행하지 않았습니다.") : T("Fast standard scan completed. Project comparison was not run.", "표준 RVT 빠른 스캔 완료. 프로젝트 비교는 실행하지 않았습니다."));
			FamilyBrowserStandardFingerprintAuditExportResult fingerprintAudit = null;
			if (isPreciseScan)
			{
				fingerprintAudit = PromptSaveStandardListFingerprintAudit(result.Snapshot, result.Registration, FamilyBrowserStandardPolicyStore.GetEffectiveSlot(_standardPolicy), caption);
			}
			string resultMessage = _statusMessage + Environment.NewLine + Environment.NewLine + T("Target: ", "대상: ") + BuildPolicyTargetLabel() + Environment.NewLine + T("Scan mode: ", "스캔 방식: ") + (isPreciseScan ? "Precise" : "Fast") + Environment.NewLine + T("Loadable families: ", "로드 가능 패밀리: ") + result.Snapshot.Summary.LoadableFamilyCount.ToString(CultureInfo.InvariantCulture) + Environment.NewLine + T("System types: ", "시스템 타입: ") + result.Snapshot.Summary.SystemTypeCount.ToString(CultureInfo.InvariantCulture) + Environment.NewLine + BuildRegistrationDialogDiagnosticSummary(result) + BuildStandardFingerprintAuditDialogSummary(fingerprintAudit);
			if (isPreciseScan)
			{
				ShowDashboardMessage(this, resultMessage, caption, MessageBoxButtons.OK, MessageBoxIcon.Asterisk);
				RefreshDocumentShellOnly();
				return;
			}
			string guidanceMessage = resultMessage + Environment.NewLine + Environment.NewLine + T("Precise scan is required for 3D preview images and accurate fingerprint/parameter checks.", "3D 미리보기 및 정확한 Fingerprint/파라미터 검토를 위해서는 정밀 스캔이 필요합니다.");
			bool num = ShowDashboardChoiceMessage(this, guidanceMessage, caption, MessageBoxIcon.Asterisk, T("Open Standard RVT Manager", "표준 RVT 관리 패널 열기"), T("Close", "닫기")) == DialogResult.Yes;
			RefreshDocumentShellOnly();
			if (num)
			{
				ShowStandardRvtManager();
			}
		}
		catch (Exception ex)
		{
			ProjectData.SetProjectError(ex);
			Exception ex2 = ex;
			if (_longOperationActive)
			{
				CompleteLongOperationProgress(T("Standard RVT scan failed.", "표준 RVT 스캔에 실패했습니다."));
			}
			ShowLoggedError(caption, ex2);
			ProjectData.ClearProjectError();
		}
	}

