	private void UpdateSelectedStandardImages()
	{
		string text = T("Update Selected 3D Images", "선택 3D 이미지 갱신");
		if (!EnsurePermission("RegisterStandard", text))
		{
			return;
		}
		Document standardDoc = null;
		bool shouldCloseStandardDoc = false;
		try
		{
			StandardLibraryRegistrationRecord registration = LoadRegistrationOrWarn(text);
			if (registration == null)
			{
				return;
			}
			ISet<string> names = PromptStandardFamilyNameSet(text, T("Enter standard family names for 3D image refresh, one per line. Cached images are skipped when metadata matches.", "3D 이미지를 갱신할 표준 패밀리 이름을 한 줄에 하나씩 입력하세요. 메타데이터가 같으면 캐시 이미지는 건너뜁니다."), StandardRvtChangeCandidateService.BuildRecentLoadableFamilyNameText(_workspaceRoot, registration.SourceId));
			if (names.Count != 0)
			{
				BeginLongOperationProgress(text, T("Opening standard RVT for selected 3D images...", "선택 3D 이미지 갱신을 위해 표준 RVT를 여는 중..."));
				standardDoc = StandardLibraryDocumentResolver.OpenRegisteredDocument(_uiApplication.Application, registration, ref shouldCloseStandardDoc);
				FamilyThumbnailBatchUpdateResult result = FamilyThumbnailPreviewService.UpdateStandardCache(standardDoc, _workspaceRoot, registration, [SpecialName] (int current, int total, string name) =>
				{
					UpdateLongOperationProgress(text, current, total, T("Updating selected 3D images ", "선택 3D 이미지 업데이트 중 ") + current.ToString(CultureInfo.InvariantCulture) + "/" + total.ToString(CultureInfo.InvariantCulture) + "  " + name);
				}, _uiApplication, names);
				_statusMessage = T("Selected 3D image cache updated. Success: ", "선택 3D 이미지 캐시 업데이트 완료. 성공: ") + result.SuccessCount.ToString(CultureInfo.InvariantCulture) + T(" / Failed: ", " / 실패: ") + result.FailedCount.ToString(CultureInfo.InvariantCulture) + T(" / Skipped: ", " / 건너뜀: ") + result.SkippedCount.ToString(CultureInfo.InvariantCulture);
				CompleteLongOperationProgress(_statusMessage);
				ShowDashboardMessage(this, _statusMessage + Environment.NewLine + Environment.NewLine + T("Auto-confirmed warnings: ", "자동 확인 경고: ") + CountThumbnailAutoConfirmedDialogs(result).ToString(CultureInfo.InvariantCulture) + Environment.NewLine + BuildThumbnailFailureDetails(result) + BuildThumbnailDiagnosticPathLine(result), text, MessageBoxButtons.OK, (result.FailedCount > 0) ? MessageBoxIcon.Exclamation : MessageBoxIcon.Asterisk);
				PromptSaveThumbnailDiagnosticReport(result);
				RefreshDocumentShellOnly();
			}
		}
		catch (Exception ex)
		{
			ProjectData.SetProjectError(ex);
			Exception ex2 = ex;
			if (_longOperationActive)
			{
				CompleteLongOperationProgress(T("Selected 3D image cache update failed.", "선택 3D 이미지 캐시 업데이트에 실패했습니다."));
			}
			ShowLoggedError(text, ex2);
			ProjectData.ClearProjectError();
		}
		finally
		{
			if (shouldCloseStandardDoc && standardDoc != null)
			{
				try
				{
					standardDoc.Close(false);
				}
				catch (Exception projectError)
				{
					ProjectData.SetProjectError(projectError);
					ProjectData.ClearProjectError();
				}
			}
		}
	}

