	private ISet<string> BuildRecentLoadableFamilyCandidateNameSet(string sourceId)
	{
		HashSet<string> result = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
		if (string.IsNullOrWhiteSpace(sourceId))
		{
			return result;
		}
		try
		{
			foreach (StandardRvtChangeCandidateEntry entry in StandardRvtChangeCandidateService.LoadRecent(_workspaceRoot, sourceId, 160))
			{
				if (entry != null && string.Equals(entry.CandidateKind ?? string.Empty, "LoadableFamily", StringComparison.OrdinalIgnoreCase) && !string.IsNullOrWhiteSpace(entry.FamilyName))
				{
					result.Add(entry.FamilyName.Trim());
				}
			}
		}
		catch (Exception projectError)
		{
			ProjectData.SetProjectError(projectError);
			ProjectData.ClearProjectError();
		}
		return result;
	}

	private ISet<string> PromptStandardFamilyNameSet(string title, string prompt, string defaultValue = "")
	{
		HashSet<string> result = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
		string raw = Interaction.InputBox(prompt + Environment.NewLine + Environment.NewLine + T("Tip: paste Family names only. If you paste 'Category | Family', the Family part is used.", "팁: Family 이름만 붙여넣으세요. 'Category | Family' 형식이면 Family 부분만 사용합니다."), title, defaultValue ?? string.Empty);
		if (string.IsNullOrWhiteSpace(raw))
		{
			return result;
		}
		string[] array = raw.Replace("\r", "\n").Split(new string[1] { "\n" }, StringSplitOptions.RemoveEmptyEntries);
		checked
		{
			for (int i = 0; i < array.Length; i++)
			{
				string value = (array[i] ?? string.Empty).Trim();
				if (value.Contains("|"))
				{
					value = value.Substring(value.LastIndexOf('|') + 1).Trim();
				}
				if (value.Contains("\t"))
				{
					string[] array2 = value.Split(new string[1] { "\t" }, StringSplitOptions.None);
					value = array2[array2.Length - 1].Trim();
				}
				if (!string.IsNullOrWhiteSpace(value))
				{
					result.Add(value);
				}
			}
			return result;
		}
	}

	private void AttachRegistrationResultToEffectiveSlot(StandardLibraryRegistrationResult result)
	{
		if (result != null && result.Registration != null)
		{
			_registration = result.Registration;
			string requestedSlotKey = ResolveSlotKey(FamilyBrowserStandardPolicyStore.GetEffectiveSlot(_standardPolicy));
			StoreStandardRegistrationForDashboard(FamilyBrowserStandardPolicyStore.AttachRegistrationToSlot(_workspaceRoot, _standardPolicy, requestedSlotKey, result.Registration, Environment.UserName), result.Registration);
			_standardPolicy = LoadStandardPolicy();
			FamilyBrowserStandardLibrarySlot registeredSlot = ResolvePolicySlot(_standardPolicy, requestedSlotKey);
			if (registeredSlot != null)
			{
				_browseDisciplineKey = ResolveSlotKey(registeredSlot);
				_browseDisciplineAutoSelected = false;
			}
			UpdateStandardContext(_registration);
			InvalidateFastComparisonCache("standard-rvt-scan");
			StandardRvtChangeCandidateService.NotifyPolicyChanged();
		}
	}

	private void AttachPartialRefreshResultToEffectiveSlot(StandardLibraryPartialRefreshResult result)
	{
		if (result != null && result.Registration != null)
		{
			_registration = result.Registration;
			string requestedSlotKey = ResolveSlotKey(FamilyBrowserStandardPolicyStore.GetEffectiveSlot(_standardPolicy));
			StoreStandardRegistrationForDashboard(FamilyBrowserStandardPolicyStore.AttachRegistrationToSlot(_workspaceRoot, _standardPolicy, requestedSlotKey, result.Registration, Environment.UserName), result.Registration);
			_standardPolicy = LoadStandardPolicy();
			FamilyBrowserStandardLibrarySlot registeredSlot = ResolvePolicySlot(_standardPolicy, requestedSlotKey);
			if (registeredSlot != null)
			{
				_browseDisciplineKey = ResolveSlotKey(registeredSlot);
				_browseDisciplineAutoSelected = false;
			}
			UpdateStandardContext(_registration);
			InvalidateFastComparisonCache("standard-rvt-partial-refresh");
			StandardRvtChangeCandidateService.NotifyPolicyChanged();
		}
	}

	private string BuildMissingFamilyNameDetails(IEnumerable<string> names)
	{
		List<string> list = (names ?? Enumerable.Empty<string>()).Where([SpecialName] (string x) => !string.IsNullOrWhiteSpace(x)).Take(12).ToList();
		if (list.Count == 0)
		{
			return string.Empty;
		}
		return Environment.NewLine + T("Missing names: ", "찾지 못한 이름: ") + string.Join(", ", list) + Environment.NewLine;
	}

	private string BuildPartialRefreshDiagnosticSummary(StandardLibraryPartialRefreshResult result)
	{
		if (result == null)
		{
			return string.Empty;
