	private void UpdateStandardImages()
	{
		if (!EnsurePermission("RegisterStandard", T("Update 3D Images", "3D 이미지 업데이트")))
		{
			return;
		}
		Document standardDoc = null;
		bool shouldCloseStandardDoc = false;
		try
		{
			StandardLibraryRegistrationRecord registration = LoadRegistrationOrWarn(T("Update Images", "이미지 업데이트"));
			if (registration != null)
			{
				string title = T("3D Image Cache", "3D 이미지 캐시");
				BeginLongOperationProgress(title, T("Opening standard RVT for 3D image cache...", "3D 이미지 캐시 생성을 위해 표준 RVT를 여는 중..."));
				standardDoc = StandardLibraryDocumentResolver.OpenRegisteredDocument(_uiApplication.Application, registration, ref shouldCloseStandardDoc);
				FamilyThumbnailBatchUpdateResult result = FamilyThumbnailPreviewService.UpdateStandardCache(standardDoc, _workspaceRoot, registration, [SpecialName] (int current, int total, string name) =>
				{
					UpdateLongOperationProgress(title, current, total, T("Updating 3D images ", "3D 이미지 업데이트 중 ") + current.ToString(CultureInfo.InvariantCulture) + "/" + total.ToString(CultureInfo.InvariantCulture) + "  " + name);
				}, _uiApplication);
				_statusMessage = T("3D image cache updated. Success: ", "3D 이미지 캐시 업데이트 완료. 성공: ") + result.SuccessCount.ToString(CultureInfo.InvariantCulture) + T(" / Failed: ", " / 실패: ") + result.FailedCount.ToString(CultureInfo.InvariantCulture);
				CompleteLongOperationProgress(_statusMessage);
				ShowDashboardMessage(this, T("3D image cache updated.", "3D 이미지 캐시 업데이트 완료.") + Environment.NewLine + Environment.NewLine + T("Success: ", "성공: ") + result.SuccessCount.ToString(CultureInfo.InvariantCulture) + Environment.NewLine + T("Failed: ", "실패: ") + result.FailedCount.ToString(CultureInfo.InvariantCulture) + Environment.NewLine + T("Skipped: ", "건너뜀: ") + result.SkippedCount.ToString(CultureInfo.InvariantCulture) + Environment.NewLine + T("Auto-confirmed warnings: ", "자동 확인 경고: ") + CountThumbnailAutoConfirmedDialogs(result).ToString(CultureInfo.InvariantCulture) + Environment.NewLine + BuildThumbnailFailureDetails(result) + BuildThumbnailDiagnosticPathLine(result) + T("Image cache saved for admin diagnostics.", "이미지 캐시는 관리자 진단용으로 저장되었습니다."), T("Update Images", "이미지 업데이트"), MessageBoxButtons.OK, MessageBoxIcon.Asterisk);
				PromptSaveThumbnailDiagnosticReport(result);
				RefreshDocumentShellOnly();
			}
		}
		catch (Exception ex)
		{
			ProjectData.SetProjectError(ex);
			Exception ex2 = ex;
			if (_longOperationActive)
			{
				CompleteLongOperationProgress(T("3D image cache update failed.", "3D 이미지 캐시 업데이트에 실패했습니다."));
			}
			ShowLoggedError("Update Images", ex2);
			ProjectData.ClearProjectError();
		}
		finally
		{
			if (shouldCloseStandardDoc && standardDoc != null)
			{
				try
				{
					standardDoc.Close(false);
				}
				catch (Exception projectError)
				{
					ProjectData.SetProjectError(projectError);
					ProjectData.ClearProjectError();
				}
			}
		}
	}

