	private FamilyBrowserStandardFingerprintAuditExportResult PromptSaveStandardListFingerprintAudit(StandardLibrarySnapshot snapshot, StandardLibraryRegistrationRecord registration, FamilyBrowserStandardLibrarySlot slot, string caption)
	{
		FamilyBrowserStandardFingerprintAuditExportResult PromptSaveStandardListFingerprintAudit;
		if (snapshot == null || slot == null)
		{
			PromptSaveStandardListFingerprintAudit = null;
		}
		else
		{
			try
			{
				FamilyBrowserStandardListCatalog catalog = FamilyBrowserStandardListService.LoadForSlot(slot, registration);
				if (!FamilyBrowserStandardListService.IsFilteringEnabled(catalog))
				{
					PromptSaveStandardListFingerprintAudit = null;
				}
				else if (!FamilyBrowserStandardPolicyStore.IsManagedDataRootAvailable(_workspaceRoot))
				{
					PromptSaveStandardListFingerprintAudit = null;
				}
				else
				{
					string reportFolder = Path.Combine(FamilyBrowserStandardPolicyStore.GetDataFolder(_workspaceRoot, "Reports"), "StandardFingerprintAudit");
					Directory.CreateDirectory(reportFolder);
					string sourceName = ((!string.IsNullOrWhiteSpace(snapshot.ResolvedPath)) ? Path.GetFileNameWithoutExtension(snapshot.ResolvedPath) : (string.IsNullOrWhiteSpace(snapshot.DisplayName) ? "StandardRVT" : snapshot.DisplayName));
					string fileName = "standard-fingerprint-audit-" + SafeFileToken(ResolveSlotLabel(slot)) + "-" + SafeFileToken(sourceName) + "-" + DateTime.Now.ToString("yyyyMMdd-HHmmss", CultureInfo.InvariantCulture) + ".xlsx";
					if (ShowDashboardMessage(this, T("Save a fingerprint audit Excel based on the connected standard family list?", "연결된 표준 패밀리 리스트 기준으로 Fingerprint 점검 Excel을 저장할까요?"), caption, MessageBoxButtons.YesNo, MessageBoxIcon.Question) != DialogResult.Yes)
					{
						PromptSaveStandardListFingerprintAudit = new FamilyBrowserStandardFingerprintAuditExportResult
						{
							WasCanceled = true
						};
					}
					else
					{
						using SaveFileDialog dialog = new SaveFileDialog();
						dialog.Title = T("Save fingerprint audit Excel", "Fingerprint 점검 Excel 저장");
						dialog.Filter = "Excel Workbook (*.xlsx)|*.xlsx";
						dialog.DefaultExt = "xlsx";
						dialog.AddExtension = true;
						dialog.OverwritePrompt = true;
						dialog.CheckPathExists = true;
						dialog.RestoreDirectory = true;
						dialog.FileName = fileName;
						ConfigureExplorerSaveDialog(dialog, reportFolder);
						if (dialog.ShowDialog(this) != DialogResult.OK)
						{
							PromptSaveStandardListFingerprintAudit = new FamilyBrowserStandardFingerprintAuditExportResult
							{
								WasCanceled = true
							};
						}
						else
						{
							FamilyBrowserStandardFingerprintAuditExportResult result = FamilyBrowserStandardListExcelExportService.SaveFingerprintAudit(dialog.FileName, ResolveSlotLabel(slot), catalog, snapshot, ResolveSlotKey(slot), ResolveSlotLabel(slot), IsKorean());
							PromptOpenSavedExcel(result.OutputPath, caption, this);
							PromptSaveStandardListFingerprintAudit = result;
						}
					}
				}
			}
			catch (Exception ex)
			{
				ProjectData.SetProjectError(ex);
				Exception ex2 = ex;
				WriteDashboardRuntimeDiagnostic("standard-list-fingerprint-audit-failed: " + ex2.Message, -1, -1L);
				PromptSaveStandardListFingerprintAudit = new FamilyBrowserStandardFingerprintAuditExportResult
				{
					ErrorMessage = ex2.Message
				};
				ProjectData.ClearProjectError();
			}
		}
		return PromptSaveStandardListFingerprintAudit;
	}

	private FamilyBrowserStandardFingerprintAuditExportResult PromptSaveStandardListFingerprintAuditIfAvailable(FamilyBrowserStandardPolicy policy, FamilyBrowserStandardLibrarySlot slot, string caption)
	{
		FamilyBrowserStandardFingerprintAuditExportResult PromptSaveStandardListFingerprintAuditIfAvailable;
		if (policy == null || slot == null)
		{
			PromptSaveStandardListFingerprintAuditIfAvailable = null;
		}
		else
		{
			try
			{
				StandardLibraryRegistrationRecord registration = TryLoadRegistrationForSlot(policy, slot);
				if (registration == null || string.IsNullOrWhiteSpace(registration.LastSnapshotPath) || !File.Exists(registration.LastSnapshotPath))
				{
					PromptSaveStandardListFingerprintAuditIfAvailable = null;
				}
				else
				{
					StandardLibrarySnapshot snapshot = LoadStandardSnapshotForDashboard(registration.LastSnapshotPath);
					PromptSaveStandardListFingerprintAuditIfAvailable = ((snapshot != null && ShouldRunPreciseProjectContentCheck(snapshot)) ? PromptSaveStandardListFingerprintAudit(snapshot, registration, slot, caption) : null);
				}
			}
			catch (Exception ex)
			{
				ProjectData.SetProjectError(ex);
				Exception ex2 = ex;
				WriteDashboardRuntimeDiagnostic("standard-list-fingerprint-audit-after-list-connect-failed: " + ex2.Message, -1, -1L);
				PromptSaveStandardListFingerprintAuditIfAvailable = new FamilyBrowserStandardFingerprintAuditExportResult
				{
					ErrorMessage = ex2.Message
				};
				ProjectData.ClearProjectError();
			}
		}
		return PromptSaveStandardListFingerprintAuditIfAvailable;
	}

	private void SaveStandardFingerprintAuditForActiveSlot()
	{
		string caption = T("Fingerprint Audit Excel", "Fingerprint 점검 Excel");
		try
		{
			if (!EnsurePermission("ManagePolicy", caption))
			{
				return;
			}
			FamilyBrowserStandardPolicy policy = LoadStandardPolicy();
			FamilyBrowserStandardLibrarySlot slot = ResolveBrowseSlot(policy);
			if (slot == null)
			{
				slot = FamilyBrowserStandardPolicyStore.GetEffectiveSlot(policy);
			}
			if (slot == null)
			{
				ShowDashboardMessage(this, T("No active standard target is selected.", "선택된 표준 대상이 없습니다."), caption, MessageBoxButtons.OK, MessageBoxIcon.Asterisk);
				return;
			}
			FamilyBrowserStandardFingerprintAuditExportResult result = PromptSaveStandardListFingerprintAuditIfAvailable(policy, slot, caption);
			if (result == null)
			{
				ShowDashboardMessage(this, T("Fingerprint audit needs both a precise standard RVT scan and a connected standard list Excel/JSON.", "Fingerprint 점검은 표준 RVT 정밀 스캔 결과와 연결된 표준 목록 Excel/JSON이 둘 다 필요합니다."), caption, MessageBoxButtons.OK, MessageBoxIcon.Asterisk);
			}
			else
			{
				ShowDashboardMessage(this, BuildStandardFingerprintAuditDialogSummary(result), caption, MessageBoxButtons.OK, string.IsNullOrWhiteSpace(result.ErrorMessage) ? MessageBoxIcon.Asterisk : MessageBoxIcon.Exclamation);
			}
		}
		catch (Exception ex)
		{
			ProjectData.SetProjectError(ex);
			Exception ex2 = ex;
			ShowLoggedError("Fingerprint Audit Excel", ex2);
			ProjectData.ClearProjectError();
		}
	}

	private string BuildStandardFingerprintAuditDialogSummary(FamilyBrowserStandardFingerprintAuditExportResult result)
	{
		if (result == null)
		{
			return string.Empty;
		}
		if (result.WasCanceled)
		{
			return T("Fingerprint audit Excel was not saved.", "Fingerprint 점검 Excel 저장을 건너뛰었습니다.") + Environment.NewLine;
		}
		if (!string.IsNullOrWhiteSpace(result.ErrorMessage))
		{
			return T("Fingerprint audit Excel failed: ", "Fingerprint 점검 Excel 생성 실패: ") + result.ErrorMessage + Environment.NewLine;
		}
		if (string.IsNullOrWhiteSpace(result.OutputPath))
		{
			return string.Empty;
		}
		return T("Fingerprint audit Excel: ", "Fingerprint 점검 Excel: ") + result.OutputPath + Environment.NewLine + T("Audit rows: ", "점검 행: ") + result.RowCount.ToString(CultureInfo.InvariantCulture) + T(" / missing fingerprints: ", " / Fingerprint 없음: ") + result.MissingFingerprintCount.ToString(CultureInfo.InvariantCulture) + T(" / recovered from signature files: ", " / signature 파일에서 복구: ") + result.RecoveredFingerprintCount.ToString(CultureInfo.InvariantCulture) + T(" / missing from snapshot: ", " / 스냅샷에 없음: ") + result.MissingFromSnapshotCount.ToString(CultureInfo.InvariantCulture) + Environment.NewLine;
	}

	private int CountThumbnailAutoConfirmedDialogs(FamilyThumbnailBatchUpdateResult result)
	{
		if (result == null || result.AutoConfirmedDialogs == null)
		{
			return 0;
