	private void PromptSaveThumbnailDiagnosticReport(FamilyThumbnailBatchUpdateResult result)
	{
		if (result == null || (result.FailedCount <= 0 && CountThumbnailAutoConfirmedDialogs(result) <= 0) || ShowDashboardMessage(this, T("Save a snapshot diagnostic log to a chosen location?", "스냅샷 진단 로그를 원하는 위치에 저장할까요?"), T("Snapshot Diagnostics", "스냅샷 진단 로그"), MessageBoxButtons.YesNo, MessageBoxIcon.Question) != DialogResult.Yes)
		{
			return;
		}
		using SaveFileDialog dialog = new SaveFileDialog();
		dialog.Title = T("Save snapshot diagnostic log", "스냅샷 진단 로그 저장");
		dialog.Filter = "Text Log (*.txt)|*.txt|All files (*.*)|*.*";
		dialog.DefaultExt = "txt";
		dialog.AddExtension = true;
		dialog.OverwritePrompt = true;
		dialog.CheckPathExists = true;
		dialog.RestoreDirectory = true;
		dialog.FileName = "KKY-FamilyBrowser-snapshot-log-" + DateTime.Now.ToString("yyyyMMdd-HHmmss", CultureInfo.InvariantCulture) + ".txt";
		try
		{
			dialog.AutoUpgradeEnabled = true;
		}
		catch (Exception projectError)
		{
			ProjectData.SetProjectError(projectError);
			ProjectData.ClearProjectError();
		}
		if (!string.IsNullOrWhiteSpace(result.OutputFolder) && Directory.Exists(result.OutputFolder))
		{
			dialog.InitialDirectory = result.OutputFolder;
		}
		else
		{
			dialog.InitialDirectory = Environment.GetFolderPath(Environment.SpecialFolder.DesktopDirectory);
		}
		if (dialog.ShowDialog(this) == DialogResult.OK)
		{
			string savedPath = FamilyThumbnailPreviewService.SaveBatchDiagnosticReport(result, dialog.FileName);
			_statusMessage = T("Snapshot diagnostic log saved: ", "스냅샷 진단 로그 저장 완료: ") + savedPath;
			ShowDashboardMessage(this, _statusMessage, T("Snapshot Diagnostics", "스냅샷 진단 로그"), MessageBoxButtons.OK, MessageBoxIcon.Asterisk);
		}
	}

	private string BuildThumbnailFailureDetails(FamilyThumbnailBatchUpdateResult result)
	{
		if (result == null || result.Items == null)
		{
			return string.Empty;
		}
		List<FamilyThumbnailBatchUpdateItem> issueItems = result.Items.Where([SpecialName] (FamilyThumbnailBatchUpdateItem x) => x != null && !x.Success).Take(5).ToList();
		if (issueItems.Count == 0)
		{
			return string.Empty;
		}
		List<string> lines = new List<string>
		{
			string.Empty,
			T("Items needing attention:", "확인할 항목:")
		};
		foreach (FamilyThumbnailBatchUpdateItem item in issueItems)
		{
			lines.Add("- " + (string.IsNullOrWhiteSpace(item.CategoryName) ? "-" : item.CategoryName) + " / " + (string.IsNullOrWhiteSpace(item.FamilyName) ? "-" : item.FamilyName) + ": " + (string.IsNullOrWhiteSpace(item.Message) ? "-" : item.Message));
		}
		int remaining = checked(result.Items.Where([SpecialName] (FamilyThumbnailBatchUpdateItem x) => x != null && !x.Success).Count() - issueItems.Count);
		if (remaining > 0)
		{
			lines.Add(T("More items are recorded in admin diagnostics: ", "추가 항목은 관리자 진단 기록에 저장됨: ") + remaining.ToString(CultureInfo.InvariantCulture));
		}
		lines.Add(string.Empty);
		return string.Join(Environment.NewLine, lines);
	}

	private void ApplySelectedStandardFamilyFromAction(string encodedToken)
	{
		try
		{
			string[] parts = Uri.UnescapeDataString(encodedToken ?? string.Empty).Split(new string[1] { "||" }, StringSplitOptions.None);
			string selectedDiscipline = string.Empty;
			string selectedCategory = string.Empty;
			string selectedFamily = string.Empty;
			if (parts.Length >= 3)
			{
				selectedDiscipline = parts[0];
				selectedCategory = parts[1];
				selectedFamily = parts[2];
			}
			else if (parts.Length >= 2)
			{
				selectedCategory = parts[0];
				selectedFamily = parts[1];
			}
			if (string.IsNullOrWhiteSpace(selectedFamily))
			{
				ShowDashboardMessage(this, T("Select a family row before loading.", "로드할 패밀리 행을 먼저 선택하세요."), T("Load Selected Family", "선택 패밀리 로드"), MessageBoxButtons.OK, MessageBoxIcon.Asterisk);
				return;
			}
			BrowserRow selectedRow = FindLoadableRowForSelection(selectedDiscipline, selectedCategory, selectedFamily);
			if (selectedRow != null && IsCategoryMismatchLoadableRow(selectedRow))
			{
				ShowDashboardMessage(this, T("This family name exists in the project, but the category differs from the registered standard. Review the category mismatch before loading or overwriting.", "프로젝트에 같은 이름의 패밀리가 있지만 등록된 표준과 카테고리가 다릅니다. 로드 또는 덮어쓰기 전에 카테고리 불일치를 먼저 검토하세요."), T("Category Review", "카테고리 검토"), MessageBoxButtons.OK, MessageBoxIcon.Exclamation);
			}
			else
			{
				ApplyStandardFamilies(selectedCategory, selectedFamily, selectedDiscipline);
			}
		}
		catch (Exception ex)
		{
			ProjectData.SetProjectError(ex);
			Exception ex2 = ex;
			ShowLoggedError("Load Selected Family", ex2);
			ProjectData.ClearProjectError();
		}
	}

	private void ApplySelectedStandardFamiliesFromAction(string encodedToken)
	{
		try
		{
			List<LoadableFamilySelection> selections = ParseLoadableFamilySelections(encodedToken);
			if (selections.Count == 0)
			{
				ShowDashboardMessage(this, T("Check one or more family rows before applying.", "적용할 패밀리 행을 하나 이상 체크하세요."), T("Load Selected Families", "선택 패밀리 로드"), MessageBoxButtons.OK, MessageBoxIcon.Asterisk);
				return;
			}
			List<string> distinctDisciplines = (from x in selections
				select Normalize(x.DisciplineKey) into x
				where x.Length > 0
				select x).Distinct(StringComparer.Ordinal).ToList();
			if (distinctDisciplines.Count > 1)
			{
				ShowDashboardMessage(this, T("Apply checked families one standard target at a time. The current selection contains multiple trades or standard RVT targets.", "체크 패밀리는 한 번에 하나의 공종/표준 RVT 기준으로만 적용할 수 있습니다. 현재 선택에 여러 공종 또는 표준 대상이 섞여 있습니다."), T("Load Selected Families", "선택 패밀리 로드"), MessageBoxButtons.OK, MessageBoxIcon.Asterisk);
				return;
			}
			foreach (LoadableFamilySelection familySelection in selections)
			{
				BrowserRow selectedRow = FindLoadableRowForSelection(familySelection.DisciplineKey, familySelection.CategoryName, familySelection.FamilyName);
				if (selectedRow != null && IsCategoryMismatchLoadableRow(selectedRow))
				{
					ShowDashboardMessage(this, T("One or more checked families have category mismatches. Clear those rows or review the category before loading or overwriting.", "체크된 패밀리 중 카테고리 불일치 항목이 있습니다. 해당 행을 선택 해제하거나 카테고리 검토 후 로드/덮어쓰기를 진행하세요."), T("Category Review", "카테고리 검토"), MessageBoxButtons.OK, MessageBoxIcon.Exclamation);
					return;
				}
			}
			string selectedDiscipline = ((distinctDisciplines.Count == 1) ? distinctDisciplines[0] : _browseDisciplineKey);
			ApplyStandardFamilies(null, null, selectedDiscipline, selections);
		}
		catch (Exception ex)
		{
			ProjectData.SetProjectError(ex);
			Exception ex2 = ex;
			ShowLoggedError("Load Selected Families", ex2);
			ProjectData.ClearProjectError();
		}
	}

	private static List<LoadableFamilySelection> ParseLoadableFamilySelections(string encodedToken)
	{
		List<LoadableFamilySelection> result = new List<LoadableFamilySelection>();
		string obj = Uri.UnescapeDataString(encodedToken ?? string.Empty).Replace("\r\n", "\n").Replace("\r", "\n");
		HashSet<string> seen = new HashSet<string>(StringComparer.Ordinal);
		string[] array = obj.Split(new string[1] { "\n" }, StringSplitOptions.RemoveEmptyEntries);
		for (int i = 0; i < array.Length; i = checked(i + 1))
		{
			string[] parts = array[i].Split(new string[1] { "||" }, StringSplitOptions.None);
			if (parts.Length < 3)
			{
				continue;
			}
			LoadableFamilySelection familySelection = new LoadableFamilySelection
			{
				DisciplineKey = (parts[0] ?? string.Empty).Trim(),
				CategoryName = (parts[1] ?? string.Empty).Trim(),
				FamilyName = (parts[2] ?? string.Empty).Trim()
			};
			if (!string.IsNullOrWhiteSpace(familySelection.FamilyName))
			{
				string key = BuildFamilySelectionKey(familySelection.CategoryName, familySelection.FamilyName);
				if (seen.Add(key))
				{
					result.Add(familySelection);
				}
			}
		}
		return result;
	}

	private bool IsActiveStandardUnavailable(StandardLibraryRegistrationRecord registration)
	{
		if (registration == null)
		{
			return true;
		}
		if (string.IsNullOrWhiteSpace(registration.ResolvedPath))
		{
			return true;
		}
		return false;
	}

	private void ApplyStandardFamilies(string selectedCategoryName = null, string selectedFamilyName = null, string selectedDisciplineKey = null, IList<LoadableFamilySelection> selectedFamilies = null)
	{
		int selectedFamilyCount = selectedFamilies?.Count ?? 0;
		bool isSelectedApply = !string.IsNullOrWhiteSpace(selectedFamilyName) || selectedFamilyCount > 0;
		string commandTitle = ((!isSelectedApply) ? T("Update Existing Standard Families", "기존 표준 패밀리 업데이트") : ((selectedFamilyCount > 1) ? T("Load Selected Families", "선택 패밀리 로드") : T("Load Selected Family", "선택 패밀리 로드")));
		if ((!isSelectedApply && !EnsurePermission("ManagePolicy", commandTitle)) || !EnsurePermission("LoadFamilies", commandTitle) || !(isSelectedApply ? EnsureReadinessAllows(commandTitle, new string[1] { "Policy" }) : EnsureReadinessAllowsContentApply(T("Apply Standard Families", "표준 패밀리 적용"))))
		{
			return;
		}
		Document standardDoc = null;
		bool shouldCloseStandardDoc = false;
		checked
		{
			try
			{
				Document doc = GetActiveDocument();
				if (doc == null)
				{
					ShowDashboardMessage(this, T("Open a Revit project before loading standard families.", "표준 패밀리를 로드하기 전에 Revit 프로젝트를 열어주세요."), T("Apply Standard Families", "표준 패밀리 적용"), MessageBoxButtons.OK, MessageBoxIcon.Asterisk);
					return;
				}
				StandardLibraryRegistrationRecord registration = LoadRegistrationOrWarn(T("Apply Standard Families", "표준 패밀리 적용"), selectedDisciplineKey);
				if (registration == null)
				{
					return;
				}
				StandardLibrarySnapshot standardSnapshot = LoadStandardSnapshotForDashboard(registration.LastSnapshotPath);
				string title = ((!isSelectedApply) ? T("Update Existing Standard Families", "기존 표준 패밀리 업데이트") : ((selectedFamilyCount > 1) ? T("Load Selected Families", "선택 패밀리 로드") : T("Load Selected Family", "선택 패밀리 로드")));
				BeginLongOperationProgress(title, T("Preparing family load plan...", "패밀리 로드 계획을 준비하는 중..."));
				FamilyBrowserStandardLibrarySlot applySlot = ResolvePolicySlot(_standardPolicy, selectedDisciplineKey);
				string applyDisciplineKey = ResolveSlotKey(applySlot);
				string applyDisciplineLabel = ResolveSlotLabel(applySlot);
				FamilyBrowserStandardListCatalog standardListCatalog = LoadStandardListCatalogForDashboard(applySlot, registration);
				bool allowFingerprintOverwrite = !isSelectedApply || HasPermission("ManagePolicy");
				string comparisonPath = string.Empty;
				int skippedMissingFamilyCount = 0;
				int skippedLatestFamilyCount = 0;
				LoadableFamilySyncPlan plan;
				if (isSelectedApply)
				{
					Stopwatch planSw = Stopwatch.StartNew();
					UpdateLongOperationProgress(title, 12, 100, T("Preparing selected family load plan...", "선택 패밀리 로드 계획을 준비하는 중..."), forcePaint: true);
					plan = BuildSelectedLoadableFamilyLoadPlan(doc, registration, standardSnapshot, selectedCategoryName, selectedFamilyName, selectedFamilies);
					WriteDashboardRuntimeDiagnostic("FamilyLoad.SelectedPlan.Fast", (plan.Items != null) ? plan.Items.Count : 0, planSw.ElapsedMilliseconds);
					UpdateLongOperationProgress(title, 100, 100, T("Selected family load plan prepared.", "선택 패밀리 로드 계획을 준비했습니다."), forcePaint: true);
				}
				else
				{
					string fingerprintDebugRunFolder = FingerprintDebugSignatureStore.CreateProjectRunFolder(_workspaceRoot, doc.Title ?? string.Empty, DateTime.UtcNow.ToString("O", CultureInfo.InvariantCulture), ProjectSnapshotStore.ResolveProjectIdentityPath(doc));
					ProjectContentSnapshot projectSnapshot = ProjectSnapshotCaptureService.Capture(doc, null, includeDeepLoadableContent: false, [SpecialName] (int current, int total, string message) =>
					{
						UpdateLongOperationProgressRange(title, 8, 48, current, total, message);
					}, fingerprintDebugRunFolder);
					UpdateLongOperationProgress(title, 52, 100, T("Saving current project snapshot...", "현재 프로젝트 스냅샷을 저장하는 중..."), forcePaint: true);
					string projectSnapshotPath = ProjectSnapshotStore.Save(_workspaceRoot, projectSnapshot, doc);
					ProjectTrackingCatalog trackingCatalog = ProjectTrackingStoreService.Load(doc);
					UpdateLongOperationProgress(title, 62, 100, T("Building family comparison report...", "패밀리 비교 리포트를 만드는 중..."), forcePaint: true);
					ProjectStandardComparisonReport comparison = ProjectStandardComparisonService.BuildReport(registration, registration.LastSnapshotPath, standardSnapshot, projectSnapshotPath, projectSnapshot, trackingCatalog);
					comparison = FilterComparisonByStandardList(comparison, standardListCatalog, applyDisciplineKey, applyDisciplineLabel, standardSnapshot);
					UpdateLongOperationProgress(title, 82, 100, T("Saving family comparison report...", "패밀리 비교 리포트를 저장하는 중..."), forcePaint: true);
					comparisonPath = ProjectStandardComparisonStore.Save(_workspaceRoot, comparison);
					UpdateLongOperationProgress(title, 90, 100, T("Building family load execution plan...", "패밀리 로드 실행 계획을 만드는 중..."), forcePaint: true);
					plan = LoadableFamilySyncPlannerService.BuildPlan(comparison, comparisonPath, allowFingerprintOverwrite, isSelectedApply);
					if (!isSelectedApply)
					{
						int fullPlanItemCount = ((plan.Items != null) ? plan.Items.Count : 0);
						skippedLatestFamilyCount = CountFamilyPlanAction(plan, "keepcurrent");
						skippedMissingFamilyCount = CountFamilyPlanAction(plan, "skipmissingfromproject");
						LoadableFamilySyncPlan filteredPlan = FilterFamilyPlanForExistingUpdate(plan);
						WriteDashboardRuntimeDiagnostic("FamilyLoad.ExistingUpdatePlan.Filtered total=" + fullPlanItemCount.ToString(CultureInfo.InvariantCulture) + " actionable=" + ((filteredPlan.Items != null) ? filteredPlan.Items.Count : 0).ToString(CultureInfo.InvariantCulture) + " latestSkipped=" + skippedLatestFamilyCount.ToString(CultureInfo.InvariantCulture) + " missingSkipped=" + skippedMissingFamilyCount.ToString(CultureInfo.InvariantCulture), -1, -1L);
						plan = filteredPlan;
					}
					UpdateLongOperationProgress(title, 100, 100, T("Family load plan prepared.", "패밀리 로드 계획을 준비했습니다."), forcePaint: true);
				}
				CompleteLongOperationProgress(T("Family load plan prepared.", "패밀리 로드 계획을 준비했습니다."));
				string scopeText = BuildSelectedFamilyScopeText(selectedCategoryName, selectedFamilyName, selectedDisciplineKey, selectedFamilies);
				int num = plan.Summary.LoadCount + plan.Summary.ReloadCount + plan.Summary.StampOnlyCount;
				string categoryMismatchSummary = BuildCategoryMismatchBlockerSummary(plan, 6);
				if (num == 0)
				{
					string noActionMessage = (isSelectedApply ? T("No selected family is in Load Available state. Existing family updates are handled from Admin Settings only.", "선택한 항목 중 로드 가능 상태의 패밀리가 없습니다. 기존 패밀리 업데이트는 관리자 설정에서만 실행합니다.") : T("No loaded family needs a standard update.", "표준 업데이트가 필요한 기존 로드 패밀리가 없습니다."));
					if (scopeText.Length > 0)
					{
						noActionMessage = scopeText + noActionMessage;
					}
					if (plan.Summary.BlockedCount > 0)
					{
						noActionMessage = noActionMessage + Environment.NewLine + T("Manual review required: ", "수동 검토 필요: ") + plan.Summary.BlockedCount.ToString(CultureInfo.InvariantCulture);
					}
					if (!isSelectedApply && skippedLatestFamilyCount > 0)
					{
						noActionMessage = noActionMessage + Environment.NewLine + T("Latest families left unchanged: ", "최신 확인 패밀리 유지: ") + skippedLatestFamilyCount.ToString(CultureInfo.InvariantCulture);
					}
					if (categoryMismatchSummary.Length > 0)
					{
						noActionMessage = noActionMessage + Environment.NewLine + Environment.NewLine + categoryMismatchSummary;
					}
					ShowDashboardMessage(this, noActionMessage, commandTitle, MessageBoxButtons.OK, MessageBoxIcon.Asterisk);
					_lastComparisonPath = comparisonPath;
					if (isSelectedApply)
					{
						RefreshDocumentShellOnly();
					}
					else
					{
						RefreshDashboard();
					}
					return;
				}
				string confirmMessage = ((!isSelectedApply) ? ((allowFingerprintOverwrite ? T("Update existing project families from the registered standard? Missing families will not be created.", "현재 프로젝트에 이미 로드된 패밀리만 표준 기준으로 업데이트할까요? 누락 패밀리는 새로 로드하지 않습니다.") : T("Apply standard family changes to existing loaded families?", "기존에 로드된 패밀리에만 표준 패밀리 변경을 적용할까요?")) + Environment.NewLine + Environment.NewLine + T("Latest families left unchanged: ", "최신 확인 패밀리 유지: ") + skippedLatestFamilyCount.ToString(CultureInfo.InvariantCulture) + Environment.NewLine + T("Missing families skipped: ", "누락 패밀리 건너뜀: ") + skippedMissingFamilyCount.ToString(CultureInfo.InvariantCulture) + Environment.NewLine + T("Reload different families: ", "변경 패밀리 재로드: ") + plan.Summary.ReloadCount.ToString(CultureInfo.InvariantCulture) + Environment.NewLine + T("Refresh tracking only: ", "추적만 갱신: ") + plan.Summary.StampOnlyCount.ToString(CultureInfo.InvariantCulture) + Environment.NewLine + T("Manual review blocked: ", "수동 검토 차단: ") + plan.Summary.BlockedCount.ToString(CultureInfo.InvariantCulture)) : (T("Load the selected missing standard families into the current model?", "선택한 누락 표준 패밀리를 현재 모델에 로드할까요?") + Environment.NewLine + Environment.NewLine + T("Load selected families: ", "선택 패밀리 로드: ") + plan.Summary.LoadCount.ToString(CultureInfo.InvariantCulture) + Environment.NewLine + T("Existing family updates are available only from Admin Settings.", "기존 패밀리 업데이트는 관리자 설정에서만 실행합니다.")));
				if (categoryMismatchSummary.Length > 0)
				{
					confirmMessage = confirmMessage + Environment.NewLine + Environment.NewLine + categoryMismatchSummary;
				}
				if (scopeText.Length > 0)
				{
					confirmMessage = scopeText + confirmMessage;
				}
				if (ShowDashboardMessage(this, confirmMessage, commandTitle, MessageBoxButtons.YesNo, MessageBoxIcon.Question) != DialogResult.Yes)
				{
					_statusMessage = T("Family load was cancelled.", "패밀리 로드가 취소되었습니다.");
					RenderDashboard();
					return;
				}
				BeginLongOperationProgress(title, (!isSelectedApply) ? T("Updating existing standard families...", "기존 표준 패밀리를 업데이트하는 중...") : ((selectedFamilyCount > 1) ? T("Loading selected standard families...", "선택한 표준 패밀리들을 로드하는 중...") : T("Loading selected standard family...", "선택한 표준 패밀리를 로드하는 중...")));
				if (plan.Summary.LoadCount + plan.Summary.ReloadCount > 0)
				{
					UpdateLongOperationProgress(title, 8, 100, T("Opening registered standard RVT...", "등록된 표준 RVT를 여는 중..."), forcePaint: true);
					standardDoc = StandardLibraryDocumentResolver.OpenRegisteredDocument(_uiApplication.Application, registration, ref shouldCloseStandardDoc);
				}
				LoadableFamilySyncExecutionReport execution = LoadableFamilySyncExecutionService.Execute(doc, standardDoc, plan, [SpecialName] (int current, int total, string message) =>
				{
					UpdateLongOperationProgressRange(title, 15, 78, current, total, message);
				});
				execution.ComparisonPath = comparisonPath;
				if (execution.Summary.LoadedCount + execution.Summary.ReloadedCount > 0 || plan.Summary.StampOnlyCount > 0)
				{
					UpdateLongOperationProgress(title, 84, 100, isSelectedApply ? T("Refreshing selected family tracking stamp...", "선택 패밀리 추적 스탬프를 갱신하는 중...") : T("Refreshing tracking for updated families...", "업데이트된 패밀리 추적 스탬프를 갱신하는 중..."), forcePaint: true);
					RefreshSelectedFamilyTrackingAfterLoad(doc, registration, standardSnapshot, plan, execution);
				}
				string executionReportPath = LoadableFamilySyncStore.Save(_workspaceRoot, execution);
				StandardRvtChangeCandidateService.RecordLoadableFamilyOperation(_workspaceRoot, doc, registration, execution, isSelectedApply ? "LoadSelectedStandardFamilies" : "UpdateExistingStandardFamilies");
				_statusMessage = ((!isSelectedApply) ? T("Existing standard family update completed: ", "기존 표준 패밀리 업데이트 완료: ") : ((selectedFamilyCount > 1) ? T("Selected standard families load completed: ", "선택 표준 패밀리 로드 완료: ") : T("Selected standard family load completed: ", "선택 표준 패밀리 로드 완료: "))) + T("Loaded ", "로드됨 ") + execution.Summary.LoadedCount.ToString(CultureInfo.InvariantCulture) + T(" / Reloaded ", " / 재로드됨 ") + execution.Summary.ReloadedCount.ToString(CultureInfo.InvariantCulture) + T(" / Failed ", " / 실패 ") + execution.Summary.FailedCount.ToString(CultureInfo.InvariantCulture);
				CompleteLongOperationProgress(_statusMessage);
				using (FamilyLoadResultDialog resultDialog = new FamilyLoadResultDialog(IsKorean(), commandTitle, isSelectedApply ? T("Selected standard family load completed.", "선택 표준 패밀리 로드가 완료되었습니다.") : T("Existing standard family update completed.", "기존 표준 패밀리 업데이트가 완료되었습니다."), scopeText, execution, executionReportPath))
				{
					resultDialog.ShowDialog(this);
				}
				MarkCurrentProjectContentChanged(BuildCurrentDocumentRuntimeKey());
				if (isSelectedApply)
				{
					RefreshDocumentShellOnly();
				}
				else
				{
					RefreshDashboard();
				}
			}
			catch (Exception ex)
			{
				ProjectData.SetProjectError(ex);
				Exception ex2 = ex;
				if (_longOperationActive)
				{
					CompleteLongOperationProgress(T("Family load failed.", "패밀리 로드에 실패했습니다."));
				}
				ShowLoggedError(commandTitle, ex2);
				ProjectData.ClearProjectError();
			}
			finally
			{
				if (shouldCloseStandardDoc && standardDoc != null)
				{
					try
					{
						standardDoc.Close(false);
					}
					catch (Exception projectError)
					{
						ProjectData.SetProjectError(projectError);
						ProjectData.ClearProjectError();
					}
				}
			}
		}
	}

	private void StampCurrentProjectTracking()
	{
		//IL_00a9: Unknown result type (might be due to invalid IL or missing references)
		//IL_00b0: Expected O, but got Unknown
		//IL_00b2: Unknown result type (might be due to invalid IL or missing references)
		//IL_00c2: Unknown result type (might be due to invalid IL or missing references)
		try
		{
			if (!EnsurePermission("StampTracking", T("Stamp Tracking", "추적 스탬프")))
			{
				return;
			}
			Document doc = GetActiveDocument();
			if (doc == null)
			{
				ShowDashboardMessage(this, T("Open a Revit project before stamping tracking.", "추적 스탬프를 찍기 전에 Revit 프로젝트를 열어주세요."), T("Stamp Tracking", "추적 스탬프"), MessageBoxButtons.OK, MessageBoxIcon.Asterisk);
				return;
			}
			StandardLibraryRegistrationRecord registration = LoadRegistrationOrWarn(T("Stamp Tracking", "추적 스탬프"));
			if (registration != null)
			{
				StandardLibrarySnapshot standardSnapshot = LoadStandardSnapshotForDashboard(registration.LastSnapshotPath);
				ProjectContentSnapshot projectSnapshot = ProjectSnapshotCaptureService.Capture(doc);
				ProjectTrackingCatalog catalog = ProjectTrackingStampService.BuildCatalog(registration, standardSnapshot, projectSnapshot);
				Transaction tx = new Transaction(doc, "KKY Family Browser Stamp Tracking");
				try
				{
					tx.Start();
					ProjectTrackingStoreService.Save(doc, catalog);
					tx.Commit();
				}
				finally
				{
					((IDisposable)tx)?.Dispose();
				}
				ProjectTrackingOutputStore.Save(_workspaceRoot, catalog);
				ProjectTrackingStoreService.ClearCurrentModelCheckRequired(doc);
				ShowDashboardMessage(this, T("Tracking stamped.", "추적 스탬프 완료.") + Environment.NewLine + Environment.NewLine + T("Tracked loadable families: ", "추적된 로드 가능 패밀리: ") + catalog.LoadableFamilies.Count.ToString(CultureInfo.InvariantCulture) + Environment.NewLine + T("Tracked system types: ", "추적된 시스템 타입: ") + catalog.SystemTypes.Count.ToString(CultureInfo.InvariantCulture) + Environment.NewLine + T("Tracking report saved for admin diagnostics.", "추적 리포트는 관리자 진단용으로 저장되었습니다."), T("Stamp Tracking", "추적 스탬프"), MessageBoxButtons.OK, MessageBoxIcon.Asterisk);
				MarkCurrentProjectContentChanged(BuildCurrentDocumentRuntimeKey());
				RefreshDashboard();
			}
		}
		catch (Exception ex)
		{
			ProjectData.SetProjectError(ex);
			Exception ex2 = ex;
			ShowLoggedError("Stamp Tracking", ex2);
			ProjectData.ClearProjectError();
		}
	}

	private void CheckTracking()
	{
		try
		{
			Document doc = GetActiveDocument();
			if (doc == null)
			{
				ShowDashboardMessage(this, T("Open a Revit project before checking tracking.", "추적 상태를 확인하기 전에 Revit 프로젝트를 열어주세요."), T("Check Tracking", "추적 확인"), MessageBoxButtons.OK, MessageBoxIcon.Asterisk);
