		}
		catch (Exception ex)
		{
			ProjectData.SetProjectError(ex);
			Exception ex2 = ex;
			ShowLoggedError("Check Tracking", ex2);
			ProjectData.ClearProjectError();
		}
	}

	private void RunSystemPreflight()
	{
		Document standardDoc = null;
		bool shouldCloseStandardDoc = false;
		try
		{
			Document doc = GetActiveDocument();
			if (doc == null)
			{
				ShowDashboardMessage(this, T("Open a Revit project before reviewing system types.", "시스템 타입 검토를 실행하기 전에 Revit 프로젝트를 열어주세요."), T("System Type Review", "시스템 타입 검토"), MessageBoxButtons.OK, MessageBoxIcon.Asterisk);
				return;
			}
			StandardLibraryRegistrationRecord registration = LoadRegistrationOrWarn(T("System Type Review", "시스템 타입 검토"), _browseDisciplineKey);
			if (registration != null)
			{
				string operationTitle = T("System Type Diagnostics", "시스템 타입 정밀 진단");
				BeginLongOperationProgress(operationTitle, T("Opening registered standard RVT...", "등록된 표준 RVT를 여는 중..."));
				SystemTypePreflightReport report = null;
				List<FamilyThumbnailAutoConfirmedDialogRecord> systemPreflightAutoDialogs = new List<FamilyThumbnailAutoConfirmedDialogRecord>();
				using (FamilyThumbnailConstraintDialogGuard dialogGuard = new FamilyThumbnailConstraintDialogGuard(_uiApplication))
				{
					standardDoc = StandardLibraryDocumentResolver.OpenRegisteredDocument(_uiApplication.Application, registration, ref shouldCloseStandardDoc);
					UpdateLongOperationProgress(operationTitle, 8, 100, T("Reading system type definitions...", "시스템 타입 정의를 읽는 중..."), forcePaint: true);
					report = SystemTypePreflightBuilderService.BuildReport(registration, standardDoc, doc, includeApplyDryRun: true, CreateLongOperationProgressCallback(operationTitle));
					systemPreflightAutoDialogs = dialogGuard.GetRecordsSince(0);
				}
				FamilyBrowserStandardLibrarySlot slot = ResolvePolicySlot(_standardPolicy, _browseDisciplineKey);
				string disciplineKey = ResolveSlotKey(slot);
				string disciplineLabel = ResolveSlotLabel(slot);
				UpdateLongOperationProgress(operationTitle, 88, 100, T("Filtering diagnostics by selected standard list...", "선택된 표준 목록 기준으로 진단 결과를 필터링하는 중..."), forcePaint: true);
				FamilyBrowserStandardListCatalog standardListCatalog = LoadStandardListCatalogForDashboard(slot, registration);
				report = FilterSystemPreflightByStandardList(report, standardListCatalog, disciplineKey, disciplineLabel);
				UpdateLongOperationProgress(operationTitle, 96, 100, T("Saving system type diagnostics report...", "시스템 타입 진단 리포트를 저장하는 중..."), forcePaint: true);
				_lastPreflightPath = SystemTypePreflightStore.Save(_workspaceRoot, report);
				UpdateSystemRowsFromPreflight(report, _browseDisciplineKey);
				_statusMessage = T("System type review completed. Rows refreshed.", "시스템 타입 검토 완료. 목록을 새로고쳤습니다.") + " " + T("Ready: ", "준비: ") + report.Summary.ReadyCount.ToString(CultureInfo.InvariantCulture) + " / " + T("Review: ", "검토: ") + checked(report.Summary.ApprovalRequiredCount + report.Summary.DependencyManualReviewCount).ToString(CultureInfo.InvariantCulture) + " / " + T("Blocked: ", "차단: ") + report.Summary.BlockedCount.ToString(CultureInfo.InvariantCulture);
				CompleteLongOperationProgress(_statusMessage);
				RenderDashboard();
				ShowDashboardMessage(this, BuildSystemPreflightResultMessage(report, disciplineLabel, systemPreflightAutoDialogs), operationTitle, MessageBoxButtons.OK, (report.Summary.BlockedCount > 0 || report.Summary.LoadableFoundationBlockedCount > 0 || report.Summary.DependencyManualReviewCount > 0) ? MessageBoxIcon.Exclamation : MessageBoxIcon.Asterisk);
			}
		}
		catch (Exception ex)
		{
			ProjectData.SetProjectError(ex);
			Exception ex2 = ex;
			if (_longOperationActive)
			{
				CompleteLongOperationProgress(T("System type diagnostics failed.", "시스템 타입 정밀 진단에 실패했습니다."));
			}
			ShowLoggedError("System Type Review", ex2);
			ProjectData.ClearProjectError();
		}
		finally
		{
			if (shouldCloseStandardDoc && standardDoc != null)
			{
				try
				{
					standardDoc.Close(false);
				}
				catch (Exception projectError)
				{
					ProjectData.SetProjectError(projectError);
					ProjectData.ClearProjectError();
				}
			}
		}
	}

	private string BuildCurrentModelCheckResultMessage(ProjectStandardComparisonReport report, ProjectContentSnapshot projectSnapshot, string disciplineLabel, IEnumerable<FamilyThumbnailAutoConfirmedDialogRecord> autoDialogRecords = null)
	{
		ProjectStandardComparisonSummary summary = report?.Summary ?? new ProjectStandardComparisonSummary();
		ProjectContentSnapshotSummary snapshotSummary = projectSnapshot?.Summary ?? new ProjectContentSnapshotSummary();
		checked
		{
			int loadableActionCount = summary.LoadableLoadAvailableCount + summary.LoadableDifferentCount;
			int systemActionCount = summary.SystemLoadAvailableCount + summary.SystemDifferentCount;
			string targetText = FirstNonEmptyValue(disciplineLabel, report?.Standard?.DisplayName ?? string.Empty, "-");
			string projectText = FirstNonEmptyValue(report?.Project?.DocumentTitle ?? string.Empty, projectSnapshot?.DocumentTitle ?? string.Empty, "-");
			string standardText = FirstNonEmptyValue(report?.Standard?.DisplayName ?? string.Empty, targetText);
			StringBuilder builder = new StringBuilder();
			builder.AppendLine(T("Current Model Check completed.", "현재 모델 검사를 완료했습니다."));
			builder.AppendLine();
			builder.AppendLine(T("Review target: ", "검사 기준: ") + targetText);
			builder.AppendLine(T("Standard RVT: ", "표준 RVT: ") + standardText);
			builder.AppendLine(T("Project: ", "프로젝트: ") + projectText);
			builder.AppendLine();
			builder.AppendLine(T("Scanned current project", "현재 프로젝트 스캔"));
			builder.AppendLine("- " + T("Loadable families: ", "로더블 패밀리: ") + snapshotSummary.LoadableFamilyCount.ToString(CultureInfo.InvariantCulture));
			builder.AppendLine("- " + T("Loadable types: ", "로더블 타입: ") + snapshotSummary.LoadableTypeCount.ToString(CultureInfo.InvariantCulture));
			if (snapshotSummary.LoadableFingerprintWrittenCount > 0 || snapshotSummary.LoadableFingerprintMissingCount > 0 || snapshotSummary.LoadableSignatureMissingCount > 0)
			{
				int missingFingerprintCount = ((snapshotSummary.LoadableFingerprintMissingCount > 0) ? snapshotSummary.LoadableFingerprintMissingCount : snapshotSummary.LoadableSignatureMissingCount);
				int writtenFingerprintCount = ((snapshotSummary.LoadableFingerprintWrittenCount > 0) ? snapshotSummary.LoadableFingerprintWrittenCount : Math.Max(0, snapshotSummary.LoadableFamilyCount - missingFingerprintCount));
				builder.AppendLine("- " + T("Current project fingerprints: ", "현재 프로젝트 Fingerprint: ") + writtenFingerprintCount.ToString(CultureInfo.InvariantCulture) + T(" created / ", "개 생성 / ") + missingFingerprintCount.ToString(CultureInfo.InvariantCulture) + T(" missing", "개 누락"));
			}
			if (snapshotSummary.LoadableSignatureWrittenCount > 0 || snapshotSummary.LoadableSignatureFileMissingCount > 0)
			{
				builder.AppendLine("- " + T("Signature diagnostic files: ", "Signature 진단 파일: ") + snapshotSummary.LoadableSignatureWrittenCount.ToString(CultureInfo.InvariantCulture) + T(" written / ", "개 저장 / ") + snapshotSummary.LoadableSignatureFileMissingCount.ToString(CultureInfo.InvariantCulture) + T(" file-write failed", "개 파일 저장 실패"));
			}
			builder.AppendLine("- " + T("System types: ", "시스템 타입: ") + snapshotSummary.SystemTypeCount.ToString(CultureInfo.InvariantCulture));
			AppendProjectSignatureFailureSummary(builder, projectSnapshot, report);
			builder.AppendLine();
			builder.AppendLine(T("Comparison result", "비교 결과"));
			builder.AppendLine("- " + T("Loadable latest: ", "로더블 기준 일치: ") + summary.LoadableLatestCount.ToString(CultureInfo.InvariantCulture));
			builder.AppendLine("- " + T("Loadable action needed: ", "로더블 조치 필요: ") + loadableActionCount.ToString(CultureInfo.InvariantCulture));
			builder.AppendLine("- " + T("Loadable project-only: ", "로더블 프로젝트 전용: ") + summary.LoadableProjectOnlyCount.ToString(CultureInfo.InvariantCulture));
			builder.AppendLine("- " + T("System latest: ", "시스템 기준 일치: ") + summary.SystemLatestCount.ToString(CultureInfo.InvariantCulture));
			builder.AppendLine("- " + T("System action needed: ", "시스템 조치 필요: ") + systemActionCount.ToString(CultureInfo.InvariantCulture));
			builder.AppendLine("- " + T("System project-only: ", "시스템 프로젝트 전용: ") + summary.SystemProjectOnlyCount.ToString(CultureInfo.InvariantCulture));
			if (!string.IsNullOrWhiteSpace(_lastComparisonPath))
			{
				builder.AppendLine();
				builder.AppendLine(T("Report saved: ", "리포트 저장: ") + _lastComparisonPath);
			}
			AppendAutoHandledDialogSummary(builder, autoDialogRecords);
			return builder.ToString().TrimEnd();
		}
	}

	private void AppendProjectSignatureFailureSummary(StringBuilder builder, ProjectContentSnapshot projectSnapshot, ProjectStandardComparisonReport report)
	{
		if (builder == null)
		{
			return;
		}
		List<ProjectLoadableSignatureFailureItem> failures = ResolveProjectSignatureFailures(projectSnapshot, report);
		if (failures.Count == 0)
		{
			return;
		}
		builder.AppendLine();
		builder.AppendLine(T("Fingerprint missing list", "Fingerprint 누락 목록"));
		builder.AppendLine("- " + failures.Count.ToString(CultureInfo.InvariantCulture) + T(" loadable families need diagnostics. The full list is saved in the project scan JSON and comparison report JSON.", "개 로더블 패밀리의 진단이 필요합니다. 전체 목록은 프로젝트 스캔 JSON과 비교 리포트 JSON에 저장됩니다."));
		foreach (ProjectLoadableSignatureFailureItem failure in failures.Take(12))
		{
			builder.AppendLine("  - " + FirstNonEmptyValue(failure.CategoryName ?? string.Empty, "-") + " / " + FirstNonEmptyValue(failure.FamilyName ?? string.Empty, "-") + " / " + T("reason: ", "사유: ") + FirstNonEmptyValue(failure.Reason ?? string.Empty, T("No recorded reason.", "기록된 사유 없음.")) + (string.IsNullOrWhiteSpace(failure.ContentSignatureDebugPath) ? string.Empty : (" / " + failure.ContentSignatureDebugPath)));
		}
		if (failures.Count > 12)
		{
			builder.AppendLine("  - " + T("Additional omitted rows: ", "추가 생략 항목: ") + checked(failures.Count - 12).ToString(CultureInfo.InvariantCulture));
		}
	}

	private static List<ProjectLoadableSignatureFailureItem> ResolveProjectSignatureFailures(ProjectContentSnapshot projectSnapshot, ProjectStandardComparisonReport report)
	{
		if (report != null && report.ProjectLoadableSignatureFailures != null && report.ProjectLoadableSignatureFailures.Count > 0)
		{
			return report.ProjectLoadableSignatureFailures.Where([SpecialName] (ProjectLoadableSignatureFailureItem x) => x != null).OrderBy([SpecialName] (ProjectLoadableSignatureFailureItem x) => x.CategoryName ?? string.Empty, StringComparer.OrdinalIgnoreCase).ThenBy([SpecialName] (ProjectLoadableSignatureFailureItem x) => x.FamilyName ?? string.Empty, StringComparer.OrdinalIgnoreCase)
				.ToList();
		}
		if (projectSnapshot != null && projectSnapshot.LoadableSignatureFailures != null && projectSnapshot.LoadableSignatureFailures.Count > 0)
		{
			return projectSnapshot.LoadableSignatureFailures.Where([SpecialName] (ProjectLoadableSignatureFailureItem x) => x != null).OrderBy([SpecialName] (ProjectLoadableSignatureFailureItem x) => x.CategoryName ?? string.Empty, StringComparer.OrdinalIgnoreCase).ThenBy([SpecialName] (ProjectLoadableSignatureFailureItem x) => x.FamilyName ?? string.Empty, StringComparer.OrdinalIgnoreCase)
				.ToList();
		}
		return new List<ProjectLoadableSignatureFailureItem>();
	}

