	private void ExportCurrentModelCheckReviewList(IWin32Window owner, ProjectStandardComparisonReport report, string disciplineLabel)
	{
		try
		{
			if (ProjectComparisonReviewExcelExportService.CountReviewRows(report) <= 0)
			{
				ShowDashboardMessage(owner, T("There are no review-needed or different-from-standard items to export.", "내보낼 검토 필요 또는 표준과 다른 항목이 없습니다."), T("Current Model Check", "현재 모델 검사"), MessageBoxButtons.OK, MessageBoxIcon.Asterisk);
				return;
			}
			string projectName = FirstNonEmptyValue(report?.Project?.DocumentTitle ?? string.Empty, "Project");
			string targetName = FirstNonEmptyValue(disciplineLabel, report?.Standard?.DisplayName ?? string.Empty, "Standard");
			string reportFolder = Environment.GetFolderPath(Environment.SpecialFolder.DesktopDirectory);
			if (FamilyBrowserStandardPolicyStore.IsManagedDataRootAvailable(_workspaceRoot))
			{
				reportFolder = FamilyBrowserStandardPolicyStore.GetDataFolder(_workspaceRoot, "Reports");
				try
				{
					Directory.CreateDirectory(reportFolder);
				}
				catch (Exception projectError)
				{
					ProjectData.SetProjectError(projectError);
					reportFolder = Environment.GetFolderPath(Environment.SpecialFolder.DesktopDirectory);
					ProjectData.ClearProjectError();
				}
			}
			using SaveFileDialog dialog = new SaveFileDialog();
			dialog.Title = T("Export current model review list", "현재 모델 검토 리스트 내보내기");
			dialog.Filter = "Excel Workbook (*.xlsx)|*.xlsx";
			dialog.DefaultExt = "xlsx";
			dialog.AddExtension = true;
			dialog.OverwritePrompt = true;
			dialog.CheckPathExists = true;
			dialog.RestoreDirectory = true;
			dialog.InitialDirectory = reportFolder;
			dialog.FileName = SafeFileName("KKY_CurrentModelReview_" + projectName + "_" + targetName + "_" + DateTime.Now.ToString("yyyyMMdd-HHmm", CultureInfo.InvariantCulture)) + ".xlsx";
			ConfigureExplorerSaveDialog(dialog, reportFolder);
			if (dialog.ShowDialog(owner) == DialogResult.OK)
			{
				ProjectComparisonReviewExcelExportResult result = ProjectComparisonReviewExcelExportService.SaveReviewList(dialog.FileName, report, disciplineLabel, _lastComparisonPath, IsKorean());
				ShowSavedExcelMessageAndMaybeOpen(owner, T("Current Model Check", "현재 모델 검사"), T("Review Excel exported.", "검토 Excel을 추출했습니다.") + Environment.NewLine + T("Rows: ", "행: ") + result.RowCount.ToString(CultureInfo.InvariantCulture) + Environment.NewLine + result.OutputPath, result.OutputPath);
			}
		}
		catch (Exception ex)
		{
			ProjectData.SetProjectError(ex);
			Exception ex2 = ex;
			ShowLoggedError(T("Current Model Check Export", "현재 모델 검사 내보내기"), ex2);
			ProjectData.ClearProjectError();
		}
	}

	private string BuildSystemPreflightResultMessage(SystemTypePreflightReport report, string disciplineLabel, IEnumerable<FamilyThumbnailAutoConfirmedDialogRecord> autoDialogRecords = null)
	{
		SystemTypePreflightSummary summary = report?.Summary ?? new SystemTypePreflightSummary();
		checked
		{
			int reviewCount = summary.ApprovalRequiredCount + summary.DependencyManualReviewCount;
			string targetText = FirstNonEmptyValue(disciplineLabel, report?.StandardDisplayName ?? string.Empty, "-");
			string projectText = FirstNonEmptyValue(report?.ProjectDocumentTitle ?? string.Empty, "-");
			int dependencyActionCount = summary.MissingDependencyFamilyCount + summary.DependencyReloadCount;
			int executableCount = CountSystemActions(report, "createmissingtype") + CountSystemActions(report, "overwritedestination") + CountSystemActions(report, "consolidateduplicatesuffixtypes") + CountKeepWithDuplicateCleanup(report);
			int duplicateRiskCount = CountDuplicateRiskItems(report);
			StringBuilder builder = new StringBuilder();
			builder.AppendLine(T("System type diagnostics completed.", "시스템 타입 정밀 진단을 완료했습니다."));
			builder.AppendLine();
			builder.AppendLine(T("Review target: ", "검사 기준: ") + targetText);
			builder.AppendLine(T("Project: ", "프로젝트: ") + projectText);
			builder.AppendLine();
			builder.AppendLine(T("Diagnostics summary", "진단 요약"));
			builder.AppendLine("- " + T("No change: ", "변경 없음: ") + summary.NoChangeCount.ToString(CultureInfo.InvariantCulture));
			builder.AppendLine("- " + T("Ready: ", "준비: ") + summary.ReadyCount.ToString(CultureInfo.InvariantCulture));
			builder.AppendLine("- " + T("Review: ", "검토: ") + reviewCount.ToString(CultureInfo.InvariantCulture));
			builder.AppendLine("- " + T("Blocked: ", "차단: ") + summary.BlockedCount.ToString(CultureInfo.InvariantCulture));
			builder.AppendLine("- " + T("Loadable foundation blocked: ", "로더블 기반 차단: ") + summary.LoadableFoundationBlockedCount.ToString(CultureInfo.InvariantCulture));
			builder.AppendLine("- " + T("Dependency actions: ", "의존성 조치: ") + dependencyActionCount.ToString(CultureInfo.InvariantCulture));
			builder.AppendLine("- " + T("Executable system type actions: ", "실행 가능한 시스템 타입 작업: ") + executableCount.ToString(CultureInfo.InvariantCulture));
			if (duplicateRiskCount > 0)
			{
				builder.AppendLine("- " + T("Duplicate risk: ", "중복 위험: ") + duplicateRiskCount.ToString(CultureInfo.InvariantCulture));
			}
			if (!string.IsNullOrWhiteSpace(_lastPreflightPath))
			{
				builder.AppendLine();
				builder.AppendLine(T("Report saved: ", "리포트 저장: ") + _lastPreflightPath);
			}
			AppendAutoHandledDialogSummary(builder, autoDialogRecords);
			return builder.ToString().TrimEnd();
		}
	}

	private void AppendAutoHandledDialogSummary(StringBuilder builder, IEnumerable<FamilyThumbnailAutoConfirmedDialogRecord> records)
	{
		if (builder == null || records == null)
		{
			return;
		}
		List<FamilyThumbnailAutoConfirmedDialogRecord> list = records.Where([SpecialName] (FamilyThumbnailAutoConfirmedDialogRecord x) => x != null).ToList();
		if (list.Count == 0)
		{
			return;
		}
		builder.AppendLine();
		builder.AppendLine(T("Auto-handled Revit warnings: ", "자동 처리한 Revit 경고: ") + list.Count.ToString(CultureInfo.InvariantCulture));
		foreach (FamilyThumbnailAutoConfirmedDialogRecord record in list.Take(5))
		{
			string target = FirstNonEmptyValue(record.FamilyName, record.CategoryName, "-");
			string reason = FirstNonEmptyValue(record.Reason, "-");
			string result = FirstNonEmptyValue(record.OverrideResult, "-");
			builder.AppendLine("- " + target + " / " + reason + " / " + result);
		}
		if (list.Count > 5)
		{
			builder.AppendLine(T("...and more warnings were auto-handled.", "...추가 경고도 자동 처리되었습니다."));
		}
	}

	private void ApplySelectedStandardSystemTypeFromAction(string encodedToken)
	{
		try
		{
			string[] parts = Uri.UnescapeDataString(encodedToken ?? string.Empty).Split(new string[1] { "||" }, StringSplitOptions.None);
			string selectedDiscipline = string.Empty;
			string selectedCategory = string.Empty;
			string selectedSystemType = string.Empty;
			string selectedKind = string.Empty;
			if (parts.Length >= 4)
			{
				selectedDiscipline = parts[0];
				selectedCategory = parts[1];
				selectedSystemType = parts[2];
				selectedKind = parts[3];
			}
			else if (parts.Length >= 3)
			{
				selectedCategory = parts[0];
				selectedSystemType = parts[1];
				selectedKind = parts[2];
			}
			if (string.IsNullOrWhiteSpace(selectedSystemType) || string.IsNullOrWhiteSpace(selectedKind))
			{
				ShowDashboardMessage(this, T("Select a system type row before applying.", "적용할 시스템 타입 행을 먼저 선택하세요."), T("Apply Selected System Type", "선택 시스템 타입 적용"), MessageBoxButtons.OK, MessageBoxIcon.Asterisk);
				return;
			}
			SystemRow selectedRow = FindSystemRowForSelection(selectedDiscipline, selectedCategory, selectedSystemType, selectedKind);
			if (selectedRow != null && IsCategoryMismatchSystemRow(selectedRow))
			{
				ShowDashboardMessage(this, T("This system type has a category mismatch. Review the category before applying the registered standard type.", "이 시스템 타입은 카테고리 불일치 항목입니다. 등록된 표준 타입을 적용하기 전에 카테고리를 먼저 검토하세요."), T("Category Review", "카테고리 검토"), MessageBoxButtons.OK, MessageBoxIcon.Exclamation);
			}
			else if (selectedRow != null && IsDuplicateRiskSystemRow(selectedRow))
			{
				ShowDashboardMessage(this, T("This system type has duplicate type risk. Review or clean duplicate system types before applying.", "이 시스템 타입은 중복 타입 위험이 있습니다. 적용 전에 중복 시스템 타입을 먼저 확인하거나 정리하세요."), T("Review Duplicate Types", "중복 타입 검토"), MessageBoxButtons.OK, MessageBoxIcon.Exclamation);
			}
			else
			{
				ApplyStandardSystemTypes(selectedCategory, selectedSystemType, selectedKind, selectedDiscipline);
			}
		}
		catch (Exception ex)
		{
			ProjectData.SetProjectError(ex);
			Exception ex2 = ex;
			ShowLoggedError("Apply Selected System Type", ex2);
			ProjectData.ClearProjectError();
		}
	}

	private void ApplySelectedStandardSystemTypesFromAction(string encodedToken)
	{
		try
		{
			List<SystemTypeSelection> selections = ParseSystemTypeSelections(encodedToken);
			if (selections.Count == 0)
			{
				ShowDashboardMessage(this, T("Check one or more system type rows before applying.", "적용할 시스템 타입 행을 하나 이상 체크하세요."), T("Apply Selected System Types", "선택 시스템 타입 적용"), MessageBoxButtons.OK, MessageBoxIcon.Asterisk);
				return;
			}
			List<string> distinctDisciplines = (from x in selections
				select Normalize(x.DisciplineKey) into x
				where x.Length > 0
				select x).Distinct(StringComparer.Ordinal).ToList();
			if (distinctDisciplines.Count > 1)
			{
				ShowDashboardMessage(this, T("Apply checked system types one standard target at a time. The current selection contains multiple trades or standard RVT targets.", "체크 시스템 타입은 한 번에 하나의 공종/표준 RVT 기준으로만 적용할 수 있습니다. 현재 선택에 여러 공종 또는 표준 대상이 섞여 있습니다."), T("Apply Selected System Types", "선택 시스템 타입 적용"), MessageBoxButtons.OK, MessageBoxIcon.Asterisk);
				return;
			}
			foreach (SystemTypeSelection systemSelection in selections)
			{
				SystemRow selectedRow = FindSystemRowForSelection(systemSelection.DisciplineKey, systemSelection.CategoryName, systemSelection.SystemTypeName, systemSelection.SystemFamilyKind);
				if (selectedRow != null && IsCategoryMismatchSystemRow(selectedRow))
				{
					ShowDashboardMessage(this, T("One or more checked system types have category mismatches. Clear those rows or review the category before applying.", "체크된 시스템 타입 중 카테고리 불일치 항목이 있습니다. 해당 행을 선택 해제하거나 카테고리 검토 후 적용하세요."), T("Category Review", "카테고리 검토"), MessageBoxButtons.OK, MessageBoxIcon.Exclamation);
					return;
				}
				if (selectedRow != null && IsDuplicateRiskSystemRow(selectedRow))
				{
					ShowDashboardMessage(this, T("One or more checked system types have duplicate risk. Clear those rows or resolve duplicate types first.", "체크된 시스템 타입 중 중복 위험 항목이 있습니다. 해당 행을 선택 해제하거나 중복 타입을 먼저 정리하세요."), T("Duplicate Risk", "중복 위험"), MessageBoxButtons.OK, MessageBoxIcon.Exclamation);
					return;
				}
			}
			string selectedDiscipline = ((distinctDisciplines.Count == 1) ? distinctDisciplines[0] : _browseDisciplineKey);
			ApplyStandardSystemTypes(null, null, null, selectedDiscipline, selections);
		}
		catch (Exception ex)
		{
			ProjectData.SetProjectError(ex);
			Exception ex2 = ex;
			ShowLoggedError("Apply Selected System Types", ex2);
			ProjectData.ClearProjectError();
		}
	}

	private static List<SystemTypeSelection> ParseSystemTypeSelections(string encodedToken)
	{
		List<SystemTypeSelection> result = new List<SystemTypeSelection>();
		string obj = Uri.UnescapeDataString(encodedToken ?? string.Empty).Replace("\r\n", "\n").Replace("\r", "\n");
		HashSet<string> seen = new HashSet<string>(StringComparer.Ordinal);
		string[] array = obj.Split(new string[1] { "\n" }, StringSplitOptions.RemoveEmptyEntries);
		for (int i = 0; i < array.Length; i = checked(i + 1))
		{
			string[] parts = array[i].Split(new string[1] { "||" }, StringSplitOptions.None);
			if (parts.Length < 4)
			{
				continue;
			}
			SystemTypeSelection systemSelection = new SystemTypeSelection
			{
				DisciplineKey = (parts[0] ?? string.Empty).Trim(),
				CategoryName = (parts[1] ?? string.Empty).Trim(),
				SystemTypeName = (parts[2] ?? string.Empty).Trim(),
				SystemFamilyKind = (parts[3] ?? string.Empty).Trim()
			};
			if (!string.IsNullOrWhiteSpace(systemSelection.SystemTypeName))
			{
				string key = BuildSystemSelectionKey(systemSelection.SystemFamilyKind, systemSelection.CategoryName, systemSelection.SystemTypeName);
				if (seen.Add(key))
				{
					result.Add(systemSelection);
				}
			}
		}
		return result;
	}

