	private void WriteSystemTypePreflightNormalizationDiagnostics(SystemTypePreflightReport report)
	{
		if (report == null || report.Diagnostics == null)
		{
			return;
		}
		foreach (SystemTypePreflightDiagnostic diagnostic in report.Diagnostics.Where([SpecialName] (SystemTypePreflightDiagnostic x) => x != null && (string.Equals(x.Stage, "NormalizeSameNameRoutingActions", StringComparison.Ordinal) || string.Equals(x.Stage, "PromoteSelectedMissingSystemType", StringComparison.Ordinal) || string.Equals(x.Stage, "EnsureRoutingFamilyDependencyItems", StringComparison.Ordinal))).Take(24))
		{
			WriteDashboardRuntimeDiagnostic("Preflight." + (diagnostic.Stage ?? "-") + " planned=" + (diagnostic.PlannedAction ?? "-") + " normalized=" + (diagnostic.NormalizedAction ?? "-") + " kind=" + (diagnostic.SystemFamilyKind ?? "-") + " type=" + (diagnostic.SystemTypeName ?? "-") + " reason=" + (diagnostic.Reason ?? "-") + " details=" + (diagnostic.Details ?? "-"), -1, -1L);
		}
	}

	private static ProjectContentSnapshot BuildSelectedSystemApplyPostSnapshot(Document doc, SystemTypePreflightReport postPreflight)
	{
		List<string> dependencyFamilyNames = ExtractSystemDependencyFamilyNames(postPreflight);
		ProjectContentSnapshot snapshot = ProjectSnapshotCaptureService.CaptureLoadableFamiliesByNames(doc, dependencyFamilyNames, null, includeDeepLoadableContent: false, includeInstanceCounts: false);
		HashSet<string> seen = new HashSet<string>(StringComparer.Ordinal);
		List<SystemSyncExecutionItem> executionItems = postPreflight?.ExecutionPlan?.Items ?? new List<SystemSyncExecutionItem>();
		foreach (SystemSyncExecutionItem item in executionItems)
		{
			if (item != null && !string.IsNullOrWhiteSpace(item.SystemTypeName))
			{
				string key = BuildSystemSelectionKey(item.SystemFamilyKind, item.CategoryName, item.SystemTypeName);
				if (seen.Add(key))
				{
					ProjectContentSnapshot selectedSystemSnapshot = ProjectSnapshotCaptureService.CaptureSystemTypesByKey(doc, item.SystemFamilyKind, item.CategoryName, item.SystemTypeName);
					MergeSystemTypesIntoSnapshot(snapshot, selectedSystemSnapshot);
				}
			}
		}
		return snapshot;
	}

	private static List<string> ExtractSystemDependencyFamilyNames(SystemTypePreflightReport report)
	{
		if (report == null || report.StandardCatalog == null || report.StandardCatalog.Types == null)
		{
			return new List<string>();
		}
		return (from x in report.StandardCatalog.Types.Where([SpecialName] (SystemTypeSemanticSnapshot x) => x != null && x.RoutingDependencies != null).SelectMany([SpecialName] (SystemTypeSemanticSnapshot x) => x.RoutingDependencies)
			where x != null && !string.IsNullOrWhiteSpace(x.FamilyName)
			select x.FamilyName).Distinct(StringComparer.OrdinalIgnoreCase).ToList();
	}

	private static bool ShouldStampSystemApplyTracking(SystemTypeApplyExecutionReport execution)
	{
		if (execution == null || execution.Summary == null)
		{
			return false;
		}
		if (execution.Summary.FailedCount > 0 || execution.Summary.BlockedCount > 0)
		{
			return false;
		}
		return CountSystemApplyMutations(execution) > 0;
	}

	private static int CountSystemApplyMutations(SystemTypeApplyExecutionReport execution)
	{
		if (execution == null || execution.Summary == null)
		{
			return 0;
		}
		return checked(execution.Summary.CreatedCount + execution.Summary.OverwrittenCount + execution.Summary.ConsolidatedCount);
	}

	private static void AddSystemApplyTrackingSkippedMessage(SystemTypeApplyExecutionReport execution)
	{
		if (execution == null || execution.Items == null)
		{
			return;
		}
		string reason = "SystemApply.StampTracking.Skipped - tracking was not stamped because the apply did not complete a clean create/overwrite/consolidate post-check.";
		foreach (SystemTypeApplyExecutionItem item in execution.Items)
		{
			if (item != null && item.Messages != null)
			{
				item.Messages.Add(reason);
			}
		}
	}

	private static string BuildSystemApplyResultDialogDetails(SystemTypeApplyExecutionReport execution, int maxItems)
	{
		if (execution == null || execution.Items == null)
		{
			return string.Empty;
		}
		List<string> lines = (from x in execution.Items
			where x != null
			where !string.Equals(Normalize(x.Outcome), "created", StringComparison.Ordinal) || !string.IsNullOrWhiteSpace(x.Details) || (x.Messages != null && x.Messages.Count > 0)
			select x).Take(Math.Max(1, maxItems)).Select([SpecialName] (SystemTypeApplyExecutionItem x) =>
		{
			string text = x.Details ?? string.Empty;
			if (string.IsNullOrWhiteSpace(text) && x.Messages != null && x.Messages.Count > 0)
			{
				text = x.Messages[checked(x.Messages.Count - 1)];
			}
			return "- " + (x.SystemTypeName ?? string.Empty) + " [" + (x.SyncAction ?? string.Empty) + " -> " + (x.Outcome ?? string.Empty) + "]" + (string.IsNullOrWhiteSpace(text) ? string.Empty : (" " + text));
		}).ToList();
		if (lines.Count == 0)
		{
			return string.Empty;
		}
		return Environment.NewLine + Environment.NewLine + string.Join(Environment.NewLine, lines);
	}

