	private static List<LoadableFamilySelection> BuildEffectiveLoadableFamilySelections(string selectedCategoryName, string selectedFamilyName, IList<LoadableFamilySelection> selectedFamilies)
	{
		List<LoadableFamilySelection> result = new List<LoadableFamilySelection>();
		HashSet<string> seen = new HashSet<string>(StringComparer.Ordinal);
		if (selectedFamilies != null)
		{
			foreach (LoadableFamilySelection familySelection in selectedFamilies)
			{
				if (familySelection != null)
				{
					AddEffectiveLoadableFamilySelection(result, seen, familySelection.CategoryName, familySelection.FamilyName);
				}
			}
		}
		else
		{
			AddEffectiveLoadableFamilySelection(result, seen, selectedCategoryName, selectedFamilyName);
		}
		return result;
	}

	private static void AddEffectiveLoadableFamilySelection(ICollection<LoadableFamilySelection> result, ISet<string> seen, string categoryName, string familyName)
	{
		if (result != null && seen != null && !string.IsNullOrWhiteSpace(familyName))
		{
			string key = BuildFamilySelectionKey(categoryName, familyName);
			if (seen.Add(key))
			{
				result.Add(new LoadableFamilySelection
				{
					CategoryName = (categoryName ?? string.Empty).Trim(),
					FamilyName = (familyName ?? string.Empty).Trim()
				});
			}
