		{
			return string.Equals(Normalize(projectFamily.CategoryId), Normalize(standardFamily.CategoryId), StringComparison.Ordinal);
		}
		return string.Equals(Normalize(projectFamily.CategoryName), Normalize(standardFamily.CategoryName), StringComparison.Ordinal);
	}

