	private void RefreshSelectedFamilyTrackingAfterLoad(Document doc, StandardLibraryRegistrationRecord registration, StandardLibrarySnapshot standardSnapshot, LoadableFamilySyncPlan plan, LoadableFamilySyncExecutionReport execution)
	{
		//IL_0060: Unknown result type (might be due to invalid IL or missing references)
		//IL_0067: Expected O, but got Unknown
		//IL_0069: Unknown result type (might be due to invalid IL or missing references)
		//IL_0079: Unknown result type (might be due to invalid IL or missing references)
		if (doc == null || registration == null || standardSnapshot == null || plan == null || execution == null)
		{
			return;
		}
		Stopwatch trackingSw = Stopwatch.StartNew();
		HashSet<string> selectedKeys = BuildSuccessfulLoadableExecutionKeys(execution);
		if (selectedKeys.Count != 0)
		{
			ProjectContentSnapshot postSnapshot = BuildSelectedLoadableSnapshotFromStandard(doc, standardSnapshot, selectedKeys);
			ProjectTrackingCatalog selectedCatalog = ProjectTrackingStampService.BuildCatalog(registration, standardSnapshot, postSnapshot);
			ProjectTrackingCatalog mergedCatalog = MergeSelectedLoadableTrackingCatalog(ProjectTrackingStoreService.Load(doc), selectedCatalog, selectedKeys);
			Transaction tx = new Transaction(doc, "KKY Family Browser Stamp Tracking After Selected Family Load");
			try
			{
				tx.Start();
				ProjectTrackingStoreService.Save(doc, mergedCatalog);
				tx.Commit();
			}
			finally
			{
				((IDisposable)tx)?.Dispose();
			}
			execution.TrackingPath = ProjectTrackingOutputStore.Save(_workspaceRoot, mergedCatalog);
			execution.Summary.TrackingRefreshedCount = ((selectedCatalog.LoadableFamilies != null) ? selectedCatalog.LoadableFamilies.Count : 0);
			WriteDashboardRuntimeDiagnostic("FamilyLoad.SelectedTracking.Fast", execution.Summary.TrackingRefreshedCount, trackingSw.ElapsedMilliseconds);
		}
	}

	private static HashSet<string> BuildLoadablePlanSelectionKeys(LoadableFamilySyncPlan plan)
	{
		HashSet<string> result = new HashSet<string>(StringComparer.Ordinal);
		if (plan == null || plan.Items == null)
		{
			return result;
		}
		foreach (LoadableFamilySyncPlanItem item in plan.Items)
		{
			if (item != null)
			{
				string key = BuildFamilySelectionKey(item.CategoryName, item.FamilyName);
				if (!string.IsNullOrWhiteSpace(key) && key.Length > 1)
				{
					result.Add(key);
				}
			}
		}
		return result;
	}

	private static HashSet<string> BuildSuccessfulLoadableExecutionKeys(LoadableFamilySyncExecutionReport execution)
	{
		HashSet<string> result = new HashSet<string>(StringComparer.Ordinal);
		if (execution == null || execution.Items == null)
		{
			return result;
		}
		foreach (LoadableFamilySyncExecutionItem item in execution.Items)
		{
			if (item == null)
			{
				continue;
			}
			string outcome = Normalize(item.Outcome);
			if (string.Equals(outcome, "loaded", StringComparison.Ordinal) || string.Equals(outcome, "reloaded", StringComparison.Ordinal) || string.Equals(outcome, "stamprefreshpending", StringComparison.Ordinal))
			{
				string key = BuildFamilySelectionKey(item.CategoryName, item.FamilyName);
				if (!string.IsNullOrWhiteSpace(key) && key.Length > 1)
				{
					result.Add(key);
				}
			}
		}
		return result;
	}

	private static ProjectContentSnapshot BuildSelectedLoadableSnapshotFromStandard(Document doc, StandardLibrarySnapshot standardSnapshot, ISet<string> selectedKeys)
	{
		ProjectContentSnapshot snapshot = new ProjectContentSnapshot
		{
			CapturedAtUtc = DateTime.UtcNow.ToString("O", CultureInfo.InvariantCulture)
		};
		if (doc != null)
		{
			try
			{
				snapshot.DocumentTitle = doc.Title;
			}
			catch (Exception projectError)
			{
				ProjectData.SetProjectError(projectError);
				ProjectData.ClearProjectError();
			}
			try
			{
				snapshot.DocumentPath = doc.PathName;
			}
			catch (Exception projectError2)
			{
				ProjectData.SetProjectError(projectError2);
				ProjectData.ClearProjectError();
			}
			try
			{
				if (doc.Application != null)
				{
					snapshot.RevitVersion = doc.Application.VersionNumber;
				}
			}
			catch (Exception projectError3)
			{
				ProjectData.SetProjectError(projectError3);
				ProjectData.ClearProjectError();
			}
		}
		if (standardSnapshot == null || selectedKeys == null || selectedKeys.Count == 0)
		{
			return snapshot;
		}
		foreach (StandardLoadableFamilySnapshotItem item in standardSnapshot.LoadableFamilies ?? new List<StandardLoadableFamilySnapshotItem>())
		{
			if (item != null && selectedKeys.Contains(BuildFamilySelectionKey(item.CategoryName, item.FamilyName)))
			{
				snapshot.LoadableFamilies.Add(new ProjectLoadableFamilySnapshotItem
				{
					FamilyName = item.FamilyName,
					CategoryName = item.CategoryName,
					CategoryId = item.CategoryId,
					CategoryGroup = item.CategoryGroup,
					TypeCount = item.TypeCount,
					InstanceCount = 0,
					TypeNames = new List<string>(item.TypeNames ?? new List<string>()),
					Parameters = new List<StandardFamilyParameterSnapshotItem>(item.Parameters ?? new List<StandardFamilyParameterSnapshotItem>()),
					ContentFingerprint = item.ContentFingerprint,
					IsShared = item.IsShared
				});
			}
		}
		snapshot.Summary.LoadableFamilyCount = snapshot.LoadableFamilies.Count;
		snapshot.Summary.LoadableTypeCount = snapshot.LoadableFamilies.Sum([SpecialName] (ProjectLoadableFamilySnapshotItem x) => x.TypeCount);
		return snapshot;
	}

	private static ProjectTrackingCatalog MergeSelectedLoadableTrackingCatalog(ProjectTrackingCatalog existingCatalog, ProjectTrackingCatalog selectedCatalog, ISet<string> selectedKeys)
	{
		ProjectTrackingCatalog result = null;
		if (existingCatalog == null || selectedCatalog == null || !string.Equals(Normalize(existingCatalog.SourceId), Normalize(selectedCatalog.SourceId), StringComparison.Ordinal))
		{
			result = ((selectedCatalog == null) ? new ProjectTrackingCatalog() : selectedCatalog);
		}
		else
		{
			result = existingCatalog;
			result.GeneratedAtUtc = selectedCatalog.GeneratedAtUtc;
			result.SourceDisplayName = selectedCatalog.SourceDisplayName;
			result.ApprovedStandardStamp = selectedCatalog.ApprovedStandardStamp;
			result.ProjectDocumentTitle = selectedCatalog.ProjectDocumentTitle;
			result.ProjectDocumentPath = selectedCatalog.ProjectDocumentPath;
		}
		if (result.LoadableFamilies == null)
		{
			result.LoadableFamilies = new List<TrackedLoadableFamilyState>();
		}
		if (result.SystemTypes == null)
		{
			result.SystemTypes = new List<TrackedSystemTypeState>();
		}
		ISet<string> set = selectedKeys ?? new HashSet<string>(StringComparer.Ordinal);
		if (set.Count > 0)
		{
			result.LoadableFamilies.RemoveAll([SpecialName] (TrackedLoadableFamilyState x) => x != null && set.Contains(Normalize(x.IdentityKey)));
		}
		if (selectedCatalog != null && selectedCatalog.LoadableFamilies != null)
		{
			result.LoadableFamilies.AddRange(selectedCatalog.LoadableFamilies);
		}
		return result;
	}

