	private string BuildSelectedFamilyScopeText(string selectedCategoryName, string selectedFamilyName, string selectedDisciplineKey, IList<LoadableFamilySelection> selectedFamilies)
	{
		if (selectedFamilies != null && selectedFamilies.Count > 0)
		{
			List<string> lines = new List<string> { T("Scope: checked families - ", "범위: 체크 패밀리 - ") + selectedFamilies.Count.ToString(CultureInfo.InvariantCulture) };
			foreach (LoadableFamilySelection familySelection in selectedFamilies.Take(8))
			{
				string label = (string.IsNullOrWhiteSpace(familySelection.CategoryName) ? "-" : familySelection.CategoryName) + " / " + (string.IsNullOrWhiteSpace(familySelection.FamilyName) ? "-" : familySelection.FamilyName);
				lines.Add("- " + label);
			}
			if (selectedFamilies.Count > 8)
			{
				lines.Add(T("...and more checked families.", "...추가 체크 패밀리 포함."));
			}
			return string.Join(Environment.NewLine, lines) + Environment.NewLine + Environment.NewLine;
		}
		if (string.IsNullOrWhiteSpace(selectedFamilyName))
		{
			return string.Empty;
		}
		return T("Scope: selected family - ", "범위: 선택 패밀리 - ") + (string.IsNullOrWhiteSpace(selectedDisciplineKey) ? string.Empty : (ResolveDisciplineDisplayName(_standardPolicy, selectedDisciplineKey) + " / ")) + (string.IsNullOrWhiteSpace(selectedCategoryName) ? "-" : selectedCategoryName) + " / " + (string.IsNullOrWhiteSpace(selectedFamilyName) ? "-" : selectedFamilyName) + Environment.NewLine + Environment.NewLine;
	}

	private static void RebuildLoadableFamilyPlanSummary(LoadableFamilySyncPlan plan)
	{
		if (plan == null)
		{
			return;
		}
		plan.Summary = new LoadableFamilySyncPlanSummary();
		if (plan.Items == null)
		{
			return;
		}
		checked
		{
			foreach (LoadableFamilySyncPlanItem item in plan.Items)
			{
				switch (Normalize(item.ExecutionMode))
				{
				case "load":
					plan.Summary.LoadCount++;
					break;
				case "reload":
					plan.Summary.ReloadCount++;
					break;
				case "stamponly":
					plan.Summary.StampOnlyCount++;
					break;
				case "blocked":
					plan.Summary.BlockedCount++;
					break;
				default:
					plan.Summary.SkipCount++;
					break;
				}
			}
		}
	}

