		}
		string b = Normalize(plannedAction);
		return plan.Items.Where([SpecialName] (LoadableFamilySyncPlanItem x) => x != null && string.Equals(Normalize(x.PlannedAction), b, StringComparison.Ordinal)).Count();
	}

	private string BuildCategoryMismatchBlockerSummary(LoadableFamilySyncPlan plan, int maxItems)
	{
		if (plan == null || plan.Items == null)
		{
			return string.Empty;
		}
		List<LoadableFamilySyncPlanItem> blockers = plan.Items.Where([SpecialName] (LoadableFamilySyncPlanItem x) => x != null && string.Equals(Normalize(x.PlannedAction), "blockedcategorymismatch", StringComparison.Ordinal)).OrderBy([SpecialName] (LoadableFamilySyncPlanItem x) => Normalize(x.CategoryName) + "|" + Normalize(x.FamilyName), StringComparer.Ordinal).ToList();
		if (blockers.Count == 0)
		{
			return string.Empty;
		}
		List<string> lines = new List<string> { T("Category review blocked: ", "카테고리 검토 차단: ") + blockers.Count.ToString(CultureInfo.InvariantCulture) };
		foreach (LoadableFamilySyncPlanItem item in blockers.Take(Math.Max(0, maxItems)))
		{
			string label = (string.IsNullOrWhiteSpace(item.CategoryName) ? (string.IsNullOrWhiteSpace(item.FamilyName) ? "-" : item.FamilyName) : (item.CategoryName + " / " + (string.IsNullOrWhiteSpace(item.FamilyName) ? "-" : item.FamilyName)));
			lines.Add("- " + label);
		}
		if (blockers.Count > maxItems)
		{
			lines.Add(T("...and more items require category review.", "...추가 항목도 카테고리 검토가 필요합니다."));
