	private static HashSet<string> BuildNestedLoadableNameSet(IEnumerable<LoadableFamilyComparisonItem> items)
	{
		HashSet<string> result = new HashSet<string>(StringComparer.Ordinal);
		if (items == null)
		{
			return result;
		}
		foreach (LoadableFamilyComparisonItem parentItem in items)
		{
			if (parentItem == null || parentItem.NestedLoadableFamilies == null)
			{
				continue;
			}
			foreach (StandardNestedLoadableFamilySnapshotItem child in parentItem.NestedLoadableFamilies)
			{
				if (child != null && child.IsShared && IsModelNestedLoadableChild(child))
				{
					string familyName = Normalize((child == null) ? string.Empty : child.FamilyName);
					if (!string.IsNullOrWhiteSpace(familyName))
					{
						result.Add(familyName);
					}
				}
			}
		}
		return result;
	}

	private static ProjectStandardComparisonSummary BuildComparisonSummary(ProjectStandardComparisonReport report)
	{
		ProjectStandardComparisonSummary summary = new ProjectStandardComparisonSummary();
		if (report == null)
		{
			return summary;
		}
		checked
		{
			foreach (LoadableFamilyComparisonItem item in report.LoadableFamilies ?? new List<LoadableFamilyComparisonItem>())
			{
				switch (item.Status)
				{
				case "LoadedLatest":
					summary.LoadableLatestCount++;
					break;
				case "LoadAvailable":
					summary.LoadableLoadAvailableCount++;
					break;
				case "DifferentFromStandard":
				case "LoadedWithoutVersionStamp":
				case "StampNormalizationNeeded":
				case "UpdateAvailable":
				case "LocallyModified":
				case "VersionConflict":
				case "CategoryMismatch":
				case "ManualReview":
					summary.LoadableDifferentCount++;
					break;
				case "ProjectOnly":
					summary.LoadableProjectOnlyCount++;
					break;
				}
			}
			foreach (SystemTypeComparisonItem item2 in report.SystemTypes ?? new List<SystemTypeComparisonItem>())
			{
				switch (item2.Status)
				{
				case "LoadedLatest":
					summary.SystemLatestCount++;
					break;
				case "LoadAvailable":
					summary.SystemLoadAvailableCount++;
					break;
				case "DifferentFromStandard":
				case "LoadedWithoutVersionStamp":
				case "StampNormalizationNeeded":
				case "UpdateAvailable":
				case "LocallyModified":
				case "VersionConflict":
				case "CategoryMismatch":
				case "ManualReview":
					summary.SystemDifferentCount++;
					break;
				case "ProjectOnly":
					summary.SystemProjectOnlyCount++;
					break;
				}
			}
			return summary;
		}
	}

