	private static bool MatchesSelectedSystemSelections(SystemTypeSyncPlanItem item, ISet<string> selectedKeys)
	{
		if (item == null || selectedKeys == null || selectedKeys.Count == 0)
		{
			return false;
		}
		foreach (string selectedKey in selectedKeys)
		{
			string[] parts = selectedKey.Split('|');
			if (parts.Length >= 3)
			{
				string selectedKind = parts[0];
				string selectedCategory = parts[1];
				string selectedType = parts[2];
				if (string.Equals(Normalize(item.SystemFamilyKind), selectedKind, StringComparison.Ordinal) && string.Equals(Normalize(item.CategoryName), selectedCategory, StringComparison.Ordinal) && (string.Equals(Normalize(item.SourceTypeName), selectedType, StringComparison.Ordinal) || string.Equals(Normalize(item.DestinationTypeName), selectedType, StringComparison.Ordinal)))
				{
					return true;
				}
			}
		}
		return false;
	}

