		filtered.StandardCatalog = report.StandardCatalog ?? new SystemTypeCatalogSnapshot();
		filtered.ProjectCatalog = report.ProjectCatalog ?? new SystemTypeCatalogSnapshot();
		filtered.ProjectRoutingFamilies = report.ProjectRoutingFamilies ?? new RoutingFamilyCatalogSnapshot();
		filtered.Diagnostics = (report.Diagnostics ?? new List<SystemTypePreflightDiagnostic>()).Where([SpecialName] (SystemTypePreflightDiagnostic x) => MatchesSelectedSystemPreflightDiagnostic(x, selectedSystemTypeName, selectedSystemFamilyKind)).ToList();
		filtered.SyncPlan = new SystemTypeSyncPlan();
		if (report.SyncPlan != null)
		{
			filtered.SyncPlan.GeneratedAtUtc = report.SyncPlan.GeneratedAtUtc;
			filtered.SyncPlan.Items = (report.SyncPlan.Items ?? new List<SystemTypeSyncPlanItem>()).Where([SpecialName] (SystemTypeSyncPlanItem x) => MatchesSelectedSystemSyncItem(x, selectedCategoryName, selectedSystemTypeName, selectedSystemFamilyKind)).ToList();
		}
		filtered.DependencyPlan = new RoutingDependencyPreflightPlan();
		if (report.DependencyPlan != null)
		{
			filtered.DependencyPlan.GeneratedAtUtc = report.DependencyPlan.GeneratedAtUtc;
			filtered.DependencyPlan.Items = (report.DependencyPlan.Items ?? new List<RoutingDependencyPreflightItem>()).Where([SpecialName] (RoutingDependencyPreflightItem x) => MatchesSelectedSystemDependencyItem(x, selectedSystemTypeName, selectedSystemFamilyKind)).ToList();
		}
		filtered.ExecutionPlan = new SystemSyncExecutionPlan();
		if (report.ExecutionPlan != null)
		{
			filtered.ExecutionPlan.GeneratedAtUtc = report.ExecutionPlan.GeneratedAtUtc;
			filtered.ExecutionPlan.Items = (report.ExecutionPlan.Items ?? new List<SystemSyncExecutionItem>()).Where([SpecialName] (SystemSyncExecutionItem x) => MatchesSelectedSystemType(x.SystemFamilyKind, x.CategoryName, x.SystemTypeName, selectedCategoryName, selectedSystemTypeName, selectedSystemFamilyKind)).ToList();
		}
		filtered.Summary = SystemTypePreflightBuilderService.BuildSummary(filtered.ExecutionPlan, filtered.DependencyPlan);
		return filtered;
