	private static bool MatchesSelectedSystemPreflightDiagnostic(SystemTypePreflightDiagnostic diagnostic, string selectedSystemTypeName, string selectedSystemFamilyKind)
	{
		if (diagnostic == null)
		{
			return false;
		}
		return string.Equals(Normalize(diagnostic.SystemTypeName), Normalize(selectedSystemTypeName), StringComparison.Ordinal) && string.Equals(Normalize(diagnostic.SystemFamilyKind), Normalize(selectedSystemFamilyKind), StringComparison.Ordinal);
	}

	private static bool MatchesSelectedSystemSyncItem(SystemTypeSyncPlanItem item, string selectedCategoryName, string selectedSystemTypeName, string selectedSystemFamilyKind)
	{
		if (item == null)
		{
			return false;
		}
		string selectedType = Normalize(selectedSystemTypeName);
		if (selectedType.Length == 0)
		{
			return false;
		}
		bool num = string.Equals(Normalize(item.SourceTypeName), selectedType, StringComparison.Ordinal);
		bool destinationMatches = string.Equals(Normalize(item.DestinationTypeName), selectedType, StringComparison.Ordinal);
		if (!num && !destinationMatches)
		{
			return false;
		}
		return MatchesSelectedSystemIdentity(item.SystemFamilyKind, item.CategoryName, selectedCategoryName, selectedSystemFamilyKind);
	}

	private static bool MatchesSelectedSystemDependencyItem(RoutingDependencyPreflightItem item, string selectedSystemTypeName, string selectedSystemFamilyKind)
	{
		if (item == null)
		{
			return false;
		}
		if (!string.Equals(Normalize(item.SystemTypeName), Normalize(selectedSystemTypeName), StringComparison.Ordinal))
		{
			return false;
		}
		string selectedKind = Normalize(selectedSystemFamilyKind);
		if (selectedKind.Length == 0)
		{
			return true;
		}
		return string.Equals(Normalize(item.SystemFamilyKind), selectedKind, StringComparison.Ordinal);
	}

	private static bool MatchesSelectedSystemType(string systemFamilyKind, string categoryName, string typeName, string selectedCategoryName, string selectedSystemTypeName, string selectedSystemFamilyKind)
	{
		if (!string.Equals(Normalize(typeName), Normalize(selectedSystemTypeName), StringComparison.Ordinal))
		{
			return false;
		}
		return MatchesSelectedSystemIdentity(systemFamilyKind, categoryName, selectedCategoryName, selectedSystemFamilyKind);
	}

	private static bool MatchesSelectedSystemIdentity(string systemFamilyKind, string categoryName, string selectedCategoryName, string selectedSystemFamilyKind)
	{
		string kind = Normalize(systemFamilyKind);
		string selectedKind = Normalize(selectedSystemFamilyKind);
		if (selectedKind.Length > 0)
		{
			return string.Equals(kind, selectedKind, StringComparison.Ordinal);
		}
		string selectedCategory = Normalize(selectedCategoryName);
		if (selectedCategory.Length == 0)
		{
			return true;
		}
		string category = Normalize(categoryName);
		if (category.Length == 0)
		{
			return string.Equals(kind, selectedCategory, StringComparison.Ordinal);
		}
		return string.Equals(category, selectedCategory, StringComparison.Ordinal);
	}

	private static int PromoteSelectedMissingSupportedSystemTypes(SystemTypePreflightReport report)
	{
		if (report == null || report.SyncPlan == null || report.SyncPlan.Items == null)
		{
			return 0;
		}
		if (report.Diagnostics == null)
		{
			report.Diagnostics = new List<SystemTypePreflightDiagnostic>();
		}
		int promotedCount = 0;
		foreach (SystemTypeSyncPlanItem item in report.SyncPlan.Items)
		{
			if (item != null && IsSupportedSystemApplyKind(item.SystemFamilyKind) && string.Equals(Normalize(item.Action), "skipmissingtype", StringComparison.Ordinal))
			{
				string plannedAction = item.Action;
				item.Action = "CreateMissingType";
				item.Reason = FamilyBrowserLanguageService.Text("Selected missing supported system type will be created from the registered standard.", "선택한 누락 지원 시스템 타입을 등록된 표준에서 생성합니다.");
				promotedCount = checked(promotedCount + 1);
				report.Diagnostics.Add(new SystemTypePreflightDiagnostic
				{
					Stage = "PromoteSelectedMissingSystemType",
					PlannedAction = (plannedAction ?? string.Empty),
					NormalizedAction = item.Action,
					SystemTypeName = (item.SourceTypeName ?? string.Empty),
					SystemFamilyKind = (item.SystemFamilyKind ?? string.Empty),
					Reason = "ExplicitSelectedApply",
					Details = FamilyBrowserLanguageService.Text("Selected supported system type is missing from the current project, so it is planned as CreateMissingType instead of SkipMissingType.", "선택한 지원 시스템 타입이 현재 프로젝트에 없어서 SkipMissingType 대신 CreateMissingType으로 계획했습니다.")
				});
			}
		}
		return promotedCount;
	}

	private void OpenOutputFolder()
	{
		try
		{
			if (!FamilyBrowserStandardPolicyStore.IsManagedDataRootAvailable(_workspaceRoot))
			{
				ShowDashboardMessage(this, T("No managed shared folder is connected yet. Refresh the homepage path first.", "아직 공용 관리 폴더가 연결되지 않았습니다. 먼저 홈페이지 경로를 다시 확인하세요."), T("Open Output", "출력 폴더 열기"), MessageBoxButtons.OK, MessageBoxIcon.Asterisk);
				return;
			}
			string outputDir = FamilyBrowserStandardPolicyStore.GetDataRootFolder(_workspaceRoot);
			Directory.CreateDirectory(outputDir);
			Process.Start(new ProcessStartInfo(outputDir)
			{
				UseShellExecute = true
			});
		}
		catch (Exception ex)
		{
			ProjectData.SetProjectError(ex);
			Exception ex2 = ex;
			ShowLoggedError("Open Output", ex2);
			ProjectData.ClearProjectError();
		}
	}

	private void OpenRequestFolder()
	{
		try
		{
			string caption = T("Open Request Store", "요청 저장소 열기");
			if (!EnsurePermission("ManagePolicy", caption))
			{
				return;
			}
			FamilyBrowserStandardPolicy policy = _standardPolicy ?? LoadStandardPolicy();
			if (EnsureRequestStoreWritableOrPrompt(caption, ref policy, string.Empty))
			{
				string requestFolder = FamilyBrowserRequestStore.GetRequestFolder(_workspaceRoot, policy);
				if (string.IsNullOrWhiteSpace(requestFolder))
				{
					ShowDashboardMessage(this, T("Request store folder is not configured.", "요청 저장소 폴더가 설정되지 않았습니다."), caption, MessageBoxButtons.OK, MessageBoxIcon.Asterisk);
					return;
				}
				Directory.CreateDirectory(requestFolder);
				Process.Start(new ProcessStartInfo(requestFolder)
				{
					UseShellExecute = true
				});
			}
		}
		catch (Exception ex)
		{
			ProjectData.SetProjectError(ex);
			Exception ex2 = ex;
			ShowLoggedError("Open Request Store", ex2);
			ProjectData.ClearProjectError();
		}
	}

	private void OpenManagedRootFolder()
	{
		try
		{
			string caption = T("Open Managed Folder", "관리 폴더 열기");
			if (EnsurePermission("ManagePolicy", caption))
			{
				string managedRoot = ResolveManagedRootFolderForDisplay();
				if (string.IsNullOrWhiteSpace(managedRoot) || !Directory.Exists(managedRoot))
				{
					ShowDashboardMessage(this, T("No reachable managed folder is currently connected. Refresh the homepage path first.", "현재 연결된 관리 폴더에 접근할 수 없습니다. 먼저 홈페이지 경로를 다시 확인하세요."), caption, MessageBoxButtons.OK, MessageBoxIcon.Asterisk);
					return;
				}
				Process.Start(new ProcessStartInfo(managedRoot)
				{
					UseShellExecute = true
				});
			}
		}
		catch (Exception ex)
		{
			ProjectData.SetProjectError(ex);
			Exception ex2 = ex;
			ShowLoggedError("Open Managed Folder", ex2);
			ProjectData.ClearProjectError();
		}
	}

	private void CreateRequestDraft(string requestKind)
	{
		try
		{
			string caption = T("Register Request", "요청 등록");
			if (!EnsurePermission("CreateRequest", caption))
			{
				return;
			}
			FamilyBrowserStandardPolicy policy = _standardPolicy ?? LoadStandardPolicy();
			if (!EnsureRequestStoreWritableOrPrompt(caption, ref policy, string.Empty))
			{
				return;
			}
			using RequestComposerForm dialog = new RequestComposerForm(IsKorean(), NormalizeRequestKind(requestKind), BuildPolicyTargetLabel(), ResolveRequestDefaultItemName(requestKind), ResolveRequestDefaultReason(requestKind), BuildDisciplineDisplayOptions(policy));
			if (dialog.ShowDialog(this) != DialogResult.OK)
			{
				_statusMessage = T("Request registration cancelled.", "요청 등록이 취소되었습니다.");
				RenderDashboard();
				return;
			}
			string itemName = dialog.RequestTitle;
			string categoryName = (string.IsNullOrWhiteSpace(dialog.Discipline) ? BuildPolicyTargetLabel() : dialog.Discipline);
			string reason = dialog.RequestBody;
			List<string> attachmentPaths = dialog.AttachmentPaths;
			string submittedAt = DateTime.UtcNow.ToString("O", CultureInfo.InvariantCulture);
			string currentUser = CurrentUserIdentity();
			FamilyBrowserRequestRecord familyBrowserRequestRecord = BuildRequestRecord(dialog.RequestKind, itemName, categoryName, reason);
			familyBrowserRequestRecord.Status = "Submitted";
			familyBrowserRequestRecord.UpdatedAtUtc = submittedAt;
			familyBrowserRequestRecord.LastUpdatedBy = currentUser;
			familyBrowserRequestRecord.Discipline = categoryName;
			familyBrowserRequestRecord.CategoryName = categoryName;
			familyBrowserRequestRecord.ProgressNote = T("Request registered.", "요청 등록 완료");
			familyBrowserRequestRecord.History = new List<string> { submittedAt + " | " + currentUser + " | Request registered" };
			FamilyBrowserRequestSaveResult saveResult = SaveRequestWithStoreFallback(ref policy, familyBrowserRequestRecord, attachmentPaths, caption);
			if (saveResult != null)
			{
				familyBrowserRequestRecord.SourcePath = saveResult.RequestPath;
				familyBrowserRequestRecord.AttachmentFolder = saveResult.AttachmentFolder;
				_statusMessage = T("Request registered: ", "요청 등록 완료: ") + familyBrowserRequestRecord.ItemName;
				RefreshRequestsAndAudit(forceLoadRequests: true);
				if (!_requestRecords.Any([SpecialName] (FamilyBrowserRequestRecord x) => string.Equals(x.RequestId, familyBrowserRequestRecord.RequestId, StringComparison.OrdinalIgnoreCase)))
				{
					_requestRecords.Insert(0, familyBrowserRequestRecord);
				}
				RenderDashboard();
			}
		}
		catch (Exception ex)
		{
			ProjectData.SetProjectError(ex);
			Exception ex2 = ex;
			ShowLoggedError("Create Request", ex2);
			ProjectData.ClearProjectError();
		}
	}

	private FamilyBrowserRequestSaveResult SaveRequestWithStoreFallback(ref FamilyBrowserStandardPolicy policy, FamilyBrowserRequestRecord record, IEnumerable<string> attachmentPaths, string caption)
	{
		FamilyBrowserRequestSaveResult SaveRequestWithStoreFallback;
		try
		{
			SaveRequestWithStoreFallback = FamilyBrowserRequestStore.Save(_workspaceRoot, policy, record, attachmentPaths);
		}
		catch (Exception ex)
		{
			ProjectData.SetProjectError(ex);
			Exception firstFailure = ex;
			if (!EnsureRequestStoreWritableOrPrompt(caption, ref policy, firstFailure.Message))
			{
				if (CanSeeInternalPaths())
				{
					_statusMessage = T("Request registration was cancelled because no writable request store was selected.", "쓸 수 있는 요청 저장소가 선택되지 않아 요청 등록을 취소했습니다.");
				}
				else
				{
					_statusMessage = T("Request registration could not be saved. Ask an administrator to check the request storage.", "요청을 저장할 수 없습니다. 관리자에게 요청 저장소 확인을 요청하세요.");
				}
				RenderDashboard();
				SaveRequestWithStoreFallback = null;
				ProjectData.ClearProjectError();
			}
			else
			{
				SaveRequestWithStoreFallback = FamilyBrowserRequestStore.Save(_workspaceRoot, policy, record, attachmentPaths);
				ProjectData.ClearProjectError();
			}
		}
		return SaveRequestWithStoreFallback;
	}

	private bool EnsureRequestStoreWritableOrPrompt(string caption, ref FamilyBrowserStandardPolicy policy, string reason)
	{
		if (policy == null)
		{
			policy = LoadStandardPolicy();
		}
		string detail = string.Empty;
		FamilyBrowserRequestStoreInfo info = FamilyBrowserRequestStore.GetRequestStoreInfo(_workspaceRoot, policy);
		if (FamilyBrowserRequestStoreBackendService.TestWritable(info, ref detail))
		{
			return true;
		}
		if (!CanSeeInternalPaths())
		{
			_statusMessage = T("The request store is not reachable. Ask an administrator to check the Family Request Path Settings.", "요청 저장소에 연결할 수 없습니다. 관리자에게 패밀리 요청 경로 설정 확인을 요청하세요.");
			RenderDashboard();
			return false;
		}
		string selectedPath = string.Empty;
		if (!PromptRequestStoreFolder(caption, reason, info, ref selectedPath))
		{
			_statusMessage = T("Request store selection was cancelled.", "요청 저장소 선택이 취소되었습니다.");
			RenderDashboard();
			return false;
		}
		string folder = TrimFolderSeparators(Environment.ExpandEnvironmentVariables(selectedPath));
		if (string.IsNullOrWhiteSpace(folder))
		{
			_statusMessage = T("Request store folder is empty.", "요청 저장소 폴더 경로가 비어 있습니다.");
			RenderDashboard();
			return false;
		}
		if (!IsAllowedSharedRuntimePath(folder))
		{
			_statusMessage = T("Request store must be a shared managed folder, not a local C/AppData/UserProfile path.", "요청 저장소는 로컬 C/AppData/사용자 폴더가 아니라 공용 관리 폴더여야 합니다.");
			RenderDashboard();
			return false;
		}
		Directory.CreateDirectory(folder);
		FamilyBrowserStandardPolicyStore.SetRequestStore(_workspaceRoot, policy, "NetworkShare", folder, string.Empty, Environment.UserName);
		_standardPolicy = LoadStandardPolicy();
		policy = _standardPolicy;
		info = FamilyBrowserRequestStore.GetRequestStoreInfo(_workspaceRoot, policy);
		if (!FamilyBrowserRequestStoreBackendService.TestWritable(info, ref detail))
		{
			throw new InvalidOperationException(T("The selected request store is not writable. ", "선택한 요청 저장소에 쓸 수 없습니다. ") + detail);
		}
		FamilyBrowserRequestStoreBackendService.WriteStoreManifest(folder, info);
		_statusMessage = T("Request store connected: ", "요청 저장소 연결 완료: ") + folder;
		UpdateOperationalReadiness(policy);
		return true;
	}

	private bool PromptRequestStoreFolder(string caption, string reason, FamilyBrowserRequestStoreInfo info, ref string selectedPath)
	{
		using FolderBrowserDialog dialog = new FolderBrowserDialog();
		string currentPath = ((info == null) ? string.Empty : info.StoreLocation);
		dialog.Description = T("The request store is not available. Select a folder that this PC can read and write. Use the same shared folder on colleague PCs to see the same request list.", "요청 저장소에 접근할 수 없습니다. 이 PC에서 읽고 쓸 수 있는 폴더를 선택하세요. 동료 PC에서도 같은 요청 목록을 보려면 같은 공유 폴더를 선택하면 됩니다.");
		if (!string.IsNullOrWhiteSpace(reason))
		{
			FolderBrowserDialog folderBrowserDialog;
			(folderBrowserDialog = dialog).Description = folderBrowserDialog.Description + Environment.NewLine + Environment.NewLine + T("Cause: ", "원인: ") + reason;
		}
		dialog.ShowNewFolderButton = true;
		if (CanProbeRequestStoreDirectory(info, currentPath) && FamilyBrowserRequestStoreBackendService.DirectoryExistsFast(info, 500))
		{
			dialog.SelectedPath = currentPath;
		}
		if (dialog.ShowDialog(this) != DialogResult.OK || string.IsNullOrWhiteSpace(dialog.SelectedPath))
		{
			return false;
		}
		selectedPath = dialog.SelectedPath;
		return true;
	}

	private static bool CanProbeRequestStoreDirectory(FamilyBrowserRequestStoreInfo info, string currentPath)
	{
		if (string.IsNullOrWhiteSpace(currentPath))
		{
			return false;
		}
		if (info == null || !info.IsFileBacked || !info.IsShared)
		{
			return true;
		}
		string detail = string.Empty;
		if (FamilyBrowserRequestStoreBackendService.IsObviouslyUnavailable(info, ref detail))
		{
			return false;
		}
		return !currentPath.Trim().StartsWith("\\\\", StringComparison.Ordinal);
	}

	private List<string> PromptRequestAttachments(string requestKind)
	{
		List<string> selectedPaths = new List<string>();
		if (ShowDashboardMessage(this, T("Attach reference files to this request?", "이 요청에 참고 파일을 첨부할까요?") + Environment.NewLine + T("Files will be attached to the request. The storage path is managed by administrators.", "파일은 요청에 첨부됩니다. 저장 경로는 관리자가 관리합니다."), ResolveRequestTitle(requestKind), MessageBoxButtons.YesNo, MessageBoxIcon.Question) != DialogResult.Yes)
		{
			return selectedPaths;
		}
		using (OpenFileDialog dialog = new OpenFileDialog())
		{
			dialog.Title = T("Select request attachments", "요청 첨부파일 선택");
			dialog.Filter = "All files (*.*)|*.*|Revit Families (*.rfa)|*.rfa|Revit Projects (*.rvt)|*.rvt|Documents (*.pdf;*.docx;*.xlsx;*.pptx;*.txt)|*.pdf;*.docx;*.xlsx;*.pptx;*.txt";
			dialog.CheckFileExists = true;
			dialog.Multiselect = true;
			dialog.RestoreDirectory = true;
			if (dialog.ShowDialog(this) == DialogResult.OK)
			{
				selectedPaths.AddRange(dialog.FileNames.Where([SpecialName] (string x) => !string.IsNullOrWhiteSpace(x)));
			}
		}
		return selectedPaths;
	}

	private void UpdateRequestStatusFromAction(string action)
	{
		try
		{
			FamilyBrowserStandardPolicy policy = _standardPolicy ?? LoadStandardPolicy();
			string[] parts = action.Split('/');
			if (parts.Length < 3)
			{
				_statusMessage = T("Request status action is incomplete.", "요청 상태 변경 정보가 부족합니다.");
				RenderDashboard();
				return;
			}
			string nextStatus = ResolveRequestStatusToken(parts[1]);
			string requestId = parts[2].Trim();
			if (string.IsNullOrWhiteSpace(nextStatus) || string.IsNullOrWhiteSpace(requestId))
			{
				_statusMessage = T("Request status action is incomplete.", "요청 상태 변경 정보가 부족합니다.");
				RenderDashboard();
				return;
			}
			string requiredPermission = (string.Equals(nextStatus, "Submitted", StringComparison.OrdinalIgnoreCase) ? "SubmitRequest" : "ApproveRequest");
			if (EnsurePermission(requiredPermission, T("Update Request Status", "요청 상태 변경")))
			{
				string note = PromptText(T("Update Request Status", "요청 진행 상태 변경"), T("Add a short progress note.", "진행 메모를 짧게 입력하세요."), ResolveDefaultStatusNote(nextStatus));
				if (note == null)
				{
					_statusMessage = T("Request status update cancelled.", "요청 진행 상태 변경이 취소되었습니다.");
					RenderDashboard();
					return;
				}
				FamilyBrowserRequestStore.UpdateStatus(_workspaceRoot, policy, requestId, nextStatus, CurrentUserIdentity(), note);
				_statusMessage = T("Request status updated: ", "요청 진행 상태 변경 완료: ") + RequestStatusLabel(nextStatus);
				RefreshRequestsAndAudit(forceLoadRequests: true);
				RenderDashboard();
			}
		}
		catch (Exception ex)
		{
			ProjectData.SetProjectError(ex);
			Exception ex2 = ex;
			ShowLoggedError("Update Request Status", ex2);
			ProjectData.ClearProjectError();
		}
	}

	private void DeleteRequestFromAction(string action)
	{
		try
		{
			string caption = T("Delete Request", "요청 삭제");
			string text = action.Substring("request-delete/".Length).Trim();
			if (string.IsNullOrWhiteSpace(text))
			{
				_statusMessage = T("Request delete action is incomplete.", "요청 삭제 정보가 부족합니다.");
				RenderDashboard();
				return;
			}
			FamilyBrowserStandardPolicy policy = _standardPolicy ?? LoadStandardPolicy();
			FamilyBrowserRequestRecord record = FamilyBrowserRequestStore.List(_workspaceRoot, policy).FirstOrDefault([SpecialName] (FamilyBrowserRequestRecord x) => string.Equals(x.RequestId, text, StringComparison.OrdinalIgnoreCase));
			if (record == null)
			{
				_statusMessage = T("Request was not found.", "요청을 찾을 수 없습니다.");
				RenderDashboard();
				return;
			}
			if (!CanDeleteRequestRecord(record))
			{
				_statusMessage = T("Only the request creator or an administrator can delete this request.", "요청 작성자 또는 관리자만 이 요청을 삭제할 수 있습니다.");
				ShowDashboardMessage(this, _statusMessage, caption, MessageBoxButtons.OK, MessageBoxIcon.Exclamation);
				RenderDashboard();
				return;
			}
			string confirmMessage = T("Delete this request? Only this request file and its attachments will be removed.", "이 요청을 삭제할까요? 이 요청 파일과 이 요청의 첨부파일만 삭제됩니다.") + Environment.NewLine + Environment.NewLine + T("Request: ", "요청: ") + record.ItemName + Environment.NewLine + T("Status: ", "상태: ") + RequestStatusLabel(record.Status);
			if (ShowDashboardMessage(this, confirmMessage, caption, MessageBoxButtons.YesNo, MessageBoxIcon.Question) != DialogResult.Yes)
			{
				_statusMessage = T("Request deletion cancelled.", "요청 삭제가 취소되었습니다.");
				RenderDashboard();
				return;
			}
			FamilyBrowserRequestStore.Delete(_workspaceRoot, policy, text, new string[2]
			{
				Environment.UserName,
				CurrentUserIdentity()
			}, CanSeeInternalPaths());
			_statusMessage = T("Request deleted: ", "요청 삭제 완료: ") + record.ItemName;
			RefreshRequestsAndAudit(forceLoadRequests: true);
			RenderDashboard();
		}
		catch (UnauthorizedAccessException ex)
		{
			ProjectData.SetProjectError(ex);
			UnauthorizedAccessException ex2 = ex;
			_statusMessage = T("Only the request creator or an administrator can delete this request.", "요청 작성자 또는 관리자만 이 요청을 삭제할 수 있습니다.");
			ShowDashboardMessage(this, _statusMessage, T("Delete Request", "요청 삭제"), MessageBoxButtons.OK, MessageBoxIcon.Exclamation);
			RenderDashboard();
			ProjectData.ClearProjectError();
		}
		catch (Exception ex3)
		{
			ProjectData.SetProjectError(ex3);
			Exception ex4 = ex3;
			ShowLoggedError("Delete Request", ex4);
			ProjectData.ClearProjectError();
		}
	}

