		{
			if (EnsurePermission("ManagePolicy", T("Request Store", "요청 저장소")))
			{
				FamilyBrowserStandardPolicy policy = LoadStandardPolicy();
				string currentPath = ((policy.RequestStore == null) ? string.Empty : policy.RequestStore.Path);
				string requestPath = PromptText(T("Manual Request Folder", "요청 폴더 수동 지정"), T("Enter the shared request folder path only when you need to override the homepage-managed folder. Example: \\\\server\\BIM\\KKYFamilyBrowser\\Requests", "홈페이지 관리 폴더를 예외적으로 덮어쓸 때만 공유 요청 폴더 경로를 입력하세요. 예: \\\\server\\BIM\\KKYFamilyBrowser\\Requests"), currentPath);
				if (string.IsNullOrWhiteSpace(requestPath))
				{
					_statusMessage = T("Request store update was cancelled.", "요청 저장소 변경이 취소되었습니다.");
