	private static string TrimFolderSeparators(string folderPath)
	{
		string text = (folderPath ?? string.Empty).Trim();
		if (string.IsNullOrWhiteSpace(text))
		{
			return string.Empty;
		}
		string root = Path.GetPathRoot(text);
		while (text.Length > (root ?? string.Empty).Length && (text.EndsWith(Path.DirectorySeparatorChar.ToString(), StringComparison.Ordinal) || text.EndsWith(Path.AltDirectorySeparatorChar.ToString(), StringComparison.Ordinal)))
		{
			text = text.Substring(0, checked(text.Length - 1));
		}
		return text;
	}

	private static bool IsAllowedSharedRuntimePath(string path)
	{
		string value = Environment.ExpandEnvironmentVariables((path ?? string.Empty).Trim());
		bool IsAllowedSharedRuntimePath;
		if (string.IsNullOrWhiteSpace(value))
		{
			IsAllowedSharedRuntimePath = false;
		}
		else
		{
			try
			{
				if (value.StartsWith("\\\\", StringComparison.Ordinal))
				{
					IsAllowedSharedRuntimePath = true;
				}
				else
				{
					string root = Path.GetPathRoot(value);
					if (string.IsNullOrWhiteSpace(root))
					{
						IsAllowedSharedRuntimePath = false;
					}
					else
					{
						string windowsRoot = Path.GetPathRoot(Environment.GetFolderPath(Environment.SpecialFolder.Windows));
						IsAllowedSharedRuntimePath = (string.IsNullOrWhiteSpace(windowsRoot) || !string.Equals(root, windowsRoot, StringComparison.OrdinalIgnoreCase)) && !IsSameOrChildRuntimePath(value, Environment.GetFolderPath(Environment.SpecialFolder.CommonApplicationData)) && !IsSameOrChildRuntimePath(value, Environment.GetFolderPath(Environment.SpecialFolder.ApplicationData)) && !IsSameOrChildRuntimePath(value, Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData)) && !IsSameOrChildRuntimePath(value, Environment.GetFolderPath(Environment.SpecialFolder.UserProfile)) && !IsSameOrChildRuntimePath(value, Path.GetTempPath());
					}
				}
			}
			catch (Exception projectError)
			{
				ProjectData.SetProjectError(projectError);
				IsAllowedSharedRuntimePath = false;
				ProjectData.ClearProjectError();
			}
		}
		return IsAllowedSharedRuntimePath;
	}

	private static bool IsSameOrChildRuntimePath(string candidate, string parent)
	{
		bool IsSameOrChildRuntimePath;
		if (string.IsNullOrWhiteSpace(candidate) || string.IsNullOrWhiteSpace(parent))
		{
			IsSameOrChildRuntimePath = false;
		}
		else
		{
			try
			{
				string candidateFull = Path.GetFullPath(candidate).TrimEnd(Path.DirectorySeparatorChar, Path.AltDirectorySeparatorChar);
				string parentFull = Path.GetFullPath(parent).TrimEnd(Path.DirectorySeparatorChar, Path.AltDirectorySeparatorChar);
				IsSameOrChildRuntimePath = string.Equals(candidateFull, parentFull, StringComparison.OrdinalIgnoreCase) || candidateFull.StartsWith(parentFull + Conversions.ToString(Path.DirectorySeparatorChar), StringComparison.OrdinalIgnoreCase) || candidateFull.StartsWith(parentFull + Conversions.ToString(Path.AltDirectorySeparatorChar), StringComparison.OrdinalIgnoreCase);
			}
			catch (Exception projectError)
			{
				ProjectData.SetProjectError(projectError);
				IsSameOrChildRuntimePath = false;
				ProjectData.ClearProjectError();
			}
		}
		return IsSameOrChildRuntimePath;
	}

	private void ConfigureConnectorRequestStore(string mode)
	{
		try
		{
			if (!EnsurePermission("ManagePolicy", T("Request Store", "요청 저장소")))
			{
				return;
			}
			FamilyBrowserStandardPolicy policy = LoadStandardPolicy();
			FamilyBrowserRequestStoreSettings settings = policy.RequestStore ?? FamilyBrowserRequestStoreSettings.CreateDefault();
			string currentPath = ((settings == null) ? string.Empty : settings.Path);
			string currentEndpoint = ((settings == null) ? string.Empty : settings.Endpoint);
			string title = ResolveRequestStoreSetupTitle(mode);
			string requestPath = PromptText(title, ResolveRequestStorePathPrompt(mode), currentPath);
			if (requestPath == null)
			{
				_statusMessage = T("Request store update was cancelled.", "요청 저장소 변경이 취소되었습니다.");
				RenderDashboard();
				return;
			}
			string endpoint = PromptText(title, ResolveRequestStoreEndpointPrompt(mode), currentEndpoint);
			if (endpoint == null)
			{
				_statusMessage = T("Request store update was cancelled.", "요청 저장소 변경이 취소되었습니다.");
				RenderDashboard();
				return;
			}
			if (string.IsNullOrWhiteSpace(requestPath) && string.IsNullOrWhiteSpace(endpoint))
			{
				_statusMessage = T("Request store update was cancelled.", "요청 저장소 변경이 취소되었습니다.");
				RenderDashboard();
				return;
			}
			FamilyBrowserStandardPolicyStore.SetRequestStore(_workspaceRoot, policy, mode, requestPath, endpoint, Environment.UserName);
			FamilyBrowserRequestStoreInfo info = FamilyBrowserRequestStore.GetRequestStoreInfo(_workspaceRoot, policy);
			_statusMessage = T("Request store changed: ", "요청 저장소를 변경했습니다: ") + ((info == null) ? mode : FamilyBrowserRequestStore.Describe(_workspaceRoot, policy));
			RefreshDocumentShellOnly();
		}
		catch (Exception ex)
		{
			ProjectData.SetProjectError(ex);
			Exception ex2 = ex;
			ShowLoggedError("Set Request Store", ex2);
			ProjectData.ClearProjectError();
		}
	}

	private string ResolveRequestStoreSetupTitle(string mode)
	{
		switch (FamilyBrowserPolicyKey.Normalize(mode))
		{
		case "sharepoint":
		case "share-point":
			return T("SharePoint Request Store", "SharePoint 요청 저장소");
		case "cloudstorage":
		case "cloud-storage":
			return T("Cloud Request Store", "클라우드 요청 저장소");
		case "api":
			return T("API Request Store", "API 요청 저장소");
		default:
			return T("Request Store", "요청 저장소");
		}
	}

	private string ResolveRequestStorePathPrompt(string mode)
	{
		switch (FamilyBrowserPolicyKey.Normalize(mode))
		{
		case "sharepoint":
		case "share-point":
			return T("Enter the locally synced SharePoint request folder. Leave blank to use a local connector queue.", "로컬 동기화된 SharePoint 요청 폴더를 입력하세요. 비워두면 로컬 커넥터 큐를 사용합니다.");
		case "cloudstorage":
		case "cloud-storage":
			return T("Enter the locally synced cloud request folder. Leave blank to use a local connector queue.", "로컬 동기화된 클라우드 요청 폴더를 입력하세요. 비워두면 로컬 커넥터 큐를 사용합니다.");
		case "api":
			return T("Enter the API connector queue or mirror folder. Leave blank to use this PC's local queue.", "API 커넥터 큐 또는 미러 폴더를 입력하세요. 비워두면 현재 PC의 로컬 큐를 사용합니다.");
		default:
			return T("Enter the request store folder.", "요청 저장소 폴더를 입력하세요.");
		}
	}

	private string ResolveRequestStoreEndpointPrompt(string mode)
	{
		switch (FamilyBrowserPolicyKey.Normalize(mode))
		{
		case "sharepoint":
		case "share-point":
			return T("Enter the SharePoint site or library URL for reference. This is optional when a synced folder is used.", "참고용 SharePoint 사이트 또는 라이브러리 URL을 입력하세요. 동기화 폴더를 쓰면 선택 사항입니다.");
		case "cloudstorage":
		case "cloud-storage":
			return T("Enter the cloud storage URL for reference. This is optional when a synced folder is used.", "참고용 클라우드 저장소 URL을 입력하세요. 동기화 폴더를 쓰면 선택 사항입니다.");
		case "api":
			return T("Enter the server API endpoint. The current build will stage requests in the queue folder for that connector.", "서버 API 엔드포인트를 입력하세요. 현재 빌드는 해당 커넥터용 큐 폴더에 요청을 적재합니다.");
		default:
			return T("Enter an optional endpoint or reference URL.", "선택 사항인 엔드포인트 또는 참조 URL을 입력하세요.");
