	private void RefreshDeploymentBootstrap()
	{
		try
		{
			if (EnsurePermission("ManagePolicy", T("Shared Settings", "공유 설정")))
			{
				if (FamilyBrowserDeploymentBootstrapService.IsBootstrapDisabled(FamilyBrowserMachineConfigStore.ResolveDeploymentBootstrapUrl()))
				{
					FamilyBrowserDeploymentBootstrapService.SetBootstrapUrl(string.Empty, Environment.UserName);
				}
				_deploymentBootstrapResult = FamilyBrowserDeploymentBootstrapService.TryApply(_workspaceRoot, Environment.UserName, force: true, BuildDeploymentProjectIdentity(GetActiveDocument()));
				_standardPolicy = LoadStandardPolicy();
				FamilyBrowserNativeCommandGuardService.NotifyPolicyChanged();
				RefreshDocumentShellOnly();
				_statusMessage = T("Shared settings refreshed: ", "공유 설정 새로고침 완료: ") + ResolveDeploymentBootstrapMessage();
				RenderDashboard();
			}
		}
		catch (Exception ex)
		{
			ProjectData.SetProjectError(ex);
			Exception ex2 = ex;
			ShowLoggedError("Shared Settings", ex2);
			ProjectData.ClearProjectError();
		}
	}

	private void RefreshHomepageSecurityPolicy()
	{
		try
		{
			FamilyBrowserDeploymentBootstrapSecurityRefreshResult result = FamilyBrowserDeploymentBootstrapService.RefreshSecurityFromHomepage(_workspaceRoot, Environment.UserName, BuildDeploymentProjectIdentity(GetActiveDocument()));
			_standardPolicy = LoadStandardPolicy();
			FamilyBrowserNativeCommandGuardService.NotifyPolicyChanged();
			EnsureAdminModeAllowed(_standardPolicy);
			string message = ((result == null) ? string.Empty : result.Message);
			RefreshDocumentShellOnly();
			if (result != null && result.Success)
			{
				_statusMessage = T("Homepage permission keywords refreshed: ", "홈페이지 권한 키워드 새로고침 완료: ") + ResolveHomepageSecurityRefreshMessage(message);
			}
			else
			{
				_statusMessage = T("Homepage permission refresh failed: ", "홈페이지 권한 새로고침 실패: ") + ResolveHomepageSecurityRefreshMessage(message);
			}
			RenderDashboard();
		}
		catch (Exception ex)
		{
			ProjectData.SetProjectError(ex);
			Exception ex2 = ex;
			ShowLoggedError(T("Homepage Permission Refresh", "홈페이지 권한 새로고침"), ex2);
			ProjectData.ClearProjectError();
		}
	}

	private void ConfigureDeploymentBootstrapProfile()
	{
		try
		{
			if (!EnsurePermission("ManagePolicy", T("Shared Settings Profile", "공유 설정 프로필")))
			{
				return;
			}
			FamilyBrowserDeploymentBootstrapProfileIndexResult indexResult = FamilyBrowserDeploymentBootstrapService.ListBootstrapProfiles(force: true);
			if (indexResult == null || !indexResult.Success || indexResult.Profiles == null || indexResult.Profiles.Count == 0)
			{
				_statusMessage = T("No homepage profile list was found. Use Set Shared Settings URL or update bootstrap-index.json.", "홈페이지 프로필 목록을 찾지 못했습니다. 공유 설정 URL을 직접 지정하거나 bootstrap-index.json을 갱신하세요.");
				RenderDashboard();
				return;
			}
			string currentUrl = FamilyBrowserMachineConfigStore.ResolveDeploymentBootstrapUrl();
			if (string.IsNullOrWhiteSpace(currentUrl))
			{
				currentUrl = ((_deploymentBootstrapResult == null) ? string.Empty : _deploymentBootstrapResult.BootstrapUrl);
			}
			string finalMessage;
			using (BootstrapProfileSelectionForm dialog = new BootstrapProfileSelectionForm(IsKorean(), indexResult, currentUrl, BuildDeploymentProjectIdentity(GetActiveDocument())))
			{
				if (dialog.ShowDialog(this) != DialogResult.OK)
				{
					_statusMessage = T("Shared settings profile selection was cancelled.", "공유 설정 프로필 선택이 취소되었습니다.");
					RenderDashboard();
					return;
				}
				if (dialog.UseAutomaticMatching)
				{
					FamilyBrowserDeploymentBootstrapService.SetBootstrapUrl(string.Empty, Environment.UserName);
					finalMessage = T("Homepage automatic matching is active. Users do not need to choose a profile.", "홈페이지 자동 매칭을 사용합니다. 사용자는 프로필을 선택할 필요가 없습니다.");
				}
				else
				{
					FamilyBrowserDeploymentBootstrapService.SetBootstrapUrl(dialog.SelectedProfileUrl, Environment.UserName);
					finalMessage = T("Shared settings profile selected on this PC: ", "이 PC의 공유 설정 프로필 선택 완료: ") + dialog.SelectedProfileName;
				}
			}
			_deploymentBootstrapResult = FamilyBrowserDeploymentBootstrapService.TryApply(_workspaceRoot, Environment.UserName, force: true, BuildDeploymentProjectIdentity(GetActiveDocument()));
			_standardPolicy = LoadStandardPolicy();
			FamilyBrowserNativeCommandGuardService.NotifyPolicyChanged();
			RefreshDocumentShellOnly();
			_statusMessage = finalMessage;
			RenderDashboard();
		}
		catch (Exception ex)
		{
			ProjectData.SetProjectError(ex);
			Exception ex2 = ex;
			ShowLoggedError("Shared Settings Profile", ex2);
			ProjectData.ClearProjectError();
		}
	}

	private void ConfigureDeploymentBootstrapUrl()
	{
		try
		{
			if (EnsurePermission("ManagePolicy", T("Shared Settings", "공유 설정")))
			{
				string currentUrl = FamilyBrowserMachineConfigStore.ResolveDeploymentBootstrapUrl();
				if (string.IsNullOrWhiteSpace(currentUrl))
				{
					currentUrl = "disabled";
				}
				string bootstrapUrl = PromptText(T("Shared Settings URL", "공유 설정 URL"), T("Enter the Family Browser shared settings JSON URL or file path.", "Family Browser 공유 설정 JSON URL 또는 파일 경로를 입력하세요."), currentUrl);
				if (string.IsNullOrWhiteSpace(bootstrapUrl))
				{
					_statusMessage = T("Shared settings URL update was cancelled.", "공유 설정 URL 변경이 취소되었습니다.");
					RenderDashboard();
					return;
				}
				FamilyBrowserDeploymentBootstrapService.SetBootstrapUrl(bootstrapUrl.Trim(), Environment.UserName);
				_deploymentBootstrapResult = FamilyBrowserDeploymentBootstrapService.TryApply(_workspaceRoot, Environment.UserName, force: true, BuildDeploymentProjectIdentity(GetActiveDocument()));
				_standardPolicy = LoadStandardPolicy();
				FamilyBrowserNativeCommandGuardService.NotifyPolicyChanged();
				RefreshDocumentShellOnly();
				_statusMessage = T("Shared settings URL saved: ", "공유 설정 URL 저장 완료: ") + bootstrapUrl.Trim();
				RenderDashboard();
			}
		}
		catch (Exception ex)
		{
			ProjectData.SetProjectError(ex);
			Exception ex2 = ex;
			ShowLoggedError("Shared Settings URL", ex2);
			ProjectData.ClearProjectError();
		}
	}

	private FamilyBrowserRequestRecord BuildRequestRecord(string requestKind, string itemName, string categoryName, string reason)
	{
		Document doc = GetActiveDocument();
		if (_standardPolicy == null)
		{
			LoadStandardPolicy();
		}
		StandardLibraryRegistrationRecord registration = _registration;
		ProjectTrackingCatalog catalog = ((doc == null) ? null : ProjectTrackingStoreService.Load(doc));
		string currentUser = CurrentUserIdentity();
		FamilyBrowserRequestRecord record = new FamilyBrowserRequestRecord
		{
			RequestId = FamilyBrowserRequestStore.CreateRequestId(requestKind),
			RequestKind = NormalizeRequestKind(requestKind),
			Status = "Draft",
			CreatedAtUtc = DateTime.UtcNow.ToString("O", CultureInfo.InvariantCulture),
			CreatedBy = currentUser,
			UpdatedAtUtc = DateTime.UtcNow.ToString("O", CultureInfo.InvariantCulture),
			LastUpdatedBy = currentUser,
			ProjectTitle = ((doc == null) ? _projectTitle : doc.Title),
			ProjectPath = ((doc == null) ? _projectPath : (string.IsNullOrWhiteSpace(doc.PathName) ? T("Unsaved project", "저장되지 않은 프로젝트") : doc.PathName)),
			CentralPath = _centralPathText,
			StandardTarget = BuildPolicyTargetLabel(),
			StandardMode = BuildPolicyModeLabel(),
			StandardDisplayName = ((registration == null) ? T("not registered", "미등록") : registration.DisplayName),
			StandardRvtPath = ((registration == null) ? _standardPathText : registration.ResolvedPath),
			StandardSourceId = ((registration == null) ? string.Empty : registration.SourceId),
			ComparisonPath = _lastComparisonPath,
			PreflightPath = _lastPreflightPath,
			TrackingState = ((catalog == null) ? _trackingText : catalog.ApprovedStandardStamp),
			ItemName = itemName,
			CategoryName = categoryName,
			Discipline = BuildPolicyTargetLabel(),
			SuggestedAction = ResolveRequestSuggestedAction(requestKind),
			Reason = reason,
			Notes = BuildRequestNotes(requestKind),
			ProgressNote = T("Request registered.", "요청 등록 완료")
		};
		record.History.Add(record.CreatedAtUtc + " | " + currentUser + " | Request registered");
		if (!string.IsNullOrWhiteSpace(_lastComparisonPath))
		{
			record.Attachments.Add(_lastComparisonPath);
		}
		if (!string.IsNullOrWhiteSpace(_lastPreflightPath))
		{
			record.Attachments.Add(_lastPreflightPath);
		}
		return record;
	}

	private string PromptText(string title, string prompt, string defaultValue)
	{
		using ModernTextPromptForm dialog = new ModernTextPromptForm(IsKorean(), title, prompt, defaultValue);
		if (dialog.ShowDialog(this) != DialogResult.OK)
		{
			return null;
		}
		return dialog.Value;
	}

	private string ResolveRequestTitle(string requestKind)
	{
		return NormalizeRequestKind(requestKind) switch
		{
			"FAMILY" => T("Family Request", "패밀리 추가 요청"), 
			"SYSTEM" => T("System Type Request", "시스템 타입 요청"), 
			"UPDATE" => T("Update Approval Request", "업데이트 승인 요청"), 
			_ => T("Request", "요청"), 
		};
	}

	private string ResolveRequestDefaultItemName(string requestKind)
	{
		return NormalizeRequestKind(requestKind) switch
		{
			"FAMILY" => T("New standard family", "신규 표준 패밀리"), 
			"SYSTEM" => T("New standard system type", "신규 표준 시스템 타입"), 
			"UPDATE" => T("Current model standard update approval", "현재 모델 표준 업데이트 승인"), 
			_ => string.Empty, 
		};
	}

	private string ResolveRequestDefaultReason(string requestKind)
	{
		return NormalizeRequestKind(requestKind) switch
		{
			"FAMILY" => T("Required family is not available in the registered standard RVT.", "필요한 패밀리가 등록된 표준 RVT에 없습니다."), 
			"SYSTEM" => T("Required system type or routing setup is not available in the registered standard RVT.", "필요한 시스템 타입 또는 라우팅 설정이 등록된 표준 RVT에 없습니다."), 
			"UPDATE" => T("Current project content differs from the registered standard and requires approval before overwrite.", "현재 프로젝트 내용이 등록된 표준과 달라 덮어쓰기 전 승인이 필요합니다."), 
			_ => string.Empty, 
		};
	}

	private string ResolveRequestSuggestedAction(string requestKind)
	{
		return NormalizeRequestKind(requestKind) switch
		{
			"FAMILY" => T("Review and add to standard RVT", "검토 후 표준 RVT에 추가"), 
			"SYSTEM" => T("Review system type, dependencies and routing settings", "시스템 타입, 의존 패밀리, 라우팅 설정 검토"), 
			"UPDATE" => T("Approve overwrite or reject drift", "덮어쓰기 승인 또는 변경 차단"), 
			_ => T("Review", "검토"), 
		};
	}

	private string BuildRequestNotes(string requestKind)
	{
		List<string> notes = new List<string>
		{
			T("Request created from KKY Family Browser.", "KKY 패밀리 브라우저에서 생성된 요청입니다."),
			T("Standard target: ", "표준 대상: ") + BuildPolicyTargetLabel(),
			T("Mode: ", "모드: ") + BuildPolicyModeLabel()
		};
		if (string.Equals(NormalizeRequestKind(requestKind), "SYSTEM", StringComparison.Ordinal))
		{
			notes.Add(T("System type requests must pass loadable-family foundation validation before apply.", "시스템 타입 요청은 적용 전 로더블 패밀리 기반 검증을 통과해야 합니다."));
		}
		if (!string.IsNullOrWhiteSpace(_lastComparisonPath))
		{
			notes.Add(T("Comparison report attached.", "비교 리포트가 첨부되었습니다."));
		}
		if (!string.IsNullOrWhiteSpace(_lastPreflightPath))
		{
			notes.Add(T("System type review report attached.", "시스템 타입 검토 리포트가 첨부되었습니다."));
		}
		return string.Join(Environment.NewLine, notes);
	}

	private static string NormalizeRequestKind(string requestKind)
	{
		return Normalize(requestKind) switch
		{
			"family" => "FAMILY", 
			"system" => "SYSTEM", 
			"update" => "UPDATE", 
			_ => "GENERAL", 
		};
	}

	private static string ResolveRequestStatusToken(string statusToken)
	{
		return Normalize(statusToken) switch
		{
			"draft" => "Draft", 
			"submitted" => "Submitted", 
			"reviewing" => "Reviewing", 
			"approved" => "Approved", 
			"rejected" => "Rejected", 
			"completed" => "Completed", 
			_ => string.Empty, 
		};
	}

	private string ResolveDefaultStatusNote(string status)
	{
		return Normalize(status) switch
		{
			"submitted" => T("Submitted to BIM manager.", "BIM 관리자에게 접수"), 
			"reviewing" => T("Review started.", "검토 시작"), 
			"approved" => T("Approved for standard update.", "표준 반영 승인"), 
			"rejected" => T("Rejected. See reason.", "반려, 사유 확인 필요"), 
			"completed" => T("Applied to standard library.", "표준 라이브러리 반영 완료"), 
			_ => T("Status updated.", "진행 상태 변경"), 
		};
	}

	private void UpdateSystemRowsFromPreflight(SystemTypePreflightReport report, string selectedDisciplineKey = null)
	{
		if (report == null)
		{
			_systemRows = new List<SystemRow>();
			_systemSummary = T("System comparison has not been refreshed yet.", "시스템 비교가 아직 새로고침되지 않았습니다.");
			_lastSystemPreflightReport = null;
			return;
		}
		_lastSystemPreflightReport = report;
		FamilyBrowserStandardLibrarySlot slot = ResolvePolicySlot(_standardPolicy ?? LoadStandardPolicy(), selectedDisciplineKey);
		string disciplineKey = ResolveSlotKey(slot);
		string disciplineLabel = ResolveSlotLabel(slot);
		_systemRows = (from x in report.ExecutionPlan.Items.OrderBy([SpecialName] (SystemSyncExecutionItem x) => Normalize(x.CategoryName) + "|" + Normalize(x.SystemTypeName), StringComparer.Ordinal)
			select BuildSystemRowFromExecutionItem(x, disciplineKey, disciplineLabel) into x
			where _adminModeEnabled || !ShouldHideMatchedStandardStatus(x.RawStatus)
			select x).ToList();
		_systemSummary = T("Review: ready ", "검토: 준비 ") + report.Summary.ReadyCount.ToString(CultureInfo.InvariantCulture) + T(" / approval ", " / 승인 필요 ") + report.Summary.ApprovalRequiredCount.ToString(CultureInfo.InvariantCulture) + T(" / blocked ", " / 차단 ") + report.Summary.BlockedCount.ToString(CultureInfo.InvariantCulture) + T(" / loadable foundation blocked ", " / 로더블 기반 차단 ") + report.Summary.LoadableFoundationBlockedCount.ToString(CultureInfo.InvariantCulture) + T(" / dependency reload ", " / 의존성 재로드 ") + report.Summary.DependencyReloadCount.ToString(CultureInfo.InvariantCulture) + T(" / manual review ", " / 수동 검토 ") + report.Summary.DependencyManualReviewCount.ToString(CultureInfo.InvariantCulture);
	}

	private SystemRow BuildSystemRowFromExecutionItem(SystemSyncExecutionItem item, string disciplineKey, string disciplineLabel)
	{
		List<string> list = ExtractDuplicateStepTargets(item);
		string rawStatus = ((list.Count > 0) ? "DuplicateRisk" : item.ExecutionStatus);
		string notes = BuildExecutionNotes(item);
		string status = ((list.Count > 0) ? T("Duplicate Risk", "중복 위험") : DisplaySystemComparisonStatus(item.ExecutionStatus, notes));
		string action = ((list.Count > 0) ? T("Review Duplicate Types", "중복 타입 검토") : TranslateAction(item.SyncAction));
		return new SystemRow
		{
			Status = status,
			RawStatus = rawStatus,
			DisciplineKey = disciplineKey,
			DisciplineLabel = disciplineLabel,
			Name = item.SystemTypeName,
			Category = (string.IsNullOrWhiteSpace(item.CategoryName) ? item.SystemFamilyKind : item.CategoryName),
			SystemFamilyKind = item.SystemFamilyKind,
			Action = action,
			Notes = notes
		};
	}

	private StandardLibraryRegistrationRecord LoadRegistrationOrWarn(string caption, string standardTargetKey = null)
	{
		_standardPolicy = LoadStandardPolicy();
		FamilyBrowserStandardLibrarySlot slot = ResolvePolicySlot(_standardPolicy, standardTargetKey);
		string registryPath = ResolveRegistrationPathForSlot(_standardPolicy, slot);
		string targetLabel = ((slot == null) ? BuildPolicyTargetLabel() : ResolveSlotLabel(slot));
		if (!File.Exists(registryPath))
		{
			ShowDashboardMessage(this, T("Register Standard RVT first for ", "먼저 이 대상의 표준 RVT를 등록하세요: ") + targetLabel, caption, MessageBoxButtons.OK, MessageBoxIcon.Asterisk);
			return null;
		}
		StandardLibraryRegistrationRecord registration = LoadStandardRegistrationForDashboard(registryPath);
		if (registration == null || string.IsNullOrWhiteSpace(registration.LastSnapshotPath) || !File.Exists(registration.LastSnapshotPath))
		{
			ShowDashboardMessage(this, StandardScanNeededUserAction(), caption, MessageBoxButtons.OK, MessageBoxIcon.Asterisk);
			return null;
		}
		_registration = registration;
		return registration;
	}

	private StandardLibraryRegistrationRecord TryLoadRegistrationForSlot(FamilyBrowserStandardPolicy policy, FamilyBrowserStandardLibrarySlot slot, int timeoutMilliseconds = 0)
	{
		StandardLibraryRegistrationRecord TryLoadRegistrationForSlot;
		if (timeoutMilliseconds > 0)
		{
			try
			{
				Task<StandardLibraryRegistrationRecord> loadTask = Task.Factory.StartNew([SpecialName] () => this.TryLoadRegistrationForSlot(policy, slot), CancellationToken.None, TaskCreationOptions.DenyChildAttach, TaskScheduler.Default);
				if (loadTask.Wait(timeoutMilliseconds))
				{
					TryLoadRegistrationForSlot = loadTask.Result;
				}
				else
