	private void BeginLongOperationProgress(string title, string message, int total = 100)
	{
		_longOperationActive = true;
		_longOperationTitle = (title ?? string.Empty).Trim();
		_longOperationMessage = (message ?? string.Empty).Trim();
		_longOperationCurrent = 0;
		_longOperationTotal = Math.Max(1, total);
		_longOperationLastPaintUtc = DateTime.MinValue;
		_statusMessage = (string.IsNullOrWhiteSpace(_longOperationMessage) ? _longOperationTitle : _longOperationMessage);
		base.UseWaitCursor = true;
		Cursor = Cursors.WaitCursor;
		PaintLongOperationProgress(forcePaint: true);
	}

	private Action<int, int, string> CreateLongOperationProgressCallback(string title)
	{
		return [SpecialName] (int current, int total, string message) =>
		{
			UpdateLongOperationProgress(title, current, total, message);
		};
	}

	private Action<int, int, string> CreateDashboardRefreshProgressCallback(string progressTitle, int progressStart, int progressEnd, int subRangeStart, int subRangeEnd)
	{
		if ((string.IsNullOrWhiteSpace(progressTitle) || !_longOperationActive) && !IsStartupOverlayVisible())
		{
			return null;
		}
		return [SpecialName] (int current, int total, string message) =>
		{
			int num = Math.Max(1, total);
			double num2 = Math.Max(0.0, Math.Min(1.0, (double)current / (double)num));
			int num3 = Math.Max(0, Math.Min(100, subRangeStart));
			int num4 = Math.Max(num3, Math.Min(100, subRangeEnd));
			int current2 = checked(num3 + (int)Math.Round(num2 * (double)(num4 - num3)));
			ReportDashboardRefreshProgress(progressTitle, progressStart, progressEnd, current2, 100, message);
		};
	}

	private void ReportDashboardRefreshProgress(string progressTitle, int progressStart, int progressEnd, int current, int total, string message, bool forcePaint = false)
	{
		int safeTotal = Math.Max(1, total);
		double ratio = Math.Max(0.0, Math.Min(1.0, (double)current / (double)safeTotal));
		int startValue = Math.Max(0, Math.Min(100, progressStart));
		int endValue = Math.Max(startValue, Math.Min(100, progressEnd));
		int mappedCurrent = checked(startValue + (int)Math.Round(ratio * (double)(endValue - startValue)));
		if (IsStartupOverlayVisible())
		{
			int startupCurrent = mappedCurrent;
			if (_startupBrowserRenderPending && startupCurrent >= 100)
			{
				startupCurrent = 98;
			}
			UpdateStartupOverlayProgress(startupCurrent, 100, message, forcePaint);
		}
		if (!string.IsNullOrWhiteSpace(progressTitle) && _longOperationActive)
		{
			UpdateLongOperationProgress(progressTitle, mappedCurrent, 100, message, forcePaint);
		}
	}

	private void UpdateLongOperationProgress(string title, int current, int total, string message, bool forcePaint = false)
	{
		if (!_longOperationActive)
		{
			BeginLongOperationProgress(title, message, Math.Max(1, total));
		}
		if (!string.IsNullOrWhiteSpace(title))
		{
			_longOperationTitle = title.Trim();
		}
		_longOperationTotal = Math.Max(1, total);
		_longOperationCurrent = Math.Max(0, Math.Min(current, _longOperationTotal));
		if (!string.IsNullOrWhiteSpace(message))
		{
			_longOperationMessage = message.Trim();
		}
		_statusMessage = (string.IsNullOrWhiteSpace(_longOperationMessage) ? _longOperationTitle : _longOperationMessage);
		PaintLongOperationProgress(forcePaint);
	}

	private void UpdateLongOperationProgressRange(string title, int rangeStart, int rangeEnd, int current, int total, string message, bool forcePaint = false)
	{
		int safeTotal = Math.Max(1, total);
		double ratio = Math.Max(0.0, Math.Min(1.0, (double)current / (double)safeTotal));
		int startValue = Math.Max(0, Math.Min(100, rangeStart));
		int endValue = Math.Max(startValue, Math.Min(100, rangeEnd));
		int mapped = checked(startValue + (int)Math.Round(ratio * (double)(endValue - startValue)));
		UpdateLongOperationProgress(title, mapped, 100, message, forcePaint);
	}

	private void CompleteLongOperationProgress(string finalMessage = null)
	{
		if (!string.IsNullOrWhiteSpace(finalMessage))
		{
			_statusMessage = finalMessage.Trim();
		}
		_longOperationActive = false;
		base.UseWaitCursor = false;
		Cursor = Cursors.Default;
		Text = DashboardWindowTitle();
		PaintLongOperationProgress(forcePaint: true);
	}

	private void PaintLongOperationProgress(bool forcePaint = false)
	{
		DateTime now = DateTime.UtcNow;
		if (!forcePaint && DateTime.Compare(_longOperationLastPaintUtc, DateTime.MinValue) != 0 && (now - _longOperationLastPaintUtc).TotalMilliseconds < 250.0)
		{
			return;
		}
		_longOperationLastPaintUtc = now;
		try
		{
			Text = ((_longOperationActive && !string.IsNullOrWhiteSpace(_longOperationTitle)) ? (_longOperationTitle + " - " + _statusMessage) : DashboardWindowTitle());
			if (_browser == null || (object)_browser.Document == null)
			{
				Application.DoEvents();
				return;
			}
			SetDashboardElementText("dashboardStatusBar", _statusMessage);
			HtmlElement panel = _browser.Document.GetElementById("longOperationProgress");
			if ((object)panel == null)
			{
				Application.DoEvents();
				return;
			}
			panel.Style = (_longOperationActive ? "display:block;" : "display:none;");
			SetDashboardElementText("longOperationTitle", string.IsNullOrWhiteSpace(_longOperationTitle) ? T("Working", "작업 진행 중") : _longOperationTitle);
			SetDashboardElementText("longOperationMessage", string.IsNullOrWhiteSpace(_longOperationMessage) ? T("Please wait...", "잠시만 기다려주세요...") : _longOperationMessage);
			int percent = ResolveLongOperationPercent(_longOperationCurrent, _longOperationTotal);
			SetDashboardElementText("longOperationCount", _longOperationCurrent.ToString(CultureInfo.InvariantCulture) + " / " + _longOperationTotal.ToString(CultureInfo.InvariantCulture) + " (" + percent.ToString(CultureInfo.InvariantCulture) + "%)");
			HtmlElement bar = _browser.Document.GetElementById("longOperationBar");
			if ((object)bar != null)
			{
				bar.Style = "width:" + percent.ToString(CultureInfo.InvariantCulture) + "%;";
			}
		}
		catch (Exception projectError)
		{
			ProjectData.SetProjectError(projectError);
			ProjectData.ClearProjectError();
		}
		finally
		{
			Application.DoEvents();
		}
	}

	private void SetDashboardElementText(string elementId, string text)
	{
		try
		{
			if (_browser != null && (object)_browser.Document != null)
			{
				HtmlElement element = _browser.Document.GetElementById(elementId);
				if ((object)element != null)
				{
					element.InnerText = text ?? string.Empty;
				}
			}
		}
		catch (Exception projectError)
		{
			ProjectData.SetProjectError(projectError);
			ProjectData.ClearProjectError();
		}
	}

	private static int ResolveLongOperationPercent(int current, int total)
	{
		if (total <= 0)
		{
			return 0;
		}
		int value = checked((int)Math.Round((double)Math.Max(0, current) / (double)total * 100.0));
		return Math.Max(0, Math.Min(100, value));
	}

	private void RenderDashboard(bool preserveCurrentBrowserTab = true, bool preserveUiState = true)
	{
		Stopwatch renderSw = Stopwatch.StartNew();
		if (preserveUiState)
		{
			Stopwatch captureSw = Stopwatch.StartNew();
			CaptureDashboardUiState();
			captureSw.Stop();
			if (!string.IsNullOrWhiteSpace(_lastDashboardUiStateJson))
			{
				WriteDashboardRuntimeDiagnostic("render-capture-ui-state:" + (_activeTab ?? "unknown"), _lastDashboardUiStateJson.Length, captureSw.ElapsedMilliseconds);
			}
		}
		else
		{
			_lastDashboardUiStateJson = string.Empty;
			WriteDashboardRuntimeDiagnostic("render-skip-ui-state:" + (_activeTab ?? "unknown"), -1, -1L);
		}
		if (preserveCurrentBrowserTab)
		{
			Stopwatch rememberSw = Stopwatch.StartNew();
			RememberActiveDashboardTab();
			rememberSw.Stop();
			WriteDashboardRuntimeDiagnostic("render-remember-tab:" + (_activeTab ?? "unknown"), -1, rememberSw.ElapsedMilliseconds);
		}
		if (IsStartupOverlayVisible())
		{
			UpdateStartupOverlayProgress(90, 100, T("Preparing dashboard HTML render...", "대시보드 HTML 렌더를 준비하는 중..."), forcePaint: true);
		}
		Stopwatch buildSw = Stopwatch.StartNew();
		string html = BuildDashboardHtml();
		buildSw.Stop();
		WriteDashboardRuntimeDiagnostic("render-build-html:" + (_activeTab ?? "unknown"), html.Length, buildSw.ElapsedMilliseconds);
		Stopwatch assignSw = Stopwatch.StartNew();
		if (IsStartupOverlayVisible())
		{
			_startupBrowserRenderPending = true;
			UpdateStartupOverlayProgress(96, 100, T("Passing dashboard HTML to the browser renderer...", "대시보드 HTML을 브라우저 렌더러에 전달하는 중..."), forcePaint: true);
		}
		_browser.DocumentText = html;
		assignSw.Stop();
		renderSw.Stop();
		WriteDashboardRuntimeDiagnostic("render-documenttext-set:" + (_activeTab ?? "unknown"), html.Length, assignSw.ElapsedMilliseconds);
		WriteDashboardRuntimeDiagnostic("render-total:" + (_activeTab ?? "unknown"), html.Length, renderSw.ElapsedMilliseconds);
	}

