	private void AppendActiveDashboardPane(StringBuilder sb, string activeTab, bool showAdminUi)
	{
		switch (NormalizeDashboardTabName(activeTab))
		{
		case "families":
			AppendFamilyPane(sb);
			break;
		case "systems":
			AppendSystemPane(sb);
			break;
		case "requests":
			AppendRequestPane(sb);
			break;
		case "audit":
			if (showAdminUi)
			{
				AppendAuditPane(sb);
			}
			else
			{
				AppendRequestPane(sb);
			}
			break;
		case "unregisteredfamilies":
			if (showAdminUi)
			{
				AppendUnregisteredFamilyPane(sb);
			}
			else
			{
				AppendFamilyPane(sb);
			}
			break;
		case "unregisteredsystems":
			if (showAdminUi)
			{
				AppendUnregisteredSystemPane(sb);
			}
			else
			{
				AppendSystemPane(sb);
			}
			break;
		case "permissions":
			if (showAdminUi)
			{
				AppendPermissionPane(sb);
			}
			else
			{
				AppendSettingsPane(sb);
			}
			break;
		case "admin":
			if (showAdminUi)
			{
				AppendAdminPane(sb);
			}
			else
			{
				AppendSettingsPane(sb);
			}
			break;
		case "help":
			if (showAdminUi)
			{
				AppendHelpPane(sb);
			}
			else
			{
				AppendSettingsPane(sb);
			}
			break;
		case "settings":
			AppendSettingsPane(sb);
			break;
		default:
			AppendFamilyPane(sb);
			break;
		}
	}

