		sb.AppendLine("<div class=\"preview-modal-head\"><span>" + Html(T("System Type Layers", "시스템 타입 레이어")) + "</span><a href=\"#\" onclick=\"return closeLayerModal()\" class=\"preview-modal-close\">" + Html(T("Close", "닫기")) + "</a></div>");
		sb.AppendLine("<div class=\"preview-modal-stage layer-modal-stage\" id=\"layerModalBody\"></div>");
		sb.AppendLine("</div></div>");
		sb.AppendLine("<div id=\"diffModalMask\" class=\"preview-modal-mask diff-modal-mask\" onclick=\"return closeDiffModalFromMask(event)\"><div class=\"preview-modal diff-modal\">");
		sb.AppendLine("<div class=\"preview-modal-head\"><span id=\"diffModalTitle\">" + Html(T("Fingerprint Difference Summary", "Fingerprint 차이 요약")) + "</span><a href=\"#\" onclick=\"return closeDiffModal()\" class=\"preview-modal-close\">" + Html(T("Close", "닫기")) + "</a></div>");
		sb.AppendLine("<div class=\"preview-modal-stage diff-modal-stage\" id=\"diffModalBody\"></div>");
		sb.AppendLine("</div></div>");
		sb.AppendLine("<div id=\"parameterModalMask\" class=\"preview-modal-mask parameter-modal-mask\" onclick=\"return closeParameterFormulaModalFromMask(event)\"><div class=\"preview-modal parameter-modal\">");
		sb.AppendLine("<div class=\"preview-modal-head\"><span id=\"parameterModalTitle\">" + Html(T("Parameter Formula Detail", "파라미터 Formula 상세보기")) + "</span><a href=\"#\" onclick=\"return closeParameterFormulaModal()\" class=\"preview-modal-close\">" + Html(T("Close", "닫기")) + "</a></div>");
		sb.AppendLine("<div class=\"preview-modal-stage parameter-modal-stage\" id=\"parameterModalBody\"></div>");
		sb.AppendLine("</div></div>");
	}

	private string BuildDashboardHtml()
	{
		Stopwatch buildSw = Stopwatch.StartNew();
		StringBuilder sb = new StringBuilder();
		Stopwatch permissionSw = Stopwatch.StartNew();
		DashboardPermissionSnapshot dashboardPermissionSnapshot = BuildDashboardPermissionSnapshot();
		bool canLoadFamilies = dashboardPermissionSnapshot.CanLoadFamilies;
		bool canApplySystems = dashboardPermissionSnapshot.CanApplySystems;
		bool canCreateRequest = dashboardPermissionSnapshot.CanCreateRequest;
		bool canSubmitRequest = dashboardPermissionSnapshot.CanSubmitRequest;
		bool canApproveRequest = dashboardPermissionSnapshot.CanApproveRequest;
		bool canViewAdmin = dashboardPermissionSnapshot.CanViewAdmin;
		permissionSw.Stop();
		bool showAdminUi = _adminModeEnabled;
		string initialTab = (_activeTab = ResolveInitialDashboardTab(showAdminUi, canViewAdmin));
		bool browserTabActive = IsBrowserDashboardTab(initialTab);
		WriteDashboardRuntimeDiagnostic("html-permissions:" + (initialTab ?? "unknown"), -1, permissionSw.ElapsedMilliseconds);
		string runtimeDebugInfo = BuildRuntimeDebugInfo();
		string runtimeDebugLogPath = DashboardRuntimeDiagnosticLogPath();
		sb.AppendLine("<!doctype html>");
		sb.AppendLine("<html>");
