		sb.AppendLine("var preview3dLabel='" + Js(T("Preview 3D", "3D 미리보기")) + "';var systemPreviewLabel='" + Js(T("System Type Review Data", "시스템 타입 검토 데이터")) + "';var noCachedSystemPreview='" + Js(T("System types are reviewed through parameters, routing rules, and dependent loadable families instead of a cached 3D image.", "시스템 타입은 캐시된 3D 이미지 대신 파라미터, 라우팅 규칙, 의존 로더블 패밀리 기준으로 검토합니다.")) + "';var previewImageDisplayFailed='" + Js(T("The PNG exists, but Revit's embedded browser could not display it.", "PNG 파일은 있지만 Revit 내장 브라우저가 표시하지 못했습니다.")) + "';var previewInlineLoadingLabel='" + Js(T("The PNG exists. Loading it through the inline preview fallback...", "PNG 파일은 있습니다. 내장 표시 방식으로 다시 불러오는 중입니다...")) + "';");
		sb.AppendLine("var detailFamilyLabel='" + Js(T("Loadable Family", "로더블 패밀리")) + "';var detailSystemLabel='" + Js(T("System Type", "시스템 타입")) + "';var detailModelLabel='" + Js(T("Model", "모델")) + "';var detailAnnotationLabel='" + Js(T("Annotation", "주석")) + "';var detailOtherLabel='" + Js(T("Other", "기타")) + "';");
		sb.AppendLine("var singleFamilyLabel='" + Js(T("Single Family", "단일 패밀리")) + "';var compositeFamilyLabel='" + Js(T("Composite Family", "복합 패밀리")) + "';var nestedChildrenLabel='" + Js(T("Nested families", "하위 패밀리")) + "';var noNestedChildrenLabel='" + Js(T("No nested loadable families.", "하위 로더블 패밀리 없음")) + "';var familyTypesLabel='" + Js(T("Family Types", "패밀리 타입")) + "';var typeNameLabel='" + Js(T("Type Name", "타입 이름")) + "';var noFamilyTypesLabel='" + Js(T("No captured type list.", "캡처된 타입 목록 없음")) + "';var previewOpenLabel='" + Js(T("Open large view", "크게 보기")) + "';");
		sb.AppendLine("var systemLayerTitle='" + Js(T("Layer Composition", "레이어 구성")) + "';var noSystemLayerLabel='" + Js(T("No layer composition data for this system type.", "이 시스템 타입에는 레이어 구성 데이터가 없습니다.")) + "';var layerIndexLabel='" + Js(T("No.", "번호")) + "';var layerFunctionLabel='" + Js(T("Function", "기능")) + "';var layerNameLabel='" + Js(T("Material / Name", "재료 / 이름")) + "';var layerThicknessLabel='" + Js(T("Thickness", "두께")) + "';var openLayerTableLabel='" + Js(T("Open large table", "표 크게 보기")) + "';");
		sb.AppendLine("var paramSharedLabel='" + Js(T("Shared", "공유")) + "';var paramFamilyLabel='" + Js(T("Family", "패밀리")) + "';var paramScopeFamilyLabel='" + Js(T("Family", "패밀리")) + "';var paramScopeInstanceLabel='" + Js(T("Instance", "인스턴스")) + "';var paramScopeTypeLabel='" + Js(T("Type", "타입")) + "';var paramNameLabel='" + Js(T("Name", "이름")) + "';var paramValueLabel='" + Js(T("Formula / Value", "수식 / 값")) + "';var paramKindLabel='" + Js(T("Kind", "구분")) + "';var paramScopeLabel='" + Js(T("Scope", "범위")) + "';var paramTypesLabel='" + Js(T("Types", "타입")) + "';var paramSampleTypeLabel='" + Js(T("Type sample", "타입 예시")) + "';var noParamDataLabel='" + Js(T("No captured shared parameter data.", "캡처된 공유 파라미터 데이터가 없습니다.")) + "';var moreParamsLabel='" + Js(T("more parameters", "개 추가 파라미터")) + "';var paramFormulaOpenLabel='" + Js(T("Formula Detail", "Formula 상세보기")) + "';var paramFormulaTitleLabel='" + Js(T("Parameter Formula Detail", "파라미터 Formula 상세보기")) + "';");
		sb.AppendLine("var diffTitleLabel='" + Js(T("Fingerprint Difference Summary", "Fingerprint 차이 요약")) + "';var diffAreaLabel='" + Js(T("Item", "항목")) + "';var diffStandardLabel='" + Js(T("Standard", "표준")) + "';var diffProjectLabel='" + Js(T("Current Project", "현재 프로젝트")) + "';var diffNoteLabel='" + Js(T("Difference", "차이")) + "';var diffOpenLabel='" + Js(T("Show Detail", "상세 보기")) + "';var diffCloseLabel='" + Js(T("Hide Detail", "접기")) + "';var diffCountUnitLabel='" + Js(T(" item", "개")) + "';");
		sb.AppendLine("var currentTab='" + Js(initialTab) + "';var currentFilter='All';var currentDiscipline='All';var currentTreeDiscipline='All';var currentTreeGroup='';var currentTreeCategory='';var currentSystemTreeDiscipline='All';var currentSystemTreeCategory='';var advStatus='All';var advGroup='All';var advCategory='';var advMismatchOnly=false;var expandedFamilyNodes={};var initialDashboardUiStateJson='" + Js(_lastDashboardUiStateJson) + "';");
		sb.AppendLine("var adminModeEnabled=" + (_adminModeEnabled ? "true" : "false") + ";var canLoadFamilies=" + (canLoadFamilies ? "true" : "false") + ";var canApplySystems=" + (canApplySystems ? "true" : "false") + ";var canCreateRequest=" + (canCreateRequest ? "true" : "false") + ";var canSubmitRequest=" + (canSubmitRequest ? "true" : "false") + ";var canApproveRequest=" + (canApproveRequest ? "true" : "false") + ";var canViewAdmin=" + (canViewAdmin ? "true" : "false") + ";var focusStandardRegistration=" + (_focusStandardRegistrationOnNextRender ? "true" : "false") + ";");
		sb.AppendLine("function disableLinks(match){var links=document.getElementsByTagName('a');for(var i=0;i<links.length;i++){var h=links[i].getAttribute('href')||'';if(h.indexOf(match)>=0){links[i].className=(links[i].className||'')+' disabled';links[i].title='" + Js(T("Not available for your current role.", "현재 역할에서는 사용할 수 없습니다.")) + "';links[i].removeAttribute('href');links[i].onclick=function(){return false;};}}}");
		sb.AppendLine("function hideTab(tab){var tabs=document.getElementsByName('dashTab');for(var i=0;i<tabs.length;i++){if(tabs[i].getAttribute('data-tab')==tab){tabs[i].style.display='none';}}}");
		sb.AppendLine("function applyPermissionUi(){if(!canLoadFamilies)disableLinks('kkyfb:sync-families');if(!canApplySystems)disableLinks('kkyfb:apply-systems');if(!canCreateRequest){disableLinks('kkyfb:request-new');disableLinks('kkyfb:request-family');disableLinks('kkyfb:request-system');disableLinks('kkyfb:request-update');}if(!canSubmitRequest)disableLinks('kkyfb:request-status/submitted');if(!canApproveRequest){disableLinks('kkyfb:request-status/reviewing');disableLinks('kkyfb:request-status/approved');disableLinks('kkyfb:request-status/rejected');disableLinks('kkyfb:request-status/completed');}if(!canViewAdmin)hideTab('admin');}");
		sb.AppendLine("function byId(id){return document.getElementById(id);}");
		sb.AppendLine("var fbDebugLines=['RUNTIME " + Js(runtimeDebugInfo) + "','HOST LOG " + Js(runtimeDebugLogPath) + "','TITLE " + Js(DashboardWindowTitle()) + "'];function fbTime(){var d=new Date();return ('0'+d.getHours()).slice(-2)+':'+('0'+d.getMinutes()).slice(-2)+':'+('0'+d.getSeconds()).slice(-2);}function fbLog(msg){try{var line=fbTime()+' '+msg;fbDebugLines.push(line);if(fbDebugLines.length>260)fbDebugLines.shift();var box=byId('fbDebugLog');if(box){box.innerText=fbDebugLines.join('\\n');box.scrollTop=box.scrollHeight;}}catch(ex){}}function fbErr(where,e){fbLog('ERROR '+where+': '+((e&&(e.message||e.description||e.number))||e));}function hasClass(e,c){return !!(e&&(' '+(e.className||'')+' ').indexOf(' '+c+' ')>=0);}");
		sb.AppendLine("fbLog('HOST html-ready');");
		sb.AppendLine("function paneState(id){var e=byId(id);if(!e)return id+': missing';return id+': style.display='+e.style.display+', offset='+e.offsetWidth+'x'+e.offsetHeight+', class='+(e.className||'');}function debugSnapshot(reason){try{fbLog('SNAPSHOT '+reason+' tab='+currentTab+' body='+(document.body?document.body.className:'no-body'));fbLog(paneState('mainCenter'));fbLog(paneState('selectionDetailPanel'));fbLog(paneState('browserSearch'));fbLog(paneState('familiesPane'));fbLog(paneState('systemsPane'));fbLog(paneState('requestsPane'));fbLog(paneState('auditPane'));fbLog(paneState('permissionsPane'));fbLog(paneState('adminPane'));fbLog(paneState('helpPane'));fbLog(paneState('settingsPane'));}catch(e){fbErr('debugSnapshot',e);}}");
		sb.AppendLine("function toggleDebug(){try{var b=document.body;if(!b)return false;var c=' '+(b.className||' ')+' ';if(c.indexOf(' fb-debug-on ')>=0){b.className=(b.className||'').replace(/(^|\\s)fb-debug-on(?=\\s|$)/g,' ').replace(/^\\s+|\\s+$/g,'').replace(/\\s+/g,' ');}else{b.className=((b.className||'')+' fb-debug-on').replace(/^\\s+|\\s+$/g,'').replace(/\\s+/g,' ');debugSnapshot('F12');}return false;}catch(e){return false;}}document.onkeydown=function(ev){ev=ev||window.event;var k=ev.keyCode||ev.which;if(k==123){toggleDebug();if(ev.preventDefault)ev.preventDefault();ev.returnValue=false;return false;}};window.onerror=function(msg,url,line){fbLog('JS ERROR line '+line+': '+msg);return false;};");
		sb.AppendLine("function showPane(id,on){var e=byId(id);if(e){e.style.display=on?'block':'none';fbLog('showPane '+id+'='+on);}else fbLog('showPane missing '+id);}");
		sb.AppendLine("function syncFixedHeaderScroll(wrap,headId){try{var h=byId(headId||(wrap?wrap.getAttribute('data-fixed-head')||'':''));if(h&&wrap)h.scrollLeft=wrap.scrollLeft||0;}catch(e){if(window.fbErr)fbErr('syncFixedHeaderScroll',e);}}");
		sb.AppendLine("function rowsFor(tab){var t=byId(tab+'Table');return t?t.getElementsByTagName('tr'):[];}");
		sb.AppendLine("function isBrowserTab(tab){return tab=='families'||tab=='systems';}");
		sb.AppendLine("function safeUi(name,fn){try{if(!fn){fn=name;name='anonymous';}if(fn)fn();}catch(e){fbErr(name,e);}}");
		sb.AppendLine("function scrollOf(id){var e=byId(id);return e?e.scrollTop:0;}function setScroll(id,value){var e=byId(id);if(e&&typeof value!='undefined')e.scrollTop=value||0;}function firstByClassName(cls){var all=document.getElementsByTagName('*');var needle=' '+cls+' ';for(var i=0;i<all.length;i++){if((' '+(all[i].className||' ')+' ').indexOf(needle)>=0)return all[i];}return null;}function currentSelectedRow(){var rows=rowsFor(currentTab);for(var i=0;i<rows.length;i++){if(rows[i].className.indexOf('data')>=0&&rows[i].className.indexOf('selected')>=0)return rows[i];}return null;}function rowState(row){if(!row)return null;return{discipline:row.getAttribute('data-discipline-key')||'',treeDiscipline:row.getAttribute('data-tree-discipline-key')||'',category:row.getAttribute('data-category')||'',name:row.getAttribute('data-name')||'',kind:row.getAttribute('data-kind')||'',raw:row.getAttribute('data-raw')||''};}");
		sb.AppendLine("function captureDashboardUiStateJson(){try{if(!window.JSON||!JSON.stringify)return'';var search=byId('searchBox');var tw=firstByClassName('family-tablewrap')||firstByClassName('tablewrap');var tree=firstByClassName('family-tree-panel');var center=byId('mainCenter');var detail=byId('selectionDetailPanel');var s={tab:currentTab||'families',search:search?search.value:'',currentFilter:currentFilter||'All',currentDiscipline:currentDiscipline||'All',currentTreeDiscipline:currentTreeDiscipline||'All',currentTreeGroup:currentTreeGroup||'',currentTreeCategory:currentTreeCategory||'',currentSystemTreeDiscipline:currentSystemTreeDiscipline||'All',currentSystemTreeCategory:currentSystemTreeCategory||'',advStatus:advStatus||'All',advGroup:advGroup||'All',advCategory:advCategory||'',advMismatchOnly:!!advMismatchOnly,expandedFamilyNodes:expandedFamilyNodes||{},selected:rowState(currentSelectedRow()),scroll:{table:tw?tw.scrollTop:0,tree:tree?tree.scrollTop:0,center:center?center.scrollTop:0,detail:detail?detail.scrollTop:0}};return JSON.stringify(s);}catch(e){if(window.fbErr)fbErr('captureDashboardUiStateJson',e);return'';}}");
		sb.AppendLine("function visibleDataRow(row){return row&&row.className.indexOf('data')>=0&&row.style.display!='none';}function familyRowCheck(row){if(!row)return null;var inputs=row.getElementsByTagName('input');for(var i=0;i<inputs.length;i++){if((' '+(inputs[i].className||' ')+' ').indexOf(' family-row-check ')>=0)return inputs[i];}return null;}function checkedFamilyRows(){var rows=rowsFor('families');var out=[];for(var i=0;i<rows.length;i++){var cb=familyRowCheck(rows[i]);if(cb&&cb.checked&&visibleDataRow(rows[i]))out.push(rows[i]);}return out;}function updateFamilySelectionControls(){var rows=rowsFor('families');var visible=0;var checked=0;for(var i=0;i<rows.length;i++){if(!visibleDataRow(rows[i]))continue;visible++;var cb=familyRowCheck(rows[i]);if(cb&&cb.checked)checked++;}var c=byId('selectedFamilyCount');if(c)c.innerText=checked;var all=byId('familyCheckAll');if(all){all.checked=(visible>0&&checked==visible);try{all.indeterminate=(checked>0&&checked<visible);}catch(e){}}var b=byId('checkedFamilyApply');if(b){var base=b.getAttribute('data-base-label')||b.innerText||'';b.innerText=base+(checked>0?' ('+checked+')':'');}}function toggleFamilyCheck(ev,cb){ev=ev||window.event;if(ev&&ev.stopPropagation)ev.stopPropagation();if(ev)ev.cancelBubble=true;updateFamilySelectionControls();return true;}function toggleAllFamilyChecks(ev,cb){ev=ev||window.event;if(ev&&ev.stopPropagation)ev.stopPropagation();if(ev)ev.cancelBubble=true;var rows=rowsFor('families');for(var i=0;i<rows.length;i++){if(!visibleDataRow(rows[i]))continue;var rcb=familyRowCheck(rows[i]);if(rcb)rcb.checked=!!cb.checked;}updateFamilySelectionControls();return true;}function clearFamilySelection(){var rows=rowsFor('families');for(var i=0;i<rows.length;i++){var cb=familyRowCheck(rows[i]);if(cb)cb.checked=false;if(rows[i].className.indexOf('data')>=0)rows[i].className=rows[i].className.replace(' selected','');}updateFamilySelectionControls();resetDetailForCurrentTab();return false;}function clearSystemSelection(){var rows=rowsFor('systems');for(var i=0;i<rows.length;i++){if(rows[i].className.indexOf('data')>=0)rows[i].className=rows[i].className.replace(' selected','');}resetDetailForCurrentTab();return false;}");
		sb.AppendLine("function systemRowCheck(row){if(!row)return null;var inputs=row.getElementsByTagName('input');for(var i=0;i<inputs.length;i++){if((' '+(inputs[i].className||' ')+' ').indexOf(' system-row-check ')>=0)return inputs[i];}return null;}function checkedSystemRows(){var rows=rowsFor('systems');var out=[];for(var i=0;i<rows.length;i++){var cb=systemRowCheck(rows[i]);if(cb&&cb.checked&&visibleDataRow(rows[i]))out.push(rows[i]);}return out;}function updateSystemSelectionControls(){var rows=rowsFor('systems');var visible=0;var checked=0;for(var i=0;i<rows.length;i++){if(!visibleDataRow(rows[i]))continue;visible++;var cb=systemRowCheck(rows[i]);if(cb&&cb.checked)checked++;}var c=byId('selectedSystemCount');if(c)c.innerText=checked;var all=byId('systemCheckAll');if(all){all.checked=(visible>0&&checked==visible);try{all.indeterminate=(checked>0&&checked<visible);}catch(e){}}var b=byId('checkedSystemApply');if(b){var base=b.getAttribute('data-base-label')||b.innerText||'';b.innerText=base+(checked>0?' ('+checked+')':'');}}function toggleSystemCheck(ev,cb){ev=ev||window.event;if(ev&&ev.stopPropagation)ev.stopPropagation();if(ev)ev.cancelBubble=true;updateSystemSelectionControls();return true;}function toggleAllSystemChecks(ev,cb){ev=ev||window.event;if(ev&&ev.stopPropagation)ev.stopPropagation();if(ev)ev.cancelBubble=true;var rows=rowsFor('systems');for(var i=0;i<rows.length;i++){if(!visibleDataRow(rows[i]))continue;var rcb=systemRowCheck(rows[i]);if(rcb)rcb.checked=!!cb.checked;}updateSystemSelectionControls();return true;}function clearSystemSelection(){var rows=rowsFor('systems');for(var i=0;i<rows.length;i++){var cb=systemRowCheck(rows[i]);if(cb)cb.checked=false;if(rows[i].className.indexOf('data')>=0)rows[i].className=rows[i].className.replace(' selected','');}updateSystemSelectionControls();resetDetailForCurrentTab();return false;}");
		sb.AppendLine("function normalizeStatusFilter(filter){filter=filter||'All';if(filter=='Blocked'||filter=='ManualReview'||filter=='ProjectOnly'||filter=='CategoryMismatch'||filter=='ReviewNeeded'||filter=='ApprovalRequired')return 'NeedsReview';return filter;}function statusFilterClass(e){return(e&&e.getAttribute('data-filter-class'))||'filter';}function setFilter(filter){currentFilter=normalizeStatusFilter(filter);var filters=document.getElementsByName('statusFilter');for(var i=0;i<filters.length;i++){filters[i].className=statusFilterClass(filters[i])+(filters[i].getAttribute('data-filter')==currentFilter?' active':'');}filterRows();return false;}");
		sb.AppendLine("function setDisciplineFilter(filter){currentDiscipline=filter;var filters=document.getElementsByName('disciplineFilter');for(var i=0;i<filters.length;i++){filters[i].className='filter discipline-filter'+(filters[i].getAttribute('data-discipline')==filter?' active':'');}filterRows();return false;}");
		sb.AppendLine("function textOf(v){return (v||'').toLowerCase();}");
		sb.AppendLine("var filterRowsTimer=null;function queueFilterRows(){try{if(filterRowsTimer)clearTimeout(filterRowsTimer);filterRowsTimer=setTimeout(function(){filterRowsTimer=null;filterRows();},25);}catch(e){filterRows();}return true;}");
		sb.AppendLine("function isUpdateStatus(s){return s=='UpdateAvailable'||s=='LoadedWithoutVersionStamp'||s=='StampNormalizationNeeded';}");
		sb.AppendLine("function isFingerprintDifferentStatus(s){return isUpdateStatus(s)||s=='DifferentFromStandard'||s=='LocallyModified'||s=='VersionConflict';}");
		sb.AppendLine("function isDuplicateRiskRow(row){var text=textOf((row.getAttribute('data-action')||'')+' '+(row.getAttribute('data-notes')||'')+' '+(row.getAttribute('data-changes')||''));return text.indexOf('duplicate')>=0||text.indexOf('중복')>=0;}");
		sb.AppendLine("function isCategoryMismatchRow(row){return (row.getAttribute('data-raw')||'')=='CategoryMismatch';}");
		sb.AppendLine("function isReviewStatus(s){return s=='Blocked'||s=='CategoryMismatch'||s=='ProjectOnly'||s=='ManualReview'||s=='ReviewNeeded'||s=='ApprovalRequired'||s=='DifferentFromStandard'||s=='LocallyModified'||s=='VersionConflict';}");
		sb.AppendLine("function statusMatches(row){if(currentFilter=='All')return true;var s=row.getAttribute('data-raw')||'';var g=row.getAttribute('data-group')||'';if(currentFilter=='ModelCategory')return g=='Model';if(currentFilter=='AnnotationCategory')return g=='Annotation';if(currentFilter=='DuplicateRisk')return isDuplicateRiskRow(row);if(currentFilter=='UpdateAvailable')return isUpdateStatus(s);if(currentFilter=='FingerprintDifferent')return isFingerprintDifferentStatus(s);if(currentFilter=='Latest')return s=='LoadedLatest'||s=='Latest'||s=='NoChange';if(currentFilter=='NeedsReview')return isReviewStatus(s);if(currentFilter=='Blocked')return s=='Blocked'||s=='DifferentFromStandard'||s=='LocallyModified'||s=='VersionConflict';if(currentFilter=='ManualReview')return s=='ManualReview'||s=='DifferentFromStandard'||s=='LocallyModified'||s=='VersionConflict'||s=='ApprovalRequired';return s==currentFilter;}");
		sb.AppendLine("function isMismatchStatus(s){return isFingerprintDifferentStatus(s)||s=='CategoryMismatch'||s=='ProjectOnly'||s=='ManualReview'||s=='ApprovalRequired';}");
		sb.AppendLine("function isMismatchCandidate(row){var s=row.getAttribute('data-raw')||'';return isMismatchStatus(s)||isDuplicateRiskRow(row);}");
		sb.AppendLine("function rowTreeDiscipline(row){return row.getAttribute('data-tree-discipline-key')||row.getAttribute('data-discipline-key')||'';}");
		sb.AppendLine("function disciplineMatches(row){return true;}");
		sb.AppendLine("function familyTreeMatches(row){if(currentTab!='families')return true;var d=rowTreeDiscipline(row);var g=row.getAttribute('data-group')||'';var c=row.getAttribute('data-category')||'';if(currentTreeDiscipline!='All'&&d!=currentTreeDiscipline)return false;if(currentTreeGroup!=''&&g!=currentTreeGroup)return false;if(currentTreeCategory!=''&&c!=currentTreeCategory)return false;return true;}");
		sb.AppendLine("function updateFamilyGroupToggleActive(){var toggles=document.getElementsByName('familyGroupToggle');for(var i=0;i<toggles.length;i++){var g=toggles[i].getAttribute('data-family-group')||'';toggles[i].className=(g==currentTreeGroup)?'active':'';}}");
		sb.AppendLine("function familyTreeKey(d,g){return (d||'All')+'||'+(g||'');}");
		sb.AppendLine("function ensureFamilyTreeSelectionVisible(){if(currentTreeDiscipline!='All'){expandedFamilyNodes[familyTreeKey(currentTreeDiscipline,'')]=true;if(currentTreeGroup!='')expandedFamilyNodes[familyTreeKey(currentTreeDiscipline,currentTreeGroup)]=true;}}");
		sb.AppendLine("function updateFamilyTreeExpanded(){var children=document.getElementsByName('familyTreeChildren');for(var i=0;i<children.length;i++){var key=children[i].getAttribute('data-family-tree-children')||'';children[i].style.display=expandedFamilyNodes[key]?'block':'none';}var toggles=document.getElementsByName('familyTreeToggle');for(var j=0;j<toggles.length;j++){var tkey=toggles[j].getAttribute('data-family-tree-toggle')||'';toggles[j].innerText=expandedFamilyNodes[tkey]?'-':'+';}}");
		sb.AppendLine("function updateFamilyTreeActive(){ensureFamilyTreeSelectionVisible();var nodes=document.getElementsByName('familyTreeNode');for(var i=0;i<nodes.length;i++){var d=nodes[i].getAttribute('data-tree-discipline')||'All';var g=nodes[i].getAttribute('data-tree-group')||'';var c=nodes[i].getAttribute('data-tree-category')||'';var base=nodes[i].getAttribute('data-base-class')||'tree-node';nodes[i].className=base+((d==currentTreeDiscipline&&g==currentTreeGroup&&c==currentTreeCategory)?' active':'');}updateFamilyTreeExpanded();updateFamilyGroupToggleActive();}");
		sb.AppendLine("function setTreeFilter(d,g,c){currentTreeDiscipline=d||'All';currentTreeGroup=g||'';currentTreeCategory=c||'';updateFamilyTreeActive();filterRows();return false;}");
		sb.AppendLine("function setFamilyGroupFilter(g){currentTreeGroup=g||'';currentTreeCategory='';updateFamilyTreeActive();filterRows();return false;}");
		sb.AppendLine("function toggleFamilyTree(d,g){var key=familyTreeKey(d,g);expandedFamilyNodes[key]=!expandedFamilyNodes[key];updateFamilyTreeExpanded();return false;}");
		sb.AppendLine("function systemTreeMatches(row){if(currentTab!='systems')return true;var d=rowTreeDiscipline(row);var c=row.getAttribute('data-category')||'';if(currentSystemTreeDiscipline!='All'&&d!=currentSystemTreeDiscipline)return false;if(currentSystemTreeCategory!=''&&c!=currentSystemTreeCategory)return false;return true;}");
		sb.AppendLine("function updateSystemTreeActive(){var nodes=document.getElementsByName('systemTreeNode');for(var i=0;i<nodes.length;i++){var d=nodes[i].getAttribute('data-system-tree-discipline')||'All';var c=nodes[i].getAttribute('data-system-tree-category')||'';var base=nodes[i].getAttribute('data-base-class')||'tree-node';nodes[i].className=base+((d==currentSystemTreeDiscipline&&c==currentSystemTreeCategory)?' active':'');}if(currentSystemTreeCategory!=''){var children=document.getElementsByName('systemTreeChildren');for(var j=0;j<children.length;j++){if((children[j].getAttribute('data-system-tree-children')||'')==currentSystemTreeDiscipline)children[j].style.display='block';}var toggles=document.getElementsByName('systemTreeToggle');for(var k=0;k<toggles.length;k++){if((toggles[k].getAttribute('data-system-tree-toggle')||'')==currentSystemTreeDiscipline)toggles[k].innerText='-';}}}");
		sb.AppendLine("function setSystemTreeFilter(d,c){currentSystemTreeDiscipline=d||'All';currentSystemTreeCategory=c||'';updateSystemTreeActive();filterRows();return false;}");
		sb.AppendLine("function toggleSystemTree(d){var key=d||'';var children=document.getElementsByName('systemTreeChildren');var expanded=false;for(var i=0;i<children.length;i++){if((children[i].getAttribute('data-system-tree-children')||'')==key){expanded=children[i].style.display!='block';children[i].style.display=expanded?'block':'none';}}var toggles=document.getElementsByName('systemTreeToggle');for(var j=0;j<toggles.length;j++){if((toggles[j].getAttribute('data-system-tree-toggle')||'')==key)toggles[j].innerText=expanded?'-':'+';}return false;}");
		sb.AppendLine("function advancedMatches(row){if(currentTab!='families'&&currentTab!='systems')return true;var s=row.getAttribute('data-raw')||'';var g=row.getAttribute('data-group')||'';var c=textOf(row.getAttribute('data-category')||'');if(advStatus!='All'){if(advStatus=='UpdateAvailable'){if(!isUpdateStatus(s))return false;}else if(advStatus=='FingerprintDifferent'){if(!isFingerprintDifferentStatus(s)&&!isDuplicateRiskRow(row))return false;}else if(advStatus=='DuplicateRisk'){if(!isDuplicateRiskRow(row))return false;}else if(advStatus=='Latest'){if(!(s=='LoadedLatest'||s=='Latest'||s=='NoChange'))return false;}else if(advStatus=='NeedsReview'){if(!isReviewStatus(s))return false;}else if(advStatus=='Blocked'){if(!(s=='Blocked'||s=='DifferentFromStandard'||s=='LocallyModified'||s=='VersionConflict'))return false;}else if(advStatus=='ManualReview'){if(!(s=='ManualReview'||s=='DifferentFromStandard'||s=='LocallyModified'||s=='VersionConflict'||s=='ApprovalRequired'))return false;}else if(s!=advStatus){return false;}}if(advGroup!='All'&&g!=advGroup)return false;if(advCategory!=''&&c.indexOf(textOf(advCategory))<0)return false;if(advMismatchOnly&&!isMismatchCandidate(row))return false;return true;}");
		sb.AppendLine("function filterRows(){var browserTab=(currentTab=='families'||currentTab=='systems');var search=byId('searchBox');var q=browserTab?textOf(search?search.value:''):'';var rows=rowsFor(currentTab);var first=null;var shown=0;for(var i=0;i<rows.length;i++){var r=rows[i];if(r.className.indexOf('data')<0)continue;var hay=textOf((r.getAttribute('data-discipline')||'')+' '+(r.getAttribute('data-group')||'')+' '+(r.getAttribute('data-kind')||'')+' '+(r.getAttribute('data-status')||'')+' '+(r.getAttribute('data-name')||'')+' '+(r.getAttribute('data-category')||'')+' '+(r.getAttribute('data-action')||'')+' '+(r.getAttribute('data-notes')||'')+' '+(r.getAttribute('data-approved')||'')+' '+(r.getAttribute('data-loaded')||'')+' '+(r.getAttribute('data-changes')||''));var ok=(q==''||hay.indexOf(q)>=0)&&statusMatches(r)&&disciplineMatches(r)&&familyTreeMatches(r)&&systemTreeMatches(r)&&advancedMatches(r);r.style.display=ok?'':'none';if(!ok&&currentTab=='families'){var cb=familyRowCheck(r);if(cb)cb.checked=false;}if(!ok&&currentTab=='systems'){var scb=systemRowCheck(r);if(scb)scb.checked=false;}if(ok){shown++;if(!first)first=r;}}var count=byId('visibleCount');if(count)count.innerText=shown+' '+visibleLabel;if(first)selectRow(first);else if(browserTab)resetDetailForCurrentTab();if(currentTab=='families')updateFamilySelectionControls();if(currentTab=='systems')updateSystemSelectionControls();}");
		sb.AppendLine("function openAdvancedFilter(){var m=byId('filterMask');if(m)m.style.display='block';return false;}");
		sb.AppendLine("function closeAdvancedFilter(){var m=byId('filterMask');if(m)m.style.display='none';return false;}");
		sb.AppendLine("function applyAdvancedFilter(){var s=byId('advStatus');var g=byId('advGroup');var c=byId('advCategory');var mm=byId('advMismatchOnly');advStatus=s?s.value:'All';advGroup=g?g.value:'All';advCategory=c?c.value:'';advMismatchOnly=mm?mm.checked:false;filterRows();return closeAdvancedFilter();}");
		sb.AppendLine("function resetAdvancedFilter(){var s=byId('advStatus');var g=byId('advGroup');var c=byId('advCategory');var mm=byId('advMismatchOnly');if(s)s.value='All';if(g)g.value='All';if(c)c.value='';if(mm)mm.checked=false;advStatus='All';advGroup='All';advCategory='';advMismatchOnly=false;filterRows();return false;}");
		sb.AppendLine("function escHtml(v){return (v||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/\"/g,'&quot;');}");
		sb.AppendLine("function splitDetailParts(v){v=v||'-';var parts=v.split('|');var out=[];for(var i=0;i<parts.length&&out.length<3;i++){var p=parts[i].replace(/^\\s+|\\s+$/g,'');if(p&&p!='-')out.push(p);}if(out.length==0)out.push(v);return out;}function compactDetailText(v){var out=splitDetailParts(v);return out.length?out.join(' · '):(v||'-');}function renderChangeSummary(v){var parts=splitDetailParts(v);var title=escHtml(v||'-');var html='<div class=\"change-list\" title=\"'+title+'\">';for(var i=0;i<3;i++){var text=parts[i]||'';html+='<div class=\"change-row\"><span class=\"change-index\">'+(text?(i+1):'')+'</span><span class=\"change-value\" title=\"'+escHtml(text)+'\">'+(text?escHtml(text):'&nbsp;')+'</span></div>';}return html+'</div>';}");
		sb.AppendLine("function parseFingerprintDiffRows(raw){raw=raw||'';var lines=raw.split(/\\r?\\n/);var rows=[];for(var i=0;i<lines.length;i++){var line=lines[i];if(!line)continue;var p=line.split('\\t');while(p.length<4)p.push('');rows.push({area:p[0]||'-',standard:p[1]||'-',project:p[2]||'-',note:p[3]||''});if(rows.length>=24)break;}return rows;}");
		sb.AppendLine("function diffCellHasValue(v){v=v||'';return v!=''&&v!='-';}function diffCellCount(v){v=v||'';var m=v.match(/(\\d+)\\s*(개|item)/i);if(m)return parseInt(m[1],10)||1;return diffCellHasValue(v)?1:0;}function fingerprintDiffRowCount(row){var s=diffCellCount(row.standard);var p=diffCellCount(row.project);if(s>0&&p>0&&s==1&&p==1)return 1;var total=s+p;return total>0?total:1;}");
		sb.AppendLine("function renderFingerprintDiffSummary(rows){var order=[];var map={};for(var i=0;i<rows.length;i++){var key=rows[i].area||'-';if(!map[key]){map[key]=0;order.push(key);}map[key]+=fingerprintDiffRowCount(rows[i]);}var html='';var limit=6;for(var j=0;j<order.length&&j<limit;j++){var k=order[j];html+='<span class=\"fingerprint-diff-chip\">'+escHtml(k)+' '+map[k]+escHtml(diffCountUnitLabel)+'</span>';}if(order.length>limit)html+='<span class=\"fingerprint-diff-chip\">+'+(order.length-limit)+'</span>';return html;}");
		sb.AppendLine("var fingerprintDiffStore={};var fingerprintDiffSeq=0;function storeFingerprintDiffRaw(raw){fingerprintDiffSeq++;var id='fd'+fingerprintDiffSeq;fingerprintDiffStore[id]=raw||'';return id;}");
		sb.AppendLine("function diffCellHtml(v){return escHtml(v||'').replace(/ \\[\\[BR\\]\\] /g,'<br/>').replace(/\\[\\[BR\\]\\]/g,'<br/>');}function diffCellTitle(v){return escHtml((v||'').replace(/ \\[\\[BR\\]\\] /g,'\\n').replace(/\\[\\[BR\\]\\]/g,'\\n'));}function sortFingerprintDiffRows(rows){try{rows.sort(function(a,b){var av=(a.area||'')+'|'+(a.standard||'')+'|'+(a.project||'')+'|'+(a.note||'');var bv=(b.area||'')+'|'+(b.standard||'')+'|'+(b.project||'')+'|'+(b.note||'');return av.localeCompare?av.localeCompare(bv):(av<bv?-1:(av>bv?1:0));});}catch(e){}return rows;}function renderFingerprintDiffDetailTable(rows){rows=sortFingerprintDiffRows(rows||[]);var html='<table class=\"fingerprint-diff-table\"><colgroup><col class=\"diff-area\"/><col class=\"diff-side\"/><col class=\"diff-side\"/><col class=\"diff-note\"/></colgroup><tr><th>'+escHtml(diffAreaLabel)+'</th><th>'+escHtml(diffStandardLabel)+'</th><th>'+escHtml(diffProjectLabel)+'</th><th>'+escHtml(diffNoteLabel)+'</th></tr>';for(var r=0;r<rows.length;r++){html+='<tr><td title=\"'+diffCellTitle(rows[r].area)+'\">'+diffCellHtml(rows[r].area)+'</td><td title=\"'+diffCellTitle(rows[r].standard)+'\">'+diffCellHtml(rows[r].standard)+'</td><td title=\"'+diffCellTitle(rows[r].project)+'\">'+diffCellHtml(rows[r].project)+'</td><td title=\"'+diffCellTitle(rows[r].note)+'\">'+diffCellHtml(rows[r].note)+'</td></tr>';}return html+'</table>';}");
		sb.AppendLine("function openFingerprintDiffModal(raw){var mask=byId('diffModalMask');var body=byId('diffModalBody');if(!mask||!body)return false;var rows=parseFingerprintDiffRows(raw);body.innerHTML=rows.length?renderFingerprintDiffDetailTable(rows):'<div class=\"diff-modal-empty\">-</div>';mask.style.display='block';return false;}function openStoredFingerprintDiff(id){return openFingerprintDiffModal(fingerprintDiffStore[id]||'');}function closeDiffModal(){var mask=byId('diffModalMask');var body=byId('diffModalBody');if(mask)mask.style.display='none';if(body)body.innerHTML='';return false;}function closeDiffModalFromMask(ev){ev=ev||window.event;var t=ev.target||ev.srcElement;if(t&&t.id=='diffModalMask')return closeDiffModal();return false;}function toggleFingerprintDiff(link){var id=link?link.getAttribute('data-diffid'):'';return openStoredFingerprintDiff(id);}");
		sb.AppendLine("function renderFingerprintDiffTable(raw){var rows=parseFingerprintDiffRows(raw);if(rows.length==0)return '';var id=storeFingerprintDiffRaw(raw);return '<div class=\"fingerprint-diff-wrap\"><div class=\"fingerprint-diff-head\"><span class=\"fingerprint-diff-title\">'+escHtml(diffTitleLabel)+'</span><a href=\"#\" class=\"fingerprint-diff-toggle\" data-diffid=\"'+escHtml(id)+'\" onclick=\"return toggleFingerprintDiff(this)\">'+escHtml(diffOpenLabel)+'</a></div><div class=\"fingerprint-diff-summary\">'+renderFingerprintDiffSummary(rows)+'</div></div>';}");
		sb.AppendLine("function basisCard(tone,title,desc){var icon=tone=='good'?'✓':(tone=='bad'?'!':'?');return '<div class=\"basis-card '+tone+'\"><span class=\"basis-icon\">'+icon+'</span><span class=\"basis-body\"><span class=\"basis-title\">'+escHtml(title)+'</span>'+(desc?'<span class=\"basis-desc\">'+escHtml(desc)+'</span>':'')+'</span></div>';}");
		sb.AppendLine("function isBasisMatch(raw,notes,changes){var r=(raw||'').toLowerCase();var n=(notes||'').toLowerCase();var c=(changes||'').toLowerCase();return r=='loadedlatest'||r=='latest'||r=='nochange'||n.indexOf('기준 일치')>=0||n.indexOf('프로젝트 내용이 현재 표준 스냅샷 및 추적 승인 스탬프와 일치')>=0||n.indexOf('현재 프로젝트 내용이 현재 표준 스냅샷 및 추적 승인 스탬프와 일치')>=0||n.indexOf('matches the current standard snapshot and tracked approval stamp')>=0||c.indexOf('기준 일치')>=0;}");
		sb.AppendLine("function renderBasisMemo(row){var raw=row.getAttribute('data-raw')||'';var notes=row.getAttribute('data-notes')||'';var changes=row.getAttribute('data-changes')||'';var diff=renderFingerprintDiffTable(row.getAttribute('data-diffrows')||'');if(isDuplicateRiskRow(row)){var dupDesc=compactDetailText(changes!='-'?changes:notes);return basisCard('warn','" + Js(T("Duplicate Risk", "중복 위험")) + "',dupDesc||'" + Js(T("Duplicate cleanup or consolidation is required before applying.", "적용 전에 중복 정리 또는 통합 검토가 필요합니다.")) + "')+diff;}if(isBasisMatch(raw,notes,changes))return basisCard('good','" + Js(T("Basis Match", "기준 일치")) + "','')+diff;var r=raw.toLowerCase();var desc=compactDetailText(changes!='-'?changes:notes);if(r=='loadavailable')return basisCard('info','" + Js(T("Load Available", "로드 가능")) + "','" + Js(T("Not loaded in this project.", "현재 프로젝트에 로드되지 않음")) + "')+diff;else if(r=='skippedmissing'||r=='skipped')return basisCard('info','" + Js(T("Skipped", "건너뜀")) + "','" + Js(T("Missing items are left uncreated; only existing project content is updated.", "누락 항목은 새로 만들지 않고 현재 프로젝트에 이미 있는 항목만 갱신합니다.")) + "')+diff;else if(r=='projectonly')desc='" + Js(T("Not found in the registered standard.", "등록된 표준에 없음")) + "';else if(r=='categorymismatch')desc=desc||'" + Js(T("Family name matches, but category differs.", "패밀리명은 같지만 카테고리가 다름")) + "';else if(r=='updateavailable'||r=='differentfromstandard'||r=='locallymodified'||r=='versionconflict')desc=desc||'" + Js(T("Fingerprint differs from the standard.", "Fingerprint가 표준과 다름")) + "';else if(r=='loadedwithoutversionstamp'||r=='stampnormalizationneeded'){desc=desc||'" + Js(T("Content is close to the standard, but the approval stamp needs refresh.", "내용은 표준 기준에 가깝지만 승인 스탬프 갱신이 필요합니다.")) + "';return basisCard('warn','" + Js(T("Tracking Needs Refresh", "추적 갱신 필요")) + "',desc)+diff;}return basisCard('bad','" + Js(T("Basis Mismatch", "기준 불일치")) + "',desc)+diff;}");
		sb.AppendLine("function isBasisDescNoise(v){var s=textOf(v||'').replace(/^\\s+|\\s+$/g,'');if(!s||s=='-')return true;return s=='fingerprint differs'||s=='fingerprint 불일치'||s=='fingerprint가 표준과 다름'||s=='system type fingerprint differs'||s.indexOf('fingerprint differs from the standard')>=0||s.indexOf('signature differs')>=0||s.indexOf('signature 차이')>=0||s.indexOf('signature 원문')>=0||s.indexOf('stored fingerprint')>=0||s.indexOf('저장된 fingerprint')>=0||s.indexOf('stored hash differs')>=0||s.indexOf('해시 다름')>=0||s.indexOf('contentfingerprint')>=0||s.indexOf('fingerprint는 다르지만')>=0;}");
		sb.AppendLine("function compactBasisDetailText(v){var raw=v||'';var parts=raw.split('|');var out=[];for(var i=0;i<parts.length&&out.length<3;i++){var p=(parts[i]||'').replace(/^\\s+|\\s+$/g,'');if(p&&!isBasisDescNoise(p))out.push(p);}return out.join(' · ');}");
		sb.AppendLine("function renderBasisMemo(row){var raw=row.getAttribute('data-raw')||'';var notes=row.getAttribute('data-notes')||'';var changes=row.getAttribute('data-changes')||'';var diff=renderFingerprintDiffTable(row.getAttribute('data-diffrows')||'');var source=(changes&&changes!='-')?changes:notes;if(isDuplicateRiskRow(row)){var dupDesc=compactBasisDetailText(source);return basisCard('warn','" + Js(T("Duplicate Risk", "중복 위험")) + "',dupDesc||'" + Js(T("Duplicate cleanup or consolidation is required before applying.", "적용 전에 중복 정리 또는 통합 검토가 필요합니다.")) + "')+diff;}if(isBasisMatch(raw,notes,changes))return basisCard('good','" + Js(T("Basis Match", "기준 일치")) + "','')+diff;var r=raw.toLowerCase();var desc=compactBasisDetailText(source);if(r=='loadavailable')return basisCard('info','" + Js(T("Load Available", "로드 가능")) + "','" + Js(T("Not loaded in this project.", "현재 프로젝트에 로드되지 않음")) + "')+diff;else if(r=='skippedmissing'||r=='skipped')return basisCard('info','" + Js(T("Skipped", "건너뜀")) + "','" + Js(T("Missing items are left uncreated; only existing project content is updated.", "누락 항목은 새로 만들지 않고 현재 프로젝트에 이미 있는 항목만 갱신합니다.")) + "')+diff;else if(r=='projectonly')desc='" + Js(T("Not found in the registered standard.", "등록된 표준에 없음")) + "';else if(r=='categorymismatch')desc=desc||'" + Js(T("Family name matches, but category differs.", "패밀리명은 같지만 카테고리가 다름")) + "';else if(r=='loadedwithoutversionstamp'||r=='stampnormalizationneeded'){desc=desc||'" + Js(T("Content is close to the standard, but the approval stamp needs refresh.", "내용은 표준 기준에 가깝지만 승인 스탬프 갱신이 필요합니다.")) + "';return basisCard('warn','" + Js(T("Tracking Needs Refresh", "추적 갱신 필요")) + "',desc)+diff;}return basisCard('bad','" + Js(T("Basis Mismatch", "기준 불일치")) + "',desc)+diff;}");
		sb.AppendLine("function trimParam(v){return (v||'').replace(/^\\s+|\\s+$/g,'');}function clipParam(v,max){v=v||'-';return v.length>max?v.substring(0,max-3)+'...':v;}function parseParameterPreview(raw){var info={typeCount:'',sample:'',rows:[],message:''};raw=raw||'';if(!raw){info.message=noParamDataLabel;return info;}var lines=raw.split(/\\r?\\n/);var scope='';for(var i=0;i<lines.length;i++){var line=trimParam(lines[i]);if(!line)continue;var low=line.toLowerCase();if(low.indexOf('no standard snapshot')>=0||low.indexOf('no cached parameter')>=0||low.indexOf('no captured shared')>=0){info.message=line;continue;}if(low.indexOf('types:')==0){info.typeCount=trimParam(line.substring(line.indexOf(':')+1));continue;}if(low.indexOf('family parameters')>=0){scope=paramScopeFamilyLabel;continue;}if(low.indexOf('instance parameters')>=0){scope=paramScopeInstanceLabel;continue;}if(low.indexOf('type parameters:')>=0){scope=paramScopeTypeLabel;info.sample=trimParam(line.substring(line.indexOf(':')+1));continue;}if(line.charAt(0)=='-'){var entry=trimParam(line.substring(1));var shared=entry.toLowerCase().indexOf('[shared]')>=0;var instance=entry.toLowerCase().indexOf('[instance]')>=0;entry=trimParam(entry.replace(/\\s*\\[shared\\]\\s*/ig,'').replace(/\\s*\\[instance\\]\\s*/ig,''));if(instance)scope=paramScopeInstanceLabel;var idx=entry.indexOf(':');var name=trimParam(idx>=0?entry.substring(0,idx):entry);var value=trimParam(idx>=0?entry.substring(idx+1):'');if(name)info.rows.push({kind:shared?paramSharedLabel:paramFamilyLabel,kindClass:shared?'shared':'family',scope:scope||'-',name:name,value:value||'-'});}}return info;}function renderParameterTable(raw){var info=parseParameterPreview(raw);if(info.rows.length==0)return '<div class=\"parameter-empty\">'+escHtml(info.message||noParamDataLabel)+'</div>';var shared=0;var family=0;for(var i=0;i<info.rows.length;i++){if(info.rows[i].kindClass=='shared')shared++;else family++;}var summary=[];if(info.typeCount)summary.push(paramTypesLabel+': '+info.typeCount);summary.push(paramSharedLabel+': '+shared);if(info.sample)summary.push(paramSampleTypeLabel+': '+clipParam(info.sample,24));var html='<div class=\"parameter-summary\">'+escHtml(summary.join(' · '))+'</div><table class=\"parameter-table\"><tr><th>'+escHtml(paramKindLabel)+'</th><th>'+escHtml(paramScopeLabel)+'</th><th>'+escHtml(paramNameLabel)+'</th><th>'+escHtml(paramValueLabel)+'</th></tr>';var limit=14;for(var r=0;r<info.rows.length&&r<limit;r++){var item=info.rows[r];html+='<tr><td><span class=\"parameter-kind '+item.kindClass+'\">'+escHtml(item.kind)+'</span></td><td title=\"'+escHtml(item.scope)+'\">'+escHtml(clipParam(item.scope,16))+'</td><td title=\"'+escHtml(item.name)+'\">'+escHtml(clipParam(item.name,34))+'</td><td title=\"'+escHtml(item.value)+'\">'+escHtml(clipParam(item.value,36))+'</td></tr>';}if(info.rows.length>limit)html+='<tr><td colspan=\"4\" class=\"parameter-more\">+'+(info.rows.length-limit)+' '+escHtml(moreParamsLabel)+'</td></tr>';return html+'</table>';}function updateParameterDetail(row){var block=byId('detailParameterBlock');var target=byId('detailParameters');if(!block||!target)return;if(currentTab!='families'||!adminModeEnabled){target.innerHTML='-';block.style.display='none';return;}target.innerHTML=renderParameterTable(row.getAttribute('data-parameters')||'');block.style.display='block';}");
		sb.AppendLine("function parseParameterPreview(raw){var info={typeCount:'',sample:'',rows:[],message:''};raw=raw||'';if(!raw){info.message=noParamDataLabel;return info;}var lines=raw.split(/\\r?\\n/);var scope='';for(var i=0;i<lines.length;i++){var line=trimParam(lines[i]);if(!line)continue;var low=line.toLowerCase();var colon=line.indexOf(':');if(low.indexOf('no standard snapshot')>=0||low.indexOf('no cached parameter')>=0||low.indexOf('no captured shared')>=0||line.indexOf('표준 스냅샷 파라미터 데이터')>=0||line.indexOf('캡처된 공유 파라미터 데이터')>=0||line.indexOf('공유 파라미터 데이터가 없습니다')>=0){info.message=line;continue;}if(low.indexOf('types:')==0||line.indexOf('타입 수:')==0){info.typeCount=trimParam(colon>=0?line.substring(colon+1):'');continue;}if(low.indexOf('family parameters')>=0||line.indexOf('패밀리 파라미터')>=0){scope=paramScopeFamilyLabel;continue;}if(low.indexOf('instance parameters')>=0||line.indexOf('인스턴스 파라미터')>=0){scope=paramScopeInstanceLabel;continue;}if(low.indexOf('type parameters:')>=0||line.indexOf('타입 파라미터:')>=0){scope=paramScopeTypeLabel;info.sample=trimParam(colon>=0?line.substring(colon+1):'');continue;}if(line.charAt(0)=='-'||line.charAt(0)=='·'){var entry=trimParam(line.substring(1));var entryLow=entry.toLowerCase();var shared=entryLow.indexOf('[shared]')>=0||entry.indexOf('[공유]')>=0;var instance=entryLow.indexOf('[instance]')>=0||entry.indexOf('[인스턴스]')>=0;entry=trimParam(entry.replace(/\\s*\\[shared\\]\\s*/ig,'').replace(/\\s*\\[instance\\]\\s*/ig,'').replace(/\\s*\\[공유\\]\\s*/g,'').replace(/\\s*\\[인스턴스\\]\\s*/g,''));if(instance)scope=paramScopeInstanceLabel;var idx=entry.indexOf(':');var name=trimParam(idx>=0?entry.substring(0,idx):entry);var value=trimParam(idx>=0?entry.substring(idx+1):'');if(name)info.rows.push({kind:shared?paramSharedLabel:paramFamilyLabel,kindClass:shared?'shared':'family',scope:scope||'-',name:name,value:value||'-'});}}return info;}function renderParameterTable(raw){var info=parseParameterPreview(raw);if(info.rows.length==0)return '<div class=\"parameter-empty\">'+escHtml(info.message||noParamDataLabel)+'</div>';var shared=0;for(var i=0;i<info.rows.length;i++){if(info.rows[i].kindClass=='shared')shared++;}var summary=[];if(info.typeCount)summary.push(paramTypesLabel+': '+info.typeCount);summary.push(paramSharedLabel+': '+shared);if(info.sample)summary.push(paramSampleTypeLabel+': '+clipParam(info.sample,32));var html='<div class=\"parameter-summary\">'+escHtml(summary.join(' · '))+'</div><table class=\"parameter-table\"><tr><th>'+escHtml(paramKindLabel)+'</th><th>'+escHtml(paramScopeLabel)+'</th><th>'+escHtml(paramNameLabel)+'</th><th>'+escHtml(paramValueLabel)+'</th></tr>';var limit=18;for(var r=0;r<info.rows.length&&r<limit;r++){var item=info.rows[r];html+='<tr><td><span class=\"parameter-kind '+item.kindClass+'\">'+escHtml(item.kind)+'</span></td><td title=\"'+escHtml(item.scope)+'\">'+escHtml(clipParam(item.scope,18))+'</td><td title=\"'+escHtml(item.name)+'\">'+escHtml(clipParam(item.name,40))+'</td><td title=\"'+escHtml(item.value)+'\">'+escHtml(clipParam(item.value,42))+'</td></tr>';}if(info.rows.length>limit)html+='<tr><td colspan=\"4\" class=\"parameter-more\">+'+(info.rows.length-limit)+' '+escHtml(moreParamsLabel)+'</td></tr>';return html+'</table>';}");
		sb.AppendLine("function renderParameterFallback(raw){raw=raw||'';if(!raw)return '<div class=\"parameter-empty\">'+escHtml(noParamDataLabel)+'</div>';return '<div class=\"parameter-raw\">'+escHtml(raw).replace(/\\r?\\n/g,'<br/>')+'</div>';}function updateParameterDetail(row){var block=byId('detailParameterBlock');var target=byId('detailParameters');if(!block||!target)return;if(currentTab!='families'){target.innerHTML='-';block.style.display='none';return;}var raw=row.getAttribute('data-parameters')||'';try{var html=renderParameterTable(raw);if(!html||html.replace(/<[^>]*>/g,'').replace(/^\\s+|\\s+$/g,'')=='')html=renderParameterFallback(raw);target.innerHTML=html;}catch(e){if(window.fbErr)fbErr('updateParameterDetail',e);target.innerHTML=renderParameterFallback(raw);}block.style.display='block';}");
		sb.AppendLine("var parameterFormulaStore={};var parameterFormulaSeq=0;function storeParameterFormulaRaw(raw){parameterFormulaSeq++;var id='pf'+parameterFormulaSeq;parameterFormulaStore[id]=raw||'';return id;}");
		sb.AppendLine("function renderParameterFormulaDetailTable(info){var html='<div class=\"parameter-table-scroll\"><table class=\"parameter-table\"><colgroup><col class=\"parameter-kind-col\"/><col class=\"parameter-scope-col\"/><col class=\"parameter-name-col\"/><col class=\"parameter-value-col\"/></colgroup><tr><th>'+escHtml(paramKindLabel)+'</th><th>'+escHtml(paramScopeLabel)+'</th><th>'+escHtml(paramNameLabel)+'</th><th>'+escHtml(paramValueLabel)+'</th></tr>';for(var r=0;r<info.rows.length;r++){var item=info.rows[r];html+='<tr><td><span class=\"parameter-kind '+item.kindClass+'\">'+escHtml(item.kind)+'</span></td><td title=\"'+escHtml(item.scope)+'\">'+escHtml(item.scope)+'</td><td class=\"parameter-name-cell\" title=\"'+escHtml(item.name)+'\">'+escHtml(item.name)+'</td><td class=\"parameter-value-cell\" title=\"'+escHtml(item.value)+'\">'+escHtml(item.value)+'</td></tr>';}return html+'</table></div>';}");
		sb.AppendLine("function openParameterFormulaModal(raw){var mask=byId('parameterModalMask');var body=byId('parameterModalBody');if(!mask||!body)return false;var info=parseParameterPreview(raw);body.innerHTML=info.rows.length?renderParameterFormulaDetailTable(info):'<div class=\"parameter-modal-empty\">'+escHtml(info.message||noParamDataLabel)+'</div>';mask.style.display='block';return false;}function openStoredParameterFormula(id){return openParameterFormulaModal(parameterFormulaStore[id]||'');}function closeParameterFormulaModal(){var mask=byId('parameterModalMask');var body=byId('parameterModalBody');if(mask)mask.style.display='none';if(body)body.innerHTML='';return false;}function closeParameterFormulaModalFromMask(ev){ev=ev||window.event;var t=ev.target||ev.srcElement;if(t&&t.id=='parameterModalMask')return closeParameterFormulaModal();return false;}");
