		sb.AppendLine("var previewModalDefaultZoom=0.75;var previewModalZoom=previewModalDefaultZoom;var previewModalAutoLabel='" + Js(T("Auto", "자동")) + "';function renderPreviewFallback(title,detail){var html='<div class=\"preview-diagnostic\"><strong>'+escHtml(title)+'</strong>';if(detail)html+='<div>'+escHtml(detail).replace(/\\r?\\n/g,'<br/>')+'</div>';return html+'</div>';}function findPreviewImageWrap(node){while(node&&node.nodeType==1){if((' '+(node.className||'')+' ').indexOf(' preview-image-wrap ')>=0)return node;node=node.parentNode;}return null;}function requestInlinePreview(path,detail){try{if(!path)return false;var preview=byId('preview');if(preview)preview.innerHTML=renderPreviewFallback(preview3dLabel,previewInlineLoadingLabel);window.location='kkyfb:preview-inline/'+encodeURIComponent(path);return true;}catch(e){return false;}}function showPreviewImageError(img){var d=img.getAttribute('data-diag')||'';var path=img.getAttribute('data-path')||'';if(path&&img.getAttribute('data-inline-requested')!='1'){img.setAttribute('data-inline-requested','1');if(requestInlinePreview(path,d))return;}var wrap=findPreviewImageWrap(img);if(wrap)wrap.innerHTML=renderPreviewFallback(noCachedPreview,d||previewImageDisplayFailed);}function applyInlinePreviewDataUri(src,diag){var preview=byId('preview');if(preview)preview.innerHTML=renderPreviewImage(src,diag||previewImageDisplayFailed,'');return true;}function showInlinePreviewFailure(detail){var preview=byId('preview');if(preview)preview.innerHTML=renderPreviewFallback(noCachedPreview,detail||previewImageDisplayFailed);return true;}");
		sb.AppendLine("function fitPreviewImage(img){try{if(!img)return false;var wrap=findPreviewImageWrap(img);if(!wrap)return false;var boxW=wrap.clientWidth||wrap.offsetWidth||0;var boxH=wrap.clientHeight||wrap.offsetHeight||0;if(boxW<=0||boxH<=0){var preview=byId('preview');if(preview){boxW=preview.clientWidth||preview.offsetWidth||0;boxH=preview.clientHeight||preview.offsetHeight||0;}}if(boxW<=0||boxH<=0){setTimeout(function(){fitPreviewImage(img);},80);return false;}var nw=img.naturalWidth||0;var nh=img.naturalHeight||0;if((nw<=0||nh<=0)&&img.getAttribute('data-natural-w')){nw=parseInt(img.getAttribute('data-natural-w'),10)||0;nh=parseInt(img.getAttribute('data-natural-h'),10)||0;}if(nw<=0||nh<=0){nw=img.width||img.offsetWidth||0;nh=img.height||img.offsetHeight||0;}if(nw<=0||nh<=0)return false;img.setAttribute('data-natural-w',nw);img.setAttribute('data-natural-h',nh);var scale=Math.min(boxW/nw,boxH/nh);if(!isFinite(scale)||scale<=0)scale=1;if(scale>1)scale=1;var w=Math.max(1,Math.floor(nw*scale));var h=Math.max(1,Math.floor(nh*scale));img.style.width=w+'px';img.style.height=h+'px';img.style.maxWidth='none';img.style.maxHeight='none';img.style.left='50%';img.style.top='50%';img.style.margin='0';img.style.position='absolute';img.style.display='block';img.style.transform='translate(-50%,-50%)';return true;}catch(e){return false;}}function fitVisiblePreviewImages(){try{var preview=byId('preview');if(!preview)return;var imgs=preview.getElementsByTagName('img');for(var i=0;i<imgs.length;i++)fitPreviewImage(imgs[i]);}catch(e){}}");
		sb.AppendLine("function centerPreviewModalImage(){try{var stage=byId('previewModalStage');var canvas=byId('previewModalCanvas');if(!stage)return;var sw=(canvas&&canvas.offsetWidth)?canvas.offsetWidth:stage.scrollWidth;var sh=(canvas&&canvas.offsetHeight)?canvas.offsetHeight:stage.scrollHeight;stage.scrollLeft=Math.max(0,Math.round((sw-(stage.clientWidth||0))/2));stage.scrollTop=Math.max(0,Math.round((sh-(stage.clientHeight||0))/2));}catch(e){}}");
		sb.AppendLine("function previewModalNaturalSize(img){var w=(img&&img.naturalWidth)||0;var h=(img&&img.naturalHeight)||0;if((w<=0||h<=0)&&img){w=parseInt(img.getAttribute('data-natural-w'),10)||0;h=parseInt(img.getAttribute('data-natural-h'),10)||0;}if((w<=0||h<=0)&&img){w=img.width||img.offsetWidth||0;h=img.height||img.offsetHeight||0;}if(img&&w>0&&h>0){img.setAttribute('data-natural-w',w);img.setAttribute('data-natural-h',h);}return{w:w,h:h};}function computePreviewModalFitZoom(){var stage=byId('previewModalStage');var img=byId('previewModalImage');var s=previewModalNaturalSize(img);if(!stage||!img||s.w<=0||s.h<=0)return previewModalDefaultZoom;var boxW=Math.max(1,(stage.clientWidth||stage.offsetWidth||1)-56);var boxH=Math.max(1,(stage.clientHeight||stage.offsetHeight||1)-56);var z=Math.min(boxW/s.w,boxH/s.h);if(!isFinite(z)||z<=0)z=previewModalDefaultZoom;if(z>1)z=1;if(z<0.25)z=0.25;return z;}function updatePreviewModalZoom(autoLabel){var stage=byId('previewModalStage');var canvas=byId('previewModalCanvas');var img=byId('previewModalImage');var label=byId('previewZoomLabel');if(img){var s=previewModalNaturalSize(img);if(s.w>0&&s.h>0){var w=Math.max(1,Math.round(s.w*previewModalZoom));var h=Math.max(1,Math.round(s.h*previewModalZoom));var pad=56;var stageW=stage?(stage.clientWidth||stage.offsetWidth||1):1;var stageH=stage?(stage.clientHeight||stage.offsetHeight||1):1;var canvasW=Math.max(stageW,w+pad);var canvasH=Math.max(stageH,h+pad);if(canvas){canvas.style.width=canvasW+'px';canvas.style.height=canvasH+'px';}img.style.width=w+'px';img.style.height=h+'px';img.style.left=Math.max(0,Math.round((canvasW-w)/2))+'px';img.style.top=Math.max(0,Math.round((canvasH-h)/2))+'px';}else{img.style.width=Math.round(previewModalZoom*100)+'%';img.style.height='auto';}}if(label)label.innerText=(autoLabel?previewModalAutoLabel+' ':'')+Math.round(previewModalZoom*100)+'%';setTimeout(centerPreviewModalImage,0);}");
		sb.AppendLine("function openPreviewModal(src,diag){var mask=byId('previewModalMask');var img=byId('previewModalImage');if(!mask||!img||!src)return false;previewModalZoom=previewModalDefaultZoom;img.onload=function(){previewModalZoom=computePreviewModalFitZoom();updatePreviewModalZoom(true);centerPreviewModalImage();};img.src=src;img.title=diag||'';mask.style.display='block';updatePreviewModalZoom(true);setTimeout(function(){previewModalZoom=computePreviewModalFitZoom();updatePreviewModalZoom(true);centerPreviewModalImage();},80);return false;}function closePreviewModal(){var mask=byId('previewModalMask');var img=byId('previewModalImage');if(mask)mask.style.display='none';if(img){img.onload=null;img.removeAttribute('src');}return false;}function closePreviewModalFromMask(ev){ev=ev||window.event;var t=ev.target||ev.srcElement;if(t&&t.id=='previewModalMask')return closePreviewModal();return false;}function zoomPreviewModal(delta){previewModalZoom+=delta;if(previewModalZoom<0.25)previewModalZoom=0.25;if(previewModalZoom>4)previewModalZoom=4;updatePreviewModalZoom(false);return false;}function resetPreviewModalZoom(){previewModalZoom=computePreviewModalFitZoom();updatePreviewModalZoom(true);return false;}function renderPreviewImage(p,d,path){var diag=escHtml(d||previewImageDisplayFailed);var src=escHtml(p||'');var rawPath=escHtml(path||'');setTimeout(fitVisiblePreviewImages,25);return '<div class=\"preview-image-wrap\"><span class=\"preview-image-cell\"><img class=\"preview-fit-image\" src=\"'+src+'\" data-src=\"'+src+'\" data-path=\"'+rawPath+'\" data-diag=\"'+diag+'\" onclick=\"openPreviewModal(this.getAttribute(\\'data-src\\'),this.getAttribute(\\'data-diag\\'));return false;\" onload=\"fitPreviewImage(this)\" onerror=\"showPreviewImageError(this)\" /></span><span class=\"preview-open-chip\">'+escHtml(previewOpenLabel)+'</span></div>';}");
		sb.AppendLine("function parseSystemLayers(raw){var rows=[];raw=raw||'';if(!raw)return rows;var lines=raw.split(/\\r?\\n/);for(var i=0;i<lines.length;i++){var line=lines[i];if(!line)continue;var p=line.split('\\t');if(p.length<4)continue;rows.push({index:p[0]||'-',func:p[1]||'-',name:p[2]||'-',thick:p[3]||'-'});}return rows;}function renderSystemLayerTable(raw,large){var rows=parseSystemLayers(raw);if(rows.length==0)return '<div class=\"system-layer-empty\">'+escHtml(noSystemLayerLabel)+'</div>';var html='<div class=\"system-layer-wrap\"><span class=\"system-layer-title\">'+escHtml(systemLayerTitle)+'</span><table class=\"system-layer-table\"><tr><th class=\"layer-index\">'+escHtml(layerIndexLabel)+'</th><th class=\"layer-function\">'+escHtml(layerFunctionLabel)+'</th><th>'+escHtml(layerNameLabel)+'</th><th class=\"layer-thickness\">'+escHtml(layerThicknessLabel)+'</th></tr>';for(var i=0;i<rows.length;i++){html+='<tr><td class=\"layer-index\">'+escHtml(rows[i].index)+'</td><td class=\"layer-function\">'+escHtml(rows[i].func)+'</td><td>'+escHtml(rows[i].name)+'</td><td class=\"layer-thickness\">'+escHtml(rows[i].thick)+'</td></tr>';}html+='</table>';if(!large)html+='<a class=\"system-layer-open\" href=\"#\" onclick=\"return openLayerModalFromCurrentSelection()\">'+escHtml(openLayerTableLabel)+'</a>';return html+'</div>';}function openLayerModalFromCurrentSelection(){var rows=rowsFor('systems');for(var i=0;i<rows.length;i++){if(rows[i].className.indexOf('data')>=0&&rows[i].className.indexOf('selected')>=0)return openLayerModal(rows[i].getAttribute('data-systemlayers')||'');}return false;}function openLayerModal(raw){var mask=byId('layerModalMask');var body=byId('layerModalBody');if(!mask||!body)return false;body.innerHTML=renderSystemLayerTable(raw,true);mask.style.display='block';return false;}function closeLayerModal(){var mask=byId('layerModalMask');var body=byId('layerModalBody');if(mask)mask.style.display='none';if(body)body.innerHTML='';return false;}function c