		sb.AppendLine("function detailKindLabel(row){var kind=row.getAttribute('data-kind')||'';var group=row.getAttribute('data-group')||'';if(currentTab=='systems')return kind?detailSystemLabel+' · '+kind:detailSystemLabel;if(group=='Model')return detailFamilyLabel+' · '+detailModelLabel;if(group=='Annotation')return detailFamilyLabel+' · '+detailAnnotationLabel;if(group=='Other')return detailFamilyLabel+' · '+detailOtherLabel;return detailFamilyLabel;}function detailTone(row){var s=row.getAttribute('data-raw')||'';if(isDuplicateRiskRow(row))return 'warn';if(s=='LoadedLatest'||s=='Latest'||s=='NoChange')return 'good';if(s=='LoadAvailable')return 'info';if(isUpdateStatus(s)||s=='LoadedWithoutVersionStamp'||s=='StampNormalizationNeeded')return 'warn';if(s=='Blocked'||s=='DifferentFromStandard'||s=='LocallyModified'||s=='VersionConflict'||s=='CategoryMismatch'||s=='ManualReview'||s=='ApprovalRequired')return 'bad';return 'info';}function setDetailText(id,value){var e=byId(id);if(e){var v=value||'-';e.innerText=v;e.title=v;}}function setDetailHtml(id,value){var e=byId(id);if(e)e.innerHTML=value||'-';}function updateStatusBadge(row){var e=byId('detailStatus');if(!e)return;e.innerText=row.getAttribute('data-status')||'-';e.className='detail-status-badge '+detailTone(row);}function resetDetailForCurrentTab(){setDetailText('detailKind',(currentTab=='systems')?detailSystemLabel:detailFamilyLabel);setDetailText('detailName','-');setDetailText('detailDiscipline','-');setDetailText('detailCategory','-');var s=byId('detailStatus');if(s){s.innerText='-';s.title='-';s.className='detail-status-badge info';}setDetailText('detailAction','-');setDetailHtml('detailNotes','-');setDetailText('detailApproved','-');setDetailText('detailLoaded','-');setDetailHtml('detailChanges',renderChangeSummary('-'));var block=byId('detailNestedBlock');if(block)block.style.display='none';var paramBlock=byId('detailParameterBlock');if(paramBlock)paramBlock.style.display='none';setDetailHtml('detailParameters