	private void AppendLongOperationProgress(StringBuilder sb)
	{
		int percent = ResolveLongOperationPercent(_longOperationCurrent, _longOperationTotal);
		sb.AppendLine("<div id=\"longOperationProgress\" class=\"long-operation-progress\" style=\"" + (_longOperationActive ? "display:block;" : "display:none;") + "\">");
		sb.AppendLine("<div class=\"long-operation-card\">");
		sb.AppendLine("<div class=\"long-operation-head\">");
		sb.AppendLine("<span id=\"longOperationTitle\" class=\"long-operation-title\">" + Html(string.IsNullOrWhiteSpace(_longOperationTitle) ? T("Working", "작업 진행 중") : _longOperationTitle) + "</span>");
		sb.AppendLine("<span id=\"longOperationCount\" class=\"long-operation-count\">" + Html(_longOperationCurrent.ToString(CultureInfo.InvariantCulture) + " / " + Math.Max(1, _longOperationTotal).ToString(CultureInfo.InvariantCulture) + " (" + percent.ToString(CultureInfo.InvariantCulture) + "%)") + "</span>");
		sb.AppendLine("</div>");
		sb.AppendLine("<div id=\"longOperationMessage\" class=\"long-operation-message\">" + Html(string.IsNullOrWhiteSpace(_longOperationMessage) ? T("Please wait...", "잠시만 기다려주세요...") : _longOperationMessage) + "</div>");
		sb.AppendLine("<div class=\"long-operation-track\"><div id=\"longOperationBar\" class=\"long-operation-bar\" style=\"width:" + percent.ToString(CultureInfo.InvariantCulture) + "%;\"></div></div>");
		sb.AppendLine("</div>");
		sb.AppendLine("</div>");
	}

	private static string BuildRuntimeDebugInfo()
	{
		string BuildRuntimeDebugInfo;
		try
		{
			string assemblyPath = Assembly.GetExecutingAssembly().Location;
			string stamp = "-";
			if (!string.IsNullOrWhiteSpace(assemblyPath) && File.Exists(assemblyPath))
			{
				stamp = File.GetLastWriteTime(assemblyPath).ToString("yyyy-MM-dd HH:mm:ss", CultureInfo.InvariantCulture);
			}
			string route = ((assemblyPath.IndexOf("\\_BuildCheck\\", StringComparison.OrdinalIgnoreCase) >= 0) ? "BuildCheck" : ((assemblyPath.IndexOf("\\bin\\", StringComparison.OrdinalIgnoreCase) >= 0) ? "DirectBin" : "InstalledOrOther"));
			BuildRuntimeDebugInfo = "Route=" + route + " | Assembly=" + assemblyPath + " | LastWrite=" + stamp;
		}
		catch (Exception ex)
		{
			ProjectData.SetProjectError(ex);
			Exception ex2 = ex;
			BuildRuntimeDebugInfo = "Route=Unknown | Assembly=unavailable | " + ex2.GetType().Name + ": " + ex2.Message;
			ProjectData.ClearProjectError();
		}
		return BuildRuntimeDebugInfo;
	}

	private static string DashboardRuntimeDiagnosticLogPath()
	{
		string workspaceRoot = HostWorkspacePathResolver.ResolveRoot();
		if (!FamilyBrowserStandardPolicyStore.IsManagedDataRootAvailable(workspaceRoot))
		{
			return string.Empty;
		}
		return Path.Combine(FamilyBrowserStandardPolicyStore.GetDataFolder(workspaceRoot, "Diagnostics"), "dashboard-runtime-" + DateTime.Now.ToString("yyyyMMdd", CultureInfo.InvariantCulture) + ".log");
	}

	private void WriteDashboardRuntimeDiagnostic(string stage, int htmlLength = -1, long elapsedMilliseconds = -1L)
	{
		try
		{
			string logPath = DashboardRuntimeDiagnosticLogPath();
			if (!string.IsNullOrWhiteSpace(logPath))
			{
				string dir = Path.GetDirectoryName(logPath);
				if (!string.IsNullOrWhiteSpace(dir))
				{
					Directory.CreateDirectory(dir);
				}
				string assemblyPath = Assembly.GetExecutingAssembly().Location;
				string assemblyStamp = "-";
				if (!string.IsNullOrWhiteSpace(assemblyPath) && File.Exists(assemblyPath))
				{
					assemblyStamp = File.GetLastWriteTime(assemblyPath).ToString("yyyy-MM-dd HH:mm:ss", CultureInfo.InvariantCulture);
				}
				string manifestPath = "C:\\ProgramData\\Autodesk\\Revit\\Addins\\2019\\KKY_FamilyBrowser_RevitHost.addin";
				string manifestAssembly = ExtractManifestAssemblyPath(manifestPath);
				List<string> lines = new List<string>
				{
					"-----",
					"Time=" + DateTime.Now.ToString("yyyy-MM-dd HH:mm:ss.fff", CultureInfo.InvariantCulture),
					"Stage=" + (stage ?? "-"),
					"Title=" + DashboardWindowTitle(),
					"BuildLabelEn=TEST",
					"BuildLabelKo=TEST 중",
					"ActiveTab=" + (_activeTab ?? "-"),
					"HtmlLength=" + htmlLength.ToString(CultureInfo.InvariantCulture),
					"ElapsedMs=" + elapsedMilliseconds.ToString(CultureInfo.InvariantCulture),
					"Assembly=" + assemblyPath,
					"AssemblyLastWrite=" + assemblyStamp,
					"Manifest2019=" + manifestPath,
					"ManifestAssembly=" + manifestAssembly,
					"Runtime=" + BuildRuntimeDebugInfo()
				};
				File.AppendAllLines(logPath, lines, Encoding.UTF8);
			}
		}
		catch (Exception projectError)
		{
			ProjectData.SetProjectError(projectError);
			ProjectData.ClearProjectError();
		}
	}

	private static string ExtractManifestAssemblyPath(string manifestPath)
	{
		checked
		{
			string ExtractManifestAssemblyPath;
			try
			{
				if (string.IsNullOrWhiteSpace(manifestPath) || !File.Exists(manifestPath))
				{
					ExtractManifestAssemblyPath = "-";
				}
				else
				{
					string text = File.ReadAllText(manifestPath, Encoding.UTF8);
					string openTag = "<Assembly>";
					string closeTag = "</Assembly>";
					int startIndex = text.IndexOf(openTag, StringComparison.OrdinalIgnoreCase);
					if (startIndex < 0)
					{
						ExtractManifestAssemblyPath = "-";
					}
					else
					{
						startIndex += openTag.Length;
						int endIndex = text.IndexOf(closeTag, startIndex, StringComparison.OrdinalIgnoreCase);
						ExtractManifestAssemblyPath = ((endIndex >= startIndex) ? text.Substring(startIndex, endIndex - startIndex).Trim() : "-");
					}
				}
			}
			catch (Exception ex)
			{
				ProjectData.SetProjectError(ex);
				Exception ex2 = ex;
				ExtractManifestAssemblyPath = "unavailable: " + ex2.GetType().Name + ": " + ex2.Message;
				ProjectData.ClearProjectError();
			}
			return ExtractManifestAssemblyPath;
		}
	}

