	private void AppendFamilyTree(StringBuilder sb, IList<BrowserRow> rows)
	{
		sb.AppendLine("<div class=\"family-tree-panel\">");
		sb.AppendLine("<div class=\"tree-title\">" + Html(T("Trade / Category", "공종 / 카테고리")) + "</div>");
		sb.AppendLine("<div class=\"tree-help\">" + Html(T("Select a trade to see all families, or select a category under it.", "공종을 선택하면 전체 패밀리, 하위 카테고리를 선택하면 해당 카테고리만 표시됩니다.")) + "</div>");
		AppendFamilyTreeNode(sb, "All", string.Empty, string.Empty, T("All Trades", "전체 공종"), rows?.Count ?? 0, "tree-node level1", active: true);
		if (rows != null && rows.Count > 0)
		{
			IOrderedEnumerable<IGrouping<string, BrowserRow>> disciplineGroups = (from x in rows
				group x by NormalizeDisciplineTreeKey(x.DisciplineKey, x.DisciplineLabel)).OrderBy([SpecialName] (IGrouping<string, BrowserRow> g) => Normalize(g.First().DisciplineLabel), StringComparer.Ordinal);
			foreach (IGrouping<string, BrowserRow> disciplineGroup in disciplineGroups)
			{
				BrowserRow firstRow = disciplineGroup.First();
				string disciplineKey = NormalizeDisciplineTreeKey(firstRow.DisciplineKey, firstRow.DisciplineLabel);
				string disciplineLabel = ResolveTreeLabel(firstRow.DisciplineLabel, disciplineKey);
				sb.AppendLine("<div class=\"tree-row\">");
				AppendFamilyTreeNode(sb, disciplineKey, string.Empty, string.Empty, disciplineLabel, disciplineGroup.Count(), "tree-node level1", active: false);
				AppendFamilyTreeToggle(sb, disciplineKey, string.Empty);
				sb.AppendLine("</div>");
				sb.AppendLine("<div name=\"familyTreeChildren\" class=\"tree-children\" data-family-tree-children=\"" + Attr(FamilyTreeToggleKey(disciplineKey, string.Empty)) + "\">");
				IOrderedEnumerable<IGrouping<string, BrowserRow>> modelAnnotationGroups = (from x in disciplineGroup
					group x by NormalizeCategoryGroupToken(x.CategoryGroup) into g
					orderby CategoryGroupSortOrder(g.Key)
					select g).ThenBy([SpecialName] (IGrouping<string, BrowserRow> g) => CategoryGroupLabel(g.Key), StringComparer.Ordinal);
				foreach (IGrouping<string, BrowserRow> modelAnnotationGroup in modelAnnotationGroups)
				{
					string groupToken = NormalizeCategoryGroupToken(modelAnnotationGroup.Key);
					sb.AppendLine("<div class=\"tree-row\">");
					AppendFamilyTreeNode(sb, disciplineKey, groupToken, string.Empty, CategoryGroupLabel(groupToken), modelAnnotationGroup.Count(), "tree-node level2", active: false);
					AppendFamilyTreeToggle(sb, disciplineKey, groupToken);
					sb.AppendLine("</div>");
					sb.AppendLine("<div name=\"familyTreeChildren\" class=\"tree-children\" data-family-tree-children=\"" + Attr(FamilyTreeToggleKey(disciplineKey, groupToken)) + "\">");
					IOrderedEnumerable<IGrouping<string, BrowserRow>> categoryGroups = (from x in modelAnnotationGroup
						group x by (!string.IsNullOrWhiteSpace(x.Category)) ? x.Category : T("Uncategorized", "미분류")).OrderBy([SpecialName] (IGrouping<string, BrowserRow> g) => Normalize(g.Key), StringComparer.Ordinal);
					foreach (IGrouping<string, BrowserRow> categoryGroup in categoryGroups)
					{
						AppendFamilyTreeNode(sb, disciplineKey, groupToken, categoryGroup.Key, categoryGroup.Key, categoryGroup.Count(), "tree-node level3", active: false);
					}
					sb.AppendLine("</div>");
				}
				sb.AppendLine("</div>");
			}
		}
		sb.AppendLine("</div>");
	}

	private void AppendFamilyTreeNode(StringBuilder sb, string disciplineKey, string categoryGroup, string category, string label, int count, string baseClass, bool active)
	{
		string nodeClass = baseClass + (active ? " active" : string.Empty);
		string treeGroup = (string.IsNullOrWhiteSpace(categoryGroup) ? string.Empty : NormalizeCategoryGroupToken(categoryGroup));
		sb.AppendLine("<a name=\"familyTreeNode\" class=\"" + Attr(nodeClass) + "\" data-base-class=\"" + Attr(baseClass) + "\" data-tree-discipline=\"" + Attr(string.IsNullOrWhiteSpace(disciplineKey) ? "All" : disciplineKey) + "\" data-tree-group=\"" + Attr(treeGroup) + "\" data-tree-category=\"" + Attr(category ?? string.Empty) + "\" href=\"#\" onclick=\"return setTreeFilter('" + Js(string.IsNullOrWhiteSpace(disciplineKey) ? "All" : disciplineKey) + "','" + Js(treeGroup) + "','" + Js(category ?? string.Empty) + "')\">" + Html(label) + "<span class=\"tree-count\">" + count.ToString(CultureInfo.InvariantCulture) + "</span></a>");
	}

	private void AppendFamilyTreeToggle(StringBuilder sb, string disciplineKey, string categoryGroup)
	{
		string treeGroup = (string.IsNullOrWhiteSpace(categoryGroup) ? string.Empty : NormalizeCategoryGroupToken(categoryGroup));
		sb.AppendLine("<a name=\"familyTreeToggle\" class=\"tree-toggle\" data-family-tree-toggle=\"" + Attr(FamilyTreeToggleKey(disciplineKey, treeGroup)) + "\" href=\"#\" onclick=\"return toggleFamilyTree('" + Js(string.IsNullOrWhiteSpace(disciplineKey) ? "All" : disciplineKey) + "','" + Js(treeGroup) + "')\">+</a>");
	}

	private static string FamilyTreeToggleKey(string disciplineKey, string categoryGroup)
	{
		string obj = (string.IsNullOrWhiteSpace(disciplineKey) ? "All" : disciplineKey);
		string groupKey = (string.IsNullOrWhiteSpace(categoryGroup) ? string.Empty : NormalizeCategoryGroupToken(categoryGroup));
		return obj + "||" + groupKey;
	}

	private static int CategoryGroupSortOrder(string categoryGroup)
	{
		string left = NormalizeCategoryGroupToken(categoryGroup);
		if (Operators.CompareString(left, "Model", TextCompare: false) != 0)
		{
			if (Operators.CompareString(left, "Annotation", TextCompare: false) == 0)
			{
				return 1;
			}
			return 2;
		}
		return 0;
	}

	private static string NormalizeDisciplineTreeKey(string disciplineKey, string disciplineLabel)
	{
		string key = (disciplineKey ?? string.Empty).Trim();
		if (key.Length > 0)
		{
			return key;
		}
		string label = (disciplineLabel ?? string.Empty).Trim();
		if (label.Length > 0)
		{
			return label;
		}
		return "Unassigned";
	}

	private string ResolveTreeLabel(string label, string fallback)
	{
		if (!string.IsNullOrWhiteSpace(label))
		{
			return label.Trim();
		}
		if (string.Equals(fallback, "Unassigned", StringComparison.OrdinalIgnoreCase))
		{
			return T("Unassigned", "미지정");
		}
		return fallback;
	}

