			sb.AppendLine("<a id=\"checkedSystemApply\" class=\"tool primary command-apply\" href=\"#\" data-base-label=\"" + Attr(checkedLabel) + "\" onclick=\"return loadSelectedSystemType()\">" + Html(checkedLabel) + "</a>");
			sb.AppendLine("<a class=\"tool ghost\" href=\"#\" onclick=\"return clearSystemSelection()\">" + Html(T("Clear Selection", "선택 초기화")) + "</a>");
		}
		else
		{
			sb.AppendLine("<span class=\"tool primary command-apply disabled\" title=\"" + Attr(T("Your current Family Browser role cannot apply approved standard system types. Ask an admin to enable modeler system apply or use Request Addition.", "현재 Family Browser 권한으로는 승인된 표준 시스템 타입을 적용할 수 없습니다. 관리자에게 모델러 시스템 적용 권한을 요청하거나 추가 요청을 사용하세요.")) + "\">" + Html(T("Apply Selected Items", "선택 항목 적용")) + "</span>");
		}
		AppendSystemInlineStatusFilterBar(sb, systemRows);
		sb.AppendLine("</div>");
		sb.AppendLine("<div class=\"family-browser-grid system-browser-grid\">");
		AppendSystemTree(sb, systemRows);
		sb.AppendLine("<div class=\"family-list-panel\">");
		AppendSystemFixedHeader(sb);
		sb.AppendLine("<div class=\"family-tablewrap has-fixed-head\" data-fixed-head=\"systemsFixedHeader\" onscroll=\"syncFixedHeaderScroll(this,'systemsFixedHeader')\"><table id=\"systemsTable\">");
		AppendSystemColGroup(sb);
		sb.AppendLine("<tbody>");
		if (systemRows.Count != 0)
		{
			foreach (SystemRow row in systemRows)
			{
				AppendRow(sb, "systems", row.Status, row.RawStatus, row.DisciplineKey, row.DisciplineLabel, row.Name, row.Category, row.Action, row.Notes, "-", "-", row.Notes, row.SystemFamilyKind, string.Empty, string.Empty, string.Empty, string.Empty, string.Empty, SystemTreeRowDisciplineKey(row), row.LayerSummary, row.DifferenceSummaryTable);
			}
		}
		else if (_activeStandardScanNeeded)
		{
			AppendEmptyTableRow(sb, 7, T("Scan needed", "스캔 필요"), StandardScanNeededUserAction());
		}
		else if (IsActiveStandardUnavailable(_registration))
		{
			AppendStandardRegistrationRequiredRow(sb, 7, T("System Type Load", "시스템 타입 로드"));
		}
		else if (!_adminModeEnabled && _systemRows.Count > 0)
		{
			AppendEmptyTableRow(sb, 7, T("No loadable standard system types for modeler view", "모델러가 적용할 표준 시스템 타입이 없습니다"), T("Items that are not in the standard or require review are hidden here and shown only in admin review.", "표준에 없거나 검토가 필요한 항목은 이 화면에서 숨기고 관리자 검토에서만 표시합니다."));
		}
		else
		{
			AppendEmptyTableRow(sb, 7, T("System type list is not ready yet", "시스템 타입 목록이 아직 준비되지 않았습니다"), T("Open or refresh the dashboard with a registered standard RVT. Current-project system types are compared automatically.", "등록된 표준 RVT가 있는 상태로 화면을 열거나 새로고침하세요. 현재 프로젝트 시스템 타입은 자동으로 비교됩니다."));
		}
		sb.AppendLine("</tbody></table></div>");
		sb.AppendLine("</div>");
		sb.AppendLine("</div>");
		sb.AppendLine("</div>");
