	private void AppendSystemTree(StringBuilder sb, IList<SystemRow> rows)
	{
		sb.AppendLine("<div class=\"family-tree-panel\">");
		sb.AppendLine("<div class=\"tree-title\">" + Html(T("Trade / Category", "공종 / 카테고리")) + "</div>");
		sb.AppendLine("<div class=\"tree-help\">" + Html(T("Select a trade to see all system types. Use +/- to expand only the categories you need.", "공종을 선택하면 해당 시스템 타입 전체가 표시됩니다. +/-로 필요한 카테고리만 펼쳐서 보세요.")) + "</div>");
		AppendSystemTreeNode(sb, "All", string.Empty, T("All Trades", "전체 공종"), rows?.Count ?? 0, "tree-node level1", active: true);
		if (rows != null && rows.Count > 0)
		{
			IOrderedEnumerable<IGrouping<string, SystemRow>> disciplineGroups = (from x in rows
				group x by SystemTreeRowDisciplineKey(x)).OrderBy([SpecialName] (IGrouping<string, SystemRow> g) => Normalize(g.First().DisciplineLabel), StringComparer.Ordinal);
			foreach (IGrouping<string, SystemRow> disciplineGroup in disciplineGroups)
			{
				SystemRow firstRow = disciplineGroup.First();
				string disciplineKey = SystemTreeRowDisciplineKey(firstRow);
				string disciplineLabel = ResolveTreeLabel(firstRow.DisciplineLabel, disciplineKey);
				sb.AppendLine("<div class=\"tree-row\">");
				AppendSystemTreeNode(sb, disciplineKey, string.Empty, disciplineLabel, disciplineGroup.Count(), "tree-node level1", active: false);
				sb.AppendLine("<a name=\"systemTreeToggle\" class=\"tree-toggle\" data-system-tree-toggle=\"" + Attr(disciplineKey) + "\" href=\"#\" onclick=\"return toggleSystemTree('" + Js(disciplineKey) + "')\">+</a>");
				sb.AppendLine("</div>");
				sb.AppendLine("<div name=\"systemTreeChildren\" class=\"tree-children\" data-system-tree-children=\"" + Attr(disciplineKey) + "\">");
				IOrderedEnumerable<IGrouping<string, SystemRow>> categoryGroups = (from x in disciplineGroup
					group x by (!string.IsNullOrWhiteSpace(x.Category)) ? x.Category : T("Uncategorized", "미분류")).OrderBy([SpecialName] (IGrouping<string, SystemRow> g) => Normalize(g.Key), StringComparer.Ordinal);
				foreach (IGrouping<string, SystemRow> categoryGroup in categoryGroups)
				{
					AppendSystemTreeNode(sb, disciplineKey, categoryGroup.Key, categoryGroup.Key, categoryGroup.Count(), "tree-node level2", active: false);
				}
				sb.AppendLine("</div>");
			}
		}
		sb.AppendLine("</div>");
	}

	private void AppendSystemTreeNode(StringBuilder sb, string disciplineKey, string category, string label, int count, string baseClass, bool active)
	{
		string nodeClass = baseClass + (active ? " active" : string.Empty);
		string key = (string.IsNullOrWhiteSpace(disciplineKey) ? "All" : disciplineKey);
		string categoryValue = category ?? string.Empty;
		sb.AppendLine("<a name=\"systemTreeNode\" class=\"" + Attr(nodeClass) + "\" data-base-class=\"" + Attr(baseClass) + "\" data-system-tree-discipline=\"" + Attr(key) + "\" data-system-tree-category=\"" + Attr(categoryValue) + "\" href=\"#\" onclick=\"return setSystemTreeFilter('" + Js(key) + "','" + Js(categoryValue) + "')\">" + Html(label) + "<span class=\"tree-count\">" + count.ToString(CultureInfo.InvariantCulture) + "</span></a>");
	}

	private static string SystemTreeRowDisciplineKey(SystemRow row)
	{
		if (row == null)
		{
			return "Unassigned";
		}
		return NormalizeDisciplineTreeKey(row.DisciplineKey, row.DisciplineLabel);
	}

