	private void AppendSystemPreflightBoard(StringBuilder sb)
	{
		sb.AppendLine("<div class=\"request-status-strip\" style=\"min-height:140px;padding:16px 22px 4px 22px;box-sizing:border-box;border-bottom:1px solid #d4dfda;background:#fbfdfb;overflow:visible\">");
		if (_lastSystemPreflightReport == null)
		{
			sb.AppendLine("<div class=\"hint\" style=\"margin-top:14px\">" + Html(T("System Type Load compares the current RVT automatically. Manager diagnostics are only needed for deeper duplicate/dependency investigation.", "시스템 타입 로드는 현재 RVT를 자동 비교합니다. 관리자 정밀 진단은 중복/의존성 원인을 더 깊게 확인할 때만 사용합니다.")) + "</div>");
			sb.AppendLine("</div>");
			return;
		}
		SystemTypePreflightSummary summary = _lastSystemPreflightReport.Summary;
		AppendSystemPreflightMetric(sb, T("Ready", "준비"), summary.ReadyCount, "good");
		AppendSystemPreflightMetric(sb, T("Approval", "승인"), summary.ApprovalRequiredCount, "warn");
		AppendSystemPreflightMetric(sb, T("Blocked", "차단"), summary.BlockedCount, "bad");
		AppendSystemPreflightMetric(sb, T("Loadable Base", "로더블 기반"), summary.LoadableFoundationBlockedCount, (summary.LoadableFoundationBlockedCount > 0) ? "bad" : "good");
		AppendSystemPreflightMetric(sb, T("Dependency Reload", "의존 재로드"), summary.DependencyReloadCount, (summary.DependencyReloadCount > 0) ? "warn" : "good");
		AppendSystemPreflightMetric(sb, T("Manual Review", "수동 검토"), summary.DependencyManualReviewCount, (summary.DependencyManualReviewCount > 0) ? "bad" : "good");
		int duplicateRiskCount = checked(CountSystemActions(_lastSystemPreflightReport, "consolidateduplicatesuffixtypes") + CountKeepWithDuplicateCleanup(_lastSystemPreflightReport));
		if (duplicateRiskCount > 0)
		{
			AppendSystemPreflightMetric(sb, T("Duplicate Risk", "중복 위험"), duplicateRiskCount, "bad");
			sb.AppendLine("<div class=\"hint\" style=\"clear:both;margin-top:2px\">" + Html(T("Duplicate-risk items are cleanup/consolidation candidates. Review the canonical type and standard loadable dependencies before applying.", "중복 위험 항목은 정리/통합 검토 대상입니다. 기준 타입과 표준 로더블 의존성을 확인한 뒤 적용하세요.")) + "</div>");
		}
		sb.AppendLine("</div>");
	}

	private static void AppendSystemPreflightMetric(StringBuilder sb, string label, int count, string tone)
	{
		sb.AppendLine("<div class=\"request-status\"><strong><span class=\"badge " + Attr(tone) + "\">" + count.ToString(CultureInfo.InvariantCulture) + "</span></strong><span>" + Html(label) + "</span></div>");
	}

	private void AppendRequestPane(StringBuilder sb)
	{
		FamilyBrowserStandardPolicy policy = _standardPolicy ?? LoadStandardPolicy();
		string requestStoreHintClass = "hint " + ResolveRequestStorePaneHintClass(policy);
		string requestStoreHint = ResolveRequestStorePaneHint(policy);
		sb.AppendLine("<div id=\"requestsPane\" style=\"" + Attr(DashboardPaneDisplayStyle("requests")) + "\">");
		sb.AppendLine("<div class=\"pane-head\">");
		sb.AppendLine("<a class=\"tool primary\" href=\"kkyfb:request-new\">" + Html(T("Register Request", "요청 등록하기")) + "</a>");
		sb.AppendLine("<a class=\"tool\" href=\"kkyfb:request-refresh\">" + Html(T("Refresh List", "목록 새로고침")) + "</a>");
		sb.AppendLine("<span class=\"" + requestStoreHintClass + "\" style=\"display:inline-block;vertical-align:middle;margin-left:8px;max-width:620px;font-size:24px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;\">" + Html(requestStoreHint) + "</span>");
		sb.AppendLine("</div>");
		sb.AppendLine("<div class=\"request-pane-scroll\">");
		AppendRequestStatusStrip(sb);
		sb.AppendLine("<div class=\"section\" style=\"margin-top:8px\">" + Html(T("Request List", "요청 목록")) + "</div>");
		sb.AppendLine("<table id=\"requestsTable\">");
		sb.AppendLine("<tr><th style=\"width:130px\">" + Html(T("Status", "상태")) + "</th><th style=\"width:150px\">" + Html(T("Trade", "공종")) + "</th><th style=\"width:150px\">" + Html(T("Type", "구분")) + "</th><th>" + Html(T("Title", "제목")) + "</th><th style=\"width:170px\">" + Html(T("By", "작성자")) + "</th><th style=\"width:150px\">" + Html(T("Created", "작성일")) + "</th><th style=\"width:95px\">" + Html(T("Files", "첨부")) + "</th><th style=\"width:180px\">" + Html(T("Progress", "진행")) + "</th></tr>");
		if (!_requestRecordsLoaded)
		{
			AppendEmptyTableRow(sb, 8, T("Request list has not been loaded yet", "요청 목록을 아직 불러오지 않았습니다"), T("Open this tab or click Refresh List to load requests.", "이 탭을 열거나 목록 새로고침을 눌러 요청을 불러오세요."));
		}
		else if (_requestRecords == null || _requestRecords.Count == 0)
		{
			AppendEmptyTableRow(sb, 8, T("No requests yet", "등록된 요청이 아직 없습니다"), T("Use Register Request when a needed family or system type is missing.", "필요한 패밀리나 시스템 타입이 없을 때 요청 등록하기를 사용하세요."));
		}
		else
		{
			foreach (FamilyBrowserRequestRecord record in _requestRecords.Take(80))
			{
				AppendRequestRow(sb, record);
			}
		}
		sb.AppendLine("</table>");
		sb.AppendLine("</div>");
		sb.AppendLine("</div>");
	}

