				int systemCount = group.Where((_Closure_0024__._0024I629_002D4 == null) ? (_Closure_0024__._0024I629_002D4 = [SpecialName] (FamilyBrowserRequestRecord x) => string.Equals(Normalize(x.RequestKind), "system", StringComparison.Ordinal)) : _Closure_0024__._0024I629_002D4).Count();
				int updateCount = group.Where((_Closure_0024__._0024I629_002D5 == null) ? (_Closure_0024__._0024I629_002D5 = [SpecialName] (FamilyBrowserRequestRecord x) => string.Equals(Normalize(x.RequestKind), "update", StringComparison.Ordinal)) : _Closure_0024__._0024I629_002D5).Count();
				int openCount = group.Where((_Closure_0024__._0024I629_002D6 == null) ? (_Closure_0024__._0024I629_002D6 = [SpecialName] (FamilyBrowserRequestRecord x) => !IsRequestClosed(x.Status)) : _Closure_0024__._0024I629_002D6).Count();
				FamilyBrowserRequestRecord latest = group.OrderByDescending((_Closure_0024__._0024I629_002D7 == null) ? (_Closure_0024__._0024I629_002D7 = [SpecialName] (FamilyBrowserRequestRecord x) => ParseRequestDate(x.UpdatedAtUtc, x.CreatedAtUtc)) : _Closure_0024__._0024I629_002D7).FirstOrDefault();
				string latestText = ((latest == null) ? "-" : (RequestStatusLabel(latest.Status) + " / " + SafeShortName(latest.ItemName, 32)));
				sb.AppendLine("<div class=\"discipline-card\">");
