	private void AppendRequestRow(StringBuilder sb, FamilyBrowserRequestRecord record)
	{
		string status = (string.IsNullOrWhiteSpace(record.Status) ? "Draft" : record.Status);
		string discipline = NormalizeRequestDiscipline(record);
		string notes = BuildRequestRowNotes(record);
		string actionText = ResolveRequestProgressText(record);
		int attachmentCount = CountRequestAttachments(record);
		bool canSeeRequestStorage = CanSeeInternalPaths();
		string changeDetail = LastRequestHistory(record);
		if (attachmentCount > 0)
		{
			changeDetail = changeDetail + Environment.NewLine + T("Attachments: ", "첨부파일: ") + attachmentCount.ToString(CultureInfo.InvariantCulture);
			if (canSeeRequestStorage && !string.IsNullOrWhiteSpace(record.AttachmentFolder))
			{
				changeDetail = changeDetail + Environment.NewLine + T("Attachment folder: ", "첨부 폴더: ") + record.AttachmentFolder;
			}
		}
		sb.Append("<tr class=\"data\" onclick=\"selectRow(this)\"");
		sb.Append(" data-raw=\"" + Attr(status) + "\"");
		sb.Append(" data-status=\"" + Attr(RequestStatusLabel(status)) + "\"");
		sb.Append(" data-name=\"" + Attr(record.ItemName) + "\"");
		sb.Append(" data-category=\"" + Attr(discipline) + "\"");
		sb.Append(" data-action=\"" + Attr(actionText) + "\"");
		sb.Append(" data-notes=\"" + Attr(notes) + "\"");
		sb.Append(" data-approved=\"" + Attr(record.RequestId) + "\"");
		sb.Append(" data-loaded=\"" + Attr(FormatRequestDate(record.UpdatedAtUtc)) + "\"");
		sb.Append(" data-changes=\"" + Attr(changeDetail) + "\"");
		sb.Append(" data-preview=\"\">");
		sb.Append("<td><span class=\"badge " + StatusClass(status) + "\">" + Html(RequestStatusLabel(status)) + "</span></td>");
		sb.Append("<td>" + Html(SafeShortName(discipline, 24)) + "</td>");
		sb.Append("<td>" + Html(RequestKindLabel(record.RequestKind)) + "</td>");
		sb.Append("<td>" + Html(record.ItemName) + "</td>");
		sb.Append("<td>" + Html(record.CreatedBy) + "</td>");
		sb.Append("<td>" + Html(FormatRequestDate(record.CreatedAtUtc)) + "</td>");
		sb.Append("<td>" + attachmentCount.ToString(CultureInfo.InvariantCulture) + "</td>");
		sb.Append("<td class=\"request-actions\">" + BuildRequestProgressActions(record) + "</td>");
		sb.AppendLine("</tr>");
	}

	private string BuildRequestProgressActions(FamilyBrowserRequestRecord record)
	{
		string requestId = Attr(record.RequestId);
		bool canSeeRequestStorage = CanSeeInternalPaths();
		if (!HasPermission("ApproveRequest"))
		{
			string readOnlyActions = Html(RequestStatusLabel(record.Status));
			if (canSeeRequestStorage && CountRequestAttachments(record) > 0)
			{
				readOnlyActions = readOnlyActions + "<a href=\"kkyfb:request-attachments/" + requestId + "\">" + Html(T("Files", "첨부")) + "</a>";
			}
			if (CanDeleteRequestRecord(record))
			{
				readOnlyActions += RequestDeleteLink(requestId, T("Delete", "삭제"));
			}
			return readOnlyActions;
		}
		string actions = Normalize(record.Status) switch
		{
			"draft" => RequestActionLink("submitted", requestId, T("Submit", "접수")), 
			"submitted" => RequestActionLink("reviewing", requestId, T("Review", "검토")) + RequestActionLink("rejected", requestId, T("Reject", "반려"), "bad-action"), 
			"reviewing" => RequestActionLink("approved", requestId, T("Approve", "승인"), "primary") + RequestActionLink("rejected", requestId, T("Reject", "반려"), "bad-action"), 
			"approved" => RequestActionLink("completed", requestId, T("Complete", "완료"), "primary") + RequestActionLink("rejected", requestId, T("Reject", "반려"), "bad-action"), 
			"rejected" => RequestActionLink("submitted", requestId, T("Reopen", "재접수")), 
			_ => Html(T("Completed", "완료")), 
		};
		if (canSeeRequestStorage && CountRequestAttachments(record) > 0)
		{
			actions = actions + "<a href=\"kkyfb:request-attachments/" + requestId + "\">" + Html(T("Files", "첨부")) + "</a>";
		}
		if (CanDeleteRequestRecord(record))
		{
			actions += RequestDeleteLink(requestId, T("Delete", "삭제"));
		}
		return actions;
	}

	private static string RequestActionLink(string statusToken, string requestId, string text, string cssClass = "")
	{
		string classes = (string.IsNullOrWhiteSpace(cssClass) ? string.Empty : (" class=\"" + Attr(cssClass) + "\""));
		return "<a" + classes + " href=\"kkyfb:request-status/" + Attr(statusToken) + "/" + requestId + "\">" + Html(text) + "</a>";
	}

	private static string RequestDeleteLink(string requestId, string text)
	{
		return "<a class=\"bad-action\" href=\"kkyfb:request-delete/" + Attr(requestId) + "\">" + Html(text) + "</a>";
	}

	private bool CanDeleteRequestRecord(FamilyBrowserRequestRecord record)
	{
		if (record == null)
		{
			return false;
		}
		if (CanSeeInternalPaths())
		{
			return true;
		}
		return RequestUserMatchesCurrentUser(record.CreatedBy);
	}

	private bool RequestUserMatchesCurrentUser(string requestUser)
	{
		HashSet<string> requestKeys = BuildRequestUserIdentityKeys(requestUser);
		if (requestKeys.Count == 0)
		{
			return false;
		}
		foreach (string key in BuildRequestUserIdentityKeys(Environment.UserName))
		{
			if (requestKeys.Contains(key))
			{
				return true;
			}
		}
		foreach (string key2 in BuildRequestUserIdentityKeys(CurrentUserIdentity()))
		{
			if (requestKeys.Contains(key2))
			{
				return true;
			}
		}
		return false;
	}

	private static HashSet<string> BuildRequestUserIdentityKeys(string identity)
	{
		HashSet<string> keys = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
		string value = (identity ?? string.Empty).Trim();
		if (value.Length == 0)
		{
			return keys;
		}
		keys.Add(value);
		int slashIndex = value.LastIndexOf('\\');
		checked
		{
			if (slashIndex >= 0 && slashIndex < value.Length - 1)
			{
				keys.Add(value.Substring(slashIndex + 1));
			}
			int atIndex = value.IndexOf('@');
			if (atIndex > 0)
			{
				keys.Add(value.Substring(0, atIndex));
			}
			return keys;
		}
	}

	private string ResolveRequestProgressText(FamilyBrowserRequestRecord record)
	{
		string note = DisplayRequestProgressNote((record.ProgressNote ?? string.Empty).Trim());
		if (note.Length > 0)
		{
			return RequestStatusLabel(record.Status) + " - " + note;
		}
		return RequestStatusLabel(record.Status);
	}

	private string BuildRequestRowNotes(FamilyBrowserRequestRecord record)
	{
		List<string> parts = new List<string>();
		if (!string.IsNullOrWhiteSpace(record.Reason))
		{
			parts.Add(DisplayRequestFieldText(record.Reason));
		}
		if (!string.IsNullOrWhiteSpace(record.SuggestedAction))
		{
			parts.Add(T("Next action: ", "다음 조치: ") + DisplayRequestFieldText(record.SuggestedAction));
		}
		if (!string.IsNullOrWhiteSpace(record.Notes))
		{
			parts.Add(T("Context: ", "참고: ") + DisplayRequestFieldText(record.Notes));
		}
		if (!string.IsNullOrWhiteSpace(record.ProgressNote))
		{
			parts.Add(T("Progress: ", "진행: ") + DisplayRequestProgressNote(record.ProgressNote));
		}
		bool canSeeRequestStorage = CanSeeInternalPaths();
		if (canSeeRequestStorage && !string.IsNullOrWhiteSpace(record.SourcePath))
		{
			parts.Add(T("Request file: ", "요청서: ") + record.SourcePath);
		}
		int attachmentCount = CountRequestAttachments(record);
		if (attachmentCount > 0)
		{
			parts.Add(T("Attachments: ", "첨부파일: ") + attachmentCount.ToString(CultureInfo.InvariantCulture));
			if (canSeeRequestStorage && !string.IsNullOrWhiteSpace(record.AttachmentFolder))
			{
				parts.Add(T("Attachment folder: ", "첨부 폴더: ") + record.AttachmentFolder);
			}
		}
		return string.Join(Environment.NewLine, parts);
	}

	private static int CountRequestAttachments(FamilyBrowserRequestRecord record)
	{
		if (record == null || record.AttachmentFiles == null)
		{
			return 0;
		}
		return record.AttachmentFiles.Count;
	}

	private string RequestKindLabel(string requestKind)
	{
		return Normalize(requestKind) switch
		{
			"family" => T("Family", "패밀리"), 
			"system" => T("System Type", "시스템 타입"), 
			"update" => T("Update", "업데이트"), 
			_ => T("General", "일반"), 
		};
	}

	private string RequestStatusLabel(string status)
	{
		return Normalize(status) switch
		{
			"submitted" => T("Submitted", "접수"), 
			"reviewing" => T("Reviewing", "검토 중"), 
			"approved" => T("Approved", "승인"), 
			"rejected" => T("Rejected", "반려"), 
			"completed" => T("Completed", "완료"), 
			_ => T("Registered", "등록"), 
		};
	}

	private string NormalizeRequestDiscipline(FamilyBrowserRequestRecord record)
	{
		if (record == null)
		{
			return T("Unassigned", "미지정");
		}
		if (!string.IsNullOrWhiteSpace(record.Discipline))
		{
			return DisplayRequestFieldText(record.Discipline);
		}
		if (!string.IsNullOrWhiteSpace(record.StandardTarget))
		{
			return DisplayRequestFieldText(record.StandardTarget);
		}
		if (!string.IsNullOrWhiteSpace(record.CategoryName))
		{
			return DisplayRequestFieldText(record.CategoryName);
		}
		return T("Unassigned", "미지정");
	}

	private string DisplayRequestFieldText(string value)
	{
		if (string.IsNullOrWhiteSpace(value) || !IsKorean())
		{
			return value ?? string.Empty;
		}
		return value.Trim() switch
		{
			"Unassigned" => "미지정", 
			"Request file" => "요청 파일", 
			"Ask the administrator to inspect this request file." => "관리자에게 이 요청 파일 검토를 요청하세요.", 
			"The request file exists, but its JSON could not be read by the request board." => "요청 파일은 있지만 요청 목록에서 JSON 내용을 읽지 못했습니다.", 
			"The file is still visible so it is not lost. Check request-read-errors.log in the request store." => "파일은 목록에 남겨두었습니다. 요청 저장소의 request-read-errors.log를 확인하세요.", 
			_ => value, 
		};
	}

	private static bool IsRequestClosed(string status)
	{
		string raw = Normalize(status);
		if (Operators.CompareString(raw, "completed", TextCompare: false) != 0)
		{
			return Operators.CompareString(raw, "rejected", TextCompare: false) == 0;
		}
		return true;
	}

	private static string FormatRequestDate(string value)
	{
		DateTime parsed = ParseRequestDate(value, string.Empty);
		if (DateTime.Compare(parsed, DateTime.MinValue) == 0)
		{
			return "-";
		}
		return parsed.ToLocalTime().ToString("MM-dd HH:mm", CultureInfo.InvariantCulture);
	}

	private static DateTime ParseRequestDate(string primary, string fallback)
	{
		if (DateTime.TryParse(primary, CultureInfo.InvariantCulture, DateTimeStyles.AdjustToUniversal | DateTimeStyles.AssumeUniversal, out var parsed))
		{
			return parsed.ToUniversalTime();
		}
		if (DateTime.TryParse(fallback, CultureInfo.InvariantCulture, DateTimeStyles.AdjustToUniversal | DateTimeStyles.AssumeUniversal, out parsed))
		{
			return parsed.ToUniversalTime();
		}
		return DateTime.MinValue;
	}

	private string LastRequestHistory(FamilyBrowserRequestRecord record)
	{
		if (record == null || record.History == null || record.History.Count == 0)
		{
			return "-";
		}
		return DisplayRequestHistory(record.History[checked(record.History.Count - 1)]);
	}

	private string DisplayRequestProgressNote(string note)
	{
		if (string.IsNullOrWhiteSpace(note))
		{
			return string.Empty;
		}
		string value = note;
		if (IsKorean())
		{
			value = value.Replace("Request registered.", "요청 등록 완료");
			value = value.Replace("Request registered", "요청 등록 완료");
			value = value.Replace("Submitted to BIM manager.", "BIM 관리자에게 접수");
			value = value.Replace("Review started.", "검토 시작");
			value = value.Replace("Approved for standard update.", "표준 반영 승인");
			value = value.Replace("Rejected. See reason.", "반려, 사유 확인 필요");
			value = value.Replace("Applied to standard library.", "표준 라이브러리 반영 완료");
			value = value.Replace("Status updated.", "진행 상태 변경");
		}
		else
		{
			value = value.Replace("요청 등록 완료", "Request registered");
			value = value.Replace("BIM 관리자에게 접수", "Submitted to BIM manager.");
			value = value.Replace("검토 시작", "Review started.");
			value = value.Replace("표준 반영 승인", "Approved for standard update.");
			value = value.Replace("반려, 사유 확인 필요", "Rejected. See reason.");
			value = value.Replace("표준 라이브러리 반영 완료", "Applied to standard library.");
			value = value.Replace("진행 상태 변경", "Status updated.");
		}
		return value;
	}

	private string DisplayRequestHistory(string history)
	{
		if (string.IsNullOrWhiteSpace(history))
		{
			return string.Empty;
		}
		string value = DisplayRequestProgressNote(history);
		if (!IsKorean())
		{
			value = value.Replace("등록 -> 접수", "Registered -> Submitted");
			value = value.Replace("접수 -> 검토중", "Submitted -> Reviewing");
			value = value.Replace("검토중 -> 승인", "Reviewing -> Approved");
			value = value.Replace("검토중 -> 반려", "Reviewing -> Rejected");
			value = value.Replace("승인 -> 완료", "Approved -> Completed");
			value = value.Replace("승인 -> 반려", "Approved -> Rejected");
			return value.Replace("반려 -> 재접수", "Rejected -> Submitted");
		}
		value = value.Replace("draft -> submitted", "등록 -> 접수");
		value = value.Replace("Draft -> Submitted", "등록 -> 접수");
		value = value.Replace("submitted -> reviewing", "접수 -> 검토중");
		value = value.Replace("Submitted -> Reviewing", "접수 -> 검토중");
		value = value.Replace("reviewing -> approved", "검토중 -> 승인");
		value = value.Replace("Reviewing -> Approved", "검토중 -> 승인");
		value = value.Replace("reviewing -> rejected", "검토중 -> 반려");
		value = value.Replace("Reviewing -> Rejected", "검토중 -> 반려");
		value = value.Replace("approved -> completed", "승인 -> 완료");
		value = value.Replace("Approved -> Completed", "승인 -> 완료");
		value = value.Replace("approved -> rejected", "승인 -> 반려");
		value = value.Replace("Approved -> Rejected", "승인 -> 반려");
		value = value.Replace("rejected -> submitted", "반려 -> 재접수");
		return value.Replace("Rejected -> Submitted", "반려 -> 재접수");
	}

	private static void AppendRequestCard(StringBuilder sb, string title, string body, string actionText, string actionName)
	{
		sb.AppendLine("<div class=\"request-card\">");
		sb.AppendLine("<strong>" + Html(title) + "</strong>");
		sb.AppendLine("<span>" + Html(body) + "</span>");
		sb.AppendLine("<a href=\"kkyfb:" + Attr(actionName) + "\">" + Html(actionText) + "</a>");
		sb.AppendLine("</div>");
	}

	private void AppendAuditPane(StringBuilder sb)
	{
		FamilyBrowserStandardPolicy policy = _standardPolicy ?? LoadStandardPolicy();
		sb.AppendLine("<div id=\"auditPane\" style=\"" + Attr(DashboardPaneDisplayStyle("audit")) + "\">");
		sb.AppendLine("<div class=\"request-pane-scroll list\">");
		AppendCheckMaintenanceWorkspace(sb, policy, includeSectionChrome: true);
		sb.AppendLine("</div>");
		sb.AppendLine("</div>");
	}

	private void AppendCheckMaintenanceWorkspace(StringBuilder sb, FamilyBrowserStandardPolicy policy, bool includeSectionChrome = false)
	{
		FamilyBrowserStandardLibrarySlot reviewTarget = ResolveBrowseSlot(policy);
		string targetLabel = ((reviewTarget == null) ? BuildPolicyTargetLabel() : ResolveSlotLabel(reviewTarget));
		if (includeSectionChrome)
		{
			sb.AppendLine("<div class=\"admin-box\">");
			sb.AppendLine("<div class=\"admin-section-eyebrow\">" + Html(T("Review", "검토")) + "</div>");
			sb.AppendLine("<div class=\"section\">" + Html(T("Current Model Check / Maintenance", "현재 모델 검사 / 유지관리")) + "</div>");
		}
		sb.AppendLine("<div class=\"settings-note compact\">" + Html(T("Choose the exact standard RVT target before checking or updating. This matters when multiple trades contain families with the same name.", "검사 또는 업데이트 전에 기준이 될 표준 RVT 대상을 정확히 선택하세요. 공종별 표준에 같은 이름의 패밀리가 있을 수 있어서 중요합니다.")) + "</div>");
		AppendAdminRow(sb, T("Selected review target", "선택된 검사 기준"), targetLabel);
		AppendAdminRow(sb, T("Current project rule", "현재 프로젝트 규칙"), CurrentProjectPolicyRuleLabel(policy));
		AppendAdminRow(sb, T("Request store detail", "요청 저장소 상세"), ResolveRequestStoreReadiness(policy));
		sb.AppendLine("<div class=\"settings-action-grid\">");
		AppendSettingsActionGroupStart(sb, T("Health Checks", "상태 점검"), T("Run Current Model Check against one selected standard RVT target. It reads the open project and compares it to that target's cached standard snapshot.", "현재 모델 검사는 선택한 표준 RVT 하나를 기준으로 실행합니다. 열려 있는 프로젝트를 읽고 해당 기준의 캐시된 표준 스냅샷과 비교합니다."));
		AppendTargetActionLinks(sb, policy, "refresh-target", T("Project Check", "프로젝트 검사"), emphasizeSelected: true);
		AppendTargetActionLinks(sb, policy, "preflight-target", T("System Type Diagnostics", "시스템 타입 정밀 진단"));
		AppendSettingsActionLink(sb, "kkyfb:stamp", T("Stamp Tracking", "추적 스탬프"));
		AppendSettingsActionLink(sb, "kkyfb:tracking", T("Check Tracking", "추적 확인"));
		AppendSettingsActionGroupEnd(sb);
		AppendSettingsActionGroupStart(sb, T("Standard Family Maintenance", "표준 패밀리 유지관리"), T("Admin-only update for families already loaded in this project. Choose the standard RVT target first; missing standard families are not created here.", "관리자 전용입니다. 기준 표준 RVT 대상을 먼저 선택합니다. 현재 프로젝트에 이미 로드된 패밀리만 표준 기준으로 업데이트하고, 누락 패밀리는 새로 로드하지 않습니다."));
		AppendTargetActionLinks(sb, policy, "sync-families-target", T("Update Existing Families", "기존 패밀리 업데이트"), emphasizeSelected: true);
		AppendSettingsActionGroupEnd(sb);
		sb.AppendLine("</div>");
		if (includeSectionChrome)
		{
			sb.AppendLine("</div>");
		}
	}

	private void AppendCurrentModelDirtySection(StringBuilder sb)
	{
		ProjectTrackingDirtyMarker marker = ProjectTrackingStoreService.LoadCurrentModelCheckMarker(GetActiveDocument());
		if (marker == null)
		{
			return;
		}
		sb.AppendLine("<div class=\"section\">" + Html(T("Protected Deletion Review", "보호 항목 삭제 검토")) + "<span class=\"admin-note\">" + Html(T("Current Model Check required", "현재 모델 검사 필요")) + "</span></div>");
		sb.AppendLine("<div class=\"hint\" style=\"margin-bottom:14px\">" + Html(T("Protected family/type deletion was detected. Deleted items may not be restored automatically. Run Current Model Check, then restore missing items from the standard RVT.", "관리 대상 패밀리/타입 삭제가 감지되었습니다. 삭제된 항목은 자동으로 되돌릴 수 없을 수 있습니다. 현재 모델 검사를 실행한 뒤 표준 RVT 기준으로 누락 항목을 복구하세요.")) + "</div>");
		sb.AppendLine("<div class=\"admin-actions\" style=\"margin-bottom:18px\">");
		sb.AppendLine("<a class=\"tool primary\" href=\"kkyfb:refresh\">" + Html(T("Run Current Model Check", "현재 모델 검사 실행")) + "</a>");
		sb.AppendLine("</div>");
		sb.AppendLine("<table id=\"dirtyTable\" style=\"margin-bottom:26px\">");
		sb.AppendLine("<tr><th style=\"width:170px\">" + Html(T("Detected", "감지 시각")) + "</th><th style=\"width:170px\">" + Html(T("User", "사용자")) + "</th><th style=\"width:190px\">" + Html(T("Kind", "구분")) + "</th><th style=\"width:300px\">" + Html(T("Name", "이름")) + "</th><th style=\"width:230px\">" + Html(T("Category", "카테고리")) + "</th><th style=\"width:130px\">" + Html(T("Element Id", "요소 ID")) + "</th><th>" + Html(T("Action Needed", "필요 작업")) + "</th></tr>");
		if (marker.Items == null || marker.Items.Count == 0)
		{
			AppendEmptyTableRow(sb, 7, T("Protected deletion marker exists, but no item details were recorded", "보호 항목 삭제 표시가 있지만 항목 세부 정보가 기록되지 않았습니다"), T("Run Current Model Check and compare against the registered standard.", "현재 모델 검사를 실행하고 등록된 표준과 비교하세요."));
		}
		else
		{
			foreach (ProjectTrackingDirtyItem item in marker.Items)
			{
				sb.Append("<tr>");
				sb.Append("<td>" + Html(FormatUtcStamp(marker.DetectedAtUtc)) + "</td>");
				sb.Append("<td>" + Html(marker.User) + "</td>");
				sb.Append("<td>" + Html(DisplayDirtyKind(item.Kind)) + "</td>");
				sb.Append("<td>" + Html(item.Name) + "</td>");
				sb.Append("<td>" + Html(item.CategoryName) + "</td>");
				sb.Append("<td>" + Html(item.ElementIdText) + "</td>");
				sb.Append("<td><span class=\"badge warn\">" + Html(DisplayDirtyRequiredAction(item.RequiredAction)) + "</span><div class=\"muted\">" + Html(DisplayDirtyRecoveryStatus(item.RecoveryStatus)) + "</div></td>");
				sb.AppendLine("</tr>");
			}
		}
		sb.AppendLine("</table>");
	}

	private string DisplayDirtyKind(string kind)
	{
		return Normalize(kind) switch
		{
			"family" => T("Family", "패밀리"), 
			"loadablefamilytype" => T("Loadable Family Type", "로더블 패밀리 타입"), 
			"systemtype" => T("System Type", "시스템 타입"), 
			_ => string.IsNullOrWhiteSpace(kind) ? "-" : kind, 
		};
	}

	private string DisplayDirtyRequiredAction(string action)
	{
		string left = Normalize(action);
		if (Operators.CompareString(left, "currentmodelcheckrequired", TextCompare: false) == 0)
		{
			return T("Run Current Model Check", "현재 모델 검사 실행");
		}
		return string.IsNullOrWhiteSpace(action) ? T("Admin review required", "관리자 검토 필요") : action;
	}

	private string DisplayDirtyRecoveryStatus(string status)
	{
		string left = Normalize(status);
		if (Operators.CompareString(left, "needsadminrestorefromstandard", TextCompare: false) == 0)
		{
			return T("Restore from standard RVT", "표준 RVT 기준 복구 필요");
		}
		return string.IsNullOrWhiteSpace(status) ? T("Manual review", "수동 검토") : status;
	}

	private void AppendFingerprintDifferenceSection(StringBuilder sb)
	{
		List<BrowserRow> fingerprintLoadables = _loadableRows.Where([SpecialName] (BrowserRow x) => IsFingerprintDifferentStatus(x.RawStatus)).OrderBy([SpecialName] (BrowserRow x) => Normalize(x.Category) + "|" + Normalize(x.Name), StringComparer.Ordinal).ToList();
		List<SystemRow> fingerprintSystems = _systemComparisonRows.Where([SpecialName] (SystemRow x) => IsFingerprintDifferentStatus(x.RawStatus)).OrderBy([SpecialName] (SystemRow x) => Normalize(x.Category) + "|" + Normalize(x.Name), StringComparer.Ordinal).ToList();
		sb.AppendLine("<div class=\"section\">" + Html(T("Fingerprint Differences", "Fingerprint 차이 항목")) + "<span class=\"admin-note\">" + Html(T("Admin overwrite review", "관리자 덮어쓰기 검토")) + "</span></div>");
		sb.AppendLine("<div class=\"request-context\">" + Html(_projectScanText) + "</div>");
		sb.AppendLine("<div class=\"hint\" style=\"margin-bottom:14px\">" + Html(T("These loaded project items have a different fingerprint from the registered standard and are candidates for admin overwrite.", "현재 프로젝트에 로드되어 있지만 등록된 표준과 fingerprint가 다른 항목입니다. 관리자가 표준 기준으로 덮어쓰기 검토할 대상입니다.")) + "</div>");
		sb.AppendLine("<div class=\"admin-actions\" style=\"margin-bottom:18px\">");
		sb.AppendLine("<a class=\"tool primary\" href=\"kkyfb:refresh\">" + Html(T("Run Current Model Check", "현재 모델 검사 실행")) + "</a>");
		sb.AppendLine(ToolActionLink("apply-systems", T("Bulk Apply Standard System Types", "표준 시스템 타입 일괄 적용"), primary: false, HasPermission("ManagePolicy") && HasPermission("ApplySystemTypes")));
		sb.AppendLine("</div>");
		sb.AppendLine("<table id=\"auditTable\">");
		sb.AppendLine("<tr><th style=\"width:190px\">" + Html(T("Kind", "구분")) + "</th><th style=\"width:230px\">" + Html(T("Status", "상태")) + "</th><th style=\"width:340px\">" + Html(T("Name", "이름")) + "</th><th style=\"width:260px\">" + Html(T("Category", "카테고리")) + "</th><th>" + Html(T("Notes", "메모")) + "</th></tr>");
		if (fingerprintLoadables.Count != 0 || fingerprintSystems.Count != 0)
		{
			foreach (BrowserRow row in fingerprintLoadables)
			{
				AppendAuditDifferenceRow(sb, T("Loadable Family", "로더블 패밀리"), row.Status, row.RawStatus, row.Name, row.Category, row.Action, row.Notes, row.ChangeSummary);
			}
			foreach (SystemRow row2 in fingerprintSystems)
			{
				AppendAuditDifferenceRow(sb, T("System Type", "시스템 타입"), row2.Status, row2.RawStatus, row2.Name, row2.Category, row2.Action, row2.Notes, row2.Notes);
			}
		}
		else
		{
			AppendEmptyTableRow(sb, 5, T("No fingerprint differences are listed", "표시할 fingerprint 차이 항목이 없습니다"), T("Run Current Model Check to refresh comparison results. Active project changes only update document and policy state so large central files open faster.", "비교 결과를 새로고침하려면 현재 모델 검사를 실행하세요. 활성 프로젝트 변경 시에는 큰 센트럴 파일이 빠르게 열리도록 문서와 정책 상태만 갱신합니다."));
		}
		sb.AppendLine("</table>");
		sb.AppendLine("<div class=\"section\" style=\"margin-top:28px\">" + Html(T("Other Review Items", "기타 검토 항목")) + "</div>");
	}

	private static void AppendAuditDifferenceRow(StringBuilder sb, string kind, string status, string rawStatus, string name, string category, string action, string notes, string changes)
	{
		sb.Append("<tr class=\"data\" onclick=\"selectRow(this)\"");
		sb.Append(" data-raw=\"" + Attr(rawStatus) + "\"");
		sb.Append(" data-status=\"" + Attr(status) + "\"");
		sb.Append(" data-name=\"" + Attr(name) + "\"");
		sb.Append(" data-category=\"" + Attr(category) + "\"");
		sb.Append(" data-action=\"" + Attr(action) + "\"");
		sb.Append(" data-notes=\"" + Attr(notes) + "\"");
		sb.Append(" data-approved=\"-\"");
		sb.Append(" data-loaded=\"-\"");
		sb.Append(" data-changes=\"" + Attr(changes) + "\"");
		sb.Append(" data-kind=\"" + Attr(kind) + "\"");
		sb.Append(" data-parameters=\"\"");
		sb.Append(" data-preview=\"\">");
		sb.Append("<td>" + Html(kind) + "</td>");
		sb.Append("<td><span class=\"badge " + StatusClass(rawStatus) + "\">" + Html(status) + "</span></td>");
		sb.Append("<td>" + Html(name) + "</td>");
		sb.Append("<td>" + Html(category) + "</td>");
		sb.Append("<td>" + Html(notes) + "</td>");
		sb.AppendLine("</tr>");
	}

	private void AppendPermissionPane(StringBuilder sb)
	{
		FamilyBrowserStandardPolicy policy = _standardPolicy ?? LoadStandardPolicy();
		string currentUser = CurrentUserIdentity();
		FamilyBrowserProjectPolicyContext context = CurrentProjectPolicyContext();
		FamilyBrowserPermissionExcelDiagnostic diagnostic = null;
		string roleLabel = CurrentSecurityRoleLabel(policy);
		FamilyBrowserFileGuardPolicy fileGuard = policy?.FileGuard ?? FamilyBrowserFileGuardPolicy.CreateDefault();
		int fileGuardTargetCount = (fileGuard.Targets ?? new List<FamilyBrowserFileGuardTarget>()).Where([SpecialName] (FamilyBrowserFileGuardTarget x) => x?.Enabled ?? false).Count();
		sb.AppendLine("<div id=\"permissionsPane\" style=\"" + Attr(DashboardPaneDisplayStyle("permissions")) + "\">");
		sb.AppendLine("<div class=\"request-pane-scroll\">");
		sb.AppendLine("<div class=\"section\">" + Html(T("Permission / Native Command Guard", "권한 / Revit 기본 명령 차단")) + "</div>");
		sb.AppendLine("<div class=\"hint\" style=\"margin-bottom:14px\">" + Html(T("Homepage admin keywords grant full access. Non-admin users follow the file-specific Revit native command guard.", "홈페이지 관리자 키워드는 전체 권한을 부여합니다. 비관리자는 파일별 Revit 기본 명령 차단 설정을 따릅니다.")) + "</div>");
		sb.AppendLine("<div class=\"diagnostic-grid\">");
		AppendDiagnosticCard(sb, T("Current User", "현재 사용자"), currentUser, roleLabel);
		AppendDiagnosticCard(sb, T("Current Model", "현재 모델"), string.IsNullOrWhiteSpace(context.ProjectTitle) ? "-" : context.ProjectTitle, string.IsNullOrWhiteSpace(context.CentralPath) ? context.ModelPath : context.CentralPath);
		AppendDiagnosticCard(sb, T("File-specific Guard", "파일별 권한 적용"), fileGuard.Enabled ? T("Enabled", "사용 중") : T("Disabled", "사용 안 함"), T("Targets: ", "대상: ") + fileGuardTargetCount.ToString(CultureInfo.InvariantCulture) + (string.IsNullOrWhiteSpace(fileGuard.RootFolder) ? string.Empty : (" / " + fileGuard.RootFolder)));
		AppendDiagnosticCard(sb, T("Admin Rule", "관리자 기준"), T("Homepage profile keywords", "홈페이지 프로필 키워드"), T("Admin Mode ON bypasses modeler restrictions.", "관리자 모드 ON이면 모델러 제한을 우회합니다."));
		sb.AppendLine("</div>");
		sb.AppendLine("<div class=\"permission-note\">");
		sb.AppendLine("<b>" + Html(T("How to read this", "읽는 방법")) + "</b><br />");
		sb.AppendLine(Html(T("The guard controls two Revit native command groups: Load/Edit Family and Add/Delete/Rename Types. Family Browser add-in buttons and admin access follow the homepage admin keyword policy.", "차단 설정은 Revit 기본 명령 두 그룹을 제어합니다: 패밀리 로드/편집과 타입 추가/삭제/이름 변경. Family Browser 버튼과 관리자 권한은 홈페이지 관리자 키워드 정책을 따릅니다.")));
		sb.AppendLine("</div>");
		sb.AppendLine("<div class=\"admin-actions\" style=\"margin-bottom:10px\">");
		sb.AppendLine("<a class=\"tool primary\" href=\"kkyfb:permission-check\">" + Html(T("Check Current Permission", "현재 권한 확인")) + "</a>");
		sb.AppendLine("<a class=\"tool\" href=\"kkyfb:file-guard-config\">" + Html(T("Configure File-specific Guard", "파일별 권한 적용 설정")) + "</a>");
		sb.AppendLine(ToolTabLink("admin", T("Admin Settings", "관리자 설정"), primary: false, CanViewAdminTab()));
		sb.AppendLine("</div>");
		sb.AppendLine("<table id=\"permissionsTable\">");
		sb.AppendLine("<tr><th style=\"width:240px\">" + Html(T("Guarded Revit Command", "보호 대상 Revit 명령")) + "</th><th style=\"width:120px\">" + Html(T("Result", "결과")) + "</th><th style=\"width:120px\">" + Html(T("O/X", "O/X")) + "</th><th style=\"width:210px\">" + Html(T("Source", "판정 기준")) + "</th><th>" + Html(T("Notes", "메모")) + "</th></tr>");
		string[] array = PermissionDiagnosticOrder();
		foreach (string permission in array)
		{
			AppendPermissionDiagnosticRow(sb, policy, context, currentUser, diagnostic, permission);
		}
		sb.AppendLine("</table>");
		sb.AppendLine("</div>");
		sb.AppendLine("</div>");
	}

	private void AppendPermissionDiagnosticRow(StringBuilder sb, FamilyBrowserStandardPolicy policy, FamilyBrowserProjectPolicyContext context, string currentUser, FamilyBrowserPermissionExcelDiagnostic diagnostic, string permission)
	{
		bool num = FamilyBrowserSecurityPolicyService.Can(policy, currentUser, permission, context, diagnostic);
		string token = PermissionExcelToken(diagnostic, permission);
		bool isAdmin = string.Equals(FamilyBrowserSecurityPolicyService.ResolveRole(policy, currentUser, context, diagnostic), "Admin", StringComparison.OrdinalIgnoreCase);
		string source = PermissionDecisionSource(diagnostic, permission, token, isAdmin);
		string notes = PermissionDecisionNotes(diagnostic, permission, token, isAdmin);
		string statusText = (num ? T("Allowed", "허용") : T("Blocked", "차단"));
		string rawStatus = (num ? "Allowed" : "Blocked");
		string tone = (num ? "good" : "bad");
		sb.AppendLine("<tr class=\"data\" data-raw=\"" + Attr(rawStatus) + "\" data-name=\"" + Attr(PermissionLabel(permission)) + "\" data-category=\"" + Attr(T("Permission", "권한")) + "\" data-status=\"" + Attr(statusText) + "\" data-action=\"" + Attr(source) + "\" data-notes=\"" + Attr(notes) + "\" data-approved=\"-\" data-loaded=\"-\" data-changes=\"" + Attr(T("Final result: ", "최종 결과: ") + statusText) + "\" data-parameters=\"" + Attr(T("Excel cell: ", "Excel 셀: ") + (string.IsNullOrWhiteSpace(token) ? "-" : token)) + "\" data-preview=\"\" onclick=\"selectRow(this)\">");
		sb.AppendLine("<td>" + Html(PermissionLabel(permission)) + "</td>");
		sb.AppendLine("<td><span class=\"badge " + tone + "\">" + Html(statusText) + "</span></td>");
		sb.AppendLine("<td>" + Html(string.IsNullOrWhiteSpace(token) ? "-" : token) + "</td>");
		sb.AppendLine("<td>" + Html(source) + "</td>");
		sb.AppendLine("<td>" + Html(notes) + "</td>");
		sb.AppendLine("</tr>");
	}

	private static string[] PermissionDiagnosticOrder()
	{
		return new string[2] { "EditFamilies", "AddDeleteTypes" };
	}

	private string PermissionLabel(string permission)
	{
		return permission switch
		{
			"LoadFamilies" => T("Load Families", "패밀리 로드"), 
			"ApplySystemTypes" => T("Load System Types", "시스템 타입 로드"), 
			"CreateRequest" => T("Create Request", "요청 작성"), 
			"SubmitRequest" => T("Submit Request", "요청 접수"), 
			"ApproveRequest" => T("Approve Request", "요청 승인"), 
			"RegisterStandard" => T("Connect Standard RVT", "표준 RVT 연결"), 
			"ManagePolicy" => T("Manage Policy", "정책 관리"), 
			"StampTracking" => T("Stamp Tracking", "추적 스탬프"), 
			"EditFamilies" => T("Load/Edit Family", "패밀리 로드/편집"), 
			"AddDeleteTypes" => T("Add/Delete Types", "타입 추가/삭제"), 
			_ => string.IsNullOrWhiteSpace(permission) ? "-" : permission, 
		};
	}

	private static string PermissionExcelToken(FamilyBrowserPermissionExcelDiagnostic diagnostic, string permission)
	{
		if (diagnostic == null || diagnostic.PermissionTokens == null)
		{
			return string.Empty;
		}
		if (diagnostic.PermissionTokens.ContainsKey(permission))
		{
			return diagnostic.PermissionTokens[permission];
		}
		if (string.Equals(permission, "SubmitRequest", StringComparison.OrdinalIgnoreCase) && diagnostic.PermissionTokens.ContainsKey("CreateRequest"))
		{
			return diagnostic.PermissionTokens["CreateRequest"];
		}
		return string.Empty;
	}

	private string PermissionDecisionSource(FamilyBrowserPermissionExcelDiagnostic diagnostic, string permission, string token, bool isAdmin)
	{
		if (isAdmin)
		{
			return T("Homepage admin", "홈페이지 관리자");
		}
		if (diagnostic != null && diagnostic.Matched && !string.IsNullOrWhiteSpace(token))
		{
			return T("Excel row ", "Excel 행 ") + diagnostic.MatchedRowNumber.ToString(CultureInfo.InvariantCulture);
		}
		if (diagnostic != null && diagnostic.Matched)
		{
			return T("Excel row matched", "Excel 행 매칭");
		}
		return T("File guard / default", "파일별 권한 / 기본값");
	}

	private string PermissionDecisionNotes(FamilyBrowserPermissionExcelDiagnostic diagnostic, string permission, string token, bool isAdmin)
	{
		if (isAdmin)
		{
			return T("Admin users have full access while Admin Mode is on.", "관리자는 관리자 모드 ON 상태에서 전체 권한을 가집니다.");
		}
		if (diagnostic == null || !diagnostic.Enabled)
		{
			return T("Non-admin users follow file-specific guard settings. If the current model is not listed, Revit native commands remain allowed by default.", "비관리자는 파일별 권한 적용 설정을 따릅니다. 현재 모델이 대상에 없으면 Revit 기본 명령은 기본적으로 허용됩니다.");
		}
		if (!diagnostic.Matched && string.IsNullOrWhiteSpace(diagnostic.LastError) && diagnostic.RowCount == 0 && !diagnostic.Exists && !string.IsNullOrWhiteSpace(diagnostic.SourcePath))
		{
			return T("Not checked yet. Click Check Current Permission to read the Excel file.", "아직 확인하지 않았습니다. 현재 권한 확인을 누르면 Excel 파일을 읽습니다.");
		}
		if (!string.IsNullOrWhiteSpace(diagnostic.LastError))
		{
			return diagnostic.LastError;
		}
		if (diagnostic.Matched && !string.IsNullOrWhiteSpace(token))
		{
			return T("Explicit O/X value from the matched Excel row.", "매칭된 Excel 행의 명시 O/X 값입니다.");
		}
		if (diagnostic.Matched)
		{
			return T("Excel row matched, but this O/X cell is blank. The guarded command remains blocked for non-admin users.", "Excel 행은 매칭됐지만 이 O/X 셀이 비어 있습니다. 비관리자는 해당 보호 명령이 차단됩니다.");
		}
		return T("No Excel row matched both this model and this user, so the guarded command remains blocked for non-admin users.", "현재 모델과 사용자를 동시에 만족하는 Excel 행이 없어 비관리자는 해당 보호 명령이 차단됩니다.");
	}

	private void AppendDiagnosticCard(StringBuilder sb, string title, string value, string body)
	{
		sb.AppendLine("<div class=\"diagnostic-card\">");
		sb.AppendLine("<strong>" + Html(title) + "</strong>");
		sb.AppendLine("<span>" + Html(string.IsNullOrWhiteSpace(value) ? "-" : value) + "</span>");
		sb.AppendLine("<span>" + Html(string.IsNullOrWhiteSpace(body) ? "-" : body) + "</span>");
		sb.AppendLine("</div>");
	}

	private string PermissionExcelStatusTitle(FamilyBrowserPermissionExcelDiagnostic diagnostic)
	{
		if (diagnostic == null || !diagnostic.Enabled)
		{
			return T("Not connected", "미연결");
		}
		if (string.IsNullOrWhiteSpace(diagnostic.LastError) && diagnostic.RowCount == 0 && !diagnostic.Exists && !string.IsNullOrWhiteSpace(diagnostic.SourcePath))
		{
			return T("Not checked", "미확인");
		}
		if (!string.IsNullOrWhiteSpace(diagnostic.LastError) || !diagnostic.Exists)
		{
			return T("Blocked", "차단");
		}
		return T("Connected", "연결됨");
	}

	private string PermissionExcelStatusBody(FamilyBrowserPermissionExcelDiagnostic diagnostic)
	{
		if (diagnostic == null)
		{
			return "-";
		}
		if (!diagnostic.Enabled)
		{
			return T("JSON/project policy is active.", "JSON/프로젝트 정책이 적용됩니다.");
		}
		if (!string.IsNullOrWhiteSpace(diagnostic.LastError))
		{
			return diagnostic.LastError;
		}
		if (diagnostic.RowCount == 0 && !diagnostic.Exists && !string.IsNullOrWhiteSpace(diagnostic.SourcePath))
		{
			return string.IsNullOrWhiteSpace(diagnostic.Message) ? T("Click Check Current Permission to read the Excel file.", "현재 권한 확인을 누르면 Excel 파일을 읽습니다.") : diagnostic.Message;
		}
		if (!diagnostic.Exists)
		{
			return T("Excel file was not found.", "Excel 파일을 찾을 수 없습니다.");
		}
		return diagnostic.RowCount.ToString(CultureInfo.InvariantCulture) + T(" row(s), active ", " 행, 활성 ") + diagnostic.ActiveRowCount.ToString(CultureInfo.InvariantCulture);
	}

	private string PermissionMatchedRowBody(FamilyBrowserPermissionExcelDiagnostic diagnostic)
	{
		if (diagnostic == null || !diagnostic.Matched)
		{
			return "-";
		}
		List<string> parts = new List<string>();
		if (!string.IsNullOrWhiteSpace(diagnostic.MatchedRole))
		{
			parts.Add(T("Role ", "역할 ") + diagnostic.MatchedRole);
		}
		if (!string.IsNullOrWhiteSpace(diagnostic.MatchedUser))
		{
			parts.Add(T("User ", "사용자 ") + diagnostic.MatchedUser);
		}
		if (!string.IsNullOrWhiteSpace(diagnostic.MatchedMode) || !string.IsNullOrWhiteSpace(diagnostic.MatchedValue))
		{
			parts.Add(diagnostic.MatchedMode + " " + diagnostic.MatchedValue);
		}
		if (parts.Count == 0)
		{
			return diagnostic.Message;
		}
		return string.Join(" / ", parts);
	}

	private string ResolveRequestStoreLabel(FamilyBrowserStandardPolicy policy)
	{
		FamilyBrowserRequestStoreSettings settings = policy?.RequestStore;
		switch (FamilyBrowserPolicyKey.Normalize((settings == null || string.IsNullOrWhiteSpace(settings.Mode)) ? "Local" : settings.Mode))
		{
		case "networkshare":
		case "network-share":
			return T("Network share", "네트워크 공유");
		case "sharepoint":
		case "share-point":
			return T("SharePoint connector", "SharePoint 커넥터");
		case "cloudstorage":
		case "cloud-storage":
			return T("Cloud storage connector", "클라우드 저장소 커넥터");
		case "api":
			return T("Internal API / DB connector", "내부 API / DB 커넥터");
		default:
			return T("Local test store", "로컬 테스트 저장소");
		}
	}

	private string ResolvePolicyDeploymentLabel()
	{
		FamilyBrowserMachineConfig config = FamilyBrowserMachineConfigStore.Load();
		if (config.UseManagedPolicy && !string.IsNullOrWhiteSpace(config.ManagedPolicyPath))
		{
			if (FamilyBrowserDeploymentBootstrapService.IsBootstrapDisabled(config.DeploymentBootstrapUrl))
			{
				return T("Homepage connection disabled locally", "홈페이지 연결이 이 PC에서 비활성화됨");
			}
			return T("Managed shared policy", "공용 관리 정책");
		}
		return T("Local policy on this PC", "이 PC의 로컬 정책");
	}

	private string ResolveManagedFolderLabel()
	{
		FamilyBrowserMachineConfig config = FamilyBrowserMachineConfigStore.Load();
		string managedRoot = ResolveManagedRootFolderForDisplay();
		if (string.IsNullOrWhiteSpace(managedRoot))
		{
			return T("Not connected yet. Refresh the homepage path to use the first reachable managed folder.", "아직 연결되지 않았습니다. 홈페이지 경로를 다시 확인하면 접근 가능한 첫 관리 폴더를 사용합니다.");
		}
		if (FamilyBrowserDeploymentBootstrapService.IsBootstrapDisabled(config.DeploymentBootstrapUrl))
		{
			return T("Local managed folder override: ", "로컬 관리 폴더 우선 설정: ") + managedRoot;
		}
		return T("Connected managed folder: ", "연결된 관리 폴더: ") + managedRoot;
	}

	private string ResolveManagedRootFolderForDisplay()
	{
		string policyPath = FamilyBrowserMachineConfigStore.ResolveManagedPolicyPath();
		if (string.IsNullOrWhiteSpace(policyPath) && _deploymentBootstrapResult != null)
		{
			policyPath = _deploymentBootstrapResult.ManagedPolicyPath ?? string.Empty;
		}
		return ExtractManagedRootFolder(policyPath);
	}

	private static string ExtractManagedRootFolder(string policyPath)
	{
		string ExtractManagedRootFolder;
		try
		{
			string expandedPath = Environment.ExpandEnvironmentVariables((policyPath ?? string.Empty).Trim());
			string policyFolder;
			if (string.IsNullOrWhiteSpace(expandedPath))
			{
				ExtractManagedRootFolder = string.Empty;
			}
			else
			{
				policyFolder = Path.GetDirectoryName(expandedPath);
				if (string.IsNullOrWhiteSpace(policyFolder))
				{
					ExtractManagedRootFolder = string.Empty;
				}
				else
				{
					string trimmedFolder = policyFolder.TrimEnd(Path.DirectorySeparatorChar, Path.AltDirectorySeparatorChar);
					if (!string.Equals(Path.GetFileName(trimmedFolder), "Config", StringComparison.OrdinalIgnoreCase))
					{
						goto IL_0093;
					}
					DirectoryInfo parent = Directory.GetParent(trimmedFolder);
					if (parent == null || string.IsNullOrWhiteSpace(parent.FullName))
					{
						goto IL_0093;
					}
					ExtractManagedRootFolder = parent.FullName;
				}
			}
			goto end_IL_0000;
			IL_0093:
			ExtractManagedRootFolder = policyFolder;
			end_IL_0000:;
		}
		catch (Exception projectError)
		{
			ProjectData.SetProjectError(projectError);
			ExtractManagedRootFolder = string.Empty;
			ProjectData.ClearProjectError();
		}
		return ExtractManagedRootFolder;
	}

	private string ResolveDeploymentBootstrapLabel()
	{
		string bootstrapUrl = (FamilyBrowserMachineConfigStore.Load().DeploymentBootstrapUrl ?? string.Empty).Trim();
		if (string.Equals(bootstrapUrl, "disabled", StringComparison.OrdinalIgnoreCase))
		{
			return T("Homepage connection is disabled locally. Use Check Homepage Path Again to restore the homepage-managed folder.", "이 PC에서 홈페이지 연결이 비활성화되어 있습니다. 홈페이지 관리 폴더로 복구하려면 홈페이지 경로 다시 확인을 사용하세요.");
		}
		if (string.IsNullOrWhiteSpace(bootstrapUrl))
		{
			bootstrapUrl = "https://update.zerokky.com/family-browser/bootstrap.json";
		}
		string resultText = ResolveDeploymentBootstrapMessage();
		return T("Source: ", "소스: ") + bootstrapUrl + " / " + resultText;
	}

	private string ResolveDeploymentBootstrapMessage()
	{
		FamilyBrowserDeploymentBootstrapResult result = _deploymentBootstrapResult ?? FamilyBrowserDeploymentBootstrapService.GetLastResult();
		if (result == null)
		{
			return T("not checked yet", "아직 확인 전");
		}
		if (string.IsNullOrWhiteSpace(result.Message))
		{
			return T("checked", "확인됨");
		}
		return result.Message switch
		{
			"No deployment bootstrap was available." => T("no shared settings file found yet", "공유 설정 파일이 아직 없습니다"), 
			"Deployment bootstrap is disabled." => T("shared settings are disabled", "공유 설정이 비활성화되어 있습니다"), 
			"Deployment bootstrap was empty." => T("shared settings file was empty", "공유 설정 파일이 비어 있습니다"), 
			_ => result.Message, 
		};
	}

	private string ResolveHomepageSecurityRefreshMessage(string message)
	{
		if (string.IsNullOrWhiteSpace(message))
		{
			return T("checked", "확인됨");
		}
		return message switch
		{
			"Homepage security refreshed." => T("changed values were applied", "변경된 값이 적용되었습니다"), 
			"Homepage security unchanged." => T("no change", "변경 없음"), 
			"Homepage security settings were not configured." => T("admin profile keywords are not configured on the homepage", "홈페이지에 관리자 프로필 키워드가 설정되어 있지 않습니다"), 
			"Homepage security bootstrap was not reachable." => T("homepage bootstrap was not reachable", "홈페이지 설정 파일에 접근할 수 없습니다"), 
			"Homepage security refresh is disabled." => T("homepage refresh is disabled", "홈페이지 새로고침이 비활성화되어 있습니다"), 
			"Homepage security bootstrap is disabled." => T("homepage bootstrap is disabled", "홈페이지 설정 파일이 비활성화되어 있습니다"), 
			"Homepage security bootstrap was empty." => T("homepage bootstrap was empty", "홈페이지 설정 파일이 비어 있습니다"), 
			_ => message, 
		};
	}

	private string ResolvePolicyDeploymentReadiness()
	{
		FamilyBrowserMachineConfig config = FamilyBrowserMachineConfigStore.Load();
		string ResolvePolicyDeploymentReadiness;
		if (!config.UseManagedPolicy || string.IsNullOrWhiteSpace(config.ManagedPolicyPath))
		{
			ResolvePolicyDeploymentReadiness = ((_deploymentBootstrapResult == null || string.IsNullOrWhiteSpace(_deploymentBootstrapResult.ManagedPolicyPathIssue)) ? T("Homepage path is the source of truth. Refresh it to connect the first reachable managed folder.", "홈페이지 경로가 기준입니다. 새로고침하면 접근 가능한 첫 관리 폴더에 연결합니다.") : (T("Homepage path was checked, but no managed folder candidate was reachable: ", "홈페이지 경로를 확인했지만 접근 가능한 관리 폴더 후보가 없었습니다: ") + _deploymentBootstrapResult.ManagedPolicyPathIssue));
		}
		else
		{
			_ = string.Empty;
			try
			{
				if (string.IsNullOrWhiteSpace(Path.GetDirectoryName(Environment.ExpandEnvironmentVariables(config.ManagedPolicyPath))))
				{
					ResolvePolicyDeploymentReadiness = T("Managed policy path must be an absolute JSON file path.", "공용 정책 경로는 절대 JSON 파일 경로여야 합니다.");
					goto IL_0119;
				}
			}
			catch (Exception projectError)
			{
				ProjectData.SetProjectError(projectError);
				ResolvePolicyDeploymentReadiness = T("Managed policy path must be an absolute JSON file path.", "공용 정책 경로는 절대 JSON 파일 경로여야 합니다.");
				ProjectData.ClearProjectError();
				goto IL_0119;
			}
			ResolvePolicyDeploymentReadiness = (FamilyBrowserDeploymentBootstrapService.IsBootstrapDisabled(config.DeploymentBootstrapUrl) ? T("Homepage connection is disabled locally. Use Check Homepage Path Again to return to homepage-managed operation.", "이 PC에서 홈페이지 연결이 비활성화되어 있습니다. 홈페이지 관리 방식으로 돌아가려면 홈페이지 경로 다시 확인을 사용하세요.") : ((_deploymentBootstrapResult == null || !_deploymentBootstrapResult.Applied) ? T("Managed folder is configured locally. Refresh homepage path when you want to verify the latest server settings.", "이 PC에 관리 폴더가 설정되어 있습니다. 서버 설정을 다시 확인하려면 홈페이지 경로를 새로고침하세요.") : T("Connected through homepage settings. Users do not need to choose a path manually.", "홈페이지 설정으로 연결되었습니다. 일반 사용자는 경로를 직접 선택할 필요가 없습니다.")));
		}
		goto IL_0119;
		IL_0119:
		return ResolvePolicyDeploymentReadiness;
	}

	private string ResolveRequestStoreReadiness(FamilyBrowserStandardPolicy policy)
	{
		FamilyBrowserRequestStoreInfo info = FamilyBrowserRequestStore.GetRequestStoreInfo(_workspaceRoot, policy);
		if (info == null)
		{
			return T("Request store is not configured.", "요청 저장소가 설정되지 않았습니다.");
		}
		if (info.UsesConnectorQueue)
		{
			if (string.Equals(info.Mode, "Api", StringComparison.OrdinalIgnoreCase))
			{
				return T("Queue-ready. A server connector can later publish staged requests to the API endpoint.", "큐 저장 준비됨. 이후 서버 커넥터가 적재된 요청을 API 엔드포인트로 전송할 수 있습니다.");
			}
			return T("Queue-ready. Set a synced folder path when this must be visible to every installed user.", "큐 저장 준비됨. 설치 사용자 전체가 보려면 동기화 폴더 경로를 지정하세요.");
		}
		if (info.IsShared)
		{
			return T("Ready for team-wide request visibility if account and folder permissions are configured.", "계정과 폴더 권한이 설정되어 있으면 팀 전체 요청 현황 공유에 사용할 수 있습니다.");
		}
		return T("Works on this PC only. Use for demos and debugging.", "현재 PC에서만 동작합니다. 데모와 디버깅용입니다.");
	}

	private string ResolveRequestStorePaneHintClass(FamilyBrowserStandardPolicy policy)
	{
		FamilyBrowserRequestStoreInfo info = FamilyBrowserRequestStore.GetRequestStoreInfo(_workspaceRoot, policy);
		if (!CanSeeInternalPaths())
		{
			if (info == null || string.IsNullOrWhiteSpace(info.StoreLocation) || !IsRequestStoreLikelyReachable(policy))
			{
				return "warn";
			}
			return "good";
		}
		if (info == null || !info.IsShared || !IsRequestStoreLikelyReachable(policy))
		{
			return "warn";
		}
		return "good";
	}

	private string ResolveRequestStorePaneHint(FamilyBrowserStandardPolicy policy)
	{
		FamilyBrowserRequestStoreInfo info = FamilyBrowserRequestStore.GetRequestStoreInfo(_workspaceRoot, policy);
		if (!CanSeeInternalPaths())
		{
			if (info == null || string.IsNullOrWhiteSpace(info.StoreLocation))
			{
				return T("Request storage needs administrator setup.", "요청 저장소는 관리자 설정이 필요합니다.");
			}
			if (!IsRequestStoreLikelyReachable(policy))
			{
				return T("Request storage is not reachable. Ask an administrator to check it.", "요청 저장소에 연결할 수 없습니다. 관리자에게 확인을 요청하세요.");
			}
			return T("Requests are saved through the add-in. The storage path is hidden.", "요청은 애드인에서 저장됩니다. 저장 경로는 숨겨져 있습니다.");
		}
		if (info == null || string.IsNullOrWhiteSpace(info.StoreLocation))
		{
			return T("Request store not configured. Register Request will ask for a folder.", "요청 저장소 미설정. 요청 등록 시 폴더를 선택할 수 있습니다.");
		}
		if (!info.IsShared)
		{
			return T("Local test store only. Other PCs will not see these requests.", "로컬 테스트 저장소입니다. 다른 PC에서는 이 요청을 볼 수 없습니다.");
		}
		if (!IsRequestStoreLikelyReachable(policy))
		{
			return T("Shared request store not reachable. Register Request will ask for a folder.", "공유 요청 저장소 미연결. 요청 등록 시 폴더를 선택할 수 있습니다.");
		}
		return T("Shared request store connected.", "공유 요청 저장소 연결됨.");
	}

	private bool IsRequestStoreLikelyReachable(FamilyBrowserStandardPolicy policy)
	{
		FamilyBrowserRequestStoreInfo info = FamilyBrowserRequestStore.GetRequestStoreInfo(_workspaceRoot, policy);
		if (info == null || string.IsNullOrWhiteSpace(info.StoreLocation))
		{
			return false;
		}
		if (!info.IsFileBacked)
		{
			return true;
		}
		if (!info.IsShared)
		{
			return true;
		}
		string detail = string.Empty;
		return !FamilyBrowserRequestStoreBackendService.IsObviouslyUnavailable(info, ref detail);
	}

