	private void AppendAdminSetupFlow(StringBuilder sb, FamilyBrowserStandardPolicy policy)
	{
		FamilyBrowserStandardLibrarySlot slot = FamilyBrowserStandardPolicyStore.GetEffectiveSlot(policy);
		StandardLibraryRegistrationRecord registration = ((slot == null) ? null : TryLoadRegistrationForSlot(policy, slot));
		StandardRvtFileStampStatus standardStampStatus = BuildStandardRvtFileStampStatus(registration);
		string standardStatus = ((slot == null) ? T("Not selected", "선택 없음") : BuildPolicyTargetLabel());
		if (StandardRvtFileChanged(standardStampStatus))
		{
			standardStatus = standardStatus + " / " + T("RVT updated", "RVT 업데이트됨");
		}
		string standardListStatus;
		if (slot == null)
		{
			standardListStatus = T("No active target", "활성 대상 없음");
		}
		else
		{
			FamilyBrowserStandardListCatalog catalog = LoadStandardListCatalogForDashboard(slot, registration);
			standardListStatus = (FamilyBrowserStandardListService.IsFilteringEnabled(catalog) ? (T("Connected", "연결됨") + " / " + catalog.RowCount.ToString(CultureInfo.InvariantCulture) + T(" row(s)", " 행")) : (string.IsNullOrWhiteSpace(catalog.LastError) ? T("Optional, not connected", "선택 사항, 미연결") : catalog.LastError));
		}
		FamilyBrowserFileGuardPolicy fileGuard = policy?.FileGuard ?? FamilyBrowserFileGuardPolicy.CreateDefault();
		string fileGuardStatus = (fileGuard.Enabled ? (T("Enabled", "사용 중") + " / " + (fileGuard.Targets ?? new List<FamilyBrowserFileGuardTarget>()).Where([SpecialName] (FamilyBrowserFileGuardTarget x) => x?.Enabled ?? false).Count().ToString(CultureInfo.InvariantCulture) + T(" target(s)", "개 대상")) : T("Optional, not enabled", "선택 사항, 사용 안 함"));
		sb.AppendLine("<div class=\"admin-flow\">");
		AppendAdminFlowStep(sb, "1", T("Standard RVT", "표준 RVT"), standardStatus, (slot == null || StandardRvtFileChanged(standardStampStatus)) ? "warn" : "good");
		AppendAdminFlowStep(sb, "2", T("Standard List", "표준 목록"), standardListStatus, (slot == null) ? "warn" : "info");
		AppendAdminFlowStep(sb, "3", T("Request Store", "요청 저장소"), ResolveRequestStoreLabel(policy), IsRequestStoreLikelyReachable(policy) ? "good" : "warn");
		AppendAdminFlowStep(sb, "4", T("File-specific Guard", "파일별 권한 적용"), fileGuardStatus, fileGuard.Enabled ? "good" : "info");
		sb.AppendLine("</div>");
	}

	private static void AppendAdminFlowStep(StringBuilder sb, string number, string title, string value, string tone)
	{
		sb.AppendLine("<div class=\"admin-flow-step " + Attr(tone) + "\">");
		sb.AppendLine("<div class=\"admin-flow-number\">" + Html(number) + "</div>");
		sb.AppendLine("<div class=\"admin-flow-title\">" + Html(title) + "</div>");
		sb.AppendLine("<div class=\"admin-flow-value\">" + Html(string.IsNullOrWhiteSpace(value) ? "-" : value) + "</div>");
		sb.AppendLine("</div>");
	}

	private static void AppendSettingsActionGroupStart(StringBuilder sb, string title, string body)
	{
		sb.AppendLine("<div class=\"settings-action-group\">");
		sb.AppendLine("<div class=\"settings-action-title\">" + Html(title) + "</div>");
		sb.AppendLine("<div class=\"settings-action-body\">" + Html(body) + "</div>");
		sb.AppendLine("<div class=\"admin-actions compact\">");
	}

	private static void AppendSettingsActionLink(StringBuilder sb, string href, string label, bool primary = false, bool quiet = false)
	{
		string className = (primary ? "tool primary" : (quiet ? "tool quiet" : "tool"));
		sb.AppendLine("<a class=\"" + className + "\" href=\"" + Attr(href) + "\">" + Html(label) + "</a>");
	}

	private void AppendTargetActionLinks(StringBuilder sb, FamilyBrowserStandardPolicy policy, string actionPrefix, string actionLabel, bool emphasizeSelected = false)
	{
		List<FamilyBrowserStandardLibrarySlot> slots = GetBrowserStandardSlots(policy);
		if (slots.Count == 0)
		{
			AppendSettingsDisabledAction(sb, actionLabel, T("No standard target is configured.", "설정된 표준 대상이 없습니다."));
			return;
		}
		FamilyBrowserStandardLibrarySlot selectedSlot = ResolveBrowseSlot(policy);
		foreach (FamilyBrowserStandardLibrarySlot slot in slots)
		{
			if (slot != null)
			{
				StandardLibraryRegistrationRecord registration = TryLoadRegistrationForSlot(policy, slot);
				string slotLabel = ResolveSlotLabel(slot);
				string label = actionLabel + " · " + slotLabel;
				if (registration == null || string.IsNullOrWhiteSpace(registration.LastSnapshotPath))
				{
					AppendSettingsDisabledAction(sb, label, T("Register and scan this standard RVT first.", "이 표준 RVT를 먼저 등록/스캔하세요."));
					continue;
				}
				string href = "kkyfb:" + actionPrefix + "/" + Uri.EscapeDataString(ResolveSlotKey(slot));
				bool isSelected = selectedSlot != null && string.Equals(Normalize(ResolveSlotKey(selectedSlot)), Normalize(ResolveSlotKey(slot)), StringComparison.Ordinal);
				AppendSettingsActionLink(sb, href, label, emphasizeSelected && isSelected);
			}
		}
	}

	private static void AppendSettingsDisabledAction(StringBuilder sb, string label, string reason)
	{
		sb.AppendLine("<span class=\"tool disabled\" title=\"" + Attr(reason) + "\">" + Html(label) + "</span>");
	}

	private static void AppendSettingsActionGroupEnd(StringBuilder sb)
	{
		sb.AppendLine("</div>");
		sb.AppendLine("</div>");
	}

	private void AppendOperationalReadinessCompact(StringBuilder sb)
	{
		sb.AppendLine("<div class=\"request-status-strip\">");
		if (_readinessReport == null)
		{
			sb.AppendLine("<div class=\"request-status\"><strong>-</strong><span>" + Html(T("Not checked", "미확인")) + "</span></div>");
		}
		else
		{
			sb.AppendLine("<div class=\"request-status\"><strong>" + _readinessReport.BlockingCount.ToString(CultureInfo.InvariantCulture) + "</strong><span>" + Html(T("Blocked", "차단")) + "</span></div>");
			sb.AppendLine("<div class=\"request-status\"><strong>" + _readinessReport.WarningCount.ToString(CultureInfo.InvariantCulture) + "</strong><span>" + Html(T("Warnings", "주의")) + "</span></div>");
			sb.AppendLine("<div class=\"request-status\"><strong>" + _readinessReport.ReadyCount.ToString(CultureInfo.InvariantCulture) + "</strong><span>" + Html(T("Ready", "준비")) + "</span></div>");
		}
		sb.AppendLine("</div>");
		sb.AppendLine("<div class=\"permission-note\">" + Html(ReadinessBody()) + "</div>");
