		{
			AppendAdminRow(sb, T("Excel policy", "Excel 정책"), T("Not connected. Use project/default permission policy.", "미연결. 프로젝트/기본 권한 정책을 사용합니다."));
			return;
		}
		AppendAdminRow(sb, T("Excel policy", "Excel 정책"), T("Connected. The file is not parsed while rendering Settings; use Permission Diagnostic to test a row.", "연결됨. 설정 화면을 그릴 때는 파일을 파싱하지 않습니다. 행 검증은 권한 진단에서 실행하세요."));
		AppendAdminRow(sb, T("Excel path", "Excel 경로"), settings.Path);
