	private void AppendFileGuardCompact(StringBuilder sb, FamilyBrowserStandardPolicy policy)
	{
		FamilyBrowserFileGuardPolicy fileGuard = policy?.FileGuard;
		if (fileGuard == null || !fileGuard.Enabled)
		{
			AppendAdminRow(sb, T("File guards", "파일별 권한 적용"), T("Disabled. Native command blocking uses the global/default policy.", "비활성. Revit 기본 명령 차단은 전체/기본 정책을 따릅니다."));
			return;
		}
		List<FamilyBrowserFileGuardTarget> targets = (fileGuard.Targets ?? new List<FamilyBrowserFileGuardTarget>()).Where([SpecialName] (FamilyBrowserFileGuardTarget x) => x?.Enabled ?? false).ToList();
		int familyBlockCount = targets.Where([SpecialName] (FamilyBrowserFileGuardTarget x) => x.BlockFamilyLoadAndEdit).Count();
		int typeBlockCount = targets.Where([SpecialName] (FamilyBrowserFileGuardTarget x) => x.BlockTypeChanges).Count();
		AppendAdminRow(sb, T("File guards", "파일별 권한 적용"), T("Enabled", "활성") + " / " + targets.Count.ToString(CultureInfo.InvariantCulture) + T(" file(s)", "개 파일") + " / " + T("family guard ", "패밀리 차단 ") + familyBlockCount.ToString(CultureInfo.InvariantCulture) + " / " + T("type guard ", "타입 차단 ") + typeBlockCount.ToString(CultureInfo.InvariantCulture));
		if (!string.IsNullOrWhiteSpace(fileGuard.RootFolder))
		{
			AppendAdminRow(sb, T("Guard folder", "권한 적용 폴더"), fileGuard.RootFolder);
		}
	}

