		AppendAdminRow(sb, StandardRvtFileChanged(status) ? T("Standard RVT update", "표준 RVT 업데이트") : T("Standard RVT stamp", "표준 RVT 기록"), BuildStandardRvtUpdateSummary(status));
		if (includeDetails && status != null && status.Exists && !status.FileProbeSkipped)
		{
			if (status.HasAnyRecordedStamp)
			{
