	private string BuildStandardRvtUpdateSummary(StandardRvtFileStampStatus status)
	{
		if (status == null || !status.HasRegistration)
		{
			return T("No standard RVT has been registered for the active target.", "활성 대상에 등록된 표준 RVT가 없습니다.");
		}
		if (string.IsNullOrWhiteSpace(status.Path))
		{
			return T("The registered standard RVT path is empty.", "등록된 표준 RVT 경로가 비어 있습니다.");
		}
		if (!string.IsNullOrWhiteSpace(status.ErrorMessage))
		{
			return T("Could not check the standard RVT file stamp: ", "표준 RVT 파일 수정일을 확인하지 못했습니다: ") + status.ErrorMessage;
		}
		if (!status.Exists)
		{
			return T("The registered standard RVT file cannot be found: ", "등록된 표준 RVT 파일을 찾을 수 없습니다: ") + status.Path;
		}
		if (status.FileProbeSkipped)
		{
			return T("Showing the last registered standard RVT scan stamp. The source RVT file was not touched while rendering this screen.", "마지막 표준 RVT 등록/스캔 기록을 표시합니다. 이 화면을 그리는 동안 원본 RVT 파일에는 접근하지 않았습니다.");
		}
		if (!status.HasAnyRecordedStamp)
		{
			return StandardScanNeededUserAction();
		}
		if (status.ChangedSinceScan)
		{
			string reason = T("the file modified date differs from the recorded scan date", "파일 수정일이 기록된 스캔 날짜와 다름");
			return T("Action needed: the standard RVT changed after the last scan (", "조치 필요: 마지막 스캔 이후 표준 RVT가 변경되었습니다(") + reason + T("). Re-scan the selected standard RVT.", "). 선택 표준 RVT를 다시 스캔하세요.");
		}
		return T("No change detected since the last standard scan.", "마지막 표준 스캔 이후 파일 변경이 감지되지 않았습니다.");
	}

	private static bool StandardRvtFileChanged(StandardRvtFileStampStatus status)
	{
		if (status != null && status.Exists)
		{
			return status.ChangedSinceScan;
		}
		return false;
	}

	private static string FormatStandardRvtStamp(DateTime lastWriteUtc, long length)
	{
		return ((DateTime.Compare(lastWriteUtc, DateTime.MinValue) == 0) ? "-" : FormatUtcStamp(lastWriteUtc.ToUniversalTime().ToString("O", CultureInfo.InvariantCulture))) + " / " + FormatFileLength(length);
	}

	private static string FormatFileLength(long length)
	{
		if (length <= 0)
		{
			return "-";
		}
		return length.ToString("N0", CultureInfo.InvariantCulture) + " bytes";
	}

	private static void AppendSimpleCard(StringBuilder sb, string title, string value, string body)
	{
		sb.AppendLine("<div class=\"simple-card\">");
