		sb.AppendLine("<span>" + Html(string.IsNullOrWhiteSpace(value) ? "-" : value) + "</span>");
		sb.AppendLine("<span>" + Html(string.IsNullOrWhiteSpace(body) ? "-" : body) + "</span>");
		sb.AppendLine("</div>");
	}

