			AppendAdminRow(sb, T("Review report", "검토 리포트"), string.IsNullOrWhiteSpace(_lastPreflightPath) ? "-" : _lastPreflightPath);
			sb.AppendLine("</div>");
			sb.AppendLine("<div class=\"admin-box\">");
			sb.AppendLine("<div class=\"section\">" + Html(T("Registered Libraries", "등록된 표준 RVT")) + "</div>");
