			AppendAdminRow(sb, T("Path details", "경로 상세"), InternalPathHiddenLabel());
			AppendAdminRow(sb, T("Next action", "다음 작업"), T("Ask an administrator to open Admin Settings or Help / Technical Details for exact paths and diagnostics.", "정확한 경로와 진단 정보는 관리자에게 관리자 설정 또는 상세 도움말에서 확인을 요청하세요."));
