	private void AppendOperationalReadiness(StringBuilder sb, FamilyBrowserStandardPolicy policy)
	{
		sb.AppendLine("<div class=\"section\">" + Html(T("Operational Readiness", "운영 준비도")) + "</div>");
		if (_readinessReport == null)
		{
			sb.AppendLine("<div class=\"hint\">" + Html(T("Readiness has not been checked.", "운영 준비도를 아직 확인하지 못했습니다.")) + "</div>");
			return;
		}
		sb.AppendLine("<div class=\"request-status-strip\">");
		sb.AppendLine("<div class=\"request-status\"><strong>" + _readinessReport.BlockingCount.ToString(CultureInfo.InvariantCulture) + "</strong><span>" + Html(T("Blocked", "차단")) + "</span></div>");
		sb.AppendLine("<div class=\"request-status\"><strong>" + _readinessReport.WarningCount.ToString(CultureInfo.InvariantCulture) + "</strong><span>" + Html(T("Warnings", "주의")) + "</span></div>");
		sb.AppendLine("<div class=\"request-status\"><strong>" + _readinessReport.ReadyCount.ToString(CultureInfo.InvariantCulture) + "</strong><span>" + Html(T("Ready", "준비")) + "</span></div>");
		sb.AppendLine("</div>");
		if (CanSeeInternalPaths())
		{
			AppendAdminRow(sb, T("Policy path", "정책 경로"), _readinessReport.PolicyPath);
		}
		else
		{
			AppendAdminRow(sb, T("Policy", "정책"), ResolvePolicyDeploymentLabel());
		}
		AppendAdminRow(sb, T("Standard target", "표준 대상"), _readinessReport.StandardTarget);
		foreach (FamilyBrowserOperationalReadinessItem item in _readinessReport.Items.Where([SpecialName] (FamilyBrowserOperationalReadinessItem x) => ShouldDisplayReadinessItem(x)).Take(12))
		{
			sb.AppendLine("<div class=\"summary-card\">");
			sb.AppendLine("<strong><span class=\"badge " + StatusClass(item.Status) + "\">" + Html(DisplayReadinessStatus(item.Status)) + "</span> " + Html(DisplayReadinessArea(item.Area)) + "</strong>");
			sb.AppendLine("<span>" + Html(HideInternalPathDetails(TranslateNote(item.Message))) + "</span>");
			if (!string.IsNullOrWhiteSpace(item.Action))
			{
				sb.AppendLine("<span>" + Html(HideInternalPathDetails(TranslateNote(item.Action))) + "</span>");
			}
			sb.AppendLine("</div>");
		}
		sb.AppendLine("<div class=\"hint\" style=\"margin-bottom:18px\">" + Html(ReadinessBody()) + "</div>");
	}

	private static bool ShouldDisplayReadinessItem(FamilyBrowserOperationalReadinessItem item)
	{
		if (item == null)
		{
			return false;
		}
		return !string.Equals(FamilyBrowserPolicyKey.Normalize(item.Area), FamilyBrowserPolicyKey.Normalize("Snapshot"), StringComparison.Ordinal);
	}

	private string ReadinessTitle()
	{
		if (_readinessReport == null)
		{
			return T("not checked", "미확인");
		}
		if (_readinessReport.BlockingCount > 0)
		{
			return T("blocked", "차단") + " " + _readinessReport.BlockingCount.ToString(CultureInfo.InvariantCulture);
		}
		if (_readinessReport.WarningCount > 0)
		{
			return T("warnings", "주의") + " " + _readinessReport.WarningCount.ToString(CultureInfo.InvariantCulture);
		}
		return T("ready", "준비됨");
	}

	private string ReadinessBody()
	{
		if (_readinessReport == null)
		{
			return T("Run refresh to check policy, standard RVT and request store.", "새로고침으로 정책, 표준 RVT, 요청 저장소를 확인하세요.");
		}
		if (_readinessReport.BlockingCount > 0)
		{
			return T("Resolve blocked items before production use.", "실사용 전 차단 항목을 먼저 해결하세요.");
		}
		if (_readinessReport.WarningCount > 0)
		{
			return T("Usable for testing, but warnings remain.", "테스트는 가능하지만 주의 항목이 남아 있습니다.");
		}
		return T("Policy, standard RVT and request store are ready.", "정책, 표준 RVT, 요청 저장소가 준비되었습니다.");
	}

	private string ReadinessTone()
	{
		if (_readinessReport == null)
		{
			return "warn";
		}
		if (_readinessReport.BlockingCount > 0)
		{
			return "bad";
		}
		if (_readinessReport.WarningCount > 0)
		{
			return "warn";
		}
		return "good";
	}

	private string DisplayReadinessStatus(string status)
	{
		string left = FamilyBrowserPolicyKey.Normalize(status);
		if (Operators.CompareString(left, FamilyBrowserPolicyKey.Normalize("Ready"), TextCompare: false) == 0)
		{
			return T("Ready", "준비");
		}
		if (Operators.CompareString(left, FamilyBrowserPolicyKey.Normalize("Warning"), TextCompare: false) == 0)
		{
			return T("Warning", "주의");
		}
		if (Operators.CompareString(left, FamilyBrowserPolicyKey.Normalize("Blocked"), TextCompare: false) == 0)
		{
			return T("Blocked", "차단");
		}
		return string.IsNullOrWhiteSpace(status) ? "-" : status;
	}

	private void AppendPolicyModeSelector(StringBuilder sb)
	{
		FamilyBrowserStandardPolicy obj = _standardPolicy ?? LoadStandardPolicy();
		bool separatedActive = !string.Equals(obj.Mode, "Integrated", StringComparison.OrdinalIgnoreCase);
		bool integratedActive = string.Equals(obj.Mode, "Integrated", StringComparison.OrdinalIgnoreCase);
		sb.AppendLine("<div class=\"selector\">");
		sb.AppendLine("<a class=\"" + (separatedActive ? "active" : string.Empty) + "\" href=\"kkyfb:mode-separated\">" + Html(T("Separate Standards by Trade", "공종별 표준 사용")) + "</a>");
		sb.AppendLine("<a class=\"" + (integratedActive ? "active" : string.Empty) + "\" href=\"kkyfb:mode-integrated\">" + Html(T("Use One Integrated Standard", "통합 표준 사용")) + "</a>");
		sb.AppendLine("</div>");
	}

	private void AppendDisciplineSelector(StringBuilder sb, bool includeIntegratedHint)
	{
		FamilyBrowserStandardPolicy policy = _standardPolicy ?? LoadStandardPolicy();
		sb.AppendLine("<div class=\"selector\">");
		foreach (FamilyBrowserStandardLibrarySlot slot in FamilyBrowserStandardPolicyStore.GetDisciplineSlots(policy))
		{
			AppendDisciplineLink(sb, policy, slot);
		}
		sb.AppendLine("</div>");
		if (includeIntegratedHint && string.Equals(policy.Mode, "Integrated", StringComparison.OrdinalIgnoreCase))
		{
			sb.AppendLine("<div class=\"hint\">" + Html(T("Integrated mode uses one standard RVT. Trade buttons are kept for later filtering and request routing.", "통합 모드는 하나의 표준 RVT를 사용합니다. 공종 버튼은 이후 필터와 요청 라우팅 기준으로 사용합니다.")) + "</div>");
		}
	}

	private void AppendDisciplineLink(StringBuilder sb, FamilyBrowserStandardPolicy policy, FamilyBrowserStandardLibrarySlot slot)
	{
		if (slot != null)
		{
			string discipline = slot.Discipline;
			bool active = string.Equals(FamilyBrowserPolicyKey.Normalize(policy.ActiveDiscipline), FamilyBrowserPolicyKey.Normalize(discipline), StringComparison.OrdinalIgnoreCase);
			string token = Uri.EscapeDataString(discipline ?? string.Empty);
			sb.AppendLine("<a class=\"" + (active ? "active" : string.Empty) + "\" href=\"kkyfb:discipline-" + Attr(token) + "\">" + Html(FamilyBrowserStandardPolicyStore.ResolveSlotDisplayName(slot, IsKorean())) + "</a>");
		}
	}

	private void AppendPolicySlotSummary(StringBuilder sb, FamilyBrowserStandardPolicy policy)
	{
		if (policy == null)
		{
			return;
		}
		AppendSlotSummary(sb, FamilyBrowserStandardPolicyStore.ResolveSlotDisplayName(policy.IntegratedLibrary, IsKorean()), policy.IntegratedLibrary);
		foreach (FamilyBrowserStandardLibrarySlot slot in policy.DisciplineLibraries)
		{
			AppendSlotSummary(sb, FamilyBrowserStandardPolicyStore.ResolveSlotDisplayName(slot, IsKorean()), slot);
		}
	}

	private static void AppendSlotSummary(StringBuilder sb, string label, FamilyBrowserStandardLibrarySlot slot)
	{
		if (slot != null)
		{
			string value = (string.IsNullOrWhiteSpace(slot.StandardRvtPath) ? "-" : slot.StandardRvtPath);
			if (!string.IsNullOrWhiteSpace(slot.LastSnapshotAtUtc))
			{
				value = value + " / " + FormatUtcStamp(slot.LastSnapshotAtUtc);
			}
			if (!string.IsNullOrWhiteSpace(slot.StandardListPath))
			{
				value = value + " / List: " + slot.StandardListPath;
			}
			AppendAdminRow(sb, label, value);
		}
	}

	private void AppendPermissionExcelSummary(StringBuilder sb, FamilyBrowserStandardPolicy policy)
	{
		FamilyBrowserPermissionExcelSettings settings = policy?.PermissionExcel;
		if (settings == null || !settings.Enabled || string.IsNullOrWhiteSpace(settings.Path))
		{
			AppendAdminRow(sb, T("Excel policy", "Excel 정책"), T("Disabled. JSON security policy is active.", "비활성화됨. JSON 권한 정책이 적용됩니다."));
			return;
		}
		AppendAdminRow(sb, T("Excel file", "Excel 파일"), settings.Path);
		AppendAdminRow(sb, T("Sheet", "시트"), string.IsNullOrWhiteSpace(settings.SheetName) ? T("first worksheet", "첫 번째 시트") : settings.SheetName);
		AppendAdminRow(sb, T("Excel status", "Excel 상태"), T("Connected. File contents are checked only from Permission Diagnostic or native Revit command guard.", "연결됨. 파일 내용은 권한 진단 또는 Revit 기본 명령 차단 시에만 확인합니다."));
	}

	private static void AppendAdminRow(StringBuilder sb, string label, string value)
	{
		sb.AppendLine("<div class=\"admin-row\">");
		sb.AppendLine("<div class=\"label\">" + Html(label) + "</div>");
		sb.AppendLine("<div class=\"value\">" + Html(string.IsNullOrWhiteSpace(value) ? "-" : value) + "</div>");
		sb.AppendLine("</div>");
	}

	private static void AppendListPane(StringBuilder sb, string id, List<string> items, string emptyText)
	{
		sb.AppendLine("<div id=\"" + id + "\" style=\"display:none\">");
		sb.AppendLine("<div class=\"list\">");
		if (items == null || items.Count == 0)
		{
			sb.AppendLine("<div class=\"empty\">" + Html(emptyText) + "</div>");
		}
		else
		{
			foreach (string item in items)
			{
				sb.AppendLine("<div>" + Html(item) + "</div>");
			}
		}
		sb.AppendLine("</div>");
		sb.AppendLine("</div>");
	}

	private void AppendRow(StringBuilder sb, string tableName, string status, string rawStatus, string disciplineKey, string disciplineLabel, string name, string category, string action, string notes, string approved, string loaded, string changes, string systemFamilyKind, string parameters, string previewPath, string previewDiagnostic = "", string categoryGroup = "", string nestedSummary = "", string treeDisciplineKey = "", string systemLayerSummary = "", string differenceSummaryTable = "", string typeSummary = "")
	{
		string previewUri = ToFileUri(previewPath, _deferExpensiveStartupLookups);
		string effectiveTreeDisciplineKey = (string.IsNullOrWhiteSpace(treeDisciplineKey) ? disciplineKey : treeDisciplineKey);
		sb.Append("<tr class=\"data\" onclick=\"selectRow(this)\"");
		sb.Append(" data-raw=\"" + Attr(rawStatus) + "\"");
		sb.Append(" data-status=\"" + Attr(status) + "\"");
		sb.Append(" data-discipline-key=\"" + Attr(disciplineKey) + "\"");
		sb.Append(" data-tree-discipline-key=\"" + Attr(effectiveTreeDisciplineKey) + "\"");
		sb.Append(" data-discipline=\"" + Attr(disciplineLabel) + "\"");
		sb.Append(" data-group=\"" + Attr(NormalizeCategoryGroupToken(categoryGroup)) + "\"");
		sb.Append(" data-name=\"" + Attr(name) + "\"");
		sb.Append(" data-category=\"" + Attr(category) + "\"");
		sb.Append(" data-action=\"" + Attr(action) + "\"");
		sb.Append(" data-notes=\"" + Attr(notes) + "\"");
		sb.Append(" data-approved=\"" + Attr(approved) + "\"");
