	private void AppendFamilyInlineStatusFilterIfAny(StringBuilder sb, IEnumerable<BrowserRow> rows, string key, string label)
	{
		int count = rows.Where([SpecialName] (BrowserRow x) => MatchesFamilyRowFilter(x, key)).Count();
		if (count > 0)
		{
			AppendInlineStatusFilter(sb, key, label, count);
		}
	}

	private void AppendSystemInlineStatusFilterIfAny(StringBuilder sb, IEnumerable<SystemRow> rows, string key, string label)
	{
		int count = ((!string.Equals(Normalize(key), "duplicaterisk", StringComparison.Ordinal)) ? rows.Where([SpecialName] (SystemRow x) => MatchesSystemRowFilter(x, key)).Count() : rows.Where([SpecialName] (SystemRow x) => IsDuplicateRiskSystemRow(x)).Count());
		if (count > 0)
		{
			AppendInlineStatusFilter(sb, key, label, count);
		}
	}

	private void AppendFilterBar(StringBuilder sb)
	{
		sb.AppendLine("<div class=\"filterbar\">");
		bool systemTabActive = IsSystemBrowserTabActive();
		if (_adminModeEnabled)
		{
			AppendFilter(sb, "All", T("All", "전체"), CountBrowserContent("All", systemTabActive));
			AppendFilter(sb, "LoadAvailable", T("Load Available", "로드 가능"), CountBrowserContent("LoadAvailable", systemTabActive));
			AppendFilter(sb, "UpdateAvailable", T("Update Available", "업데이트 가능"), CountBrowserContent("UpdateAvailable", systemTabActive));
			AppendFilter(sb, "FingerprintDifferent", T("Fingerprint Different", "표준과 다름"), CountBrowserContent("FingerprintDifferent", systemTabActive));
			AppendFilter(sb, "DuplicateRisk", T("Duplicate Risk", "중복 위험"), CountBrowserContent("DuplicateRisk", systemTabActive));
			AppendFilter(sb, "Latest", T("Matches Standard", "표준과 일치"), CountBrowserContent("Latest", systemTabActive));
			if (!systemTabActive)
			{
				AppendFilter(sb, "LoadedNameMatch", T("Loaded - Check Needed", "로드됨(검사 필요)"), CountBrowserContent("LoadedNameMatch", systemTabActive));
			}
			AppendFilter(sb, "NeedsReview", T("Needs Review", "검토 대상"), CountBrowserContent("NeedsReview", systemTabActive));
		}
		else if (systemTabActive)
		{
			AppendFilter(sb, "All", T("All", "전체"), CountModelerSystem("All"));
			AppendFilter(sb, "LoadAvailable", T("Load Available", "로드 가능"), CountModelerSystem("LoadAvailable"));
			AppendFilter(sb, "UpdateAvailable", T("Update Available", "업데이트 가능"), CountModelerSystem("UpdateAvailable"));
		}
		else
		{
			AppendFilter(sb, "All", T("All", "전체"), CountModelerFamily("All"));
			AppendFilter(sb, "LoadAvailable", T("Load Available", "로드 가능"), CountModelerFamily("LoadAvailable"));
			AppendFilter(sb, "UpdateAvailable", T("Update Available", "업데이트 가능"), CountModelerFamily("UpdateAvailable"));
		}
		sb.AppendLine("</div>");
	}

	private void AppendDisciplineFilterBar(StringBuilder sb)
	{
		if (!_adminModeEnabled)
		{
			return;
		}
		FamilyBrowserStandardPolicy policy = _standardPolicy ?? LoadStandardPolicy();
		List<FamilyBrowserStandardLibrarySlot> slots = GetBrowserStandardSlots(policy);
		if (slots.Count <= 1)
		{
			return;
		}
		FamilyBrowserStandardLibrarySlot browseSlot = ResolveBrowseSlot(policy);
		string activeKey = ((browseSlot == null) ? string.Empty : ResolveSlotKey(browseSlot));
		sb.AppendLine("<div id=\"disciplineFilterBar\" class=\"disciplinebar\">");
		sb.AppendLine("<span class=\"discipline-label\">" + Html(T("Trade", "공종")) + "</span>");
		foreach (FamilyBrowserStandardLibrarySlot slot in slots)
		{
			string key = ResolveSlotKey(slot);
			AppendDisciplineFilter(sb, key, ResolveSlotLabel(slot), IsStandardSlotReady(policy, slot), string.Equals(Normalize(key), Normalize(activeKey), StringComparison.Ordinal));
		}
		sb.AppendLine("</div>");
	}

	private void AppendDisciplineFilter(StringBuilder sb, string key, string label, bool isReady, bool active)
	{
		string stateText = (isReady ? T("ready", "준비됨") : T("not registered", "미등록"));
		sb.AppendLine("<a name=\"disciplineFilter\" data-discipline=\"" + Attr(key) + "\" class=\"filter discipline-filter" + (active ? " active" : string.Empty) + "\" href=\"kkyfb:browse-discipline-" + Attr(Uri.EscapeDataString(key ?? string.Empty)) + "\">" + Html(label) + "<span class=\"count\">" + Html(stateText) + "</span></a>");
	}

	private bool IsStandardSlotReady(FamilyBrowserStandardPolicy policy, FamilyBrowserStandardLibrarySlot slot)
	{
		bool IsStandardSlotReady;
		try
		{
			StandardLibraryRegistrationRecord registration = TryLoadRegistrationForSlot(policy, slot, _deferExpensiveStartupLookups ? 300 : 0);
			IsStandardSlotReady = registration != null && !string.IsNullOrWhiteSpace(registration.LastSnapshotPath);
		}
		catch (Exception projectError)
		{
			ProjectData.SetProjectError(projectError);
			IsStandardSlotReady = false;
			ProjectData.ClearProjectError();
		}
		return IsStandardSlotReady;
	}

