	private int CountLoadable(string filter)
	{
		return _loadableRows.Where([SpecialName] (BrowserRow x) => MatchesFilterStatus(x.RawStatus, filter)).Count();
	}

	private int CountDashboardLoadAvailable()
	{
		checked
		{
			if (_adminModeEnabled)
			{
				return CountLoadable("LoadAvailable") + CountSystemContent("LoadAvailable");
			}
			return CountModelerFamily("LoadAvailable") + CountModelerSystem("LoadAvailable");
		}
	}

	private int CountDashboardUpdateAvailable()
	{
		checked
		{
			if (_adminModeEnabled)
			{
				return CountLoadable("UpdateAvailable") + CountSystemContent("UpdateAvailable");
			}
			return CountModelerFamily("UpdateAvailable") + CountModelerSystem("UpdateAvailable");
		}
	}

	private int CountModelerFamily(string filter)
	{
		int count = 0;
		foreach (BrowserRow row in _loadableRows)
		{
			if (row != null && (_adminModeEnabled || IsModelerVisibleFamilyRow(row)) && MatchesFamilyRowFilter(row, filter))
			{
				count = checked(count + 1);
			}
		}
		return count;
	}

	private int CountModelerSystem(string filter)
	{
		int count = 0;
		foreach (SystemRow row in _systemRows)
		{
			if (row != null && (_adminModeEnabled || IsModelerVisibleSystemRow(row)) && MatchesSystemRowFilter(row, filter))
			{
				count = checked(count + 1);
			}
		}
		return count;
	}

	private bool IsSystemBrowserTabActive()
	{
		return string.Equals(NormalizeDashboardTabName(_activeTab), "systems", StringComparison.Ordinal);
	}

	private int CountModelerReviewNeeded()
	{
		int num = CountModelerFamily("CategoryMismatch");
		int systemCount = _systemRows.Where([SpecialName] (SystemRow x) => MatchesFilterStatus(x.RawStatus, "CategoryMismatch")).Count();
		return checked(num + systemCount);
	}

	private IEnumerable<BrowserRow> FamilyRowsForCurrentMode()
	{
		if (_adminModeEnabled)
		{
			return _loadableRows;
		}
		return (from x in _loadableRows
			where IsModelerVisibleFamilyRow(x)
			orderby ModelerStatusRank(x.RawStatus)
			select x).ThenBy([SpecialName] (BrowserRow x) => NormalizeCategoryGroupToken(x.CategoryGroup), StringComparer.Ordinal).ThenBy([SpecialName] (BrowserRow x) => Normalize(x.Category), StringComparer.Ordinal).ThenBy([SpecialName] (BrowserRow x) => Normalize(x.Name), StringComparer.Ordinal);
	}

	private IEnumerable<SystemRow> SystemRowsForCurrentMode()
	{
		if (_adminModeEnabled)
		{
			return _systemRows;
		}
		return (from x in _systemRows
			where IsModelerVisibleSystemRow(x)
			orderby ModelerStatusRank(x.RawStatus)
			select x).ThenBy([SpecialName] (SystemRow x) => Normalize(x.Category), StringComparer.Ordinal).ThenBy([SpecialName] (SystemRow x) => Normalize(x.Name), StringComparer.Ordinal);
	}

	private static bool IsModelerVisibleFamilyRow(BrowserRow row)
	{
		if (row == null)
		{
			return false;
		}
		if (row.IsNestedLoadableChild)
		{
			return false;
		}
		string raw = Normalize(row.RawStatus);
		return Operators.CompareString(raw, "loadavailable", TextCompare: false) == 0 || Operators.CompareString(raw, "categorymismatch", TextCompare: false) == 0 || IsModelerActionableUpdateStatus(row.RawStatus);
	}

	private static bool IsModelerVisibleSystemRow(SystemRow row)
	{
		if (row == null)
		{
			return false;
		}
		string raw = Normalize(row.RawStatus);
		if (Operators.CompareString(raw, "loadavailable", TextCompare: false) == 0 || Operators.CompareString(raw, "categorymismatch", TextCompare: false) == 0 || IsModelerActionableUpdateStatus(row.RawStatus))
		{
			return true;
		}
		return false;
	}

	private string DisplayReadinessArea(string area)
	{
		string left = FamilyBrowserPolicyKey.Normalize(area);
		if (Operators.CompareString(left, FamilyBrowserPolicyKey.Normalize("Policy"), TextCompare: false) == 0)
		{
			return T("Policy", "정책");
		}
		if (Operators.CompareString(left, FamilyBrowserPolicyKey.Normalize("Standard RVT"), TextCompare: false) == 0)
		{
			return T("Standard RVT", "표준 RVT");
		}
		if (Operators.CompareString(left, FamilyBrowserPolicyKey.Normalize("Snapshot"), TextCompare: false) == 0)
		{
			return T("Snapshot", "스냅샷");
		}
		if (Operators.CompareString(left, FamilyBrowserPolicyKey.Normalize("Request Store"), TextCompare: false) == 0)
		{
			return T("Request Store", "요청 저장소");
		}
		if (Operators.CompareString(left, FamilyBrowserPolicyKey.Normalize("Security"), TextCompare: false) == 0)
		{
			return T("Security", "보안");
		}
		if (Operators.CompareString(left, FamilyBrowserPolicyKey.Normalize("Deployment"), TextCompare: false) == 0)
		{
			return T("Deployment", "배포");
		}
		if (Operators.CompareString(left, FamilyBrowserPolicyKey.Normalize("Readiness"), TextCompare: false) == 0)
		{
			return T("Readiness", "준비도");
		}
		return string.IsNullOrWhiteSpace(area) ? "-" : area;
	}

	private static int ModelerStatusRank(string status)
	{
		string raw = Normalize(status);
		if (Operators.CompareString(raw, "loadavailable", TextCompare: false) == 0)
		{
			return 0;
		}
		if (Operators.CompareString(raw, "categorymismatch", TextCompare: false) == 0)
		{
			return 1;
		}
		if (IsModelerActionableUpdateStatus(status))
		{
			return 2;
		}
		switch (raw)
		{
		case "loadedlatest":
		case "latest":
		case "nochange":
			return 8;
		default:
			return 9;
		}
	}

	private bool MatchesFamilyRowFilter(BrowserRow row, string filter)
	{
		if (row == null)
		{
			return false;
		}
		return Normalize(filter) switch
		{
			"all" => true, 
			"modelcategory" => string.Equals(NormalizeCategoryGroupToken(row.CategoryGroup), "Model", StringComparison.Ordinal), 
			"annotationcategory" => string.Equals(NormalizeCategoryGroupToken(row.CategoryGroup), "Annotation", StringComparison.Ordinal), 
			"updateavailable" => IsModelerActionableUpdateStatus(row.RawStatus), 
			_ => MatchesFilterStatus(row.RawStatus, filter), 
		};
	}

	private bool MatchesSystemRowFilter(SystemRow row, string filter)
	{
		if (row == null)
		{
			return false;
		}
		string left = Normalize(filter);
		if (Operators.CompareString(left, "all", TextCompare: false) != 0)
		{
			if (Operators.CompareString(left, "updateavailable", TextCompare: false) == 0)
			{
				return IsModelerActionableUpdateStatus(row.RawStatus);
			}
			return MatchesFilterStatus(row.RawStatus, filter);
		}
		return true;
	}

	private string ModelerFamilyStatusLabel(string status)
	{
		string raw = Normalize(status);
		if (Operators.CompareString(raw, "loadavailable", TextCompare: false) == 0)
		{
			return T("Load Available", "로드 가능");
		}
		if (IsTrackingRefreshStatus(status))
		{
			return T("Tracking Needs Refresh", "추적 갱신 필요");
		}
		if (IsModelerActionableUpdateStatus(status))
		{
			return T("Update Available", "업데이트 가능");
		}
		switch (raw)
		{
		case "loadedlatest":
		case "latest":
		case "nochange":
			return T("Loaded", "로드됨");
		default:
			return DisplayStatus(status);
		}
	}

	private string ModelerFamilyActionLabel(string status)
	{
		string raw = Normalize(status);
		if (Operators.CompareString(raw, "loadavailable", TextCompare: false) == 0)
		{
			return T("Load selected family", "선택 패밀리 로드");
		}
		if (IsTrackingRefreshStatus(status))
		{
			return T("Refresh tracking", "추적 갱신");
		}
		if (IsModelerActionableUpdateStatus(status))
		{
			return T("Update from standard", "표준으로 업데이트");
		}
		if (Operators.CompareString(raw, "categorymismatch", TextCompare: false) == 0)
		{
			return T("Admin review required", "관리자 검토 필요");
		}
		if (Operators.CompareString(raw, "reviewneeded", TextCompare: false) == 0)
		{
			return T("Run current model check", "현재 모델 검사 필요");
		}
		return T("No action needed", "작업 없음");
	}

	private string CategoryGroupLabel(string categoryGroup)
	{
		string left = NormalizeCategoryGroupToken(categoryGroup);
		if (Operators.CompareString(left, "Model", TextCompare: false) != 0)
		{
			if (Operators.CompareString(left, "Annotation", TextCompare: false) == 0)
			{
				return T("Annotation", "주석");
			}
			return T("Other", "기타");
		}
		return T("Model", "모델");
	}

	private int CountContent(string filter)
	{
		return checked(CountFamilyContent(filter) + CountSystemContent(filter));
	}

	private int CountBrowserContent(string filter, bool systemTabActive)
	{
		if (systemTabActive)
		{
			return CountSystemContent(filter);
		}
		return CountFamilyContent(filter);
	}

	private int CountFamilyContent(string filter)
	{
		string left = Normalize(filter);
		if (Operators.CompareString(left, "modelcategory", TextCompare: false) != 0)
		{
			if (Operators.CompareString(left, "annotationcategory", TextCompare: false) == 0)
			{
				return _loadableRows.Where([SpecialName] (BrowserRow x) => string.Equals(NormalizeCategoryGroupToken(x.CategoryGroup), "Annotation", StringComparison.Ordinal)).Count();
			}
			return _loadableRows.Where([SpecialName] (BrowserRow x) => MatchesFilterStatus(x.RawStatus, filter)).Count();
		}
		return _loadableRows.Where([SpecialName] (BrowserRow x) => string.Equals(NormalizeCategoryGroupToken(x.CategoryGroup), "Model", StringComparison.Ordinal)).Count();
	}

	private int CountSystemContent(string filter)
	{
		switch (Normalize(filter))
		{
		case "duplicaterisk":
			return CountDuplicateRiskRows();
		case "modelcategory":
		case "annotationcategory":
			return 0;
		default:
			return _systemRows.Where([SpecialName] (SystemRow x) => MatchesFilterStatus(x.RawStatus, filter)).Count();
		}
	}

	private int CountDuplicateRiskRows()
	{
		return _systemRows.Where([SpecialName] (SystemRow x) => IsDuplicateRiskSystemRow(x)).Count();
	}

	private BrowserRow FindLoadableRowForSelection(string disciplineKey, string categoryName, string familyName)
	{
		string text = Normalize(disciplineKey);
		string text2 = Normalize(categoryName);
		string b = Normalize(familyName);
		return _loadableRows.FirstOrDefault([SpecialName] (BrowserRow row) =>
		{
			if (row == null)
			{
				return false;
			}
			if (!string.Equals(Normalize(row.Name), b, StringComparison.Ordinal))
			{
				return false;
			}
			if (text2.Length > 0 && !string.Equals(Normalize(row.Category), text2, StringComparison.Ordinal))
			{
				return false;
			}
			return (text.Length <= 0 || string.Equals(Normalize(row.DisciplineKey), text, StringComparison.Ordinal)) ? true : false;
		});
	}

	private static bool IsCategoryMismatchLoadableRow(BrowserRow row)
	{
		if (row != null)
		{
			return string.Equals(Normalize(row.RawStatus), "categorymismatch", StringComparison.Ordinal);
		}
		return false;
	}

	private static bool IsCategoryMismatchSystemRow(SystemRow row)
	{
		if (row != null)
		{
			return string.Equals(Normalize(row.RawStatus), "categorymismatch", StringComparison.Ordinal);
		}
		return false;
	}

	private SystemRow FindSystemRowForSelection(string disciplineKey, string categoryName, string systemTypeName, string systemFamilyKind)
	{
		string text = Normalize(disciplineKey);
		string text2 = Normalize(categoryName);
		string b = Normalize(systemTypeName);
		string text3 = Normalize(systemFamilyKind);
		return _systemRows.FirstOrDefault([SpecialName] (SystemRow row) =>
		{
			if (row == null)
			{
				return false;
			}
			if (!string.Equals(Normalize(row.Name), b, StringComparison.Ordinal))
			{
				return false;
			}
			if (text3.Length > 0 && !string.Equals(Normalize(row.SystemFamilyKind), text3, StringComparison.Ordinal))
			{
				return false;
			}
			if (text2.Length > 0 && !string.Equals(Normalize(row.Category), text2, StringComparison.Ordinal))
			{
				return false;
			}
			return (text.Length <= 0 || string.Equals(Normalize(row.DisciplineKey), text, StringComparison.Ordinal)) ? true : false;
		});
	}

	private static bool IsDuplicateRiskSystemRow(SystemRow row)
	{
		if (row == null)
		{
			return false;
		}
		string text = Normalize(string.Join(" ", row.Action, row.Notes));
		return text.IndexOf("duplicate", StringComparison.Ordinal) >= 0 || text.IndexOf("중복", StringComparison.Ordinal) >= 0;
	}

	private int CountDisciplineContent(string disciplineKey)
	{
		checked
		{
			if (string.Equals(disciplineKey, "All", StringComparison.OrdinalIgnoreCase))
			{
				return _loadableRows.Count + _systemRows.Count;
			}
			string b = Normalize(disciplineKey);
			return _loadableRows.Where([SpecialName] (BrowserRow x) => string.Equals(Normalize(x.DisciplineKey), b, StringComparison.Ordinal)).Count() + _systemRows.Where([SpecialName] (SystemRow x) => string.Equals(Normalize(x.DisciplineKey), b, StringComparison.Ordinal)).Count();
		}
	}

	private static int CountSystemActions(SystemTypePreflightReport report, string actionName)
	{
		if (report == null || report.ExecutionPlan == null || report.ExecutionPlan.Items == null)
		{
			return 0;
		}
		return (from x in report.ExecutionPlan.Items
			where IsSupportedSystemApplyKind(x.SystemFamilyKind)
			where !string.Equals(Normalize(x.ExecutionStatus), "blocked", StringComparison.Ordinal)
			where string.Equals(Normalize(x.SyncAction), Normalize(actionName), StringComparison.Ordinal)
			select x).Count();
	}

	private static int CountDependencyApplyActions(SystemTypePreflightReport report)
	{
		if (report == null || report.DependencyPlan == null || report.DependencyPlan.Items == null)
		{
			return 0;
		}
		return report.DependencyPlan.Items.Where([SpecialName] (RoutingDependencyPreflightItem x) => IsExecutableDependencyApplyAction(x.Action)).Count();
	}

	private static bool IsExecutableDependencyApplyAction(string actionName)
	{
		switch (Normalize(actionName))
		{
		case "loadmissingdependencyfamily":
		case "reloadfamilyoverwrite":
		case "promoteorrenamedependencytype":
			return true;
		default:
			return false;
		}
	}

	private static int CountKeepWithDuplicateCleanup(SystemTypePreflightReport report)
	{
		if (report == null || report.ExecutionPlan == null || report.ExecutionPlan.Items == null)
		{
			return 0;
		}
		return (from x in report.ExecutionPlan.Items
			where IsSupportedSystemApplyKind(x.SystemFamilyKind)
			where !string.Equals(Normalize(x.ExecutionStatus), "blocked", StringComparison.Ordinal)
			where string.Equals(Normalize(x.SyncAction), "keepdestination", StringComparison.Ordinal)
			where x.Steps != null && x.Steps.Any([SpecialName] (SystemSyncExecutionStep stepItem) => string.Equals(Normalize(stepItem.Action), "cleanupduplicatesystemtypes", StringComparison.Ordinal))
			select x).Count();
	}

	private static int CountDuplicateRiskItems(SystemTypePreflightReport report)
	{
		if (report == null || report.ExecutionPlan == null || report.ExecutionPlan.Items == null)
		{
			return 0;
		}
		return report.ExecutionPlan.Items.Where([SpecialName] (SystemSyncExecutionItem x) => ExtractDuplicateStepTargets(x).Count > 0).Count();
	}

	private static string BuildDuplicateRiskSummary(SystemTypePreflightReport report, int maxItems)
	{
		if (report == null || report.ExecutionPlan == null || report.ExecutionPlan.Items == null || maxItems <= 0)
		{
			return string.Empty;
		}
		List<string> labels = new List<string>();
		foreach (SystemSyncExecutionItem item in report.ExecutionPlan.Items)
		{
			List<string> targets = ExtractDuplicateStepTargets(item);
			if (targets.Count != 0)
			{
				string itemName = (string.IsNullOrWhiteSpace(item.SystemTypeName) ? item.SystemFamilyKind : item.SystemTypeName);
				string targetText = string.Join(", ", targets.Take(3).ToArray());
				labels.Add(itemName + (string.IsNullOrWhiteSpace(targetText) ? string.Empty : (" -> " + targetText)));
				if (labels.Count >= maxItems)
				{
					break;
				}
			}
		}
		return string.Join(Environment.NewLine, labels.ToArray());
	}

	private string BuildSystemCategoryMismatchBlockerSummary(SystemTypePreflightReport report, int maxItems)
	{
		if (report == null || report.ExecutionPlan == null || report.ExecutionPlan.Items == null)
		{
			return string.Empty;
		}
		List<SystemSyncExecutionItem> blockers = report.ExecutionPlan.Items.Where([SpecialName] (SystemSyncExecutionItem x) => IsSystemCategoryMismatchBlocker(x)).OrderBy([SpecialName] (SystemSyncExecutionItem x) => Normalize(x.SystemFamilyKind) + "|" + Normalize(x.CategoryName) + "|" + Normalize(x.SystemTypeName), StringComparer.Ordinal).ToList();
		if (blockers.Count == 0)
		{
			return string.Empty;
		}
		List<string> lines = new List<string> { T("Category review blocked: ", "카테고리 검토 차단: ") + blockers.Count.ToString(CultureInfo.InvariantCulture) };
		foreach (SystemSyncExecutionItem item in blockers.Take(Math.Max(0, maxItems)))
		{
			string label = (string.IsNullOrWhiteSpace(item.SystemFamilyKind) ? "-" : item.SystemFamilyKind);
			if (!string.IsNullOrWhiteSpace(item.CategoryName))
			{
				label = label + " / " + item.CategoryName;
			}
			if (!string.IsNullOrWhiteSpace(item.SystemTypeName))
			{
				label = label + " / " + item.SystemTypeName;
			}
			lines.Add("- " + label);
		}
		if (blockers.Count > maxItems)
		{
			lines.Add(T("...and more system types require category review.", "...추가 시스템 타입도 카테고리 검토가 필요합니다."));
		}
		return string.Join(Environment.NewLine, lines.ToArray());
	}

	private static bool IsSystemCategoryMismatchBlocker(SystemSyncExecutionItem item)
	{
		if (item == null)
		{
			return false;
		}
		List<string> chunks = new List<string>
		{
			item.SyncAction ?? string.Empty,
			item.ExecutionStatus ?? string.Empty,
			item.Summary ?? string.Empty
		};
		if (item.BlockingReasons != null)
		{
			chunks.AddRange(item.BlockingReasons);
		}
		if (item.Steps != null)
		{
			foreach (SystemSyncExecutionStep stepItem in item.Steps)
			{
				if (stepItem != null)
				{
					chunks.Add(stepItem.Action ?? string.Empty);
					chunks.Add(stepItem.Notes ?? string.Empty);
				}
			}
		}
		string text = Normalize(string.Join(" ", chunks.ToArray()));
		return text.Contains("categorymismatch") || text.Contains("category mismatch") || text.Contains("category differs") || text.Contains("category identity differs") || text.Contains("카테고리");
	}

	private string BuildSystemDependencyBlockerSummary(SystemTypePreflightReport report, int maxItems)
	{
		if (report == null || report.ExecutionPlan == null || report.ExecutionPlan.Items == null)
		{
			return string.Empty;
		}
		List<string> labels = new List<string>();
		foreach (SystemSyncExecutionItem item in report.ExecutionPlan.Items.Where([SpecialName] (SystemSyncExecutionItem x) => x != null && x.Steps != null).OrderBy([SpecialName] (SystemSyncExecutionItem x) => Normalize(x.SystemFamilyKind) + "|" + Normalize(x.SystemTypeName), StringComparer.Ordinal))
		{
			foreach (SystemSyncExecutionStep stepItem in item.Steps)
			{
				if (stepItem == null)
				{
					continue;
				}
				string status = Normalize(stepItem.Status);
				if (string.Equals(status, "manualreview", StringComparison.Ordinal) || string.Equals(status, "foundationblocked", StringComparison.Ordinal))
				{
					string systemLabel = (string.IsNullOrWhiteSpace(item.SystemFamilyKind) ? "-" : item.SystemFamilyKind);
					if (!string.IsNullOrWhiteSpace(item.SystemTypeName))
					{
						systemLabel = systemLabel + " / " + item.SystemTypeName;
					}
					string targetLabel = (string.IsNullOrWhiteSpace(stepItem.TargetName) ? "-" : stepItem.TargetName);
					string actionLabel = TranslateAction(stepItem.Action);
					labels.Add(systemLabel + " -> " + targetLabel + (string.IsNullOrWhiteSpace(actionLabel) ? string.Empty : (" (" + actionLabel + ")")));
				}
			}
		}
		if (labels.Count == 0)
		{
			return string.Empty;
		}
		List<string> lines = new List<string> { T("Dependency/foundation review blocked: ", "의존/기반 검토 차단: ") + labels.Count.ToString(CultureInfo.InvariantCulture) };
		foreach (string label in labels.Take(Math.Max(0, maxItems)))
		{
			lines.Add("- " + label);
		}
		if (labels.Count > maxItems)
		{
			lines.Add(T("...and more dependency items require review.", "...추가 의존 항목도 검토가 필요합니다."));
		}
		return string.Join(Environment.NewLine, lines.ToArray());
	}

	private static int CountSupportedNoChange(SystemTypePreflightReport report)
	{
		if (report == null || report.ExecutionPlan == null || report.ExecutionPlan.Items == null)
		{
			return 0;
		}
		return (from x in report.ExecutionPlan.Items
			where IsSupportedSystemApplyKind(x.SystemFamilyKind)
			where string.Equals(Normalize(x.ExecutionStatus), "nochange", StringComparison.Ordinal)
			select x).Count();
	}

	private static int CountUnsupportedActionableSystemTypes(SystemTypePreflightReport report)
	{
		if (report == null || report.ExecutionPlan == null || report.ExecutionPlan.Items == null)
		{
			return 0;
		}
		return (from x in report.ExecutionPlan.Items
			where !IsSupportedSystemApplyKind(x.SystemFamilyKind)
			where !string.Equals(Normalize(x.ExecutionStatus), "nochange", StringComparison.Ordinal)
			where !string.Equals(Normalize(x.ExecutionStatus), "blocked", StringComparison.Ordinal)
			where !string.Equals(Normalize(x.ExecutionStatus), "skippedmissing", StringComparison.Ordinal)
			select x).Count();
	}

	private static bool IsSupportedSystemApplyKind(string systemFamilyKind)
	{
		return SystemTypeSupportPolicyService.CanApply(systemFamilyKind);
	}

	private static bool MatchesFilterStatus(string status, string filter)
	{
		string raw = Normalize(status);
		switch (Normalize(filter))
		{
		case "all":
			return true;
		case "fingerprintdifferent":
			return IsFingerprintDifferentStatus(status);
		case "duplicaterisk":
			return Operators.CompareString(raw, "duplicaterisk", TextCompare: false) == 0;
		case "updateavailable":
			return IsModelerActionableUpdateStatus(status);
		case "latest":
			return Operators.CompareString(raw, "loadedlatest", TextCompare: false) == 0 || Operators.CompareString(raw, "latest", TextCompare: false) == 0 || Operators.CompareString(raw, "nochange", TextCompare: false) == 0;
		case "needsreview":
			return IsAdminReviewRequiredStatus(status) || Operators.CompareString(raw, "blocked", TextCompare: false) == 0;
		case "blocked":
		{
			int result;
			switch (raw)
			{
			default:
				result = ((Operators.CompareString(raw, "versionconflict", TextCompare: false) == 0) ? 1 : 0);
				break;
			case "blocked":
			case "categorymismatch":
			case "differentfromstandard":
			case "locallymodified":
				result = 1;
				break;
			}
			return (byte)result != 0;
		}
		case "manualreview":
			return IsAdminReviewRequiredStatus(status);
		default:
			return Operators.CompareString(raw, Normalize(filter), TextCompare: false) == 0;
		}
	}

	private static bool IsFingerprintDifferentStatus(string status)
	{
		return IsAdminFingerprintDifferentStatus(status);
	}

	private static bool IsModelerActionableUpdateStatus(string status)
	{
		if (Operators.CompareString(Normalize(status), "updateavailable", TextCompare: false) != 0)
		{
			return IsTrackingRefreshStatus(status);
		}
		return true;
	}

	private static bool IsTrackingRefreshStatus(string status)
	{
		string raw = Normalize(status);
		if (Operators.CompareString(raw, "loadedwithoutversionstamp", TextCompare: false) != 0)
		{
			return Operators.CompareString(raw, "stampnormalizationneeded", TextCompare: false) == 0;
		}
		return true;
	}

	private static bool IsAdminFingerprintDifferentStatus(string status)
	{
		string raw = Normalize(status);
		switch (raw)
		{
		default:
			return Operators.CompareString(raw, "stampnormalizationneeded", TextCompare: false) == 0;
		case "updateavailable":
		case "differentfromstandard":
		case "locallymodified":
		case "versionconflict":
		case "loadedwithoutversionstamp":
			return true;
		}
	}

	private static bool IsAdminReviewRequiredStatus(string status)
	{
		string raw = Normalize(status);
		switch (raw)
		{
		default:
			return Operators.CompareString(raw, "approvalrequired", TextCompare: false) == 0;
		case "differentfromstandard":
		case "locallymodified":
		case "versionconflict":
		case "categorymismatch":
		case "projectonly":
		case "manualreview":
		case "reviewneeded":
			return true;
		}
	}

	private static bool IsUpdateAvailableStatus(string status)
	{
		return IsModelerActionableUpdateStatus(status);
	}

	private void PrepareRequestAndAuditPlaceholders()
	{
		_requestRecords = new List<FamilyBrowserRequestRecord>();
		_requestRecordsLoaded = false;
		_requestItems = new List<string>
		{
			T("Request list loads when the Request Addition tab is opened.", "요청 목록은 추가 요청 탭을 열 때 불러옵니다."),
			T("Startup does not read the request storage path.", "시작 시 요청 저장 경로를 읽지 않습니다.")
		};
		_auditItems = new List<string> { T("Run Current Model Check to populate review items.", "검토 항목은 현재 모델 검사를 실행하면 표시됩니다.") };
	}

	private void RefreshRequestsAndAudit(bool forceLoadRequests = false)
	{
		_requestItems.Clear();
		FamilyBrowserStandardPolicy policy = _standardPolicy ?? LoadStandardPolicy();
		bool shouldLoadRequests = forceLoadRequests || string.Equals(Normalize(_activeTab), "requests", StringComparison.OrdinalIgnoreCase);
		FamilyBrowserRequestStoreInfo storeInfo = null;
		if (shouldLoadRequests)
		{
			_requestRecordsLoaded = false;
			_requestRecords = FamilyBrowserRequestStore.List(_workspaceRoot, policy);
			_requestRecordsLoaded = true;
			storeInfo = FamilyBrowserRequestStore.GetRequestStoreInfo(_workspaceRoot, policy);
			_requestItems.Add(T("Request store: ", "요청 저장소: ") + ResolveRequestStoreLabel(policy));
		}
		else
		{
			if (!_requestRecordsLoaded)
			{
				_requestRecords = new List<FamilyBrowserRequestRecord>();
			}
			_requestItems.Add(T("Request list loads when the Request Addition tab is opened.", "요청 목록은 추가 요청 탭을 열 때 불러옵니다."));
			_requestItems.Add(T("This refresh did not read the request storage path.", "이번 갱신에서는 요청 저장 경로를 읽지 않았습니다."));
		}
		_requestItems.Add(T("Request entry: title, content and optional attachments", "요청 등록: 제목, 내용, 선택 첨부파일"));
		_requestItems.Add(T("Standard source: ", "표준 소스: ") + ((_registration == null) ? T("not registered", "미등록") : _registration.DisplayName));
		if (shouldLoadRequests && CanSeeInternalPaths())
		{
			_requestItems.Add(T("Last comparison: ", "마지막 비교: ") + (string.IsNullOrWhiteSpace(_lastComparisonPath) ? T("not written", "아직 저장되지 않음") : _lastComparisonPath));
			_requestItems.Add(T("Request folder: ", "요청 저장 폴더: ") + ((storeInfo == null) ? "-" : storeInfo.StoreLocation));
			if (storeInfo != null)
			{
				_requestItems.Add(T("Store detail: ", "저장소 세부: ") + storeInfo.Detail);
				if (!string.IsNullOrWhiteSpace(storeInfo.Endpoint))
				{
					_requestItems.Add(T("Endpoint: ", "엔드포인트: ") + storeInfo.Endpoint);
				}
			}
		}
		else if (shouldLoadRequests)
		{
			_requestItems.Add(T("Last comparison: ", "마지막 비교: ") + (string.IsNullOrWhiteSpace(_lastComparisonPath) ? T("not written", "아직 저장되지 않음") : T("written; path hidden", "저장됨; 경로 숨김")));
			_requestItems.Add(T("Request storage: ", "요청 저장소: ") + ResolveRequestStorePaneHint(policy));
		}
		int requestCount = _requestRecords.Count;
		if (requestCount > 0)
		{
			int openRequestCount = _requestRecords.Where([SpecialName] (FamilyBrowserRequestRecord x) => !IsRequestClosed(x.Status)).Count();
			int attachmentCount = _requestRecords.Sum([SpecialName] (FamilyBrowserRequestRecord x) => CountRequestAttachments(x));
			_requestItems.Add(T("Open requests: ", "진행중 요청: ") + openRequestCount.ToString(CultureInfo.InvariantCulture));
			_requestItems.Add(T("Saved requests: ", "등록된 요청: ") + requestCount.ToString(CultureInfo.InvariantCulture));
			_requestItems.Add(T("Attached files: ", "첨부파일: ") + attachmentCount.ToString(CultureInfo.InvariantCulture));
		}
		Document doc = GetActiveDocument();
		ProjectTrackingCatalog catalog = ((doc == null) ? null : ProjectTrackingStoreService.Load(doc));
		ProjectTrackingDirtyMarker dirtyMarker = ((doc == null) ? null : ProjectTrackingStoreService.LoadCurrentModelCheckMarker(doc));
		if (dirtyMarker != null)
		{
			_requestItems.Add(T("Tracking review: Current Model Check required after protected deletion", "추적 검토: 보호 항목 삭제 후 현재 모델 검사 필요"));
		}
		if (catalog == null)
		{
			_requestItems.Add(T("Tracking: not stamped", "추적: 스탬프 없음"));
		}
		else
		{
			_requestItems.Add(T("Tracking: ", "추적: ") + catalog.LoadableFamilies.Count.ToString(CultureInfo.InvariantCulture) + T(" loadables / ", "개 로드 가능 / ") + catalog.SystemTypes.Count.ToString(CultureInfo.InvariantCulture) + T(" system types", "개 시스템 타입"));
		}
		_auditItems.Clear();
		if (dirtyMarker != null)
		{
			foreach (ProjectTrackingDirtyItem item in (dirtyMarker.Items ?? new List<ProjectTrackingDirtyItem>()).Take(10))
			{
				_auditItems.Add(T("Deleted protected item / ", "삭제된 보호 항목 / ") + DisplayDirtyKind(item.Kind) + " / " + item.CategoryName + " / " + item.Name + " / " + T("Current Model Check required", "현재 모델 검사 필요"));
			}
		}
		foreach (BrowserRow row in _loadableRows.Where([SpecialName] (BrowserRow x) => Operators.CompareString(Normalize(x.RawStatus), "projectonly", TextCompare: false) == 0 || MatchesFilterStatus(x.RawStatus, "ManualReview")).Take(40))
		{
			_auditItems.Add(row.Status + " / " + row.Category + " / " + row.Name);
		}
		foreach (SystemRow row2 in _systemRows.Where([SpecialName] (SystemRow x) => Operators.CompareString(Normalize(x.RawStatus), "projectonly", TextCompare: false) == 0 || MatchesFilterStatus(x.RawStatus, "ManualReview") || Operators.CompareString(Normalize(x.RawStatus), "blocked", TextCompare: false) == 0).Take(40))
		{
			_auditItems.Add(T("System / ", "시스템 / ") + row2.Status + " / " + row2.Category + " / " + row2.Name);
		}
	}

	private void UpdateTrackingState(ProjectTrackingCatalog catalog)
	{
		if (ProjectTrackingStoreService.LoadCurrentModelCheckMarker(GetActiveDocument()) != null)
		{
			_trackingText = T("Tracking: Current Model Check required", "추적: 현재 모델 검사 필요");
			_trackingTone = "bad";
		}
		else if (catalog == null)
		{
			_trackingText = T("Tracking: not stamped", "추적: 스탬프 없음");
			_trackingTone = "warn";
		}
		else if (_registration != null && !string.Equals(Normalize(catalog.SourceId), Normalize(_registration.SourceId), StringComparison.Ordinal))
		{
			_trackingText = T("Tracking: source mismatch", "추적: 표준 소스 불일치");
			_trackingTone = "bad";
		}
		else
		{
			_trackingText = T("Tracking: ", "추적: ") + catalog.LoadableFamilies.Count.ToString(CultureInfo.InvariantCulture) + " / " + catalog.SystemTypes.Count.ToString(CultureInfo.InvariantCulture);
			_trackingTone = "good";
		}
	}

	private int CountSavedRequestDrafts()
	{
		int CountSavedRequestDrafts;
		try
		{
			string requestDir = FamilyBrowserStandardPolicyStore.GetDataFolder(_workspaceRoot, "Requests");
			CountSavedRequestDrafts = (Directory.Exists(requestDir) ? Directory.GetFiles(requestDir, "FBR-*.json").Length : 0);
		}
		catch (Exception projectError)
		{
			ProjectData.SetProjectError(projectError);
			CountSavedRequestDrafts = 0;
			ProjectData.ClearProjectError();
		}
		return CountSavedRequestDrafts;
	}

	private void ShowLoggedError(string caption, Exception ex)
	{
		string logPath = WriteErrorLog(caption, ex);
		string displayCaption = DisplayErrorCaption(caption);
		FamilyBrowserFriendlyError friendly = FamilyBrowserErrorHelp.Build(displayCaption, ex, logPath, IsKorean());
		_statusMessage = friendly.Summary + (CanSeeInternalPaths() ? (T("  Log: ", "  로그: ") + logPath) : T("  Technical log was saved for admin review.", "  기술 로그는 관리자 검토용으로 저장되었습니다."));
		RenderDashboard();
		ShowDashboardMessage(this, friendly.ToDialogMessage(IsKorean()), displayCaption, MessageBoxButtons.OK, MessageBoxIcon.Hand);
	}

	private string WriteErrorLog(string caption, Exception ex)
	{
		return FamilyBrowserErrorHelp.WriteLog(_workspaceRoot, caption, ex);
	}

