	private string LoadableAction(string status)
	{
		switch (Normalize(status))
		{
		case "loadavailable":
			return T("Not loaded", "현재 프로젝트에 없음");
		case "updateavailable":
			return T("Update", "업데이트");
		case "loadedwithoutversionstamp":
		case "stampnormalizationneeded":
			return T("Refresh Tracking", "추적 갱신");
		case "differentfromstandard":
		case "locallymodified":
		case "versionconflict":
			return T("Manual Review", "수동 검토");
		case "categorymismatch":
			return T("Category Review", "카테고리 검토");
		case "projectonly":
			if (_adminModeEnabled)
			{
				return T("Review for Standard", "표준 편입 검토");
			}
			return T("Not in standard", "표준 외 항목");
		default:
			return T("Keep", "유지");
		}
	}

