	}

	private string BuildTypeNote(LoadableFamilyComparisonItem item)
	{
		List<string> notes = new List<string>();
		if (item.MissingTypeNames != null && item.MissingTypeNames.Count > 0)
		{
			notes.Add(BuildTypeDifferenceBrief(T("Missing", "누락"), item.MissingTypeNames));
		}
		if (item.ExtraTypeNames != null && item.ExtraTypeNames.Count > 0)
		{
			notes.Add(BuildTypeDifferenceBrief(T("Extra", "추가"), item.ExtraTypeNames));
		}
		if (notes.Count == 0)
		{
			return DisplayStatus(item.Status);
		}
		return string.Join(" / ", notes);
	}

	private string BuildFamilyMemo(LoadableFamilyComparisonItem item)
	{
		if (item == null)
		{
			return "-";
		}
		if (IsBasisMatch(item.Status, item.Notes))
		{
			return T("Basis Match", "기준 일치");
		}
		List<string> parts = new List<string>();
		switch (Normalize(item.Status))
		{
		case "loadavailable":
			parts.Add(T("Not loaded in this project", "현재 프로젝트에 로드되지 않음"));
			break;
		case "projectonly":
			parts.Add(T("Not found in standard", "등록된 표준에 없음"));
			parts.Add(BuildProjectFamilyUsageNote(item.ProjectInstanceCount));
			break;
		case "categorymismatch":
			parts.Add(T("Category review required", "카테고리 검토 필요"));
			break;
		case "manualreview":
			if (HasProjectFingerprintMissing(item))
			{
				parts.Add(T("Current project fingerprint was not created", "현재 프로젝트 Fingerprint 생성 실패"));
			}
			else if (!string.IsNullOrWhiteSpace(item.Notes))
			{
				parts.Add(TranslateNote(item.Notes));
			}
			else
			{
				parts.Add(T("Manual review required", "수동 검토 필요"));
			}
			break;
		case "updateavailable":
		case "differentfromstandard":
		case "locallymodified":
		case "versionconflict":
		{
			if (HasProjectFingerprintMissing(item))
			{
				parts.Add(T("Current project fingerprint was not created", "현재 프로젝트 Fingerprint 생성 실패"));
				break;
			}
			List<string> diffParts = BuildFingerprintDifferenceDisplayParts(item, 2);
			if (diffParts.Count > 0)
			{
				parts.AddRange(diffParts);
			}
			else if (HasTypeInventoryDifference(item))
			{
				parts.Add(T("Type inventory differs", "타입 구성 불일치"));
			}
			break;
		}
		case "loadedwithoutversionstamp":
		case "stampnormalizationneeded":
			parts.Add(T("Tracking stamp needs refresh", "추적 스탬프 갱신 필요"));
			if (!string.IsNullOrWhiteSpace(item.Notes))
			{
				parts.Add(TranslateNote(item.Notes));
			}
			break;
		default:
			if (!string.IsNullOrWhiteSpace(item.Notes))
			{
				parts.Add(TranslateNote(item.Notes));
			}
			else
			{
				parts.Add(BuildTypeNote(item));
			}
			break;
		}
		if (item.StandardTypeCount != item.ProjectTypeCount)
		{
			parts.Add(string.Format(CultureInfo.InvariantCulture, T("Types {0}/{1}", "타입 {0}/{1}"), item.ProjectTypeCount, item.StandardTypeCount));
		}
		if (item.MissingTypeNames != null && item.MissingTypeNames.Count > 0)
		{
			parts.Add(BuildTypeDifferenceBrief(T("Missing type", "누락 타입"), item.MissingTypeNames));
		}
		if (item.ExtraTypeNames != null && item.ExtraTypeNames.Count > 0)
		{
			parts.Add(BuildTypeDifferenceBrief(T("Extra type", "추가 타입"), item.ExtraTypeNames));
		}
		List<string> cleaned = parts.Where([SpecialName] (string x) => !string.IsNullOrWhiteSpace(x) && Operators.CompareString(x.Trim(), "-", TextCompare: false) != 0).Take(3).ToList();
		if (cleaned.Count == 0)
		{
			return string.Empty;
		}
		return string.Join(" | ", cleaned);
	}

	private string BuildStandardListReviewMemo(LoadableFamilyComparisonItem item, bool allowedByStandardList)
	{
		if (item == null || allowedByStandardList)
		{
			return string.Empty;
		}
		if (!FamilyBrowserStandardListService.IsFilteringEnabled(_activeStandardListCatalog))
		{
			return string.Empty;
		}
		if (!string.Equals(Normalize(item.Status), "projectonly", StringComparison.Ordinal))
		{
			return string.Empty;
		}
		return T("Not in standard Excel list", "표준 Excel 목록에 없음");
	}

	private string BuildProjectFamilyUsageNote(int instanceCount)
	{
		if (instanceCount > 0)
		{
			return string.Format(CultureInfo.InvariantCulture, T("Used in model: {0}", "모델에서 사용 중: {0}개"), instanceCount);
		}
		return T("No placed instances", "배치 인스턴스 없음");
	}

	private string BuildRoutingDependencyNote(string categoryName, string categoryId)
	{
		if (FamilyBrowserFamilyClassificationService.IsRoutingDependencyCategory(categoryName, categoryId))
		{
			return T("Used by routing preference", "라우팅 환경설정에서 사용");
		}
		return string.Empty;
	}

	private static bool IsHiddenNestedLoadableChild(StandardLoadableFamilySnapshotItem item, HashSet<string> nestedFamilyNames)
	{
		if (item == null)
		{
			return false;
		}
		if (!item.IsShared)
		{
			return false;
		}
		if (!IsModelLoadableFamily(item))
		{
			return false;
		}
		if (!item.IsNestedLoadableChild && (nestedFamilyNames == null || !nestedFamilyNames.Contains(Normalize(item.FamilyName))))
		{
			return false;
		}
		return true;
	}

	private static HashSet<string> BuildNestedLoadableNameSet(StandardLibrarySnapshot snapshot)
	{
		HashSet<string> result = new HashSet<string>(StringComparer.Ordinal);
		if (snapshot == null || snapshot.LoadableFamilies == null)
		{
			return result;
		}
		foreach (StandardLoadableFamilySnapshotItem parentItem in snapshot.LoadableFamilies)
		{
			if (parentItem == null)
			{
				continue;
			}
			if (parentItem.IsNestedLoadableChild && parentItem.IsShared && IsModelLoadableFamily(parentItem))
			{
				string nestedFamilyName = Normalize(parentItem.FamilyName);
				if (!string.IsNullOrWhiteSpace(nestedFamilyName))
				{
					result.Add(nestedFamilyName);
				}
			}
			if (parentItem.NestedLoadableFamilies == null)
			{
				continue;
			}
			foreach (StandardNestedLoadableFamilySnapshotItem child in parentItem.NestedLoadableFamilies)
			{
				if (child != null && child.IsShared && IsModelNestedLoadableChild(child))
				{
					string familyName = Normalize((child == null) ? string.Empty : child.FamilyName);
					if (!string.IsNullOrWhiteSpace(familyName))
					{
						result.Add(familyName);
					}
				}
			}
		}
		return result;
	}

	private static bool IsModelLoadableFamily(StandardLoadableFamilySnapshotItem item)
	{
		if (item == null)
		{
			return false;
		}
		return string.Equals(FamilyBrowserFamilyClassificationService.ResolveCategoryGroup(item.CategoryGroup, item.CategoryName, item.CategoryId, item.FamilyName), "Model", StringComparison.OrdinalIgnoreCase);
	}

	private static bool IsModelNestedLoadableChild(StandardNestedLoadableFamilySnapshotItem item)
	{
		if (item == null)
		{
			return false;
		}
		return string.Equals(FamilyBrowserFamilyClassificationService.ResolveCategoryGroup(item.CategoryGroup, item.CategoryName, item.CategoryId, item.FamilyName), "Model", StringComparison.OrdinalIgnoreCase);
	}

	private string BuildNestedLoadableSummary(IEnumerable<StandardNestedLoadableFamilySnapshotItem> items)
	{
		if (items == null)
		{
			return string.Empty;
		}
		List<StandardNestedLoadableFamilySnapshotItem> nestedItems = items.Where([SpecialName] (StandardNestedLoadableFamilySnapshotItem x) => x != null && !string.IsNullOrWhiteSpace(x.FamilyName) && x.IsShared && IsModelNestedLoadableChild(x) && !FamilyBrowserFamilyClassificationService.IsTypeManagedFamilyLike(x.CategoryName, x.CategoryId, x.FamilyName)).OrderBy([SpecialName] (StandardNestedLoadableFamilySnapshotItem x) => Normalize(x.CategoryName), StringComparer.Ordinal).ThenBy([SpecialName] (StandardNestedLoadableFamilySnapshotItem x) => Normalize(x.FamilyName), StringComparer.Ordinal)
			.ToList();
		if (nestedItems.Count == 0)
		{
			return string.Empty;
		}
		List<string> lines = new List<string>();
		foreach (StandardNestedLoadableFamilySnapshotItem item in nestedItems.Take(12))
		{
			string categoryText = (string.IsNullOrWhiteSpace(item.CategoryName) ? "-" : item.CategoryName);
			string categorySuffix = (string.Equals(categoryText, "-", StringComparison.Ordinal) ? string.Empty : (" (" + categoryText + ")"));
			lines.Add("- " + item.FamilyName + categorySuffix);
		}
		if (nestedItems.Count > 12)
		{
			lines.Add(string.Format(CultureInfo.InvariantCulture, T("+ {0} more", "+ {0}개 더 있음"), checked(nestedItems.Count - 12)));
		}
		return string.Join(Environment.NewLine, lines);
	}

	private string BuildFamilyTypeSummary(IEnumerable<string> typeNames)
	{
		if (typeNames == null)
		{
			return string.Empty;
		}
		List<string> names = (from x in typeNames
			where !string.IsNullOrWhiteSpace(x)
			select x.Trim()).Distinct(StringComparer.OrdinalIgnoreCase).OrderBy([SpecialName] (string x) => Normalize(x), StringComparer.Ordinal).ToList();
		if (names.Count == 0)
		{
			return string.Empty;
		}
		return string.Join(Environment.NewLine, names);
	}

	private static string BuildSystemLayerSummary(IEnumerable<StandardSystemTypeLayerSnapshotItem> layers)
	{
		if (layers == null)
		{
			return string.Empty;
		}
		List<StandardSystemTypeLayerSnapshotItem> layerItems = (from x in layers
			where x != null
			orderby (x.Index <= 0) ? int.MaxValue : x.Index
			select x).ToList();
		if (layerItems.Count == 0)
		{
			return string.Empty;
		}
		List<string> lines = new List<string>();
		int fallbackIndex = 1;
		foreach (StandardSystemTypeLayerSnapshotItem layer in layerItems)
		{
			int displayIndex = ((layer.Index > 0) ? layer.Index : fallbackIndex);
			lines.Add(string.Join("\t", displayIndex.ToString(CultureInfo.InvariantCulture), SystemLayerCell(layer.FunctionName), SystemLayerCell(layer.MaterialName), SystemLayerCell(layer.ThicknessDisplay)));
			fallbackIndex = checked(fallbackIndex + 1);
		}
		return string.Join(Environment.NewLine, lines);
	}

	private static string SystemLayerCell(string value)
	{
		if (string.IsNullOrWhiteSpace(value))
		{
			return "-";
		}
		return value.Replace("\r\n", " ").Replace("\r", " ").Replace("\n", " ")
			.Replace("\t", " ")
			.Trim();
	}

	private static string CombineMemo(string primary, string extra)
	{
		string baseText = (primary ?? string.Empty).Trim();
		string extraText = (extra ?? string.Empty).Trim();
		if (extraText.Length == 0)
		{
			return (baseText.Length == 0) ? "-" : baseText;
		}
		if (baseText.Length == 0 || Operators.CompareString(baseText, "-", TextCompare: false) == 0)
		{
			return extraText;
		}
		if (baseText.IndexOf(extraText, StringComparison.OrdinalIgnoreCase) >= 0)
		{
			return baseText;
		}
		return baseText + " | " + extraText;
	}

	private string BuildFingerprintDifferenceTableText(LoadableFamilyComparisonItem item)
	{
		if (item == null)
		{
			return string.Empty;
		}
		List<string> rows = new List<string>();
		AppendTypeInventoryDifferenceRows(rows, item);
		if (item.FingerprintDifferenceDetails != null)
		{
			foreach (LoadableFingerprintDifferenceDetailItem detail in item.FingerprintDifferenceDetails)
			{
				if (detail == null || string.Equals(NormalizeDifferenceToken(detail.Area), "familytypes", StringComparison.Ordinal))
				{
					continue;
				}
				foreach (string line in BuildConciseFingerprintDifferenceTableLines(detail))
				{
					if (!string.IsNullOrWhiteSpace(line))
					{
						rows.Add(line);
						if (rows.Count >= 12)
						{
							break;
						}
					}
				}
				if (rows.Count >= 12)
				{
					break;
				}
			}
		}
		if (rows.Count == 0 && HasFingerprintDifferenceSummary(item))
		{
			foreach (string reason in item.FingerprintDifferenceSummary)
			{
				if (string.IsNullOrWhiteSpace(reason))
				{
					continue;
				}
				string note = BuildConciseSummaryDifferenceNote(reason);
				if (!string.IsNullOrWhiteSpace(note))
				{
					rows.Add(BuildFingerprintDifferenceTableLine(T("Summary", "요약"), "-", "-", note));
					if (rows.Count >= 8)
					{
						break;
					}
				}
			}
		}
		return string.Join("\n", rows);
	}

	private void AppendTypeInventoryDifferenceRows(IList<string> rows, LoadableFamilyComparisonItem item)
	{
		if (rows == null || item == null)
		{
			return;
		}
		List<string> missingTypes = CleanTypeDifferenceNames(item.MissingTypeNames);
		List<string> extraTypes = CleanTypeDifferenceNames(item.ExtraTypeNames);
		if (item.StandardTypeCount != item.ProjectTypeCount)
		{
			List<string> detailParts = new List<string>();
			if (missingTypes.Count > 0)
			{
				detailParts.Add(T("Missing ", "누락 ") + missingTypes.Count.ToString(CultureInfo.InvariantCulture));
			}
			if (extraTypes.Count > 0)
			{
				detailParts.Add(T("Extra ", "추가 ") + extraTypes.Count.ToString(CultureInfo.InvariantCulture));
			}
			rows.Add(BuildFingerprintDifferenceTableLine(T("Type Count", "타입 수"), item.StandardTypeCount.ToString(CultureInfo.InvariantCulture), item.ProjectTypeCount.ToString(CultureInfo.InvariantCulture), (detailParts.Count == 0) ? T("Type count differs", "타입 수 다름") : string.Join(" / ", detailParts)));
		}
		if (missingTypes.Count > 0)
		{
			rows.Add(BuildFingerprintDifferenceTableLine(T("Missing Type", "누락 타입"), FormatTypeDifferenceNames(missingTypes), FormatDifferenceCountLabel(T("Missing from current project", "현재 프로젝트에 없음"), missingTypes.Count), FormatDifferenceCountLabel(T("Missing type", "누락 타입"), missingTypes.Count)));
		}
		if (extraTypes.Count > 0)
		{
			rows.Add(BuildFingerprintDifferenceTableLine(T("Extra Type", "추가 타입"), FormatDifferenceCountLabel(T("Not in standard", "표준에 없음"), extraTypes.Count), FormatTypeDifferenceNames(extraTypes), FormatDifferenceCountLabel(T("Current project only", "현재 프로젝트에만 있음"), extraTypes.Count)));
		}
	}

	private static List<string> CleanTypeDifferenceNames(IEnumerable<string> names)
	{
		if (names == null)
		{
			return new List<string>();
		}
		return (from x in names
			where !string.IsNullOrWhiteSpace(x)
			select x.Trim()).Distinct(StringComparer.OrdinalIgnoreCase).OrderBy([SpecialName] (string x) => x, StringComparer.OrdinalIgnoreCase).ToList();
	}

	private string FormatTypeDifferenceNames(IList<string> names)
	{
		if (names == null || names.Count == 0)
		{
			return "-";
		}
		List<string> visible = names.Take(12).ToList();
		List<string> lines = new List<string> { string.Format(CultureInfo.InvariantCulture, T("{0} types", "{0}개"), names.Count) };
		foreach (string listedType in visible)
		{
			lines.Add("- " + listedType);
		}
		if (names.Count > visible.Count)
		{
			lines.Add("+" + checked(names.Count - visible.Count).ToString(CultureInfo.InvariantCulture));
		}
		return string.Join(" [[BR]] ", lines);
	}

	private string FormatDifferenceCountLabel(string label, int count)
	{
		return label + " " + string.Format(CultureInfo.InvariantCulture, T("{0} types", "{0}개"), count);
	}

	private string BuildTypeDifferenceBrief(string label, IEnumerable<string> names)
	{
		List<string> cleanNames = CleanTypeDifferenceNames(names);
		if (cleanNames.Count == 0)
		{
			return string.Empty;
		}
		if (cleanNames.Count == 1)
		{
			return label + ": " + cleanNames[0];
		}
		return label + " " + string.Format(CultureInfo.InvariantCulture, T("{0} types", "{0}개"), cleanNames.Count);
	}

	private string BuildSystemDifferenceTableText(SystemTypeComparisonItem item)
	{
		if (item == null)
		{
			return string.Empty;
		}
		List<string> rows = new List<string>();
		HashSet<string> seen = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
		if (item.DifferenceSummary != null)
		{
			foreach (string reason in item.DifferenceSummary)
			{
				foreach (string line in BuildSystemDifferenceTableLines(reason))
				{
					if (!string.IsNullOrWhiteSpace(line) && seen.Add(line))
					{
						rows.Add(line);
						if (rows.Count >= 12)
						{
							break;
						}
					}
				}
				if (rows.Count >= 12)
				{
					break;
				}
			}
		}
		if (rows.Count == 0 && !string.IsNullOrWhiteSpace(item.Notes))
		{
			foreach (string line2 in BuildSystemDifferenceTableLines(item.Notes))
			{
				if (!string.IsNullOrWhiteSpace(line2) && seen.Add(line2))
				{
					rows.Add(line2);
					if (rows.Count >= 8)
					{
						break;
					}
				}
			}
		}
		return string.Join("\n", rows);
	}

	private List<string> BuildSystemDifferenceTableLines(string summary)
	{
		List<string> rows = new List<string>();
		string text = CollapseSystemDifferenceText(summary);
		if (string.IsNullOrWhiteSpace(text))
		{
			return rows;
		}
		string label = string.Empty;
		string standardValue = string.Empty;
		string projectValue = string.Empty;
		if (TryParseSystemValueDifference(text, ref label, ref standardValue, ref projectValue))
		{
			rows.Add(BuildFingerprintDifferenceTableLine(TranslateSystemDifferenceArea(label), FormatSystemDifferenceCell(label, standardValue), FormatSystemDifferenceCell(label, projectValue), BuildSystemDifferenceNote(label)));
			return rows;
		}
		string key = NormalizeDifferenceToken(text);
		if (key.Contains("routingpreference") || key.Contains("라우팅"))
		{
			rows.Add(BuildFingerprintDifferenceTableLine(T("Routing Preference", "라우팅 환경설정"), "-", "-", T("Configuration differs", "구성 다름")));
		}
		else if (key.Contains("layer") || key.Contains("compoundstructure") || key.Contains("레이어"))
		{
			rows.Add(BuildFingerprintDifferenceTableLine(T("Layer", "레이어 구성"), "-", "-", T("Configuration differs", "구성 다름")));
		}
		else if (key.Contains("fingerprint"))
		{
			rows.Add(BuildFingerprintDifferenceTableLine("Fingerprint", "-", "-", T("Fingerprint differs", "Fingerprint 다름")));
		}
		else
		{
			rows.Add(BuildFingerprintDifferenceTableLine(T("Summary", "요약"), "-", "-", ShortDifferenceValue(TranslateNote(text), 90)));
		}
		return rows;
	}

	private static bool TryParseSystemValueDifference(string text, ref string label, ref string standardValue, ref string projectValue)
	{
		label = string.Empty;
		standardValue = string.Empty;
		projectValue = string.Empty;
		if (string.IsNullOrWhiteSpace(text))
		{
			return false;
		}
		string marker = " 다름:";
		int markerIndex = text.IndexOf(marker, StringComparison.OrdinalIgnoreCase);
		if (markerIndex < 0)
		{
			marker = " differs:";
			markerIndex = text.IndexOf(marker, StringComparison.OrdinalIgnoreCase);
		}
		if (markerIndex < 0)
		{
			return false;
		}
		label = text.Substring(0, markerIndex).Trim();
		return TryExtractSystemDifferenceValues(text.Substring(checked(markerIndex + marker.Length)).Trim(), ref standardValue, ref projectValue);
	}

	private static bool TryExtractSystemDifferenceValues(string text, ref string standardValue, ref string projectValue)
	{
		standardValue = string.Empty;
		projectValue = string.Empty;
		string rest = (text ?? string.Empty).Trim();
		if (rest.Length == 0)
		{
			return false;
		}
		checked
		{
			if (rest.StartsWith("표준 ", StringComparison.OrdinalIgnoreCase))
			{
				rest = rest.Substring("표준 ".Length).Trim();
				string separator = " / 현재 프로젝트 ";
				int separatorIndex = rest.IndexOf(separator, StringComparison.OrdinalIgnoreCase);
				if (separatorIndex < 0)
				{
					separator = " / 프로젝트 ";
					separatorIndex = rest.IndexOf(separator, StringComparison.OrdinalIgnoreCase);
				}
				if (separatorIndex >= 0)
				{
					standardValue = rest.Substring(0, separatorIndex).Trim();
					projectValue = rest.Substring(separatorIndex + separator.Length).Trim();
					return true;
				}
			}
			if (rest.StartsWith("standard ", StringComparison.OrdinalIgnoreCase))
			{
				rest = rest.Substring("standard ".Length).Trim();
				string separator2 = " / current project ";
				int separatorIndex2 = rest.IndexOf(separator2, StringComparison.OrdinalIgnoreCase);
				if (separatorIndex2 < 0)
				{
					separator2 = " / project ";
					separatorIndex2 = rest.IndexOf(separator2, StringComparison.OrdinalIgnoreCase);
				}
				if (separatorIndex2 >= 0)
				{
					standardValue = rest.Substring(0, separatorIndex2).Trim();
					projectValue = rest.Substring(separatorIndex2 + separator2.Length).Trim();
					return true;
				}
			}
			return false;
		}
	}

	private string TranslateSystemDifferenceArea(string label)
	{
		switch (NormalizeDifferenceToken(label))
		{
		case "classification":
		case "분류":
			return T("Classification", "분류");
		case "segment":
			return "Segment";
		case "material":
		case "재질":
			return T("Material", "재질");
		case "shape":
		case "형상":
			return T("Shape", "형상");
		case "routingpreference":
			return T("Routing Preference", "라우팅 환경설정");
		case "routingcriteria":
			return T("Routing Criteria", "라우팅 조건");
		case "routingpartfingerprint":
			return T("Routing Part Fingerprint", "라우팅 부품 Fingerprint");
		case "routingdependencyfingerprint":
			return T("Routing Dependency", "루팅 의존 패밀리");
		case "layer":
		case "layer구성":
		case "compoundstructure":
			return T("Layer", "레이어 구성");
		default:
			return string.IsNullOrWhiteSpace(label) ? T("Difference", "차이") : label.Trim();
		}
	}

	private string BuildSystemDifferenceNote(string label)
	{
		string key = NormalizeDifferenceToken(label);
		if (key.Contains("routingcriteria"))
		{
			return T("Size range or routing criteria differ", "사이즈 범위 또는 라우팅 조건 다름");
		}
		if (key.Contains("routingpreference"))
		{
			return T("Routing part/type setting differs", "라우팅 부품/타입 설정 다름");
		}
		if (key.Contains("routingpartfingerprint") || key.Contains("routingdependencyfingerprint"))
		{
			return T("Referenced routing family/type content differs", "참조 라우팅 패밀리/타입 내용 다름");
		}
		return T("Value differs", "값 다름");
	}

	private string FormatSystemDifferenceCell(string label, string value)
	{
		string key = NormalizeDifferenceToken(label);
		if (key.Contains("routingcriteria"))
		{
			return ShortDifferenceValue(FormatRoutingCriteriaDifferenceCell(value), 130);
		}
		if (key.Contains("routingpreference") || key.Contains("routingpartfingerprint") || key.Contains("routingdependencyfingerprint"))
		{
			return ShortDifferenceValue(FormatRoutingRuleDifferenceCell(value), 130);
		}
		return ShortDifferenceValue(value, 90);
	}

	private string FormatRoutingCriteriaDifferenceCell(string value)
	{
		string text = CleanDifferenceTableCell(value);
		if (string.IsNullOrWhiteSpace(text))
		{
			return "-";
		}
		text = Regex.Replace(text, "(?i)routingpreferencesizecriterion", T("Size", "사이즈"));
		text = Regex.Replace(text, "(?i)\\bmin=", T("min=", "최소="));
		text = Regex.Replace(text, "(?i)\\bmax=", T("max=", "최대="));
		text = text.Replace("&", " / ");
		text = text.Replace(":", " ");
		text = Regex.Replace(text, "\\s{2,}", " ");
		return text.Trim();
	}

	private string FormatRoutingRuleDifferenceCell(string value)
	{
		string text = CleanDifferenceTableCell(value);
		if (string.IsNullOrWhiteSpace(text))
		{
			return "-";
		}
		text = text.Replace("family=", T("family=", "패밀리=")).Replace("type=", T("type=", "타입=")).Replace("part=", T("part=", "부품="));
		text = Regex.Replace(text, "\\s{2,}", " ");
		return text.Trim();
	}

	private static string CollapseSystemDifferenceText(string value)
	{
		return (value ?? string.Empty).Replace("\r\n", " ").Replace("\r", " ").Replace("\n", " ")
			.Replace("\t", " ")
			.Trim();
	}

	private string BuildConciseSummaryDifferenceNote(string reason)
	{
		string text = TranslateNote(reason);
		if (string.IsNullOrWhiteSpace(text))
		{
			return string.Empty;
		}
		string normalized = Normalize(text);
		if (normalized.Contains("signature detail paths") || normalized.Contains("fingerprint 상세 경로") || normalized.Contains("contentsignaturedebugpath") || normalized.Contains("standardsignature=") || normalized.Contains("projectsignature="))
		{
			return string.Empty;
		}
		if (normalized.Contains("type count") || normalized.Contains("타입 개수"))
		{
			return T("Type count", "타입 수");
		}
		if (normalized.Contains("missing project types") || normalized.Contains("누락 타입"))
		{
			return T("Missing type", "누락 타입");
		}
		if (normalized.Contains("extra project types") || normalized.Contains("추가 타입"))
		{
			return T("Extra type", "추가 타입");
		}
		if (normalized.Contains("parameter") || normalized.Contains("파라미터"))
		{
			return T("Parameter", "파라미터");
		}
		if (normalized.Contains("connector") || normalized.Contains("커넥터"))
		{
			return T("Connector", "커넥터");
		}
		if (normalized.Contains("geometry") || normalized.Contains("형상"))
		{
			return T("Geometry", "형상");
		}
		if (normalized.Contains("nested") || normalized.Contains("하위"))
		{
			return T("Nested family", "하위 패밀리");
		}
		if (normalized.Contains("fingerprint"))
		{
			return "Fingerprint";
		}
		return ShortDifferenceValue(text, 42);
	}

	private string BuildFingerprintDifferenceTableLine(string area, string standardValue, string projectValue, string details)
	{
		return string.Join("\t", CleanDifferenceTableCell(area), CleanDifferenceTableCell(string.IsNullOrWhiteSpace(standardValue) ? "-" : standardValue), CleanDifferenceTableCell(string.IsNullOrWhiteSpace(projectValue) ? "-" : projectValue), CleanDifferenceTableCell(details));
	}

	private static string CleanDifferenceTableCell(string value)
	{
		return (value ?? string.Empty).Replace("\r\n", " ").Replace("\r", " ").Replace("\n", " ")
			.Replace("\t", " ")
			.Trim();
	}

	private List<string> BuildConciseFingerprintDifferenceTableLines(LoadableFingerprintDifferenceDetailItem detail)
	{
		List<string> rows = new List<string>();
		if (detail == null)
		{
			return rows;
		}
		string areaKey = NormalizeDifferenceToken(detail.Area);
		string kindKey = NormalizeDifferenceToken(detail.DifferenceKind);
		if (areaKey.StartsWith("elements", StringComparison.Ordinal) && !string.Equals(areaKey, "elements", StringComparison.Ordinal))
		{
			rows.Add(BuildSignatureGroupDifferenceLine(TranslateDifferenceArea(detail.Area, string.Empty), detail));
			return rows;
		}
		switch (areaKey)
		{
		case "familytypes":
			if (Operators.CompareString(kindKey, "count", TextCompare: false) == 0)
			{
				rows.Add(BuildFingerprintDifferenceTableLine(T("Type Count", "타입 수"), ShortDifferenceValue(detail.StandardValue, 18), ShortDifferenceValue(detail.ProjectValue, 18), string.Empty));
				break;
			}
			if (!IsDifferenceBlank(detail.StandardValue))
			{
				rows.Add(BuildFingerprintDifferenceTableLine(T("Missing Type", "누락 타입"), ShortDifferenceValue(detail.StandardValue, 80), "-", string.Empty));
			}
			if (!IsDifferenceBlank(detail.ProjectValue))
			{
				rows.Add(BuildFingerprintDifferenceTableLine(T("Extra Type", "추가 타입"), "-", ShortDifferenceValue(detail.ProjectValue, 80), string.Empty));
			}
			if (rows.Count == 0)
			{
				rows.Add(BuildFingerprintDifferenceTableLine(T("Type List", "타입 구성"), ShortDifferenceValue(detail.StandardValue, 60), ShortDifferenceValue(detail.ProjectValue, 60), string.Empty));
			}
			break;
		case "parametersformulas":
		{
			string changedLabels = BuildParameterChangedLabelText(detail.StandardValue, detail.ProjectValue);
			switch (kindKey)
			{
			case "standardonly":
				rows.Add(BuildFingerprintDifferenceTableLine(T("Missing Parameter", "누락 파라미터"), BuildParameterCompactCell(detail.StandardValue, string.Empty), "-", string.Empty));
				break;
			case "projectonly":
				rows.Add(BuildFingerprintDifferenceTableLine(T("Extra Parameter", "추가 파라미터"), "-", BuildParameterCompactCell(detail.ProjectValue, string.Empty), string.Empty));
				break;
			case "modified":
				rows.Add(BuildFingerprintDifferenceTableLine(T("Parameter", "파라미터"), BuildParameterCompactCell(detail.StandardValue, changedLabels), BuildParameterCompactCell(detail.ProjectValue, changedLabels), changedLabels));
				break;
			default:
				rows.Add(BuildFingerprintDifferenceTableLine(T("Parameter", "파라미터"), BuildParameterCompactCell(detail.StandardValue, string.Empty), BuildParameterCompactCell(detail.ProjectValue, string.Empty), changedLabels));
				break;
			}
			break;
		}
		case "category":
			rows.Add(BuildSimpleDifferenceLine(T("Category", "카테고리"), detail));
			break;
		case "categorygroup":
			rows.Add(BuildSimpleDifferenceLine(T("Category Group", "카테고리 그룹"), detail));
			break;
		case "familyname":
			rows.Add(BuildSimpleDifferenceLine(T("Family Name", "패밀리명"), detail));
			break;
		case "sharedflag":
			rows.Add(BuildSimpleDifferenceLine(T("Shared", "공유 여부"), detail));
			break;
		case "contentfingerprint":
			rows.Add(BuildFingerprintDifferenceTableLine(T("Fingerprint Missing", "Fingerprint 누락"), "-", ShortDifferenceValue(detail.ProjectValue, 70), string.Empty));
			break;
		case "storedfingerprint":
			rows.Add(BuildFingerprintDifferenceTableLine(T("Fingerprint", "Fingerprint"), T("Source same", "원문 동일"), T("Hash differs", "해시 다름"), T("Rescan", "재스캔")));
			break;
		case "signaturediagnostics":
			rows.Add(BuildFingerprintDifferenceTableLine(T("Diagnostics", "진단 누락"), BuildSignatureDiagnosticPresence(detail.StandardValue), BuildSignatureDiagnosticPresence(detail.ProjectValue), string.Empty));
			break;
		case "nestedlabels":
			rows.Add(BuildNestedLabelDifferenceLine(detail));
			break;
		case "nestedloadableinstances":
			rows.Add(BuildNestedLoadableDifferenceLine(T("Nested Placed Instance", "하위 배치 인스턴스"), detail));
			break;
		case "nestedloadabletypes":
			rows.Add(BuildNestedLoadableDifferenceLine(T("Nested Family - Type", "하위 패밀리 - 타입"), detail));
			break;
		case "nestedloadablefamilies":
			rows.Add(BuildNestedLoadableDifferenceLine(T("Nested Family", "하위 패밀리"), detail));
			break;
		case "connectors":
			rows.Add(BuildSignatureGroupDifferenceLine(T("Connector", "커넥터"), detail));
			break;
		case "geometry":
			rows.Add(BuildSignatureGroupDifferenceLine(T("Geometry", "형상"), detail));
			break;
		case "elements":
			rows.Add(BuildSignatureGroupDifferenceLine(T("Element", "요소"), detail));
			break;
		case "signatureversion":
			rows.Add(BuildSimpleDifferenceLine(T("Version", "버전"), detail));
			break;
		default:
			rows.Add(BuildFingerprintDifferenceTableLine(TranslateDifferenceArea(detail.Area, string.Empty), ShortDifferenceValue(detail.StandardValue, 60), ShortDifferenceValue(detail.ProjectValue, 60), BuildShortDifferenceNote(detail.Details)));
			break;
		}
		return rows;
	}

	private string BuildSimpleDifferenceLine(string label, LoadableFingerprintDifferenceDetailItem detail)
	{
		return BuildFingerprintDifferenceTableLine(label, ShortDifferenceValue((detail == null) ? string.Empty : detail.StandardValue, 60), ShortDifferenceValue((detail == null) ? string.Empty : detail.ProjectValue, 60), string.Empty);
	}

	private string BuildSignatureGroupDifferenceLine(string label, LoadableFingerprintDifferenceDetailItem detail)
	{
		string standardValue = BuildSignatureDifferenceValueCell((detail == null) ? string.Empty : detail.StandardValue);
		string projectValue = BuildSignatureDifferenceValueCell((detail == null) ? string.Empty : detail.ProjectValue);
		if (IsDifferenceBlank(standardValue))
		{
			standardValue = BuildSignatureCountCell((detail == null) ? string.Empty : detail.Details, standardSide: true);
		}
		if (IsDifferenceBlank(projectValue))
		{
			projectValue = BuildSignatureCountCell((detail == null) ? string.Empty : detail.Details, standardSide: false);
		}
		return BuildFingerprintDifferenceTableLine(label, standardValue, projectValue, BuildSignatureDifferenceNote(detail));
	}

	private string BuildNestedLoadableDifferenceLine(string label, LoadableFingerprintDifferenceDetailItem detail)
	{
		string standardValue = BuildNestedLoadableDifferenceCell((detail == null) ? string.Empty : detail.StandardValue);
		string projectValue = BuildNestedLoadableDifferenceCell((detail == null) ? string.Empty : detail.ProjectValue);
		if (IsDifferenceBlank(standardValue))
		{
			standardValue = BuildSignatureCountCell((detail == null) ? string.Empty : detail.Details, standardSide: true);
		}
		if (IsDifferenceBlank(projectValue))
		{
			projectValue = BuildSignatureCountCell((detail == null) ? string.Empty : detail.Details, standardSide: false);
		}
		return BuildFingerprintDifferenceTableLine(label, standardValue, projectValue, BuildSignatureDifferenceNote(detail));
	}

	private string BuildNestedLoadableDifferenceCell(string value)
	{
		string raw = CleanDifferenceTableCell(value);
		if (string.IsNullOrWhiteSpace(raw) || string.Equals(raw, "-", StringComparison.Ordinal))
		{
			return "-";
		}
		List<string> tokens = SplitSignatureRawTokens(Regex.Replace(raw, "\\[[^\\]]*\\]", string.Empty).Trim());
		if (tokens.Count == 0)
		{
			return BuildSignatureDifferenceValueCell(raw);
		}
		string kind = NormalizeDifferenceToken(tokens[0]);
		switch (kind)
		{
		default:
			return BuildSignatureDifferenceValueCell(raw);
		case "familyinstance":
		case "familysymbol":
		case "family":
		{
			string nestedFamily = FirstNonEmptyValue(ExtractSignatureDebugTokenValue(raw, "nestedFamily"), ExtractSignatureDebugTokenValue(raw, "family"));
			string nestedType = ExtractSignatureDebugTokenValue(raw, "nestedType");
			string ids = ExtractSignatureDebugIds(raw);
			switch (kind)
			{
			case "familyinstance":
				nestedFamily = FirstNonEmptyValue(nestedFamily, GetToken(tokens, 2));
				nestedType = FirstNonEmptyValue(nestedType, GetToken(tokens, 3));
				break;
			case "familysymbol":
				nestedType = FirstNonEmptyValue(nestedType, GetToken(tokens, 2));
				break;
			case "family":
				nestedFamily = FirstNonEmptyValue(nestedFamily, GetToken(tokens, 2));
				break;
			}
			List<string> parts = new List<string>();
			AddSignatureField(parts, T("Nested Family", "하위 패밀리"), nestedFamily);
			if (Operators.CompareString(kind, "familyinstance", TextCompare: false) == 0 || Operators.CompareString(kind, "familysymbol", TextCompare: false) == 0 || !string.IsNullOrWhiteSpace(nestedType))
			{
				AddSignatureField(parts, T("Type", "타입"), nestedType);
			}
			if (Operators.CompareString(kind, "familyinstance", TextCompare: false) == 0)
			{
				AddSignatureField(parts, "ID", ids);
			}
			if (parts.Count == 0)
			{
				return BuildSignatureDifferenceValueCell(raw);
			}
			return ShortDifferenceValue(string.Join(" [[BR]] ", parts), 180);
		}
		}
	}

	private static string ExtractSignatureDebugTokenValue(string value, string key)
	{
		string text = value ?? string.Empty;
		if (string.IsNullOrWhiteSpace(text) || string.IsNullOrWhiteSpace(key))
		{
			return string.Empty;
		}
		string marker = key + "=";
		int index = text.IndexOf(marker, StringComparison.OrdinalIgnoreCase);
		if (index < 0)
		{
			return string.Empty;
		}
		checked
		{
			index += marker.Length;
			if (index < text.Length && text[index] == '"')
			{
				index++;
				int quotedEndIndex = text.IndexOf('"', index);
				if (quotedEndIndex < 0 || quotedEndIndex <= index)
				{
					return string.Empty;
				}
				return text.Substring(index, quotedEndIndex - index).Trim();
			}
			int endIndex = text.IndexOfAny(new char[4] { ' ', '/', ',', ']' }, index);
			if (endIndex < 0)
			{
				endIndex = text.Length;
			}
			if (endIndex <= index)
			{
				return string.Empty;
			}
			return text.Substring(index, endIndex - index).Trim();
		}
	}

	private string BuildSignatureDifferenceValueCell(string value)
	{
		string text = StripDebugUidTokens(CleanDifferenceTableCell(value));
		if (string.IsNullOrWhiteSpace(text) || string.Equals(text, "-", StringComparison.Ordinal))
		{
			return "-";
		}
		string readable = BuildReadableSignatureDifferenceCell(text);
		if (!string.IsNullOrWhiteSpace(readable))
		{
			return ShortDifferenceValue(readable, 140);
		}
		text = Regex.Replace(text, "\\b[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}\\b", string.Empty, RegexOptions.IgnoreCase);
		text = text.Replace("|", " · ").Replace(":", " ").Replace("familyinstance", T("Nested instance", "하위 인스턴스"))
			.Replace("dimension", T("Dimension", "치수선"))
			.Replace("material", T("Material", "재료"));
		text = Regex.Replace(text, "\\s{2,}", " ");
		text = text.Trim().Trim('/', ',', '·');
		if (string.IsNullOrWhiteSpace(text))
		{
			return "-";
		}
		return ShortDifferenceValue(text, 120);
	}

	private string BuildReadableSignatureDifferenceCell(string value)
	{
		string text = StripDebugUidTokens(CleanDifferenceTableCell(value));
		if (string.IsNullOrWhiteSpace(text) || string.Equals(text, "-", StringComparison.Ordinal))
		{
			return "-";
		}
		string ids = ExtractSignatureDebugIds(text);
		text = Regex.Replace(text, "\\[[^\\]]*\\]", string.Empty).Trim();
		List<string> tokens = SplitSignatureRawTokens(text);
		if (tokens.Count == 0)
		{
			return string.Empty;
		}
		string kind = NormalizeDifferenceToken(tokens[0]);
		List<string> parts = new List<string>();
		if (!string.IsNullOrWhiteSpace(ids))
		{
			parts.Add("ID: " + ids);
		}
		switch (kind)
		{
		case "familyinstance":
			AddSignatureField(parts, T("Category", "카테고리"), GetToken(tokens, 1));
			AddSignatureField(parts, T("Nested Family", "하위 패밀리"), GetToken(tokens, 2));
			AddSignatureField(parts, T("Placed Type", "배치 타입"), FirstNonEmptyValue(GetToken(tokens, 5), GetToken(tokens, 2)));
			break;
		case "familysymbol":
			AddSignatureField(parts, T("Category", "카테고리"), GetToken(tokens, 1));
			AddSignatureField(parts, T("Nested Type", "하위 타입"), GetToken(tokens, 2));
			break;
		case "family":
			AddSignatureField(parts, T("Category", "카테고리"), GetToken(tokens, 1));
			AddSignatureField(parts, T("Family", "패밀리"), GetToken(tokens, 2));
			AddSignatureField(parts, T("State", "상태"), GetToken(tokens, 3));
			break;
		case "dimension":
			AddSignatureField(parts, T("Category", "카테고리"), GetToken(tokens, 1));
			AddSignatureField(parts, T("Name", "이름"), GetToken(tokens, 2));
			AddSignatureField(parts, T("Type", "타입"), FirstNonEmptyValue(GetToken(tokens, 5), GetToken(tokens, 3)));
			break;
		case "material":
			AddSignatureField(parts, T("Material", "재료"), GetToken(tokens, 2));
			break;
		case "element":
			AddSignatureField(parts, T("Category", "카테고리"), GetToken(tokens, 1));
			AddSignatureField(parts, T("Name", "이름"), GetToken(tokens, 2));
			AddSignatureField(parts, T("Type", "타입"), GetToken(tokens, 5));
			break;
		default:
			AddSignatureField(parts, T("Category", "카테고리"), GetToken(tokens, 1));
			AddSignatureField(parts, T("Name", "이름"), GetToken(tokens, 2));
			AddSignatureField(parts, T("Type", "타입"), GetToken(tokens, 5));
			break;
		}
		if (parts.Count == 0)
		{
			return string.Empty;
		}
		return string.Join(" · ", parts);
	}

	private static List<string> SplitSignatureRawTokens(string value)
	{
		string text = value ?? string.Empty;
		int bracketIndex = text.IndexOf("[", StringComparison.Ordinal);
		if (bracketIndex >= 0)
		{
			text = text.Substring(0, bracketIndex);
		}
		return (from x in text.Split('|')
			select (x ?? string.Empty).Trim() into x
			where x.Length > 0
			select x).ToList();
	}

	private static string GetToken(IList<string> tokens, int index)
	{
		if (tokens == null || index < 0 || index >= tokens.Count)
		{
			return string.Empty;
		}
		return tokens[index];
	}

	private static void AddSignatureField(IList<string> parts, string label, string value)
	{
		string text = CleanDifferenceTableCell(value);
		if (!string.IsNullOrWhiteSpace(text) && !string.Equals(text, "-", StringComparison.Ordinal))
		{
			text = CleanSignatureDisplayValue(text);
			if (!string.IsNullOrWhiteSpace(text) && !string.Equals(text, "-", StringComparison.Ordinal))
			{
				parts.Add(label + ": " + text);
			}
		}
	}

	private static string CleanSignatureDisplayValue(string value)
	{
		string text = CleanDifferenceTableCell(value);
		if (string.IsNullOrWhiteSpace(text))
		{
			return string.Empty;
		}
		text = StripDebugUidTokens(text);
		text = Regex.Replace(text, "\\b[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}\\b", string.Empty, RegexOptions.IgnoreCase);
		text = Regex.Replace(text, "^(dimensiontype|familytype|familysymbol|elementtype|material|element)\\s*/+\\s*", string.Empty, RegexOptions.IgnoreCase);
		text = text.Replace("//", "/").Replace("|", " · ");
		text = Regex.Replace(text, "\\s*/\\s*", "/");
		text = Regex.Replace(text, "\\s{2,}", " ");
		text = text.Trim().Trim('/', ',', '·');
		return text.Trim();
	}

	private static string ExtractSignatureDebugIds(string value)
	{
		string text = value ?? string.Empty;
		if (string.IsNullOrWhiteSpace(text))
		{
			return string.Empty;
		}
		MatchCollection matches = Regex.Matches(text, "ID\\s+([0-9]+)", RegexOptions.IgnoreCase);
		if (matches == null || matches.Count == 0)
		{
			return string.Empty;
		}
		List<string> ids = new List<string>();
		foreach (Match match in matches)
		{
			if (match != null && match.Groups.Count >= 2)
			{
				string idValue = match.Groups[1].Value;
				if (!string.IsNullOrWhiteSpace(idValue) && !ids.Contains(idValue, StringComparer.OrdinalIgnoreCase))
				{
					ids.Add(idValue);
				}
			}
		}
		string moreText = string.Empty;
		Match moreMatch = Regex.Match(text, "\\+([0-9]+)", RegexOptions.IgnoreCase);
		if (moreMatch.Success)
		{
			moreText = " +" + moreMatch.Groups[1].Value;
		}
		return string.Join(", ", ids.Take(4)) + moreText;
	}

	private string BuildSignatureDifferenceNote(LoadableFingerprintDifferenceDetailItem detail)
	{
		switch (NormalizeDifferenceToken((detail == null) ? string.Empty : detail.DifferenceKind))
		{
		case "standardonly":
			return T("Only in standard", "표준에만 있음");
		case "projectonly":
			return T("Only in current project", "현재 프로젝트에만 있음");
		case "modified":
			return T("Value differs", "값 다름");
		case "omitted":
			return BuildShortDifferenceNote((detail == null) ? string.Empty : detail.Details);
		default:
		{
			string details = ((detail == null) ? string.Empty : detail.Details);
			int standardCount = ExtractSignatureSideCount(details, "standard-only ");
			int projectCount = ExtractSignatureSideCount(details, "project-only ");
			List<string> parts = new List<string>();
			if (standardCount > 0)
			{
				parts.Add(T("Standard only ", "표준에만 ") + standardCount.ToString(CultureInfo.InvariantCulture));
			}
			if (projectCount > 0)
			{
				parts.Add(T("Current project only ", "현재 프로젝트에만 ") + projectCount.ToString(CultureInfo.InvariantCulture));
			}
			if (parts.Count == 0)
			{
				return BuildShortDifferenceNote(details);
			}
			return ShortDifferenceValue(string.Join(" · ", parts), 48);
		}
		}
	}

	private string BuildNestedLabelDifferenceLine(LoadableFingerprintDifferenceDetailItem detail)
	{
		if (detail == null)
		{
			return BuildFingerprintDifferenceTableLine(T("Nested Label", "하위 Label"), "-", "-", string.Empty);
		}
		string standardValue = BuildNestedLabelDifferenceCell(detail.StandardValue);
		string projectValue = BuildNestedLabelDifferenceCell(detail.ProjectValue);
		if (IsDifferenceBlank(standardValue) && IsDifferenceBlank(projectValue))
		{
			return BuildSignatureGroupDifferenceLine(T("Nested Label", "하위 Label"), detail);
		}
		return BuildFingerprintDifferenceTableLine(T("Nested Label", "하위 Label"), standardValue, projectValue, BuildNestedLabelDifferenceNote(detail.Details));
	}

	private string BuildNestedLabelDifferenceNote(string details)
	{
		string text = TranslateDifferenceDetail(details);
		if (string.IsNullOrWhiteSpace(text))
		{
			return T("Label differs", "Label 다름");
		}
		text = text.Replace("Nested label differs: ", string.Empty).Replace("Nested label differs.", T("Label differs", "Label 다름")).Replace("Nested label is missing in project.", T("Project missing", "프로젝트 누락"))
			.Replace("Nested label exists only in project.", T("Current project only", "현재 프로젝트에만 있음"))
			.Replace("Label definition differs.", T("Label definition differs", "Label 정의 다름"))
			.Replace("Label name", T("Label name", "Label 이름"))
			.Replace("Label parameter", T("Label parameter", "Label 파라미터"))
			.Replace("nested family", T("Nested family", "하위 패밀리"))
			.Replace("nested type", T("Nested type", "하위 타입"))
			.Replace("nested category", T("Nested category", "하위 카테고리"))
			.Replace("type/instance", T("Type/Instance", "타입/인스턴스"))
			.Replace("storage", T("Storage", "저장형식"))
			.Replace("formula", T("Formula", "공식"));
		return ShortDifferenceValue(text, 48);
	}

	private string BuildNestedLabelDifferenceCell(string value)
	{
		string text = StripDebugUidTokens(CleanDifferenceTableCell(value));
		if (string.IsNullOrWhiteSpace(text) || string.Equals(text, "-", StringComparison.Ordinal))
		{
			return "-";
		}
		text = text.Replace("nested-labels=", string.Empty).Replace("=>", " Label ").Replace("label=", T("Label parameter ", "Label 파라미터 "))
			.Replace("nested-family=", T("Nested family ", "하위 패밀리 "))
			.Replace("nested-type=", T("Nested type ", "하위 타입 "))
			.Replace("nested-category=", T("Nested category ", "하위 카테고리 "))
			.Replace("|", " · ");
		text = Regex.Replace(text, "\\b[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}\\b", string.Empty, RegexOptions.IgnoreCase);
		text = Regex.Replace(text, "\\s{2,}", " ");
		text = text.Replace("/ /", "/").Trim().Trim('/', ',', '·');
		if (string.IsNullOrWhiteSpace(text))
		{
			return "-";
		}
		return ShortDifferenceValue(text, 120);
	}

	private string BuildShortDifferenceNote(string details)
	{
		string text = TranslateDifferenceDetail(details);
		if (string.IsNullOrWhiteSpace(text))
		{
			return string.Empty;
		}
		return ShortDifferenceValue(text, 42);
	}

	private string BuildSignatureDiagnosticPresence(string value)
	{
		if (IsDifferenceBlank(value))
		{
			return T("Missing", "없음");
		}
		if (string.Equals(CleanDifferenceTableCell(value), "readable", StringComparison.OrdinalIgnoreCase))
		{
			return T("Present", "있음");
		}
		return T("Missing", "없음");
	}

	private string BuildSignatureCountCell(string details, bool standardSide)
	{
		int count = ExtractSignatureSideCount(details, standardSide ? "standard-only " : "project-only ");
		if (count <= 0)
		{
			return "-";
		}
		string text = count.ToString(CultureInfo.InvariantCulture) + T(" item", "개");
		string ids = ExtractSignatureSideIds(details, standardSide ? "standard ids " : "project ids ");
		if (!string.IsNullOrWhiteSpace(ids))
		{
			text = text + " / " + ids;
		}
		return ShortDifferenceValue(text, 84);
	}

	private static int ExtractSignatureSideCount(string details, string marker)
	{
		string text = details ?? string.Empty;
		int index = text.IndexOf(marker, StringComparison.OrdinalIgnoreCase);
		if (index < 0)
		{
			return 0;
		}
		checked
		{
			index += marker.Length;
			StringBuilder digits = new StringBuilder();
			for (; index < text.Length && char.IsDigit(text[index]); index++)
			{
				digits.Append(text[index]);
			}
			if (int.TryParse(digits.ToString(), NumberStyles.Integer, CultureInfo.InvariantCulture, out var value))
			{
				return value;
			}
			return 0;
		}
	}

	private static string ExtractSignatureSideIds(string details, string marker)
	{
		string text = details ?? string.Empty;
		if (string.IsNullOrWhiteSpace(text) || string.IsNullOrWhiteSpace(marker))
		{
			return string.Empty;
		}
		int index = text.IndexOf(marker, StringComparison.OrdinalIgnoreCase);
		if (index < 0)
		{
			return string.Empty;
		}
		checked
		{
			index += marker.Length;
			int nextIndex = text.IndexOf(", project ids ", index, StringComparison.OrdinalIgnoreCase);
			if (nextIndex < 0)
			{
				nextIndex = text.Length;
			}
			if (nextIndex <= index)
			{
				return string.Empty;
			}
			return StripDebugUidTokens(text.Substring(index, nextIndex - index).Trim().Trim(','));
		}
	}

	private static string StripDebugUidTokens(string value)
	{
		string text = value ?? string.Empty;
		if (string.IsNullOrWhiteSpace(text))
		{
			return string.Empty;
		}
		text = Regex.Replace(text, "\\s*/\\s*UID\\s+[^,]+", string.Empty, RegexOptions.IgnoreCase);
		text = Regex.Replace(text, "(^|,\\s*)UID\\s+[^,]+", "$1", RegexOptions.IgnoreCase);
		text = Regex.Replace(text, "\\s{2,}", " ");
		return text.Trim().Trim(',').Trim();
	}

	private static bool IsDifferenceBlank(string value)
	{
		string text = CleanDifferenceTableCell(value);
		if (!string.IsNullOrWhiteSpace(text))
		{
			return string.Equals(text, "-", StringComparison.Ordinal);
		}
		return true;
	}

	private string BuildParameterCompactCell(string value, string changedLabels)
	{
		List<string> segments = SplitDifferenceValue(value);
		if (segments.Count == 0)
		{
			return "-";
		}
		string name = segments[0];
		if (string.IsNullOrWhiteSpace(changedLabels))
		{
			return ShortDifferenceValue(name, 54);
		}
		string labelKey = NormalizeDifferenceToken(changedLabels);
		if (labelKey.Contains(NormalizeDifferenceToken(T("Formula", "공식"))))
		{
			return ShortDifferenceValue(name + " / " + FirstNonEmptyValue(GetParameterFormula(segments), T("No formula", "공식 없음")), 72);
		}
		if (labelKey.Contains(NormalizeDifferenceToken(T("Shared", "공유"))))
		{
			return ShortDifferenceValue(name + " / " + GetParameterSharedLabel(segments), 72);
		}
		if (labelKey.Contains("guid"))
		{
			return ShortDifferenceValue(name + " / " + GetParameterGuidLabel(segments), 72);
		}
		if (labelKey.Contains(NormalizeDifferenceToken(T("Type/Instance", "타입/인스턴스"))))
		{
			return ShortDifferenceValue(name + " / " + GetParameterRoleLabel(segments), 72);
		}
		if (labelKey.Contains(NormalizeDifferenceToken(T("Data Type", "자료형"))))
		{
			return ShortDifferenceValue(name + " / " + GetParameterStorageLabel(segments), 72);
		}
		return ShortDifferenceValue(name, 54);
	}

	private string BuildParameterChangedLabelText(string standardValue, string projectValue)
	{
		List<string> standardSegments = SplitDifferenceValue(standardValue);
		List<string> projectSegments = SplitDifferenceValue(projectValue);
		if (standardSegments.Count == 0 || projectSegments.Count == 0)
		{
			return string.Empty;
		}
		List<string> labels = new List<string>();
		if (!string.Equals(GetParameterFormula(standardSegments), GetParameterFormula(projectSegments), StringComparison.OrdinalIgnoreCase))
		{
			labels.Add(T("Formula", "공식"));
		}
		if (!string.Equals(GetParameterSharedToken(standardSegments), GetParameterSharedToken(projectSegments), StringComparison.OrdinalIgnoreCase))
		{
			labels.Add(T("Shared", "공유"));
		}
		if (!string.Equals(GetParameterGuidToken(standardSegments), GetParameterGuidToken(projectSegments), StringComparison.OrdinalIgnoreCase))
		{
			labels.Add("GUID");
		}
		if (!string.Equals(GetParameterRoleToken(standardSegments), GetParameterRoleToken(projectSegments), StringComparison.OrdinalIgnoreCase))
		{
			labels.Add(T("Type/Instance", "타입/인스턴스"));
		}
		if (!string.Equals(GetParameterStorageLabel(standardSegments), GetParameterStorageLabel(projectSegments), StringComparison.OrdinalIgnoreCase))
		{
			labels.Add(T("Data Type", "자료형"));
		}
		if (labels.Count == 0)
		{
			labels.Add(T("Definition", "정의"));
		}
		return string.Join(", ", labels.Take(2));
	}

	private static string GetParameterRoleToken(IList<string> segments)
	{
		if (segments == null || segments.Count <= 2)
		{
			return string.Empty;
		}
		return segments[2];
	}

	private string GetParameterRoleLabel(IList<string> segments)
	{
		if (NormalizeDifferenceToken(GetParameterRoleToken(segments)).Contains("instance"))
		{
			return T("Instance", "인스턴스");
		}
		return T("Type", "타입");
	}

	private static string GetParameterSharedToken(IList<string> segments)
	{
		if (segments == null || segments.Count <= 3)
		{
			return string.Empty;
		}
		return segments[3];
	}

	private string GetParameterSharedLabel(IList<string> segments)
	{
		if (NormalizeDifferenceToken(GetParameterSharedToken(segments)).Contains("shared"))
		{
			return T("Shared", "공유");
		}
		return T("Family", "패밀리");
	}

	private static string GetParameterStorageLabel(IList<string> segments)
	{
		if (segments == null || segments.Count <= 4)
		{
			return string.Empty;
		}
		return segments[4];
	}

	private static string GetParameterGuidToken(IList<string> segments)
	{
		if (segments == null)
		{
			return string.Empty;
		}
		foreach (string segment in segments)
		{
			if (segment != null && segment.Trim().StartsWith("guid:", StringComparison.OrdinalIgnoreCase))
			{
				return segment.Trim();
			}
		}
		return string.Empty;
	}

	private string GetParameterGuidLabel(IList<string> segments)
	{
		if (string.IsNullOrWhiteSpace(GetParameterGuidToken(segments)))
		{
			return T("No GUID", "GUID 없음");
		}
		return "GUID";
	}

	private static string GetParameterFormula(IList<string> segments)
	{
		if (segments == null)
		{
			return string.Empty;
		}
		foreach (string segment in segments)
		{
			if (segment != null)
			{
				string text = segment.Trim();
				if (text.StartsWith("formula=", StringComparison.OrdinalIgnoreCase))
				{
					return text.Substring("formula=".Length).Trim();
				}
			}
		}
		return string.Empty;
	}

	private string TranslateDifferenceArea(string area, string kind)
	{
		string normalizedArea = Normalize(area);
		string baseLabel;
		if (normalizedArea.StartsWith("elements/", StringComparison.Ordinal))
		{
			baseLabel = T("Element - ", "요소 - ") + TranslateElementSignatureKind(normalizedArea.Substring("elements/".Length));
		}
		else
		{
			switch (normalizedArea)
			{
			case "category":
				baseLabel = T("Category", "카테고리");
				break;
			case "categorygroup":
			case "category group":
				baseLabel = T("Category Group", "카테고리 그룹");
				break;
			case "familyname":
			case "family name":
				baseLabel = T("Family Name", "패밀리명");
				break;
			case "familytypes":
			case "family types":
				baseLabel = T("Family Types", "타입 구성");
				break;
			case "sharedflag":
			case "shared flag":
				baseLabel = T("Shared Flag", "공유 여부");
				break;
			case "parametersformulas":
			case "parameters/formulas":
				baseLabel = T("Parameters / Formulas", "파라미터 / 공식");
				break;
			case "contentfingerprint":
			case "content fingerprint":
				baseLabel = T("Content Fingerprint", "Content Fingerprint");
				break;
			case "storedfingerprint":
			case "stored fingerprint":
				baseLabel = T("Stored Fingerprint", "저장된 Fingerprint");
				break;
			case "signaturediagnostics":
			case "signature diagnostics":
				baseLabel = T("Signature Diagnostics", "Signature 진단");
				break;
			case "nestedlabels":
			case "nested labels":
				baseLabel = T("Nested Labels", "하위 패밀리 Label");
				break;
			case "nestedloadableinstances":
			case "nested/loadable instances":
				baseLabel = T("Nested Instances", "하위 인스턴스");
				break;
			case "nestedloadabletypes":
			case "nested/loadable types":
				baseLabel = T("Nested Family Types", "하위 패밀리 타입");
				break;
			case "nestedloadablefamilies":
			case "nested/loadable families":
				baseLabel = T("Nested Families", "하위 패밀리");
				break;
			case "connectors":
				baseLabel = T("Connectors", "커넥터");
				break;
			case "geometry":
				baseLabel = T("Geometry", "형상");
				break;
			case "elements":
				baseLabel = T("Elements", "요소");
				break;
			case "signatureversion":
			case "signature version":
				baseLabel = T("Signature Version", "Signature 버전");
				break;
			case "additionalgroups":
			case "additional groups":
				baseLabel = T("Additional Groups", "추가 그룹");
				break;
			default:
				baseLabel = (string.IsNullOrWhiteSpace(area) ? T("Difference", "차이") : area);
				break;
			}
		}
		string kindLabel = TranslateDifferenceKind(kind);
		if (string.IsNullOrWhiteSpace(kindLabel))
		{
			return baseLabel;
		}
		return baseLabel + " · " + kindLabel;
	}

	private string TranslateElementSignatureKind(string value)
	{
		return Normalize(value) switch
		{
			"dimension" => T("Dimension", "치수선"), 
			"element" => T("Element", "요소"), 
			"family" => T("Family", "패밀리"), 
			"material" => T("Material", "재료"), 
			"reference plane" => T("Reference Plane", "참조 평면"), 
			"model line" => T("Model Line", "모델 선"), 
			"detail line" => T("Detail Line", "상세 선"), 
			"text" => T("Text", "문자"), 
			"filled region" => T("Filled Region", "채우기 영역"), 
			"form" => T("Form", "형상 요소"), 
			_ => HumanizeSignatureToken(value), 
		};
	}

	private static string HumanizeSignatureToken(string value)
	{
		string text = (value ?? string.Empty).Trim();
		if (text.Length == 0)
		{
			return string.Empty;
		}
		text = text.Replace("_", " ").Replace("-", " ").Replace("/", " ");
		StringBuilder builder = new StringBuilder();
		checked
		{
			int num = text.Length - 1;
			for (int index = 0; index <= num; index++)
			{
				char ch = text[index];
				if (index > 0 && char.IsUpper(ch) && !char.IsWhiteSpace(text[index - 1]))
				{
					builder.Append(' ');
				}
				builder.Append(ch);
			}
			return CultureInfo.CurrentCulture.TextInfo.ToTitleCase(builder.ToString().ToLowerInvariant());
		}
	}

	private string TranslateDifferenceKind(string kind)
	{
		switch (Normalize(kind))
		{
		case "different":
			return T("Different", "다름");
		case "modified":
			return T("Modified", "수정됨");
		case "standardonly":
		case "standard-only":
			return T("Standard Only", "표준에만 있음");
		case "projectonly":
		case "project-only":
			return T("Current Project Only", "현재 프로젝트에만 있음");
		case "inventory":
			return T("Inventory", "구성");
		case "count":
			return T("Count", "개수");
		case "missing":
			return T("Missing", "누락");
		case "signaturesource":
		case "signature-source":
			return T("Signature Source", "Signature 원문");
		case "omitted":
			return T("Omitted", "생략");
		default:
			return kind ?? string.Empty;
		}
	}

	private string TranslateDifferenceDetail(string detail)
	{
		if (string.IsNullOrWhiteSpace(detail))
		{
			return string.Empty;
		}
		string value = TranslateNote(detail);
		if (IsKorean())
		{
			value = value.Replace("Type count differs.", "타입 개수가 다릅니다.");
			value = value.Replace("Standard-only types are missing in the project; project-only types are extra.", "표준에만 있는 타입은 현재 프로젝트 누락, 현재 프로젝트에만 있는 타입은 추가 타입입니다.");
			value = value.Replace("Parameter exists only in the project scan.", "현재 프로젝트 스캔에만 있는 파라미터입니다.");
			value = value.Replace("Parameter exists only in the standard scan.", "표준 스캔에만 있는 파라미터입니다.");
			value = value.Replace("Parameter definition, shared flag, GUID, or formula differs.", "파라미터 정의, 공유 여부, GUID 또는 공식이 다릅니다.");
			value = value.Replace("Parameter signature differed, but no compact parameter row could be isolated.", "파라미터 signature는 다르지만 간단한 행으로 분리하지 못했습니다.");
			value = value.Replace("Project family content fingerprint was not created.", "프로젝트 패밀리 Content Fingerprint가 생성되지 않았습니다.");
			value = value.Replace("One or both signature detail files could not be read.", "하나 이상의 signature 상세 파일을 읽지 못했습니다.");
			value = value.Replace("Signature source text is identical. Rebuild both precise scans so stored hashes are regenerated.", "Signature 원문은 동일합니다. 저장된 해시를 다시 만들도록 양쪽 정밀 스캔을 재생성하세요.");
			value = value.Replace("Fingerprint differs, but no concise field-level difference was identified. Inspect signature diagnostics.", "Fingerprint는 다르지만 간단한 필드 차이를 찾지 못했습니다. Signature 진단 파일을 확인하세요.");
			value = value.Replace("standard-only", "표준에만 있음");
			value = value.Replace("project-only", "현재 프로젝트에만 있음");
			value = value.Replace("additional signature difference groups omitted.", "개의 추가 signature 차이 그룹을 생략했습니다.");
		}
		return value;
	}

	private string BuildChangeSummary(LoadableFamilyComparisonItem item)
	{
		if (item == null)
		{
			return "-";
		}
		if (IsBasisMatch(item.Status, item.Notes))
		{
			return T("Basis Match", "기준 일치");
		}
		List<string> parts = new List<string>();
		switch (Normalize(item.Status))
		{
		case "loadavailable":
			parts.Add(T("Not loaded", "현재 프로젝트에 없음"));
			break;
		case "projectonly":
			parts.Add(T("Not in standard", "표준에 없음"));
			break;
		case "categorymismatch":
			parts.Add(T("Category review required", "카테고리 검토 필요"));
			break;
		case "manualreview":
			if (HasProjectFingerprintMissing(item))
			{
				parts.Add(T("Current project fingerprint was not created", "현재 프로젝트 Fingerprint 생성 실패"));
			}
			else if (!string.IsNullOrWhiteSpace(item.Notes))
			{
				parts.Add(TranslateNote(item.Notes));
			}
			else
			{
				parts.Add(T("Manual review required", "수동 검토 필요"));
			}
			break;
		case "updateavailable":
		case "differentfromstandard":
		case "locallymodified":
		case "versionconflict":
		{
			if (HasProjectFingerprintMissing(item))
			{
				parts.Add(T("Current project fingerprint was not created", "현재 프로젝트 Fingerprint 생성 실패"));
				break;
			}
			List<string> diffParts = BuildFingerprintDifferenceDisplayParts(item, 3);
			if (diffParts.Count > 0)
			{
				parts.AddRange(diffParts);
			}
			else if (HasTypeInventoryDifference(item))
			{
				parts.Add(T("Type inventory differs", "타입 구성 불일치"));
			}
			break;
		}
		case "loadedwithoutversionstamp":
		case "stampnormalizationneeded":
			parts.Add(T("Tracking refresh required", "추적 갱신 필요"));
			if (!string.IsNullOrWhiteSpace(item.Notes))
			{
				parts.Add(TranslateNote(item.Notes));
			}
			break;
		default:
			parts.Add(DisplayStatus(item.Status));
			break;
		}
		if (item.StandardTypeCount != item.ProjectTypeCount)
		{
			parts.Add(string.Format(CultureInfo.InvariantCulture, T("Types {0}/{1}", "타입 {0}/{1}"), item.ProjectTypeCount, item.StandardTypeCount));
		}
		if (item.MissingTypeNames != null && item.MissingTypeNames.Count > 0)
		{
			parts.Add(BuildTypeDifferenceBrief(T("Missing type", "누락 타입"), item.MissingTypeNames));
		}
		if (item.ExtraTypeNames != null && item.ExtraTypeNames.Count > 0)
		{
			parts.Add(BuildTypeDifferenceBrief(T("Extra type", "추가 타입"), item.ExtraTypeNames));
		}
		return string.Join(" | ", parts);
	}

	private static bool HasFingerprintDifferenceSummary(LoadableFamilyComparisonItem item)
	{
		if (item != null && item.FingerprintDifferenceSummary != null)
		{
			return item.FingerprintDifferenceSummary.Any([SpecialName] (string x) => !string.IsNullOrWhiteSpace(x));
		}
		return false;
	}

	private static bool HasFingerprintDifferenceDetails(LoadableFamilyComparisonItem item)
	{
		if (item != null && item.FingerprintDifferenceDetails != null)
		{
			return item.FingerprintDifferenceDetails.Any([SpecialName] (LoadableFingerprintDifferenceDetailItem x) => x != null);
		}
		return false;
	}

	private List<string> BuildFingerprintDifferenceDisplayParts(LoadableFamilyComparisonItem item, int maxCount)
	{
		List<string> result = new List<string>();
		if (maxCount <= 0)
		{
			return result;
		}
		if (HasFingerprintDifferenceDetails(item))
		{
			foreach (LoadableFingerprintDifferenceDetailItem detail in item.FingerprintDifferenceDetails)
			{
				string brief = BuildFingerprintDifferenceBrief(detail);
				if (!string.IsNullOrWhiteSpace(brief))
				{
					AddUniqueBrief(result, brief);
					if (result.Count >= maxCount)
					{
						return result;
					}
				}
			}
		}
		if (item != null && HasTypeInventoryDifference(item))
		{
			if (item.MissingTypeNames != null && item.MissingTypeNames.Count > 0)
			{
				AddUniqueBrief(result, BuildTypeDifferenceBrief(T("Missing type", "누락 타입"), item.MissingTypeNames));
			}
			if (result.Count < maxCount && item.ExtraTypeNames != null && item.ExtraTypeNames.Count > 0)
			{
				AddUniqueBrief(result, BuildTypeDifferenceBrief(T("Extra type", "추가 타입"), item.ExtraTypeNames));
			}
			if (result.Count >= maxCount)
			{
				return result.Take(maxCount).ToList();
			}
		}
		if (!HasFingerprintDifferenceSummary(item))
		{
			return result;
		}
		foreach (string reason in item.FingerprintDifferenceSummary)
		{
			if (string.IsNullOrWhiteSpace(reason))
			{
				continue;
			}
			string summaryBrief = string.Empty;
			if (TryBuildFingerprintSummaryBrief(reason, ref summaryBrief))
			{
				AddUniqueBrief(result, summaryBrief);
				if (result.Count >= maxCount)
				{
					break;
				}
				continue;
			}
			string text = TranslateNote(reason).Replace("|", " / ").Trim();
			if (!IsGenericFingerprintSummary(text) && text.Length != 0)
			{
				AddUniqueBrief(result, text);
				if (result.Count >= maxCount)
				{
					break;
				}
			}
		}
		return result;
	}

	private bool TryBuildFingerprintSummaryBrief(string reason, ref string brief)
	{
		brief = string.Empty;
		string text = (reason ?? string.Empty).Trim();
		if (text.Length == 0)
		{
			return false;
		}
		Match signatureMatch = Regex.Match(text, "^Signature differs \\[(?<area>[^\\]]+)\\]: (?<side>standard-only|project-only) (?<count>[0-9]+)", RegexOptions.IgnoreCase);
		if (signatureMatch.Success)
		{
			string area = TranslateDifferenceArea(signatureMatch.Groups["area"].Value, string.Empty);
			string sideLabel = (string.Equals(signatureMatch.Groups["side"].Value, "standard-only", StringComparison.OrdinalIgnoreCase) ? T("standard only", "표준에만") : T("current project only", "현재 프로젝트에만"));
			brief = area + ": " + sideLabel + " " + signatureMatch.Groups["count"].Value;
			return true;
		}
		string normalized = Normalize(text);
		if (normalized.Contains("parameter") && normalized.Contains("signature"))
		{
			brief = TranslateDifferenceArea("parameters/formulas", string.Empty);
			return true;
		}
		if (normalized.Contains("type inventory differs") || normalized.Contains("content signature type inventory differs"))
		{
			brief = TranslateDifferenceArea("family types", string.Empty);
			return true;
		}
		if (normalized.Contains("category group differs"))
		{
			brief = TranslateDifferenceArea("category group", string.Empty);
			return true;
		}
		if (normalized.Contains("category differs"))
		{
			brief = TranslateDifferenceArea("category", string.Empty);
			return true;
		}
		if (normalized.Contains("family name differs"))
		{
			brief = TranslateDifferenceArea("family name", string.Empty);
			return true;
		}
		if (normalized.Contains("shared flag differs"))
		{
			brief = TranslateDifferenceArea("shared flag", string.Empty);
			return true;
		}
		return false;
	}

	private string BuildFingerprintDifferenceBrief(LoadableFingerprintDifferenceDetailItem detail)
	{
		if (detail == null)
		{
			return string.Empty;
		}
		List<string> lines = BuildConciseFingerprintDifferenceTableLines(detail);
		if (lines.Count == 0)
		{
			return string.Empty;
		}
		string[] parts = lines[0].Split('\t');
		if (parts.Length == 0)
		{
			return string.Empty;
		}
		string area = ((parts.Length > 0) ? parts[0] : string.Empty);
		string standardValue = ((parts.Length > 1) ? parts[1] : string.Empty);
		string projectValue = ((parts.Length > 2) ? parts[2] : string.Empty);
		string note = ((parts.Length > 3) ? parts[3] : string.Empty);
		if (!IsDifferenceBlank(note))
		{
			return area + ": " + note;
		}
		if (!IsDifferenceBlank(standardValue) && IsDifferenceBlank(projectValue))
		{
			return area + ": " + standardValue;
		}
		if (IsDifferenceBlank(standardValue) && !IsDifferenceBlank(projectValue))
		{
			return area + ": " + projectValue;
		}
		if (!IsDifferenceBlank(standardValue) && !IsDifferenceBlank(projectValue))
		{
			return area + " " + standardValue + "/" + projectValue;
		}
		return area;
	}

	private string BuildParameterDifferenceBrief(LoadableFingerprintDifferenceDetailItem detail, string kindKey)
	{
		string parameterName = ExtractDifferenceValueName(string.Equals(CleanDifferenceTableCell(detail.StandardValue), "-", StringComparison.Ordinal) ? detail.ProjectValue : detail.StandardValue);
		if (string.IsNullOrWhiteSpace(parameterName))
		{
			parameterName = T("parameter", "파라미터");
		}
		switch (kindKey)
		{
		case "standardonly":
			return T("Standard-only parameter: ", "표준에만 파라미터: ") + ShortDifferenceValue(parameterName, 54);
		case "projectonly":
			return T("Current-project-only parameter: ", "현재 프로젝트에만 파라미터: ") + ShortDifferenceValue(parameterName, 54);
		case "modified":
		{
			string standardBrief = BuildParameterAttributeBrief(detail.StandardValue);
			string projectBrief = BuildParameterAttributeBrief(detail.ProjectValue);
			return T("Parameter differs: ", "파라미터 상이: ") + ShortDifferenceValue(parameterName, 42) + " (" + T("Std ", "표준 ") + standardBrief + " / " + T("Current ", "현재 프로젝트 ") + projectBrief + ")";
		}
		default:
			return T("Parameter signature differs: ", "파라미터 signature 상이: ") + ShortDifferenceValue(parameterName, 54);
		}
	}

	private string BuildSignatureDifferenceBrief(LoadableFingerprintDifferenceDetailItem detail)
	{
		string translatedDetail = TranslateDifferenceDetail(detail.Details);
		if (!string.IsNullOrWhiteSpace(translatedDetail) && !string.Equals(translatedDetail, "-", StringComparison.Ordinal))
		{
			return translatedDetail;
		}
		return BuildStandardProjectPair(detail.StandardValue, detail.ProjectValue, 44);
	}

	private string BuildStandardProjectPair(string standardValue, string projectValue, int maxCellLength)
	{
		return T("standard ", "표준 ") + ShortDifferenceValue(standardValue, maxCellLength) + T(", current project ", ", 현재 프로젝트 ") + ShortDifferenceValue(projectValue, maxCellLength);
	}

	private static string NormalizeDifferenceToken(string value)
	{
		return Normalize(value).Replace("/", string.Empty).Replace("\\", string.Empty).Replace(" ", string.Empty)
			.Replace("-", string.Empty)
			.Replace("_", string.Empty)
			.Replace(".", string.Empty);
	}

	private static string ExtractDifferenceValueName(string value)
	{
		List<string> segments = SplitDifferenceValue(value);
		if (segments.Count == 0)
		{
			return string.Empty;
		}
		return segments[0];
	}

	private static string BuildParameterAttributeBrief(string value)
	{
		List<string> segments = SplitDifferenceValue(value);
		if (segments.Count <= 1)
		{
			return ShortDifferenceValue(value, 44);
		}
		List<string> attrs = (from x in segments.Skip(1)
			where !string.IsNullOrWhiteSpace(x) && !string.Equals(x, "-", StringComparison.Ordinal)
			select x).Take(4).ToList();
		if (attrs.Count == 0)
		{
			return "-";
		}
		return ShortDifferenceValue(string.Join("·", attrs), 70);
	}

	private static List<string> SplitDifferenceValue(string value)
	{
		string text = CleanDifferenceTableCell(value);
		if (string.IsNullOrWhiteSpace(text) || string.Equals(text, "-", StringComparison.Ordinal))
		{
			return new List<string>();
		}
		return (from x in text.Split(new string[1] { " / " }, StringSplitOptions.None)
			select x.Trim() into x
			where x.Length > 0
			select x).ToList();
	}

	private static string ShortDifferenceValue(string value, int maxLength)
	{
		string text = CleanDifferenceTableCell(value);
		if (string.IsNullOrWhiteSpace(text))
		{
			return "-";
		}
		text = text.Replace("'", string.Empty);
		if (maxLength <= 3 || text.Length <= maxLength)
		{
			return text;
		}
		return text.Substring(0, checked(maxLength - 3)) + "...";
	}

	private static void AddUniqueBrief(List<string> result, string value)
	{
		if (result != null && !string.IsNullOrWhiteSpace(value))
		{
			string text = value.Trim();
			if (!result.Any([SpecialName] (string x) => string.Equals(x, text, StringComparison.OrdinalIgnoreCase)))
			{
				result.Add(text);
			}
		}
	}

	private static bool IsGenericFingerprintSummary(string value)
	{
		string normalized = Normalize(value);
		switch (normalized)
		{
		default:
			if (!normalized.StartsWith("signature differs ", StringComparison.Ordinal) && !normalized.StartsWith("signature 차이 ", StringComparison.Ordinal) && !normalized.Contains("signature 원문") && !normalized.Contains("stored fingerprint") && !normalized.Contains("저장된 fingerprint") && !normalized.Contains("stored hash differs") && !normalized.Contains("해시 다름") && !normalized.Contains("fingerprint는 다르지만") && !normalized.Contains("기준 불일치 fingerprint"))
			{
				return normalized.Contains("fingerprint differs from the standard");
			}
			break;
		case "fingerprint differs":
		case "fingerprint 불일치":
		case "fingerprint가 표준과 다름":
		case "system type fingerprint differs":
		case "contentfingerprint differs.":
			break;
		}
		return true;
	}

	private static bool HasTypeInventoryDifference(LoadableFamilyComparisonItem item)
	{
		if (item == null)
		{
			return false;
		}
		return (item.MissingTypeNames != null && item.MissingTypeNames.Count > 0) || (item.ExtraTypeNames != null && item.ExtraTypeNames.Count > 0);
	}

	private static bool HasProjectFingerprintMissing(LoadableFamilyComparisonItem item)
	{
		if (item == null)
		{
			return false;
		}
		return !string.IsNullOrWhiteSpace(item.StandardContentFingerprint) && string.IsNullOrWhiteSpace(item.ProjectContentFingerprint);
	}

	private static bool IsBasisMatch(string status, string note)
	{
		switch (Normalize(status))
		{
		case "loadedlatest":
		case "latest":
		case "nochange":
			return true;
		default:
		{
			string normalizedNote = Normalize(note);
			return normalizedNote.Contains("project content matches the current standard snapshot and tracked approval stamp") || normalizedNote.Contains("프로젝트 내용이 현재 표준 스냅샷 및 추적 승인 스탬프와 일치");
		}
		}
	}

	private string BuildExecutionNotes(SystemSyncExecutionItem item)
	{
		List<string> parts = new List<string>();
		parts.Add(T("Policy: ", "정책: ") + SystemTypeSupportPolicyService.ResolveDisplayLabel(item.SystemFamilyKind));
		if (!string.IsNullOrWhiteSpace(item.Summary))
		{
			parts.Add(TranslateNote(item.Summary));
		}
		if (item.BlockingReasons != null && item.BlockingReasons.Count > 0)
		{
			parts.Add(T("Blocked: ", "차단: ") + string.Join("; ", from x in item.BlockingReasons.Take(3)
				select TranslateBlockingReason(x)));
		}
		if (item.Steps != null && item.Steps.Count > 0)
		{
			parts.Add(T("Steps: ", "단계: ") + string.Join(", ", item.Steps.Select([SpecialName] (SystemSyncExecutionStep x) => TranslateAction(x.Action)).Distinct().Take(4)));
		}
		List<string> duplicateTargets = ExtractDuplicateStepTargets(item);
		if (duplicateTargets.Count > 0)
		{
			parts.Add(T("Duplicate types: ", "중복 타입: ") + string.Join(", ", duplicateTargets.Take(6)));
		}
		return string.Join(" / ", parts);
	}

	private static List<string> ExtractDuplicateStepTargets(SystemSyncExecutionItem item)
	{
		if (item == null)
		{
			return new List<string>();
		}
		List<string> targets = new List<string>();
		if (item.RelatedDuplicateNames != null)
		{
			targets.AddRange(item.RelatedDuplicateNames);
		}
		if (item.Steps != null)
		{
			targets.AddRange(from x in item.Steps.Where([SpecialName] (SystemSyncExecutionStep x) => x != null && IsDuplicateCleanupAction(x.Action)).SelectMany([SpecialName] (SystemSyncExecutionStep x) => SplitDisplayList(x.TargetName))
				where !string.Equals(Normalize(x), Normalize(item.SystemTypeName), StringComparison.Ordinal)
				select x);
		}
		return targets.Where([SpecialName] (string x) => !string.IsNullOrWhiteSpace(x)).Distinct(StringComparer.OrdinalIgnoreCase).ToList();
	}

	private static bool IsDuplicateCleanupAction(string action)
	{
		switch (Normalize(action))
		{
		case "cleanupduplicatesystemtypes":
		case "consolidateduplicatesystemtypes":
		case "consolidateduplicatesuffixtypes":
			return true;
		default:
			return false;
		}
	}

	private static IEnumerable<string> SplitDisplayList(string value)
	{
		if (string.IsNullOrWhiteSpace(value))
		{
			return Enumerable.Empty<string>();
		}
		return from x in value.Split(new char[1] { ',' }, StringSplitOptions.RemoveEmptyEntries)
			select x.Trim() into x
			where x.Length > 0
			select x;
	}

	private string TranslateBlockingReason(string reason)
	{
		if (string.IsNullOrWhiteSpace(reason))
		{
			return string.Empty;
		}
		int colonIndex = reason.IndexOf(':');
		if (colonIndex > 0)
		{
			string actionName = reason.Substring(0, colonIndex).Trim();
			string detail = reason.Substring(checked(colonIndex + 1)).Trim();
			string translatedAction = TranslateAction(actionName);
			if (!string.Equals(translatedAction, actionName, StringComparison.Ordinal))
			{
				return translatedAction + ": " + TranslateNote(detail);
			}
		}
		return TranslateNote(reason);
	}

