		case "manualreview":
		case "manualreviewnameonlymatch":
		case "promoteorrenamedependencytype":
			return T("Manual Review", "수동 검토");
		case "blockedcategorymismatch":
			return T("Category Mismatch Review", "카테고리 불일치 검토");
		case "reviewdependencycategory":
			return T("Review Dependency Category", "의존 카테고리 검토");
