	private string DisplayStatus(string status)
	{
		switch (Normalize(status))
		{
		case "loadavailable":
			return T("Load Available", "로드 가능");
		case "updateavailable":
			return T("Update Available", "업데이트 가능");
		case "loadedlatest":
		case "latest":
			return T("Loaded Latest", "최신 로드됨");
		case "loadednamematch":
			return T("Loaded - Check Needed", "로드됨(검사 필요)");
		case "differentfromstandard":
			return T("Different From Standard", "표준과 다름");
		case "locallymodified":
			return T("Locally Modified", "로컬 수정됨");
		case "versionconflict":
			return T("Version Conflict", "버전 충돌");
		case "projectonly":
			return T("Review Needed", "검토 필요");
		case "categorymismatch":
			return T("Category Mismatch", "카테고리 불일치");
		case "approvalrequired":
			return T("Approval Required", "승인 필요");
		case "stampnormalizationneeded":
			return T("Stamp Refresh Needed", "스탬프 갱신 필요");
		case "loadedwithoutversionstamp":
			return T("Stamp Missing", "스탬프 없음");
		case "nochange":
			return T("No Change", "변경 없음");
		case "skippedmissing":
		case "skipped":
			return T("Skipped", "건너뜀");
		case "duplicaterisk":
			return T("Duplicate Risk", "중복 위험");
		case "ready":
			return T("Ready", "준비");
		case "blocked":
			return T("Blocked", "차단");
		case "manualreview":
			return T("Manual Review", "수동 검토");
		case "reviewneeded":
			return T("Review Needed", "검토 필요");
		default:
			if (string.IsNullOrWhiteSpace(status))
			{
				return "-";
			}
			return status;
		}
	}

	private static string StatusClass(string status)
	{
		switch (Normalize(status))
		{
		case "loadedlatest":
		case "latest":
		case "nochange":
		case "ready":
		case "approved":
		case "completed":
			return "good";
		case "loadavailable":
		case "loadednamematch":
		case "updateavailable":
		case "approvalrequired":
		case "stampnormalizationneeded":
		case "loadedwithoutversionstamp":
		case "draft":
		case "submitted":
		case "reviewing":
		case "warning":
		case "duplicaterisk":
		case "reviewneeded":
			return "warn";
		case "skippedmissing":
		case "skipped":
			return "info";
		case "blocked":
		case "manualreview":
		case "categorymismatch":
		case "differentfromstandard":
		case "projectonly":
		case "locallymodified":
		case "versionconflict":
		case "rejected":
			return "bad";
		default:
			return "info";
		}
	}

	private static string TryGetCentralPath(Document doc)
	{
		string TryGetCentralPath;
		if (doc == null)
		{
			TryGetCentralPath = string.Empty;
		}
		else
		{
			try
			{
				ModelPath modelPath = doc.GetWorksharingCentralModelPath();
				TryGetCentralPath = ((modelPath != null) ? ModelPathUtils.ConvertModelPathToUserVisiblePath(modelPath) : string.Empty);
			}
			catch (Exception projectError)
			{
				ProjectData.SetProjectError(projectError);
				TryGetCentralPath = string.Empty;
				ProjectData.ClearProjectError();
			}
		}
		return TryGetCentralPath;
	}

	private static bool IsDetachedDocument(Document doc)
	{
		if (doc == null)
		{
			return false;
		}
		try
		{
			PropertyInfo propertyInfo = ((object)doc).GetType().GetProperty("IsDetached");
			if ((object)propertyInfo == null)
			{
				return false;
			}
			object value = RuntimeHelpers.GetObjectValue(propertyInfo.GetValue(doc, null));
			if (value is bool)
			{
				return Conversions.ToBoolean(value);
			}
		}
		catch (Exception projectError)
		{
			ProjectData.SetProjectError(projectError);
			ProjectData.ClearProjectError();
		}
		return false;
	}

	private static bool IsSameUserVisiblePath(string leftPath, string rightPath)
	{
		if (string.IsNullOrWhiteSpace(leftPath) || string.IsNullOrWhiteSpace(rightPath))
		{
			return false;
		}
		try
		{
			leftPath = Path.GetFullPath(leftPath);
			rightPath = Path.GetFullPath(rightPath);
		}
		catch (Exception projectError)
		{
			ProjectData.SetProjectError(projectError);
			ProjectData.ClearProjectError();
		}
		return string.Equals(leftPath.Trim(), rightPath.Trim(), StringComparison.OrdinalIgnoreCase);
	}

	private static string FormatUtcStamp(string value)
	{
		if (string.IsNullOrWhiteSpace(value))
		{
			return "-";
		}
		if (DateTime.TryParse(value, CultureInfo.InvariantCulture, DateTimeStyles.AdjustToUniversal | DateTimeStyles.AssumeUniversal, out var parsed))
		{
			return parsed.ToLocalTime().ToString("yyyy-MM-dd HH:mm", CultureInfo.InvariantCulture);
		}
		return value;
	}

	private static string SafeShortName(string value, int maxLength)
	{
		if (string.IsNullOrWhiteSpace(value) || value.Length <= maxLength)
		{
			return value ?? string.Empty;
		}
		return value.Substring(0, checked(maxLength - 3)) + "...";
	}

	private static string SafeFileName(string value)
	{
		if (string.IsNullOrWhiteSpace(value))
		{
			return "Project";
		}
		char[] invalidFileNameChars = Path.GetInvalidFileNameChars();
		char[] chars = value.Select([SpecialName] (char ch) => (!invalidFileNameChars.Contains(ch)) ? ch : '_').ToArray();
		return new string(chars);
	}

	private static string Normalize(string value)
	{
		if (value == null)
		{
			return string.Empty;
		}
		return value.Trim().ToLowerInvariant();
	}

	private static string Html(string value)
	{
		if (value == null)
		{
			return string.Empty;
		}
		return value.Replace("&", "&amp;").Replace("<", "&lt;").Replace(">", "&gt;")
			.Replace("\"", "&quot;");
	}

	private static string Attr(string value)
	{
		return Html(value).Replace("'", "&#39;").Replace("\r", " ").Replace("\n", " ");
	}

	private static string AttrMultiline(string value)
	{
		return Html(value).Replace("'", "&#39;").Replace("\r\n", "&#10;").Replace("\r", "&#10;")
			.Replace("\n", "&#10;");
	}

	private static string Js(string value)
	{
		if (value == null)
		{
			return string.Empty;
		}
		return value.Replace("\\", "\\\\").Replace("'", "\\'").Replace("\r", " ")
			.Replace("\n", " ");
	}

	private static StandardLoadableFamilySnapshotItem FindStandardFamilySnapshot(StandardLibrarySnapshot snapshot, string categoryName, string familyName)
	{
		return FindStandardFamilySnapshot(BuildStandardFamilySnapshotLookup(snapshot), categoryName, familyName);
	}

	private static StandardLoadableFamilySnapshotItem FindStandardFamilySnapshot(StandardFamilySnapshotLookup lookup, string categoryName, string familyName)
	{
		if (lookup == null)
		{
			return null;
		}
		string exactKey = BuildStandardFamilyLookupKey(categoryName, familyName);
		StandardLoadableFamilySnapshotItem exact = null;
		if (lookup.ExactByCategoryFamily != null && lookup.ExactByCategoryFamily.TryGetValue(exactKey, out exact))
		{
			return exact;
		}
		string familyToken = Normalize(familyName);
		if (string.IsNullOrWhiteSpace(familyToken) || lookup.AmbiguousFamilyTokens == null || lookup.AmbiguousFamilyTokens.Contains(familyToken) || lookup.UniqueByFamily == null)
		{
			return null;
		}
		StandardLoadableFamilySnapshotItem unique = null;
		if (lookup.UniqueByFamily.TryGetValue(familyToken, out unique))
		{
			return unique;
		}
		return null;
	}

	private static StandardFamilySnapshotLookup BuildStandardFamilySnapshotLookup(StandardLibrarySnapshot snapshot)
	{
		StandardFamilySnapshotLookup lookup = new StandardFamilySnapshotLookup();
		if (snapshot == null || snapshot.LoadableFamilies == null)
		{
			return lookup;
		}
		foreach (StandardLoadableFamilySnapshotItem item in snapshot.LoadableFamilies)
		{
			if (item == null || string.IsNullOrWhiteSpace(item.FamilyName))
			{
				continue;
			}
			string exactKey = BuildStandardFamilyLookupKey(item.CategoryName, item.FamilyName);
			if (!lookup.ExactByCategoryFamily.ContainsKey(exactKey))
			{
				lookup.ExactByCategoryFamily.Add(exactKey, item);
			}
			string familyToken = Normalize(item.FamilyName);
			if (!lookup.AmbiguousFamilyTokens.Contains(familyToken))
			{
				if (lookup.UniqueByFamily.ContainsKey(familyToken))
				{
					lookup.UniqueByFamily.Remove(familyToken);
					lookup.AmbiguousFamilyTokens.Add(familyToken);
				}
				else
				{
					lookup.UniqueByFamily.Add(familyToken, item);
				}
			}
		}
		return lookup;
	}

	private static string BuildStandardFamilyLookupKey(string categoryName, string familyName)
	{
		return Normalize(categoryName) + "|" + Normalize(familyName);
	}

	private static string ResolveFamilyCategoryGroup(StandardLoadableFamilySnapshotItem family, string categoryName, string categoryId, string familyName)
	{
		string storedGroup = string.Empty;
		string effectiveCategoryName = categoryName ?? string.Empty;
		string effectiveCategoryId = categoryId ?? string.Empty;
		string effectiveFamilyName = familyName ?? string.Empty;
		if (family != null)
		{
			storedGroup = family.CategoryGroup ?? string.Empty;
			if (string.IsNullOrWhiteSpace(effectiveCategoryName))
			{
				effectiveCategoryName = family.CategoryName ?? string.Empty;
			}
			if (string.IsNullOrWhiteSpace(effectiveCategoryId))
			{
				effectiveCategoryId = family.CategoryId ?? string.Empty;
			}
			if (string.IsNullOrWhiteSpace(effectiveFamilyName))
			{
				effectiveFamilyName = family.FamilyName ?? string.Empty;
			}
		}
		return FamilyBrowserFamilyClassificationService.ResolveCategoryGroup(storedGroup, effectiveCategoryName, effectiveCategoryId, effectiveFamilyName);
	}

	private static string NormalizeCategoryGroupToken(string value)
	{
		switch (Normalize(value))
		{
		case "model":
		case "모델":
			return "Model";
		case "annotation":
		case "annotationcategory":
		case "주석":
		case "주석카테고리":
			return "Annotation";
		default:
			return "Other";
		}
	}

	private static string InferCategoryGroupFromCategoryName(string categoryName)
	{
		string normalized = Normalize(categoryName);
		if (normalized.Length == 0)
		{
			return "Other";
		}
		if (normalized.Contains("annotation") || normalized.Contains("tag") || normalized.Contains("symbol") || normalized.Contains("text") || normalized.Contains("detail") || normalized.Contains("title block") || normalized.Contains("view reference") || normalized.Contains("revision") || normalized.Contains("주석") || normalized.Contains("태그") || normalized.Contains("기호") || normalized.Contains("문자") || normalized.Contains("상세") || normalized.Contains("제목"))
		{
			return "Annotation";
		}
		return "Model";
	}

