	private static string BuildParameterPreviewText(StandardLoadableFamilySnapshotItem family)
	{
		if (family == null)
		{
			return SharedText("No standard snapshot parameter data. Re-register the standard RVT.", "표준 스냅샷 파라미터 데이터가 없습니다. 표준 RVT를 다시 등록하세요.");
		}
		return FamilyBrowserDashboardHtmlForm.BuildParameterPreviewText(family.Parameters ?? new List<StandardFamilyParameterSnapshotItem>(), family.TypeCount, SharedText("No standard snapshot parameter data. Re-register the standard RVT.", "표준 스냅샷 파라미터 데이터가 없습니다. 표준 RVT를 다시 등록하세요."), SharedText("No captured shared parameter data. Run a precise standard scan after shared parameters are added.", "캡처된 공유 파라미터 데이터가 없습니다. 공유 파라미터를 추가한 뒤 표준 정밀 스캔을 실행하세요."));
	}

	private static string BuildParameterPreviewText(IEnumerable<StandardFamilyParameterSnapshotItem> parametersSource, int typeCount, string missingParameterMessage, string noSharedParameterMessage)
	{
		List<StandardFamilyParameterSnapshotItem> allParameters = (parametersSource ?? new List<StandardFamilyParameterSnapshotItem>()).Where([SpecialName] (StandardFamilyParameterSnapshotItem x) => x != null && !string.IsNullOrWhiteSpace(x.Name) && !IsEmptyReadOnlyPreviewParameter(x)).ToList();
		List<StandardFamilyParameterSnapshotItem> parameters = DeduplicatePreviewParameters(allParameters.Where([SpecialName] (StandardFamilyParameterSnapshotItem x) => IsSharedPreviewParameter(x)).ToList());
		if (parameters.Count == 0)
		{
			if (allParameters.Count > 0)
			{
				return SharedText("Captured parameter data exists, but no shared parameters were identified. Captured parameters: ", "파라미터 데이터는 캡처됐지만 공유 파라미터로 확인된 항목이 없습니다. 캡처 파라미터 수: ") + allParameters.Count.ToString(CultureInfo.InvariantCulture);
			}
			return string.IsNullOrWhiteSpace(missingParameterMessage) ? SharedText("No captured shared parameter data. Run a precise standard scan after shared parameters are added.", "캡처된 공유 파라미터 데이터가 없습니다. 공유 파라미터를 추가한 뒤 표준 정밀 스캔을 실행하세요.") : missingParameterMessage;
		}
		List<string> lines = new List<string> { SharedText("Types: ", "타입 수: ") + typeCount.ToString(CultureInfo.InvariantCulture) };
		List<StandardFamilyParameterSnapshotItem> familyParameters = (from x in parameters
			where string.Equals(Normalize(x.Scope), "family", StringComparison.Ordinal)
			orderby IsSharedPreviewParameter(x) descending
			select x).ThenBy([SpecialName] (StandardFamilyParameterSnapshotItem x) => Normalize(x.Name), StringComparer.Ordinal).Take(6).ToList();
		if (familyParameters.Count > 0)
		{
			lines.Add(SharedText("Shared family parameters", "공유 패밀리 파라미터"));
			lines.AddRange(familyParameters.Select([SpecialName] (StandardFamilyParameterSnapshotItem x) => FormatParameterPreview(x)));
		}
		List<StandardFamilyParameterSnapshotItem> instanceParameters = (from x in parameters
			where x.IsInstance || string.Equals(Normalize(x.Scope), "instance", StringComparison.Ordinal)
			orderby IsSharedPreviewParameter(x) descending
			select x).ThenBy([SpecialName] (StandardFamilyParameterSnapshotItem x) => Normalize(x.Name), StringComparer.Ordinal).Take(8).ToList();
		if (instanceParameters.Count > 0)
		{
			lines.Add(SharedText("Shared instance parameters", "공유 인스턴스 파라미터"));
			lines.AddRange(instanceParameters.Select([SpecialName] (StandardFamilyParameterSnapshotItem x) => FormatParameterPreview(x)));
		}
		string text = (from x in parameters
			where string.Equals(Normalize(x.Scope), "type", StringComparison.Ordinal) && !string.IsNullOrWhiteSpace(x.TypeName)
			select x.TypeName).OrderBy([SpecialName] (string x) => Normalize(x), StringComparer.Ordinal).FirstOrDefault();
		if (!string.IsNullOrWhiteSpace(text))
		{
			List<StandardFamilyParameterSnapshotItem> typeParameters = (from x in parameters
				where string.Equals(Normalize(x.Scope), "type", StringComparison.Ordinal) && string.Equals(Normalize(x.TypeName), Normalize(text), StringComparison.Ordinal)
				orderby IsSharedPreviewParameter(x) descending
				select x).ThenBy([SpecialName] (StandardFamilyParameterSnapshotItem x) => Normalize(x.Name), StringComparer.Ordinal).Take(12).ToList();
			lines.Add(SharedText("Shared type parameters: ", "공유 타입 파라미터: ") + text);
			lines.AddRange(typeParameters.Select([SpecialName] (StandardFamilyParameterSnapshotItem x) => FormatParameterPreview(x)));
		}
		return string.Join("\n", lines);
	}

	private static string FormatParameterPreview(StandardFamilyParameterSnapshotItem item)
	{
		string value = item.ValuePreview ?? string.Empty;
		string formula = item.Formula ?? string.Empty;
		if (!string.IsNullOrWhiteSpace(formula))
		{
			value = SharedText("Formula: ", "수식: ") + formula;
		}
		if (value.Length > 80)
		{
			value = value.Substring(0, 77) + "...";
		}
		List<string> flags = new List<string>();
		if (IsSharedPreviewParameter(item))
		{
			flags.Add(SharedText("shared", "공유"));
		}
		if (item.IsInstance)
		{
			flags.Add(SharedText("instance", "인스턴스"));
		}
		string suffix = ((flags.Count == 0) ? string.Empty : (" [" + string.Join("] [", flags) + "]"));
		return "- " + item.Name + ": " + (string.IsNullOrWhiteSpace(value) ? "-" : value) + suffix;
	}

	private static List<StandardFamilyParameterSnapshotItem> DeduplicatePreviewParameters(IEnumerable<StandardFamilyParameterSnapshotItem> parameters)
	{
		return FamilyParameterSnapshotNormalizationService.DeduplicateDefinitions(parameters);
	}

	private static string BuildPreviewParameterIdentityKey(StandardFamilyParameterSnapshotItem item)
	{
		if (item == null)
		{
			return string.Empty;
		}
		string guid = Normalize(item.ExternalGuid);
		if (guid.Length > 0)
		{
			return "guid|" + guid;
		}
		if (item.IsShared)
		{
			return "shared|" + Normalize(item.Name) + "|" + Normalize(item.StorageType) + "|" + Normalize(item.Formula);
		}
		return "local|" + Normalize(item.Scope) + "|" + Normalize(item.Name) + "|" + Normalize(item.StorageType) + "|" + item.IsInstance + "|" + Normalize(item.Formula) + "|" + Normalize(item.ParameterId);
	}

	private static StandardFamilyParameterSnapshotItem SelectPreferredPreviewParameter(IEnumerable<StandardFamilyParameterSnapshotItem> items)
	{
		return (from x in items ?? Enumerable.Empty<StandardFamilyParameterSnapshotItem>()
			where x != null
			orderby PreviewParameterPreferenceRank(x), !string.IsNullOrWhiteSpace(x.Formula) descending, !string.IsNullOrWhiteSpace(x.ValuePreview) descending, !string.IsNullOrWhiteSpace(x.TypeName) descending
			select x).FirstOrDefault();
	}

	private static int PreviewParameterPreferenceRank(StandardFamilyParameterSnapshotItem item)
	{
		if (item == null)
		{
			return int.MaxValue;
		}
		string scope = Normalize(item.Scope);
		if (item.IsInstance || string.Equals(scope, "instance", StringComparison.Ordinal))
		{
			return 0;
		}
		if (string.Equals(scope, "type", StringComparison.Ordinal))
		{
			return 1;
		}
		if (string.Equals(scope, "family", StringComparison.Ordinal))
		{
			return 2;
		}
		return 3;
	}

	private static bool IsEmptyReadOnlyPreviewParameter(StandardFamilyParameterSnapshotItem item)
	{
		if (item == null || !item.IsReadOnly)
		{
			return false;
		}
		if (item.IsShared)
		{
			return false;
		}
		return string.IsNullOrWhiteSpace(item.ValuePreview) && string.IsNullOrWhiteSpace(item.Formula);
	}

	private static bool IsSharedPreviewParameter(StandardFamilyParameterSnapshotItem item)
	{
		if (item == null)
		{
			return false;
		}
		return item.IsShared || !string.IsNullOrWhiteSpace(item.ExternalGuid);
	}

	private static string StripTypePrefix(string value)
	{
		if (string.IsNullOrWhiteSpace(value))
		{
			return string.Empty;
		}
		string[] array = new string[4] { "Project types: ", "Standard types: ", "프로젝트 타입: ", "표준 타입: " };
		foreach (string prefix in array)
		{
			if (value.StartsWith(prefix, StringComparison.OrdinalIgnoreCase))
			{
				return value.Substring(prefix.Length);
			}
		}
		return value;
	}

	private static string ToFileUri(string path, bool deferFileIo = false)
	{
		string ToFileUri;
		if (string.IsNullOrWhiteSpace(path))
		{
			ToFileUri = string.Empty;
		}
		else
		{
			try
			{
				FileInfo sourceInfo = new FileInfo(path);
				if (!sourceInfo.Exists || sourceInfo.Length <= 0)
				{
					ToFileUri = string.Empty;
				}
				else
				{
					string cacheKey = BuildBrowserPreviewUriCacheKey(sourceInfo) + (deferFileIo ? "|defer" : "|display");
					string cachedUri = string.Empty;
					object browserPreviewUriCacheLock = BrowserPreviewUriCacheLock;
					ObjectFlowControl.CheckForSyncLockOnValueType(browserPreviewUriCacheLock);
					bool lockTaken = false;
					try
					{
						Monitor.Enter(browserPreviewUriCacheLock, ref lockTaken);
						CachedBrowserPreviewUri cached = null;
						if (!BrowserPreviewUriCache.TryGetValue(cacheKey, out cached) || cached == null || string.IsNullOrWhiteSpace(cached.Uri))
						{
							goto end_IL_006a;
						}
						ToFileUri = cached.Uri;
						goto end_IL_0014;
						end_IL_006a:;
					}
					finally
					{
						if (lockTaken)
						{
							Monitor.Exit(browserPreviewUriCacheLock);
						}
					}
					FileInfo displayInfo = (deferFileIo ? sourceInfo : ResolveBrowserPreviewDisplayFile(sourceInfo, allowCopy: true));
					if (displayInfo == null || !displayInfo.Exists || displayInfo.Length <= 0)
					{
						displayInfo = sourceInfo;
					}
					cachedUri = new Uri(displayInfo.FullName).AbsoluteUri;
					object browserPreviewUriCacheLock2 = BrowserPreviewUriCacheLock;
					ObjectFlowControl.CheckForSyncLockOnValueType(browserPreviewUriCacheLock2);
					bool lockTaken2 = false;
					try
					{
						Monitor.Enter(browserPreviewUriCacheLock2, ref lockTaken2);
						BrowserPreviewUriCache[cacheKey] = new CachedBrowserPreviewUri
						{
							SourcePath = sourceInfo.FullName,
							LastWriteTicks = sourceInfo.LastWriteTimeUtc.Ticks,
							Length = sourceInfo.Length,
							Uri = cachedUri
						};
					}
					finally
					{
						if (lockTaken2)
						{
							Monitor.Exit(browserPreviewUriCacheLock2);
						}
					}
					ToFileUri = cachedUri;
				}
				end_IL_0014:;
			}
			catch (Exception projectError)
			{
				ProjectData.SetProjectError(projectError);
				ToFileUri = string.Empty;
				ProjectData.ClearProjectError();
			}
		}
		return ToFileUri;
	}

	private static FileInfo ResolveBrowserPreviewDisplayFile(FileInfo sourceInfo, bool allowCopy)
	{
		if (sourceInfo == null || !sourceInfo.Exists || sourceInfo.Length <= 0)
		{
			return sourceInfo;
		}
		try
		{
			if (!FamilyBrowserStandardPolicyStore.IsManagedDataRootAvailable(HostWorkspacePathResolver.ResolveRoot()))
			{
				return sourceInfo;
			}
			string cacheFolder = FamilyBrowserStandardPolicyStore.GetDataFolder(HostWorkspacePathResolver.ResolveRoot(), "HtmlPreviewCache");
			if (string.IsNullOrWhiteSpace(cacheFolder) || cacheFolder.IndexOf("NoManagedDataRoot", StringComparison.OrdinalIgnoreCase) >= 0)
			{
				return sourceInfo;
			}
			string cachePath = Path.Combine(cacheFolder, ComputePreviewCacheName(sourceInfo.FullName, sourceInfo) + ".png");
			if (string.Equals(Path.GetFullPath(cachePath), sourceInfo.FullName, StringComparison.OrdinalIgnoreCase))
			{
				return sourceInfo;
			}
			bool shouldCopy = true;
			if (File.Exists(cachePath))
			{
				FileInfo cachedInfo = new FileInfo(cachePath);
				shouldCopy = cachedInfo.Length != sourceInfo.Length || cachedInfo.LastWriteTimeUtc.Ticks != sourceInfo.LastWriteTimeUtc.Ticks;
				if (!shouldCopy && cachedInfo.Length > 0)
				{
					return cachedInfo;
				}
			}
			if (!allowCopy)
			{
				return sourceInfo;
			}
			if (shouldCopy)
			{
				Directory.CreateDirectory(cacheFolder);
				File.Copy(sourceInfo.FullName, cachePath, overwrite: true);
				File.SetLastWriteTimeUtc(cachePath, sourceInfo.LastWriteTimeUtc);
			}
			FileInfo displayInfo = new FileInfo(cachePath);
			if (displayInfo.Exists && displayInfo.Length > 0)
			{
				return displayInfo;
			}
		}
		catch (Exception projectError)
		{
			ProjectData.SetProjectError(projectError);
			ProjectData.ClearProjectError();
		}
		return sourceInfo;
	}

	private void InlinePreviewImageFromAction(string encodedPath)
	{
		try
		{
			string sourcePath = Uri.UnescapeDataString(encodedPath ?? string.Empty);
			string failureReason = string.Empty;
			string dataUri = TryBuildInlinePreviewDataUri(sourcePath, ref failureReason);
			if (string.IsNullOrWhiteSpace(dataUri))
			{
				TryInvokeDashboardScript("showInlinePreviewFailure", string.IsNullOrWhiteSpace(failureReason) ? T("Could not display the preview image inline.", "미리보기 이미지를 내장 표시 방식으로도 불러오지 못했습니다.") : failureReason);
			}
			else
			{
				TryInvokeDashboardScript("applyInlinePreviewDataUri", dataUri, T("Displayed through inline preview fallback.", "내장 표시 방식으로 불러왔습니다."));
			}
		}
		catch (Exception ex)
		{
			ProjectData.SetProjectError(ex);
			Exception ex2 = ex;
			TryInvokeDashboardScript("showInlinePreviewFailure", T("Could not display the preview image inline: ", "미리보기 이미지를 내장 표시 방식으로 불러오지 못했습니다: ") + ex2.Message);
			ProjectData.ClearProjectError();
		}
	}

	private string TryBuildInlinePreviewDataUri(string sourcePath, ref string failureReason)
	{
		failureReason = string.Empty;
		string TryBuildInlinePreviewDataUri;
		if (string.IsNullOrWhiteSpace(sourcePath))
		{
			failureReason = T("Preview path is empty.", "미리보기 경로가 비어 있습니다.");
			TryBuildInlinePreviewDataUri = string.Empty;
		}
		else
		{
			try
			{
				string fullPath = Path.GetFullPath(sourcePath);
				if (!File.Exists(fullPath))
				{
					failureReason = T("Preview PNG does not exist: ", "미리보기 PNG 파일이 없습니다: ") + fullPath;
					TryBuildInlinePreviewDataUri = string.Empty;
				}
				else if (!string.Equals(Path.GetExtension(fullPath), ".png", StringComparison.OrdinalIgnoreCase))
				{
					failureReason = T("Preview fallback accepts PNG files only.", "미리보기 대체 표시는 PNG 파일만 허용합니다.");
					TryBuildInlinePreviewDataUri = string.Empty;
				}
				else
				{
					string dataRoot = FamilyBrowserStandardPolicyStore.GetDataRootFolder(_workspaceRoot);
					if (!string.IsNullOrWhiteSpace(dataRoot) && dataRoot.IndexOf("NoManagedDataRoot", StringComparison.OrdinalIgnoreCase) < 0 && !IsPathInsideFolder(fullPath, dataRoot))
					{
						failureReason = T("Preview PNG is outside the managed Family Browser folder.", "미리보기 PNG가 Family Browser 공용 관리 폴더 밖에 있습니다.");
						TryBuildInlinePreviewDataUri = string.Empty;
					}
					else
					{
						FileInfo info = new FileInfo(fullPath);
						if (info.Length <= 0)
						{
							failureReason = T("Preview PNG is empty.", "미리보기 PNG 파일이 비어 있습니다.");
							TryBuildInlinePreviewDataUri = string.Empty;
						}
						else if (info.Length > 8388608)
						{
							failureReason = T("Preview PNG is too large for inline display.", "미리보기 PNG가 내장 표시로 불러오기에는 너무 큽니다.");
							TryBuildInlinePreviewDataUri = string.Empty;
						}
						else
						{
							byte[] bytes = File.ReadAllBytes(fullPath);
							TryBuildInlinePreviewDataUri = "data:image/png;base64," + Convert.ToBase64String(bytes);
						}
					}
				}
			}
			catch (Exception ex)
			{
				ProjectData.SetProjectError(ex);
				Exception ex2 = ex;
				failureReason = ex2.Message;
				TryBuildInlinePreviewDataUri = string.Empty;
				ProjectData.ClearProjectError();
			}
		}
		return TryBuildInlinePreviewDataUri;
	}

	private static bool IsPathInsideFolder(string candidatePath, string folderPath)
	{
		bool IsPathInsideFolder;
		if (string.IsNullOrWhiteSpace(candidatePath) || string.IsNullOrWhiteSpace(folderPath))
		{
			IsPathInsideFolder = false;
		}
		else
		{
			try
			{
				string candidate = Path.GetFullPath(candidatePath).TrimEnd(Path.DirectorySeparatorChar, Path.AltDirectorySeparatorChar);
				string folder = Path.GetFullPath(folderPath).TrimEnd(Path.DirectorySeparatorChar, Path.AltDirectorySeparatorChar);
				if (string.Equals(candidate, folder, StringComparison.OrdinalIgnoreCase))
				{
					IsPathInsideFolder = true;
				}
				else
				{
					folder += Conversions.ToString(Path.DirectorySeparatorChar);
					IsPathInsideFolder = candidate.StartsWith(folder, StringComparison.OrdinalIgnoreCase);
				}
			}
			catch (Exception projectError)
			{
				ProjectData.SetProjectError(projectError);
				IsPathInsideFolder = false;
				ProjectData.ClearProjectError();
			}
		}
		return IsPathInsideFolder;
	}

	private static bool IsValidPreviewImage(string path)
	{
		bool IsValidPreviewImage;
		try
		{
			using Image image = Image.FromFile(path);
			IsValidPreviewImage = image.Width > 0 && image.Height > 0;
		}
		catch (Exception projectError)
		{
			ProjectData.SetProjectError(projectError);
			IsValidPreviewImage = false;
			ProjectData.ClearProjectError();
		}
		return IsValidPreviewImage;
	}

	private static string BuildBrowserPreviewUriCacheKey(FileInfo sourceInfo)
	{
		if (sourceInfo == null)
		{
			return string.Empty;
		}
		return sourceInfo.FullName + "|" + sourceInfo.Length.ToString(CultureInfo.InvariantCulture) + "|" + sourceInfo.LastWriteTimeUtc.Ticks.ToString(CultureInfo.InvariantCulture);
	}

	private static string ComputePreviewCacheName(string path, FileInfo sourceInfo)
	{
		string raw = path + "|" + sourceInfo.Length.ToString(CultureInfo.InvariantCulture) + "|" + sourceInfo.LastWriteTimeUtc.Ticks.ToString(CultureInfo.InvariantCulture);
		using SHA256 sha = SHA256.Create();
		return BitConverter.ToString(sha.ComputeHash(Encoding.UTF8.GetBytes(raw))).Replace("-", string.Empty).ToLowerInvariant();
	}

	private DialogResult ShowDashboardMessage(IWin32Window owner, string message, string caption, MessageBoxButtons buttons, MessageBoxIcon icon)
	{
