	private DialogResult ShowDashboardMessage(IWin32Window owner, string message, string caption, MessageBoxButtons buttons, MessageBoxIcon icon, MessageBoxDefaultButton defaultButton)
	{
		DialogResult ShowDashboardMessage;
		try
		{
			if (buttons != MessageBoxButtons.OK && buttons != MessageBoxButtons.YesNo)
			{
				ShowDashboardMessage = MessageBox.Show(owner, message, caption, buttons, icon, defaultButton);
			}
			else
			{
				IWin32Window effectiveOwner = owner ?? this;
				using DashboardMessageDialog dialog = new DashboardMessageDialog(IsKorean(), message, caption, buttons, icon, defaultButton);
				ShowDashboardMessage = dialog.ShowDialog(effectiveOwner);
			}
		}
		catch (Exception projectError)
		{
			ProjectData.SetProjectError(projectError);
			ShowDashboardMessage = MessageBox.Show(owner, message, caption, buttons, icon, defaultButton);
			ProjectData.ClearProjectError();
		}
		return ShowDashboardMessage;
	}

	private DialogResult ShowDashboardMessage(string message, string caption, MessageBoxButtons buttons, MessageBoxIcon icon)
	{
		return ShowDashboardMessage(this, message, caption, buttons, icon, MessageBoxDefaultButton.Button1);
	}

