		{
			IWin32Window effectiveOwner = owner ?? this;
			using DashboardMessageDialog dialog = new DashboardMessageDialog(IsKorean(), message, caption, MessageBoxButtons.YesNo, icon, MessageBoxDefaultButton.Button1, positiveButtonText, negativeButtonText);
			ShowDashboardChoiceMessage = dialog.ShowDialog(effectiveOwner);
		}
		catch (Exception projectError)
		{
			ProjectData.SetProjectError(projectError);
			ShowDashboardChoiceMessage = ShowDashboardMessage(owner, message, caption, MessageBoxButtons.YesNo, icon);
			ProjectData.ClearProjectError();
		}
		return ShowDashboardChoiceMessage;
	}

